# Build lookup maps (name -> alpha2/alpha3, alpha3 -> alpha2, alpha2 -> alpha3)
NAT_NAME_TO_CODE2 = {}
NAT_NAME_TO_CODE3 = {}
NAT_CODE3_TO_CODE2 = {}
NAT_CODE2_TO_CODE3 = {}
NAT_CODE2_TO_NAME = {}
NAT_CODE3_TO_NAME = {}
for _nm, _c2, _c3 in NATIONALITY_OPTIONS:
    try:
        if _nm:
            _k = _nm.strip().lower()
            if _c2:
                NAT_NAME_TO_CODE2[_k] = _c2
                NAT_CODE2_TO_NAME[_c2.strip().upper()] = _nm
            if _c3:
                NAT_NAME_TO_CODE3[_k] = _c3
                NAT_CODE3_TO_NAME[_c3.strip().upper()] = _nm
    except Exception:
        pass
    try:
        if _c3 and _c2:
            NAT_CODE3_TO_CODE2[_c3.strip().upper()] = _c2
    except Exception:
        pass
    try:
        if _c2 and _c3:
            NAT_CODE2_TO_CODE3[_c2.strip().upper()] = _c3.strip().upper()
    except Exception:
        pass

# Common aliases / abbreviations (extra convenience)
NAT_ALIAS_TO_CODE2 = {
    "UAE": "AE",
    "UNITED ARAB EMIRATES": "AE",
    "KSA": "SA",
    "KINGDOM OF SAUDI ARABIA": "SA",
    "UK": "GB",
    "UNITED KINGDOM": "GB",
    "GREAT BRITAIN": "GB",
    "USA": "US",
    "U.S.A": "US",
    "UNITED STATES": "US",
    "UNITED STATES OF AMERICA": "US",
    "RUSSIA": "RU",
    "IRAN": "IR",
    "SYRIA": "SY",
    "VIETNAM": "VN",
    "BOLIVIA": "BO",
    "VENEZUELA": "VE",
    "TANZANIA": "TZ",
    "MOLDOVA": "MD",
    "LAOS": "LA",
    "SOUTH KOREA": "KR",
    "NORTH KOREA": "KP",
}

# Sticker overrides (preferred abbreviations; may differ from ISO alpha-3)
NAT_STICKER_OVERRIDES = {
    "ARE": "UAE",  # United Arab Emirates
}


def _nat3_override(code3: str) -> str:
    c = (code3 or "").strip().upper()
    if not c:
        return ""
    return NAT_STICKER_OVERRIDES.get(c, c)


def nationality_short(nat: str) -> str:
    """Return an abbreviated nationality for stickers (ISO alpha-3 if known)."""
    s = (nat or "").strip()
    if not s:
        return _nat3_override("")
    # If already looks like a code (first token in e.g. "AE - United Arab Emirates")
    try:
        m = re.match(r"^([A-Za-z]{2,3})\b", s)
        if m:
            tok = m.group(1).upper()
            # Already ISO alpha-3?
            if len(tok) == 3 and tok.isalpha():
                if tok in NAT_CODE3_TO_CODE2:
                    return _nat3_override(tok)
                # Common 3-letter aliases (UAE, KSA, ...)
                if tok in NAT_ALIAS_TO_CODE2:
                    c2 = (NAT_ALIAS_TO_CODE2.get(tok) or "").upper()
                    return _nat3_override(NAT_CODE2_TO_CODE3.get(c2, tok))
                return _nat3_override(tok)
            # ISO alpha-2 -> alpha-3
            if len(tok) == 2 and tok.isalpha():
                return _nat3_override(NAT_CODE2_TO_CODE3.get(tok, tok))
    except Exception:
        pass

    up = s.upper()

    # Full value might itself be a code/alias
    if len(up) == 3 and up.isalpha():
        if up in NAT_CODE3_TO_CODE2:
            return _nat3_override(up)
        if up in NAT_ALIAS_TO_CODE2:
            c2 = (NAT_ALIAS_TO_CODE2.get(up) or "").upper()
            return _nat3_override(NAT_CODE2_TO_CODE3.get(c2, up))
        return _nat3_override(up)

    if len(up) == 2 and up.isalpha():
        return _nat3_override(NAT_CODE2_TO_CODE3.get(up, up))

    # Aliases / abbreviations
    if up in NAT_ALIAS_TO_CODE2:
        c2 = (NAT_ALIAS_TO_CODE2.get(up) or "").upper()
        return _nat3_override(NAT_CODE2_TO_CODE3.get(c2, (up[:3] if up else "")))

    # Direct name match
    key = s.lower()
    if key in NAT_NAME_TO_CODE3:
        return _nat3_override(NAT_NAME_TO_CODE3.get(key) or "")

    # Normalize punctuation/spaces
    try:
        key2 = re.sub(r"[^a-z0-9 ]+", "", key).strip()
        key2 = re.sub(r"\s+", " ", key2)
        if key2 in NAT_NAME_TO_CODE3:
            return _nat3_override(NAT_NAME_TO_CODE3.get(key2) or "")
        if key2.upper() in NAT_ALIAS_TO_CODE2:
            c2 = (NAT_ALIAS_TO_CODE2.get(key2.upper()) or "").upper()
            return _nat3_override(NAT_CODE2_TO_CODE3.get(c2, key2.upper()[:3]))
        # If user typed a 2-letter code with punctuation around it (e.g. "(AE)")
        m2 = re.match(r"^([a-z]{2,3})$", key2)
        if m2:
            tok2 = m2.group(1).upper()
            if len(tok2) == 3:
                return _nat3_override(tok2)
            if len(tok2) == 2:
                return _nat3_override(NAT_CODE2_TO_CODE3.get(tok2, tok2))
    except Exception:
        pass

    # Fallback: first 3 letters (Latin) or first 3 chars
    try:
        letters = re.sub(r"[^A-Za-z]", "", s)
        if letters:
            return _nat3_override(letters[:3].upper())
    except Exception:
        pass
    return _nat3_override((s[:3] or s).upper())


def nationality_full(nat: str) -> str:
    """Return nationality/country full name from code/alias when possible."""
    s = (nat or "").strip()
    if not s:
        return ""

    key = s.lower()
    if key in NAT_NAME_TO_CODE2:
        return s

    up = s.upper()
    c2 = ""
    c3 = ""

    if up in NAT_ALIAS_TO_CODE2:
        c2 = (NAT_ALIAS_TO_CODE2.get(up) or "").upper()
    elif len(up) == 2 and up.isalpha():
        c2 = up
    elif len(up) == 3 and up.isalpha():
        c3 = up
    else:
        try:
            m = re.match(r"^([A-Za-z]{2,3})\b", s)
            if m:
                tok = (m.group(1) or "").upper()
                if len(tok) == 2:
                    c2 = tok
                elif len(tok) == 3:
                    c3 = tok
        except Exception:
            return s

    if c2:
        return NAT_CODE2_TO_NAME.get(c2, s)
    if c3:
        return NAT_CODE3_TO_NAME.get(c3, s)
    return s


# ------------------------------------------------------------
# Scan / barcode normalization helpers
# ------------------------------------------------------------
# Some barcode scanners (or phone scanner apps) may send:
# - trailing CR/LF, or ASCII Group Separator (GS) / other control chars
# - GS1 prefixes like ]C1
# - URLs (e.g., http://ED-downtime-tools/scan?code=...)
# - Arabic / Persian digits
#
# We normalize those inputs to the actual Case No / ID number.
try:
    _ARABIC_DIGITS_TRANS = str.maketrans("٠١٢٣٤٥٦٧٨٩", "0123456789")
    _PERSIAN_DIGITS_TRANS = str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789")
except Exception:
    _ARABIC_DIGITS_TRANS = None
    _PERSIAN_DIGITS_TRANS = None


def normalize_scan_code(raw) -> str:
    """Normalize scanner/phone input into a clean Case No / ID number string."""
    if raw is None:
        return ""
    s = str(raw)

    # Convert Arabic/Persian digits to latin digits
    try:
        if _ARABIC_DIGITS_TRANS:
            s = s.translate(_ARABIC_DIGITS_TRANS)
        if _PERSIAN_DIGITS_TRANS:
            s = s.translate(_PERSIAN_DIGITS_TRANS)
    except Exception:
        pass

    # Remove non-printable characters (CR/LF/GS etc.)
    try:
        s = "".join(ch for ch in s if ch.isprintable())
    except Exception:
        pass

    s = s.strip()
    if not s:
        return ""

    # Remove common GS1 prefix like ]C1 (3 chars)
    try:
        if s.startswith("]") and len(s) >= 3 and s[2].isdigit():
            s = s[3:].strip()
    except Exception:
        pass

    # If the scanned content is a URL, extract the code-like parameter
    try:
        low = s.lower()
        if low.startswith("http://") or low.startswith("https://"):
            u = urlparse(s)
            qs = parse_qs(u.query or "")
            for k in ("code", "scan_code", "visit_id", "id", "id_number", "mrn"):
                if k in qs and qs[k]:
                    s = str(qs[k][0]).strip()
                    break
            else:
                # Fallback: digits anywhere in the URL
                m = re.search(r"(\d{6,})", s)
                if m:
                    s = m.group(1)
    except Exception:
        pass

    s = str(s).strip()
    if not s:
        return ""

    # If mixed text, extract first numeric run (>=6 digits) — common in scanner outputs
    if not s.isdigit():
        try:
            m = re.search(r"(\d{6,})", s)
            if m:
                s = m.group(1)
        except Exception:
            pass

    return str(s).strip()


