# Barcode (local, offline-safe)
# NOTE: We intentionally avoid ReportLab's dynamic barcode imports because
# PyInstaller may miss submodules like reportlab.graphics.barcode.code128.
# We generate Code128 SVG locally with a small built-in encoder.


# ------------------------------------------------------------
# PDF Unicode font helper
# Tries to use a Unicode-capable TTF (Windows Arial / Linux DejaVu)
# to avoid report generation crashes when text contains non-Latin chars.
# ------------------------------------------------------------
_PDF_UNICODE_FONT_NAME = None


def _get_pdf_unicode_font_name():
    global _PDF_UNICODE_FONT_NAME
    if _PDF_UNICODE_FONT_NAME is not None:
        return _PDF_UNICODE_FONT_NAME

    candidates = [
        # Windows
        (
            "Arial",
            [
                "C:/Windows/Fonts/arial.ttf",
                "C:/Windows/Fonts/ARIAL.TTF",
            ],
        ),
        # Linux
        (
            "DejaVuSans",
            [
                "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
                "/usr/share/fonts/truetype/dejavu/DejaVuSansCondensed.ttf",
            ],
        ),
    ]

    for font_name, paths in candidates:
        for p in paths:
            try:
                if os.path.exists(p):
                    pdfmetrics.registerFont(TTFont(font_name, p))
                    _PDF_UNICODE_FONT_NAME = font_name
                    return _PDF_UNICODE_FONT_NAME
            except Exception:
                continue

    _PDF_UNICODE_FONT_NAME = ""
    return _PDF_UNICODE_FONT_NAME


def _pdf_safe_drawString(c, x, y, text, max_chars=None):
    s = "" if text is None else str(text)
    if max_chars is not None:
        s = s[:max_chars]
    try:
        c.drawString(x, y, s)
        return
    except Exception as draw_exc:
        _log_noncritical_exception(
            "PDF drawString failed; attempting latin-1 fallback",
            draw_exc,
        )
        try:
            s2 = s.encode("latin-1", errors="replace").decode("latin-1")
            c.drawString(x, y, s2)
        except Exception as fallback_exc:
            _log_noncritical_exception(
                "PDF drawString latin-1 fallback failed; text skipped to keep PDF generation running",
                fallback_exc,
            )

# ------------------------------------------------------------
# Download filename helpers (PDF / attachments)
# - Creates human-friendly filenames with patient name, ID, insurance number.
# - Preserves Unicode (Arabic names) using RFC 5987 (filename*).
# - Default behavior is to force download ("attachment").
#   To keep old behavior (open in browser tab), set env var: ED_PDF_INLINE=1
# ------------------------------------------------------------


def _clean_filename_part(val, max_len=80):
    # Keep Unicode text, remove characters illegal on common filesystems.
    if val is None:
        return ""
    s = str(val)

    # Collapse whitespace
    try:
        s = re.sub(r"\s+", " ", s).strip()
    except Exception as e:
        _log_noncritical_exception(
            "Filename whitespace cleanup failed; using strip fallback",
            e,
        )
        s = s.strip()

    if not s:
        return ""

    # Remove non-printable/control characters
    try:
        s = "".join(ch for ch in s if ch.isprintable())
    except Exception as e:
        _log_noncritical_exception(
            "Filename printable-character cleanup failed; keeping original text",
            e,
        )

    # Windows forbidden: <>:"/\|?*  (also safe for macOS/Linux)
    try:
        s = re.sub(r'[<>:"/\\|?*]+', "_", s)
    except Exception as e:
        _log_noncritical_exception(
            "Filename forbidden-character regex cleanup failed; using manual fallback",
            e,
        )
        # Last-resort manual replace
        for ch in '<>:"/\\|?*':
            s = s.replace(ch, "_")

    # Avoid Windows trailing dots/spaces
    s = s.rstrip(" .")

    if max_len and len(s) > max_len:
        s = s[:max_len].rstrip(" ._")

    return s


def _trim_filename_keep_ext(filename, max_len=180):
    if not filename:
        return filename
    filename = str(filename)

    if len(filename) <= max_len:
        return filename

    base, ext = os.path.splitext(filename)
    ext = ext or ""

    room = max_len - len(ext)
    if room <= 1:
        return filename[:max_len].rstrip(" ._")

    base = base[:room].rstrip(" ._")
    return base + ext


def _ascii_fallback_filename(unicode_filename, default="document.pdf"):
    # Browsers that don't support filename* will use filename= (ASCII).
    try:
        f = secure_filename(unicode_filename)
    except Exception:
        f = ""

    if not f:
        f = default

    # Keep PDF extension if present in the original
    try:
        if str(unicode_filename).lower().endswith(".pdf") and not str(
            f
        ).lower().endswith(".pdf"):
            f = f + ".pdf"
    except Exception:
        pass

    return f


def _content_disposition(filename, inline=False):
    # RFC 5987: filename*=UTF-8''<urlencoded>
    disp = "inline" if inline else "attachment"
    fn = str(filename or "document.pdf")

    ascii_fn = _ascii_fallback_filename(fn, default="document.pdf")
    try:
        quoted = quote(fn)
    except Exception:
        try:
            quoted = quote(
                fn.encode("utf-8", errors="ignore").decode("utf-8", errors="ignore")
            )
        except Exception:
            quoted = ""

    return f"{disp}; filename=\"{ascii_fn}\"; filename*=UTF-8''{quoted}"


def _patient_download_filename(
    visit_row, doc_tag, ext="pdf", visit_id=None, extra=None, max_len=180
):
    # visit_row can be sqlite Row, dict, or any mapping.
    def _get(k):
        try:
            return visit_row[k]
        except Exception:
            try:
                return visit_row.get(k)
            except Exception:
                return None

    name = _get("name") or ""
    idn = _get("id_number") or ""
    ins_no = _get("insurance_no") or ""
    if not ins_no:
        ins_no = _get("insurance") or ""

    parts = []
    if name:
        parts.append(name)
    if idn:
        parts.append(f"ID-{idn}")
    if ins_no:
        parts.append(f"INS-{ins_no}")
    if doc_tag:
        parts.append(doc_tag)
    if visit_id:
        parts.append(f"Visit-{visit_id}")
    if extra:
        parts.append(extra)

    cleaned = [_clean_filename_part(p) for p in parts]
    cleaned = [p for p in cleaned if p]

    base = (
        "__".join(cleaned)
        if cleaned
        else (_clean_filename_part(doc_tag or "document") or "document")
    )

    ext = (ext or "").lstrip(".")
    filename = f"{base}.{ext}" if ext else base

    return _trim_filename_keep_ext(filename, max_len=max_len)


def _patient_pdf_headers(visit_row, doc_tag, visit_id=None, extra=None, inline=None):
    """Build Content-Disposition header for patient PDFs with a patient-based filename.

    Default behavior: show the PDF in the browser (inline).
    To force download: add ?download=1 (or ?dl=1).
    To force inline: add ?inline=1 (or ?view=1).

    Environment override:
    - ED_PDF_INLINE=1  -> always inline by default
    - ED_PDF_INLINE=0  -> always download by default
    """

    def _truthy(x):
        if x is None:
            return False
        s = str(x).strip().lower()
        return s in ("1", "true", "yes", "y", "on")

    def _falsy(x):
        if x is None:
            return False
        s = str(x).strip().lower()
        return s in ("0", "false", "no", "n", "off")

    # Decide inline vs attachment
    if inline is None:
        # 1) Query params override (download wins)
        try:
            q_download = request.args.get("download")
            if q_download is None:
                q_download = request.args.get("dl")

            q_inline = request.args.get("inline")
            if q_inline is None:
                q_inline = request.args.get("view")

            if q_download is not None and not _falsy(q_download):
                inline = False
            elif q_inline is not None and not _falsy(q_inline):
                inline = True
        except Exception:
            pass

    if inline is None:
        # 2) Env override (if provided)
        try:
            env_raw = os.environ.get("ED_PDF_INLINE", None)
            if env_raw is not None and str(env_raw).strip() != "":
                if _falsy(env_raw):
                    inline = False
                else:
                    inline = _truthy(env_raw)
        except Exception:
            pass

    if inline is None:
        # 3) Default: inline (view)
        inline = True

    filename = _patient_download_filename(
        visit_row,
        doc_tag=doc_tag,
        ext="pdf",
        visit_id=visit_id,
        extra=extra,
    )
    return {"Content-Disposition": _content_disposition(filename, inline=inline)}


def _pdf_move_mrd_addendum_to_end(pdf_bytes: bytes) -> bytes:
    """Move pages containing 'MRD Downtime Addendum' to the end of the PDF.

    Safe no-op if pypdf is unavailable or no addendum pages are detected.
    """
    try:
        import io

        try:
            from pypdf import PdfReader, PdfWriter
        except Exception:
            from PyPDF2 import PdfReader, PdfWriter

        reader = PdfReader(io.BytesIO(pdf_bytes))
        if not getattr(reader, "pages", None):
            return pdf_bytes

        main_pages = []
        add_pages = []
        for p in reader.pages:
            try:
                t = p.extract_text() or ""
            except Exception:
                t = ""
            if "MRD Downtime Addendum" in t:
                add_pages.append(p)
            else:
                main_pages.append(p)

        if not add_pages:
            return pdf_bytes

        writer = PdfWriter()
        for p in main_pages + add_pages:
            writer.add_page(p)

        out = io.BytesIO()
        writer.write(out)
        return out.getvalue()
    except Exception:
        return pdf_bytes


def _pdf_row_get(row, key, default=None):
    try:
        val = row[key]
        return default if val is None else val
    except Exception:
        try:
            val = row.get(key)
            return default if val is None else val
        except Exception:
            return default


def _pdf_resolve_patient_mrn(visit_row=None, visit_id=None, cur=None):
    """Resolve patient MRN for PDF stamping from row first, then DB fallback."""
    mrn = _pdf_row_get(visit_row, "mrn", "") or _pdf_row_get(
        visit_row, "patient_mrn", ""
    )
    mrn = str(mrn or "").strip()
    if mrn:
        return mrn

    vid = str(visit_id or _pdf_row_get(visit_row, "visit_id", "") or "").strip()
    if not vid or cur is None:
        return ""

    try:
        row = cur.execute(
            """
            SELECT p.mrn
            FROM visits v
            JOIN patients p ON p.id = v.patient_id
            WHERE v.visit_id = ?
            LIMIT 1
            """,
            (vid,),
        ).fetchone()
        mrn = _pdf_row_get(row, "mrn", "")
        return str(mrn or "").strip()
    except Exception:
        return ""


def _pdf_attach_patient_mrn_stamp(c, visit_row=None, visit_id=None, cur=None):
    """Stamp MRN on every non-empty PDF page right before it is finalized."""
    mrn = _pdf_resolve_patient_mrn(visit_row=visit_row, visit_id=visit_id, cur=cur)
    if not mrn:
        return c

    orig_show_page = c.showPage
    orig_save = c.save

    def _page_has_content():
        try:
            return bool(getattr(c, "_code", None))
        except Exception:
            return True

    def _stamp_current_page():
        if getattr(c, "_mrn_stamp_applied", False):
            return
        if not _page_has_content():
            return
        try:
            width, _height = c._pagesize
        except Exception:
            width, _height = A4

        try:
            c.saveState()
            c.setFont("Helvetica-Bold", 8)
            c.setFillColor(colors.black)
            c.drawRightString(width - 1.2 * cm, 0.75 * cm, f"MRN: {mrn}")
            c.restoreState()
            c._mrn_stamp_applied = True
        except Exception:
            try:
                c.setFont("Helvetica-Bold", 8)
                c.setFillColor(colors.black)
                c.drawRightString(width - 1.2 * cm, 0.75 * cm, f"MRN: {mrn}")
                c._mrn_stamp_applied = True
            except Exception:
                pass

    def _show_page_with_mrn(*args, **kwargs):
        _stamp_current_page()
        result = orig_show_page(*args, **kwargs)
        c._mrn_stamp_applied = False
        return result

    def _save_with_mrn(*args, **kwargs):
        _stamp_current_page()
        return orig_save(*args, **kwargs)

    c._mrn_stamp_applied = False
    c.showPage = _show_page_with_mrn
    c.save = _save_with_mrn
    return c


# ------------------------------------------------------------
# ESI (Emergency Severity Index) helpers
# - Stored value remains "ES1..ES5" for backward compatibility.
# - Display value becomes "ESI1..ESI5" everywhere in UI/PDF.
# ------------------------------------------------------------
_ESI_CAT_RE = re.compile(r"^(ESI|ES)\s*([1-5])$", re.I)


def normalize_esi_cat(cat):
    """Normalize triage category to legacy stored form ES1..ES5."""
    if cat is None:
        return ""
    s = str(cat).strip().upper()
    m = _ESI_CAT_RE.match(s)
    if m:
        return f"ES{m.group(2)}"
    return s


def display_esi_cat(cat):
    """Display triage category as ESI1..ESI5 (UI friendly)."""
    if cat is None:
        return ""
    s = str(cat).strip()
    if not s:
        return ""
    m = _ESI_CAT_RE.match(s.strip().upper())
    if m:
        return f"ESI{m.group(2)}"
    return s



