# Resolve static assets directory robustly:
# - Supports running from source (python)
# - Supports PyInstaller onefile (assets extracted under sys._MEIPASS)
# - Supports PyInstaller running EXE from .\dist\ while static folder is shipped next to the project root
def _resolve_static_dir():
    # Optional override (useful for troubleshooting / custom deployments)
    env_dir = (
        os.environ.get("STATIC_DIR")
        or os.environ.get("APP_STATIC_DIR")
        or os.environ.get("ED_STATIC_DIR")
    )

    candidates = []
    if env_dir:
        candidates.append(env_dir)

    # If packaged/frozen (PyInstaller)
    if getattr(sys, "frozen", False):
        meipass = getattr(sys, "_MEIPASS", None)
        if meipass:
            candidates.append(os.path.join(meipass, "static"))

        exe_dir = os.path.dirname(sys.executable)
        candidates.extend(
            [
                os.path.join(exe_dir, "static"),
                # Common layout: project\dist\ED_Downtime_Server.exe + project\static\...
                os.path.join(os.path.dirname(exe_dir), "static"),
                # Safety: sometimes EXE sits deeper
                os.path.join(os.path.dirname(os.path.dirname(exe_dir)), "static"),
            ]
        )

    # Source layout
    file_dir = os.path.dirname(os.path.abspath(__file__))
    candidates.extend(
        [
            os.path.join(file_dir, "static"),
            os.path.join(os.getcwd(), "static"),
        ]
    )

    # Prefer a folder that actually contains our expected bootstrap assets
    for p in candidates:
        if not p:
            continue
        p = os.path.abspath(p)
        if os.path.isdir(p):
            boot_css = os.path.join(p, "vendor", "bootstrap", "bootstrap.min.css")
            if os.path.exists(boot_css):
                return p

    # Fallback: first existing directory
    for p in candidates:
        if not p:
            continue
        p = os.path.abspath(p)
        if os.path.isdir(p):
            return p

    # Last resort (may not exist, but keeps Flask happy)
    return os.path.join(file_dir, "static")


STATIC_DIR = _resolve_static_dir()

