# ============================================================
# Mobile/iPad export cache protection
# ============================================================
# Some mobile browsers (especially Safari on iPad/iPhone) can aggressively
# reuse cached PDF / Excel / CSV downloads when the URL is identical.  These
# helpers make export/download responses non-cacheable and remove conditional
# request validators so the browser always receives a fresh file.
NO_CACHE_EXPORT_HEADERS = {
    "Cache-Control": "no-cache, no-store, must-revalidate",
    "Pragma": "no-cache",
    "Expires": "0",
    "Surrogate-Control": "no-store",
}


def _cache_buster_value():
    """Return a changing value suitable for ?t= links in Jinja templates."""
    try:
        return str(int(time.time() * 1000))
    except Exception:
        return str(uuid.uuid4())


app.jinja_env.globals["cache_buster"] = _cache_buster_value


def _is_export_or_download_request():
    """Detect routes/URLs that should never use browser/proxy cache."""
    try:
        path = (request.path or "").lower()
    except Exception:
        path = ""
    try:
        endpoint = (request.endpoint or "").lower()
    except Exception:
        endpoint = ""
    try:
        query = (request.query_string or b"").decode("utf-8", errors="ignore").lower()
    except Exception:
        query = ""

    tokens = (
        "export",
        "download",
        "/pdf",
        ".pdf",
        ".xlsx",
        ".xls",
        ".csv",
    )
    return (
        any(t in path for t in tokens)
        or any(t in endpoint for t in tokens)
        or "download" in query
        or "dl=1" in query
    )


@app.before_request
def _strip_export_cache_validators():
    """Ignore mobile/browser conditional-cache headers for exports/downloads."""
    try:
        if not _is_export_or_download_request():
            return None
        for key in (
            "HTTP_IF_NONE_MATCH",
            "HTTP_IF_MODIFIED_SINCE",
            "HTTP_IF_MATCH",
            "HTTP_IF_UNMODIFIED_SINCE",
            "HTTP_IF_RANGE",
        ):
            request.environ.pop(key, None)
    except Exception:
        pass
    return None


def _apply_export_no_cache_headers(resp):
    """Apply hard no-cache headers to a Flask response object."""
    try:
        for key, value in NO_CACHE_EXPORT_HEADERS.items():
            resp.headers[key] = value

        # Prevent 304 / stale file reuse where possible.
        try:
            resp.headers.pop("ETag", None)
        except Exception:
            pass
        try:
            resp.headers.pop("Last-Modified", None)
        except Exception:
            pass

        # Make proxy/browser variants explicit without overwriting an existing Vary.
        vary = resp.headers.get("Vary") or ""
        wanted = ["Cookie", "Authorization", "Accept-Encoding"]
        current = {v.strip().lower() for v in vary.split(",") if v.strip()}
        add = [v for v in wanted if v.lower() not in current]
        if add:
            resp.headers["Vary"] = (vary + ", " + ", ".join(add)).strip(", ") if vary else ", ".join(add)
    except Exception:
        pass
    return resp


@app.after_request
def _prevent_mobile_export_download_cache(resp):
    """Disable caching for export/download paths and generated PDF/Excel/CSV files."""
    try:
        mimetype = (getattr(resp, "mimetype", "") or "").lower()
        content_type = (resp.headers.get("Content-Type") or "").lower()
        content_disp = (resp.headers.get("Content-Disposition") or "").lower()

        generated_file_types = (
            "application/pdf",
            "application/vnd.ms-excel",
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            "text/csv",
        )
        is_generated_file = any(ft in mimetype or ft in content_type for ft in generated_file_types)
        is_attachment = "attachment" in content_disp

        if _is_export_or_download_request() or is_generated_file or is_attachment:
            resp = _apply_export_no_cache_headers(resp)
    except Exception:
        pass
    return resp

