# ------------------------------------------------------------
# Activation (digitally signed key; no hardcoded password)
# - When ACTIVATION_REQUIRED is True, app only runs if a valid key is stored.
# - Allowed without key: /activate, /healthz, static.
# ------------------------------------------------------------
@app.before_request
def _activation_check():
    try:
        from config import APP_CONFIG

        if not APP_CONFIG.get("ACTIVATION_REQUIRED", False):
            return None
    except Exception:
        return None
    try:
        import activation_key as ak

        if ak.is_activation_valid():
            return None
    except Exception:
        pass
    ep = (request.endpoint or "").rsplit(".", 1)[-1]
    if ep in ("static", "healthz", "activate"):
        return None
    if request.path and request.path.startswith("/static/"):
        return None
    if request.path == "/healthz":
        return None
    if request.path == "/activate":
        return None
    try:
        import activation_key as ak

        html = render_template_string("""
            <!DOCTYPE html>
            <html><head><meta charset="utf-8"><title>Activation Required</title>
            <link href="{{ url_for('static', filename='vendor/bootstrap/bootstrap.min.css') }}" rel="stylesheet"></head>
            <body class="bg-light"><div class="container py-5">
            <h1 class="text-danger">Activation Required</h1>
            <p>This instance is not activated. Please enter your activation key.</p>
            <a class="btn btn-primary" href="{{ url_for('activate') }}">Enter activation key</a>
            </div></body></html>
            """)
        return html, 403
    except Exception:
        return "Activation required. Go to /activate to enter your key.", 403


