@app.before_request
def _audit_start():
    try:
        ensure_audit_log_schema_compat_once()
    except Exception:
        pass
    try:
        security.audit_before_request()
    except Exception:
        pass


@app.after_request
def _audit_end(resp):
    try:
        security.audit_after_request(resp)
    except Exception:
        pass
    return resp


@app.before_request
def _runtime_diag_start():
    try:
        g._runtime_diag_start = time.perf_counter()
    except Exception:
        pass


@app.after_request
def _runtime_diag_end(resp):
    try:
        if RUNTIME_DIAGNOSTICS is not None:
            _start = getattr(g, "_runtime_diag_start", None)
            _dur_ms = None
            if _start is not None:
                _dur_ms = int((time.perf_counter() - float(_start)) * 1000)
            RUNTIME_DIAGNOSTICS.record_request(
                method=request.method,
                path=request.path,
                endpoint=(request.endpoint or ""),
                status=getattr(resp, "status_code", None),
                duration_ms=_dur_ms,
                location=(resp.headers.get("Location") or ""),
                username=(session.get("username") or ""),
                role=(session.get("role") or ""),
            )
    except Exception:
        pass
    return resp


# Endpoints that are exempt from CSRF checks (JSON APIs, etc.)
CSRF_EXEMPT_ENDPOINTS = set()


def _csrf_submitted_token():
    """Read CSRF token from all supported tablet/browser submission paths.

    Supported inputs:
    - standard form field: csrf_token
    - AJAX headers: X-CSRFToken, X-CSRF-Token, X-CSRF
    - JSON body key: csrf_token
    """
    try:
        token = request.form.get("csrf_token")
        if token:
            return str(token).strip()
    except Exception:
        pass

    for header_name in ("X-CSRFToken", "X-CSRF-Token", "X-CSRF"):
        try:
            token = request.headers.get(header_name)
            if token:
                return str(token).strip()
        except Exception:
            pass

    try:
        if request.is_json:
            payload = request.get_json(silent=True) or {}
            token = payload.get("csrf_token") if isinstance(payload, dict) else None
            if token:
                return str(token).strip()
    except Exception:
        pass
    return ""


def _csrf_header_token():
    for header_name in ("X-CSRFToken", "X-CSRF-Token", "X-CSRF"):
        try:
            token = request.headers.get(header_name)
            if token:
                return str(token).strip()
        except Exception:
            pass
    return ""


def _csrf_wants_json():
    try:
        if request.is_json:
            return True
        accept = (request.headers.get("Accept") or "").lower()
        requested = (request.headers.get("X-Requested-With") or "").lower()
        return "application/json" in accept or requested == "xmlhttprequest"
    except Exception:
        return False


@app.after_request
def _csrf_cookie_after_request(resp):
    """Expose the current CSRF token in a non-HttpOnly same-site cookie.

    This is intentionally only a CSRF token, not an auth secret. It lets iPad,
    tablet/PWA, and bfcache-restored pages refresh AJAX headers and hidden form
    fields without getting stuck on a stale token after Safari restores a page.
    """
    try:
        token = session.get("csrf_token")
        if token:
            resp.set_cookie(
                "ed_csrf_token",
                str(token),
                max_age=12 * 60 * 60,
                secure=bool(app.config.get("SESSION_COOKIE_SECURE", False)),
                httponly=False,
                samesite=app.config.get("SESSION_COOKIE_SAMESITE", "Lax") or "Lax",
            )
    except Exception:
        pass
    return resp


@app.route("/csrf_token", methods=["GET"])
def csrf_token_api():
    """Return a fresh CSRF token for tablet/PWA restored pages."""
    token = generate_csrf_token()
    return jsonify(success=True, csrf_token=token)


@app.before_request
def csrf_protect():
    if request.method in ("POST", "PUT", "PATCH", "DELETE"):
        endpoint = (request.endpoint or "").rsplit(".", 1)[-1]
        if endpoint in CSRF_EXEMPT_ENDPOINTS:
            return

        # If the browser lost the login/session cookie, do not mask the real
        # problem as a CSRF error. Let the route/login_required redirect to login.
        if not (session.get("user_id") or session.get("username")) and endpoint != "login":
            return

        session_token = str(session.get("csrf_token") or "").strip()
        submitted_token = _csrf_submitted_token()

        if session_token and submitted_token:
            try:
                if secrets.compare_digest(session_token, submitted_token):
                    return
            except Exception:
                if session_token == submitted_token:
                    return

        # Tablet/PWA recovery path: if Safari restored a page with a missing
        # server-side CSRF token but our JS sent the same-site CSRF cookie in a
        # header, restore the session token and allow this same-origin AJAX POST.
        header_token = _csrf_header_token()
        cookie_token = str(request.cookies.get("ed_csrf_token") or "").strip()
        if (not session_token) and header_token and cookie_token:
            try:
                same = secrets.compare_digest(header_token, cookie_token)
            except Exception:
                same = header_token == cookie_token
            if same and len(header_token) >= 24:
                session["csrf_token"] = header_token
                return

        try:
            _log_noncritical_exception(
                "CSRF validation failed",
                f"endpoint={endpoint} path={request.path} has_session_token={bool(session_token)} has_submitted_token={bool(submitted_token)} ua={(request.headers.get('User-Agent') or '')[:120]}",
            )
        except Exception:
            pass

        if _csrf_wants_json():
            return jsonify(
                success=False,
                error="CSRF validation failed. Refresh the page and try again.",
                refresh_csrf_url="/csrf_token",
            ), 400

        try:
            flash("Session security token expired. The page was refreshed; please try the action again.", "warning")
        except Exception:
            pass
        try:
            return redirect(request.referrer or url_for("login"))
        except Exception:
            return "CSRF validation failed. Please refresh the page and try again.", 400


# ------------------------------------------------------------
# Maintenance mode: Database Restore in progress
# - Restore runs as a background job to avoid HTTP/Nginx timeouts.
# - While restore is running, block normal pages to prevent DB locks/corruption.
# ------------------------------------------------------------
RESTORE_IN_PROGRESS = threading.Event()
RESTORE_CURRENT_JOB_ID = None  # last started restore job id
RESTORE_JOBS = {}  # job_id -> dict
RESTORE_JOBS_LOCK = threading.Lock()


@app.before_request
def _block_requests_during_restore():
    try:
        if not RESTORE_IN_PROGRESS.is_set():
            return
        ep = (request.endpoint or "").rsplit(".", 1)[-1]
        # Allow a small set of endpoints to keep UX working during restore
        if ep in (
            "static",
            "login",
            "logout",
            "admin_restore_job",
            "admin_restore_status",
            "pwa_manifest",
            "pwa_sw",
        ):
            return
        return (
            "<div style='font-family: Arial; padding: 18px'>"
            "<h3>⏳ Database restore in progress...</h3>"
            "<p>The system is temporarily locked to prevent data corruption.</p>"
            "<p>Keep the restore status page open until it finishes.</p>"
            "</div>",
            503,
        )
    except Exception:
        return


