# ------------------------------------------------------------
# Database engine auto-detect (PostgreSQL/Railway-safe)
# ------------------------------------------------------------
def _truthy_env(value):
    try:
        return str(value or "").strip().lower() in ("1", "true", "yes", "y", "on")
    except Exception:
        return False


def _first_nonempty_env(*names):
    for name in names:
        try:
            value = os.environ.get(name)
            if value is not None and str(value).strip():
                return str(value).strip()
        except Exception:
            pass
    return ""


def _build_pg_dsn_from_parts():
    """Build a libpq DSN from PG* env vars when DATABASE_URL is absent.

    Railway commonly provides DATABASE_URL, but some PostgreSQL templates expose
    PGHOST/PGPORT/PGDATABASE/PGUSER/PGPASSWORD instead. This keeps the app
    portable across Railway, local Docker, and Windows/offline installs.
    """
    host = _first_nonempty_env("PGHOST", "POSTGRES_HOST", "POSTGRESQL_HOST")
    database = _first_nonempty_env("PGDATABASE", "POSTGRES_DB", "POSTGRES_DATABASE", "POSTGRESQL_DATABASE")
    user = _first_nonempty_env("PGUSER", "POSTGRES_USER", "POSTGRES_USERNAME", "POSTGRESQL_USER")
    password = _first_nonempty_env("PGPASSWORD", "POSTGRES_PASSWORD", "POSTGRESQL_PASSWORD")
    port = _first_nonempty_env("PGPORT", "POSTGRES_PORT", "POSTGRESQL_PORT") or "5432"
    if not (host and database and user):
        return ""
    parts = [
        f"dbname={database}",
        f"user={user}",
        f"host={host}",
        f"port={port}",
    ]
    if password:
        parts.append(f"password={password}")
    sslmode = _first_nonempty_env("PGSSLMODE", "POSTGRES_SSLMODE")
    if not sslmode and (os.environ.get("RAILWAY_ENVIRONMENT") or os.environ.get("RAILWAY_PROJECT_ID")):
        sslmode = "require"
    if sslmode:
        parts.append(f"sslmode={sslmode}")
    return " ".join(parts)


def _normalize_pg_dsn(raw_dsn):
    """Return a psycopg2/libpq-compatible PostgreSQL DSN.

    Handles Railway-style postgres:// URLs, private/public database URLs, and
    adds sslmode=require on Railway unless sslmode is already supplied.
    """
    dsn = str(raw_dsn or "").strip()
    if not dsn:
        return ""
    if dsn.startswith("postgres://"):
        dsn = "postgresql://" + dsn[len("postgres://") :]
    if dsn.startswith("postgresql://"):
        try:
            parsed = urlparse(dsn)
            q = parse_qs(parsed.query or "", keep_blank_values=True)
            has_sslmode = "sslmode" in q or "ssl" in q
            if (os.environ.get("RAILWAY_ENVIRONMENT") or os.environ.get("RAILWAY_PROJECT_ID")) and not has_sslmode:
                q["sslmode"] = ["require"]
                query = urlencode(q, doseq=True)
                dsn = urlunparse((parsed.scheme, parsed.netloc, parsed.path, parsed.params, query, parsed.fragment))
        except Exception:
            pass
    return dsn


def _detect_db_engine():
    explicit = (os.environ.get("DB_ENGINE") or APP_CONFIG.get("DB_ENGINE") or "").strip().lower()
    if explicit:
        return explicit
    pg_url = _first_nonempty_env(
        "DATABASE_URL",
        "DATABASE_PRIVATE_URL",
        "PG_DSN",
        "POSTGRES_URL",
        "POSTGRESQL_URL",
        "RAILWAY_DATABASE_URL",
    )
    if pg_url or _build_pg_dsn_from_parts():
        return "postgres"
    return "sqlite"


DB_ENGINE = _detect_db_engine()

