def _pg_dict_cursor_base():
    try:
        if psycopg2 is None:
            import importlib as _psycopg_importlib

            _pg = _psycopg_importlib.import_module("psycopg2")
            _extras = _psycopg_importlib.import_module("psycopg2.extras")
            globals()["psycopg2"] = _pg
            psycopg2.extras = _extras
        return psycopg2.extras.DictCursor
    except Exception:
        return None


_PG_DICT_CURSOR_BASE = _pg_dict_cursor_base()


class QmarkDictCursor((_PG_DICT_CURSOR_BASE or object)):
    """
    psycopg2 cursor that mimics sqlite's "?" param style
    **and** returns self from execute()/executemany() like sqlite3.

    PgBouncer note:
    - In transaction pooling mode, a session-level ``SET search_path`` may not
      survive after COMMIT/ROLLBACK because the next transaction can land on a
      different backend server connection.
    - To keep unqualified table names working on fresh Windows installs, this
      cursor re-applies ``search_path=public`` at the beginning of each new
      transaction.
    """

    def _convert(self, query: str) -> str:
        """Convert sqlite-style ? placeholders to psycopg2 %s and
        escape any literal % so psycopg2's printf-style formatting
        does not treat them as placeholders.
        """
        if not query:
            return query
        if "?" in query and "%s" not in query:
            query = query.replace("%", "%%")
            query = query.replace("?", "%s")
        return query

    def _query_needs_public_search_path(self, query) -> bool:
        try:
            q = str(query or "")
        except Exception:
            q = ""
        qn = " ".join(q.strip().lower().split())
        if not qn:
            return False
        if "search_path" in qn:
            return False
        if "pg_catalog.set_config" in qn:
            return False
        if qn.startswith("set ") or qn.startswith("show ") or qn.startswith("reset "):
            return False
        if qn.startswith("begin") or qn.startswith("commit") or qn.startswith("rollback"):
            return False
        return True

    def _ensure_public_search_path_for_txn(self, original_query) -> None:
        if not self._query_needs_public_search_path(original_query):
            return
        try:
            if psycopg2 is not None and hasattr(psycopg2, "extensions"):
                try:
                    tx_status = self.connection.get_transaction_status()
                except Exception:
                    tx_status = None
                if tx_status == psycopg2.extensions.TRANSACTION_STATUS_IDLE:
                    try:
                        setattr(self.connection, "_ed_public_search_path_for_txn", False)
                    except Exception:
                        pass
        except Exception:
            pass
        try:
            if bool(getattr(self.connection, "_ed_public_search_path_for_txn", False)):
                return
        except Exception:
            pass
        for stmt in (
            "SELECT pg_catalog.set_config('search_path', 'public', true)",
            "SET LOCAL search_path TO public",
        ):
            try:
                super().execute(stmt)
                try:
                    setattr(self.connection, "_ed_public_search_path_for_txn", True)
                except Exception:
                    pass
                return
            except Exception:
                continue

    def execute(self, query, vars=None):
        if _PG_DICT_CURSOR_BASE is None:
            raise RuntimeError("psycopg2.extras.DictCursor is not available.")
        q = self._convert(query)
        if vars is not None and not hasattr(vars, "__iter__"):
            vars = (vars,)
        try:
            self._ensure_public_search_path_for_txn(query)
        except Exception:
            pass
        try:
            super().execute(q, vars)
        except Exception:
            try:
                self.connection.rollback()
            except Exception:
                pass
            try:
                setattr(self.connection, "_ed_public_search_path_for_txn", False)
            except Exception:
                pass
            raise
        return self

    def executemany(self, query, vars_list):
        if _PG_DICT_CURSOR_BASE is None:
            raise RuntimeError("psycopg2.extras.DictCursor is not available.")
        q = self._convert(query)
        try:
            self._ensure_public_search_path_for_txn(query)
        except Exception:
            pass
        try:
            super().executemany(q, vars_list)
        except Exception:
            try:
                self.connection.rollback()
            except Exception:
                pass
            try:
                setattr(self.connection, "_ed_public_search_path_for_txn", False)
            except Exception:
                pass
            raise
        return self



class PostgresDBWrapper:
    """
    SQLite-style wrapper over a psycopg2 connection.

    20260528 connection lifecycle fix:
    - Detects a closed/released raw connection before cursor creation.
    - Reacquires a fresh request-scoped connection when code calls close_db(None)
      manually and then continues using an old local db variable.
    - Never closes a pooled connection directly from wrapper.close(); it delegates
      to Flask teardown/pool_putconn.
    """

    def __init__(self, conn=None):
        self._conn = conn
        self._released = False

    def _mark_released(self):
        self._conn = None
        self._released = True

    def _conn_closed(self, conn):
        try:
            return conn is None or bool(getattr(conn, "closed", 1))
        except Exception:
            return True

    def _ensure_live_connection(self):
        conn = self._conn
        if not self._conn_closed(conn):
            return conn

        # Drop any stale connection reference first.
        if conn is not None:
            try:
                from db import pool_putconn
                pool_putconn(conn, close=True)
            except Exception:
                pass
            self._conn = None

        try:
            from flask import has_app_context, g
        except Exception as exc:
            raise RuntimeError("PostgreSQL connection is closed and no Flask context is available") from exc

        if not has_app_context():
            raise RuntimeError("PostgreSQL connection is closed outside Flask application context")

        existing = getattr(g, "_pg_conn", None)
        if not self._conn_closed(existing):
            self._conn = existing
            self._released = False
            return existing

        # Reacquire for the current request. This protects old local variables
        # after legacy code manually called close_db(None) before request end.
        from db import acquire_request_db_slot, pool_getconn

        slot_acquired = bool(getattr(g, "_pg_request_db_slot", False))
        if not slot_acquired:
            acquire_request_db_slot()
            g._pg_request_db_slot = True
        try:
            conn = pool_getconn()
            conn.autocommit = False
        except Exception:
            if not slot_acquired:
                try:
                    from db import release_request_db_slot
                    release_request_db_slot()
                    g._pg_request_db_slot = False
                except Exception:
                    pass
            raise
        g._pg_conn = conn
        g.db = self
        self._conn = conn
        self._released = False
        return conn

    def cursor(self):
        return self._ensure_live_connection().cursor(cursor_factory=QmarkDictCursor)

    def execute(self, query, params=None):
        cur = self.cursor()
        cur.execute(query, params)
        return cur

    def commit(self):
        conn = self._ensure_live_connection()
        try:
            return conn.commit()
        finally:
            try:
                setattr(conn, "_ed_public_search_path_for_txn", False)
            except Exception:
                pass

    def rollback(self):
        conn = self._ensure_live_connection()
        try:
            return conn.rollback()
        finally:
            try:
                setattr(conn, "_ed_public_search_path_for_txn", False)
            except Exception:
                pass

    def close(self):
        # Do not call raw psycopg2 close() for pooled request connections.
        try:
            close_db(None)
        except Exception:
            try:
                from db import pool_putconn
                if self._conn is not None:
                    pool_putconn(self._conn)
            finally:
                self._mark_released()


def get_db():
    if "db" not in g:
        if DB_ENGINE == "postgres":
            from db import (
                acquire_request_db_slot,
                driver_available,
                driver_import_error,
                pool_getconn,
                release_request_db_slot,
            )

            if not driver_available() and psycopg2 is None:
                raise RuntimeError(
                    "PostgreSQL driver is not available. "
                    f"{driver_import_error() or 'Install psycopg2-binary or rebuild the EXE with psycopg2 hidden imports.'}"
                )

            slot_acquired = False
            try:
                acquire_request_db_slot()
                slot_acquired = True
                conn = pool_getconn()
                conn.autocommit = False
            except Exception:
                if slot_acquired:
                    try:
                        release_request_db_slot()
                    except Exception:
                        pass
                raise

            g._pg_conn = conn
            g._pg_request_db_slot = slot_acquired
            g.db = PostgresDBWrapper(conn)
        else:
            conn = sqlite3.connect(DATABASE, check_same_thread=False)
            conn.row_factory = sqlite3.Row
            try:
                wal = os.environ.get("SQLITE_WAL")
                if wal is None:
                    wal = APP_CONFIG.get("SQLITE_WAL", True)
                wal_on = str(wal).strip().lower() not in ("0", "false", "no", "off")
                if wal_on:
                    conn.execute("PRAGMA journal_mode=WAL")
            except Exception:
                pass
            try:
                busy = os.environ.get("SQLITE_BUSY_TIMEOUT_MS")
                if busy is None:
                    busy = APP_CONFIG.get("SQLITE_BUSY_TIMEOUT_MS", 5000)
                conn.execute(f"PRAGMA busy_timeout={int(busy)}")
            except Exception:
                pass
            try:
                conn.execute("PRAGMA synchronous=NORMAL")
            except Exception:
                pass
            try:
                conn.execute("PRAGMA temp_store=MEMORY")
            except Exception:
                pass
            g.db = conn
    return g.db


@app.teardown_appcontext
def close_db(exception):
    if DB_ENGINE == "postgres":
        wrapper = g.pop("db", None)
        conn = g.pop("_pg_conn", None)
        slot_acquired = bool(g.pop("_pg_request_db_slot", False))

        try:
            if wrapper is not None and hasattr(wrapper, "_mark_released"):
                wrapper._mark_released()
        except Exception:
            pass

        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
            try:
                from db import pool_putconn
                pool_putconn(conn)
            except Exception:
                try:
                    conn.close()
                except Exception:
                    pass

        if slot_acquired:
            try:
                from db import release_request_db_slot
                release_request_db_slot()
            except Exception:
                pass
        return

    db = g.pop("db", None)
    if db:
        try:
            db.close()
        except Exception:
            pass



