def _release_current_session_visit_locks():
    """Best-effort cleanup for any open visit locks owned by the current session."""
    try:
        u = (session.get("username") or "").strip()
        if not u:
            return
        try:
            ensure_visit_lock_schema()
        except Exception:
            pass
        db = None
        try:
            db = get_db()
            cur = db.cursor()
            _viewer = (session.get("visit_lock_viewer_token") or "").strip()
            if _viewer:
                cur.execute(
                    "DELETE FROM visit_locks_sessions WHERE viewer_token=?",
                    (_viewer,),
                )
            else:
                cur.execute(
                    "DELETE FROM visit_locks_sessions WHERE username=?",
                    (u,),
                )
            try:
                db.commit()
            except Exception:
                pass
        except Exception:
            try:
                if db is not None:
                    db.rollback()
            except Exception:
                pass
    except Exception:
        pass


def _single_session_redis_client():
    try:
        if redis_support is None:
            return None
        client = None
        try:
            client = redis_support.get_sessions_client()
        except Exception:
            client = None
        if client is None:
            try:
                client = redis_support.get_cache_client()
            except Exception:
                client = None
        return client
    except Exception:
        return None


def _single_session_key(user_id) -> str:
    return f"ed_dt:single_session:{str(user_id).strip()}"


def _ensure_single_session_db_schema():
    global _SINGLE_SESSION_DB_SCHEMA_READY
    if _SINGLE_SESSION_DB_SCHEMA_READY:
        return
    db = None
    try:
        db = get_db()
        cur = db.cursor()
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS active_user_sessions (
                user_id BIGINT PRIMARY KEY,
                username TEXT,
                session_token TEXT,
                updated_at TEXT
            )
            """
        )
        try:
            db.commit()
        except Exception:
            pass
        _SINGLE_SESSION_DB_SCHEMA_READY = True
    except Exception:
        try:
            if db is not None:
                db.rollback()
        except Exception:
            pass


def _single_session_registry_get(user_id):
    if not user_id:
        return ""
    try:
        client = _single_session_redis_client()
        if client is not None:
            raw = client.get(_single_session_key(user_id))
            if raw is None:
                return ""
            if isinstance(raw, bytes):
                return raw.decode("utf-8", errors="ignore")
            return str(raw)
    except Exception:
        pass
    db = None
    try:
        _ensure_single_session_db_schema()
        db = get_db()
        cur = db.cursor()
        row = cur.execute(
            "SELECT session_token FROM active_user_sessions WHERE user_id=?",
            (user_id,),
        ).fetchone()
        if not row:
            return ""
        try:
            return (row["session_token"] or "").strip()
        except Exception:
            return (row[0] or "").strip()
    except Exception:
        return ""
    finally:
        try:
            if db is not None:
                db.rollback()
        except Exception:
            pass


def _single_session_registry_set(user_id, username, session_token):
    if not user_id or not session_token:
        return
    try:
        client = _single_session_redis_client()
        if client is not None:
            client.setex(
                _single_session_key(user_id),
                max(3600, 7 * 24 * 3600),
                str(session_token),
            )
            return
    except Exception:
        pass
    db = None
    try:
        _ensure_single_session_db_schema()
        db = get_db()
        cur = db.cursor()
        cur.execute("DELETE FROM active_user_sessions WHERE user_id=?", (user_id,))
        cur.execute(
            "INSERT INTO active_user_sessions (user_id, username, session_token, updated_at) VALUES (?, ?, ?, ?)",
            (
                user_id,
                (username or "").strip(),
                str(session_token),
                datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            ),
        )
        try:
            db.commit()
        except Exception:
            pass
    except Exception:
        try:
            if db is not None:
                db.rollback()
        except Exception:
            pass


def _single_session_clear_registry(user_id=None, session_token=None):
    user_id = user_id or session.get("user_id")
    if not user_id:
        return
    try:
        client = _single_session_redis_client()
        if client is not None:
            key = _single_session_key(user_id)
            if session_token:
                raw = client.get(key)
                current = raw.decode("utf-8", errors="ignore") if isinstance(raw, bytes) else (str(raw) if raw is not None else "")
                if current and current != str(session_token):
                    return
            client.delete(key)
            return
    except Exception:
        pass
    db = None
    try:
        _ensure_single_session_db_schema()
        db = get_db()
        cur = db.cursor()
        if session_token:
            cur.execute(
                "DELETE FROM active_user_sessions WHERE user_id=? AND session_token=?",
                (user_id, str(session_token)),
            )
        else:
            cur.execute("DELETE FROM active_user_sessions WHERE user_id=?", (user_id,))
        try:
            db.commit()
        except Exception:
            pass
    except Exception:
        try:
            if db is not None:
                db.rollback()
        except Exception:
            pass


def _single_session_check_current(force=False):
    if not SINGLE_SESSION_ENFORCED:
        return True
    user_id = session.get("user_id")
    token = (session.get("_session_token") or "").strip()
    if not user_id or not token:
        return True
    now_ts = int(time.time())
    try:
        last_check = int(session.get("single_session_last_check") or 0)
    except Exception:
        last_check = 0
    if (not force) and last_check and (now_ts - last_check) < max(5, int(SINGLE_SESSION_CHECK_INTERVAL_SECONDS or 15)):
        return True

    current = (_single_session_registry_get(user_id) or "").strip()
    if not current:
        try:
            _single_session_registry_set(user_id, session.get("username"), token)
        except Exception:
            pass
        session["single_session_last_check"] = now_ts
        try:
            session.modified = True
        except Exception:
            pass
        return True

    if current != token:
        return False

    session["single_session_last_check"] = now_ts
    try:
        session.modified = True
    except Exception:
        pass
    return True


# ============================================================
# Security Headers
# ============================================================


@app.after_request
def add_security_headers(resp):
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["X-Frame-Options"] = "DENY"
    resp.headers["X-XSS-Protection"] = "1; mode=block"

    # Performance: allow browser caching for local static assets (bootstrap/js/css/svg)
    # while keeping application pages as no-store.
    try:
        p = request.path or ""
        if p.startswith("/static/") or p.endswith(
            (".css", ".js", ".svg", ".png", ".jpg", ".jpeg", ".webp", ".ico")
        ):
            # If the endpoint already set Cache-Control (e.g., barcode.svg), keep it.
            resp.headers.setdefault("Cache-Control", "public, max-age=604800")
        else:
            resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
            resp.headers["Pragma"] = "no-cache"
            resp.headers["Expires"] = "0"
            ep = (request.endpoint or "").rsplit(".", 1)[-1]
            if ep in ("login", "logout"):
                resp.headers.pop("Clear-Site-Data", None)  # TABLET_LOGOUT_FAST_20260526A: avoid slow iPad/Safari site-data purge
    except Exception:
        resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
        resp.headers["Pragma"] = "no-cache"
        resp.headers["Expires"] = "0"

    return resp


