def init_logging_table():
    db = get_db()
    cur = db.cursor()
    if DB_ENGINE == "postgres":
        cur.execute("""
            CREATE TABLE IF NOT EXISTS activity_log (
                id BIGSERIAL PRIMARY KEY,
                action TEXT NOT NULL,
                visit_id TEXT,
                username TEXT,
                details TEXT,
                created_at TEXT NOT NULL
            )
        """)
    else:
        cur.execute("""
            CREATE TABLE IF NOT EXISTS activity_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                action TEXT NOT NULL,
                visit_id TEXT,
                username TEXT,
                details TEXT,
                created_at TEXT NOT NULL
            )
        """)
    db.commit()


_ACTIVITY_LOG_ASYNC = str(os.environ.get("ACTION_LOG_ASYNC", APP_CONFIG.get("ACTION_LOG_ASYNC", True))).strip().lower() not in ("0", "false", "no", "off")
_ACTIVITY_LOG_QUEUE_MAX = max(1000, int(os.environ.get("ACTION_LOG_QUEUE_MAX", APP_CONFIG.get("ACTION_LOG_QUEUE_MAX", 50000)) or 50000))
_ACTIVITY_LOG_WORKER_BATCH = max(1, int(os.environ.get("ACTION_LOG_WORKER_BATCH", APP_CONFIG.get("ACTION_LOG_WORKER_BATCH", 100)) or 100))
_ACTIVITY_LOG_Q = None
_ACTIVITY_LOG_WORKER_STARTED = False
_ACTIVITY_LOG_WORKER_LOCK = threading.Lock()


def _activity_log_insert_standalone(action, visit_id, username, details, created_at):
    if DB_ENGINE == "postgres":
        from db import pool_getconn, pool_putconn

        conn = None
        try:
            conn = pool_getconn(timeout_s=1.5)
            conn.autocommit = False
            cur = PostgresDBWrapper(conn).cursor()
            cur.execute(
                """
                INSERT INTO activity_log (action, visit_id, username, details, created_at)
                VALUES (?,?,?,?,?)
                """,
                (action, visit_id, username, details, created_at),
            )
            conn.commit()
            return True
        finally:
            if conn is not None:
                try:
                    pool_putconn(conn)
                except Exception:
                    pass

    conn = None
    try:
        conn = sqlite3.connect(DATABASE, check_same_thread=False)
        conn.execute(
            """
            INSERT INTO activity_log (action, visit_id, username, details, created_at)
            VALUES (?,?,?,?,?)
            """,
            (action, visit_id, username, details, created_at),
        )
        conn.commit()
        return True
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _activity_log_worker_loop():
    while True:
        try:
            q = _ACTIVITY_LOG_Q
            if q is None:
                time.sleep(0.5)
                continue
            try:
                first = q.get(timeout=1.0)
            except Empty:
                continue
            batch = [first]
            try:
                while len(batch) < _ACTIVITY_LOG_WORKER_BATCH:
                    batch.append(q.get_nowait())
            except Empty:
                pass

            for entry in batch:
                try:
                    _activity_log_insert_standalone(*entry)
                except Exception as e:
                    _log_noncritical_exception(
                        f"activity_log async insert failed action={entry[0]!r} visit_id={entry[1]!r}",
                        e,
                    )
                finally:
                    try:
                        q.task_done()
                    except Exception:
                        pass
        except Exception:
            try:
                time.sleep(0.2)
            except Exception:
                pass


def _start_activity_log_worker_once():
    global _ACTIVITY_LOG_Q, _ACTIVITY_LOG_WORKER_STARTED
    if not _ACTIVITY_LOG_ASYNC:
        return
    with _ACTIVITY_LOG_WORKER_LOCK:
        if _ACTIVITY_LOG_WORKER_STARTED:
            return
        _ACTIVITY_LOG_Q = Queue(maxsize=_ACTIVITY_LOG_QUEUE_MAX)
        t = threading.Thread(target=_activity_log_worker_loop, name="EDDT-ActivityLogWorker", daemon=True)
        t.start()
        _ACTIVITY_LOG_WORKER_STARTED = True


def log_action(action, visit_id=None, details=None):
    """Append to activity_log with async queueing by default under load."""
    username = "UNKNOWN"
    try:
        username = session.get("username", "UNKNOWN")
    except Exception:
        username = "UNKNOWN"
    created_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    if _ACTIVITY_LOG_ASYNC:
        try:
            _start_activity_log_worker_once()
            if _ACTIVITY_LOG_Q is not None:
                _ACTIVITY_LOG_Q.put_nowait((action, visit_id, username, details, created_at))
                return
        except Full:
            pass
        except Exception:
            pass

    try:
        db = get_db()
        db.execute(
            """
            INSERT INTO activity_log (action, visit_id, username, details, created_at)
            VALUES (?,?,?,?,?)
            """,
            (action, visit_id, username, details, created_at),
        )
        db.commit()
    except Exception as e:
        try:
            _activity_log_insert_standalone(action, visit_id, username, details, created_at)
            return
        except Exception:
            _log_noncritical_exception(
                f"log_action failed action={action!r} visit_id={visit_id!r}",
                e,
            )


# ============================================================
# MRD Re-entry Tracking (Entered/Verified)
# ============================================================

# PERF 2026-04-19: Guard flag to prevent per-request DDL.
# The ALTER TABLE statements below take an AccessExclusiveLock which blocks
# all other sessions on the table. Without this flag, 1500-user load tests
# showed 11 170 calls of "ALTER TABLE mrd_reentry_marks ADD COLUMN note" in
# 40 minutes, producing ~35 000 lock waits in the PostgreSQL log.
_mrd_reentry_schema_ready = False


def ensure_mrd_reentry_schema():
    """Create/upgrade MRD re-entry tracking table.

    This table is used by MRD to mark each section/order as:
      - Entered (re-entered into the HIS)
      - Verified (double-checked)

    We store timestamps + staff display name for auditability.
    """
    global _mrd_reentry_schema_ready
    if _mrd_reentry_schema_ready:
        return True
    db = get_db()
    cur = db.cursor()

    try:
        if DB_ENGINE == "postgres":
            cur.execute("""
                CREATE TABLE IF NOT EXISTS mrd_reentry_marks (
                    id BIGSERIAL PRIMARY KEY,
                    visit_id TEXT NOT NULL,
                    entity_type TEXT NOT NULL,
                    entity_id TEXT NOT NULL,
                    entered_at TEXT,
                    entered_by TEXT,
                    verified_at TEXT,
                    verified_by TEXT,
                    note TEXT,
                    updated_at TEXT,
                    updated_by TEXT
                )
                """)
            # Unique (visit, type, id)
            try:
                cur.execute("""
                    CREATE UNIQUE INDEX IF NOT EXISTS idx_mrd_reentry_unique
                    ON mrd_reentry_marks(visit_id, entity_type, entity_id)
                    """)
            except Exception:
                pass
            try:
                cur.execute("""
                    CREATE INDEX IF NOT EXISTS idx_mrd_reentry_visit
                    ON mrd_reentry_marks(visit_id)
                    """)
            except Exception:
                pass

            # Backward-compat: add newly introduced columns if missing
            for col in ("note", "updated_at", "updated_by"):
                try:
                    cur.execute(
                        f"ALTER TABLE mrd_reentry_marks ADD COLUMN IF NOT EXISTS {col} TEXT"
                    )
                except Exception:
                    pass
        else:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS mrd_reentry_marks (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    visit_id TEXT NOT NULL,
                    entity_type TEXT NOT NULL,
                    entity_id TEXT NOT NULL,
                    entered_at TEXT,
                    entered_by TEXT,
                    verified_at TEXT,
                    verified_by TEXT,
                    note TEXT,
                    updated_at TEXT,
                    updated_by TEXT
                )
                """)
            try:
                cur.execute("""
                    CREATE UNIQUE INDEX IF NOT EXISTS idx_mrd_reentry_unique
                    ON mrd_reentry_marks(visit_id, entity_type, entity_id)
                    """)
            except Exception:
                pass
            try:
                cur.execute("""
                    CREATE INDEX IF NOT EXISTS idx_mrd_reentry_visit
                    ON mrd_reentry_marks(visit_id)
                    """)
            except Exception:
                pass

        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            _log_noncritical_exception(
                "Clinical orders page status rollback failed"
            )
        # Don't raise at startup
        return False

    # Schema successfully ensured: flip the guard so subsequent calls in this
    # process short-circuit (no per-request DDL under load).
    _mrd_reentry_schema_ready = True
    return True


def mrd_get_marks_for_visit(cur, visit_id: str):
    """Return marks as dict keyed by '<entity_type>:<entity_id>' for a visit."""
    visit_id = (visit_id or "").strip()
    if not visit_id:
        return {}

    try:
        ensure_mrd_reentry_schema()
    except Exception:
        pass

    marks = {}
    try:
        rows = cur.execute(
            """
            SELECT entity_type, entity_id,
                   entered_at, entered_by,
                   verified_at, verified_by,
                   note, updated_at, updated_by
            FROM mrd_reentry_marks
            WHERE visit_id=?
            """,
            (visit_id,),
        ).fetchall()
    except Exception:
        rows = []

    for r in rows or []:
        et = _safe_row_get(r, "entity_type", "") or ""
        eid = _safe_row_get(r, "entity_id", "") or ""
        key = f"{et}:{eid}"
        marks[key] = {
            "entity_type": et,
            "entity_id": eid,
            "entered_at": _safe_row_get(r, "entered_at", ""),
            "entered_by": _safe_row_get(r, "entered_by", ""),
            "verified_at": _safe_row_get(r, "verified_at", ""),
            "verified_by": _safe_row_get(r, "verified_by", ""),
            "note": _safe_row_get(r, "note", ""),
            "updated_at": _safe_row_get(r, "updated_at", ""),
            "updated_by": _safe_row_get(r, "updated_by", ""),
        }
    return marks


# ============================================================
# DB Initialization + Auto Upgrades
# ============================================================


def table_columns(table):
    """Return a set of column names for a table (SQLite or PostgreSQL).

    - SQLite: PRAGMA table_info(table)
    - PostgreSQL: information_schema.columns
    """
    table = (table or "").strip()
    if not table:
        return set()

    cur = get_db().cursor()

    if DB_ENGINE == "postgres":
        # Prefer current_schema(); fallback to public
        rows = []
        try:
            rows = cur.execute(
                """
                SELECT column_name
                FROM information_schema.columns
                WHERE table_schema = current_schema()
                  AND table_name = ?
                """,
                (table,),
            ).fetchall()
        except Exception:
            rows = []
        if not rows:
            try:
                rows = cur.execute(
                    """
                    SELECT column_name
                    FROM information_schema.columns
                    WHERE table_schema = 'public'
                      AND table_name = ?
                    """,
                    (table,),
                ).fetchall()
            except Exception:
                rows = []

        cols = set()
        for r in rows or []:
            try:
                cols.add(r["column_name"])
            except Exception:
                try:
                    cols.add(r[0])
                except Exception:
                    pass
        return cols

    # SQLite
    try:
        rows = cur.execute(f"PRAGMA table_info({table})").fetchall()
    except Exception:
        rows = []

    cols = set()
    for r in rows or []:
        # sqlite3.Row may be tuple-like or mapping depending on row_factory
        try:
            cols.add(r["name"])
        except Exception:
            try:
                cols.add(r[1])
            except Exception:
                pass
    return cols


# PERF 2026-04-19: Process-wide cache of (table, column) pairs we have
# successfully ensured. Prevents repeat ALTER TABLE ADD COLUMN IF NOT EXISTS
# under load (each one takes an AccessExclusiveLock on Postgres even when the
# column exists). See ensure_column() docstring for full context.
_ensured_columns_cache = set()


def ensure_column(table, col, col_type, strict: bool = False):
    """Add a column if missing, in a dual-engine safe way.

    PERF 2026-04-19:
    - Maintain a process-wide cache of (table, column) pairs we have already
      successfully ensured. Without this, every request path that calls
      ensure_column(...) issues an ALTER TABLE ... ADD COLUMN IF NOT EXISTS
      which takes an AccessExclusiveLock even when the column already exists,
      blocking every other session on that table.
    - 1500-user load-test log analysis showed > 34 000 such DDL statements in
      40 minutes, producing ~35 000 lock waits. The cache below eliminates
      repeat DDL for the lifetime of the process.
    """
    table = (table or "").strip()
    col = (col or "").strip()
    col_type = (col_type or "TEXT").strip()
    if not table or not col:
        # Provider notes (ED Note) table (idempotent)
        try:
            db = get_db()
            db.execute("""
                CREATE TABLE IF NOT EXISTS provider_notes (
                    id BIGSERIAL PRIMARY KEY,
                    visit_id TEXT UNIQUE NOT NULL,
                    note_text TEXT,
                    created_at TEXT NOT NULL,
                    created_by TEXT NOT NULL,
                    updated_at TEXT,
                    updated_by TEXT
                )
            """)
            db.commit()
        except Exception as e:
            _log_noncritical_exception(
                "ensure_column bootstrap provider_notes creation failed",
                e,
            )
            if strict:
                raise

        return

    db = get_db()

    # Fast path: if we've already ensured this (table, column) in this process,
    # skip the ALTER. This is the key fix for the 1500-user lock-contention
    # storm documented above.
    _cache_key = (table.lower(), col.lower())
    if _cache_key in _ensured_columns_cache:
        return

    if DB_ENGINE == "postgres":
        try:
            db.execute(f"ALTER TABLE {table} ADD COLUMN IF NOT EXISTS {col} {col_type}")
            db.commit()
            _ensured_columns_cache.add(_cache_key)
        except Exception as e:
            _log_noncritical_exception(
                f"ensure_column postgres failed table={table} col={col}",
                e,
            )
            try:
                db.rollback()
            except Exception as rb_exc:
                _log_noncritical_exception(
                    f"ensure_column postgres rollback failed table={table} col={col}",
                    rb_exc,
                )
            if strict:
                raise
        return

    # SQLite
    cols = table_columns(table)
    if col not in cols:
        try:
            db.execute(f"ALTER TABLE {table} ADD COLUMN {col} {col_type}")
            db.commit()
            _ensured_columns_cache.add(_cache_key)
        except Exception as e:
            _msg = str(e or '').lower()
            if 'duplicate column name' in _msg or 'already exists' in _msg:
                try:
                    db.rollback()
                except Exception:
                    pass
                _ensured_columns_cache.add(_cache_key)
                return
            _log_noncritical_exception(
                f"ensure_column sqlite failed table={table} col={col}",
                e,
            )
            try:
                db.rollback()
            except Exception as rb_exc:
                _log_noncritical_exception(
                    f"ensure_column sqlite rollback failed table={table} col={col}",
                    rb_exc,
                )
            if strict:
                raise
    else:
        # Column already present — remember so we don't re-check on every call.
        _ensured_columns_cache.add(_cache_key)


# ------------------------------------------------------------
# Ensure default Orders Items exist (PostgreSQL + fresh installs)
# ------------------------------------------------------------


def seed_default_catalogs_if_empty():
    """Ensure default items exist in Orders Items tables.

    Previous behavior only seeded defaults when a table had *zero* active rows.
    That meant new defaults (e.g., additional Radiology types) would NOT appear
    on existing installs.

    New behavior:
    - Insert missing defaults (do NOT overwrite existing/custom items).
    - Do NOT reactivate items that were manually disabled.
    - Append new defaults after the current max sort_order.
    """
    try:
        db = get_db()
        cur = db.cursor()
    except Exception:
        return

    tables = [
        ("items_radiology", DEFAULT_RAD_ITEMS),
        ("items_labs", DEFAULT_LAB_ITEMS),
        ("items_medications", DEFAULT_MED_ITEMS),
        ("items_home_meds", DEFAULT_HOME_MED_ITEMS),
    ]

    for table, items in tables:
        try:
            rows = cur.execute(f"SELECT name FROM {table}").fetchall()
            existing = set()
            for r in rows or []:
                try:
                    name = r[0] if not isinstance(r, dict) else r.get("name")
                except Exception:
                    name = None
                name = (name or "").strip()
                if name:
                    existing.add(name.lower())
        except Exception:
            continue

        # Max sort_order (append at the end); safe if column doesn't exist
        max_sort = 0
        try:
            r = cur.execute(f"SELECT MAX(sort_order) FROM {table}").fetchone()
            if r is not None:
                v = (
                    r[0]
                    if not isinstance(r, dict)
                    else (list(r.values())[0] if r else None)
                )
                if v is not None:
                    max_sort = int(v)
        except Exception:
            max_sort = 0

        for name in items or []:
            name = (name or "").strip()
            if not name:
                continue
            if name.lower() in existing:
                continue
            max_sort += 1
            try:
                if DB_ENGINE == "postgres":
                    cur.execute(
                        f"INSERT INTO {table} (name, is_active, sort_order) VALUES (?,?,?) "
                        "ON CONFLICT (name) DO NOTHING",
                        (name, 1, max_sort),
                    )
                else:
                    cur.execute(
                        f"INSERT OR IGNORE INTO {table} (name, is_active, sort_order) VALUES (?,?,?)",
                        (name, 1, max_sort),
                    )
                existing.add(name.lower())
            except Exception:
                continue

    try:
        db.commit()
    except Exception:
        pass


