_daily_counters_schema_ready = False


def ensure_daily_counters_schema():
    """Create/register the lightweight per-day counters table once per process."""
    global _daily_counters_schema_ready
    if _daily_counters_schema_ready:
        return
    db = get_db()
    cur = db.cursor()
    try:
        if DB_ENGINE == "postgres":
            cur.execute("""
                CREATE TABLE IF NOT EXISTS daily_counters (
                    counter_name TEXT NOT NULL,
                    counter_date TEXT NOT NULL,
                    last_value BIGINT NOT NULL DEFAULT 0,
                    PRIMARY KEY (counter_name, counter_date)
                )
            """)
        else:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS daily_counters (
                    counter_name TEXT NOT NULL,
                    counter_date TEXT NOT NULL,
                    last_value INTEGER NOT NULL DEFAULT 0,
                    PRIMARY KEY (counter_name, counter_date)
                )
            """)
        try:
            db.commit()
        except Exception:
            pass
        _daily_counters_schema_ready = True
    except Exception:
        _daily_counters_schema_ready = False
        try:
            db.rollback()
        except Exception:
            pass
        raise


def _next_daily_counter(counter_name: str, counter_date: str | None = None) -> int:
    """Atomically allocate the next counter value for a specific day.

    Important under high load:
    - PostgreSQL allocations use a short dedicated transaction, committed immediately.
    - This avoids holding the daily_counters row lock until the *caller* commits,
      which previously serialized /register POST requests behind file I/O + visit insert.
    - Gaps remain acceptable if a later business transaction rolls back.
    """
    ensure_daily_counters_schema()
    day_key = (counter_date or datetime.now().strftime("%Y-%m-%d")).strip()
    name = (counter_name or "").strip()
    if not name:
        raise ValueError("counter_name is required")

    if DB_ENGINE == "postgres":
        from db import pool_getconn, pool_putconn

        conn = None
        try:
            conn = pool_getconn(timeout_s=1.5)
            conn.autocommit = False
            cur = PostgresDBWrapper(conn).cursor()
            cur.execute(
                """
                INSERT INTO daily_counters (counter_name, counter_date, last_value)
                VALUES (?, ?, 0)
                ON CONFLICT (counter_name, counter_date) DO NOTHING
                """,
                (name, day_key),
            )
            cur.execute(
                """
                UPDATE daily_counters
                   SET last_value = last_value + 1
                 WHERE counter_name=? AND counter_date=?
                RETURNING last_value
                """,
                (name, day_key),
            )
            row = cur.fetchone()
            conn.commit()
            try:
                return int(row["last_value"])
            except Exception:
                return int(row[0])
        except Exception:
            if conn is not None:
                try:
                    conn.rollback()
                except Exception:
                    pass
            raise
        finally:
            if conn is not None:
                try:
                    pool_putconn(conn)
                except Exception:
                    pass

    db = get_db()
    cur = db.cursor()
    try:
        cur.execute(
            """
            INSERT OR IGNORE INTO daily_counters (counter_name, counter_date, last_value)
            VALUES (?, ?, 0)
            """,
            (name, day_key),
        )
        cur.execute(
            """
            UPDATE daily_counters
               SET last_value = last_value + 1
             WHERE counter_name=? AND counter_date=?
            """,
            (name, day_key),
        )
        row = cur.execute(
            "SELECT last_value FROM daily_counters WHERE counter_name=? AND counter_date=?",
            (name, day_key),
        ).fetchone()
        try:
            return int(row["last_value"])
        except Exception:
            return int(row[0])
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass
        raise


def _next_daily_counter_pg_cursor(cur, counter_name: str, counter_date: str) -> int:
    day_key = (counter_date or datetime.now().strftime("%Y-%m-%d")).strip()
    name = (counter_name or "").strip()
    if not name:
        raise ValueError("counter_name is required")
    cur.execute(
        """
        INSERT INTO daily_counters (counter_name, counter_date, last_value)
        VALUES (?, ?, 0)
        ON CONFLICT (counter_name, counter_date) DO NOTHING
        """,
        (name, day_key),
    )
    cur.execute(
        """
        UPDATE daily_counters
           SET last_value = last_value + 1
         WHERE counter_name=? AND counter_date=?
        RETURNING last_value
        """,
        (name, day_key),
    )
    row = cur.fetchone()
    try:
        return int(row["last_value"])
    except Exception:
        return int(row[0])


def allocate_visit_identifiers():
    """Allocate visit_id + queue_no with minimal DB contention.

    PostgreSQL uses one short-lived dedicated checkout/transaction for BOTH counters,
    so /register consumes one transient allocator connection instead of two.
    """
    ensure_daily_counters_schema()
    today = datetime.now().strftime("%Y%m%d")
    day_key = datetime.now().strftime("%Y-%m-%d")

    if DB_ENGINE == "postgres":
        from db import pool_getconn, pool_putconn

        conn = None
        try:
            conn = pool_getconn(timeout_s=1.5)
            conn.autocommit = False
            cur = PostgresDBWrapper(conn).cursor()
            visit_num = _next_daily_counter_pg_cursor(cur, "visit_id", day_key)
            queue_no = _next_daily_counter_pg_cursor(cur, "queue_no", day_key)
            conn.commit()
            return f"{today}{int(visit_num):05d}", int(queue_no)
        except Exception:
            if conn is not None:
                try:
                    conn.rollback()
                except Exception:
                    pass
            raise
        finally:
            if conn is not None:
                try:
                    pool_putconn(conn)
                except Exception:
                    pass

    visit_num = _next_daily_counter("visit_id", day_key)
    queue_no = _next_daily_counter("queue_no", day_key)
    return f"{today}{int(visit_num):05d}", int(queue_no)


def generate_visit_id():
    return allocate_visit_identifiers()[0]


def generate_queue_no():
    return allocate_visit_identifiers()[1]


_LOGIN_CACHE = {"expires_at": 0.0, "users": {}}
_LOGIN_CACHE_LOCK = threading.Lock()


def _login_cache_ttl_seconds() -> float:
    try:
        return max(5.0, float(APP_CONFIG.get("LOGIN_USER_CACHE_SECONDS", 60.0) or 60.0))
    except Exception:
        return 60.0


def _fetch_active_login_user(username: str):
    uname = (username or "").strip()
    if not uname:
        return None

    now_ts = time.time()
    with _LOGIN_CACHE_LOCK:
        users = _LOGIN_CACHE.get("users") or {}
        if now_ts < float(_LOGIN_CACHE.get("expires_at") or 0) and uname in users:
            return users.get(uname)

    row_data = None
    try:
        db = get_db()
        cur = db.cursor()
        row = cur.execute(
            """
            SELECT id, username, role, password_hash, full_name, gd_number
              FROM users
             WHERE username=? AND is_active=1
            """,
            (uname,),
        ).fetchone()
        if row:
            try:
                row_data = dict(row)
            except Exception:
                row_data = {
                    "id": row[0],
                    "username": row[1],
                    "role": row[2],
                    "password_hash": row[3],
                    "full_name": row[4] if len(row) > 4 else "",
                    "gd_number": row[5] if len(row) > 5 else "",
                }
    except Exception:
        row_data = None

    with _LOGIN_CACHE_LOCK:
        users = dict(_LOGIN_CACHE.get("users") or {})
        if row_data:
            users[uname] = row_data
        else:
            users.pop(uname, None)
        _LOGIN_CACHE["users"] = users
        _LOGIN_CACHE["expires_at"] = time.time() + _login_cache_ttl_seconds()
    return row_data


def _cleanup_stale_visit_locks_after_login(username: str) -> None:
    uname = (username or "").strip()
    if not uname:
        return
    try:
        from db import pool_getconn, pool_putconn
    except Exception:
        return

    conn = None
    try:
        ensure_visit_lock_schema()
        conn = pool_getconn(timeout_s=0.25)
        conn.autocommit = False
        cur = PostgresDBWrapper(conn).cursor()
        cutoff = int(time.time()) - int(VISIT_LOCK_WINDOW_SECONDS)
        cur.execute(
            "DELETE FROM visit_locks_sessions WHERE username=? AND last_seen_ts < ?",
            (uname, cutoff),
        )
        conn.commit()
    except Exception:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
    finally:
        if conn is not None:
            try:
                pool_putconn(conn)
            except Exception:
                pass


