_ROLE_ALIASES = {
    "doctors": "doctor",
    "physicians": "doctor",
    "physician": "doctor",
    "dr": "doctor",
    "receptionist": "reception",
    "nurse supervisor": "nurse_supervisor",
    "nursing supervisor": "nurse_supervisor",
    "nurse_supervisor": "nurse_supervisor",
    "ip billing": "inpatient_billing",
    "ip_billing": "inpatient_billing",
    "inpatient billing": "inpatient_billing",
    "billing": "inpatient_billing",
    "clinic manager": "clinic_manager",
    "clinic_manager": "clinic_manager",
    "pharmacy": "pharmacist",
    "pharmacist": "pharmacist",
    "rad": "radiology",
}


def normalize_role_key(role: str) -> str:
    raw = (role or "").strip().lower().replace("-", " ").replace("/", " ")
    raw = re.sub(r"\s+", " ", raw).strip()
    if not raw:
        return ""
    return _ROLE_ALIASES.get(raw, raw.replace(" ", "_"))


def login_redirect_for_role(role):
    """Redirect each role to its primary landing page.

    Uses normalized role aliases so old labels like "Doctors", "Pharmacy",
    or "IP Billing" still land on the correct board.
    """
    r = normalize_role_key(role)
    try:
        if r == "reception":
            return redirect(url_for("register_patient"))
        if r == "doctor":
            return redirect(url_for("clinic_board"))
        if r == "inpatient_billing":
            return redirect(url_for("clinic_board", clinic="IPADM"))
        if r == "lab":
            return redirect(url_for("lab_board"))
        if r == "radiology":
            return redirect(url_for("radiology_board"))
        if r == "mrd":
            return redirect(url_for("mrd_reentry_worklist"))
        if r in ("nurse", "nurse_supervisor"):
            return redirect(url_for("search_patients"))
        if r == "pharmacist":
            return redirect(url_for("pharmacy_dashboard"))
        return redirect(url_for("ed_board"))
    except Exception:
        return redirect(url_for("ed_board"))

@app.before_request
def _normalize_session_role_before_guards():
    try:
        cur = session.get("role")
        norm = normalize_role_key(cur)
        if norm and norm != cur:
            session["role"] = norm
    except Exception:
        pass


def login_required(f):
    @wraps(f)
    def wrap(*args, **kwargs):
        if "user_id" not in session:
            return redirect(url_for("login"))
        return f(*args, **kwargs)

    return wrap


def role_required(*roles):
    """Role guard with RBAC-permission override.

    Legacy code uses role_required() extensively. Starting from the RBAC feature
    (Admin → User Permissions), access is also driven by per-role permission keys.

    Behavior:
    - If user's role is explicitly allowed → allow.
    - Else, if the current endpoint is mapped in ENDPOINT_PERMISSION_MAP and the
      user has that permission key → allow (admin-configurable).
    - Otherwise → deny.
    """

    def decorator(f):
        @wraps(f)
        def wrap(*args, **kwargs):
            cur_role = session.get("role")
            cur_l = normalize_role_key(cur_role)
            allowed = {normalize_role_key(x) or (x or "").strip().lower() for x in roles}

            # Legacy allow-list (case-insensitive + exact DB casing)
            if cur_l in allowed or cur_role in roles:
                return f(*args, **kwargs)

            # RBAC permission override (so admin can grant MRD / other roles)
            try:
                ep = (request.endpoint or "").split(".")[-1]
                perm_key = (
                    ENDPOINT_PERMISSION_MAP.get(ep)
                    if "ENDPOINT_PERMISSION_MAP" in globals()
                    else None
                )
                if perm_key and "has_perm" in globals() and has_perm(perm_key):
                    return f(*args, **kwargs)
            except Exception:
                pass

            flash("You do not have permission for this page.", "danger")
            try:
                return login_redirect_for_role(cur_role)
            except Exception:
                return redirect(url_for("ed_board"))

        return wrap

    return decorator


