ALL_PERMISSION_KEYS = set()
for _grp in PERMISSION_GROUPS.values():
    for _k, _lbl in _grp:
        ALL_PERMISSION_KEYS.add(_k)


def _default_permissions_for_role(role: str):
    r = normalize_role_key(role)

    # Base default (common pages)
    # NOTE: We include Patient Details to keep compatibility with older versions
    # where patient details was reachable from ED Board for most roles.
    base = {"core_ed_board", "core_patient_details", "core_search", "core_live_chat"}

    if r == "doctor":
        return base | {
            "core_triage",
            "core_clinical_orders",
            "core_depart_workflow",
            "core_reports",
            "core_ip_admission_form",
            "boards_lab_board",
            "boards_radiology_board",
            "boards_clinic_board",
        }

    if r == "nurse":
        return base | {
            "core_triage",
            "core_clinical_orders",
            "core_depart_workflow",
            "boards_lab_board",
            "boards_radiology_board",
            "boards_clinic_board",
        }

    if r == "nurse_supervisor":
        return base | {
            "core_triage",
            "core_clinical_orders",
            "core_depart_workflow",
            "boards_lab_board",
            "boards_radiology_board",
            "boards_clinic_board",
            "boards_code_orange_activate",
        }

    if r == "lab":
        return base | {"boards_lab_board"}

    if r == "pharmacist":
        # Pharmacy staff: do not grant ED Board by default (load + RBAC isolation).
        return (base - {"core_ed_board"}) | {"boards_pharmacy_dashboard"}

    if r == "radiology":
        return base | {"boards_radiology_board"}

    if r == "mrd":
        # Medical Records Department: patient files + reports + re-entry tracking.
        return base | {"core_reports", "mrd_reentry_mark"}

    if r == "clinic_manager":
        return base | {
            "boards_clinic_board",
            "core_reports",
        }

    if r in ("reception", "inpatient_billing"):
        perms = set(base) | {"boards_register", "boards_clinic_board"}
        if r == "inpatient_billing":
            perms |= {"core_reports", "core_ip_admission_form"}
        return perms

    if r == "admin":
        return set(ALL_PERMISSION_KEYS) | {
            "admin_control_panel",
            "admin_user_permissions",
        }

    return set(base)

def init_role_permissions_table():
    """Create role_permissions table if it doesn't exist (SQLite/PostgreSQL)."""
    db = get_db()
    cur = db.cursor()
    try:
        cur.execute("""
            CREATE TABLE IF NOT EXISTS role_permissions (
                role TEXT PRIMARY KEY,
                permissions_json TEXT NOT NULL,
                updated_at TEXT,
                updated_by TEXT
            )
            """)
        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass


def _fetch_one_val(row, key, idx=0):
    try:
        if row is None:
            return None
        if hasattr(row, "keys") and key in row.keys():
            return row[key]
    except Exception:
        pass
    try:
        return row[idx]
    except Exception:
        return None


def get_role_permissions(role: str):
    role = normalize_role_key(role) or (role or "").strip()
    if not role:
        return set()

    # Per-request cache
    try:
        if (
            hasattr(g, "_role_perms_cache")
            and g._role_perms_cache.get(role) is not None
        ):
            return set(g._role_perms_cache.get(role))
    except Exception:
        pass

    # Ensure table exists
    try:
        init_role_permissions_table()
    except Exception:
        pass

    perms = set()
    try:
        cur = get_db().cursor()
        row = cur.execute(
            "SELECT permissions_json FROM role_permissions WHERE role=?",
            (role,),
        ).fetchone()
        if row:
            raw = _fetch_one_val(row, "permissions_json", 0) or "[]"
            try:
                perms = set(json.loads(raw) or [])
            except Exception:
                perms = set()
        else:
            perms = _default_permissions_for_role(role)
    except Exception:
        perms = _default_permissions_for_role(role)

    perms = {p for p in perms if p in ALL_PERMISSION_KEYS}
    if role == "admin":
        perms |= set(ALL_PERMISSION_KEYS) | {"admin_control_panel", "admin_user_permissions"}

    # Activate Code Orange is intentionally limited to Admin and Nurse Supervisor only.
    if role not in ("admin", "nurse_supervisor"):
        perms.discard("boards_code_orange_activate")

    try:
        if not hasattr(g, "_role_perms_cache"):
            g._role_perms_cache = {}
        g._role_perms_cache[role] = set(perms)
    except Exception:
        pass

    return perms

def save_role_permissions(role: str, perms, actor: str = ""):
    role = normalize_role_key(role) or (role or "").strip()
    if not role:
        return False

    actor = (actor or "").strip()
    perms_set = {p for p in (perms or []) if p in ALL_PERMISSION_KEYS}

    # Safety: prevent locking out admins entirely (keep panel + permissions)
    if role == "admin":
        perms_set |= {"admin_control_panel", "admin_user_permissions"}

    # Activate Code Orange may only be assigned to Admin or Nurse Supervisor.
    if role not in ("admin", "nurse_supervisor"):
        perms_set.discard("boards_code_orange_activate")

    try:
        init_role_permissions_table()
    except Exception:
        pass

    db = get_db()
    cur = db.cursor()
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    payload = json.dumps(sorted(perms_set))

    try:
        cur.execute(
            "UPDATE role_permissions SET permissions_json=?, updated_at=?, updated_by=? WHERE role=?",
            (payload, now, actor, role),
        )
        if getattr(cur, "rowcount", 0) == 0:
            cur.execute(
                "INSERT INTO role_permissions (role, permissions_json, updated_at, updated_by) VALUES (?,?,?,?)",
                (role, payload, now, actor),
            )
        db.commit()

        try:
            if hasattr(g, "_role_perms_cache"):
                g._role_perms_cache[role] = set(perms_set)
        except Exception:
            pass

        return True
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass
        return False

def seed_role_permissions_defaults():
    """Insert default permissions rows for known roles (if missing)."""
    try:
        init_role_permissions_table()
    except Exception:
        return

    db = get_db()
    cur = db.cursor()

    roles = set()
    try:
        rows = cur.execute("SELECT DISTINCT role FROM users").fetchall()
        for r in rows or []:
            rv = _fetch_one_val(r, "role", 0)
            if rv:
                roles.add(normalize_role_key(str(rv)) or str(rv))
    except Exception:
        pass

    # Ensure common roles exist even if no user yet
    roles |= {
        "admin",
        "doctor",
        "call_center_agent",
        "nurse",
        "nurse_supervisor",
        "lab",
        "pharmacist",
        "radiology",
        "reception",
        "clinic_manager",
        "inpatient_billing",
        "mrd",
    }

    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    changed = 0
    for role in sorted([r for r in roles if r]):
        try:
            ex = cur.execute(
                "SELECT role FROM role_permissions WHERE role=?", (role,)
            ).fetchone()
        except Exception:
            ex = None
        if ex:
            continue

        perms = _default_permissions_for_role(role)
        try:
            cur.execute(
                "INSERT INTO role_permissions (role, permissions_json, updated_at, updated_by) VALUES (?,?,?,?)",
                (role, json.dumps(sorted(perms)), now, "system"),
            )
            changed += 1
        except Exception:
            pass

    try:
        if changed:
            db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass


def migrate_role_permissions_add_new_keys():
    """Backfill newly introduced permission keys into existing role_permissions rows.

    This keeps older deployments working after adding new permission keys and gating more endpoints.
    We only ADD permissions (never remove), so it is safe and admins can still adjust later.
    """
    try:
        init_role_permissions_table()
    except Exception:
        return

    db = get_db()
    cur = db.cursor()

    try:
        rows = cur.execute(
            "SELECT role, permissions_json FROM role_permissions"
        ).fetchall()
    except Exception:
        return

    changed = 0
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    for row in rows or []:
        role = _fetch_one_val(row, "role", 0) or ""
        raw = _fetch_one_val(row, "permissions_json", 1) or "[]"

        try:
            perms = set(json.loads(raw) or [])
        except Exception:
            perms = set()

        before = set(perms)
        r = normalize_role_key(role)

        # If the role had ED Board access, grant the newer workflow screens by default.
        # Do not force core_clinical_orders here: User Permissions must be able
        # to save Clinical Orders as unchecked without migration re-adding it.
        if "core_ed_board" in perms:
            for k in (
                "core_patient_details",
                "core_triage",
                "core_depart_workflow",
            ):
                if k in ALL_PERMISSION_KEYS:
                    perms.add(k)

        # Clinic Manager: clinic board and reports by default
        if r == "clinic_manager":
            for k in ("boards_clinic_board", "core_reports"):
                if k in ALL_PERMISSION_KEYS:
                    perms.add(k)

        # Clinic board / IP admission defaults for admission staff
        if r in ("reception", "inpatient_billing"):
            if "boards_clinic_board" in ALL_PERMISSION_KEYS:
                perms.add("boards_clinic_board")
        if r == "inpatient_billing":
            for k in ("core_ip_admission_form", "core_reports"):
                if k in ALL_PERMISSION_KEYS:
                    perms.add(k)

        # Nurse Supervisor: nurse-level access plus Code Orange activation by default.
        # Clinical Orders stays controlled by the saved per-role permission.
        if r == "nurse_supervisor":
            for k in (
                "core_triage",
                "core_depart_workflow",
                "boards_lab_board",
                "boards_radiology_board",
                "boards_clinic_board",
                "boards_code_orange_activate",
            ):
                if k in ALL_PERMISSION_KEYS:
                    perms.add(k)

        # MRD: allow re-entry tracking by default
        if r == "mrd":
            for k in ("core_reports", "mrd_reentry_mark"):
                if k in ALL_PERMISSION_KEYS:
                    perms.add(k)

        # Pharmacist: home medication dispense dashboard; avoid ED Board stampede
        if r == "pharmacist":
            for k in ("boards_pharmacy_dashboard",):
                if k in ALL_PERMISSION_KEYS:
                    perms.add(k)
            perms.discard("core_ed_board")

        # Admin always gets everything (and cannot lose panel + permissions page)
        if r == "admin":
            perms = set(ALL_PERMISSION_KEYS) | {
                "admin_control_panel",
                "admin_user_permissions",
            }

        # Activate Code Orange is restricted to Admin and Nurse Supervisor only.
        if r not in ("admin", "nurse_supervisor"):
            perms.discard("boards_code_orange_activate")

        # Remove unknown keys
        perms = {p for p in perms if p in ALL_PERMISSION_KEYS}

        if perms != before:
            try:
                cur.execute(
                    "UPDATE role_permissions SET permissions_json=?, updated_at=?, updated_by=? WHERE role=?",
                    (json.dumps(sorted(perms)), ts, "system_migrate", role),
                )
                changed += 1
            except Exception:
                pass

    if changed:
        try:
            db.commit()
        except Exception:
            try:
                db.rollback()
            except Exception:
                pass


def has_perm(key: str) -> bool:
    """Template/helper: check if current user's role has permission key."""
    k = (key or "").strip()
    if not k:
        return False
    role = session.get("role")
    if not role:
        return False
    try:
        perms = get_role_permissions(role)
        return k in perms
    except Exception:
        return False


