# ============================================================
# Backup (manual + scheduler)
# ============================================================


def _parse_pg_dsn(dsn: str) -> dict:
    """Parse a simple key=value PG DSN string into a dict.

    Example:
      "dbname=triage_ed user=triage_ed password=triage_ed host=127.0.0.1 port=5432"
    """
    out = {}
    try:
        for part in (dsn or "").strip().split():
            if "=" not in part:
                continue
            k, v = part.split("=", 1)
            k = (k or "").strip().lower()
            v = (v or "").strip().strip('"').strip("'")
            if k:
                out[k] = v
    except Exception:
        return out
    return out


def _find_pg_tool(tool_name: str):
    """Locate PostgreSQL CLI tools (pg_dump/pg_restore/psql).

    - First tries PATH via shutil.which
    - On Windows, also searches common PostgreSQL install directories.
    """
    try:
        p = shutil.which(tool_name)
        if p:
            return p
    except Exception:
        p = None

    if os.name == "nt":
        exe = tool_name + ".exe"
        roots = []
        try:
            roots.append(os.environ.get("ProgramFiles", r"C:\\Program Files"))
        except Exception:
            pass
        try:
            roots.append(
                os.environ.get("ProgramFiles(x86)", r"C:\\Program Files (x86)")
            )
        except Exception:
            pass
        patterns = []
        for r0 in [r for r in roots if r]:
            patterns.append(os.path.join(r0, "PostgreSQL", "*", "bin", exe))

        hits = []
        for pat in patterns:
            try:
                hits.extend(glob.glob(pat))
            except Exception:
                pass
        # Prefer newest (folder names often include version)
        try:
            hits.sort(reverse=True)
        except Exception:
            pass
        return hits[0] if hits else None

    return None


def _pg_env_and_dbname():
    info = _parse_pg_dsn(PG_DSN)
    env = os.environ.copy()
    try:
        if info.get("host"):
            env["PGHOST"] = info["host"]
        if info.get("port"):
            env["PGPORT"] = str(info["port"])
        if info.get("user"):
            env["PGUSER"] = info["user"]
        if info.get("password"):
            env["PGPASSWORD"] = info["password"]
        if info.get("dbname"):
            env["PGDATABASE"] = info["dbname"]
        env.setdefault("PGCLIENTENCODING", "UTF8")
    except Exception:
        pass
    dbname = info.get("dbname") or env.get("PGDATABASE") or ""
    return env, dbname




def postgres_reset_public_schema():
    """Reset the target PostgreSQL public schema before restore.

    Why: pg_restore --clean may fail when the live DB has dependency chains
    that differ from the dump, for example patient_lab_results FKs depending
    on visits indexes/constraints. Dropping the entire schema with CASCADE
    removes dependent objects in one safe operation, then pg_restore recreates
    the dump from a clean schema.

    Returns: (ok: bool, message: str)
    """
    if (DB_ENGINE or "").lower() != "postgres":
        return True, "not postgres"

    reset_sql = """
DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;
GRANT ALL ON SCHEMA public TO CURRENT_USER;
GRANT ALL ON SCHEMA public TO public;
""".strip()

    # Prefer psycopg2 so restore still works if psql is not in PATH.
    if psycopg2 is not None:
        try:
            conn = psycopg2.connect(PG_DSN)
            conn.autocommit = True
            cur = conn.cursor()
            cur.execute(reset_sql)
            try:
                cur.close()
            except Exception:
                pass
            try:
                conn.close()
            except Exception:
                pass
            return True, "public schema reset with CASCADE"
        except Exception as e:
            # Fall back to psql below; keep the original error for diagnostics.
            psycopg_err = str(e)
    else:
        psycopg_err = "psycopg2 not installed"

    tool = _find_pg_tool("psql")
    if not tool:
        return False, "Could not reset schema: psycopg2 failed/unavailable and psql not found. " + psycopg_err

    env, dbname = _pg_env_and_dbname()
    if not dbname:
        return False, "PG_DSN is missing dbname."

    try:
        r = subprocess.run(
            [tool, "-d", dbname, "-v", "ON_ERROR_STOP=1", "-c", reset_sql],
            env=env,
            capture_output=True,
            text=True,
        )
        if r.returncode != 0:
            return False, (r.stderr or r.stdout or "schema reset failed").strip()[:1200]
        return True, "public schema reset with CASCADE"
    except Exception as e:
        return False, str(e)


def postgres_backup_create(fmt: str = "dump", dst_path: str = None):
    """Create a PostgreSQL backup using pg_dump.

    fmt:
      - "dump" (custom format, recommended)
      - "sql"  (plain SQL)

    Returns: (path or None, error_message or None)
    """
    fmt = (fmt or "dump").strip().lower()
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    if not dst_path:
        ext = "sql" if fmt == "sql" else "dump"
        dst_path = os.path.join(BACKUP_FOLDER, f"triage_ed_{ts}.{ext}")

    tool = _find_pg_tool("pg_dump")
    if not tool:
        return (
            None,
            "pg_dump not found. Install PostgreSQL client tools or add them to PATH.",
        )

    env, dbname = _pg_env_and_dbname()
    if not dbname:
        return None, "PG_DSN is missing dbname."

    cmd = [tool, "-d", dbname, "--no-owner", "--no-privileges", "-f", dst_path]
    # Format
    if fmt == "sql":
        cmd += ["-F", "p"]
    else:
        cmd += ["-F", "c"]

    try:
        r = subprocess.run(cmd, env=env, capture_output=True, text=True)
        if r.returncode != 0:
            err = (r.stderr or r.stdout or "pg_dump failed").strip()
            return None, err[:800]
        return dst_path, None
    except Exception as e:
        return None, str(e)


def postgres_restore_from_file(src_path: str):
    """Restore PostgreSQL from a backup file (.dump/.sql).

    The old implementation used pg_restore --clean --if-exists against the
    existing live schema. That can fail when current schema constraints depend
    on each other differently than the dump order, e.g. patient_lab_results
    FKs depending on visits indexes. The safe restore path is:
      1) reset public schema with DROP SCHEMA public CASCADE;
      2) restore into the empty schema without --clean;
      3) use a single transaction so restore failures do not leave half data.

    Returns: (ok: bool, error_message: str|None)
    """
    ext = os.path.splitext(src_path or "")[1].lower()
    env, dbname = _pg_env_and_dbname()
    if not dbname:
        return False, "PG_DSN is missing dbname."

    try:
        ok_reset, reset_msg = postgres_reset_public_schema()
        if not ok_reset:
            return False, reset_msg

        if ext == ".sql":
            tool = _find_pg_tool("psql")
            if not tool:
                return (
                    False,
                    "psql not found. Install PostgreSQL client tools or add them to PATH.",
                )
            cmd = [
                tool,
                "-d",
                dbname,
                "-v",
                "ON_ERROR_STOP=1",
                "--single-transaction",
                "-f",
                src_path,
            ]
        else:
            tool = _find_pg_tool("pg_restore")
            if not tool:
                return (
                    False,
                    "pg_restore not found. Install PostgreSQL client tools or add them to PATH.",
                )
            cmd = [
                tool,
                "-d",
                dbname,
                "--single-transaction",
                "--no-owner",
                "--no-privileges",
                src_path,
            ]

        r = subprocess.run(cmd, env=env, capture_output=True, text=True)
        if r.returncode != 0:
            err = (r.stderr or r.stdout or "restore failed").strip()
            return False, (reset_msg + "\n" + err)[:2000]
        return True, None
    except Exception as e:
        return False, str(e)


# ============================================================
# Full Patient Backup Package (database + uploaded files)
# ============================================================
FULL_BACKUP_KIND = "horizon_full_patient_backup"
FULL_BACKUP_VERSION = 1
FULL_BACKUP_MANIFEST = "manifest.json"
FULL_BACKUP_DB_DIR = "database"
FULL_BACKUP_UPLOADS_DIR = "uploads"


def _backup_allowed_exts_for_engine(engine=None, include_package=True):
    engine = (engine or DB_ENGINE or "").lower()
    if engine == "postgres":
        allowed = {".dump", ".sql", ".backup", ".enc"}
    else:
        allowed = {".db", ".enc"}
    if include_package:
        allowed.add(".zip")
    return allowed


def _sha256_file(path: str) -> str:
    import hashlib as _hashlib

    h = _hashlib.sha256()
    with open(path, "rb") as fp:
        for chunk in iter(lambda: fp.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def _dir_stats(path: str):
    count = 0
    total = 0
    try:
        if not path or not os.path.isdir(path):
            return count, total
        for root, _dirs, files in os.walk(path):
            for name in files:
                fpath = os.path.join(root, name)
                try:
                    st = os.stat(fpath)
                    count += 1
                    total += int(st.st_size or 0)
                except Exception:
                    pass
    except Exception:
        pass
    return count, total


def _iter_upload_files_for_backup():
    """Yield upload files from all known upload roots, de-duplicated by archive path.

    The app stores uploaded filenames in the database and serves from the configured
    uploads folder plus a few legacy locations. Backing up all known locations avoids
    losing older patient attachments after a restore or server move.
    """
    seen_arc = set()
    seen_real = set()
    for base in _upload_search_paths():
        try:
            if not base or not os.path.isdir(base):
                continue
            base_abs = os.path.abspath(base)
            for root, dirs, files in os.walk(base_abs):
                dirs[:] = [d for d in dirs if d not in {"__pycache__", ".git", ".svn"}]
                for fname in files:
                    src = os.path.join(root, fname)
                    try:
                        real = os.path.realpath(src)
                        if real in seen_real:
                            continue
                        rel = os.path.relpath(src, base_abs)
                        if rel.startswith(".."):
                            continue
                        rel = rel.replace("\\", "/").lstrip("/")
                        parts = [x for x in rel.split("/") if x]
                        if not parts or any(x in (".", "..") for x in parts):
                            continue
                        arc_rel = "/".join(parts)
                        # First upload root wins. This matches resolve_upload_path() priority.
                        if arc_rel.lower() in seen_arc:
                            continue
                        seen_arc.add(arc_rel.lower())
                        seen_real.add(real)
                        yield src, arc_rel
                    except Exception:
                        continue
        except Exception:
            continue


def _create_full_patient_backup(dst_path: str = None, fmt: str = "dump", encrypt: bool = True):
    """Create one portable backup package containing database + uploads.

    Returns: (path or None, error_message or None)
    """
    import tempfile as _tempfile
    import zipfile as _zipfile

    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    if not dst_path:
        dst_path = os.path.join(BACKUP_FOLDER, f"triage_ed_full_{ts}.zip")
    if not str(dst_path).lower().endswith(".zip"):
        dst_path = str(dst_path) + ".zip"

    tmp_root = None
    tmp_zip = dst_path + ".tmp"
    db_tmp = None
    try:
        os.makedirs(BACKUP_FOLDER, exist_ok=True)
        tmp_root = _tempfile.mkdtemp(prefix="full_backup_", dir=BACKUP_FOLDER)

        engine = (DB_ENGINE or "").lower()
        if engine == "postgres":
            db_arc_name = "triage_ed.dump" if (fmt or "dump").lower() != "sql" else "triage_ed.sql"
            db_tmp = os.path.join(tmp_root, db_arc_name)
            path, err = postgres_backup_create(fmt=fmt or "dump", dst_path=db_tmp)
            if not path:
                return None, err or "PostgreSQL backup failed."
            db_tmp = path
        else:
            if not os.path.exists(DATABASE):
                return None, "SQLite database file was not found."
            db_arc_name = "triage_ed.db"
            db_tmp = os.path.join(tmp_root, db_arc_name)
            shutil.copy2(DATABASE, db_tmp)

        db_arc = f"{FULL_BACKUP_DB_DIR}/{db_arc_name}"
        upload_entries = []
        upload_count = 0
        upload_bytes = 0
        skipped_uploads = 0

        manifest = {
            "type": FULL_BACKUP_KIND,
            "version": FULL_BACKUP_VERSION,
            "created_at": datetime.now().isoformat(sep=" ", timespec="seconds"),
            "db_engine": engine,
            "database": {
                "path": db_arc,
                "size_bytes": os.path.getsize(db_tmp),
                "sha256": _sha256_file(db_tmp),
            },
            "uploads_prefix": FULL_BACKUP_UPLOADS_DIR + "/",
            "uploads": {
                "files_count": 0,
                "total_bytes": 0,
                "files": [],
                "skipped_files": 0,
            },
            "notes": "Full patient backup: database plus uploaded patient files.",
        }

        with _zipfile.ZipFile(tmp_zip, "w", compression=_zipfile.ZIP_DEFLATED, allowZip64=True) as zf:
            zf.write(db_tmp, db_arc)

            for src, rel in _iter_upload_files_for_backup():
                try:
                    arc = f"{FULL_BACKUP_UPLOADS_DIR}/{rel}"
                    st = os.stat(src)
                    sha = _sha256_file(src)
                    zf.write(src, arc)
                    upload_count += 1
                    upload_bytes += int(st.st_size or 0)
                    upload_entries.append(
                        {
                            "path": arc,
                            "size_bytes": int(st.st_size or 0),
                            "sha256": sha,
                        }
                    )
                except Exception:
                    skipped_uploads += 1

            manifest["uploads"]["files_count"] = upload_count
            manifest["uploads"]["total_bytes"] = upload_bytes
            manifest["uploads"]["files"] = upload_entries
            manifest["uploads"]["skipped_files"] = skipped_uploads
            zf.writestr(FULL_BACKUP_MANIFEST, json.dumps(manifest, ensure_ascii=False, indent=2))

        os.replace(tmp_zip, dst_path)
        final_path = _maybe_encrypt_backup(dst_path) if encrypt else dst_path
        return final_path, None
    except Exception as e:
        try:
            if tmp_zip and os.path.exists(tmp_zip):
                os.remove(tmp_zip)
        except Exception:
            pass
        return None, str(e)
    finally:
        try:
            if tmp_root and os.path.isdir(tmp_root):
                shutil.rmtree(tmp_root, ignore_errors=True)
        except Exception:
            pass


def _zip_member_is_safe(name: str) -> bool:
    try:
        name = (name or "").replace("\\", "/")
        if not name or name.startswith("/"):
            return False
        if re.match(r"^[A-Za-z]:", name):
            return False
        parts = [p for p in name.split("/") if p]
        return bool(parts) and all(p not in (".", "..") for p in parts)
    except Exception:
        return False


def _prepare_restore_source(src_path: str, engine: str):
    """Return restore context with db_path and optional extracted uploads_dir."""
    import tempfile as _tempfile
    import zipfile as _zipfile

    ctx = {
        "is_full_package": False,
        "tmp_dir": None,
        "db_path": src_path,
        "uploads_dir": None,
        "manifest": {},
    }
    try:
        if not src_path or not _zipfile.is_zipfile(src_path):
            return ctx

        tmp_dir = _tempfile.mkdtemp(prefix="restore_full_", dir=BACKUP_FOLDER)
        with _zipfile.ZipFile(src_path, "r", allowZip64=True) as zf:
            for info in zf.infolist():
                if not _zip_member_is_safe(info.filename):
                    raise Exception(f"Unsafe path inside backup package: {info.filename}")
            zf.extractall(tmp_dir)

        manifest = {}
        manifest_path = os.path.join(tmp_dir, FULL_BACKUP_MANIFEST)
        if os.path.exists(manifest_path):
            try:
                with open(manifest_path, "r", encoding="utf-8") as fp:
                    manifest = json.load(fp) or {}
            except Exception:
                manifest = {}

        db_rel = ""
        try:
            db_rel = ((manifest.get("database") or {}).get("path") or "").replace("\\", "/")
        except Exception:
            db_rel = ""

        db_path = None
        if db_rel and _zip_member_is_safe(db_rel):
            candidate = os.path.abspath(os.path.join(tmp_dir, db_rel))
            if candidate.startswith(os.path.abspath(tmp_dir)) and os.path.isfile(candidate):
                db_path = candidate

        if not db_path:
            allowed_db_ext = {".dump", ".sql", ".backup"} if (engine or "").lower() == "postgres" else {".db"}
            for root, _dirs, files in os.walk(tmp_dir):
                for fname in files:
                    if os.path.splitext(fname)[1].lower() in allowed_db_ext:
                        # Prefer files inside the database folder.
                        cand = os.path.join(root, fname)
                        if f"{os.sep}{FULL_BACKUP_DB_DIR}{os.sep}" in cand or os.path.basename(root) == FULL_BACKUP_DB_DIR:
                            db_path = cand
                            break
                if db_path:
                    break
            if not db_path:
                for root, _dirs, files in os.walk(tmp_dir):
                    for fname in files:
                        if os.path.splitext(fname)[1].lower() in allowed_db_ext:
                            db_path = os.path.join(root, fname)
                            break
                    if db_path:
                        break

        if not db_path or not os.path.isfile(db_path):
            shutil.rmtree(tmp_dir, ignore_errors=True)
            raise Exception("Full backup package does not contain a valid database backup file.")

        uploads_dir = os.path.join(tmp_dir, FULL_BACKUP_UPLOADS_DIR)
        if not os.path.isdir(uploads_dir):
            uploads_dir = None

        ctx.update(
            {
                "is_full_package": True,
                "tmp_dir": tmp_dir,
                "db_path": db_path,
                "uploads_dir": uploads_dir,
                "manifest": manifest,
            }
        )
        return ctx
    except Exception:
        try:
            if ctx.get("tmp_dir"):
                shutil.rmtree(ctx["tmp_dir"], ignore_errors=True)
        except Exception:
            pass
        raise


def _copytree_merge(src_dir: str, dst_dir: str):
    copied = 0
    total = 0
    os.makedirs(dst_dir, exist_ok=True)
    for root, dirs, files in os.walk(src_dir):
        rel_root = os.path.relpath(root, src_dir)
        if rel_root == ".":
            rel_root = ""
        for d in dirs:
            os.makedirs(os.path.join(dst_dir, rel_root, d), exist_ok=True)
        for fname in files:
            src = os.path.join(root, fname)
            dst = os.path.join(dst_dir, rel_root, fname)
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copy2(src, dst)
            copied += 1
            try:
                total += int(os.path.getsize(dst) or 0)
            except Exception:
                pass
    return copied, total


def _restore_uploads_from_dir(staged_uploads_dir: str):
    """Restore uploaded files safely.

    The preferred path is a directory swap that keeps the previous uploads folder
    beside the live folder as uploads.before_restore_*. If the swap is blocked by
    the OS, fall back to a non-destructive merge so patient files are not lost.
    """
    if not staged_uploads_dir or not os.path.isdir(staged_uploads_dir):
        return True, "No uploaded-files folder was found in this backup package."

    target = app.config.get("UPLOAD_FOLDER") or UPLOAD_FOLDER
    target = os.path.abspath(target)
    parent = os.path.dirname(target) or "."
    base = os.path.basename(target.rstrip(os.sep)) or "uploads"
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    token = uuid.uuid4().hex[:8]
    temp_target = os.path.join(parent, f".{base}.restore_tmp_{ts}_{token}")
    old_target = os.path.join(parent, f"{base}.before_restore_{ts}_{token}")

    try:
        os.makedirs(parent, exist_ok=True)
        shutil.copytree(staged_uploads_dir, temp_target)
        staged_count, staged_bytes = _dir_stats(temp_target)

        try:
            if os.path.exists(target):
                os.rename(target, old_target)
            os.rename(temp_target, target)
            return (
                True,
                f"Uploaded files restored: {staged_count} file(s), {staged_bytes} bytes. Previous uploads folder kept as {old_target}.",
            )
        except Exception as swap_err:
            # Roll back the live folder if the swap failed mid-way.
            try:
                if (not os.path.exists(target)) and os.path.exists(old_target):
                    os.rename(old_target, target)
            except Exception:
                pass

            copied, total = _copytree_merge(staged_uploads_dir, target)
            try:
                if os.path.isdir(temp_target):
                    shutil.rmtree(temp_target, ignore_errors=True)
            except Exception:
                pass
            return (
                True,
                f"Uploaded files merged safely: {copied} file(s), {total} bytes. Directory swap was not possible: {swap_err}",
            )
    except Exception as e:
        try:
            if os.path.isdir(temp_target):
                shutil.rmtree(temp_target, ignore_errors=True)
        except Exception:
            pass
        return False, str(e)


# ============================================================
# Restore Jobs (Background)
# ============================================================


def _restore_new_job_id() -> str:
    try:
        return uuid.uuid4().hex[:12]
    except Exception:
        return str(int(time.time()))


def _restore_job_update(job_id: str, **fields):
    try:
        with RESTORE_JOBS_LOCK:
            j = RESTORE_JOBS.get(job_id)
            if not j:
                return
            j.update(fields)
    except Exception:
        pass


def postgres_terminate_other_sessions():
    """Best-effort: terminate other active sessions on the target database.

    This avoids pg_restore waiting forever on locks when the web app is still connected.
    Returns: (ok: bool, info: str)
    """
    if psycopg2 is None:
        return False, "psycopg2 not installed"
    try:
        conn = psycopg2.connect(PG_DSN)
        conn.autocommit = True
        cur = conn.cursor()
        # Terminate other sessions in this DB (owned by same role)
        cur.execute(
            "SELECT count(*) FROM pg_stat_activity WHERE datname = current_database() AND pid <> pg_backend_pid();"
        )
        n = cur.fetchone()[0] if cur else 0
        cur.execute(
            "SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname = current_database() AND pid <> pg_backend_pid();"
        )
        try:
            cur.close()
        except Exception:
            pass
        try:
            conn.close()
        except Exception:
            pass
        return True, f"terminated {n} session(s)"
    except Exception as e:
        return False, str(e)


def postgres_close_pool():
    """Close psycopg2 connection pool (best effort)."""
    try:
        import db as _dbmod

        pool = getattr(_dbmod, "DB_POOL", None)
        if pool is not None:
            try:
                pool.closeall()
            except Exception:
                pass
        return True, None
    except Exception as e:
        return False, str(e)


def postgres_reinit_pool():
    """Re-init psycopg2 pool after restore so the app can continue without a full restart."""
    try:
        import db as _dbmod

        if hasattr(_dbmod, "_init_pool"):
            _dbmod._init_pool()
        return True, None
    except Exception as e:
        return False, str(e)


def _run_restore_job(job_id: str):
    """Worker: run restore job in background.

    Supports legacy database-only files and new full patient backup packages
    (.zip containing database + uploads). Full packages restore the database and
    uploaded patient files together.
    """
    tmp_dec_path = None
    restore_tmp_dir = None
    restore_ctx = None

    # Snapshot job parameters
    try:
        with RESTORE_JOBS_LOCK:
            job = RESTORE_JOBS.get(job_id) or {}
            src_path = job.get("src_path")
            safe_name = job.get("filename") or ""
            engine = (job.get("engine") or DB_ENGINE or "").lower()
    except Exception:
        src_path = None
        safe_name = ""
        engine = (DB_ENGINE or "").lower()

    if not src_path:
        _restore_job_update(
            job_id,
            status="error",
            step="init",
            finished_at=datetime.now().isoformat(sep=" ", timespec="seconds"),
            error="Missing source path for restore job.",
            message="Restore job is missing its source backup file.",
        )
        return

    # Start
    try:
        RESTORE_IN_PROGRESS.set()
    except Exception:
        pass

    _restore_job_update(
        job_id,
        status="running",
        step="starting",
        started_at=datetime.now().isoformat(sep=" ", timespec="seconds"),
        message="Preparing restore source...",
        error="",
    )

    try:
        # If backup is encrypted (*.enc), decrypt to a temporary file first.
        try:
            if str(src_path).lower().endswith(".enc"):
                f = _get_fernet()
                if not f:
                    raise Exception("Encrypted backup provided but ED_FERNET_KEY is not configured.")
                with open(src_path, "rb") as fp:
                    enc = fp.read()
                tmp_dec_path = src_path[:-4] + ".dec_tmp"
                with open(tmp_dec_path, "wb") as fp:
                    fp.write(f.decrypt(enc))
                src_path = tmp_dec_path
        except Exception as e:
            _restore_job_update(
                job_id,
                status="error",
                step="decrypt",
                error=str(e),
                message="Could not decrypt backup file.",
                finished_at=datetime.now().isoformat(sep=" ", timespec="seconds"),
            )
            return

        try:
            restore_ctx = _prepare_restore_source(src_path, engine)
            restore_tmp_dir = restore_ctx.get("tmp_dir")
            db_restore_path = restore_ctx.get("db_path") or src_path
            uploads_restore_dir = restore_ctx.get("uploads_dir")
            is_full_package = bool(restore_ctx.get("is_full_package"))
        except Exception as e:
            _restore_job_update(
                job_id,
                status="error",
                step="package",
                error=str(e),
                message="Invalid backup package.",
                finished_at=datetime.now().isoformat(sep=" ", timespec="seconds"),
            )
            return

        source_label = "full patient backup package" if is_full_package else "database-only backup"

        if engine == "postgres":
            # 1) terminate other sessions + close pool
            _restore_job_update(
                job_id,
                step="terminate_sessions",
                message="Terminating active DB sessions (best effort)...",
            )
            try:
                postgres_terminate_other_sessions()
            except Exception:
                pass

            _restore_job_update(
                job_id,
                step="close_pool",
                message="Closing DB connection pool (best effort)...",
            )
            try:
                postgres_close_pool()
            except Exception:
                pass

            # 2) safety backup (full package, not database only)
            try:
                _restore_job_update(
                    job_id,
                    step="safety_backup",
                    message="Creating full safety backup before restore...",
                )
                ts = datetime.now().strftime("%Y%m%d_%H%M%S")
                _create_full_patient_backup(
                    dst_path=os.path.join(BACKUP_FOLDER, f"triage_ed_before_restore_full_{ts}.zip"),
                    fmt="dump",
                    encrypt=True,
                )
            except Exception:
                _restore_job_update(
                    job_id, message="Safety backup failed (continuing with restore)..."
                )

            # 3) restore database
            _restore_job_update(
                job_id,
                step="restore_database",
                message=f"Resetting public schema and restoring database from {source_label}: {safe_name} ...",
            )
            ok, err = postgres_restore_from_file(db_restore_path)
            if not ok:
                _restore_job_update(
                    job_id,
                    status="error",
                    step="restore_database",
                    error=(err or "restore failed"),
                    message="Database restore failed.",
                    finished_at=datetime.now().isoformat(sep=" ", timespec="seconds"),
                )
                return

            # 4) restore uploaded files if this is a full package
            upload_msg = ""
            if is_full_package:
                _restore_job_update(
                    job_id,
                    step="restore_uploads",
                    message="Restoring uploaded patient files from backup package...",
                )
                ok_uploads, upload_msg = _restore_uploads_from_dir(uploads_restore_dir)
                if not ok_uploads:
                    _restore_job_update(
                        job_id,
                        status="error",
                        step="restore_uploads",
                        error=upload_msg,
                        message="Database restored, but uploaded files restore failed. Use the before-restore full backup if rollback is required.",
                        finished_at=datetime.now().isoformat(sep=" ", timespec="seconds"),
                    )
                    return

            # 5) re-init pool
            _restore_job_update(
                job_id, step="reinit_pool", message="Re-initializing connection pool..."
            )
            try:
                postgres_reinit_pool()
            except Exception:
                pass

            final_msg = "Restore completed successfully."
            if is_full_package:
                final_msg += " Database and uploaded patient files were restored."
                if upload_msg:
                    final_msg += " " + upload_msg
            else:
                final_msg += " Database restored only; this legacy backup did not include uploaded files."
            final_msg += " (Recommended: restart the app/server)."

            _restore_job_update(
                job_id,
                status="success",
                step="done",
                message=final_msg,
                finished_at=datetime.now().isoformat(sep=" ", timespec="seconds"),
            )
            return

        # SQLite restore
        _restore_job_update(
            job_id,
            step="safety_backup",
            message="Creating full safety backup before restore...",
        )
        try:
            ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            _create_full_patient_backup(
                dst_path=os.path.join(BACKUP_FOLDER, f"triage_ed_before_restore_full_{ts}.zip"),
                fmt="dump",
                encrypt=True,
            )
        except Exception:
            _restore_job_update(
                job_id, message="Safety backup failed (continuing with restore)..."
            )

        _restore_job_update(
            job_id,
            step="restore_database",
            message=f"Restoring SQLite database from {source_label}: {safe_name} ...",
        )
        try:
            tmp = DATABASE + ".restore_tmp"
            shutil.copy2(db_restore_path, tmp)

            # On Windows, replacing an open SQLite file may fail. Retry briefly.
            ok_replace = False
            last_err = None
            for _ in range(5):
                try:
                    os.replace(tmp, DATABASE)
                    ok_replace = True
                    break
                except Exception as _e:
                    last_err = _e
                    try:
                        time.sleep(1)
                    except Exception:
                        pass

            if not ok_replace:
                raise last_err or Exception("Failed to replace database file.")

            upload_msg = ""
            if is_full_package:
                _restore_job_update(
                    job_id,
                    step="restore_uploads",
                    message="Restoring uploaded patient files from backup package...",
                )
                ok_uploads, upload_msg = _restore_uploads_from_dir(uploads_restore_dir)
                if not ok_uploads:
                    _restore_job_update(
                        job_id,
                        status="error",
                        step="restore_uploads",
                        error=upload_msg,
                        message="Database restored, but uploaded files restore failed. Use the before-restore full backup if rollback is required.",
                        finished_at=datetime.now().isoformat(sep=" ", timespec="seconds"),
                    )
                    return

            final_msg = "Restore completed successfully."
            if is_full_package:
                final_msg += " Database and uploaded patient files were restored."
                if upload_msg:
                    final_msg += " " + upload_msg
            else:
                final_msg += " Database restored only; this legacy backup did not include uploaded files."
            final_msg += " (Recommended: restart the app/server)."

            _restore_job_update(
                job_id,
                status="success",
                step="done",
                message=final_msg,
                finished_at=datetime.now().isoformat(sep=" ", timespec="seconds"),
            )
        except Exception as e:
            _restore_job_update(
                job_id,
                status="error",
                step="restore_database",
                error=str(e),
                message="Database restore failed.",
                finished_at=datetime.now().isoformat(sep=" ", timespec="seconds"),
            )

    except Exception:
        _restore_job_update(
            job_id,
            status="error",
            step="exception",
            error=traceback.format_exc()[-2000:],
            message="Restore crashed with an exception.",
            finished_at=datetime.now().isoformat(sep=" ", timespec="seconds"),
        )
    finally:
        try:
            if restore_tmp_dir and os.path.isdir(restore_tmp_dir):
                shutil.rmtree(restore_tmp_dir, ignore_errors=True)
        except Exception:
            pass
        try:
            if tmp_dec_path and os.path.exists(tmp_dec_path):
                os.remove(tmp_dec_path)
        except Exception:
            pass
        try:
            RESTORE_IN_PROGRESS.clear()
        except Exception:
            pass


# Runtime performance guard for tablet/iPad startup.
# The scheduler used to run pg_dump immediately when each worker booted; on
# Railway/Gunicorn that duplicated work and delayed the first page load.
_BACKUP_SCHEDULER_STARTED = False
_BACKUP_SCHEDULER_LOCK = threading.Lock()


def _backup_scheduler_enabled():
    try:
        raw = os.environ.get("BACKUP_SCHEDULER_ENABLED")
        if raw is None:
            raw = APP_CONFIG.get("BACKUP_SCHEDULER_ENABLED", True)
        return str(raw).strip().lower() not in ("0", "false", "no", "off")
    except Exception:
        return True


def _backup_scheduler_start_delay_seconds():
    """Delay the first automatic backup so cold starts stay responsive.

    Manual Backup Now still calls do_backup() immediately. The delay only applies
    to the background scheduler. It is configurable without changing deployment:
    BACKUP_STARTUP_DELAY_SECONDS=0 restores the old immediate behavior.
    """
    try:
        raw = os.environ.get("BACKUP_STARTUP_DELAY_SECONDS")
        if raw is None:
            raw = APP_CONFIG.get("BACKUP_STARTUP_DELAY_SECONDS", None)
        if raw is None or str(raw).strip() == "":
            raw = 300 if (os.environ.get("RAILWAY_ENVIRONMENT") or os.environ.get("RAILWAY_PROJECT_ID")) else 60
        return max(0, int(float(raw)))
    except Exception:
        return 300 if (os.environ.get("RAILWAY_ENVIRONMENT") or os.environ.get("RAILWAY_PROJECT_ID")) else 60


def do_backup():
    """Create a full patient backup package in BACKUP_FOLDER.

    The package is a .zip containing the database dump/file plus the uploads
    folder, so Restore can bring back patient attachments, images, and PDFs.
    """
    try:
        if RESTORE_IN_PROGRESS.is_set():
            return None

        path, err = _create_full_patient_backup(fmt="dump", encrypt=True)
        if not path:
            try:
                app.logger.warning("Full backup failed: %s", err)
            except Exception:
                pass
            return None
        return path
    except Exception as e:
        try:
            app.logger.exception("Backup failed: %s", e)
        except Exception:
            pass
        return None


def backup_scheduler_loop():
    # Keep the first page load fast: do not run pg_dump during worker cold start.
    try:
        first_delay = _backup_scheduler_start_delay_seconds()
        if first_delay > 0:
            time.sleep(first_delay)
    except Exception:
        pass

    while True:
        do_backup()
        time.sleep(43200)  # every 12 hours


def start_backup_scheduler_once():
    # Avoid duplicate scheduler threads in the same worker and keep old debug
    # reload behavior. This is process-local; multiple Gunicorn workers are still
    # safe, but they no longer block startup with an immediate pg_dump.
    global _BACKUP_SCHEDULER_STARTED
    if app.config.get("DEBUG") and os.environ.get("WERKZEUG_RUN_MAIN") != "true":
        return
    if not _backup_scheduler_enabled():
        return
    with _BACKUP_SCHEDULER_LOCK:
        if _BACKUP_SCHEDULER_STARTED:
            return
        _BACKUP_SCHEDULER_STARTED = True
        t = threading.Thread(target=backup_scheduler_loop, daemon=True, name="ed-backup-scheduler")
        t.start()


