@app.route("/activate", methods=["GET", "POST"])
def activate():
    """Activation key entry. When ACTIVATION_REQUIRED is True, user must enter a valid key."""
    if request.method == "POST":
        key = (request.form.get("activation_key") or "").strip()
        if not key:
            flash("Please enter an activation key.", "danger")
            return redirect(url_for("activate"))
        try:
            import activation_key as ak

            valid, payload = ak.verify_activation_key(key)
            if not valid:
                flash("Invalid or expired activation key.", "danger")
                return redirect(url_for("activate"))
        except Exception:
            flash("Invalid activation key.", "danger")
            return redirect(url_for("activate"))
        base_dir = os.path.dirname(os.path.abspath(__file__))
        data_dir = os.path.join(base_dir, "data")
        try:
            os.makedirs(data_dir, exist_ok=True)
            path = os.path.join(data_dir, ".activation_key")
            with open(path, "w", encoding="utf-8") as f:
                f.write(key)
            flash("Activation key saved. You can use the application now.", "success")
        except Exception as e:
            flash(
                f"Key is valid but could not save to file: {e}. Set ED_ACTIVATION_KEY env or ACTIVATION_KEY in config.",
                "warning",
            )
        return redirect(url_for("login"))
    return render_template_string("""
        <!DOCTYPE html>
        <html><head><meta charset="utf-8"><title>Activation</title>
        <link href="{{ url_for('static', filename='vendor/bootstrap/bootstrap.min.css') }}" rel="stylesheet"></head>
        <body class="bg-light"><div class="container py-5">
        <h1>Enter activation key</h1>
        <form method="post" class="mt-3">
          <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">
          <div class="mb-3">
            <label for="activation_key" class="form-label">Activation key</label>
            <input type="text" class="form-control" id="activation_key" name="activation_key" placeholder="Paste your key" required>
          </div>
          <button type="submit" class="btn btn-primary">Login</button>
        </form>
        {% with messages = get_flashed_messages(with_categories=true) %}
          {% if messages %}
          <div class="mt-3">
            {% for cat, msg in messages %}
            <div class="alert alert-{{ 'danger' if cat == 'error' else cat or 'info' }}">{{ msg }}</div>
            {% endfor %}
          </div>
          {% endif %}
        {% endwith %}
        </div></body></html>
        """)


@app.route("/login", methods=["GET", "POST"])
def login():
    # If already logged in, do not show login form (avoid cached/back navbar confusion)
    if request.method == "GET" and session.get("user_id"):
        return login_redirect_for_role(session.get("role"))

    if request.method == "GET" and request.args.get("forced_logout") == "other_device":
        flash(
            "Your account is open on another device. This session has been closed.",
            "warning",
        )

    if request.method == "POST":
        username = request.form.get("username", "").strip()
        full_name = request.form.get("full_name", "").strip()
        password = request.form.get("password", "").strip()
        # Rate limiting: 5 failed attempts / 15 minutes (per IP + per user)
        try:
            _ip = security.get_client_ip(request)
            _allowed, _retry_after = security.login_rate_limit_check(username, _ip)
            if not _allowed:
                try:
                    security.audit_event(
                        "LOGIN_RATE_LIMIT", {"username": username}, status=429
                    )
                except Exception:
                    pass
                mins = max(1, int((_retry_after or 60) / 60))
                flash(
                    f"Too many login attempts. Please try again after {mins} minute(s).",
                    "danger",
                )
                return render_template("login.html"), 429
        except Exception:
            pass
        u = _fetch_active_login_user(username)
        if u and _verify_login_password_cached(username, (u.get("password_hash") or ""), password):
            session.clear()
            session["user_id"] = u["id"]
            session["username"] = u["username"]
            session["role"] = normalize_role_key(u.get("role") if isinstance(u, dict) else u["role"]) or (u.get("role") if isinstance(u, dict) else u["role"])
            try:
                session["full_name"] = (
                    u.get("full_name") if isinstance(u, dict) else u["full_name"]
                )
            except Exception:
                session["full_name"] = ""
            try:
                session["gd_number"] = (
                    u.get("gd_number") if isinstance(u, dict) else u["gd_number"]
                )
            except Exception:
                session["gd_number"] = ""
            session["_session_token"] = uuid.uuid4().hex
            session["single_session_last_check"] = 0
            # Security: browser-session cookie only; users must sign in again after browser restart.
            session.permanent = False
            session["last_activity"] = int(time.time())
            try:
                _single_session_registry_set(
                    u["id"],
                    u.get("username") if isinstance(u, dict) else u["username"],
                    session.get("_session_token"),
                )
            except Exception:
                pass
            # Best-effort cleanup of stale visit locks using a very short dedicated DB checkout.
            # Under load we prefer skipping this cleanup rather than blocking the login request.
            try:
                _cleanup_stale_visit_locks_after_login(u.get("username") or "")
            except Exception:
                pass
            try:
                security.login_rate_limit_reset(
                    username, security.get_client_ip(request)
                )
            except Exception:
                pass
            log_action("LOGIN", details=username)
            return login_redirect_for_role(u.get("role"))
        try:
            security.login_rate_limit_fail(username, security.get_client_ip(request))
            security.audit_event("LOGIN_FAIL", {"username": username}, status=401)
        except Exception:
            pass
        flash("Invalid username or password.", "danger")
    return render_template("login.html")


