@app.route("/session_status")
def session_status():
    if "user_id" not in session:
        return jsonify({"ok": False, "reason": "anonymous"}), 401

    if _single_session_check_current(force=True):
        return jsonify({"ok": True})

    try:
        _release_current_session_visit_locks()
    except Exception:
        pass
    try:
        log_action("AUTO_LOGOUT_OTHER_DEVICE")
    except Exception:
        pass
    session.clear()
    return (
        jsonify(
            {
                "ok": False,
                "reason": "other_device",
                "message": "Your account is open on another device. This session has been closed.",
                "redirect": url_for("login", forced_logout="other_device"),
            }
        ),
        409,
    )


def _release_visit_locks_for_identity(username=None, viewer_token=None):
    """Best-effort visit-lock cleanup that does not depend on the request session."""
    u = (username or "").strip()
    vt = (viewer_token or "").strip()
    if not (u or vt):
        return
    db = None
    try:
        ensure_visit_lock_schema()
    except Exception:
        pass
    try:
        db = get_db()
        cur = db.cursor()
        if vt:
            cur.execute(
                "DELETE FROM visit_locks_sessions WHERE viewer_token=?",
                (vt,),
            )
        elif u:
            cur.execute(
                "DELETE FROM visit_locks_sessions WHERE username=?",
                (u,),
            )
        try:
            db.commit()
        except Exception:
            pass
    except Exception as exc:
        try:
            if db is not None:
                db.rollback()
        except Exception:
            pass
        try:
            _log_noncritical_exception("logout visit-lock cleanup failed", exc)
        except Exception:
            pass


def _logout_cleanup_worker(user_id=None, username=None, session_token=None, viewer_token=None):
    """Run slow logout cleanup outside the user-facing redirect path."""
    try:
        with app.app_context():
            created_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            try:
                _activity_log_insert_standalone(
                    "LOGOUT",
                    None,
                    (username or "UNKNOWN"),
                    None,
                    created_at,
                )
            except Exception as exc:
                try:
                    _log_noncritical_exception("async logout activity log failed", exc)
                except Exception:
                    pass
            try:
                _release_visit_locks_for_identity(username=username, viewer_token=viewer_token)
            except Exception as exc:
                try:
                    _log_noncritical_exception("async logout visit-lock cleanup failed", exc)
                except Exception:
                    pass
            try:
                _single_session_clear_registry(user_id, session_token)
            except Exception as exc:
                try:
                    _log_noncritical_exception("async logout single-session cleanup failed", exc)
                except Exception:
                    pass
    except Exception:
        pass


def _start_logout_cleanup_async(user_id=None, username=None, session_token=None, viewer_token=None):
    try:
        t = threading.Thread(
            target=_logout_cleanup_worker,
            args=(user_id, username, session_token, viewer_token),
            name="EDDT-LogoutCleanup",
            daemon=True,
        )
        t.start()
    except Exception:
        # Never delay logout if the cleanup thread cannot be started.
        pass


@app.route("/logout")
def logout():
    user_id = session.get("user_id")
    username = (session.get("username") or "").strip()
    session_token = (session.get("_session_token") or "").strip()
    viewer_token = (session.get("visit_lock_viewer_token") or "").strip()

    session.clear()
    resp = redirect(url_for("login"))
    try:
        resp.delete_cookie(app.config.get("SESSION_COOKIE_NAME", "session"), path="/")
    except Exception:
        pass

    _start_logout_cleanup_async(
        user_id=user_id,
        username=username,
        session_token=session_token,
        viewer_token=viewer_token,
    )
    return resp


@app.route("/change_password", methods=["GET", "POST"])
@login_required
def change_password():
    """Allow the currently logged-in user to change their own password."""
    if request.method == "POST":
        current_password = (request.form.get("current_password") or "").strip()
        new_password = (request.form.get("new_password") or "").strip()
        confirm_password = (request.form.get("confirm_password") or "").strip()

        if not current_password:
            flash("Current password is required.", "danger")
            return redirect(url_for("change_password"))

        if len(new_password) < 6:
            flash("New password must be at least 6 characters.", "danger")
            return redirect(url_for("change_password"))

        if new_password != confirm_password:
            flash("New password and confirm password do not match.", "danger")
            return redirect(url_for("change_password"))

        cur = get_db().cursor()
        u = cur.execute(
            "SELECT id, username, password_hash FROM users WHERE id=? AND is_active=1",
            (session.get("user_id"),),
        ).fetchone()

        if not u:
            flash("User not found or inactive.", "danger")
            return redirect(url_for("logout"))

        try:
            stored_hash = (
                u.get("password_hash") if isinstance(u, dict) else u["password_hash"]
            )
        except Exception:
            stored_hash = u["password_hash"]

        if not check_password_hash(stored_hash, current_password):
            flash("Current password is incorrect.", "danger")
            return redirect(url_for("change_password"))

        new_hash = generate_password_hash(new_password)
        db = get_db()
        db.execute(
            "UPDATE users SET password_hash=? WHERE id=?",
            (new_hash, session.get("user_id")),
        )
        db.commit()

        log_action("CHANGE_PASSWORD")

        flash("Password updated successfully.", "success")
        return redirect(url_for("change_password"))

    return render_template("change_password.html")


@app.route("/healthz")
def healthz():
    """Deep health endpoint for monitoring and load tests.

    Default response always includes:
      - bootstrap_ok
      - db_pool_ready   (when DB_ENGINE == postgres)
      - redis_enabled / redis_ok / redis_cache_ok / redis_sessions_ok

    Optional query:
      ?db=1 -> also runs a trivial DB query (SELECT 1) and adds db_ok/db_error.
    """
    try:
        _tz = get_display_tzinfo()
    except Exception:
        _tz = None
    _now = datetime.now(_tz) if _tz else datetime.now()

    out = {
        "ok": True,
        "server_time": _now.strftime("%Y-%m-%d %H:%M:%S"),
        "db_engine": DB_ENGINE,
        "version": APP_VERSION,
    }

    # --- Bootstrap status ---
    try:
        out["bootstrap_ok"] = not bool(_BOOTSTRAP_LAST_ERROR)
        if _BOOTSTRAP_LAST_ERROR:
            out["bootstrap_error"] = str(_BOOTSTRAP_LAST_ERROR)[:200]
            out["ok"] = False
    except Exception:
        out["bootstrap_ok"] = False
        out["ok"] = False

    # --- PostgreSQL pool readiness ---
    if str(DB_ENGINE or "").lower() == "postgres":
        try:
            from db import DB_POOL as _DB_POOL  # lazy import

            out["db_pool_ready"] = bool(_DB_POOL is not None)
            if not out["db_pool_ready"]:
                out.setdefault("db_error", "PostgreSQL pool is not initialized")
                out["ok"] = False
        except Exception as e:
            out["db_pool_ready"] = False
            out.setdefault("db_error", str(e)[:200])
            out["ok"] = False

    # --- DB round-trip (optional) ---
    if request.args.get("db") == "1":
        try:
            cur = get_db().cursor()
            cur.execute("SELECT 1 AS ok").fetchone()
            out["db_ok"] = True
        except Exception as e:
            out["db_ok"] = False
            out["db_error"] = str(e)[:200]
            out["ok"] = False

    # --- Redis health (always included) ---
    if redis_support is not None:
        try:
            r = redis_support.health_check()
            if isinstance(r, dict):
                out.update(r)
            else:
                out.update(
                    {
                        "redis_enabled": False,
                        "redis_ok": False,
                        "redis_cache_ok": False,
                        "redis_sessions_ok": False,
                    }
                )
                out["ok"] = False
            try:
                if out.get("redis_enabled"):
                    if (
                        (not out.get("redis_ok"))
                        or (not out.get("redis_cache_ok"))
                        or (not out.get("redis_sessions_ok"))
                    ):
                        out["ok"] = False
            except Exception:
                out["ok"] = False
        except Exception as e:
            out.update(
                {
                    "redis_enabled": True,
                    "redis_ok": False,
                    "redis_cache_ok": False,
                    "redis_sessions_ok": False,
                    "redis_error": str(e)[:200],
                }
            )
            out["ok"] = False
    else:
        out.update(
            {
                "redis_enabled": False,
                "redis_ok": False,
                "redis_cache_ok": False,
                "redis_sessions_ok": False,
            }
        )
        out["ok"] = False

    resp = jsonify(out)
    resp.headers["Cache-Control"] = "no-store"
    return resp


def _runtime_diag_build_report(minutes=None, limit=10):
    if RUNTIME_DIAGNOSTICS is None:
        return {
            "generated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "window_minutes": int(minutes or 60),
            "summary": {},
            "top_slow_endpoints": [],
            "top_error_endpoints": [],
            "recent_issue_groups": [],
            "recent_issue_samples": [],
            "log_findings": {},
            "detected_problems": [
                {
                    "severity": "high",
                    "title": "Runtime diagnostics collector is unavailable",
                    "details": "The runtime diagnostics module could not be initialized.",
                }
            ],
        }

    report = RUNTIME_DIAGNOSTICS.build_report(minutes=minutes, limit=limit)
    report["db_engine"] = DB_ENGINE
    report["version"] = APP_VERSION

    try:
        if DB_ENGINE == "postgres":
            from db import DB_POOL as _DB_POOL

            report["db_pool_ready"] = bool(_DB_POOL is not None)
    except Exception as e:
        report["db_pool_ready"] = False
        report["db_pool_error"] = str(e)[:200]

    try:
        if redis_support is not None:
            report["redis"] = redis_support.health_check()
    except Exception as e:
        report["redis"] = {"redis_error": str(e)[:200]}

    return report


def _runtime_reports_dir() -> str:
    path = os.path.join(_data_root, "runtime_reports")
    os.makedirs(path, exist_ok=True)
    return path


def _list_saved_runtime_reports(limit: int = 25):
    out = []
    try:
        root_dir = _runtime_reports_dir()
        for path in sorted(Path(root_dir).glob("runtime_report_*.json"), key=lambda p: p.stat().st_mtime, reverse=True)[: max(1, int(limit or 25))]:
            try:
                st = path.stat()
                out.append({
                    "name": path.name,
                    "path": str(path),
                    "mtime": datetime.fromtimestamp(st.st_mtime).strftime("%Y-%m-%d %H:%M:%S"),
                    "size_kb": round(st.st_size / 1024.0, 1),
                })
            except Exception:
                continue
    except Exception:
        return []
    return out


@app.route("/healthz/runtime")
def runtime_health_report():
    minutes = request.args.get("minutes", type=int) or 15
    if RUNTIME_DIAGNOSTICS is None:
        return jsonify({"ok": False, "error": "runtime diagnostics unavailable"}), 503
    out = RUNTIME_DIAGNOSTICS.build_compact_report(minutes=minutes)
    out["ok"] = True
    out["db_engine"] = DB_ENGINE
    out["version"] = APP_VERSION
    resp = jsonify(out)
    resp.headers["Cache-Control"] = "no-store"
    return resp


@app.route("/admin/runtime_report.json")
@login_required
@role_required("admin")
def admin_runtime_report_json():
    minutes = request.args.get("minutes", type=int) or 60
    limit = request.args.get("limit", type=int) or 10
    report = _runtime_diag_build_report(minutes=minutes, limit=limit)
    if str(request.args.get("save") or "").strip().lower() in ("1", "true", "yes", "y", "on"):
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        save_path = os.path.join(_runtime_reports_dir(), f"runtime_report_{ts}.json")
        if safe_write_json(save_path, report):
            report["saved_to"] = save_path
    report["saved_reports"] = _list_saved_runtime_reports(limit=25)
    resp = jsonify(report)
    resp.headers["Cache-Control"] = "no-store"
    return resp


