@app.route("/admin/users", methods=["GET", "POST"])
@login_required
@role_required("admin")
def admin_users():
    db = get_db()
    cur = db.cursor()
    user_query = (request.args.get("q", "") or "").strip()

    if request.method == "POST":
        username = request.form.get("username", "").strip()
        full_name = request.form.get("full_name", "").strip()
        password = request.form.get("password", "").strip()
        role = normalize_role_key(request.form.get("role", "reception")) or "reception"
        gd_number = request.form.get("gd_number", "").strip()

        # Convenience: if physician username is numeric and GD is blank, reuse username as GD
        if role == "doctor" and username and username.isdigit() and not gd_number:
            gd_number = username

        if role == "doctor" and not gd_number:
            flash("GD Number is required for Physician users.", "danger")
            return redirect(url_for("admin_users"))

        # Auto-fill doctor display name from Physicians Directory when possible
        if role == "doctor" and gd_number and not full_name:
            try:
                full_name = (
                    _physician_directory_lookup_by_gd(cur, gd_number) or full_name
                )
            except Exception:
                pass

        if not username or not password:
            flash("Username and password are required.", "danger")
        elif len(password) < 6:
            flash("Password must be at least 6 characters.", "danger")
        else:
            try:
                cur.execute(
                    """
                    INSERT INTO users (username, full_name, password_hash, role, gd_number, created_at, is_active)
                    VALUES (?,?,?,?,?,?,1)
                """,
                    (
                        username,
                        full_name,
                        generate_password_hash(password),
                        role,
                        gd_number,
                        datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                    ),
                )
                db.commit()
                log_action("CREATE_USER", details=f"{username}:{role}")
                flash("User account created successfully.", "success")
            except Exception as e:
                try:
                    db.rollback()
                except Exception:
                    pass
                msg = str(e).lower()
                if "unique" in msg or "duplicate" in msg or "already exists" in msg:
                    flash("Username already exists.", "danger")
                else:
                    flash(f"Failed to create user: {e}", "danger")

    users = []
    try:
        if user_query:
            q = f"%{user_query.lower()}%"
            users = cur.execute(
                """
                SELECT id, username, full_name, role, gd_number, created_at, is_active
                FROM users
                WHERE LOWER(COALESCE(username,'')) LIKE ?
                   OR LOWER(COALESCE(full_name,'')) LIKE ?
                   OR LOWER(COALESCE(gd_number,'')) LIKE ?
                ORDER BY id DESC
                """,
                (q, q, q),
            ).fetchall()
        else:
            users = cur.execute(
                "SELECT id, username, full_name, role, gd_number, created_at, is_active FROM users ORDER BY id DESC"
            ).fetchall()
    except Exception as e:
        _log_noncritical_exception("admin_users: search query failed", e)
        users = cur.execute(
            "SELECT id, username, full_name, role, gd_number, created_at, is_active FROM users ORDER BY id DESC"
        ).fetchall()

    return render_template("admin_users.html", users=users, user_query=user_query)


@app.route("/admin/users/<int:user_id>/toggle", methods=["POST"])
@login_required
@role_required("admin")
def admin_toggle_user(user_id):
    db = get_db()
    cur = db.cursor()
    u = cur.execute(
        "SELECT username, is_active FROM users WHERE id=?", (user_id,)
    ).fetchone()
    if not u:
        flash("User not found.", "danger")
        return redirect(url_for("admin_users"))
    new_status = 0 if u["is_active"] else 1
    db.execute("UPDATE users SET is_active=? WHERE id=?", (new_status, user_id))
    db.commit()
    action = "DEACTIVATE_USER" if new_status == 0 else "ACTIVATE_USER"
    log_action(action, details=u["username"])
    flash(
        f"User {u['username']} is now {'inactive' if new_status == 0 else 'active'}.",
        "success",
    )
    return redirect(url_for("admin_users"))


@app.route("/admin/users/<int:user_id>/delete", methods=["POST"])
@login_required
@role_required("admin")
def admin_delete_user(user_id):
    db = get_db()
    cur = db.cursor()
    u = cur.execute(
        "SELECT id, username, role FROM users WHERE id=?",
        (user_id,),
    ).fetchone()
    if not u:
        flash("User not found.", "danger")
        return redirect(url_for("admin_users"))

    # Prevent deleting yourself while logged in
    try:
        current_id = session.get("user_id")
        if current_id == u["id"]:
            flash("You cannot delete your own account while logged in.", "danger")
            return redirect(url_for("admin_users"))
    except Exception:
        pass

    # Prevent deleting default admin user
    uname = (u["username"] or "").lower()
    if uname == "admin":
        flash("Default admin user cannot be deleted.", "danger")
        return redirect(url_for("admin_users"))

    # Ensure at least one admin remains in the system
    try:
        row = cur.execute(
            "SELECT COUNT(*) AS c FROM users WHERE role='admin' AND id<>?",
            (u["id"],),
        ).fetchone()
        remaining_admins = row["c"] if row is not None else 0
    except Exception:
        remaining_admins = 0

    if (u["role"] or "").lower() == "admin" and remaining_admins <= 0:
        flash("You cannot delete the last admin account.", "danger")
        return redirect(url_for("admin_users"))

    db.execute("DELETE FROM users WHERE id=?", (user_id,))
    db.commit()
    log_action("DELETE_USER", details=u["username"])
    flash(f"User {u['username']} deleted permanently.", "success")
    return redirect(url_for("admin_users"))




def _admin_items_tab_for_kind(kind: str) -> str:
    kind = (kind or "").strip().lower()
    allowed = {"rad", "lab", "med", "home", "dx", "doc", "nurse", "clinic"}
    return kind if kind in allowed else "rad"


def _admin_items_next_sort_order(cur, table: str, fallback: int = 1) -> int:
    try:
        row = cur.execute(
            f"SELECT COALESCE(MAX(sort_order), 0) AS m FROM {table}"
        ).fetchone()
        if row is None:
            return int(fallback)
        try:
            current = row["m"]
        except Exception:
            current = row[0]
        return int(current or 0) + 1
    except Exception:
        return int(fallback)


def _directory_search_term(q: str) -> str:
    q = (q or "").strip()
    if DB_ENGINE == "postgres":
        return f"%{q}%"
    return f"%{q.lower()}%"


def _normalize_staff_directory_name(name: str) -> str:
    s = str(name or "")
    try:
        s = unicodedata.normalize("NFKC", s)
    except Exception:
        pass
    try:
        s = s.replace("\u200f", " ").replace("\u200e", " ")
        s = re.sub(r"[\r\n\t]+", " ", s)
        s = re.sub(r"\s+", " ", s).strip()
        s = re.sub(r"^[,;:\-\s]+", "", s)
        s = re.sub(r"\s*,\s*", ", ", s)
        s = re.sub(r"\s+", " ", s).strip(" ,;-")
    except Exception:
        s = s.strip()
    return s[:160]


def _normalize_staff_directory_code(code: str) -> str:
    s = str(code or "").strip()
    try:
        s = unicodedata.normalize("NFKC", s)
    except Exception:
        pass
    s = re.sub(r"\s+", " ", s).strip()
    return s[:60]


def _normalize_staff_directory_specialty(specialty: str) -> str:
    s = str(specialty or "")
    try:
        s = unicodedata.normalize("NFKC", s)
    except Exception:
        pass
    s = re.sub(r"\s+", " ", s).strip()
    return s[:120]


def _staff_name_match_key(name: str) -> str:
    return _normalize_staff_directory_name(name).casefold()


_nursing_directory_schema_ready = False


def ensure_nursing_directory_schema():
    """Create/upgrade Nursing Directory table used by Admin - Orders Items."""
    global _nursing_directory_schema_ready
    if _nursing_directory_schema_ready:
        return

    db = get_db()
    cur = db.cursor()
    try:
        if DB_ENGINE == "postgres":
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS nursing_directory (
                    id BIGSERIAL PRIMARY KEY,
                    name TEXT NOT NULL,
                    gn_number TEXT NOT NULL DEFAULT '',
                    specialty TEXT NOT NULL DEFAULT '',
                    is_active INTEGER NOT NULL DEFAULT 1,
                    created_at TEXT NOT NULL,
                    created_by TEXT NOT NULL,
                    updated_at TEXT,
                    updated_by TEXT
                )
                """
            )
        else:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS nursing_directory (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    gn_number TEXT NOT NULL DEFAULT '',
                    specialty TEXT NOT NULL DEFAULT '',
                    is_active INTEGER NOT NULL DEFAULT 1,
                    created_at TEXT NOT NULL,
                    created_by TEXT NOT NULL,
                    updated_at TEXT,
                    updated_by TEXT
                )
                """
            )

        try:
            cur.execute("CREATE INDEX IF NOT EXISTS idx_nursing_directory_name ON nursing_directory(name)")
        except Exception as idx_exc:
            _log_noncritical_exception("ensure_nursing_directory_schema: idx_nursing_directory_name", idx_exc)
        try:
            cur.execute("CREATE INDEX IF NOT EXISTS idx_nursing_directory_gn ON nursing_directory(gn_number)")
        except Exception as idx_exc:
            _log_noncritical_exception("ensure_nursing_directory_schema: idx_nursing_directory_gn", idx_exc)
        try:
            cur.execute("CREATE INDEX IF NOT EXISTS idx_nursing_directory_active ON nursing_directory(is_active)")
        except Exception as idx_exc:
            _log_noncritical_exception("ensure_nursing_directory_schema: idx_nursing_directory_active", idx_exc)

        db.commit()
        _nursing_directory_schema_ready = True
    except Exception as schema_exc:
        _nursing_directory_schema_ready = False
        _rollback_with_logging(db, "ensure_nursing_directory_schema")
        _log_noncritical_exception("ensure_nursing_directory_schema failed", schema_exc)



def _physician_directory_row_to_dict(row):
    if row is None:
        return None
    try:
        row_id = row["id"]
        raw_name = row["value"]
        extra = row["extra"] or ""
        is_active = int(row["is_active"])
    except Exception:
        row_id = row[0] if len(row) > 0 else None
        raw_name = row[1] if len(row) > 1 else ""
        extra = row[2] if len(row) > 2 else ""
        is_active = int(row[3]) if len(row) > 3 and row[3] is not None else 1
    gd_number, specialty = doctor_extra_parse(extra or "")
    return {
        "id": row_id,
        "name": _normalize_staff_directory_name(raw_name),
        "gd_number": _normalize_staff_directory_code(gd_number),
        "specialty": _normalize_staff_directory_specialty(specialty),
        "is_active": is_active,
    }



def _nursing_directory_row_to_dict(row):
    if row is None:
        return None
    try:
        row_id = row["id"]
        name = row["name"]
        gn_number = row["gn_number"] or ""
        specialty = row["specialty"] or ""
        is_active = int(row["is_active"])
    except Exception:
        row_id = row[0] if len(row) > 0 else None
        name = row[1] if len(row) > 1 else ""
        gn_number = row[2] if len(row) > 2 else ""
        specialty = row[3] if len(row) > 3 else ""
        is_active = int(row[4]) if len(row) > 4 and row[4] is not None else 1
    return {
        "id": row_id,
        "name": _normalize_staff_directory_name(name),
        "gn_number": _normalize_staff_directory_code(gn_number),
        "specialty": _normalize_staff_directory_specialty(specialty),
        "is_active": is_active,
    }



def _search_physicians_directory(query: str = "", active_only: bool = False, limit: int = 500):
    ensure_admission_picklists_schema()
    limit = max(1, min(int(limit or 500), 5000))

    db = get_db()
    cur = db.cursor()
    sql = (
        "SELECT id, value, extra, is_active "
        "FROM admission_order_picklists WHERE category='doctor'"
    )
    params = []
    if active_only:
        sql += " AND is_active=1"
    if (query or "").strip():
        term = _directory_search_term(query)
        if DB_ENGINE == "postgres":
            sql += " AND (COALESCE(value,'') ILIKE ? OR COALESCE(label,'') ILIKE ? OR COALESCE(extra,'') ILIKE ?)"
        else:
            sql += " AND (LOWER(COALESCE(value,'')) LIKE ? OR LOWER(COALESCE(label,'')) LIKE ? OR LOWER(COALESCE(extra,'')) LIKE ?)"
        params.extend([term, term, term])
    sql += " ORDER BY is_active DESC, COALESCE(label,value), value LIMIT ?"
    params.append(limit)

    try:
        rows = cur.execute(sql, tuple(params)).fetchall()
    except Exception as search_exc:
        _log_noncritical_exception("_search_physicians_directory", search_exc)
        return []

    out = []
    for row in rows or []:
        item = _physician_directory_row_to_dict(row)
        if item:
            out.append(item)
    return out



def _save_physician_directory_entry(name: str, gd_number: str = "", specialty: str = "", actor: str = "SYSTEM", item_id=None):
    ensure_admission_picklists_schema()

    clean_name = _normalize_staff_directory_name(name)
    gd_number = _normalize_staff_directory_code(gd_number)
    specialty = _normalize_staff_directory_specialty(specialty)
    if not clean_name:
        return False, None, "Physician name is required."

    extra = doctor_extra_pack(gd_number, specialty)
    db = get_db()
    cur = db.cursor()
    actor = (actor or session.get("username") or "SYSTEM").strip() or "SYSTEM"
    now_ts = now_display_str("%Y-%m-%d %H:%M:%S")
    item_id_int = None
    if item_id not in (None, "", 0):
        try:
            item_id_int = int(item_id)
        except Exception:
            return False, None, "Invalid physician id."

    try:
        existing_rows = cur.execute(
            "SELECT id, value FROM admission_order_picklists WHERE category='doctor'"
        ).fetchall() or []
        existing_id = None
        clean_key = _staff_name_match_key(clean_name)
        for row in existing_rows:
            try:
                row_id = int(row["id"])
                row_name = row["value"]
            except Exception:
                row_id = int(row[0])
                row_name = row[1] if len(row) > 1 else ""
            if _staff_name_match_key(row_name) == clean_key:
                if item_id_int is None or row_id != item_id_int:
                    existing_id = row_id
                    break

        if item_id_int is not None:
            if existing_id is not None:
                return False, None, "Duplicate physician name already exists."
            cur.execute(
                """
                UPDATE admission_order_picklists
                   SET value=?, label=?, extra=?, is_active=1
                 WHERE id=? AND category='doctor'
                """,
                (clean_name, clean_name, extra, item_id_int),
            )
            if getattr(cur, "rowcount", 0) == 0:
                return False, None, "Physician not found."
            row_id = item_id_int
        else:
            if existing_id is not None:
                cur.execute(
                    """
                    UPDATE admission_order_picklists
                       SET value=?, label=?, extra=?, is_active=1
                     WHERE id=? AND category='doctor'
                    """,
                    (clean_name, clean_name, extra, existing_id),
                )
                row_id = existing_id
            else:
                cur.execute(
                    """
                    INSERT INTO admission_order_picklists
                    (category, value, label, extra, is_active, created_at, created_by)
                    VALUES (?,?,?,?,?,?,?)
                    """,
                    ("doctor", clean_name, clean_name, extra, 1, now_ts, actor),
                )
                row_id = getattr(cur, "lastrowid", None)
                if not row_id:
                    row = cur.execute(
                        """
                        SELECT id FROM admission_order_picklists
                        WHERE category='doctor' AND value=?
                        ORDER BY id DESC LIMIT 1
                        """,
                        (clean_name,),
                    ).fetchone()
                    try:
                        row_id = int(row["id"]) if row is not None else None
                    except Exception:
                        row_id = int(row[0]) if row is not None else None

        db.commit()
        try:
            _get_physician_directory_maps(force=True)
        except Exception:
            pass
        row = None
        if row_id is not None:
            row = cur.execute(
                "SELECT id, value, extra, is_active FROM admission_order_picklists WHERE id=?",
                (row_id,),
            ).fetchone()
        try:
            log_action(
                "PHYSICIAN_DIRECTORY_SAVE",
                details=f"id={row_id or ''}|name={clean_name}|gd={gd_number}|specialty={specialty}",
            )
        except Exception:
            pass
        return True, _physician_directory_row_to_dict(row), ""
    except Exception as save_exc:
        _rollback_with_logging(db, "_save_physician_directory_entry")
        _log_critical_exception("_save_physician_directory_entry failed", save_exc)
        return False, None, str(save_exc)



def _search_nursing_directory(query: str = "", active_only: bool = False, limit: int = 500):
    ensure_nursing_directory_schema()
    limit = max(1, min(int(limit or 500), 5000))

    db = get_db()
