@app.route("/admin/logs")
@login_required
@role_required("admin")
def admin_logs():
    cur = get_db().cursor()

    visit_f = request.args.get("visit_id", "").strip()
    user_f = request.args.get("user", "").strip()
    dfrom = request.args.get("date_from", "").strip()
    dto = request.args.get("date_to", "").strip()

    sql = "SELECT * FROM activity_log WHERE 1=1"
    params = []
    if visit_f:
        sql += " AND visit_id LIKE ?"
        params.append(f"%{visit_f}%")
    if user_f:
        sql += " AND username=?"
        params.append(user_f)
    if dfrom:
        sql += " AND date(created_at) >= date(?)"
        params.append(dfrom)
    if dto:
        sql += " AND date(created_at) <= date(?)"
        params.append(dto)

    sql += " ORDER BY id DESC LIMIT 1000"
    logs = cur.execute(sql, params).fetchall()
    users = cur.execute(
        "SELECT DISTINCT username FROM activity_log ORDER BY username"
    ).fetchall()

    return render_template(
        "admin_logs.html",
        logs=logs,
        users=users,
        visit_f=visit_f,
        user_f=user_f,
        dfrom=dfrom,
        dto=dto,
    )


