@app.route("/admin/backup")
@login_required
@role_required("admin")
def admin_backup():
    """Download a backup. Default is full package: database + uploads."""
    mode = (request.args.get("mode") or request.args.get("scope") or "full").strip().lower()

    # Backward-compatible database-only download when explicitly requested.
    if mode in {"db", "database", "database_only"}:
        if DB_ENGINE == "postgres":
            fmt = (request.args.get("format") or "dump").strip().lower()
            path, err = postgres_backup_create(fmt=fmt)
            if not path:
                flash(f"Backup failed: {err}", "danger")
                return redirect(request.referrer or url_for("admin_panel"))
            fname = os.path.basename(path)
            log_action("BACKUP_DOWNLOAD_DB_ONLY", details=fname)
            return send_from_directory(BACKUP_FOLDER, fname, as_attachment=True)

        if not os.path.exists(DATABASE):
            return "DB not found", 404
        log_action("BACKUP_DOWNLOAD_DB_ONLY", details=os.path.basename(DATABASE))
        try:
            db_abs = os.path.abspath(DATABASE)
            db_dir = os.path.dirname(db_abs) or "."
            db_name = os.path.basename(db_abs)
            return send_from_directory(db_dir, db_name, as_attachment=True)
        except Exception:
            return send_from_directory(".", DATABASE, as_attachment=True)

    path, err = _create_full_patient_backup(fmt="dump", encrypt=True)
    if not path:
        flash(f"Backup failed: {err}", "danger")
        return redirect(request.referrer or url_for("admin_panel"))
    fname = os.path.basename(path)
    log_action("BACKUP_DOWNLOAD_FULL", details=fname)
    return send_from_directory(BACKUP_FOLDER, fname, as_attachment=True)


