@app.route("/admin/backup_file/<path:filename>")
@login_required
@role_required("admin")
def admin_backup_file(filename):
    """Download a specific backup file from BACKUP_FOLDER."""
    safe_name = secure_filename(filename)
    full_path = os.path.join(BACKUP_FOLDER, safe_name)
    if not os.path.exists(full_path):
        return "Backup not found", 404

    ext = os.path.splitext(safe_name)[1].lower()
    allowed = _backup_allowed_exts_for_engine(DB_ENGINE, include_package=True)
    if ext not in allowed:
        return "Invalid backup file", 400

    # Encrypted backup: decrypt on-the-fly (requires ED_FERNET_KEY)
    if ext == ".enc":
        f = _get_fernet()
        if not f:
            abort(400)
        try:
            import io as _io

            with open(full_path, "rb") as fp:
                enc = fp.read()
            dec = f.decrypt(enc)
            out_name = (
                safe_name[:-4] if safe_name.lower().endswith(".enc") else safe_name
            )
            return send_file(
                _io.BytesIO(dec), as_attachment=True, download_name=out_name
            )
        except Exception:
            abort(400)

    return send_from_directory(BACKUP_FOLDER, safe_name, as_attachment=True)


@app.route("/admin/restore_file/<path:filename>", methods=["GET", "POST"])
@login_required
@role_required("admin")
def admin_restore_file(filename):
    """Restore Backup directly from a selected backup file, with password confirmation."""
    safe_name = secure_filename(filename)
    src_path = os.path.join(BACKUP_FOLDER, safe_name)

    ext = os.path.splitext(safe_name)[1].lower()
    allowed = _backup_allowed_exts_for_engine(DB_ENGINE, include_package=True)
    if (not os.path.exists(src_path)) or (ext not in allowed):
        flash("Backup file not found or invalid.", "danger")
        return redirect(url_for("admin_restore"))

    if request.method == "POST":
        password = request.form.get("password", "").strip()
        user_id = session.get("user_id")
        if not user_id:
            flash("Please login again.", "danger")
            return redirect(url_for("login"))

        cur = get_db().cursor()
        u = cur.execute("SELECT * FROM users WHERE id=?", (user_id,)).fetchone()
        if not u or not check_password_hash(u["password_hash"], password):
            flash("Incorrect password. Restore cancelled.", "danger")
            return redirect(url_for("admin_restore_file", filename=filename))

            # --- Restore (Background Job) ---
        global RESTORE_CURRENT_JOB_ID

        # Prevent concurrent restores
        try:
            if RESTORE_IN_PROGRESS.is_set():
                flash(
                    "A restore operation is already running. Please wait for it to finish.",
                    "warning",
                )
                if RESTORE_CURRENT_JOB_ID:
                    return redirect(
                        url_for("admin_restore_job", job_id=RESTORE_CURRENT_JOB_ID)
                    )
                return redirect(url_for("admin_panel"))
        except Exception:
            pass

        # Log start (best effort; failures go to server log via log_action)
        log_action("BACKUP_RESTORE_START", details=safe_name)

        # Close current request DB connection early to avoid:
        # - SQLite file locks on Windows
        # - PostgreSQL sessions/locks delaying pg_restore
        try:
            close_db(None)
        except Exception:
            pass

        job_id = _restore_new_job_id()
        job = {
            "id": job_id,
            "filename": safe_name,
            "src_path": src_path,
            "engine": DB_ENGINE,
            "status": "queued",
            "step": "queued",
            "started_at": None,
            "finished_at": None,
            "message": "",
            "error": "",
        }

        try:
            with RESTORE_JOBS_LOCK:
                RESTORE_JOBS[job_id] = job
                RESTORE_CURRENT_JOB_ID = job_id
        except Exception:
            pass

        try:
            t = threading.Thread(target=_run_restore_job, args=(job_id,), daemon=True)
            t.start()
        except Exception as e:
            flash(f"Failed to start restore job: {e}", "danger")
            return redirect(url_for("admin_panel"))

        flash(
            "Restore started in background. Open the status page until it finishes.",
            "warning",
        )
        return redirect(url_for("admin_restore_job", job_id=job_id))

    # GET: show confirmation form
    return render_template("admin_restore_confirm.html", backup_name=safe_name)


@app.route("/admin/restore", methods=["GET", "POST"])
@login_required
@role_required("admin")
def admin_restore():
    """Restore Backup from uploaded backup file."""
    if request.method == "POST":
        file = request.files.get("file")
        if not file or file.filename == "":
            flash("Please choose a backup file.", "danger")
            return redirect(url_for("admin_restore"))

        filename = secure_filename(file.filename)
        ext = os.path.splitext(filename)[1].lower()
        allowed = _backup_allowed_exts_for_engine(DB_ENGINE, include_package=True)
        if ext not in allowed:
            if DB_ENGINE == "postgres":
                flash(
                    "Invalid file type. Please upload a .zip full backup package, or a legacy .dump/.sql backup file.",
                    "danger",
                )
            else:
                flash("Invalid file type. Please upload a .zip full backup package, or a legacy .db backup file.", "danger")
            return redirect(url_for("admin_restore"))

        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        saved_name = f"upload_{ts}_{filename}"
        temp_path = os.path.join(BACKUP_FOLDER, saved_name)
        file.save(temp_path)

        flash("Backup file uploaded. Please confirm restore.", "warning")
        return redirect(url_for("admin_restore_file", filename=saved_name))

    # GET: list available backup files (newest first)
    backups = []
    try:
        if os.path.isdir(BACKUP_FOLDER):
            allowed = _backup_allowed_exts_for_engine(DB_ENGINE, include_package=True)
            for fname in os.listdir(BACKUP_FOLDER):
                full = os.path.join(BACKUP_FOLDER, fname)
                if not os.path.isfile(full):
                    continue
                if os.path.splitext(fname)[1].lower() not in allowed:
                    continue
                st = os.stat(full)
                backups.append(
                    {
                        "name": fname,
                        "size_kb": st.st_size / 1024.0,
                        "mtime": datetime.fromtimestamp(st.st_mtime).strftime(
                            "%Y-%m-%d %H:%M:%S"
                        ),
                    }
                )
        backups.sort(key=lambda b: b["mtime"], reverse=True)
    except Exception:
        backups = []

    return render_template("admin_restore.html", backups=backups)


@app.route("/admin/restore_job/<job_id>")
@login_required
@role_required("admin")
def admin_restore_job(job_id):
    """Show a live status page for a background restore job.

    This page intentionally avoids DB access (so it works even while restore is running).
    """
    safe_job_id = re.sub(r"[^a-zA-Z0-9]", "", (job_id or ""))[:32]
    return f"""<!doctype html>
<html>
<head>
  <meta charset=\"utf-8\">
  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">
  <title>Restore Status</title>
  <link href=\"/static/vendor/bootstrap/bootstrap.min.css\" rel=\"stylesheet\">
</head>
<body class=\"p-3\">
  <div class=\"container\" style=\"max-width: 760px;\">
    <h4 class=\"mb-1\">Database Restore Status</h4>
    <div class=\"text-muted mb-3\">Job ID: <code>{safe_job_id}</code></div>

    <div id=\"statusBox\" class=\"alert alert-info\">Loading...</div>

    <div class=\"card p-3 mb-3\">
      <div class=\"d-flex gap-2 flex-wrap\">
        <a class=\"btn btn-secondary\" href=\"/admin/restore\">Back</a>
        <a class=\"btn btn-outline-primary\" href=\"/admin/panel\">Admin Panel</a>
      </div>
      <div class=\"text-muted small mt-2\">
        Tip: If restore finishes but you still see old data, restart the app/server (recommended).
      </div>
    </div>
  </div>

<script>
async function poll(){{
  try{{
    const r = await fetch('/admin/restore_status/{safe_job_id}', {{cache:'no-store'}});
    const j = await r.json();
    const box = document.getElementById('statusBox');
    if(!j || !j.ok){{
      box.className='alert alert-danger';
      box.textContent = (j && j.error) ? j.error : 'Failed to read status';
      return;
    }}
    const job = j.job || {{}};
    const status = job.status || 'unknown';
    const step = job.step || '';
    const msg = job.message || '';
    const err = job.error || '';
    const started = job.started_at || '';
    const finished = job.finished_at || '';

    let cls = 'alert alert-info';
    if(status === 'success') cls = 'alert alert-success';
    if(status === 'error') cls = 'alert alert-danger';
    if(status === 'running') cls = 'alert alert-warning';
    if(status === 'queued') cls = 'alert alert-secondary';

    box.className = cls;
    box.innerHTML =
      '<div><strong>Status:</strong> ' + status + '</div>' +
      (step ? '<div><strong>Step:</strong> ' + step + '</div>' : '') +
      (started ? '<div><strong>Started:</strong> ' + started + '</div>' : '') +
      (finished ? '<div><strong>Finished:</strong> ' + finished + '</div>' : '') +
      (msg ? '<div class=\"mt-2\">' + msg + '</div>' : '') +
      (err ? '<hr><pre style=\"white-space:pre-wrap; margin:0\">' + err + '</pre>' : '');
  }}catch(e){{
    const box = document.getElementById('statusBox');
    box.className='alert alert-danger';
    box.textContent = 'Error: ' + e;
  }}
}}
poll();
setInterval(poll, 2000);
</script>
</body>
</html>"""


@app.route("/admin/restore_status/<job_id>")
@login_required
@role_required("admin")
def admin_restore_status(job_id):
    """JSON status for a background restore job."""
    safe_job_id = re.sub(r"[^a-zA-Z0-9]", "", (job_id or ""))[:32]
    try:
        with RESTORE_JOBS_LOCK:
            job = RESTORE_JOBS.get(safe_job_id)
    except Exception:
        job = None

    if not job:
        return jsonify(ok=False, error="Restore job not found."), 404

    out = dict(job)
    # Hide internal file paths from the UI response
    out.pop("src_path", None)

    return jsonify(
        ok=True,
        job=out,
        in_progress=RESTORE_IN_PROGRESS.is_set(),
        current_job_id=RESTORE_CURRENT_JOB_ID,
    )


# ============================================================
# Register / Search
# ============================================================


_DUPLICATE_MATCH_ORDER = {"exact": 0, "strong": 1, "possible": 2, "weak": 3}
_CLOSED_VISIT_STATUSES = ("DISCHARGED", "TRANSFERRED", "LAMA", "EXPIRED", "CANCELLED", "CLOSED")


def _dupe_strength_rank(value):
    return _DUPLICATE_MATCH_ORDER.get((value or "").lower(), 9)


def _row_value(row, key, idx=None, default=""):
    try:
        val = row[key]
    except Exception:
        try:
            val = row[idx] if idx is not None else default
        except Exception:
            val = default
    return default if val is None else val


def _clinic_label_from_code(code):
    return _clinic_row_label_lookup(code)


def _collect_patient_match_rows(
    cur,
    *,
    mrn="",
    id_number="",
    phone="",
    dob="",
    name="",
    clinic="",
    include_phone_only=True,
    limit=10,
):
    """Collect likely duplicate / existing patient matches with visit context.

    The patient record stays single. Visits may exist in different clinics.
    Only an open visit in the *same* clinic should block a new registration.
    """
    mrn = (mrn or "").strip()
    id_number = (id_number or "").strip()
    phone = (phone or "").strip()
    dob = normalize_dob_input(dob) or (dob or "").strip()
    name = (name or "").strip()
    clinic = (clinic or "").strip().upper()

    matches_by_pid = {}

    def _merge_rows(rows, strength, reason):
        for r in rows or []:
            pid = _row_value(r, "id", 0, None)
            if pid in (None, ""):
                continue
            try:
                pid = int(pid)
            except Exception:
                continue

            item = matches_by_pid.get(pid) or {
                "id": pid,
                "name": _row_value(r, "name", 1, ""),
                "mrn": _row_value(r, "mrn", 2, ""),
                "id_number": _row_value(r, "id_number", 3, ""),
                "phone": _row_value(r, "phone", 4, ""),
                "dob": _row_value(r, "dob", 5, ""),
                "match_strength": strength,
                "match_reason": reason,
                "last_visit_id": "",
                "last_visit_status": "",
                "last_visit_clinic": "",
                "last_visit_clinic_label": "",
                "open_in_clinic_visit_id": "",
                "open_visits": [],
                "open_visit_count": 0,
                "has_open_visits": False,
                "current_clinic": clinic,
                "current_clinic_label": _clinic_label_from_code(clinic),
                "recommended_action": "review",
            }

            if _dupe_strength_rank(strength) < _dupe_strength_rank(item.get("match_strength")):
                item["match_strength"] = strength
                item["match_reason"] = reason

            # Refresh patient demographics if a stronger query returned more complete data.
            for key in ("name", "mrn", "id_number", "phone", "dob"):
                if not item.get(key):
                    item[key] = _row_value(r, key, {"name":1,"mrn":2,"id_number":3,"phone":4,"dob":5}.get(key), "")

            matches_by_pid[pid] = item

    try:
        if mrn:
            _merge_rows(
                cur.execute(
                    """
                    SELECT id, name, mrn, id_number, phone, dob
                    FROM patients
                    WHERE mrn=?
                    ORDER BY id DESC
                    LIMIT ?
                    """,
                    (mrn, limit),
                ).fetchall(),
                "exact",
                "Exact MRN match",
            )
    except Exception:
        pass

    try:
        if id_number:
            _merge_rows(
                cur.execute(
                    """
                    SELECT id, name, mrn, id_number, phone, dob
                    FROM patients
                    WHERE id_number=?
                    ORDER BY id DESC
                    LIMIT ?
                    """,
                    (id_number, limit),
                ).fetchall(),
                "exact",
                "Exact ID number match",
            )
    except Exception:
        pass

    try:
        if phone and dob:
            _merge_rows(
                cur.execute(
                    """
                    SELECT id, name, mrn, id_number, phone, dob
                    FROM patients
                    WHERE phone=? AND dob=?
                    ORDER BY id DESC
                    LIMIT ?
                    """,
                    (phone, dob, limit),
                ).fetchall(),
                "strong",
                "Strong match: same phone and DOB",
            )
    except Exception:
        pass

    try:
        if name and dob:
            _merge_rows(
                cur.execute(
                    """
                    SELECT id, name, mrn, id_number, phone, dob
                    FROM patients
                    WHERE UPPER(name) LIKE UPPER(?)
                      AND dob=?
                    ORDER BY id DESC
                    LIMIT ?
                    """,
                    (f"%{name}%", dob, limit),
                ).fetchall(),
                "possible",
                "Possible match: similar name and DOB",
            )
        elif include_phone_only and phone:
            _merge_rows(
                cur.execute(
                    """
                    SELECT id, name, mrn, id_number, phone, dob
                    FROM patients
                    WHERE phone=?
                    ORDER BY id DESC
                    LIMIT ?
                    """,
                    (phone, limit),
                ).fetchall(),
                "weak",
                "Possible match: same phone number",
            )
    except Exception:
        pass

    for pid, item in list(matches_by_pid.items()):
        try:
            latest = cur.execute(
                """
                SELECT visit_id, status, clinic, created_at
                FROM visits
                WHERE patient_id=?
                ORDER BY id DESC
                LIMIT 1
                """,
                (pid,),
            ).fetchone()
        except Exception:
            latest = None
        if latest:
            item["last_visit_id"] = _row_value(latest, "visit_id", 0, "")
            item["last_visit_status"] = _row_value(latest, "status", 1, "")
            item["last_visit_clinic"] = (_row_value(latest, "clinic", 2, "") or "").strip().upper()
            item["last_visit_clinic_label"] = _clinic_label_from_code(item["last_visit_clinic"])

        open_visits = []
        try:
            open_rows = cur.execute(
                """
                SELECT visit_id, status, clinic, created_at
                FROM visits
                WHERE patient_id=?
                  AND (status IS NULL OR UPPER(status) NOT IN ('DISCHARGED','TRANSFERRED','LAMA','EXPIRED','CANCELLED','CLOSED'))
                ORDER BY id DESC
                LIMIT 6
                """,
                (pid,),
            ).fetchall()
        except Exception:
            open_rows = []

        for ov in open_rows or []:
            visit_id = _row_value(ov, "visit_id", 0, "")
            status = _row_value(ov, "status", 1, "")
            clinic_code = (_row_value(ov, "clinic", 2, "") or "ED").strip().upper()
            visit_item = {
                "visit_id": visit_id,
                "status": status,
                "clinic_code": clinic_code,
                "clinic_label": _clinic_label_from_code(clinic_code),
                "created_at": _row_value(ov, "created_at", 3, ""),
            }
            open_visits.append(visit_item)
            if clinic and clinic_code == clinic and not item.get("open_in_clinic_visit_id"):
                item["open_in_clinic_visit_id"] = visit_id

        item["open_visits"] = open_visits
        item["open_visit_count"] = len(open_visits)
        item["has_open_visits"] = bool(open_visits)

        if item.get("open_in_clinic_visit_id"):
            item["recommended_action"] = "open_existing_case"
        elif item.get("match_strength") in ("exact", "strong") or item.get("has_open_visits"):
            item["recommended_action"] = "use_existing_patient"
        else:
            item["recommended_action"] = "review"

        item["is_exact"] = item.get("match_strength") == "exact"
        item["is_strong"] = item.get("match_strength") in ("exact", "strong")
        item["same_clinic_open"] = bool(item.get("open_in_clinic_visit_id"))

    return sorted(
        matches_by_pid.values(),
        key=lambda m: (
            _dupe_strength_rank(m.get("match_strength")),
            0 if m.get("open_in_clinic_visit_id") else 1,
            0 if m.get("has_open_visits") else 1,
            (m.get("name") or "").lower(),
        ),
    )[:limit]


def _attachment_async_enabled() -> bool:
    try:
        raw = os.environ.get("ATTACHMENT_ASYNC_ENABLED", APP_CONFIG.get("ATTACHMENT_ASYNC_ENABLED", True))
        return str(raw).strip().lower() not in ("0", "false", "no", "off")
    except Exception:
        return True


def _attachment_async_max_bytes() -> int:
    try:
        raw = os.environ.get("ATTACHMENT_ASYNC_MAX_BYTES", APP_CONFIG.get("ATTACHMENT_ASYNC_MAX_BYTES", 8 * 1024 * 1024))
        return max(256 * 1024, int(raw or (8 * 1024 * 1024)))
    except Exception:
        return 8 * 1024 * 1024


def _standalone_attachment_db_insert(visit_id, filename, actor, uploaded_at):
    if DB_ENGINE == "postgres":
        from db import pool_getconn, pool_putconn

        conn = None
        try:
            conn = pool_getconn(timeout_s=1.5)
            conn.autocommit = False
            cur = PostgresDBWrapper(conn).cursor()
            cur.execute(
                """
                INSERT INTO attachments (visit_id, filename, uploaded_at, uploaded_by)
                VALUES (?,?,?,?)
                """,
                (visit_id, filename, uploaded_at, actor),
            )
            conn.commit()
            return True
        finally:
            if conn is not None:
                try:
                    pool_putconn(conn)
                except Exception:
                    pass

    conn = None
    try:
        conn = sqlite3.connect(DATABASE, check_same_thread=False)
        conn.execute(
            """
            INSERT INTO attachments (visit_id, filename, uploaded_at, uploaded_by)
            VALUES (?,?,?,?)
            """,
            (visit_id, filename, uploaded_at, actor),
        )
        conn.commit()
        return True
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _atomic_write_bytes(path, data: bytes):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp_path = f"{path}.tmp.{os.getpid()}.{threading.get_ident()}"
    with open(tmp_path, "wb") as fh:
        fh.write(data)
        fh.flush()
    os.replace(tmp_path, path)


def _capture_filestorage_bytes_for_async(file_storage, max_bytes: int):
    try:
        size_hint = getattr(file_storage, "content_length", None)
        if size_hint and int(size_hint) > int(max_bytes):
            return None
    except Exception:
        pass
    try:
        data = file_storage.read(int(max_bytes) + 1)
        if data is None:
            data = b""
        if len(data) > int(max_bytes):
            try:
                file_storage.stream.seek(0)
            except Exception:
                pass
            return None
        return data
    except Exception:
        try:
            file_storage.stream.seek(0)
        except Exception:
            pass
        return None



# ============================================================
# ATTACHMENT PATIENT STICKER PATCH (2026-05-25)
# - Adds a non-covering header band to lab/radiology PDF attachments.
# - The original page content is kept intact and shifted below a new margin.
# - Safe fallback: if PDF stamping is unavailable/fails, the original file is served/saved.
# ============================================================
def _attachment_pdf_sticker_target_v20260525(filename, context=""):
    try:
        fn = str(filename or "")
        if os.path.splitext(fn)[1].lower() != ".pdf":
            return False
        up = fn.upper()
        ctx = str(context or "").upper()
        # Do not alter administrative identity/eligibility PDFs.
        if any(tok in up for tok in ("_ID_", "_ELIG_", "ELIGIBILITY", "INSURANCE", "PASSPORT", "NATIONAL_ID", "EMIRATES_ID")):
            return False
        clinical_tokens = (
            "_LAB_", "LAB_AUTO", "LABRESULT", "LAB_RESULT", "LAB-", "LAB ",
            "_RAD_", "RADIOLOGY", "XRAY", "X-RAY", "X_RAY", " CT", "CT_", "MRI", "ULTRASOUND", "SCAN", "RESULT",
        )
        if any(tok in up for tok in clinical_tokens):
            return True
        if any(tok in ctx for tok in ("LAB", "RADIOLOGY", "XRAY", "X-RAY", "SCAN", "IMAGING")):
            return True
    except Exception:
        return False
    return False


def _attachment_sticker_row_get_v20260525(row, key, default=""):
    try:
        return _pdf_row_get(row, key, default)
    except Exception:
        try:
            value = row[key]
            return default if value is None else value
        except Exception:
            try:
                value = row.get(key, default)
                return default if value is None else value
            except Exception:
                return default


def _attachment_fetch_patient_sticker_context_v20260525(visit_id, cur=None):
    ctx = {"visit_id": str(visit_id or "").strip()}
    if not ctx["visit_id"]:
        return ctx
    close_db_after = False
    try:
        if cur is None:
            cur = get_db().cursor()
        row = cur.execute(
            """
            SELECT v.visit_id, COALESCE(v.clinic,'') AS clinic, COALESCE(v.location,'') AS location,
                   COALESCE(v.bed_no,'') AS bed_no, COALESCE(v.created_at,'') AS visit_created_at,
                   p.name, p.mrn, p.cerner_mrn, p.id_number, p.dob, p.sex
            FROM visits v
            JOIN patients p ON p.id = v.patient_id
            WHERE v.visit_id=?
            LIMIT 1
            """,
            (ctx["visit_id"],),
        ).fetchone()
        if row:
            for key in ("name", "mrn", "cerner_mrn", "id_number", "dob", "sex", "clinic", "location", "bed_no", "visit_created_at"):
                ctx[key] = str(_attachment_sticker_row_get_v20260525(row, key, "") or "").strip()
    except Exception as exc:
        try:
            _log_noncritical_exception(f"Attachment sticker patient context failed visit={visit_id}", exc)
        except Exception:
            pass
    finally:
        if close_db_after:
            try:
                cur.close()
            except Exception:
                pass
    return ctx


def _attachment_sticker_text_v20260525(value, max_len=90):
    value = re.sub(r"\s+", " ", str(value or "")).strip()
    if len(value) > max_len:
        return value[: max_len - 1] + "…"
    return value


def _attachment_pdf_overlay_page_v20260525(width, original_height, header_h, ctx, filename, page_no, page_count):
    buf = io.BytesIO()
    total_h = float(original_height) + float(header_h)
    c = canvas.Canvas(buf, pagesize=(float(width), total_h))
    try:
        c.setFillColor(colors.white)
        c.rect(0, original_height, width, header_h, fill=1, stroke=0)
        c.setStrokeColor(colors.HexColor("#9AA8B7"))
        c.setLineWidth(0.6)
        pad_x = 0.55 * cm
        pad_y = 0.18 * cm
        c.roundRect(pad_x, original_height + pad_y, width - 2 * pad_x, header_h - 2 * pad_y, 6, fill=0, stroke=1)
        c.setFillColor(colors.black)
        title = "PATIENT STICKER - ED DOWNTIME"
        case_no = _attachment_sticker_text_v20260525(ctx.get("visit_id") or "-", 40)
        name = _attachment_sticker_text_v20260525(ctx.get("name") or "-", 58)
        mrn = _attachment_sticker_text_v20260525(ctx.get("mrn") or "-", 34)
        cerner = _attachment_sticker_text_v20260525(ctx.get("cerner_mrn") or "", 34)
        pid = _attachment_sticker_text_v20260525(ctx.get("id_number") or "-", 34)
        dob = _attachment_sticker_text_v20260525(ctx.get("dob") or "-", 20)
        sex = _attachment_sticker_text_v20260525(ctx.get("sex") or "-", 12)
        clinic = _attachment_sticker_text_v20260525(ctx.get("clinic") or "-", 18)
        loc_parts = [ctx.get("location") or "", ctx.get("bed_no") or ""]
        loc = _attachment_sticker_text_v20260525(" / ".join([p for p in loc_parts if p]) or "-", 32)
        doc_type = "LAB" if "LAB" in str(filename or "").upper() else ("RAD" if "RAD" in str(filename or "").upper() else "ATTACHMENT")
        y = total_h - 0.42 * cm
        c.setFont("Helvetica-Bold", 8.4)
        c.drawString(0.8 * cm, y, f"{title}   |   {doc_type}   |   Case: {case_no}")
        c.drawRightString(width - 0.8 * cm, y, f"Page {page_no}/{page_count}")
        y -= 0.34 * cm
        c.setFont("Helvetica-Bold", 7.4)
        c.drawString(0.8 * cm, y, f"Name: {name}")
        c.setFont("Helvetica", 7.4)
        c.drawRightString(width - 0.8 * cm, y, f"MRN: {mrn}" + (f"   Cerner: {cerner}" if cerner else ""))
        y -= 0.30 * cm
        c.drawString(0.8 * cm, y, f"ID: {pid}   DOB: {dob}   Sex: {sex}")
        c.drawRightString(width - 0.8 * cm, y, f"Clinic: {clinic}   Location: {loc}")
    except Exception:
        # Keep overlay generation non-blocking; a plain text fallback is enough.
        c.setFillColor(colors.white)
        c.rect(0, original_height, width, header_h, fill=1, stroke=0)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 8)
        c.drawString(0.8 * cm, total_h - 0.55 * cm, f"PATIENT STICKER | Case: {ctx.get('visit_id') or '-'} | MRN: {ctx.get('mrn') or '-'}")
    c.save()
    return buf.getvalue()


def _sticker_pdf_bytes_for_attachment_v20260525(pdf_bytes, visit_id, filename, patient_context=None):
    if not pdf_bytes or not bytes(pdf_bytes).lstrip().startswith(b"%PDF"):
        return pdf_bytes
    try:
        try:
            from pypdf import PdfReader, PdfWriter
        except Exception:
            from PyPDF2 import PdfReader, PdfWriter
        reader = PdfReader(io.BytesIO(pdf_bytes))
        try:
            meta = reader.metadata or {}
            if str(meta.get("/EDDowntimePatientSticker") or "") == "1":
                return pdf_bytes
        except Exception:
            pass
        if getattr(reader, "is_encrypted", False):
            try:
                reader.decrypt("")
            except Exception:
                return pdf_bytes
        pages = list(reader.pages or [])
        if not pages:
            return pdf_bytes
        ctx = dict(patient_context or {})
        if visit_id and not ctx.get("visit_id"):
            ctx["visit_id"] = str(visit_id)
        writer = PdfWriter()
        total = len(pages)
        for idx, page in enumerate(pages, start=1):
            try:
                width = float(page.mediabox.width)
                height = float(page.mediabox.height)
            except Exception:
                width, height = A4
            header_h = max(1.35 * cm, min(1.75 * cm, height * 0.075))
            new_page = writer.add_blank_page(width=width, height=height + header_h)
            try:
                new_page.merge_page(page)
            except Exception:
                writer.add_page(page)
                continue
            overlay_bytes = _attachment_pdf_overlay_page_v20260525(width, height, header_h, ctx, filename, idx, total)
            overlay_page = PdfReader(io.BytesIO(overlay_bytes)).pages[0]
            new_page.merge_page(overlay_page)
        try:
            writer.add_metadata({"/EDDowntimePatientSticker": "1", "/Producer": "ED Downtime Patient Sticker"})
        except Exception:
            pass
        out = io.BytesIO()
        writer.write(out)
        stamped = out.getvalue()
        return stamped or pdf_bytes
    except Exception as exc:
        try:
            _log_noncritical_exception(f"Attachment PDF patient sticker failed visit={visit_id} filename={filename}", exc)
        except Exception:
            pass
        return pdf_bytes


def _prepare_attachment_bytes_for_patient_sticker_v20260525(visit_id, filename, data, context="attachment", patient_context=None):
    try:
        if not data or not _attachment_pdf_sticker_target_v20260525(filename, context=context):
            return data
        if not bytes(data).lstrip().startswith(b"%PDF"):
            return data
        ctx = dict(patient_context or {})
        if not ctx:
            ctx = _attachment_fetch_patient_sticker_context_v20260525(visit_id)
        return _sticker_pdf_bytes_for_attachment_v20260525(data, visit_id, filename, patient_context=ctx)
    except Exception as exc:
        try:
            _log_noncritical_exception(f"Attachment sticker prepare failed visit={visit_id} filename={filename}", exc)
        except Exception:
            pass
        return data

def _persist_attachment_bytes(visit_id, filename, data: bytes, actor, context="attachment"):
    save_path = os.path.join(UPLOAD_FOLDER, filename)
    uploaded_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    file_saved = False
    try:
        data = _prepare_attachment_bytes_for_patient_sticker_v20260525(visit_id, filename, data, context=context)
        _atomic_write_bytes(save_path, data)
        file_saved = True
        _standalone_attachment_db_insert(visit_id, filename, actor, uploaded_at)
        return True
    except Exception as e:
        if file_saved:
            try:
                os.remove(save_path)
            except Exception:
                pass
        _log_noncritical_exception(f"{context} attachment save failed visit_id={visit_id} filename={filename}", e)
        raise


def _save_attachment_with_optional_async(visit_id, file_storage, filename, actor, *, context="attachment"):
    if not file_storage or not getattr(file_storage, "filename", ""):
        return "No file selected."
    if not allowed_file(file_storage.filename):
        return "Attachment file type is not allowed."

    needs_patient_sticker = _attachment_pdf_sticker_target_v20260525(filename, context=context)

    if _attachment_async_enabled() and not needs_patient_sticker:
        data = _capture_filestorage_bytes_for_async(file_storage, _attachment_async_max_bytes())
        if data is not None:
            try:
                BG_EXECUTOR.submit(_persist_attachment_bytes, visit_id, filename, data, actor, context)
                return None
            except Exception as e:
                _log_noncritical_exception(f"{context} attachment queue failed visit_id={visit_id} filename={filename}", e)

    save_path = os.path.join(UPLOAD_FOLDER, filename)
    file_saved = False
    db = get_db()
    try:
        os.makedirs(UPLOAD_FOLDER, exist_ok=True)
        if needs_patient_sticker:
            try:
                try:
                    file_storage.stream.seek(0)
                except Exception:
                    pass
                data = file_storage.read()
                data = _prepare_attachment_bytes_for_patient_sticker_v20260525(visit_id, filename, data, context=context)
                _atomic_write_bytes(save_path, data)
            finally:
                try:
                    file_storage.stream.seek(0)
                except Exception:
                    pass
        else:
            file_storage.save(save_path)
        file_saved = True
        db.execute(
            """
            INSERT INTO attachments (visit_id, filename, uploaded_at, uploaded_by)
            VALUES (?,?,?,?)
            """,
            (
                visit_id,
                filename,
                datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                actor,
            ),
        )
        db.commit()
        return None
    except Exception as e:
        try:
            db.rollback()
        except Exception:
            pass
        if file_saved:
            try:
                os.remove(save_path)
            except Exception:
                pass
        _log_noncritical_exception(f"{context} attachment sync save failed visit_id={visit_id} filename={filename}", e)
        return "Failed to save attachment."


def _save_register_attachment_after_commit(visit_id, file_storage, file_tag, actor):
    """Persist an uploaded register attachment after the visit transaction commits."""
    if not file_storage or not getattr(file_storage, "filename", ""):
        return None

    filename_original = file_storage.filename
    if not allowed_file(filename_original):
        return "Attachment file type is not allowed."

    safe_name = secure_filename(filename_original)
    filename = f"{visit_id}_{int(datetime.now().timestamp())}_{file_tag}_{safe_name}"
    return _save_attachment_with_optional_async(
        visit_id,
        file_storage,
        filename,
        actor,
        context=f"register_{file_tag.lower()}",
    )


def _cfg_float_runtime(key: str, default: float) -> float:
    try:
        v = APP_CONFIG.get(key, default)
        if v is None:
            return float(default)
        if isinstance(v, (int, float)):
            return float(v)
        s = str(v).strip()
        if not s:
            return float(default)
        return float(s)
    except Exception:
        return float(default)


def _cfg_bool_runtime(key: str, default: bool) -> bool:
    try:
        v = APP_CONFIG.get(key, default)
        if isinstance(v, bool):
            return v
        s = str(v).strip().lower()
        if s in ("1", "true", "yes", "y", "on"):
            return True
        if s in ("0", "false", "no", "n", "off"):
            return False
    except Exception:
        pass
    return bool(default)


def _build_register_reference_data():
    """Warm shared reference data for /register so GET does not hammer PostgreSQL."""
    visit_type_options = get_system_picklist_options("visit_type")
    service_category_options = get_system_picklist_options("service_category")
    insurance_provider_options = get_system_picklist_options("insurance_provider")
    insurance_plan_options = get_system_picklist_options("insurance_plan")
    contract_schemes = get_contract_schemes(active_only=True)
    clinics = get_clinics_for_ui()

    doctor_options = []
    try:
        cur = get_db().cursor()
        seen = set()

        try:
            rows = cur.execute(
                "SELECT username, gd_number FROM users WHERE is_active=1 AND role IN ('doctor','admin') ORDER BY username"
            ).fetchall()
        except Exception:
            rows = []

        for r in rows or []:
            try:
                username = (r["username"] or "").strip()
                gd = (r["gd_number"] or "").strip()
            except Exception:
                username = (r[0] or "").strip()
                gd = (r[1] or "").strip() if len(r) > 1 else ""

            if not username:
                continue

            name_in_dir = _physician_directory_lookup_by_gd(cur, gd) if gd else ""
            if not name_in_dir:
                continue

            key = name_in_dir.lower()
            if key in seen:
                continue
            seen.add(key)
            doctor_options.append({"value": username, "label": name_in_dir})

        try:
            for d in picklist_get_doctors():
                username = (d.get("username") or "").strip()
                gd = (d.get("gd_number") or "").strip()
                if not username:
                    continue

                key = username.lower()
                if key in seen:
                    continue
                seen.add(key)

                spec = (d.get("specialty") or "").strip()
                name_in_dir = _physician_directory_lookup_by_gd(cur, gd) if gd else ""
                if not name_in_dir:
                    continue
                label = f"{name_in_dir} - {spec}" if spec else name_in_dir
                doctor_options.append({"value": username, "label": label})
        except Exception:
            pass

        doctor_options.sort(key=lambda x: (x.get("value") or "").lower())
    except Exception:
        doctor_options = []

    return {
        "visit_type_options": visit_type_options,
        "service_category_options": service_category_options,
        "insurance_provider_options": insurance_provider_options,
        "insurance_plan_options": insurance_plan_options,
        "contract_schemes": contract_schemes,
        "doctor_options": doctor_options,
        "clinics": clinics,
    }


def get_register_reference_data():
    ttl = _cfg_float_runtime("REGISTER_FORM_CACHE_SECONDS", 30.0)
    try:
        key = ("register_reference_data", str(DB_ENGINE or ""))
        if ttl and ttl > 0:
            return _REG_FORM_CACHE.get_or_compute(key, ttl, _build_register_reference_data)
    except Exception:
        pass
    return _build_register_reference_data()


def _build_clinical_order_catalogs():
    cur = get_db().cursor()

    def _rows(sql):
        try:
            rows = cur.execute(sql).fetchall()
        except Exception:
            rows = []
        out = []
        for r in rows or []:
            try:
                out.append(dict(r))
            except Exception:
                try:
                    out.append(_row_to_dict(r, cur) or {})
                except Exception:
                    out.append({})
        return out

    return {
        "rad_items": _rows("SELECT * FROM items_radiology WHERE is_active=1 ORDER BY COALESCE(sort_order, 9999), name"),
        "lab_items": _rows("SELECT * FROM items_labs WHERE is_active=1 ORDER BY COALESCE(sort_order, 9999), name"),
        "med_items": _rows("SELECT * FROM items_medications WHERE is_active=1 ORDER BY COALESCE(sort_order, 9999), name"),
        "home_med_items": _rows("SELECT * FROM items_home_meds WHERE is_active=1 ORDER BY COALESCE(sort_order, 9999), name"),
    }


def get_clinical_order_catalogs():
    ttl = _cfg_float_runtime("CLINICAL_ORDER_CATALOG_CACHE_SECONDS", 300.0)
    try:
        key = ("clinical_order_catalogs", str(DB_ENGINE or ""))
        if ttl and ttl > 0:
            return _REG_FORM_CACHE.get_or_compute(key, ttl, _build_clinical_order_catalogs)
    except Exception:
        pass
    return _build_clinical_order_catalogs()


# Duplicate route retired 20260610: enterprise handler is canonical for /register.
# @app.route("/register", methods=["GET", "POST"])
@login_required
def register_patient():
    # Ensure schemas (safe / idempotent)
    try:
        ensure_patients_extra_schema()
    except Exception:
        pass
    try:
        ensure_patient_centric_schema()
    except Exception as patient_centric_exc:
        _log_noncritical_exception("register_patient: ensure_patient_centric_schema", patient_centric_exc)
    try:
        ensure_clinic_schema()
    except Exception:
        pass
    try:
        ensure_visit_financial_schema()
    except Exception:
        pass
    try:
        ensure_contract_schemes_schema()
    except Exception:
        pass

    # Warm shared register reference data once per short TTL to avoid hammering DB on GET.
    _register_ref = get_register_reference_data()
    visit_type_options = list(_register_ref.get("visit_type_options") or [])
    service_category_options = list(_register_ref.get("service_category_options") or [])
    insurance_provider_options = list(_register_ref.get("insurance_provider_options") or [])
    insurance_plan_options = list(_register_ref.get("insurance_plan_options") or [])
    contract_schemes = list(_register_ref.get("contract_schemes") or [])
    doctor_options = list(_register_ref.get("doctor_options") or [])
    clinics_ui = list(_register_ref.get("clinics") or get_clinics_for_ui())

    # Clinic from query (preselect) or from POST
    clinic_initial = (request.args.get("clinic") or "ED").upper()

    # Helper to render (so we keep dropdowns on validation errors)
    def _render(form=None, dupe_matches=None):
        try:
            close_db(None)
        except Exception:
            pass
        return render_template(
            "register.html",
            clinic_initial=clinic_initial,
            clinics=clinics_ui,
            visit_type_options=visit_type_options,
            service_category_options=service_category_options,
            insurance_provider_options=insurance_provider_options,
            insurance_plan_options=insurance_plan_options,
            doctor_options=doctor_options,
            contract_schemes=contract_schemes,
            form=form or {},
            dupe_matches=dupe_matches or [],
        )

    if request.method == "POST":
        # ---------------------------
        # Collect form fields
        # ---------------------------
        form = {}

        def _get(k, default=""):
            v = request.form.get(k, default)
            return (v or "").strip()

        # Demographics
        form["name"] = _get("name")
        form["mrn"] = _get("mrn")
        form["id_number"] = _get("id_number")
        form["phone"] = _get("phone")
        form["email"] = _get("email")
        raw_dob = _get("dob")
        dob_norm = normalize_dob_input(raw_dob)
        dob_invalid = bool(raw_dob and not dob_norm)
        form["dob"] = dob_norm or raw_dob
        form["sex"] = _get("sex")
        form["nationality"] = _get("nationality")
        form["nok_name"] = _get("nok_name")
        form["nok_relation"] = _get("nok_relation")
        form["nok_phone"] = _get("nok_phone")

        # Encounter / visit
        form["visit_type"] = (_get("visit_type", "NEW") or "NEW").upper()
        form["service_category"] = _get("service_category")
        form["clinic"] = (_get("clinic", clinic_initial or "ED") or "ED").upper()
        form["assigned_doctor"] = _get("assigned_doctor")

        # IP admission fields (only for IPADM)
        form["ward"] = _get("ward")
        form["bed_no"] = _get("bed_no")
        form["admission_type"] = _get("admission_type")
        form["approval_no"] = _get("approval_no")

        # Insurance / policy
        form["insurance"] = _get("insurance")  # provider/company
        form["insurance_no"] = _get("insurance_no")  # member/card no
        form["ins_plan"] = _get("ins_plan")
        form["ins_card_no"] = _get("ins_card_no") or form.get("insurance_no", "")
        form["dha_member_id"] = _get("dha_member_id")
        form["policy_no"] = _get("policy_no")
        form["policy_name"] = _get("policy_name")
        form["valid_from"] = _get("valid_from")
        form["valid_to"] = _get("valid_to")
        form["eligibility_status"] = _get("eligibility_status")
        form["eligibility_notes"] = _get("eligibility_notes")

        # Financial / payment
        form["payment_method"] = _get("payment_method")
        form["receipt_no"] = _get("receipt_no")
        form["copay_amount"] = _get("copay_amount")
        form["payment_notes"] = _get("payment_notes")
        form["contract_scheme_id"] = _get("contract_scheme_id")

        # Contract scheme (snapshot values stored on the visit)
        # Consultation deductible
        form["consult_deduct_percent"] = _get("consult_deduct_percent")
        form["consult_deduct_amount"] = _get("consult_deduct_amount")

        # Service buckets
        for key in [
            "lab",
            "radiology",
            "investigation",
            "inpatient",
            "pharmacy",
            "dental",
        ]:
            form[f"{key}_percent"] = _get(f"{key}_percent")
            form[f"{key}_amount"] = _get(f"{key}_amount")

        # Misc flags
        existing_patient_id = _get("existing_patient_id")
        form["existing_patient_id"] = existing_patient_id
        force_new_patient = str(_get("force_new_patient") or "").strip().lower() in (
            "1",
            "true",
            "yes",
            "y",
            "on",
        )
        form["force_new_patient"] = "1" if force_new_patient else ""

        # Files (eligibility / patient ID attachments)
        elig_file = request.files.get("eligibility_file")
        id_file = request.files.get("id_file")

        # ---------------------------
        # Basic validation
        # ---------------------------
        if not form["name"]:
            flash("Patient name is required.", "danger")
            return _render(form=form)

        if not form["phone"]:
            flash("Patient phone is required.", "danger")
            return _render(form=form)

        if dob_invalid:
            flash("DOB format is invalid. Use YYYY-MM-DD or DD/MM/YYYY.", "danger")
            return _render(form=form)

        if not form["dob"]:
            flash("DOB is required.", "danger")
            return _render(form=form)

        if not form["sex"]:
            flash("Sex is required.", "danger")
            return _render(form=form)

        if not form["nationality"]:
            flash("Nationality is required.", "danger")
            return _render(form=form)

        clinic = form["clinic"] or "ED"

        # Keep IP admission fields only for IPADM clinic
        if clinic != "IPADM":
            form["ward"] = ""
            form["bed_no"] = ""
            form["admission_type"] = ""
            form["approval_no"] = ""

        # ---------------------------
        # Duplicate / Existing patient logic (Cerner-like)
        # ---------------------------
        db = get_db()
        cur = db.cursor()
        patient_id = None
        dupe_matches = []

        # 1) Explicit selection from UI
        # When reception confirms a new registration / case number after review,
        # keep using the selected patient file and create a new visit on that file.
        if existing_patient_id.isdigit():
            patient_id = int(existing_patient_id)

        # 2) Match by ID number (strong match)
        # Even during force-new override, keep the same patient file when the ID
        # number matches exactly; only the visit/case number should be new.
        if patient_id is None and form["mrn"]:
            try:
                row = _fetch_patient_lookup_row(cur, "mrn", form["mrn"])
                if row:
                    patient_id = int(row.get("id") or 0) or None
            except Exception:
                patient_id = None

        if patient_id is None and form["id_number"]:
            try:
                row = _fetch_patient_lookup_row(cur, "id_number", form["id_number"])
                if row:
                    patient_id = int(row.get("id") or 0) or None
            except Exception:
                patient_id = None

        # If patient found, block duplicate open visit in same clinic
        if patient_id is not None:
            try:
                ensure_patient_has_mrn(patient_id)
            except Exception:
                pass
            try:
                dup = cur.execute(
                    """
                    SELECT visit_id, status, created_at
                      FROM visits
                     WHERE patient_id=?
                       AND COALESCE(clinic,'ED')=?
                       AND (status IS NULL OR UPPER(status) NOT IN ('DISCHARGED','TRANSFERRED','LAMA','EXPIRED','CANCELLED','CLOSED'))
                     ORDER BY id DESC
                     LIMIT 1
                    """,
                    (patient_id, clinic),
                ).fetchone()
            except Exception:
                dup = None

            if dup:
                try:
                    dup_visit_id = dup["visit_id"]
                except Exception:
                    dup_visit_id = dup[0]
                if force_new_patient:
                    flash(
                        f"Confirmed override: a new case number will be created in this clinic. Existing open case remains: {dup_visit_id}.",
                        "info",
                    )
                else:
                    flash(
                        f"⚠️ Patient already registered in this clinic. Case No: {dup_visit_id}. Please open the existing case instead of registering again.",
                        "warning",
                    )
                    return redirect(url_for("patient_details", visit_id=dup_visit_id))

        # If not resolved and not forced, check likely existing patients.
        # The same patient may register in multiple clinics, but should keep one patient file.
        skip_fuzzy_duplicate_review = bool(form.get("mrn") or form.get("id_number"))
        if patient_id is None and not force_new_patient and not skip_fuzzy_duplicate_review:
            matches = _collect_patient_match_rows(
                cur,
                mrn=form["mrn"],
                id_number=form["id_number"],
                phone=form["phone"],
                dob=form["dob"],
                name=form["name"],
                clinic=clinic,
                include_phone_only=False,
                limit=8,
            )

            if matches:
                if any(m.get("open_in_clinic_visit_id") for m in matches):
                    flash(
                        "A matching patient already has an open case in this clinic. Open the existing case, or explicitly confirm a brand-new patient if the records are not the same person.",
                        "warning",
                    )
                else:
                    flash(
                        "We found similar patient records. Reuse the same patient record and create a new visit for this clinic when appropriate.",
                        "warning",
                    )
                return _render(form=form, dupe_matches=matches)

        # ---------------------------
        # Create or reuse patient record (MPI-safe)
        # ---------------------------
        try:
            patient_id = _save_patient_master_registration(cur, form, patient_id=patient_id)
        except DuplicatePatientRegistrationError as dup_exc:
            _rollback_with_logging(db, "register_patient duplicate patient master")
            existing = dup_exc.existing_patient or {}
            form["existing_patient_id"] = str(existing.get("id") or existing.get("patient_id") or "")
            try:
                dupe_matches = _collect_patient_match_rows(
                    cur,
                    mrn=form.get("mrn", ""),
                    id_number=form.get("id_number", ""),
                    phone=form.get("phone", ""),
                    dob=form.get("dob", ""),
                    name=form.get("name", ""),
                    clinic=clinic,
                    include_phone_only=True,
                    limit=8,
                )
            except Exception as dup_collect_exc:
                _log_noncritical_exception("register_patient duplicate collect", dup_collect_exc)
                dupe_matches = []
            flash(
                str(dup_exc)
                or "Patient already exists in the Master Patient Index. Please update the existing file instead of creating a duplicate.",
                "warning",
            )
            return _render(form=form, dupe_matches=dupe_matches)
        except Exception as patient_master_exc:
            _log_critical_exception("register_patient patient master save failed", patient_master_exc)
            _rollback_with_logging(db, "register_patient patient master save")
            flash(
                "Unable to save the patient master profile. Please review MRN / National ID and try again.",
                "danger",
            )
            return _render(form=form, dupe_matches=dupe_matches)

        # ---------------------------
        # Build structured Insurance + Financial JSON
        # ---------------------------
        insurance_data = {
            "provider": form.get("insurance", ""),
            "member_no": form.get("insurance_no", ""),
            "plan": form.get("ins_plan", ""),
            "card_no": form.get("ins_card_no", ""),
            "dha_member_id": form.get("dha_member_id", ""),
            "policy_no": form.get("policy_no", ""),
            "policy_name": form.get("policy_name", ""),
            "valid_from": form.get("valid_from", ""),
            "valid_to": form.get("valid_to", ""),
            "eligibility_status": form.get("eligibility_status", ""),
            "eligibility_notes": form.get("eligibility_notes", ""),
        }

        contract_scheme_snapshot = {
            "consult_deduct_percent": _safe_float(form.get("consult_deduct_percent")),
            "consult_deduct_amount": _safe_float(form.get("consult_deduct_amount")),
            "lab_percent": _safe_float(form.get("lab_percent")),
            "lab_amount": _safe_float(form.get("lab_amount")),
            "radiology_percent": _safe_float(form.get("radiology_percent")),
            "radiology_amount": _safe_float(form.get("radiology_amount")),
            "investigation_percent": _safe_float(form.get("investigation_percent")),
            "investigation_amount": _safe_float(form.get("investigation_amount")),
            "inpatient_percent": _safe_float(form.get("inpatient_percent")),
            "inpatient_amount": _safe_float(form.get("inpatient_amount")),
            "pharmacy_percent": _safe_float(form.get("pharmacy_percent")),
            "pharmacy_amount": _safe_float(form.get("pharmacy_amount")),
            "dental_percent": _safe_float(form.get("dental_percent")),
            "dental_amount": _safe_float(form.get("dental_amount")),
        }

        financial_data = {
            "payment_method": form.get("payment_method", ""),
            "receipt_no": form.get("receipt_no", ""),
            "copay_amount": _safe_float(form.get("copay_amount")),
            "notes": form.get("payment_notes", ""),
            "contract_scheme": contract_scheme_snapshot,
        }

        insurance_json = json.dumps(insurance_data, ensure_ascii=False)
        financial_json = json.dumps(financial_data, ensure_ascii=False)

        # Short display summary used across boards
        payment_summary = (request.form.get("payment_details") or "").strip()
        if not payment_summary:
            payment_summary = build_payment_summary(insurance_data, financial_data)

        # ---------------------------
        # Create Visit (Encounter)
        # ---------------------------
        form["assigned_doctor"] = _assigned_physician_display(
            cur, form.get("assigned_doctor", "")
        )

        visit_id = None
        queue_no = None

        # Parse scheme id
        cs_id = None
        try:
            cs_id = int(form.get("contract_scheme_id") or 0)
        except Exception:
            cs_id = None
        if not cs_id:
            cs_id = None

        reg_exc = None
        for reg_attempt in range(1, 6):
            try:
                visit_id, queue_no = allocate_visit_identifiers()
                cur.execute(
                    """
                    INSERT INTO visits
                    (visit_id, patient_id, queue_no, triage_status, status,
                     clinic, ward, bed_no, admission_type, approval_no,
                     assigned_doctor,
                     payment_details, visit_type, service_category,
                     insurance_json, financial_json, contract_scheme_id,
                     created_at, created_by)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    """,
                    (
                        visit_id,
                        patient_id,
                        queue_no,
                        "NO",
                        "REGISTERED",
                        clinic,
                        form.get("ward", ""),
                        form.get("bed_no", ""),
                        form.get("admission_type", ""),
                        form.get("approval_no", ""),
                        form.get("assigned_doctor", ""),
                        payment_summary,
                        form.get("visit_type", "NEW"),
                        form.get("service_category", ""),
                        insurance_json,
                        financial_json,
                        cs_id,
                        datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                        session.get("username"),
                    ),
                )
                db.commit()
                reg_exc = None
                break
            except Exception as reg_insert_exc:
                _rollback_with_logging(
                    db,
                    f"register_patient main transaction attempt {reg_attempt}",
                )
                reg_exc = reg_insert_exc
                msg = str(reg_insert_exc or "").lower()
                retryable_visit_dup = (
                    "visits_visit_id_key" in msg
                    or ("duplicate key" in msg and "visit_id" in msg)
                    or ("unique constraint" in msg and "visit_id" in msg)
                )
                if retryable_visit_dup and reg_attempt < 5:
                    try:
                        logging.getLogger(__name__).warning(
                            "register_patient retrying after duplicate visit id on attempt %s: %s",
                            reg_attempt,
                            reg_insert_exc,
                        )
                    except Exception:
                        pass
                    continue
                break

        if reg_exc is not None:
            _log_critical_exception("register_patient failed before commit", reg_exc)
            flash(f"Failed to register patient: {reg_exc}", "danger")
            return _render(form=form, dupe_matches=dupe_matches)

        try:
            close_db(None)
        except Exception:
            pass

        attachment_warnings = []
        actor = session.get("username")
        warn = _save_register_attachment_after_commit(visit_id, elig_file, "ELIG", actor)
        if warn:
            attachment_warnings.append(warn)
        warn = _save_register_attachment_after_commit(visit_id, id_file, "ID", actor)
        if warn:
            attachment_warnings.append(warn)

        for warn in attachment_warnings:
            flash(warn, "warning")
        try:
            _invalidate_visit_runtime_caches(visit_id)
            _invalidate_register_lookup_caches(
                ("patient_lookup", str(DB_ENGINE or ""), "mrn", _normalize_patient_lookup_key(form.get("mrn", "")) or str(form.get("mrn", "")).strip().upper()),
                ("patient_lookup", str(DB_ENGINE or ""), "id_number", _normalize_patient_lookup_key(form.get("id_number", "")) or str(form.get("id_number", "")).strip().upper()),
            )
        except Exception:
            pass

        log_action(
            "REGISTER_PATIENT",
            visit_id=visit_id,
            details=f"Name={form['name']} Clinic={clinic} Dr={form.get('assigned_doctor','')}",
        )

        flash(f"Patient registered. Case No: {visit_id}", "success")

        next_page = request.args.get("next")
        if next_page == "clinic_board":
            return redirect(url_for("clinic_board", clinic=clinic))
        # Inpatient Billing users should return to Clinic Board by default
        if (session.get("role") or "").lower() == "inpatient_billing":
            return redirect(url_for("clinic_board", clinic=clinic))
        # Non-ED registrations should return to the Clinic Board by default
        if (clinic or "").upper() != "ED":
            return redirect(url_for("clinic_board", clinic=clinic))
        return redirect(url_for("patient_details", visit_id=visit_id))

    # GET
    return _render(form={})


# ============================================================
# Registration helpers (AJAX)
# ============================================================


def _normalize_patient_lookup_key(value):
    """Normalize MRN / National ID for fast exact lookup.

    Removes spaces and separators so reception can type values like:
    - D0000123
    - D-0000123
    - 784-1987-1234567-1
    - 784198712345671
    """
    try:
        s = str(value or "").strip().upper()
    except Exception:
        return ""
    if not s:
        return ""
    return re.sub(r"[^A-Z0-9]+", "", s)


def _normalized_patient_lookup_sql(column_name):
    col = (column_name or "").strip()
    if col not in {"mrn", "id_number"}:
        raise ValueError("Unsupported patient lookup column")
    if (DB_ENGINE or "").lower() == "postgres":
        return (
            "UPPER(REGEXP_REPLACE(COALESCE({col},''), '[^A-Za-z0-9]+', '', 'g'))".format(col=col)
        )
    return (
        "UPPER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE({col},''), ' ', ''), '-', ''), '/', ''), '.', ''), '_', ''))".format(col=col)
    )


def _fetch_patient_lookup_row(cur, column_name, raw_value):
    raw = (raw_value or "").strip()
    if not raw:
        return None

    cache_ttl = _cfg_float_runtime("PATIENT_LOOKUP_CACHE_SECONDS", 20.0)
    cache_key = ("patient_lookup", str(DB_ENGINE or ""), column_name, _normalize_patient_lookup_key(raw) or raw.upper())

    def _query_lookup():
        base_sql = """
            SELECT id, name, mrn, id_number, phone, email, dob, sex, nationality,
                   nok_name, nok_relation, nok_phone
            FROM patients
            WHERE {where_clause}
            ORDER BY id DESC
            LIMIT 1
        """

        try:
            row = cur.execute(base_sql.format(where_clause=f"{column_name}=?"), (raw,)).fetchone()
        except Exception:
            row = None
        if row is not None:
            return _row_to_dict(row, cur)

        norm = _normalize_patient_lookup_key(raw)
        if not norm:
            return None

        try:
            row = cur.execute(
                base_sql.format(where_clause=f"{_normalized_patient_lookup_sql(column_name)}=?"),
                (norm,),
            ).fetchone()
        except Exception:
            row = None
        return _row_to_dict(row, cur) if row is not None else None

    try:
        if cache_ttl > 0:
            return _PATIENT_LOOKUP_CACHE.get_or_compute(cache_key, cache_ttl, _query_lookup)
    except Exception:
        pass
    return _query_lookup()


@app.route("/api/dupe_check")
@login_required
def api_dupe_check():
    """Patient match panel for Register stepper UI."""
    mrn = (request.args.get("mrn") or "").strip()
    id_number = (request.args.get("id_number") or "").strip()
    phone = (request.args.get("phone") or "").strip()
    dob = (request.args.get("dob") or "").strip()
    dob_norm = normalize_dob_input(dob)
    if dob_norm:
        dob = dob_norm
    name = (request.args.get("name") or "").strip()
    clinic = (request.args.get("clinic") or "").strip().upper()

    cur = get_db().cursor()
    matches = _collect_patient_match_rows(
        cur,
        mrn=mrn,
        id_number=id_number,
        phone=phone,
        dob=dob,
        name=name,
        clinic=clinic,
        include_phone_only=True,
        limit=8,
    )

    mode = "no_match"
