def get_referral_clinic_options():
    """Return list of clinics for Discharge Summary referral field.

    Includes the default ED referral clinics + all active clinics from the dynamic clinic registry.
    """
    raw = []
    raw.extend(REFERRAL_CLINICS_DEFAULT)
    try:
        for _code, label in get_clinics_for_ui():
            raw.append(label)
    except Exception:
        pass

    seen = set()
    out = []
    for x in raw:
        x = (str(x) if x is not None else "").strip()
        if not x:
            continue
        k = x.lower()
        if k in seen:
            continue
        seen.add(k)
        out.append(x)
    return out


