def ensure_clinic_schema():
    """
    Ensure DB has the extra columns needed for Clinic Board / IP admission
    + enterprise Admission Order snapshot fields (Cerner-like).

    - SQLite: uses ensure_column (safe ALTER TABLE ADD COLUMN)
    - PostgreSQL: ALTER TABLE ... ADD COLUMN IF NOT EXISTS

    PERF:
    - This function used to run (and hit the DB) on many requests.
    - We now run it once per process (idempotent) to avoid load-test slowdowns.
    """
    global _clinic_schema_ready
    if _clinic_schema_ready:
        return
    try:
        db = get_db()
        if DB_ENGINE == "postgres":
            # Idempotent upgrades
            try:
                db.execute("ALTER TABLE visits ADD COLUMN IF NOT EXISTS clinic TEXT")
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS assigned_doctor TEXT"
                )
                db.execute("ALTER TABLE visits ADD COLUMN IF NOT EXISTS ward TEXT")
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_type TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS approval_no TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_ref_datetime TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_ref_by TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_admit_dr TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_dx TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_destination TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_order_status TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_order_cancel_reason TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_order_cancelled_by TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_order_cancelled_at TEXT"
                )

                # NEW: enterprise Admission Order snapshot fields
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_patient_type TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_medical_service TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_accommodation TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_facility TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_future_admission TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_isolation TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_authorization_status TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_approval_instructions TEXT"
                )
                db.execute(
                    "ALTER TABLE visits ADD COLUMN IF NOT EXISTS admission_order_comments TEXT"
                )

                db.commit()
            except Exception:
                try:
                    db.rollback()
                except Exception as rb_exc:
                    _log_noncritical_exception(
                        "ensure_clinic_schema postgres rollback failed",
                        rb_exc,
                    )
                raise
        else:
            ensure_column("visits", "clinic", "TEXT")
            ensure_column("visits", "assigned_doctor", "TEXT")
            # Admission processing-critical fields
            ensure_column("visits", "ward", "TEXT", strict=True)
            ensure_column("visits", "bed_no", "TEXT", strict=True)
            ensure_column("visits", "admission_type", "TEXT")
            ensure_column("visits", "approval_no", "TEXT", strict=True)
            ensure_column("visits", "admission_ref_datetime", "TEXT")
            ensure_column("visits", "admission_ref_by", "TEXT")
            ensure_column("visits", "admission_admit_dr", "TEXT")
            ensure_column("visits", "admission_dx", "TEXT")
            ensure_column("visits", "admission_destination", "TEXT")
            ensure_column("visits", "admission_order_status", "TEXT")
            ensure_column("visits", "admission_order_cancel_reason", "TEXT")
            ensure_column("visits", "admission_order_cancelled_by", "TEXT")
            ensure_column("visits", "admission_order_cancelled_at", "TEXT")

            # NEW: enterprise Admission Order snapshot fields
            ensure_column("visits", "admission_patient_type", "TEXT")
            ensure_column("visits", "admission_medical_service", "TEXT")
            ensure_column("visits", "admission_accommodation", "TEXT")
            ensure_column("visits", "admission_facility", "TEXT")
            ensure_column("visits", "admission_future_admission", "TEXT")
            ensure_column("visits", "admission_isolation", "TEXT")
            ensure_column("visits", "admission_authorization_status", "TEXT")
            ensure_column("visits", "admission_approval_instructions", "TEXT")
            ensure_column("visits", "admission_order_comments", "TEXT")

        _clinic_schema_ready = True
    except Exception:
        _clinic_schema_ready = False
        try:
            get_db().rollback()
        except Exception as rb_exc:
            _log_noncritical_exception("ensure_clinic_schema rollback failed", rb_exc)
        raise


def build_patient_mrn(patient_id):
    """Create a readable MRN from the numeric patient id using the D-prefix format."""
    try:
        return f"D{int(patient_id):07d}"
    except Exception:
        return ""


def is_auto_legacy_mrn(value):
    """Return True for old auto-generated MRNs like MRN0000123."""
    try:
        return bool(re.fullmatch(r"MRN\d{7}", (value or "").strip(), re.I))
    except Exception:
        return False


def ensure_patients_mrn_schema():
    """Ensure patients.mrn exists and backfill legacy values once per process."""
    global _patients_mrn_schema_ready
    if _patients_mrn_schema_ready:
        return
    try:
        db = get_db()
        if DB_ENGINE == "postgres":
            try:
                db.execute("ALTER TABLE patients ADD COLUMN IF NOT EXISTS mrn TEXT")
                db.execute("""
                    UPDATE patients
                    SET mrn = 'D' || LPAD(CAST(id AS TEXT), 7, '0')
                    WHERE COALESCE(TRIM(mrn),'')=''
                       OR mrn ~* '^MRN[0-9]{7}$'
                    """)
                db.commit()
            except Exception:
                try:
                    db.rollback()
                except Exception:
                    pass
                raise
        else:
            ensure_column("patients", "mrn", "TEXT")
            cur = db.cursor()
            rows = cur.execute("SELECT id, mrn FROM patients ORDER BY id").fetchall()
            changed = False
            for r in rows or []:
                try:
                    pid = r["id"]
                except Exception:
                    pid = r[0]
                try:
                    current_mrn = (r["mrn"] or "").strip()
                except Exception:
                    try:
                        current_mrn = (r[1] or "").strip()
                    except Exception:
                        current_mrn = ""
                if current_mrn and not is_auto_legacy_mrn(current_mrn):
                    continue
                mrn = build_patient_mrn(pid)
                if mrn and mrn != current_mrn:
                    cur.execute("UPDATE patients SET mrn=? WHERE id=?", (mrn, pid))
                    changed = True
            if changed:
                db.commit()
        _patients_mrn_schema_ready = True
    except Exception:
        _patients_mrn_schema_ready = False
        try:
            get_db().rollback()
        except Exception:
            pass



def ensure_patient_has_mrn(patient_id):
    """Backfill MRN for one patient and return it.

    Important: this helper no longer commits on its own. The caller transaction
    remains in control so /register can commit visit + patient together once.
    """
    try:
        if not patient_id:
            return ""
        ensure_patients_mrn_schema()
        db = get_db()
        cur = db.cursor()
        row = cur.execute(
            "SELECT mrn FROM patients WHERE id=?", (patient_id,)
        ).fetchone()
        current = ""
        if row:
            try:
                current = (row["mrn"] or "").strip()
            except Exception:
                current = (row[0] or "").strip()
        if current:
            return current
        mrn = build_patient_mrn(patient_id)
        if mrn:
            cur.execute("UPDATE patients SET mrn=? WHERE id=?", (mrn, patient_id))
        return mrn
    except Exception:
        return ""



def ensure_patients_extra_schema():
    """
    Ensure patients table has the extra fields used on the Register Patient screen:
    - email
    - next of kin (name / relation / phone)

    Safe / idempotent.

    PERF:
    - Run once per process to avoid repeated schema checks under load.
    """
    global _patients_extra_schema_ready
    if _patients_extra_schema_ready:
        return
    try:
        db = get_db()
        if DB_ENGINE == "postgres":
            try:
                db.execute("ALTER TABLE patients ADD COLUMN IF NOT EXISTS email TEXT")
                db.execute(
                    "ALTER TABLE patients ADD COLUMN IF NOT EXISTS nok_name TEXT"
                )
                db.execute(
                    "ALTER TABLE patients ADD COLUMN IF NOT EXISTS nok_relation TEXT"
                )
                db.execute(
                    "ALTER TABLE patients ADD COLUMN IF NOT EXISTS nok_phone TEXT"
                )
                db.execute("ALTER TABLE patients ADD COLUMN IF NOT EXISTS mrn TEXT")
                db.commit()
            except Exception:
                try:
                    db.rollback()
                except Exception:
                    pass
                raise
        else:
            ensure_column("patients", "email", "TEXT")
            ensure_column("patients", "nok_name", "TEXT")
            ensure_column("patients", "nok_relation", "TEXT")
            ensure_column("patients", "nok_phone", "TEXT")

        ensure_patients_mrn_schema()
        _patients_extra_schema_ready = True
    except Exception:
        # PERF 2026-04-19: Do NOT reset the ready flag on transient errors.
        # A transient failure (e.g. a lock timeout during load) used to flip
        # this back to False, causing every subsequent request to re-issue
        # the DDL and amplify the lock-contention storm. Leave it False only
        # if we never succeeded in the first place; keep it True once set.
        try:
            get_db().rollback()
        except Exception:
            pass


