def get_contract_schemes(active_only=True):
    """Return contract schemes as a list of dicts."""
    try:
        ensure_contract_schemes_schema()
    except Exception:
        pass

    cur = get_db().cursor()
    try:
        if active_only:
            rows = cur.execute("""
                SELECT * FROM contract_schemes
                WHERE is_active=1
                ORDER BY provider ASC, plan ASC, policy_name ASC, id DESC
                """).fetchall()
        else:
            rows = cur.execute("""
                SELECT * FROM contract_schemes
                ORDER BY provider ASC, plan ASC, policy_name ASC, id DESC
                """).fetchall()
    except Exception:
        rows = []

    out = []
    for r in rows or []:
        try:
            out.append(dict(r))
        except Exception:
            try:
                out.append(
                    {
                        "id": r[0],
                        "provider": r[1],
                        "plan": r[2],
                        "policy_name": r[3] if len(r) > 3 else "",
                        "scheme_json": r[4] if len(r) > 4 else "{}",
                        "is_active": r[5] if len(r) > 5 else 1,
                        "created_at": r[6] if len(r) > 6 else "",
                        "created_by": r[7] if len(r) > 7 else "",
                        "updated_at": r[8] if len(r) > 8 else "",
                        "updated_by": r[9] if len(r) > 9 else "",
                    }
                )
            except Exception:
                pass
    return out


def _safe_float(x):
    try:
        if x is None:
            return None
        s = str(x).strip()
        if s == "":
            return None
        # Remove any non-numeric currency separators
        s = s.replace(",", "")
        return float(s)
    except Exception:
        return None


def build_payment_summary(insurance_data=None, financial_data=None):
    """Build a short summary string for visits.payment_details."""
    insurance_data = insurance_data or {}
    financial_data = financial_data or {}

    parts = []

    prov = (
        insurance_data.get("provider") or insurance_data.get("insurance") or ""
    ).strip()
    plan = (insurance_data.get("plan") or "").strip()
    pol = (insurance_data.get("policy_no") or "").strip()
    elig = (insurance_data.get("eligibility_status") or "").strip()

    if prov:
        parts.append(f"INS:{prov}")
    if plan:
        parts.append(f"Plan:{plan}")
    if pol:
        parts.append(f"Policy:{pol}")
    if elig:
        parts.append(f"Elig:{elig}")

    copay = financial_data.get("copay_amount")
    if copay is None:
        copay = _safe_float(financial_data.get("copay_amount_raw"))
    if copay is not None:
        try:
            copay_disp = int(copay) if float(copay).is_integer() else copay
        except Exception:
            copay_disp = copay
        parts.append(f"Copay:{copay_disp}")

    method = (financial_data.get("payment_method") or "").strip()
    if method:
        parts.append(f"Pay:{method}")

    receipt = (financial_data.get("receipt_no") or "").strip()
    if receipt:
        parts.append(f"Rcpt:{receipt}")

    return " | ".join([p for p in parts if p]).strip()


_admission_orders_schema_ready = False


def ensure_admission_orders_schema():
    """
    Ensure admission_orders table exists (enterprise version).

    Why separate table?
    - Keep multiple Admission Orders per visit (history)
    - Full audit trail (created_by/at, updated_by/at, cancelled/admitted metadata)
    - ED board visibility is preserved (clinic is NOT moved just because an order exists)
    """
    global _admission_orders_schema_ready
    if _admission_orders_schema_ready:
        return
    db = get_db()
    cur = db.cursor()

    # 1) Create/upgrade table
    try:
        if DB_ENGINE == "postgres":
            cur.execute("""
                CREATE TABLE IF NOT EXISTS admission_orders (
                    id BIGSERIAL PRIMARY KEY,
                    visit_id TEXT NOT NULL,

                    -- Doctor order header
                    ref_datetime TEXT,
                    ref_by TEXT,
                    admit_dr TEXT,
                    destination TEXT,
                    admission_type TEXT,
                    dx TEXT,

                    -- Cerner-like order fields
                    patient_type TEXT,
                    medical_service TEXT,
                    accommodation TEXT,
                    facility TEXT,
                    future_admission TEXT,
                    isolation TEXT,
                    authorization_status TEXT,
                    approval_instructions TEXT,
                    order_comments TEXT,

                    -- Admission staff processing fields
                    ward TEXT,
                    bed_no TEXT,
                    approval_no TEXT,

                    -- Workflow status
                    status TEXT,
                    cancel_reason TEXT,
                    cancelled_by TEXT,
                    cancelled_at TEXT,
                    admitted_by TEXT,
                    admitted_at TEXT,

                    -- Audit trail
                    created_at TEXT,
                    created_by TEXT,
                    updated_at TEXT,
                    updated_by TEXT
                )
                """)

            # Idempotent ADD COLUMN for older deployments (no-op if already present)
            for col, typ in [
                ("patient_type", "TEXT"),
                ("medical_service", "TEXT"),
                ("accommodation", "TEXT"),
                ("facility", "TEXT"),
                ("future_admission", "TEXT"),
                ("isolation", "TEXT"),
                ("authorization_status", "TEXT"),
                ("approval_instructions", "TEXT"),
                ("order_comments", "TEXT"),
            ]:
                try:
                    cur.execute(
                        f"ALTER TABLE admission_orders ADD COLUMN IF NOT EXISTS {col} {typ}"
                    )
                except Exception:
                    pass

            try:
                cur.execute(
                    "CREATE INDEX IF NOT EXISTS idx_admission_orders_visit ON admission_orders(visit_id)"
                )
            except Exception:
                pass
            try:
                cur.execute(
                    "CREATE INDEX IF NOT EXISTS idx_admission_orders_status ON admission_orders(status)"
                )
            except Exception:
                pass
            db.commit()
        else:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS admission_orders (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    visit_id TEXT NOT NULL,

                    ref_datetime TEXT,
                    ref_by TEXT,
                    admit_dr TEXT,
                    dx TEXT,
                    destination TEXT,
                    admission_type TEXT,

                    patient_type TEXT,
                    medical_service TEXT,
                    accommodation TEXT,
                    facility TEXT,
                    future_admission TEXT,
                    isolation TEXT,
                    authorization_status TEXT,
                    approval_instructions TEXT,
                    order_comments TEXT,

                    ward TEXT,
                    bed_no TEXT,
                    approval_no TEXT,

                    status TEXT,
                    cancel_reason TEXT,
                    cancelled_by TEXT,
                    cancelled_at TEXT,
                    admitted_by TEXT,
                    admitted_at TEXT,

                    created_at TEXT,
                    created_by TEXT,
                    updated_at TEXT,
                    updated_by TEXT
                )
                """)

            # Add missing columns for older SQLite deployments (best-effort)
            try:
                cols = {
                    r["name"]
                    for r in cur.execute(
                        "PRAGMA table_info(admission_orders)"
                    ).fetchall()
                }
                for col, typ in [
                    ("patient_type", "TEXT"),
                    ("medical_service", "TEXT"),
                    ("accommodation", "TEXT"),
                    ("facility", "TEXT"),
                    ("future_admission", "TEXT"),
                    ("isolation", "TEXT"),
                    ("authorization_status", "TEXT"),
                    ("approval_instructions", "TEXT"),
                    ("order_comments", "TEXT"),
                ]:
                    if col not in cols:
                        cur.execute(
                            f"ALTER TABLE admission_orders ADD COLUMN {col} {typ}"
                        )
            except Exception:
                pass

            try:
                cur.execute(
                    "CREATE INDEX IF NOT EXISTS idx_admission_orders_visit ON admission_orders(visit_id)"
                )
            except Exception:
                pass
            try:
                cur.execute(
                    "CREATE INDEX IF NOT EXISTS idx_admission_orders_status ON admission_orders(status)"
                )
            except Exception:
                pass

            db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass
        return

    # 2) Best-effort legacy migration from visits -> admission_orders (1 row per visit)
    #    Only migrate when:
    #      - visits has any admission-order-like data
    #      - admission_orders has no rows for that visit
    try:
        legacy_rows = cur.execute("""
            SELECT visit_id,
                   admission_ref_datetime,
                   admission_ref_by,
                   admission_admit_dr,
                   admission_dx,
                   admission_destination,
                   admission_type,

                   admission_patient_type,
                   admission_medical_service,
                   admission_accommodation,
                   admission_facility,
                   admission_future_admission,
                   admission_isolation,
                   admission_authorization_status,
                   admission_approval_instructions,
                   admission_order_comments,

                   ward,
                   bed_no,
                   approval_no,
                   admission_order_status,
                   admission_order_cancel_reason,
                   admission_order_cancelled_by,
                   admission_order_cancelled_at
            FROM visits
            WHERE
                COALESCE(NULLIF(TRIM(admission_ref_datetime),''), '') <> ''
                OR COALESCE(NULLIF(TRIM(admission_ref_by),''), '') <> ''
                OR COALESCE(NULLIF(TRIM(admission_admit_dr),''), '') <> ''
                OR COALESCE(NULLIF(TRIM(admission_dx),''), '') <> ''
                OR COALESCE(NULLIF(TRIM(admission_destination),''), '') <> ''
                OR COALESCE(NULLIF(TRIM(admission_order_status),''), '') <> ''
            """).fetchall()
    except Exception:
        legacy_rows = []

    migrated = 0
    for r in legacy_rows or []:
        try:
            vid = r["visit_id"]
        except Exception:
            try:
                vid = r[0]
            except Exception:
                continue

        try:
            exists = cur.execute(
                "SELECT 1 FROM admission_orders WHERE visit_id=? LIMIT 1",
                (vid,),
            ).fetchone()
        except Exception:
            exists = None

        if exists:
            continue

        # Pull snapshot fields (best-effort)
        try:
            ref_dt = (r["admission_ref_datetime"] or "").strip()
            ref_by = (r["admission_ref_by"] or "").strip()
            admit_dr = (r["admission_admit_dr"] or "").strip()
            dx = (r["admission_dx"] or "").strip()
            dest = (r["admission_destination"] or "").strip()
            adm_type = (r["admission_type"] or "").strip()

            patient_type = (r["admission_patient_type"] or "").strip()
            medical_service = (r["admission_medical_service"] or "").strip()
            accommodation = (r["admission_accommodation"] or "").strip()
            facility = (r["admission_facility"] or "").strip()
            future_adm = (r["admission_future_admission"] or "").strip()
            isolation = (r["admission_isolation"] or "").strip()
            auth_status = (r["admission_authorization_status"] or "").strip()
            approval_instr = (r["admission_approval_instructions"] or "").strip()
            order_comments = (r["admission_order_comments"] or "").strip()

            ward = (r["ward"] or "").strip()
            bed_no = (r["bed_no"] or "").strip()
            approval_no = (r["approval_no"] or "").strip()

            status = (r["admission_order_status"] or "").strip().upper() or "ORDERED"
            cancel_reason = (r["admission_order_cancel_reason"] or "").strip()
            cancelled_by = (r["admission_order_cancelled_by"] or "").strip()
            cancelled_at = (r["admission_order_cancelled_at"] or "").strip()
        except Exception:
            # Row-like but not mapping
            try:
                ref_dt = (r[1] or "").strip()
                ref_by = (r[2] or "").strip()
                admit_dr = (r[3] or "").strip()
                dx = (r[4] or "").strip()
                dest = (r[5] or "").strip()
                adm_type = (r[6] or "").strip()

                patient_type = (r[7] or "").strip()
                medical_service = (r[8] or "").strip()
                accommodation = (r[9] or "").strip()
                facility = (r[10] or "").strip()
                future_adm = (r[11] or "").strip()
                isolation = (r[12] or "").strip()
                auth_status = (r[13] or "").strip()
                approval_instr = (r[14] or "").strip()
                order_comments = (r[15] or "").strip()

                ward = (r[16] or "").strip()
                bed_no = (r[17] or "").strip()
                approval_no = (r[18] or "").strip()

                status = (r[19] or "").strip().upper() or "ORDERED"
                cancel_reason = (r[20] or "").strip()
                cancelled_by = (r[21] or "").strip()
                cancelled_at = (r[22] or "").strip()
            except Exception:
                continue

        if status not in ("ORDERED", "CANCELLED", "ADMITTED", "REPLACED"):
            status = "ORDERED"

        created_at = ref_dt or now_display_str("%Y-%m-%d %H:%M")
        created_by = ref_by or "LEGACY"

        admitted_at = ""
        admitted_by = ""
        if status == "ADMITTED":
            admitted_at = now_display_str("%Y-%m-%d %H:%M")
            admitted_by = "LEGACY"

        try:
            db.execute(
                """
                INSERT INTO admission_orders
                (visit_id, ref_datetime, ref_by, admit_dr, dx, destination, admission_type,
                 patient_type, medical_service, accommodation, facility, future_admission, isolation,
                 authorization_status, approval_instructions, order_comments,
                 ward, bed_no, approval_no,
                 status, cancel_reason, cancelled_by, cancelled_at,
                 admitted_by, admitted_at,
                 created_at, created_by, updated_at, updated_by)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    vid,
                    ref_dt,
                    ref_by,
                    admit_dr,
                    dx,
                    dest,
                    adm_type,
                    patient_type,
                    medical_service,
                    accommodation,
                    facility,
                    future_adm,
                    isolation,
                    auth_status,
                    approval_instr,
                    order_comments,
                    ward,
                    bed_no,
                    approval_no,
                    status,
                    cancel_reason if status == "CANCELLED" else (cancel_reason or ""),
                    cancelled_by if status == "CANCELLED" else (cancelled_by or ""),
                    cancelled_at if status == "CANCELLED" else (cancelled_at or ""),
                    admitted_by,
                    admitted_at,
                    created_at,
                    created_by,
                    created_at,
                    created_by,
                ),
            )
            migrated += 1
        except Exception:
            continue

    try:
        if migrated:
            db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass

    # Mark schema ready (per-process)
    _admission_orders_schema_ready = True


# ============================================================
# Admission Order Picklists (dynamic dropdowns + "ADD" actions)
# ============================================================
_admission_picklists_schema_ready = False

def ensure_admission_picklists_schema():
    """
    Dynamic picklists for Admission Order (Cerner-like) dropdowns.

    Categories used:
      - patient_type
      - admission_type
      - destination
      - authorization_status
      - doctor  (manual additions only; user accounts are still used too)
    """
    global _admission_picklists_schema_ready
    if _admission_picklists_schema_ready:
        return
    db = get_db()
    cur = db.cursor()
    try:
        if DB_ENGINE == "postgres":
            cur.execute("""
                CREATE TABLE IF NOT EXISTS admission_order_picklists (
                    id BIGSERIAL PRIMARY KEY,
                    category TEXT NOT NULL,
                    value TEXT NOT NULL,
                    label TEXT,
                    extra TEXT,
                    is_active INTEGER NOT NULL DEFAULT 1,
                    created_at TEXT NOT NULL,
                    created_by TEXT NOT NULL
                )
                """)
            try:
                cur.execute(
                    "CREATE UNIQUE INDEX IF NOT EXISTS idx_aopick_unique ON admission_order_picklists(category, value)"
                )
            except Exception as idx_exc:
                _log_noncritical_exception(
                    "admission_order_picklists: CREATE UNIQUE INDEX idx_aopick_unique (postgres)",
                    idx_exc,
                )
            db.commit()
        else:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS admission_order_picklists (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    category TEXT NOT NULL,
                    value TEXT NOT NULL,
                    label TEXT,
                    extra TEXT,
                    is_active INTEGER NOT NULL DEFAULT 1,
                    created_at TEXT NOT NULL,
                    created_by TEXT NOT NULL
                )
                """)
            try:
                cur.execute(
                    "CREATE UNIQUE INDEX IF NOT EXISTS idx_aopick_unique ON admission_order_picklists(category, value)"
                )
            except Exception as idx_exc:
                _log_noncritical_exception(
                    "admission_order_picklists: CREATE UNIQUE INDEX idx_aopick_unique (sqlite)",
                    idx_exc,
                )
            db.commit()
        _admission_picklists_schema_ready = True
    except Exception as schema_exc:
        _admission_picklists_schema_ready = False
        try:
            db.rollback()
        except Exception as rb_exc:
            _log_noncritical_exception(
                "ensure_admission_picklists_schema: rollback after failure",
                rb_exc,
            )
        _log_noncritical_exception(
            "ensure_admission_picklists_schema failed (picklist table/index may be missing)",
            schema_exc,
        )



def _picklist_allowed_categories():
    return {
        "patient_type",
        "admission_type",
        "destination",
        "authorization_status",
        "doctor",
    }


def picklist_upsert(
    category: str, value: str, label: str = "", extra: str = "", actor: str = ""
) -> bool:
    """
    Insert (or reactivate) a picklist value for Admission Orders.
    Returns True when saved successfully.
    """
    category = (category or "").strip()
    value = (value or "").strip()
    label = (label or "").strip()
    extra = (extra or "").strip()

    if not category or not value:
        return False
    if category not in _picklist_allowed_categories():
        return False

    # Normalize destination codes
    if category == "destination":
        value = value.upper().strip()
        if not label:
            label = value

    # Soft limits (avoid abuse)
    if len(value) > 120:
        value = value[:120]
    if len(label) > 120:
        label = label[:120]
    if len(extra) > 120:
        extra = extra[:120]

    try:
        ensure_admission_picklists_schema()
    except Exception as ensure_exc:
        _log_noncritical_exception(
            "picklist_upsert: ensure_admission_picklists_schema",
            ensure_exc,
        )

    db = get_db()
    cur = db.cursor()
    now_ts = now_display_str("%Y-%m-%d %H:%M")
    try:
        actor = actor or session.get("username", "")
    except Exception:
        pass
    actor = actor or "SYSTEM"

    try:
        if DB_ENGINE == "postgres":
            # Insert if not exists
            cur.execute(
                """
                INSERT INTO admission_order_picklists
                (category, value, label, extra, is_active, created_at, created_by)
                VALUES (?,?,?,?,1,?,?)
                ON CONFLICT (category, value) DO NOTHING
                """,
                (category, value, label or None, extra or None, now_ts, actor),
            )
            # Update details if provided + reactivate
            cur.execute(
                """
                UPDATE admission_order_picklists
                   SET label=CASE WHEN COALESCE(NULLIF(?,''), '')<>'' THEN ? ELSE label END,
                       extra=CASE WHEN COALESCE(NULLIF(?,''), '')<>'' THEN ? ELSE extra END,
                       is_active=1
                 WHERE category=? AND value=?
                """,
                (label, label, extra, extra, category, value),
            )
        else:
            # SQLite
            cur.execute(
                """
                INSERT OR IGNORE INTO admission_order_picklists
                (category, value, label, extra, is_active, created_at, created_by)
                VALUES (?,?,?,?,1,?,?)
                """,
                (category, value, label, extra, now_ts, actor),
            )
            cur.execute(
                """
                UPDATE admission_order_picklists
                   SET label=CASE WHEN ?<>'' THEN ? ELSE label END,
                       extra=CASE WHEN ?<>'' THEN ? ELSE extra END,
                       is_active=1
                 WHERE category=? AND value=?
                """,
                (label, label, extra, extra, category, value),
            )

        db.commit()
        try:
            if category == "doctor":
                _get_physician_directory_maps(force=True)
        except Exception:
            pass
        return True
    except Exception as upsert_exc:
        try:
            db.rollback()
        except Exception as rb_exc:
            _log_noncritical_exception("picklist_upsert: rollback failed", rb_exc)
        _log_noncritical_exception("picklist_upsert: save failed", upsert_exc)
        return False


def picklist_get_rows(category: str):
    category = (category or "").strip()
    if not category or category not in _picklist_allowed_categories():
        return []
    try:
        ensure_admission_picklists_schema()
    except Exception as ensure_exc:
        _log_noncritical_exception(
            "picklist_get_rows: ensure_admission_picklists_schema",
            ensure_exc,
        )

    cur = get_db().cursor()
    try:
        rows = cur.execute(
            """
            SELECT value, label, extra
            FROM admission_order_picklists
            WHERE category=? AND is_active=1
            ORDER BY COALESCE(label, value), value
            """,
            (category,),
        ).fetchall()
    except Exception as q_exc:
        _log_noncritical_exception(
            f"picklist_get_rows: query failed category={category!r}",
            q_exc,
        )
        rows = []

    out = []
    for r in rows or []:
        try:
            out.append(
                {
                    "value": (r["value"] or "").strip(),
                    "label": (r["label"] or "").strip(),
                    "extra": (r["extra"] or "").strip(),
                }
            )
        except Exception:
            try:
                out.append(
                    {
                        "value": (r[0] or "").strip(),
                        "label": (r[1] or "").strip() if len(r) > 1 else "",
                        "extra": (r[2] or "").strip() if len(r) > 2 else "",
                    }
                )
            except Exception:
                pass

    return [x for x in out if x.get("value")]


def picklist_get_values(category: str):
    return [r.get("value", "") for r in picklist_get_rows(category)]


def picklist_merge_list(defaults, extra_values):
    """Return unique list preserving order."""
    seen = set()
    out = []
    for v in defaults or []:
        v = (v or "").strip()
        if v and v not in seen:
            seen.add(v)
            out.append(v)
    for v in extra_values or []:
        v = (v or "").strip()
        if v and v not in seen:
            seen.add(v)
            out.append(v)
    return out


def picklist_merge_destinations(defaults):
    """defaults: list of (code,label). merges DB destination picklist."""
    items = []
    seen = set()
    for code, label in defaults or []:
        code = (code or "").strip().upper()
        label = (label or "").strip() or code
        if code and code not in seen:
            seen.add(code)
            items.append((code, label))

    for r in picklist_get_rows("destination"):
        code = (r.get("value") or "").strip().upper()
        label = (r.get("label") or "").strip() or code
        if code and code not in seen:
            seen.add(code)
            items.append((code, label))

    return items


def doctor_extra_parse(extra: str):
    """Parse doctor extra field.

    admission_order_picklists.extra for category 'doctor' supports:
      - "GD" (legacy)
      - "GD|Specialty" (new)
      - "|Specialty" (no GD)
    Returns (gd_number, specialty).
    """
    extra = (extra or "").strip()
    if "|" in extra:
        gd, spec = extra.split("|", 1)
        return (gd or "").strip(), (spec or "").strip()
    return extra, ""


def doctor_extra_pack(gd_number: str, specialty: str) -> str:
    """Pack GD + specialty into the picklist extra field."""
    gd_number = (gd_number or "").strip()
    specialty = (specialty or "").strip()
    if gd_number and specialty:
        return f"{gd_number}|{specialty}"
    if specialty and not gd_number:
        # Keep a leading delimiter so parsing stays unambiguous
        return f"|{specialty}"
    return gd_number or ""


def picklist_get_doctors():
    """Return list of dict {username, gd_number, specialty} from picklist category 'doctor'."""
    docs = []
    for r in picklist_get_rows("doctor"):
        name = (r.get("value") or "").strip()
        gd, spec = doctor_extra_parse(r.get("extra") or "")
        if name:
            docs.append({"username": name, "gd_number": gd, "specialty": spec})
    return docs


