def ensure_diagnosis_master_schema():
    """Create/upgrade diagnosis_master table (global list of diagnoses)."""
    db = get_db()
    cur = db.cursor()
    try:
        if DB_ENGINE == "postgres":
            cur.execute("""
                CREATE TABLE IF NOT EXISTS diagnosis_master (
                    id BIGSERIAL PRIMARY KEY,
                    name TEXT NOT NULL,
                    icd_code TEXT NOT NULL DEFAULT '',
                    synonyms TEXT NOT NULL DEFAULT '',
                    is_active INTEGER NOT NULL DEFAULT 1,
                    created_at TEXT NOT NULL,
                    created_by TEXT NOT NULL
                )
                """)
        else:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS diagnosis_master (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    icd_code TEXT NOT NULL DEFAULT '',
                    synonyms TEXT NOT NULL DEFAULT '',
                    is_active INTEGER NOT NULL DEFAULT 1,
                    created_at TEXT NOT NULL,
                    created_by TEXT NOT NULL
                )
                """)

        # Backward compatible: add synonyms column on existing DBs
        try:
            ensure_column("diagnosis_master", "synonyms", "TEXT")
        except Exception:
            pass

        # Uniqueness (Name + ICD code). ICD code may be empty string when optional.
        cur.execute(
            "CREATE UNIQUE INDEX IF NOT EXISTS idx_diagnosis_master_unique ON diagnosis_master(name, icd_code)"
        )
        cur.execute(
            "CREATE INDEX IF NOT EXISTS idx_diagnosis_master_active ON diagnosis_master(is_active)"
        )
        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass


def diagnosis_display(name: str, icd_code: str = "") -> str:
    name = (name or "").strip()
    code = (icd_code or "").strip()
    if name and code:
        return f"{name} ({code})"
    return name or ""


def diagnosis_parse_display(text: str):
    """Parse 'Name (CODE)' into (name, code). CODE is optional."""
    t = (text or "").strip()
    if not t:
        return ("", "")
    if t.endswith(")") and "(" in t:
        idx = t.rfind("(")
        name = t[:idx].strip()
        code = t[idx + 1 : -1].strip()
        if name:
            return (name, code)
    return (t, "")


def diagnosis_master_upsert(name: str, icd_code: str = "", actor: str = "SYSTEM"):
    """Insert diagnosis if not exists; reactivate if previously inactive."""
    ensure_diagnosis_master_schema()
    name = (name or "").strip()
    icd_code = (icd_code or "").strip()
    if not name:
        return (False, None, "Diagnosis name is required")

    # Basic length guards
    if len(name) > 160:
        name = name[:160]
    if len(icd_code) > 40:
        icd_code = icd_code[:40]

    db = get_db()
    cur = db.cursor()
    now_ts = now_display_str("%Y-%m-%d %H:%M:%S")
    actor = (actor or "SYSTEM").strip() or "SYSTEM"

    try:
        if DB_ENGINE == "postgres":
            cur.execute(
                """
                INSERT INTO diagnosis_master (name, icd_code, is_active, created_at, created_by)
                VALUES (?,?,1,?,?)
                ON CONFLICT (name, icd_code) DO NOTHING
                """,
                (name, icd_code, now_ts, actor),
            )
        else:
            cur.execute(
                """
                INSERT OR IGNORE INTO diagnosis_master (name, icd_code, is_active, created_at, created_by)
                VALUES (?,?,1,?,?)
                """,
                (name, icd_code, now_ts, actor),
            )

        # Reactivate if exists
        cur.execute(
            "UPDATE diagnosis_master SET is_active=1 WHERE name=? AND icd_code=?",
            (name, icd_code),
        )
        db.commit()

        row = cur.execute(
            "SELECT id FROM diagnosis_master WHERE name=? AND icd_code=?",
            (name, icd_code),
        ).fetchone()
        dx_id = None
        try:
            dx_id = row["id"]
        except Exception:
            try:
                dx_id = row[0]
            except Exception:
                dx_id = None

        return (True, dx_id, None)
    except Exception as e:
        try:
            db.rollback()
        except Exception:
            pass
        return (False, None, str(e))


def diagnosis_master_search(q: str = "", limit: int = 15):
    """Search diagnosis_master by name / ICD code / synonyms.

    Uses SQLite FTS5 when available for much faster lookup.
    """
    ensure_diagnosis_master_schema()
    q = (q or "").strip()
    try:
        limit = int(limit or 15)
    except Exception:
        limit = 15
    limit = max(1, min(limit, 50))

    db = get_db()
    cur = db.cursor()
    rows = []
    try:
        if q:
            patt = f"%{q}%"
            # SQLite FTS5 (if present)
            if DB_ENGINE != "postgres" and sqlite_fts_available("diagnosis_master_fts"):
                ftsq = fts5_query(q)
                rows = cur.execute(
                    """
                    SELECT dm.id, dm.name, dm.icd_code
                    FROM diagnosis_master_fts f
                    JOIN diagnosis_master dm ON dm.id = f.rowid
                    WHERE dm.is_active=1 AND f MATCH ?
                    ORDER BY bm25(diagnosis_master_fts), dm.name
                    LIMIT ?
                    """,
                    (ftsq, limit),
                ).fetchall()
            elif DB_ENGINE == "postgres":
                # PostgreSQL FTS (GIN index on to_tsvector expression). Keep ILIKE fallback for partial ICD codes.
                rows = cur.execute(
                    """
                    SELECT id, name, icd_code
                    FROM diagnosis_master
                    WHERE is_active=1 AND (
                        to_tsvector('simple', coalesce(name,'') || ' ' || coalesce(icd_code,'') || ' ' || coalesce(synonyms,'')) @@ plainto_tsquery('simple', ?)
                        OR name ILIKE ? OR icd_code ILIKE ? OR synonyms ILIKE ?
                    )
                    ORDER BY name
                    LIMIT ?
                    """,
                    (q, patt, patt, patt, limit),
                ).fetchall()
            else:
                rows = cur.execute(
                    """
                    SELECT id, name, icd_code
                    FROM diagnosis_master
                    WHERE is_active=1 AND (name LIKE ? OR icd_code LIKE ? OR synonyms LIKE ?)
                    ORDER BY name
                    LIMIT ?
                    """,
                    (patt, patt, patt, limit),
                ).fetchall()
        else:
            rows = cur.execute(
                """
                SELECT id, name, icd_code
                FROM diagnosis_master
                WHERE is_active=1
                ORDER BY name
                LIMIT ?
                """,
                (limit,),
            ).fetchall()
    except Exception:
        rows = []

    out = []
    for r in rows or []:
        try:
            rid = r["id"]
            name = r["name"]
            code = r["icd_code"]
        except Exception:
            rid = r[0] if len(r) > 0 else None
            name = r[1] if len(r) > 1 else ""
            code = r[2] if len(r) > 2 else ""
        out.append(
            {
                "id": rid,
                "name": (name or "").strip(),
                "icd_code": (code or "").strip(),
                "display": diagnosis_display(name, code),
            }
        )
    return out


def seed_default_diagnoses():
    """Ensure example diagnoses exist (global list)."""
    try:
        ensure_diagnosis_master_schema()
        for name, code in DEFAULT_DIAGNOSIS_ITEMS or []:
            diagnosis_master_upsert(name, code, actor="SYSTEM")
    except Exception:
        pass


