def seed_physicians_from_csv(force: bool = False):
    """Seed the Physician directory (doctor picklist) from a bundled CSV file.

    This makes sure:
    - Admin > Orders Items shows the full Physicians list.
    - Physician dropdowns/datalists across the system are pre-populated.

    Safe/idempotent:
    - By default, it only adds missing values and does NOT overwrite existing entries.
    - Set force=True to re-apply everything.
    """
    try:
        ensure_admission_picklists_schema()
    except Exception as ensure_exc:
        _log_noncritical_exception(
            "seed_physicians_from_csv: ensure_admission_picklists_schema",
            ensure_exc,
        )

    # Candidate seed files (relative to this script). If none found, use embedded CSV.
    base_dir = (
        os.path.dirname(os.path.abspath(__file__))
        if "__file__" in globals()
        else os.getcwd()
    )
    candidates = [
        os.path.join(base_dir, "doctors_seed.csv"),
        os.path.join(base_dir, "orders_items_doc_20260102_1342_cleaned.csv"),
    ]
    seed_path = None
    for p in candidates:
        try:
            if p and os.path.exists(p) and os.path.getsize(p) > 0:
                seed_path = p
                break
        except Exception:
            continue

    db = get_db()
    cur = db.cursor()

    # Existing values (avoid overwriting user edits)
    existing = set()
    try:
        rows = cur.execute(
            "SELECT value FROM admission_order_picklists WHERE category='doctor'"
        ).fetchall()
        for r in rows or []:
            try:
                v = r[0]
            except Exception:
                v = r.get("value") if hasattr(r, "get") else None
            v = (v or "").strip()
            if v:
                existing.add(v.lower())
    except Exception:
        existing = set()

    def _parse_bool(val, default=1):
        if val is None:
            return int(default)
        s = str(val).strip().lower()
        if s in ("1", "true", "t", "yes", "y", "active", "enable", "enabled"):
            return 1
        if s in ("0", "false", "f", "no", "n", "inactive", "disable", "disabled"):
            return 0
        return int(default)

    try:
        if seed_path:
            txt = open(seed_path, "r", encoding="utf-8-sig", errors="replace").read()
        else:
            txt = DEFAULT_PHYSICIANS_CSV

        if not txt or not txt.strip():
            return

        reader = csv.DictReader(io.StringIO(txt))
        for row in reader:
            if not isinstance(row, dict):
                continue

            name = (
                (
                    row.get("Name")
                    or row.get("name")
                    or row.get("Physician")
                    or row.get("doctor")
                    or ""
                )
            ).strip()
            if not name:
                continue

            key = name.lower()
            if (key in existing) and (not force):
                continue

            gd = (
                (
                    row.get("GD Number")
                    or row.get("gd_number")
                    or row.get("GD")
                    or row.get("gd")
                    or ""
                )
            ).strip()
            spec = (
                (
                    row.get("Specialty")
                    or row.get("specialty")
                    or row.get("Speciality")
                    or row.get("speciality")
                    or ""
                )
            ).strip()
            is_active_raw = (
                row.get("Is Active")
                or row.get("is_active")
                or row.get("Active")
                or row.get("active")
            )

            extra = doctor_extra_pack(gd, spec)

            # Add only (do not overwrite existing unless force=True)
            ok = True
            if force:
                ok = picklist_upsert(
                    "doctor", name, label=name, extra=extra, actor="SYSTEM"
                )
            else:
                try:
                    ex = cur.execute(
                        "SELECT 1 FROM admission_order_picklists WHERE category='doctor' AND value=? LIMIT 1",
                        (name,),
                    ).fetchone()
                    if not ex:
                        ok = picklist_upsert(
                            "doctor", name, label=name, extra=extra, actor="SYSTEM"
                        )
                except Exception:
                    ok = picklist_upsert(
                        "doctor", name, label=name, extra=extra, actor="SYSTEM"
                    )

            if ok:
                existing.add(key)

            # Optional deactivate if sheet explicitly says inactive
            try:
                if (
                    str(is_active_raw).strip() != ""
                    and _parse_bool(is_active_raw, default=1) == 0
                ):
                    cur.execute(
                        "UPDATE admission_order_picklists SET is_active=0 WHERE category='doctor' AND value=?",
                        (name,),
                    )
                    db.commit()
            except Exception:
                pass
    except Exception:
        # Never block startup if the seed file is missing/corrupt.
        try:
            db.rollback()
        except Exception:
            pass
        return


@app.route("/clinic_board")
@login_required
def clinic_board():
    try:
        ensure_patients_mrn_schema()
    except Exception:
        pass
    # Ensure clinic board / IP admission columns exist (safe/idempotent)
    try:
        ensure_clinic_schema()
    except Exception:
        pass

    # Ensure admission_orders table exists + legacy migration
    try:
        ensure_admission_orders_schema()
    except Exception:
        pass

    # Default clinic for Inpatient Billing staff is IP Admission
    default_clinic = "OPD"
    if (session.get("role") or "").lower() == "inpatient_billing":
        default_clinic = "IPADM"

    clinic_filter = (
        (request.args.get("clinic", default_clinic) or default_clinic).strip().upper()
    )
    status_filter = (request.args.get("status", "ALL") or "ALL").strip().upper()
    ward_filter = (request.args.get("ward", "") or "").strip()
    visit_f = (request.args.get("visit_id", "") or "").strip()
    user_f = (request.args.get("user", "") or "").strip()
    physician_f = (request.args.get("assigned_physician", "") or "").strip()
    q = (request.args.get("q", "") or "").strip()
    dfrom = (request.args.get("date_from", "") or "").strip()
    dto = (request.args.get("date_to", "") or "").strip()

    # Pagination
    page, per_page, offset = get_page_args(25)

    # Cache TTL (short) to reduce DB pressure under load
    try:
        ttl = float(APP_CONFIG.get("CLINIC_BOARD_CACHE_SECONDS", 0.0) or 0.0)
    except Exception:
        ttl = 0.0

    cache_base = (
        str(clinic_filter or ""),
        str(status_filter or ""),
        str(ward_filter or ""),
        str(visit_f or ""),
        str(user_f or ""),
        str(physician_f or ""),
        str(q or ""),
        str(q or ""),
        str(dfrom or ""),
        str(dto or ""),
        int(page),
        int(per_page),
        str(DB_ENGINE or ""),
    )

    def _date_floor(d: str) -> str:
        return f"{d} 00:00:00"

    def _date_ceil_excl(d: str) -> str:
        try:
            dt = datetime.strptime(d, "%Y-%m-%d") + timedelta(days=1)
            return dt.strftime("%Y-%m-%d 00:00:00")
        except Exception:
            return f"{d} 23:59:59"

    def _compute():
        cur = get_db().cursor()

        # Build base filter (visits-only) for COUNT and wards
        where_v = " WHERE 1=1"
        params_v = []

        if clinic_filter == "IPADM":
            # IP Admission board shows:
            #  - direct IPADM clinic visits (clinic = IPADM)
            #  - ED/other visits that have at least one Admission Order (without changing clinic)
            where_v += " AND (COALESCE(v.clinic,'ED')='IPADM' OR EXISTS (SELECT 1 FROM admission_orders x WHERE x.visit_id=v.visit_id))"
        else:
            where_v += " AND COALESCE(v.clinic,'ED')=?"
            params_v.append(clinic_filter)

        # Status filter
        if status_filter and status_filter != "ALL":
            if clinic_filter == "IPADM":
                # For IPADM, status refers to latest Admission Order status
                where_v += " AND UPPER(COALESCE((SELECT ao3.status FROM admission_orders ao3 WHERE ao3.visit_id=v.visit_id ORDER BY ao3.id DESC LIMIT 1),''))=?"
                params_v.append(status_filter)
            else:
                if status_filter in ("OPEN", "REGISTERED"):
                    where_v += (
                        " AND UPPER(COALESCE(v.status,'')) IN ('OPEN','REGISTERED')"
                    )
                else:
                    where_v += " AND UPPER(COALESCE(v.status,''))=?"
                    params_v.append(status_filter)

        if ward_filter:
            where_v += " AND v.ward LIKE ?"
            params_v.append(f"%{ward_filter}%")

        if visit_f:
            if DB_ENGINE == "postgres":
                where_v += " AND v.visit_id ILIKE ?"
            else:
                where_v += " AND v.visit_id LIKE ?"
            params_v.append(f"%{visit_f}%")

        if user_f:
            where_v += " AND v.created_by LIKE ?"
            params_v.append(f"%{user_f}%")

        where_v, params_v = _append_assigned_physician_filter_sql(
            where_v, params_v, physician_f, visit_alias="v"
        )

        if q:
            where_v, params_v = _append_patient_search_sql(
                where_v, params_v, q, patient_alias="p", visit_alias="v"
            )

        if dfrom:
            where_v += " AND v.created_at >= ?"
            params_v.append(_date_floor(dfrom))

        if dto:
            where_v += " AND v.created_at < ?"
            params_v.append(_date_ceil_excl(dto))

        # COUNT (fast: no join to patients/attachments)
        total = 0
        try:
            row = cur.execute(
                "SELECT COUNT(*) AS cnt FROM visits v JOIN patients p ON p.id = v.patient_id"
                + where_v,
                params_v,
            ).fetchone()
            if row:
                try:
                    total = int(row.get("cnt") or 0)
                except Exception:
                    total = int(row[0])
        except Exception:
            total = 0

        # Rows query (join patients + latest admission order)
        where_rows = where_v
        params_rows = list(params_v)

        # For IPADM, filter by latest joined AO status if a specific status is selected.
        # This keeps the rows list consistent with the joined data.
        if clinic_filter == "IPADM" and status_filter and status_filter != "ALL":
            # We already included a correlated-subquery filter in where_v for COUNT.
            # Keep it (correct), but also add the joined AO filter (cheap) to avoid extra rows.
            where_rows += " AND UPPER(COALESCE(ao.status,''))=?"
            params_rows.append(status_filter)

        sql = (
            """
            SELECT v.visit_id,
                   v.queue_no,
                   v.triage_status,
                   v.triage_cat,
                   v.status,
                   COALESCE(v.clinic,'ED') AS clinic,
                   v.location,
                   v.ward,
                   v.bed_no,
                   v.assigned_doctor,
                   v.admission_type,
                   v.approval_no,

                   ao.id AS admission_order_id,
                   ao.status AS admission_order_status,
                   ao.cancel_reason AS admission_order_cancel_reason,
                   ao.cancelled_by AS admission_order_cancelled_by,
                   ao.cancelled_at AS admission_order_cancelled_at,

                   ao.destination AS admission_destination,
                   ao.admit_dr AS admission_admit_dr,
                   ao.dx AS admission_dx,
                   ao.ref_datetime AS admission_ref_datetime,
                   ao.ref_by AS admission_ref_by,
                   ao.admission_type AS admission_order_admission_type,

                   ao.patient_type AS admission_patient_type,
                   ao.medical_service AS admission_medical_service,
                   ao.accommodation AS admission_accommodation,
                   ao.facility AS admission_facility,
                   ao.future_admission AS admission_future_admission,
                   ao.isolation AS admission_isolation,
                   ao.authorization_status AS admission_authorization_status,

                   (SELECT COUNT(*) FROM admission_orders ao2 WHERE ao2.visit_id=v.visit_id) AS admission_orders_count,

                   v.payment_details,
                   v.closed_at,
                   v.created_at,
                   v.created_by,
                   p.name,
                   p.mrn,
                   p.id_number,
                   (SELECT id FROM attachments
                     WHERE visit_id=v.visit_id
                       AND filename NOT LIKE '%_LAB_%'
                       AND filename NOT LIKE '%_RAD_%'
                       AND UPPER(filename) NOT LIKE '%ELIG%'
                     ORDER BY CASE WHEN UPPER(filename) LIKE '%ID%' THEN 0 ELSE 1 END,
                              COALESCE(uploaded_at,'') DESC,
                              id DESC
                     LIMIT 1) AS id_attachment_id,
                   (SELECT filename FROM attachments
                     WHERE visit_id=v.visit_id
                       AND filename NOT LIKE '%_LAB_%'
                       AND filename NOT LIKE '%_RAD_%'
                       AND UPPER(filename) NOT LIKE '%ELIG%'
                     ORDER BY CASE WHEN UPPER(filename) LIKE '%ID%' THEN 0 ELSE 1 END,
                              COALESCE(uploaded_at,'') DESC,
                              id DESC
                     LIMIT 1) AS id_attachment,
                   (SELECT id FROM attachments
                     WHERE visit_id=v.visit_id
                       AND filename NOT LIKE '%_LAB_%'
                       AND filename NOT LIKE '%_RAD_%'
                       AND UPPER(filename) LIKE '%ELIG%'
                     ORDER BY COALESCE(uploaded_at,'') DESC,
                              id DESC
                     LIMIT 1) AS elig_attachment_id,
                   (SELECT filename FROM attachments
                     WHERE visit_id=v.visit_id
                       AND filename NOT LIKE '%_LAB_%'
                       AND filename NOT LIKE '%_RAD_%'
                       AND UPPER(filename) LIKE '%ELIG%'
                     ORDER BY COALESCE(uploaded_at,'') DESC,
                              id DESC
                     LIMIT 1) AS elig_attachment,
                   p.insurance,
                   p.dob AS dob
            FROM visits v
            JOIN patients p ON p.id = v.patient_id
            LEFT JOIN admission_orders ao
                   ON ao.id = (
                        SELECT id
                        FROM admission_orders
                        WHERE visit_id = v.visit_id
                        ORDER BY id DESC
                        LIMIT 1
                   )
        """
            + where_rows
            + """
            ORDER BY
              CASE
                WHEN v.triage_cat IN ('ES1','ESI1') THEN 1
                WHEN v.triage_cat IN ('ES2','ESI2') THEN 2
                WHEN v.triage_cat IN ('ES3','ESI3') THEN 3
                WHEN v.triage_cat IN ('ES4','ESI4') THEN 4
                WHEN v.triage_cat IN ('ES5','ESI5') THEN 5
                ELSE 99
              END,
              v.id DESC
            LIMIT ? OFFSET ?
        """
        )

        params_page = list(params_rows) + [per_page, offset]
        rows = cur.execute(sql, params_page).fetchall()

        attachment_map = _prefetch_board_attachment_pairs(
            cur, [(_fetch_one_val(rr, "visit_id", 0) or "") for rr in (rows or [])]
        )
        doctor_display_map = _prefetch_assigned_doctor_display_map(
            cur, [(_fetch_one_val(rr, "assigned_doctor", 9) or "") for rr in (rows or [])]
        )

        visits = []
        for r in rows or []:
            try:
                d = dict(r)
            except Exception:
                try:
                    d = {k: r[k] for k in r.keys()}
                except Exception:
                    d = {}
            d["age"] = calc_age(d.get("dob"))
            try:
                att = attachment_map.get((d.get("visit_id") or "").strip()) or {}
                if att:
                    d.update(att)
            except Exception:
                pass
            d["assigned_doctor_display"] = doctor_display_map.get(
                (d.get("assigned_doctor") or "").strip(),
                (d.get("assigned_doctor") or "").strip(),
            )
            d["assigned_doctor_label"] = _ensure_dr_prefix(
                d.get("assigned_doctor_display") or d.get("assigned_doctor")
            )

            created_at = d.get("created_at")
            closed_at = d.get("closed_at")
            status_val = (d.get("status") or "").upper()
            if (
                status_val
                in (
                    "DISCHARGED",
                    "TRANSFERRED",
                    "LAMA",
                    "EXPIRED",
                    "CANCELLED",
                    "CLOSED",
                    "VISIT_COMPLETED",
                    "COMPLETED",
                )
                and closed_at
            ):
                mins = calc_minutes_between(created_at, closed_at)
            else:
                mins = calc_minutes_between(
                    created_at, datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                )

            if mins is None:
                d["waiting_text"] = "-"
                d["waiting_level"] = "none"
            else:
                try:
                    mins_int = int(mins)
                except Exception:
                    mins_int = mins
                if isinstance(mins_int, int) and mins_int >= 60:
                    h = mins_int // 60
                    m = mins_int % 60
                    if h >= 24:
                        days = h // 24
                        rem_h = h % 24
                        d["waiting_text"] = f"{days}d {rem_h}h"
                    else:
                        d["waiting_text"] = f"{h}h {m:02d}m"
                else:
                    d["waiting_text"] = f"{mins_int}m"

                if mins_int is None:
                    level = "none"
                elif mins_int < 30:
                    level = "short"
                elif mins_int < 90:
                    level = "medium"
                else:
                    level = "long"
                d["waiting_level"] = level

            visits.append(d)

        # Wards list (only relevant on IPADM board)
        wards = []
        if clinic_filter == "IPADM":
            try:
                wrows = cur.execute("""
                    SELECT DISTINCT v.ward
                    FROM visits v
                    WHERE
                      v.ward IS NOT NULL
                      AND TRIM(v.ward) <> ''
                      AND (
                        COALESCE(v.clinic,'ED')='IPADM'
                        OR EXISTS (SELECT 1 FROM admission_orders x WHERE x.visit_id=v.visit_id)
                      )
                    ORDER BY v.ward
                    """).fetchall()
                wards = [
                    (wr.get("ward") if hasattr(wr, "get") else wr[0]) for wr in wrows
                ]
            except Exception:
                wards = []

        # Users list
        users = []
        try:
            urows = cur.execute(
                "SELECT username FROM users ORDER BY username"
            ).fetchall()
            users = [
                (ur.get("username") if hasattr(ur, "get") else ur[0]) for ur in urows
            ]
        except Exception:
            users = []

        pages = max(1, (int(total or 0) + int(per_page or 1) - 1) // int(per_page or 1))

        return {
            "visits": visits,
            "wards": wards,
            "users": users,
            "total": int(total or 0),
            "pages": pages,
        }

    if ttl and ttl > 0:
        ctx = _CLINIC_BOARD_CACHE.get_or_compute(
            ("clinic_board", cache_base),
            ttl,
            _compute,
        )
    else:
        ctx = _compute()

    return render_template(
        "clinic_board.html",
        visits=ctx.get("visits", []),
        clinic_filter=clinic_filter,
        status_filter=status_filter,
        ward_filter=ward_filter,
        wards=ctx.get("wards", []),
        visit_f=visit_f,
        user_f=user_f,
        physician_f=physician_f,
        q=q,
        dfrom=dfrom,
        dto=dto,
        users=ctx.get("users", []),
        assigned_physicians=_board_collect_assigned_physician_options(ctx.get("visits", [])),
        clinics=get_clinics_for_ui(),
        page=page,
        pages=ctx.get("pages", 1),
        per_page=per_page,
        total=ctx.get("total", 0),
    )


@app.route("/ip_admit/<visit_id>")
@login_required
@role_required("admin", "doctor", "nurse", "inpatient_billing")
def ip_admit(visit_id):
    clinic = (request.args.get("clinic") or "IPADM").upper()

    try:
        ensure_clinic_schema()
    except Exception:
        pass
    try:
        ensure_admission_orders_schema()
    except Exception:
        pass

    cur = get_db().cursor()

    # Active Admission Order (latest ORDERED)
    active = None
    try:
        active = cur.execute(
            """
            SELECT id FROM admission_orders
            WHERE visit_id=? AND UPPER(COALESCE(status,''))='ORDERED'
            ORDER BY id DESC
            LIMIT 1
            """,
            (visit_id,),
        ).fetchone()
    except Exception:
        active = None

    now_ts = now_display_str("%Y-%m-%d %H:%M")
    actor = session.get("username", "")

    db = get_db()
    # Always mark visit as ADMITTED (clinical state)
    db.execute("UPDATE visits SET status='ADMITTED' WHERE visit_id=?", (visit_id,))

    # Only mark an order as ADMITTED if there is an active ORDERED order.
    # (Do NOT convert a CANCELLED/REPLACED order to ADMITTED.)
    if active:
        try:
            oid = active["id"]
        except Exception:
            oid = active[0]

        db.execute(
            """
            UPDATE admission_orders
               SET status='ADMITTED',
                   admitted_at=?,
                   admitted_by=?,
                   updated_at=?,
                   updated_by=?
             WHERE id=?
            """,
            (now_ts, actor, now_ts, actor, oid),
        )

        # Keep legacy snapshot fields in visits (for backward compatible UI)
        try:
            db.execute(
                "UPDATE visits SET admission_order_status='ADMITTED' WHERE visit_id=?",
                (visit_id,),
            )
        except Exception:
            pass

    db.commit()

    log_action("IP_ADMIT", visit_id=visit_id)
    flash("Admission marked as ADMITTED.", "success")
    return redirect(url_for("clinic_board", clinic=clinic))


# Duplicate route retired 20260610: enterprise handler is canonical for POST /ip_cancel/<visit_id>.
# @app.route("/ip_cancel/<visit_id>", methods=["POST"])
@login_required
@role_required("admin", "doctor", "nurse", "inpatient_billing")
def ip_cancel(visit_id):
    clinic = (request.args.get("clinic") or "IPADM").upper()

    try:
        ensure_clinic_schema()
    except Exception:
        pass
    try:
        ensure_admission_orders_schema()
    except Exception:
        pass

    reason = (request.form.get("reason") or "").strip()
    if not reason:
        flash("Cancellation reason is required.", "warning")
        return redirect(url_for("clinic_board", clinic=clinic))

    cancelled_by = session.get("username", "")
    cancelled_at = now_display_str("%Y-%m-%d %H:%M")

    cur = get_db().cursor()
    # Cancel the latest active (ORDERED) order
    row = None
    try:
        row = cur.execute(
            """
            SELECT id FROM admission_orders
            WHERE visit_id=? AND UPPER(COALESCE(status,''))='ORDERED'
            ORDER BY id DESC
            LIMIT 1
            """,
            (visit_id,),
        ).fetchone()
    except Exception:
        row = None

    if not row:
        flash("No active admission order found to cancel.", "warning")
        return redirect(url_for("clinic_board", clinic=clinic))

    try:
        order_id = row["id"]
    except Exception:
        order_id = row[0]

    db = get_db()
    db.execute(
        """
        UPDATE admission_orders
           SET status='CANCELLED',
               cancel_reason=?,
               cancelled_by=?,
               cancelled_at=?,
               updated_at=?,
               updated_by=?
         WHERE id=?
        """,
        (reason, cancelled_by, cancelled_at, cancelled_at, cancelled_by, order_id),
    )

    # Keep legacy snapshot fields in visits (for backward compatible UI)
    try:
        db.execute(
            """
            UPDATE visits
               SET admission_order_status='CANCELLED',
                   admission_order_cancel_reason=?,
                   admission_order_cancelled_by=?,
                   admission_order_cancelled_at=?
             WHERE visit_id=?
            """,
            (reason, cancelled_by, cancelled_at, visit_id),
        )
    except Exception:
        pass

    db.commit()
    log_action("IP_CANCEL", visit_id=visit_id, details=f"Order#{order_id}|{reason}")
    flash("Admission request cancelled.", "warning")
    return redirect(url_for("clinic_board", clinic=clinic))


# Duplicate route retired 20260610: enterprise handler is canonical for /ip_admission_form/<visit_id>.
# @app.route("/ip_admission_form/<visit_id>", methods=["GET", "POST"])
@login_required
def ip_admission_form(visit_id):
    # Ensure clinic board / IP admission columns exist
    try:
        ensure_clinic_schema()
    except Exception:
        pass

    # Ensure admission_orders table exists + legacy migration
    try:
        ensure_admission_orders_schema()
    except Exception:
        pass

    cur = get_db().cursor()
    row = cur.execute(
        """
        SELECT v.visit_id, v.patient_id, v.status, COALESCE(v.clinic,'ED') AS clinic, v.ward, v.bed_no,
               v.admission_type, v.approval_no, v.payment_details, v.ip_payment_details, v.created_at,
               v.admission_destination, v.admission_ref_datetime, v.admission_ref_by, v.admission_admit_dr, v.admission_dx,
           v.admission_patient_type, v.admission_medical_service, v.admission_accommodation, v.admission_facility,
           v.admission_future_admission, v.admission_isolation, v.admission_authorization_status,
           v.admission_approval_instructions, v.admission_order_comments,
               v.admission_order_status, v.admission_order_cancel_reason, v.admission_order_cancelled_by, v.admission_order_cancelled_at,
               p.name, p.id_number, p.insurance, p.insurance_no, p.dob AS dob
        FROM visits v
        JOIN patients p ON p.id = v.patient_id
        WHERE v.visit_id = ?
        """,
        (visit_id,),
    ).fetchone()

    if not row:
        return "Visit not found", 404

    try:
        v = dict(row)
    except Exception:
        v = {k: row[k] for k in row.keys()}
    v["age"] = calc_age(v.get("dob"))

    # Load admission orders history (latest first)
    try:
        orders = cur.execute(
            """
            SELECT id, visit_id,
                   ref_datetime, ref_by, admit_dr, dx, destination, admission_type,
                   patient_type, medical_service, accommodation, facility,
                   future_admission, isolation, authorization_status,
                   approval_instructions, order_comments,
                   ward, bed_no, approval_no,
                   status,
                   cancel_reason, cancelled_by, cancelled_at,
                   admitted_by, admitted_at,
                   created_at, created_by, updated_at, updated_by
            FROM admission_orders
            WHERE visit_id=?
            ORDER BY id DESC
            """,
            (visit_id,),
        ).fetchall()
    except Exception:
        orders = []

    has_order = bool(orders)

    # latest and active order helpers
    latest_order = orders[0] if orders else None
    active_order = None
    for o in orders or []:
        try:
            st = (o["status"] or "").upper()
        except Exception:
            try:
                st = (o[11] or "").upper()
            except Exception:
                st = ""
        if st == "ORDERED":
            active_order = o
            break

    # Override display snapshot with latest order (enterprise source of truth)
    if latest_order:
        try:
            v["admission_ref_datetime"] = latest_order["ref_datetime"]
            v["admission_ref_by"] = latest_order["ref_by"]
            v["admission_admit_dr"] = latest_order["admit_dr"]
            v["admission_dx"] = latest_order["dx"]
            v["admission_destination"] = latest_order["destination"]
            # New enterprise fields (Cerner-like)
            v["admission_patient_type"] = latest_order.get("patient_type", "")
            v["admission_medical_service"] = latest_order.get("medical_service", "")
            v["admission_accommodation"] = latest_order.get("accommodation", "")
            v["admission_facility"] = latest_order.get("facility", "")
            v["admission_future_admission"] = latest_order.get("future_admission", "")
            v["admission_isolation"] = latest_order.get("isolation", "")
            v["admission_authorization_status"] = latest_order.get(
                "authorization_status", ""
            )
            v["admission_approval_instructions"] = latest_order.get(
                "approval_instructions", ""
            )
            v["admission_order_comments"] = latest_order.get("order_comments", "")
            v["admission_order_status"] = latest_order["status"]
            v["admission_order_cancel_reason"] = latest_order["cancel_reason"]
            v["admission_order_cancelled_by"] = latest_order["cancelled_by"]
            v["admission_order_cancelled_at"] = latest_order["cancelled_at"]
        except Exception:
            pass

        # Prefill admission_type on the form if empty (from the doctor's order)
        try:
            if not (v.get("admission_type") or "").strip():
                v["admission_type"] = (latest_order["admission_type"] or "").strip()
        except Exception:
            pass

    is_ipadm = (v.get("clinic") or "").upper() == "IPADM"

    # Editing permission (enterprise): allow admission staff to EDIT admission details
    # even AFTER the admission order is ADMITTED, as long as the visit has admission context
    # (direct IPADM clinic OR any admission order exists for the visit).
    has_context = bool(is_ipadm or has_order)
    can_edit = (session.get("role") in ["admin", "inpatient_billing"]) and has_context

    # UI helper: allow deep-linking with ?edit=1 to auto-open the Edit modal.
    open_edit_modal = (request.args.get("edit") or "").strip().lower() in [
        "1",
        "true",
        "yes",
        "on",
    ]

    # Allow Admission / Inpatient Billing staff to update IP admission fields
    if request.method == "POST":
        if session.get("role") not in ["admin", "inpatient_billing"]:
            flash("You do not have permission to update this admission form.", "danger")
            return redirect(url_for("ip_admission_form", visit_id=visit_id))

        ward = (request.form.get("ward") or "").strip()
        bed_no = (request.form.get("bed_no") or "").strip()
        admission_type = (request.form.get("admission_type") or "").strip()
        approval_no = (request.form.get("approval_no") or "").strip()
        ip_payment_details = (request.form.get("ip_payment_details") or "").strip()
        insurance = (request.form.get("insurance") or "").strip()
        insurance_no = (request.form.get("insurance_no") or "").strip()

        if not has_context:
            flash(
                "No Admission Order / IP admission context found for this visit. Update is not allowed here.",
                "warning",
            )
            return redirect(url_for("ip_admission_form", visit_id=visit_id))

        if not can_edit:
            flash("You do not have permission to update this admission form.", "danger")
            return redirect(url_for("ip_admission_form", visit_id=visit_id))

        now_ts = now_display_str("%Y-%m-%d %H:%M")
        actor = session.get("username", "")

        db = get_db()
        db.execute(
            "UPDATE visits SET ward=?, bed_no=?, admission_type=?, approval_no=?, ip_payment_details=? WHERE visit_id=?",
            (ward, bed_no, admission_type, approval_no, ip_payment_details, visit_id),
        )
        db.execute(
            "UPDATE patients SET insurance=?, insurance_no=? WHERE id=?",
            (insurance, insurance_no, v.get("patient_id")),
        )

        # Update the relevant order record with processing fields
        # - Prefer the active ORDERED order
        # - If none, allow updating the latest ADMITTED order (common real-life correction scenario)
        try:
            target_order = active_order
            if not target_order and latest_order:
                try:
                    lst = (latest_order["status"] or "").upper()
                except Exception:
                    lst = ""
                if lst in ("ADMITTED", "ORDERED"):
                    target_order = latest_order

            if target_order:
                try:
                    oid = target_order["id"]
                except Exception:
                    oid = target_order[0]

                db.execute(
                    """
                    UPDATE admission_orders
                       SET ward=?,
                           bed_no=?,
                           approval_no=?,
                           updated_at=?,
                           updated_by=?,
                           admission_type=CASE
                               WHEN ? IS NULL OR TRIM(?)='' THEN admission_type
                               ELSE ?
                           END
                     WHERE id=?
                    """,
                    (
                        ward,
                        bed_no,
                        approval_no,
                        now_ts,
                        actor,
                        admission_type,
                        admission_type,
                        admission_type,
                        oid,
                    ),
                )
        except Exception:
            pass

        # Keep legacy snapshot fields in visits for UI
        try:
            if has_order and (v.get("admission_order_status") or "").strip() == "":
                db.execute(
                    "UPDATE visits SET admission_order_status='ORDERED' WHERE visit_id=?",
                    (visit_id,),
                )
        except Exception:
            pass

        db.commit()
        log_action(
            "IP_UPDATE_FIELDS",
            visit_id=visit_id,
            details=f"Ward={ward}|Bed={bed_no}|Type={admission_type}|Appr={approval_no}",
        )
        flash("IP admission fields updated.", "success")
        return redirect(url_for("ip_admission_form", visit_id=visit_id))

    return render_template(
        "ip_admission_form.html",
        v=v,
        has_order=has_order,
        can_edit=can_edit,
        open_edit_modal=open_edit_modal,
        is_ipadm=is_ipadm,
        orders=orders,
    )


def _compute_ed_board_auto_card_stats(cur):
    """Return ED Board headline cards from all ED visits, ignoring user-applied filters."""
    stats = {
        "total": 0,
        "registered": 0,
        "visit_progress": 0,
        "high_acuity": 0,
        "visit_completed": 0,
        "called": 0,
        "cancelled": 0,
    }
    if cur is None:
        return stats

    try:
        rows = cur.execute("""
            SELECT UPPER(COALESCE(status, '')) AS status, COUNT(*) AS c
            FROM visits
            WHERE COALESCE(clinic,'ED')='ED'
            GROUP BY UPPER(COALESCE(status, ''))
            """).fetchall()
        for row in rows or []:
            try:
                key = (row.get("status") or "").upper()
                count = int(row.get("c") or 0)
            except Exception:
                try:
                    key = (row[0] or "").upper()
                    count = int(row[1] or 0)
                except Exception:
                    continue
            stats["total"] += count
            if key in ("OPEN", "REGISTERED"):
                stats["registered"] += count
            elif key in ("VISIT_PROGRESS", "IN_TREATMENT"):
                stats["visit_progress"] += count
            elif key in ("VISIT_COMPLETED", "COMPLETED"):
                stats["visit_completed"] += count
            elif key == "CALLED":
                stats["called"] += count
            elif key == "CANCELLED":
                stats["cancelled"] += count
    except Exception:
        pass

    try:
        rows = cur.execute("""
            SELECT UPPER(COALESCE(triage_cat, '')) AS triage_cat, COUNT(*) AS c
            FROM visits
            WHERE COALESCE(clinic,'ED')='ED'
            GROUP BY UPPER(COALESCE(triage_cat, ''))
            """).fetchall()
        for row in rows or []:
            try:
                key = (row.get("triage_cat") or "").upper()
                count = int(row.get("c") or 0)
            except Exception:
                try:
                    key = (row[0] or "").upper()
                    count = int(row[1] or 0)
                except Exception:
                    continue
            if key in ("ES1", "ES2", "ESI1", "ESI2"):
                stats["high_acuity"] += count
    except Exception:
        pass

    return stats


# ============================================================
# ED Board
# ============================================================


# ------------------------------------------------------------
# ED Board performance cache (Safe / short TTL)
#
# Under heavy load (650~1000 active users), the home page ("/")
# becomes the hottest endpoint. A DB "stampede" can happen if
# hundreds of requests run the same COUNT / GROUP BY queries at
# the same time.
#
# Fix:
# - Cache board rows / counters / total / users list for a short TTL.
# - "Single-flight" behavior: if a cache key is missing, ONLY ONE
#   thread computes it while others wait. This reduces DB pressure
#   dramatically and avoids timeouts/500 under load.
#
# Controls (config.local.json):
#   ED_BOARD_CACHE_SECONDS               (default 0 -> disabled)
#   ED_BOARD_ROWS_CACHE_SECONDS          (default ED_BOARD_CACHE_SECONDS)
#   ED_BOARD_COUNTERS_CACHE_SECONDS      (default ED_BOARD_CACHE_SECONDS)
#   ED_BOARD_TOTAL_CACHE_SECONDS         (default ED_BOARD_CACHE_SECONDS)
#   ED_BOARD_USERS_CACHE_SECONDS         (default 60)
#   ED_BOARD_ENABLE_COUNTERS             (default true)
#   ED_BOARD_ENABLE_USER_FILTER          (default true)
#   ED_BOARD_DISABLE_TOTAL_COUNT         (default false)
# ------------------------------------------------------------


class _SingleFlightTTLCache:
    def __init__(self):
        self._lock = threading.Lock()
        self._data = {}  # key -> (expires_ts, value)
        self._inflight = {}  # key -> threading.Event

    def get(self, key):
        now = time.time()
        with self._lock:
            it = self._data.get(key)
            if not it:
                return None
            exp, val = it
            if exp is not None and exp >= now:
                return val
            # expired
            try:
                del self._data[key]
            except Exception:
                pass
        return None

    def set(self, key, value, ttl_seconds: float):
        try:
            ttl = float(ttl_seconds)
        except Exception:
            ttl = 0.0
        exp = None
        if ttl > 0:
            exp = time.time() + ttl
        with self._lock:
            self._data[key] = (exp, value)

    def get_or_compute(self, key, ttl_seconds: float, fn, wait_timeout: float = 120.0):
        def _get_unlocked(now_ts):
            it = self._data.get(key)
            if not it:
                return None
            exp, val = it
            if exp is not None and exp >= now_ts:
                return val
            try:
                del self._data[key]
            except Exception:
                pass
            return None

        now = time.time()
        with self._lock:
            cached = _get_unlocked(now)
            if cached is not None:
                return cached
            ev = self._inflight.get(key)
            leader = ev is None
            if leader:
                ev = threading.Event()
                self._inflight[key] = ev

        if not leader:
            try:
                ev.wait(timeout=wait_timeout)
            except Exception:
                pass
            cached = self.get(key)
            if cached is not None:
                return cached
            val = fn()
            try:
                self.set(key, val, ttl_seconds)
            except Exception:
                pass
            return val

        try:
            val = fn()
            try:
                self.set(key, val, ttl_seconds)
            except Exception:
                pass
            return val
        finally:
            with self._lock:
                try:
                    ev.set()
                except Exception:
                    pass
                try:
                    del self._inflight[key]
                except Exception:
                    pass


# Prefer Redis shared cache when available (multi-instance + high load)
try:
    if (
        redis_support is not None
        and getattr(redis_support, "redis_cache_enabled", lambda: False)()
    ):
        _ED_BOARD_ROWS_CACHE = redis_support.RedisSingleFlightTTLCache(
            namespace="ed_board_rows"
        )
        _ED_BOARD_COUNTS_CACHE = redis_support.RedisSingleFlightTTLCache(
            namespace="ed_board_counts"
        )
        _ED_BOARD_TOTAL_CACHE = redis_support.RedisSingleFlightTTLCache(
            namespace="ed_board_total"
        )
        _ED_BOARD_USERS_CACHE = redis_support.RedisSingleFlightTTLCache(
            namespace="ed_board_users"
        )
        _ED_BOARD_CARD_STATS_CACHE = redis_support.RedisSingleFlightTTLCache(
            namespace="ed_board_card_stats"
        )
    else:
        _ED_BOARD_ROWS_CACHE = _SingleFlightTTLCache()
        _ED_BOARD_COUNTS_CACHE = _SingleFlightTTLCache()
        _ED_BOARD_TOTAL_CACHE = _SingleFlightTTLCache()
        _ED_BOARD_USERS_CACHE = _SingleFlightTTLCache()
        _ED_BOARD_CARD_STATS_CACHE = _SingleFlightTTLCache()
except Exception:
    _ED_BOARD_ROWS_CACHE = _SingleFlightTTLCache()
    _ED_BOARD_COUNTS_CACHE = _SingleFlightTTLCache()
    _ED_BOARD_TOTAL_CACHE = _SingleFlightTTLCache()
    _ED_BOARD_USERS_CACHE = _SingleFlightTTLCache()
    _ED_BOARD_CARD_STATS_CACHE = _SingleFlightTTLCache()


# Other boards: short TTL caches to reduce DB pressure under load
try:
    if (
        redis_support is not None
        and getattr(redis_support, "redis_cache_enabled", lambda: False)()
    ):
        _CLINIC_BOARD_CACHE = redis_support.RedisSingleFlightTTLCache(
            namespace="clinic_board"
        )
        _LAB_BOARD_CACHE = redis_support.RedisSingleFlightTTLCache(
            namespace="lab_board"
        )
        _RAD_BOARD_CACHE = redis_support.RedisSingleFlightTTLCache(
            namespace="radiology_board"
        )
    else:
        _CLINIC_BOARD_CACHE = _SingleFlightTTLCache()
        _LAB_BOARD_CACHE = _SingleFlightTTLCache()
        _RAD_BOARD_CACHE = _SingleFlightTTLCache()
except Exception:
    _CLINIC_BOARD_CACHE = _SingleFlightTTLCache()
    _LAB_BOARD_CACHE = _SingleFlightTTLCache()
    _RAD_BOARD_CACHE = _SingleFlightTTLCache()

# Lightweight shared cache for register form lookups (safe for multi-instance when Redis is enabled).
try:
    if (
        redis_support is not None
        and getattr(redis_support, "redis_cache_enabled", lambda: False)()
    ):
        _REG_FORM_CACHE = redis_support.RedisSingleFlightTTLCache(namespace="register_form")
    else:
        _REG_FORM_CACHE = _SingleFlightTTLCache()
except Exception:
    _REG_FORM_CACHE = _SingleFlightTTLCache()


try:
    if (
        redis_support is not None
        and getattr(redis_support, "redis_cache_enabled", lambda: False)()
    ):
        _AUTO_SUMMARY_CACHE = redis_support.RedisSingleFlightTTLCache(namespace="auto_summary")
        _PATIENT_LOOKUP_CACHE = redis_support.RedisSingleFlightTTLCache(namespace="patient_lookup")
        _PDF_RENDER_CACHE = redis_support.RedisSingleFlightTTLCache(namespace="pdf_render")
    else:
        _AUTO_SUMMARY_CACHE = _SingleFlightTTLCache()
        _PATIENT_LOOKUP_CACHE = _SingleFlightTTLCache()
        _PDF_RENDER_CACHE = _SingleFlightTTLCache()
except Exception:
    _AUTO_SUMMARY_CACHE = _SingleFlightTTLCache()
    _PATIENT_LOOKUP_CACHE = _SingleFlightTTLCache()
    _PDF_RENDER_CACHE = _SingleFlightTTLCache()


def _cache_delete_key(cache_obj, key_obj):
    if cache_obj is None:
        return
    try:
        lock = getattr(cache_obj, "_lock", None)
        data = getattr(cache_obj, "_data", None)
        if lock is not None and data is not None:
            with lock:
                data.pop(key_obj, None)
    except Exception:
        pass
    try:
        if redis_support is not None and hasattr(cache_obj, "_key"):
            client = redis_support.get_cache_client()
            if client is not None:
                client.delete(cache_obj._key(key_obj))
    except Exception:
        pass


def _pdf_cache_ttl_seconds() -> float:
    return _cfg_float_runtime("PDF_CACHE_SECONDS", 45.0)


def _invalidate_visit_runtime_caches(visit_id: str):
    vid = (visit_id or "").strip()
    if not vid:
        return
    _cache_delete_key(_AUTO_SUMMARY_CACHE, ("auto_summary", vid))
    _cache_delete_key(_PDF_RENDER_CACHE, ("clinical_order_pdf", vid))
    _cache_delete_key(_PDF_RENDER_CACHE, ("provider_note_pdf", vid))
    _cache_delete_key(_PDF_RENDER_CACHE, ("nursing_notes_pdf", vid))


def _invalidate_register_lookup_caches(*keys):
    for key in keys:
        if key:
            _cache_delete_key(_PATIENT_LOOKUP_CACHE, key)


@app.route("/")
@login_required
def ed_board():
    try:
        ensure_patients_mrn_schema()
    except Exception:
        pass
    """
    ED Board: filterable/paged list of ED visits with simple triage coloring,
    wait time/length-of-stay calculation, and small summary counters.

    PERF NOTES (fixes from load test):
    - Avoid acquiring a DB connection unless we actually have a cache miss.
      (Previously every request grabbed a pooled connection even on cache hits.)
    - Make COUNT / counters queries operate on visits only (no JOIN/attachments),
      which reduces DB work and keeps the pool healthier under load.
    - Use created_at lexical range filtering (created_at is stored as ISO TEXT)
      to keep indexes usable on both SQLite and PostgreSQL.
    - Tune APP_CONFIG: ED_BOARD_CACHE_SECONDS / ED_BOARD_ROWS_CACHE_SECONDS /
      ED_BOARD_COUNTERS_CACHE_SECONDS (higher values reduce DB reads under burst).
    - PostgreSQL: composite index on visits (clinic, created_at) or (UPPER(status), created_at)
      for ED filters; run ANALYZE after bulk loads.
    - Prefer role-based login landing (see login_redirect_for_role) so fewer users
      hit this route simultaneously after shift changes.
    """
    status_filter = (request.args.get("status", "ALL") or "ALL").strip().upper()
    cat_filter = (request.args.get("cat", "ALL") or "ALL").strip().upper()
    visit_f = (request.args.get("visit_id", "") or "").strip()
    user_f = (request.args.get("user", "") or "").strip()
    physician_f = (request.args.get("assigned_physician", "") or "").strip()
    q = (request.args.get("q", "") or "").strip()
    dfrom = (request.args.get("date_from", "") or "").strip()
    dto = (request.args.get("date_to", "") or "").strip()

    # --- config helpers (values may come from JSON as str) ---
    def _cfg_float(key: str, default: float) -> float:
        v = APP_CONFIG.get(key, default)
        try:
            if v is None:
                return float(default)
            if isinstance(v, (int, float)):
                return float(v)
            s = str(v).strip()
            if not s:
                return float(default)
            return float(s)
        except Exception:
            return float(default)

    def _cfg_bool(key: str, default: bool) -> bool:
        v = APP_CONFIG.get(key, default)
        try:
            if isinstance(v, bool):
                return v
            s = str(v).strip().lower()
            if s in ("1", "true", "yes", "y", "on"):
                return True
            if s in ("0", "false", "no", "n", "off"):
                return False
            return bool(default)
        except Exception:
            return bool(default)

    ttl_base = _cfg_float("ED_BOARD_CACHE_SECONDS", 0.0)
    ttl_rows = _cfg_float("ED_BOARD_ROWS_CACHE_SECONDS", ttl_base)
    ttl_counts = _cfg_float("ED_BOARD_COUNTERS_CACHE_SECONDS", ttl_base)
    ttl_total = _cfg_float("ED_BOARD_TOTAL_CACHE_SECONDS", ttl_base)
    ttl_users = _cfg_float("ED_BOARD_USERS_CACHE_SECONDS", 60.0)
    ttl_card_stats = _cfg_float("ED_BOARD_CARD_STATS_CACHE_SECONDS", ttl_counts or ttl_base)

    enable_counters = _cfg_bool("ED_BOARD_ENABLE_COUNTERS", True)
    enable_user_filter = _cfg_bool("ED_BOARD_ENABLE_USER_FILTER", True)
    disable_total_count = _cfg_bool("ED_BOARD_DISABLE_TOTAL_COUNT", False)

    # Cache key base (filters only; NOT per-session user)
    cache_base = (
        str(status_filter or ""),
        str(cat_filter or ""),
        str(visit_f or ""),
        str(user_f or ""),
        str(physician_f or ""),
        str(q or ""),
        str(dfrom or ""),
        str(dto or ""),
        str(DB_ENGINE or ""),
    )

    # NOTE: created_at is stored as ISO TEXT (YYYY-MM-DD HH:MM:SS).
    # Using lexical ranges keeps indexes usable on both SQLite/Postgres.
    def _date_floor(d: str) -> str:
        return f"{d} 00:00:00"

    def _date_ceil_excl(d: str) -> str:
        try:
            dt = datetime.strptime(d, "%Y-%m-%d") + timedelta(days=1)
            return dt.strftime("%Y-%m-%d 00:00:00")
        except Exception:
            # Fallback: very permissive upper bound (still better than date() on column)
            return f"{d} 23:59:59"

    # Build WHERE clause for visits-only queries (used by counters/total)
    where_sql = " WHERE 1=1 AND COALESCE(v.clinic,'ED')='ED'"
    params = []

    # Status / triage filters
    if status_filter != "ALL":
        if status_filter in ("OPEN", "REGISTERED"):
            where_sql += " AND UPPER(COALESCE(v.status,'')) IN ('OPEN','REGISTERED')"
        else:
            where_sql += " AND UPPER(COALESCE(v.status,'')) = ?"
            params.append(status_filter)

    if cat_filter != "ALL":
        where_sql += " AND v.triage_cat = ?"
        params.append(cat_filter)

    # Text filters
    if visit_f:
        if DB_ENGINE == "postgres":
            where_sql += " AND v.visit_id ILIKE ?"
        else:
            where_sql += " AND v.visit_id LIKE ?"
        params.append(f"%{visit_f}%")

    if user_f:
        where_sql += " AND v.created_by = ?"
        params.append(user_f)

    where_sql, params = _append_assigned_physician_filter_sql(
        where_sql, params, physician_f, visit_alias="v"
    )

    where_sql, params = _append_patient_search_sql(
        where_sql, params, q, patient_alias="p", visit_alias="v"
    )

    # Date filters (based on created_at)
    if dfrom:
        where_sql += " AND v.created_at >= ?"
        params.append(_date_floor(dfrom))
    if dto:
        where_sql += " AND v.created_at < ?"
        params.append(_date_ceil_excl(dto))

    page, per_page, offset = get_page_args(30)

    # For counters / totals, avoid joining patients unless free-text patient search is active.
    _summary_from_sql = (
        " FROM visits v JOIN patients p ON p.id = v.patient_id"
        if q
        else " FROM visits v"
    )

    # Lazy DB cursor (only opened when a cache miss requires it)
    _db = None
    _cur = None

    def _cursor():
        nonlocal _db, _cur
        if _cur is None:
            _db = get_db()
            _cur = _db.cursor()
        return _cur

    # ----------------------------
    # Summary counters (cached)
    # ----------------------------
    status_counts = {}
    triage_counts = {}
    card_stats = {
        "total": 0,
        "registered": 0,
        "visit_progress": 0,
        "high_acuity": 0,
        "visit_completed": 0,
        "called": 0,
        "cancelled": 0,
    }

    def _compute_counts():
        sc = {}
        tc = {}
        cur = _cursor()
        try:
            rows = cur.execute(
                "SELECT UPPER(COALESCE(v.status,'')) AS status, COUNT(*) AS c"
                + _summary_from_sql
                + where_sql
                + " GROUP BY UPPER(COALESCE(v.status,''))",
                params,
            ).fetchall()
            for row in rows or []:
                try:
                    key = (row.get("status") or "UNKNOWN").upper()
                    c = row.get("c")
                except Exception:
                    try:
                        key = (row[0] or "UNKNOWN").upper()
                        c = row[1]
                    except Exception:
                        continue
                try:
                    sc[key] = int(c or 0)
                except Exception:
                    sc[key] = c

            # Merge OPEN + REGISTERED as one workflow group (Registered)
            try:
                _open_c = int(sc.get("OPEN", 0) or 0) + int(
                    sc.get("REGISTERED", 0) or 0
                )
                if _open_c:
                    sc["REGISTERED"] = _open_c
                    sc["OPEN"] = _open_c  # alias for backward compatibility
            except Exception:
                pass

            rows = cur.execute(
                "SELECT v.triage_cat AS triage_cat, COUNT(*) AS c"
                + _summary_from_sql
                + where_sql
                + " GROUP BY v.triage_cat",
                params,
            ).fetchall()
            for row in rows or []:
                try:
                    key = row.get("triage_cat") or "UNK"
                    c = row.get("c")
                except Exception:
                    try:
                        key = row[0] or "UNK"
                        c = row[1]
                    except Exception:
                        continue
                try:
                    tc[key] = int(c or 0)
                except Exception:
                    tc[key] = c
        except Exception:
            sc = {}
            tc = {}
        return sc, tc

    if enable_counters:
        if ttl_counts and ttl_counts > 0:
            status_counts, triage_counts = _ED_BOARD_COUNTS_CACHE.get_or_compute(
                ("ed_board_counts", cache_base),
                ttl_counts,
                _compute_counts,
            )
        else:
            status_counts, triage_counts = _compute_counts()

    def _compute_card_stats():
        return _compute_ed_board_auto_card_stats(_cursor())

    try:
        if ttl_card_stats and ttl_card_stats > 0:
            card_stats = _ED_BOARD_CARD_STATS_CACHE.get_or_compute(
                ("ed_board_card_stats", str(DB_ENGINE or "")),
                ttl_card_stats,
                _compute_card_stats,
            )
        else:
            card_stats = _compute_card_stats()
    except Exception:
        pass

    # ----------------------------
    # Total count (cached)
    # ----------------------------
    total = 0

    def _compute_total():
        cur = _cursor()
        try:
            r = cur.execute(
                "SELECT COUNT(*) AS cnt" + _summary_from_sql + where_sql,
                params,
            ).fetchone()
            if not r:
                return 0
            try:
                return int(r.get("cnt") or 0)
            except Exception:
                return int(r[0])
        except Exception:
            return 0

    if not disable_total_count:
        if ttl_total and ttl_total > 0:
            total = _ED_BOARD_TOTAL_CACHE.get_or_compute(
                ("ed_board_total", cache_base),
                ttl_total,
                _compute_total,
            )
        else:
            total = _compute_total()

    pages = (total + per_page - 1) // per_page if per_page else 1
    if pages <= 0:
        pages = 1
    if page > pages:
        page = pages
        offset = (page - 1) * per_page

    # ----------------------------
    # Main rows (cached)
    # ----------------------------
    def _compute_visits():
        cur = _cursor()
        sql2 = (
            """
            SELECT v.visit_id,
                   v.queue_no,
                   v.triage_status,
                   v.triage_cat,
                   v.status,
                   v.payment_details,
                   v.created_at,
                   v.created_by,
                   v.closed_at,
                   v.location,
                   v.bed_no,
                   v.bed_status,
                   v.task_reg,
                   v.task_ekg,
                   v.task_sepsis,
                   v.visit_type,
                   v.assigned_doctor,
                   v.allergy_status,
                   v.allergy_details,
                   p.name,
                   p.mrn,
                   p.id_number,
                   p.insurance,
                   (
                       SELECT a.id
                       FROM attachments a
                       WHERE a.visit_id = v.visit_id
                         AND a.filename NOT LIKE '%_LAB_%'
                         AND a.filename NOT LIKE '%_RAD_%'
                         AND UPPER(a.filename) NOT LIKE '%ELIG%'
                       ORDER BY CASE WHEN UPPER(a.filename) LIKE '%ID%' THEN 0 ELSE 1 END,
                                COALESCE(a.uploaded_at,'') DESC,
                                a.id DESC
                       LIMIT 1
                   ) AS id_attachment_id,
                   (
                       SELECT a.filename
                       FROM attachments a
                       WHERE a.visit_id = v.visit_id
                         AND a.filename NOT LIKE '%_LAB_%'
                         AND a.filename NOT LIKE '%_RAD_%'
                         AND UPPER(a.filename) NOT LIKE '%ELIG%'
                       ORDER BY CASE WHEN UPPER(a.filename) LIKE '%ID%' THEN 0 ELSE 1 END,
                                COALESCE(a.uploaded_at,'') DESC,
                                a.id DESC
                       LIMIT 1
                   ) AS id_attachment,
                   (
                       SELECT a.id
                       FROM attachments a
                       WHERE a.visit_id = v.visit_id
                         AND a.filename NOT LIKE '%_LAB_%'
                         AND a.filename NOT LIKE '%_RAD_%'
                         AND UPPER(a.filename) LIKE '%ELIG%'
                       ORDER BY COALESCE(a.uploaded_at,'') DESC,
                                a.id DESC
                       LIMIT 1
                   ) AS elig_attachment_id,
                   (
                       SELECT a.filename
                       FROM attachments a
                       WHERE a.visit_id = v.visit_id
                         AND a.filename NOT LIKE '%_LAB_%'
                         AND a.filename NOT LIKE '%_RAD_%'
                         AND UPPER(a.filename) LIKE '%ELIG%'
                       ORDER BY COALESCE(a.uploaded_at,'') DESC,
                                a.id DESC
                       LIMIT 1
                   ) AS elig_attachment,
                   p.dob AS dob
            FROM visits v
            JOIN patients p ON p.id = v.patient_id
        """
            + where_sql
            + """
            ORDER BY
                CASE
                    WHEN v.triage_cat IN ('ES1','ESI1') THEN 1
                    WHEN v.triage_cat IN ('ES2','ESI2') THEN 2
                    WHEN v.triage_cat IN ('ES3','ESI3') THEN 3
                    WHEN v.triage_cat IN ('ES4','ESI4') THEN 4
                    WHEN v.triage_cat IN ('ES5','ESI5') THEN 5
                    ELSE 6
                END,
                v.id DESC
            LIMIT ? OFFSET ?
        """
        )
        params2 = list(params) + [per_page, offset]
        rows = cur.execute(sql2, params2).fetchall()

        attachment_map = _prefetch_board_attachment_pairs(
            cur, [(_fetch_one_val(rr, "visit_id", 0) or "") for rr in (rows or [])]
        )
        doctor_display_map = _prefetch_assigned_doctor_display_map(
            cur, [(_fetch_one_val(rr, "assigned_doctor", 16) or "") for rr in (rows or [])]
        )

        visits_local = []
        for r in rows or []:
            try:
                d = dict(r)
            except Exception:
                d = {}
                try:
                    # very old row shape fallback
                    d = {
                        "visit_id": r[0],
                        "queue_no": r[1],
                        "triage_status": r[2],
                        "triage_cat": r[3],
                        "status": r[4],
                        "payment_details": r[5],
                        "created_at": r[6],
                        "created_by": r[7],
                        "closed_at": r[8],
                        "location": r[9],
                        "bed_no": r[10],
                        "bed_status": r[11],
                        "task_reg": r[12],
                        "task_ekg": r[13],
                        "task_sepsis": r[14],
                        "visit_type": r[15],
                        "assigned_doctor": r[16],
                        "allergy_status": r[17],
                        "allergy_details": r[18],
                        "name": r[19],
                        "mrn": r[20],
                        "id_number": r[21],
                        "insurance": r[22],
                        "id_attachment_id": r[23],
                        "id_attachment": r[24],
                        "elig_attachment_id": r[25],
                        "elig_attachment": r[26],
                        "dob": r[27],
                    }
                except Exception:
                    d = {}

            d["age"] = calc_age(d.get("dob"))
            try:
                att = attachment_map.get((d.get("visit_id") or "").strip()) or {}
                if att:
                    d.update(att)
            except Exception:
                pass
            d["assigned_doctor_display"] = doctor_display_map.get(
                (d.get("assigned_doctor") or "").strip(),
                (d.get("assigned_doctor") or "").strip(),
            )
            d["assigned_doctor_label"] = _ensure_dr_prefix(
                d.get("assigned_doctor_display") or d.get("assigned_doctor")
            )

            created_at = d.get("created_at")
            closed_at = d.get("closed_at")
            status_val = (d.get("status") or "").upper()

            if (
                status_val
                in (
                    "DISCHARGED",
                    "TRANSFERRED",
                    "LAMA",
                    "EXPIRED",
                    "CANCELLED",
                    "CLOSED",
                )
                and closed_at
            ):
                mins = calc_minutes_between(created_at, closed_at)
            else:
                mins = calc_minutes_between(created_at)

            d["waiting_minutes"] = mins
            if mins is None:
                d["waiting_text"] = "-"
                d["waiting_level"] = "none"
            else:
                try:
                    mins_int = int(mins)
                except Exception:
                    mins_int = mins

                if isinstance(mins_int, int) and mins_int >= 60:
                    h = mins_int // 60
                    m = mins_int % 60
                    if h >= 24:
                        days = h // 24
                        rem_h = h % 24
                        d["waiting_text"] = f"{days}d {rem_h}h"
                    else:
                        d["waiting_text"] = f"{h}h {m:02d}m"
                else:
                    d["waiting_text"] = f"{mins_int}m"

                if mins_int is None:
                    level = "none"
                elif mins_int < 30:
                    level = "short"
                elif mins_int < 90:
                    level = "medium"
                else:
                    level = "long"
                d["waiting_level"] = level

            visits_local.append(d)

        return visits_local

    visits = []
    if ttl_rows and ttl_rows > 0:
        visits = _ED_BOARD_ROWS_CACHE.get_or_compute(
            ("ed_board_rows", cache_base, int(page), int(per_page)),
            ttl_rows,
            _compute_visits,
        )
    else:
        visits = _compute_visits()

    # ----------------------------
    # Users list for filter dropdown (cached)
    # ----------------------------
    users = []

    def _compute_users():
        cur = _cursor()
        try:
            out = []
            for r in cur.execute(
                "SELECT DISTINCT created_by FROM visits v WHERE COALESCE(v.clinic,'ED')='ED' AND created_by IS NOT NULL AND TRIM(created_by) <> '' ORDER BY created_by"
            ).fetchall():
                try:
                    v = r.get("created_by")
                except Exception:
                    v = r[0] if r else None
                if v is None:
                    continue
                s = str(v).strip()
                if not s:
                    continue
                out.append({"created_by": s})
            return out
        except Exception:
            return []

    if enable_user_filter:
        if ttl_users and ttl_users > 0:
            users = _ED_BOARD_USERS_CACHE.get_or_compute(
                ("ed_board_users",),
                ttl_users,
                _compute_users,
            )
        else:
            users = _compute_users()

    return render_template(
        "ed_board.html",
        visits=visits,
        status_filter=status_filter,
        cat_filter=cat_filter,
        visit_f=visit_f,
        user_f=user_f,
        physician_f=physician_f,
        q=q,
        dfrom=dfrom,
        dto=dto,
        users=users,
        assigned_physicians=_board_collect_assigned_physician_options(visits),
        page=page,
        pages=pages,
        per_page=per_page,
        total=total,
        status_counts=status_counts,
        triage_counts=triage_counts,
        card_stats=card_stats,
    )


@app.route("/export/ed_board.csv")
@login_required
def export_ed_board_csv():
    cur = get_db().cursor()
    rows = cur.execute("""
        SELECT v.queue_no, v.visit_id, p.name, p.mrn, p.id_number, p.phone,
               p.insurance, p.insurance_no, v.triage_status,
               v.triage_cat, v.status, v.payment_details, v.created_at
        FROM visits v
        JOIN patients p ON p.id = v.patient_id
        WHERE COALESCE(v.clinic,'ED')='ED'
        ORDER BY v.id DESC LIMIT 500
    """).fetchall()

    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(
        [
            "Queue",
            "Case No",
            "Name",
            "MRN",
            "ID",
            "Phone",
            "Insurance",
            "Insurance No",
            "TriageStatus",
            "CAT",
            "Status",
            "Payment Details",
            "Created",
        ]
    )
    for r in rows:
        writer.writerow(list(r))

    return Response(
        output.getvalue().encode("utf-8-sig"),
        mimetype="text/csv",
        headers={"Content-Disposition": "attachment; filename=ed_board.csv"},
    )


@app.route("/export/labs.csv")
@login_required
def export_labs_csv():
    """
    Export lab requests as CSV using the same filters as the Lab Board.
    Includes extra LIS timestamps and simple TAT breakdowns.
    """
    status_filter = (request.args.get("status", "ALL") or "ALL").strip().upper()
    q = request.args.get("q", "").strip()
    dfrom = request.args.get("date_from", "").strip()
    dto = request.args.get("date_to", "").strip()

    cur = get_db().cursor()
    sql = """
        SELECT lr.id,
               v.visit_id,
               p.name,
               p.mrn,
               p.id_number,
               lr.test_name,
               lr.status,
               lr.requested_at,
               lr.collected_at,
               lr.received_at,
               lr.in_lab_at,
               lr.reported_at,
               lr.result_text,
               lr.requested_by,
               lr.collected_by,
               lr.received_by,
               lr.in_lab_by,
               lr.reported_by
        FROM lab_requests lr
        JOIN visits v ON v.visit_id = lr.visit_id
        JOIN patients p ON p.id = v.patient_id
        WHERE 1=1
    """
    params = []

    # Status filter (same as Lab Board)
    if status_filter == "PENDING":
        sql += " AND lr.status IN ('REQUESTED','COLLECTED','RECEIVED','IN_LAB')"
    elif status_filter == "REPORTED":
        sql += " AND lr.status='REPORTED'"
    elif status_filter in (
        "REQUESTED",
        "COLLECTED",
        "RECEIVED",
        "IN_LAB",
        "REPORTED",
        "CANCELLED",
    ):
        sql += " AND lr.status=?"
        params.append(status_filter)
    elif status_filter == "ALL":
        pass
    else:
        # Unknown value -> fall back to ALL (no extra filter)
        status_filter = "ALL"

    # Date filters based on requested_at
    if dfrom:
        sql += " AND date(lr.requested_at) >= date(?)"
        params.append(dfrom)
    if dto:
        sql += " AND date(lr.requested_at) <= date(?)"
        params.append(dto)

    # Text search
    if q:
        like = f"%{q}%"
        sql += " AND (p.name LIKE ? OR p.mrn LIKE ? OR p.id_number LIKE ? OR v.visit_id LIKE ? OR lr.test_name LIKE ?)"
        params.extend([like, like, like, like, like])

    # Oldest first within each group, but no hard LIMIT for export
    sql += (
        " ORDER BY "
        " CASE WHEN lr.status IN ('REQUESTED','COLLECTED','RECEIVED','IN_LAB') THEN 0 ELSE 1 END, "
        " lr.requested_at ASC, lr.id ASC"
    )

    rows = cur.execute(sql, params).fetchall()

    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(
        [
            "ID",
            "Case No",
            "Name",
            "MRN",
            "ID Number",
            "Test",
            "Status",
            "RequestedAt",
            "CollectedAt",
            "ReceivedAt",
            "InLabAt",
            "ReportedAt",
            "RequestedBy",
            "CollectedBy",
            "ReceivedBy",
            "InLabBy",
            "ReportedBy",
            "ResultText",
            "TAT_req_to_collect_min",
            "TAT_collect_to_receive_min",
            "TAT_receive_to_inlab_min",
            "TAT_inlab_to_report_min",
            "TAT_req_to_report_min",
        ]
    )

    for r in rows:
        # Compute simple TAT segments in minutes (can be None)
        req = r["requested_at"]
        col = r["collected_at"]
        rec = r["received_at"]
        inlab = r["in_lab_at"]
        rep = r["reported_at"]

        tat_req_collect = calc_minutes_between(req, col) if col else None
        tat_collect_receive = calc_minutes_between(col, rec) if col and rec else None
        tat_receive_inlab = calc_minutes_between(rec, inlab) if rec and inlab else None
        tat_inlab_report = calc_minutes_between(inlab, rep) if inlab and rep else None
        tat_req_report = calc_minutes_between(req, rep) if rep else None

        writer.writerow(
            [
                r["id"],
                r["visit_id"],
                r["name"],
                r["mrn"],
                r["id_number"],
                r["test_name"],
                r["reason_for_exam"],
                r["status"],
                r["requested_at"],
                r["collected_at"],
                r["received_at"],
                r["in_lab_at"],
                r["reported_at"],
                r["requested_by"],
                r["collected_by"],
                r["received_by"],
                r["in_lab_by"],
                r["reported_by"],
                (r["result_text"] or "").replace("\r", " ").replace("\n", " "),
                tat_req_collect,
                tat_collect_receive,
                tat_receive_inlab,
                tat_inlab_report,
                tat_req_report,
            ]
        )

    return Response(
        output.getvalue().encode("utf-8-sig"),
        mimetype="text/csv",
        headers={"Content-Disposition": "attachment; filename=labs.csv"},
    )


@app.route("/export/radiology.csv")
@login_required
def export_radiology_csv():
    """
    Export radiology requests as CSV using the same filters as the Radiology Board.
    """
    status_filter = (request.args.get("status", "ALL") or "ALL").strip().upper()
    q = request.args.get("q", "").strip()
    dfrom = request.args.get("date_from", "").strip()
    dto = request.args.get("date_to", "").strip()

    cur = get_db().cursor()
    sql = """
        SELECT rr.id,
               v.visit_id,
               p.name,
               p.mrn,
               p.id_number,
               rr.test_name,
               COALESCE(rr.reason_for_exam, '') AS reason_for_exam,
               rr.status,
               rr.requested_at,
               rr.requested_by,
               rr.sent_at,
               rr.sent_by,
               rr.received_at,
               rr.received_by,
               rr.in_process_at,
               rr.in_process_by,
               rr.done_at,
               rr.done_by,
               rr.reported_at,
               rr.reported_by,
               rr.report_text
        FROM radiology_requests rr
        JOIN visits v ON v.visit_id = rr.visit_id
        JOIN patients p ON p.id = v.patient_id
        WHERE 1=1
    """
    params = []

    # Status filter
    if status_filter == "PENDING":
        sql += (
            " AND rr.status IN ('REQUESTED','SENT','RECEIVED','UNDER_PROCESS','DONE')"
        )
    elif status_filter == "REPORTED":
        sql += " AND rr.status='REPORTED'"
    elif status_filter in (
        "REQUESTED",
        "SENT",
        "RECEIVED",
        "UNDER_PROCESS",
        "DONE",
        "CANCELLED",
    ):
        sql += " AND rr.status=?"
        params.append(status_filter)
    elif status_filter == "ALL":
        pass
    else:
        # Unknown value -> fall back to ALL (no extra filter)
        status_filter = "ALL"

    # Date filters based on requested_at
    if dfrom:
        sql += " AND date(rr.requested_at) >= date(?)"
        params.append(dfrom)
    if dto:
        sql += " AND date(rr.requested_at) <= date(?)"
        params.append(dto)

    # Text search
    if q:
        like = f"%{q}%"
        sql += " AND (p.name LIKE ? OR p.mrn LIKE ? OR p.id_number LIKE ? OR v.visit_id LIKE ? OR rr.test_name LIKE ?)"
        params.extend([like, like, like, like, like])

    sql += " ORDER BY rr.id DESC"

    rows = cur.execute(sql, params).fetchall()

    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(
        [
            "ID",
            "Case No",
            "Name",
            "MRN",
            "ID Number",
            "Study",
            "ReasonForExam",
            "Status",
            "RequestedAt",
            "RequestedBy",
            "SentAt",
            "SentBy",
            "ReceivedAt",
            "ReceivedBy",
            "ProcessAt",
            "ProcessBy",
            "ReportedAt",
            "ReportedBy",
            "TAT_Req_to_Sent_min",
            "TAT_Sent_to_Received_min",
            "TAT_Received_to_Process_min",
            "TAT_Process_to_Reported_min",
            "TAT_Total_min",
            "ReportText",
        ]
    )
    for r in rows:
        proc_at = r["in_process_at"] or r["done_at"]
        proc_by = r["in_process_by"] or r["done_by"]

        tat_req_sent = calc_minutes_between(r["requested_at"], r["sent_at"])
        tat_sent_rcv = calc_minutes_between(r["sent_at"], r["received_at"])
        tat_rcv_proc = calc_minutes_between(r["received_at"], proc_at)
        tat_proc_rep = calc_minutes_between(proc_at, r["reported_at"])
        tat_total = calc_minutes_between(r["requested_at"], r["reported_at"])

        writer.writerow(
            [
                r["id"],
                r["visit_id"],
                r["name"],
                r["mrn"],
                r["id_number"],
                r["test_name"],
                r["status"],
                r["requested_at"],
                r["requested_by"],
                r["sent_at"],
                r["sent_by"],
                r["received_at"],
                r["received_by"],
                proc_at,
                proc_by,
                r["reported_at"],
                r["reported_by"],
                tat_req_sent,
                tat_sent_rcv,
                tat_rcv_proc,
                tat_proc_rep,
                tat_total,
                (r["report_text"] or "").replace("\r", " ").replace("\n", " "),
            ]
        )

    return Response(
        output.getvalue().encode("utf-8-sig"),
        mimetype="text/csv",
        headers={"Content-Disposition": "attachment; filename=radiology.csv"},
    )


