@app.route("/api/doctor_picklist/add", methods=["POST"])
@login_required
@role_required("admin", "reception", "doctor")
def api_doctor_picklist_add():
    """
    Quick add/update doctor option (used on Edit Patient / Register).

    Stores values in admission_order_picklists under category 'doctor'.
    CSRF required (send X-CSRFToken header). Returns JSON.
    """
    try:
        ensure_admission_picklists_schema()
    except Exception as e:
        _log_critical_exception("Doctor picklist schema ensure failed", e)
        return jsonify({"ok": False, "error": "Doctor picklist schema unavailable"}), 500

    data = request.get_json(silent=True) or {}
    if not data:
        try:
            data = request.form.to_dict()
        except Exception:
            data = {}

    value = (data.get("value") or data.get("name") or "").strip()
    label = (data.get("label") or value).strip()

    # Accept either a pre-packed "extra" or separated fields
    extra = (data.get("extra") or "").strip()
    gd_number = (data.get("gd_number") or data.get("gd") or "").strip()
    specialty = (data.get("specialty") or "").strip()

    # If extra wasn't provided, build it from gd/specialty.
    # If extra is provided but specialty is also provided, treat extra as GD and pack.
    if not extra:
        extra = doctor_extra_pack(gd_number, specialty)
    else:
        if specialty and "|" not in extra:
            extra = doctor_extra_pack(extra, specialty)

    if not value:
        return jsonify({"ok": False, "error": "Value is required"}), 400

    actor = session.get("username") or "SYSTEM"
    ok = picklist_upsert("doctor", value, label=label, extra=extra, actor=actor)
    if not ok:
        return jsonify({"ok": False, "error": "Failed to save"}), 500
    try:
        _get_physician_directory_maps(force=True)
    except Exception:
        pass

    gd, spec = doctor_extra_parse(extra)
    resp_label = value
    if gd:
        resp_label = f"{value} ({gd})"
    if spec:
        resp_label = f"{resp_label} - {spec}"

    return jsonify(
        {
            "ok": True,
            "value": value,
            "label": resp_label,
            "gd_number": gd,
            "specialty": spec,
        }
    )




