# ============================================================
# Serial Vitals (repeated nursing vitals history)
# ============================================================
_patient_vitals_schema_ready = False


def _compose_bp_value(bp_sys=None, bp_dia=None, bp=None):
    combined = str(bp or "").strip().replace(" ", "")
    if combined:
        return combined
    sys_s = str(bp_sys or "").strip()
    dia_s = str(bp_dia or "").strip()
    if sys_s and dia_s:
        return f"{sys_s}/{dia_s}"
    return sys_s or dia_s or ""



def _split_bp_value(bp_value):
    s = str(bp_value or "").strip().replace(" ", "")
    if not s:
        return "", ""
    if "/" in s:
        left, right = s.split("/", 1)
        return left.strip(), right.strip()
    return s, ""



def _serial_vitals_flags(bp=None, hr=None, rr=None, temp=None, spo2=None):
    flags = {
        "bp": False,
        "hr": False,
        "rr": False,
        "temp": False,
        "spo2": False,
    }
    try:
        hr_v = _safe_float(hr)
    except Exception:
        hr_v = None
    try:
        rr_v = _safe_float(rr)
    except Exception:
        rr_v = None
    try:
        temp_v = _safe_float(temp)
    except Exception:
        temp_v = None
    try:
        spo2_v = _safe_float(spo2)
    except Exception:
        spo2_v = None
    try:
        bp_sys_s, bp_dia_s = _split_bp_value(bp)
        bp_sys_v = _safe_float(bp_sys_s)
        bp_dia_v = _safe_float(bp_dia_s)
    except Exception:
        bp_sys_v = None
        bp_dia_v = None

    if hr_v is not None and (hr_v < 60 or hr_v > 100):
        flags["hr"] = True
    if rr_v is not None and (rr_v < 10 or rr_v > 24):
        flags["rr"] = True
    if temp_v is not None and (temp_v < 36.0 or temp_v >= 38.0):
        flags["temp"] = True
    if spo2_v is not None and spo2_v < 92:
        flags["spo2"] = True
    if (bp_sys_v is not None and (bp_sys_v < 90 or bp_sys_v >= 140)) or (
        bp_dia_v is not None and (bp_dia_v < 60 or bp_dia_v >= 90)
    ):
        flags["bp"] = True
    return flags



def ensure_patient_vitals_schema():
    """Create the patient_vitals table for repeated vitals updates (safe/idempotent)."""
    global _patient_vitals_schema_ready
    if _patient_vitals_schema_ready:
        return
    try:
        db = get_db()
        cur = db.cursor()
        if DB_ENGINE == "postgres":
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS patient_vitals (
                    id BIGSERIAL PRIMARY KEY,
                    case_number TEXT NOT NULL,
                    bp TEXT,
                    hr TEXT,
                    rr TEXT,
                    temp TEXT,
                    spo2 TEXT,
                    recorded_by TEXT,
                    recorded_at TEXT NOT NULL
                )
                """
            )
        else:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS patient_vitals (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    case_number TEXT NOT NULL,
                    bp TEXT,
                    hr TEXT,
                    rr TEXT,
                    temp TEXT,
                    spo2 TEXT,
                    recorded_by TEXT,
                    recorded_at TEXT NOT NULL
                )
                """
            )
        try:
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_patient_vitals_case_recorded ON patient_vitals(case_number, recorded_at DESC)"
            )
        except Exception:
            pass
        for _table_name, _col_name, _col_type in (
            ("patients", "latest_bp", "TEXT"),
            ("patients", "latest_bp_systolic", "TEXT"),
            ("patients", "latest_bp_diastolic", "TEXT"),
            ("patients", "latest_hr", "TEXT"),
            ("patients", "latest_rr", "TEXT"),
            ("patients", "latest_temp", "TEXT"),
            ("patients", "latest_spo2", "TEXT"),
            ("patients", "latest_vitals_recorded_by", "TEXT"),
            ("patients", "latest_vitals_recorded_at", "TEXT"),
        ):
            try:
                ensure_column(_table_name, _col_name, _col_type)
            except Exception:
                pass
        try:
            db.commit()
        except Exception:
            pass
        _patient_vitals_schema_ready = True
    except Exception:
        _patient_vitals_schema_ready = False
        return



def _serialize_patient_vitals_row(row):
    d = _row_to_dict(row) or {}
    bp = (d.get("bp") or "").strip()
    hr = (d.get("hr") or "").strip()
    rr = (d.get("rr") or "").strip()
    temp = (d.get("temp") or "").strip()
    spo2 = (d.get("spo2") or "").strip()
    bp_sys, bp_dia = _split_bp_value(bp)
    recorded_at_raw = (d.get("recorded_at") or "").strip()
    recorded_at_disp = format_dt_local(recorded_at_raw) or recorded_at_raw
    out = {
        "id": d.get("id"),
        "case_number": (d.get("case_number") or "").strip(),
        "bp": bp,
        "bp_sys": bp_sys,
        "bp_dia": bp_dia,
        "hr": hr,
        "rr": rr,
        "temp": temp,
        "spo2": spo2,
        "recorded_by": (d.get("recorded_by") or "").strip(),
        "recorded_at": recorded_at_disp,
        "recorded_at_raw": recorded_at_raw,
    }
    out["flags"] = _serial_vitals_flags(bp=bp, hr=hr, rr=rr, temp=temp, spo2=spo2)
    return out



def get_patient_vitals_log(case_number, limit=50):
    ensure_patient_vitals_schema()
    cur = get_db().cursor()
    try:
        if limit and int(limit) > 0:
            rows = cur.execute(
                """
                SELECT id, case_number, bp, hr, rr, temp, spo2, recorded_by, recorded_at
                FROM patient_vitals
                WHERE case_number=?
                ORDER BY recorded_at DESC, id DESC
                LIMIT ?
                """,
                (case_number, int(limit)),
            ).fetchall()
        else:
            rows = cur.execute(
                """
                SELECT id, case_number, bp, hr, rr, temp, spo2, recorded_by, recorded_at
                FROM patient_vitals
                WHERE case_number=?
                ORDER BY recorded_at DESC, id DESC
                """,
                (case_number,),
            ).fetchall()
    except Exception as e:
        _log_noncritical_exception(
            f"Patient serial vitals query failed for case={case_number}", e
        )
        rows = []
    return [_serialize_patient_vitals_row(r) for r in (rows or [])]



def get_patient_vitals_latest(case_number):
    rows = get_patient_vitals_log(case_number, limit=1)
    return rows[0] if rows else None



def build_current_vitals_snapshot(visit_row, latest_vitals=None):
    visit = _row_to_dict(visit_row) or {}
    latest = latest_vitals or {}
    bp = (latest.get("bp") or "").strip() or _compose_bp_value(
        visit.get("bp_systolic"), visit.get("bp_diastolic")
    )
    hr = (latest.get("hr") or "").strip() or (visit.get("pulse_rate") or "")
    rr = (latest.get("rr") or "").strip() or (visit.get("resp_rate") or "")
    temp = (latest.get("temp") or "").strip() or (visit.get("temperature") or "")
    spo2 = (latest.get("spo2") or "").strip() or (visit.get("spo2") or "")
    bp_sys, bp_dia = _split_bp_value(bp)
    recorded_at = (latest.get("recorded_at") or "").strip()
    if not recorded_at:
        triage_ts = (visit.get("triage_time") or visit.get("created_at") or "").strip()
        recorded_at = format_dt_local(triage_ts) or triage_ts
    recorded_by = (latest.get("recorded_by") or visit.get("created_by") or "").strip()
    snap = {
        "bp": bp,
        "bp_sys": bp_sys,
        "bp_dia": bp_dia,
        "hr": str(hr or "").strip(),
        "rr": str(rr or "").strip(),
        "temp": str(temp or "").strip(),
        "spo2": str(spo2 or "").strip(),
        "recorded_at": recorded_at,
        "recorded_by": recorded_by,
        "source": "serial" if latest else "visit",
    }
    snap["flags"] = _serial_vitals_flags(
        bp=snap["bp"],
        hr=snap["hr"],
        rr=snap["rr"],
        temp=snap["temp"],
        spo2=snap["spo2"],
    )
    return snap



def insert_patient_vitals_reading(
    case_number,
    bp=None,
    hr=None,
    rr=None,
    temp=None,
    spo2=None,
    recorded_by=None,
    recorded_at=None,
    db=None,
    commit=True,
):
    ensure_patient_vitals_schema()
    bp_val = _compose_bp_value(bp=bp)
    hr_val = str(hr or "").strip()
    rr_val = str(rr or "").strip()
    temp_val = str(temp or "").strip()
    spo2_val = str(spo2 or "").strip()
    if not any([bp_val, hr_val, rr_val, temp_val, spo2_val]):
        return None
    db = db or get_db()
    recorded_at = (recorded_at or now_display_str("%Y-%m-%d %H:%M:%S") or "").strip()
    recorded_by = (recorded_by or session.get("username") or session.get("user") or "SYSTEM").strip()
    cur = db.cursor()
    cur.execute(
        """
        INSERT INTO patient_vitals (
            case_number, bp, hr, rr, temp, spo2, recorded_by, recorded_at
        )
        VALUES (?,?,?,?,?,?,?,?)
        """,
        (case_number, bp_val, hr_val, rr_val, temp_val, spo2_val, recorded_by, recorded_at),
    )
    if commit:
        db.commit()
    return {
        "case_number": case_number,
        "bp": bp_val,
        "hr": hr_val,
        "rr": rr_val,
        "temp": temp_val,
        "spo2": spo2_val,
        "recorded_by": recorded_by,
        "recorded_at": recorded_at,
    }


@app.route("/patient/<visit_id>/vitals_history")
@login_required
def vitals_history(visit_id):
    """Return JSON serial vitals log + latest reading for the patient modal/history UI."""
    ensure_patient_vitals_schema()
    log_rows = get_patient_vitals_log(visit_id, limit=100)

    latest = log_rows[0] if log_rows else None
    points = []
    if log_rows:
        for row in reversed(log_rows):
            points.append(
                {
                    "time": row.get("recorded_at_raw") or row.get("recorded_at"),
                    "pulse": row.get("hr"),
                    "resp": row.get("rr"),
                    "bp_sys": row.get("bp_sys"),
                    "bp_dia": row.get("bp_dia"),
                    "temp": row.get("temp"),
                    "spo2": row.get("spo2"),
                    "pain": "",
                }
            )
    else:
        cur = get_db().cursor()
        legacy_points = []
        try:
            rows = cur.execute(
                """
                SELECT recorded_at,
                       pulse_rate, resp_rate,
                       bp_systolic, bp_diastolic,
                       temperature, spo2, pain_score
                FROM vital_signs
                WHERE visit_id=?
                ORDER BY recorded_at ASC, id ASC
                """,
                (visit_id,),
            ).fetchall()
        except Exception as e:
            _log_noncritical_exception(
                f"Vitals history query failed for visit={visit_id}", e
            )
            rows = []

        for r in rows or []:
            legacy_points.append(
                {
                    "time": r["recorded_at"],
                    "pulse": r["pulse_rate"],
                    "resp": r["resp_rate"],
                    "bp_sys": r["bp_systolic"],
                    "bp_dia": r["bp_diastolic"],
                    "temp": r["temperature"],
                    "spo2": r["spo2"],
                    "pain": r["pain_score"],
                }
            )

        if legacy_points:
            points = legacy_points
            newest = legacy_points[-1]
            latest = {
                "bp": _compose_bp_value(newest.get("bp_sys"), newest.get("bp_dia")),
                "bp_sys": newest.get("bp_sys") or "",
                "bp_dia": newest.get("bp_dia") or "",
                "hr": newest.get("pulse") or "",
                "rr": newest.get("resp") or "",
                "temp": newest.get("temp") or "",
                "spo2": newest.get("spo2") or "",
                "recorded_by": "",
                "recorded_at": newest.get("time") or "",
                "recorded_at_raw": newest.get("time") or "",
            }
            latest["flags"] = _serial_vitals_flags(
                bp=latest.get("bp"),
                hr=latest.get("hr"),
                rr=latest.get("rr"),
                temp=latest.get("temp"),
                spo2=latest.get("spo2"),
            )
        else:
            v = cur.execute(
                """
                SELECT triage_time, created_at,
                       pulse_rate, resp_rate,
                       bp_systolic, bp_diastolic,
                       temperature, spo2, pain_score
                FROM visits
                WHERE visit_id=?
                """,
                (visit_id,),
            ).fetchone()
            if v:
                ts = v["triage_time"] or v["created_at"]
                points.append(
                    {
                        "time": ts,
                        "pulse": v["pulse_rate"],
                        "resp": v["resp_rate"],
                        "bp_sys": v["bp_systolic"],
                        "bp_dia": v["bp_diastolic"],
                        "temp": v["temperature"],
                        "spo2": v["spo2"],
                        "pain": v["pain_score"],
                    }
                )
                latest = {
                    "bp": _compose_bp_value(v["bp_systolic"], v["bp_diastolic"]),
                    "bp_sys": v["bp_systolic"] or "",
                    "bp_dia": v["bp_diastolic"] or "",
                    "hr": v["pulse_rate"] or "",
                    "rr": v["resp_rate"] or "",
                    "temp": v["temperature"] or "",
                    "spo2": v["spo2"] or "",
                    "recorded_by": "",
                    "recorded_at": format_dt_local(ts) or ts or "",
                    "recorded_at_raw": ts or "",
                }
                latest["flags"] = _serial_vitals_flags(
                    bp=latest.get("bp"),
                    hr=latest.get("hr"),
                    rr=latest.get("rr"),
                    temp=latest.get("temp"),
                    spo2=latest.get("spo2"),
                )

    return jsonify({"ok": True, "latest": latest, "log": log_rows, "points": points})


@app.route("/add_vitals", methods=["POST"])
@login_required
@role_required("nurse", "doctor", "admin")
def add_vitals():
    """Add a new repeated vitals reading and refresh the current visit snapshot."""
    ensure_patient_vitals_schema()
    payload = request.get_json(silent=True) or {}

    visit_id = (payload.get("visit_id") or request.form.get("visit_id") or "").strip()
    bp_sys = (payload.get("bp_systolic") or request.form.get("bp_systolic") or "").strip()
    bp_dia = (payload.get("bp_diastolic") or request.form.get("bp_diastolic") or "").strip()
    bp = _compose_bp_value(bp_sys=bp_sys, bp_dia=bp_dia, bp=payload.get("bp") or request.form.get("bp"))
    hr = (payload.get("hr") or payload.get("pulse_rate") or request.form.get("hr") or request.form.get("pulse_rate") or "").strip()
    rr = (payload.get("rr") or payload.get("resp_rate") or request.form.get("rr") or request.form.get("resp_rate") or "").strip()
    temp = (payload.get("temp") or payload.get("temperature") or request.form.get("temp") or request.form.get("temperature") or "").strip()
    spo2 = (payload.get("spo2") or request.form.get("spo2") or "").strip()
    is_ajax = request.headers.get("X-Requested-With") == "XMLHttpRequest" or request.is_json

    if not visit_id:
        if is_ajax:
            return jsonify({"ok": False, "error": "Missing case number / visit id."}), 400
        flash("Missing case number / visit id.", "danger")
        return redirect(url_for("ed_board"))

    if not any([bp, hr, rr, temp, spo2]):
        if is_ajax:
            return jsonify({"ok": False, "error": "Enter at least one vitals value."}), 400
        flash("Enter at least one vitals value.", "danger")
        return redirect(url_for("patient_details", visit_id=visit_id))

    db = get_db()
    cur = db.cursor()
    visit = cur.execute(
        """
        SELECT visit_id, patient_id, pulse_rate, resp_rate, bp_systolic, bp_diastolic, temperature, spo2
        FROM visits
        WHERE visit_id=?
        """,
        (visit_id,),
    ).fetchone()
    if not visit:
        if is_ajax:
            return jsonify({"ok": False, "error": "Visit not found."}), 404
        flash("Visit not found.", "danger")
        return redirect(url_for("ed_board"))

    now_ts = now_display_str("%Y-%m-%d %H:%M:%S") or datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    actor = (session.get("username") or session.get("user") or "SYSTEM").strip()
    bp_sys_eff = bp_sys or (visit["bp_systolic"] or "")
    bp_dia_eff = bp_dia or (visit["bp_diastolic"] or "")
    hr_eff = hr or (visit["pulse_rate"] or "")
    rr_eff = rr or (visit["resp_rate"] or "")
    temp_eff = temp or (visit["temperature"] or "")
    spo2_eff = spo2 or (visit["spo2"] or "")

    try:
        insert_patient_vitals_reading(
            visit_id,
            bp=bp,
            hr=hr or hr_eff,
            rr=rr or rr_eff,
            temp=temp or temp_eff,
            spo2=spo2 or spo2_eff,
            recorded_by=actor,
            recorded_at=now_ts,
            db=db,
            commit=False,
        )
        cur.execute(
            """
            UPDATE visits
               SET pulse_rate=?,
                   resp_rate=?,
                   bp_systolic=?,
                   bp_diastolic=?,
                   temperature=?,
                   spo2=?
             WHERE visit_id=?
            """,
            (hr_eff, rr_eff, bp_sys_eff, bp_dia_eff, temp_eff, spo2_eff, visit_id),
        )
        if visit["patient_id"] not in (None, ""):
            cur.execute(
                """
                UPDATE patients
                   SET latest_bp=?,
                       latest_bp_systolic=?,
                       latest_bp_diastolic=?,
                       latest_hr=?,
                       latest_rr=?,
                       latest_temp=?,
                       latest_spo2=?,
                       latest_vitals_recorded_by=?,
                       latest_vitals_recorded_at=?
                 WHERE id=?
                """,
                (
                    _compose_bp_value(bp_sys_eff, bp_dia_eff),
                    bp_sys_eff,
                    bp_dia_eff,
                    hr_eff,
                    rr_eff,
                    temp_eff,
                    spo2_eff,
                    actor,
                    now_ts,
                    visit["patient_id"],
                ),
            )
        db.commit()
        try:
            log_action(
                "ADD_SERIAL_VITALS",
                visit_id=visit_id,
                details=f"BP={_compose_bp_value(bp_sys_eff, bp_dia_eff)}|HR={hr_eff}|RR={rr_eff}|TEMP={temp_eff}|SPO2={spo2_eff}",
            )
        except Exception:
            pass
    except Exception as e:
        try:
            db.rollback()
        except Exception:
            pass
        if is_ajax:
            return jsonify({"ok": False, "error": str(e) or "Failed to save vitals."}), 500
        flash(f"Failed to save vitals: {e}", "danger")
        return redirect(url_for("patient_details", visit_id=visit_id))

    latest = get_patient_vitals_latest(visit_id)
    log_rows = get_patient_vitals_log(visit_id, limit=100)
    if is_ajax:
        return jsonify({"ok": True, "latest": latest, "log": log_rows})
    flash("Vitals updated successfully.", "success")
    return redirect(url_for("patient_details", visit_id=visit_id))


@app.route("/visit/<visit_id>/location_bed", methods=["POST"])
@login_required
@role_required("reception", "nurse", "doctor", "admin")
def update_location_bed(visit_id):
    """
    Simple helper to update ED Location / Bed / Bed Status from patient_details or ED Board.
    """
    db = get_db()
    cur = db.cursor()

    location = (request.form.get("location") or "").strip()
    bed_no = (request.form.get("bed_no") or "").strip()
    bed_status = (request.form.get("bed_status") or "").strip().upper()
    if bed_status not in ("EMPTY", "OCCUPIED", "DIRTY"):
        bed_status = ""

    cur.execute(
        """
        UPDATE visits
           SET location=?,
               bed_no=?,
               bed_status=?
         WHERE visit_id=?
        """,
        (location, bed_no, bed_status, visit_id),
    )
    db.commit()

    log_action(
        "UPDATE_LOC_BED", visit_id=visit_id, details=f"{location}|{bed_no}|{bed_status}"
    )
    flash("Location / Bed updated.", "success")
    return redirect(url_for("patient_details", visit_id=visit_id))


@app.route("/clinical_orders/<visit_id>/source_location", methods=["POST"])
@login_required
@role_required("nurse", "doctor", "admin")
def update_clinical_order_source_location(visit_id):
    """Update the current care area/location from the Clinical Orders workspace."""
    try:
        _ensure_order_reason_schema_columns(strict=False)
    except Exception:
        pass
    db = get_db()
    cur = db.cursor()
    allowed = {"ED", "ICU", "IP", "OR", "DR", "NICU", "CATH LAB", "RECOVERY", "ISOLATION", "OTHER"}
    care_area = (request.form.get("care_area") or "").strip().upper()
    if care_area not in allowed:
        care_area = "OTHER" if care_area else "ED"
    location = clean_text((request.form.get("location") or "").strip())[:80]
    bed_no = clean_text((request.form.get("bed_no") or "").strip())[:80]
    bed_status = (request.form.get("bed_status") or "").strip().upper()
    if bed_status not in ("EMPTY", "OCCUPIED", "DIRTY"):
        bed_status = ""
    try:
        cur.execute(
            """
            UPDATE visits
               SET care_area=?,
                   location=?,
                   bed_no=?,
                   bed_status=?
             WHERE visit_id=?
            """,
            (care_area, location, bed_no, bed_status, visit_id),
        )
        db.commit()
        log_action("UPDATE_CO_SOURCE_LOCATION", visit_id=visit_id, details=f"{care_area}|{location}|{bed_no}|{bed_status}")
        flash("Care Area / Order Source updated.", "success")
    except Exception as exc:
        _rollback_with_logging(db, f"Care Area update failed for visit={visit_id}")
        _log_critical_exception(f"Care Area update failed for visit={visit_id}", exc)
        flash("Failed to update Care Area / Order Source.", "danger")
    return redirect(url_for("clinical_orders_page", visit_id=visit_id))


@app.route("/patient/<visit_id>/edit", methods=["GET", "POST"])
@login_required
@role_required("reception", "mrd", "admin")
def edit_patient(visit_id):
    # Ensure schemas for new workflow
    try:
        ensure_clinic_schema()
    except Exception as e:
        _log_noncritical_exception(
            f"Clinic schema ensure failed before edit_patient visit={visit_id}", e
        )
    try:
        ensure_patients_extra_schema()
    except Exception as e:
        _log_noncritical_exception(
            f"Patients extra schema ensure failed before edit_patient visit={visit_id}",
            e,
        )
    try:
        ensure_visit_financial_schema()
    except Exception as e:
        _log_noncritical_exception(
            f"Visit financial schema ensure failed before edit_patient visit={visit_id}",
            e,
        )
    try:
        ensure_contract_schemes_schema()
    except Exception as e:
        _log_noncritical_exception(
            f"Contract schemes schema ensure failed before edit_patient visit={visit_id}",
            e,
        )

    db = get_db()
    cur = db.cursor()

    # Dropdown options (Master Data)
    visit_type_options = get_system_picklist_options("visit_type")
    service_category_options = get_system_picklist_options("service_category")
    insurance_provider_options = get_system_picklist_options("insurance_provider")
    insurance_plan_options = get_system_picklist_options("insurance_plan")
    contract_schemes = get_contract_schemes(active_only=True)

    # Physicians list (users + picklist)
    doctor_options = []
    try:
        seen = set()
        try:
            rows = cur.execute(
                "SELECT username, gd_number FROM users WHERE is_active=1 AND role IN ('doctor','admin') ORDER BY username"
            ).fetchall()
        except Exception:
            rows = []
        for r in rows:
            try:
                username = (r["username"] or "").strip()
                gd = (r["gd_number"] or "").strip()
            except Exception:
                username = (r[0] or "").strip()
                gd = (r[1] or "").strip() if len(r) > 1 else ""
            if not username:
                continue
            label = f"{username} ({gd})" if gd else username
            key = username.lower()
            if key in seen:
                continue
            seen.add(key)
            doctor_options.append({"value": username, "label": label})

        try:
            for d in picklist_get_doctors():
                username = (d.get("username") or "").strip()
                gd = (d.get("gd_number") or "").strip()
                if not username:
                    continue
                key = username.lower()
                if key in seen:
                    continue
                seen.add(key)
                spec = (d.get("specialty") or "").strip()

                label = f"{username} ({gd})" if gd else username
                if spec:
                    label = f"{label} - {spec}"
                doctor_options.append({"value": username, "label": label})
        except Exception as e:
            _log_noncritical_exception(
                f"Doctor picklist merge failed in edit_patient visit={visit_id}", e
            )

        doctor_options.sort(key=lambda x: (x.get("value") or "").lower())
    except Exception:
        doctor_options = []

    # Load current record
    rec = cur.execute(
        """
        SELECT
            v.visit_id,
            v.payment_details,
            v.comment,
            v.queue_no,
            v.status,
            v.clinic,
            v.ward,
            v.bed_no,
            v.admission_type,
            v.approval_no,
            v.visit_type,
            v.service_category,
            v.assigned_doctor,
            v.insurance_json,
            v.financial_json,
            v.contract_scheme_id,
            p.id AS patient_id,
            p.name,
            p.id_number,
            p.phone,
            p.insurance,
            p.insurance_no,
            p.email,
            p.nok_name,
            p.nok_relation,
            p.nok_phone,
            p.dob,
            p.sex,
            p.nationality
        FROM visits v
        JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
        """,
        (visit_id,),
    ).fetchone()

    if not rec:
        flash("Record not found.", "danger")
        return redirect(url_for("ed_board"))

    # Parse JSON blobs
    ins = {}
    fin = {}
    try:
        ins_raw = (
            rec.get("insurance_json") if hasattr(rec, "get") else rec["insurance_json"]
        )
    except Exception:
        try:
            ins_raw = rec[13]
        except Exception:
            ins_raw = ""
    try:
        fin_raw = (
            rec.get("financial_json") if hasattr(rec, "get") else rec["financial_json"]
        )
    except Exception:
        try:
            fin_raw = rec[14]
        except Exception:
            fin_raw = ""

    try:
        ins = json.loads(ins_raw or "{}")
        if not isinstance(ins, dict):
            ins = {}
    except Exception:
        ins = {}
    try:
        fin = json.loads(fin_raw or "{}")
        if not isinstance(fin, dict):
            fin = {}
    except Exception:
        fin = {}

    if request.method == "POST":

        def _get(k, default=""):
            v = request.form.get(k, default)
            return (v or "").strip()

        # Demographics
        name = _get("name")
        id_number = _get("id_number")
        phone = _get("phone")
        email = _get("email")
        raw_dob = _get("dob")
        dob_norm = normalize_dob_input(raw_dob)
        dob_invalid = bool(raw_dob and not dob_norm)
        dob = dob_norm or raw_dob
        sex = _get("sex")
        nationality = _get("nationality")
        nok_name = _get("nok_name")
        nok_relation = _get("nok_relation")
        nok_phone = _get("nok_phone")

        # Encounter
        clinic = (
            _get("clinic")
            or (rec.get("clinic") if hasattr(rec, "get") else rec["clinic"])
            or "ED"
        ).upper()
        visit_type = (
            _get("visit_type")
            or (rec.get("visit_type") if hasattr(rec, "get") else rec["visit_type"])
            or "NEW"
        ).upper()
        service_category = _get("service_category")
        assigned_doctor = _get("assigned_doctor")
        queue_no = _get("queue_no", rec["queue_no"])
        status = (_get("status", rec["status"]) or "").upper()
        comment = _get("comment")

        ward = _get("ward")
        bed_no = _get("bed_no")
        admission_type = _get("admission_type")
        approval_no = _get("approval_no")

        if clinic != "IPADM":
            ward = ""
            bed_no = ""
            admission_type = ""
            approval_no = ""

        # Insurance / policy
        insurance_provider = _get("insurance")
        insurance_no = _get("insurance_no")
        ins_plan = _get("ins_plan")
        ins_card_no = _get("ins_card_no") or insurance_no
        dha_member_id = _get("dha_member_id")
        policy_no = _get("policy_no")
        policy_name = _get("policy_name")
        valid_from = _get("valid_from")
        valid_to = _get("valid_to")
        eligibility_status = _get("eligibility_status")
        eligibility_notes = _get("eligibility_notes")

        # Financial / payment
        payment_method = _get("payment_method")
        receipt_no = _get("receipt_no")
        copay_amount = _get("copay_amount")
        payment_notes = _get("payment_notes")
        contract_scheme_id = _get("contract_scheme_id")

        consult_deduct_percent = _get("consult_deduct_percent")
        consult_deduct_amount = _get("consult_deduct_amount")
        bucket = {}
        for key in [
            "lab",
            "radiology",
            "investigation",
            "inpatient",
            "pharmacy",
            "dental",
        ]:
            bucket[f"{key}_percent"] = _get(f"{key}_percent")
            bucket[f"{key}_amount"] = _get(f"{key}_amount")

        # Validation
        if dob_invalid:
            flash("DOB format is invalid. Use YYYY-MM-DD or DD/MM/YYYY.", "danger")
            return redirect(request.url)
        if not dob:
            flash("DOB is required.", "danger")
            return redirect(request.url)

        if not name:
            flash("Patient name is required.", "danger")
            initial_visit_lock_others = prepare_visit_lock_context(
                visit_id, request.path
            )
            return render_template(
                "edit_patient.html",
                rec=rec,
                r=rec,
                visit=rec,
                visit_id=visit_id,
                initial_visit_lock_others=initial_visit_lock_others,
                clinics=get_clinics_for_ui(),
                visit_type_options=visit_type_options,
                service_category_options=service_category_options,
                doctor_options=doctor_options,
                insurance_provider_options=insurance_provider_options,
                insurance_plan_options=insurance_plan_options,
                contract_schemes=contract_schemes,
                ins=ins,
                fin=fin,
            )

        # Update patient
        try:
            cur.execute(
                """
                UPDATE patients SET
                    name=?,
                    id_number=?,
                    phone=?,
                    insurance=?,
                    insurance_no=?,
                    email=?,
                    nok_name=?,
                    nok_relation=?,
                    nok_phone=?,
                    dob=?,
                    sex=?,
                    nationality=?
                WHERE id=?
                """,
                (
                    name,
                    id_number,
                    phone,
                    insurance_provider,
                    insurance_no,
                    email,
                    nok_name,
                    nok_relation,
                    nok_phone,
                    dob,
                    sex,
                    nationality,
                    rec["patient_id"],
                ),
            )
        except Exception as e:
            _log_critical_exception(
                f"Patient demographics update failed in edit_patient visit={visit_id}",
                e,
            )
            flash("Failed to update patient demographics. No partial save was applied.", "danger")
            return redirect(request.url)

        # Rebuild JSON
        insurance_data = {
            "provider": insurance_provider,
            "member_no": insurance_no,
            "plan": ins_plan,
            "card_no": ins_card_no,
            "dha_member_id": dha_member_id,
            "policy_no": policy_no,
            "policy_name": policy_name,
            "valid_from": valid_from,
            "valid_to": valid_to,
            "eligibility_status": eligibility_status,
            "eligibility_notes": eligibility_notes,
        }

        contract_scheme_snapshot = {
            "consult_deduct_percent": _safe_float(consult_deduct_percent),
            "consult_deduct_amount": _safe_float(consult_deduct_amount),
        }
        for key in [
            "lab",
            "radiology",
            "investigation",
            "inpatient",
            "pharmacy",
            "dental",
        ]:
            contract_scheme_snapshot[f"{key}_percent"] = _safe_float(
                bucket.get(f"{key}_percent")
            )
            contract_scheme_snapshot[f"{key}_amount"] = _safe_float(
                bucket.get(f"{key}_amount")
            )

        financial_data = {
            "payment_method": payment_method,
            "receipt_no": receipt_no,
            "copay_amount": _safe_float(copay_amount),
            "notes": payment_notes,
            "contract_scheme": contract_scheme_snapshot,
        }

        insurance_json = json.dumps(insurance_data, ensure_ascii=False)
        financial_json = json.dumps(financial_data, ensure_ascii=False)

        # Summary field used by boards
        payment_details = (_get("payment_details") or "").strip()
        if not payment_details:
            payment_details = build_payment_summary(insurance_data, financial_data)

        # Parse scheme id
        cs_id = None
        try:
            cs_id = int(contract_scheme_id or 0)
        except Exception:
            cs_id = None
        if not cs_id:
            cs_id = None

        # Update visit
        cur.execute(
            """
            UPDATE visits SET
                payment_details=?,
                comment=?,
                queue_no=?,
                status=?,
                clinic=?,
                ward=?,
                bed_no=?,
                admission_type=?,
                approval_no=?,
                visit_type=?,
                service_category=?,
                assigned_doctor=?,
                insurance_json=?,
                financial_json=?,
                contract_scheme_id=?
            WHERE visit_id=?
            """,
            (
                payment_details,
                comment,
                queue_no,
                status,
                clinic,
                ward,
                bed_no,
                admission_type,
                approval_no,
                visit_type,
                service_category,
                assigned_doctor,
                insurance_json,
                financial_json,
                cs_id,
                visit_id,
            ),
        )

        db.commit()

        try:
            log_action(
                "EDIT_PATIENT",
                visit_id=visit_id,
                details=f"Clinic={clinic} Status={status}",
            )
        except Exception as e:
            _log_noncritical_exception(
                f"Edit patient audit log failed for visit={visit_id}", e
            )

        flash("Patient record updated.", "success")
        return redirect(url_for("patient_details", visit_id=visit_id))

    initial_visit_lock_others = prepare_visit_lock_context(visit_id, request.path)
    return render_template(
        "edit_patient.html",
        rec=rec,
        r=rec,
        visit=rec,
        visit_id=visit_id,
        initial_visit_lock_others=initial_visit_lock_others,
        clinics=get_clinics_for_ui(),
        visit_type_options=visit_type_options,
        service_category_options=service_category_options,
        doctor_options=doctor_options,
        insurance_provider_options=insurance_provider_options,
        insurance_plan_options=insurance_plan_options,
        contract_schemes=contract_schemes,
        ins=ins,
        fin=fin,
    )


@app.route("/patient/<visit_id>/upload_id", methods=["POST"])
@login_required
@role_required("reception", "nurse", "mrd", "admin")
def upload_id(visit_id):
    if "file" not in request.files:
        flash("No file selected.", "danger")
        return redirect(url_for("patient_details", visit_id=visit_id))

    file = request.files["file"]
    if file.filename == "":
        flash("Please choose a file.", "danger")
        return redirect(url_for("patient_details", visit_id=visit_id))

    if not allowed_file(file.filename):
        flash("Invalid file type.", "danger")
        return redirect(url_for("patient_details", visit_id=visit_id))

    safe_name = secure_filename(file.filename)
    detected_kind = _attachment_kind_from_filename(safe_name)
    if detected_kind == "elig":
        filename = f"{visit_id}_{int(datetime.now().timestamp())}_ELIG_{safe_name}"
    elif detected_kind == "id":
        filename = f"{visit_id}_{int(datetime.now().timestamp())}_ID_{safe_name}"
    else:
        filename = f"{visit_id}_{int(datetime.now().timestamp())}_{safe_name}"
    save_err = _save_attachment_with_optional_async(
        visit_id,
        file,
        filename,
        session.get("username"),
        context="upload_id",
    )
    if save_err:
        flash(save_err, "danger")
        return redirect(url_for("patient_details", visit_id=visit_id))
    try:
        pass  # _reset_board_runtime_caches()
    except Exception as e:
        _log_noncritical_exception("Board cache reset failed after ID upload", e)
    log_action("UPLOAD_ATTACHMENT", visit_id=visit_id, details=filename)
    flash("Attachment uploaded successfully.", "success")
    return redirect(url_for("patient_details", visit_id=visit_id))


@app.route("/attachment/<int:att_id>/delete", methods=["POST"])
@login_required
@role_required("reception", "mrd", "admin")
def delete_attachment(att_id):
    db = get_db()
    cur = db.cursor()
    a = cur.execute("SELECT * FROM attachments WHERE id=?", (att_id,)).fetchone()
    if not a:
        flash("Attachment not found.", "danger")
        return redirect(url_for("ed_board"))

    filename = a["filename"] or ""
    # Reception cannot delete LAB / RAD result files
    if session.get("role") == "reception" and (
        "_LAB_" in filename or "_RAD_" in filename
    ):
        flash("Reception cannot delete lab or radiology results.", "danger")
        return redirect(url_for("patient_details", visit_id=a["visit_id"]))

    # MRD also cannot delete LAB / RAD result files (admin only)
    if (session.get("role") or "").lower() == "mrd" and (
        "_LAB_" in filename or "_RAD_" in filename
    ):
        flash("Only admin can delete lab/radiology result files.", "danger")
        return redirect(url_for("patient_details", visit_id=a["visit_id"]))
    try:
        os.remove(os.path.join(UPLOAD_FOLDER, filename))
    except Exception as e:
        _log_noncritical_exception(
            f"Attachment file remove failed for visit={a['visit_id']} filename={filename}",
            e,
        )

    db.execute("DELETE FROM attachments WHERE id=?", (att_id,))
    db.commit()
    try:
        pass  # _reset_board_runtime_caches()
    except Exception as e:
        _log_noncritical_exception("Board cache reset failed after attachment delete", e)
    log_action("DELETE_ATTACHMENT", visit_id=a["visit_id"], details=filename)
    flash("Attachment deleted.", "success")
    return redirect(url_for("patient_details", visit_id=a["visit_id"]))


@app.route("/uploads/<path:filename>")
@login_required
def uploaded_file(filename):
    """Serve an uploaded file (attachments / lab / radiology uploads).

    Uses resolve_upload_path() to tolerate older deployments where the app was started
    from a different working directory (uploads folder moved).
    """
    safe_name = os.path.basename(str(filename or ""))
    if not safe_name:
        abort(404)

    # Reception: only allow ID/Eligibility attachments (block LAB/RAD generated files)
    if session.get("role") == "reception":
        if "_LAB_" in safe_name or "_RAD_" in safe_name:
            abort(403)

    full = resolve_upload_path(safe_name)
    if not full:
        # Fallback: the board may still point to a stale attachment row while a
        # newer valid eligibility/ID document exists for the same visit.
        row = None
        try:
            cur = get_db().cursor()
            row = cur.execute(
                "SELECT visit_id FROM attachments WHERE filename=?",
                (safe_name,),
            ).fetchone()
        except Exception:
            pass
        try:
            visit_id = _fetch_one_val(row, "visit_id", 1) if row else None
        except Exception:
            visit_id = None

        fallback = None
        try:
            wanted_kind = _attachment_kind_from_filename(safe_name)
        except Exception:
            wanted_kind = "generic"

        if visit_id:
            try:
                siblings = cur.execute(
                    """
                    SELECT id, filename
                    FROM attachments
                    WHERE visit_id=?
                    ORDER BY COALESCE(uploaded_at,'') DESC, id DESC
                    """,
                    (visit_id,),
                ).fetchall()
            except Exception:
                siblings = []

            fallback_kind_order = []
            if wanted_kind == "elig":
                fallback_kind_order = ["elig", "generic", "id"]
            elif wanted_kind == "id":
                fallback_kind_order = ["id", "generic", "elig"]
            else:
                fallback_kind_order = ["generic", "elig", "id"]

            for desired_kind in fallback_kind_order:
                for sib in siblings or []:
                    try:
                        sib_filename = _fetch_one_val(sib, "filename", 1)
                    except Exception:
                        sib_filename = None
                    if not sib_filename or not attachment_file_exists(sib_filename):
                        continue
                    if _attachment_kind_from_filename(sib_filename) != desired_kind:
                        continue
                    fallback = resolve_upload_path(sib_filename)
                    if fallback:
                        safe_name = os.path.basename(str(sib_filename))
                        full = fallback
                        break
                if full:
                    break

    if not full:
        abort(404)

    try:
        if _attachment_pdf_sticker_target_v20260525(safe_name, context="uploaded_file_view"):
            sticker_visit_id = None
            try:
                cur = get_db().cursor()
                row = cur.execute("SELECT visit_id FROM attachments WHERE filename=? LIMIT 1", (safe_name,)).fetchone()
                if row:
                    sticker_visit_id = _attachment_sticker_row_get_v20260525(row, "visit_id", "")
            except Exception:
                sticker_visit_id = None
            if sticker_visit_id:
                try:
                    with open(full, "rb") as fh:
                        original_payload = fh.read()
                    sticker_payload = _prepare_attachment_bytes_for_patient_sticker_v20260525(
                        sticker_visit_id,
                        safe_name,
                        original_payload,
                        context="uploaded_file_view",
                    )
                    if sticker_payload and sticker_payload != original_payload:
                        return send_file(
                            io.BytesIO(sticker_payload),
                            mimetype="application/pdf",
                            as_attachment=False,
                            download_name=safe_name,
                        )
                except Exception as sticker_exc:
                    _log_noncritical_exception(f"Attachment view-time sticker failed filename={safe_name}", sticker_exc)
        return send_file(full, as_attachment=False, download_name=safe_name)
    except TypeError:
        # Older Flask fallback
        return send_file(full, as_attachment=False)


def _attachment_kind_from_filename(filename):
    """Classify attachment filename for board/document shortcuts.

    Returns one of: 'lab', 'rad', 'elig', 'id', 'generic', 'unknown'
    """
    fn = str(filename or "").strip()
    if not fn:
        return "unknown"
    up = fn.upper()
    if "_LAB_" in up:
        return "lab"
    if "_RAD_" in up:
        return "rad"

    # Be tolerant with real-world naming and common spelling mistakes because
    # older uploads / manually named files are not always normalized.
    elig_patterns = [
        r"(?:^|[_\s-])(ELIG|ELIGIBILITY|ELIGIBLITY|ELIGIBILTY|ELIGABLITY)(?:[_\s-]|\.|$)",
        r"(?:^|[_\s-])(INS|INSURANCE|INSCARD|INS_CARD|MEDICALCARD|MEDICAL_CARD)(?:[_\s-]|\.|$)",
        r"(?:^|[_\s-])(CARDCOPY|CARD_COPY|TPA)(?:[_\s-]|\.|$)",
    ]
    for pat in elig_patterns:
        if re.search(pat, up, re.IGNORECASE):
            return "elig"

    if re.search(
        r"(?:^|[_\s-])(ID|EMIRATESID|EMIRATES_ID|NATIONALID|NATIONAL_ID|PASSPORT)(?:[_\s-]|\.|$)",
        up,
        re.IGNORECASE,
    ):
        return "id"
    return "generic"


def _resolve_board_attachment_pair(cur, visit_id, preset=None):
    """Resolve best ID / eligibility attachments for ED & Clinic boards.

    Why this exists:
    - Some legacy/generic uploads are saved without a strict _ELIG_ or _ID_ token.
    - Boards should still expose the uploaded files sensibly.
    - We also want existing records to work without forcing re-upload.

    Heuristics:
    - Prefer explicitly tagged ID / ELIG files when present.
    - If eligibility is missing, fall back to another non-result attachment.
    - If only one generic non-result attachment exists, expose it on the
      eligibility icon so the user can still open the uploaded insurance file.
    """
    out = {
        "id_attachment_id": None,
        "id_attachment": None,
        "elig_attachment_id": None,
        "elig_attachment": None,
    }
    try:
        if isinstance(preset, dict):
            for k in out.keys():
                if preset.get(k):
                    out[k] = preset.get(k)
    except Exception as e:
        _log_noncritical_exception(
            f"Attachment preset parse failed for visit={visit_id}", e
        )

    if not visit_id:
        return out

    try:
        rows = cur.execute(
            """
            SELECT id, filename, uploaded_at
            FROM attachments
            WHERE visit_id=?
              AND filename NOT LIKE '%_LAB_%'
              AND filename NOT LIKE '%_RAD_%'
            ORDER BY COALESCE(uploaded_at,'') DESC, id DESC
            """,
            (visit_id,),
        ).fetchall()
    except Exception:
        return out

    docs = []
    for r in rows or []:
        try:
            rid = r["id"]
            fn = r["filename"]
        except Exception:
            try:
                rid = r[0]
                fn = r[1]
            except Exception:
                continue
        if not fn:
            continue
        if not attachment_file_exists(fn):
            # Ignore stale DB rows whose files no longer exist on disk.
            continue
        kind = _attachment_kind_from_filename(fn)
        if kind in ("lab", "rad", "unknown"):
            continue
        docs.append({"id": rid, "filename": fn, "kind": kind})

    if not docs:
        return out

    explicit_id = [d for d in docs if d["kind"] == "id"]
    explicit_elig = [d for d in docs if d["kind"] == "elig"]
    generic = [d for d in docs if d["kind"] == "generic"]

    id_row = explicit_id[0] if explicit_id else None
    elig_row = explicit_elig[0] if explicit_elig else None

    if id_row is None:
        # When there are two generic docs, the older one is usually the ID and the
        # newer one is usually the eligibility/insurance upload.
        if len(generic) >= 2:
            id_row = generic[-1]
        elif len(generic) == 1 and not elig_row:
            id_row = generic[0]
        elif not generic and docs:
            # Last-resort: pick first non-elig explicit doc
            for d in docs:
                if d["kind"] != "elig":
                    id_row = d
                    break

    if elig_row is None:
        for d in docs:
            if id_row and d["id"] == id_row["id"]:
                continue
            # Prefer any non-ID remaining doc as eligibility fallback.
            if d["kind"] in ("elig", "generic"):
                elig_row = d
                break

        # If there is only one generic document, expose it on eligibility too.
        if elig_row is None and len(docs) == 1 and docs[0]["kind"] == "generic":
            elig_row = docs[0]

    # Never override a confirmed explicit ELIG / ID selection with None.
    if id_row:
        out["id_attachment_id"] = id_row["id"]
        out["id_attachment"] = id_row["filename"]
    if elig_row:
        out["elig_attachment_id"] = elig_row["id"]
        out["elig_attachment"] = elig_row["filename"]

    return out


def _choose_board_attachment_pair_from_docs(docs):
    out = {
        "id_attachment_id": None,
        "id_attachment": None,
        "elig_attachment_id": None,
        "elig_attachment": None,
    }
    explicit_id = [d for d in docs if d.get("kind") == "id"]
    explicit_elig = [d for d in docs if d.get("kind") == "elig"]
    generic = [d for d in docs if d.get("kind") == "generic"]

    id_row = explicit_id[0] if explicit_id else None
    elig_row = explicit_elig[0] if explicit_elig else None

    if id_row is None:
        if len(generic) >= 2:
            id_row = generic[-1]
        elif len(generic) == 1 and not elig_row:
            id_row = generic[0]
        elif not generic and docs:
            for d in docs:
                if d.get("kind") != "elig":
                    id_row = d
                    break

    if elig_row is None:
        for d in docs:
            if id_row and d.get("id") == id_row.get("id"):
                continue
            if d.get("kind") in ("elig", "generic"):
                elig_row = d
                break
        if elig_row is None and len(docs) == 1 and docs[0].get("kind") == "generic":
            elig_row = docs[0]

    if id_row:
        out["id_attachment_id"] = id_row.get("id")
        out["id_attachment"] = id_row.get("filename")
    if elig_row:
        out["elig_attachment_id"] = elig_row.get("id")
        out["elig_attachment"] = elig_row.get("filename")
    return out



def _prefetch_board_attachment_pairs(cur, visit_ids):
    pairs = {}
    ids = [str(v).strip() for v in (visit_ids or []) if str(v).strip()]
    if not ids:
        return pairs
    uniq_ids = sorted(set(ids))
    try:
        placeholders = ",".join(["?"] * len(uniq_ids))
        rows = cur.execute(
            f"""
            SELECT visit_id, id, filename, uploaded_at
            FROM attachments
            WHERE visit_id IN ({placeholders})
              AND filename NOT LIKE '%_LAB_%'
              AND filename NOT LIKE '%_RAD_%'
            ORDER BY visit_id ASC, COALESCE(uploaded_at,'') DESC, id DESC
            """,
            uniq_ids,
        ).fetchall()
    except Exception:
        return pairs

    grouped = {}
    for r in rows or []:
        try:
            visit_id = r["visit_id"]
            rid = r["id"]
            fn = r["filename"]
        except Exception:
            try:
                visit_id, rid, fn = r[0], r[1], r[2]
            except Exception:
                continue
        visit_id = (visit_id or "").strip()
        if not visit_id or not fn:
            continue
        if not attachment_file_exists(fn):
            continue
        kind = _attachment_kind_from_filename(fn)
        if kind in ("lab", "rad", "unknown"):
            continue
        grouped.setdefault(visit_id, []).append({"id": rid, "filename": fn, "kind": kind})

    for visit_id, docs in grouped.items():
        try:
            pairs[visit_id] = _choose_board_attachment_pair_from_docs(docs)
        except Exception:
            continue
    return pairs



def _prefetch_assigned_doctor_display_map(cur, assigned_values):
    out = {}
    vals = [str(v).strip() for v in (assigned_values or []) if str(v).strip()]
    if not vals:
        return out
    uniq = sorted(set(vals))
    try:
        placeholders = ",".join(["?"] * len(uniq))
        rows = cur.execute(
            f"SELECT username, role, gd_number FROM users WHERE is_active=1 AND username IN ({placeholders})",
            uniq,
        ).fetchall()
    except Exception:
        rows = []

    users = {}
    for r in rows or []:
        try:
            uname = (r["username"] or "").strip()
            role = normalize_role_key(r["role"])
            gd = (r["gd_number"] or "").strip()
        except Exception:
            try:
                uname = (r[0] or "").strip()
                role = normalize_role_key(r[1])
                gd = (r[2] or "").strip()
            except Exception:
                continue
        if uname:
            users[uname] = {"role": role, "gd": gd}

    by_gd, _by_name = _get_physician_directory_maps(cur)

    for raw in uniq:
        u = users.get(raw)
        if not u:
            out[raw] = raw
            continue
        if u.get("role") in ("doctor", "admin"):
            out[raw] = (by_gd.get(u.get("gd") or "") or raw).strip()
        else:
            out[raw] = raw
    return out


@app.route("/attachment/<int:att_id>")
@login_required
def open_attachment(att_id):
    """Open an attachment by DB id (more robust than filename URLs)."""
    cur = get_db().cursor()
    row = cur.execute(
        "SELECT id, visit_id, filename FROM attachments WHERE id=?",
        (att_id,),
    ).fetchone()
    if not row:
        abort(404)

    filename = _fetch_one_val(row, "filename", 2)
    if not filename:
        abort(404)

    safe_name = os.path.basename(str(filename))

    # Reception: only allow ID/Eligibility attachments (block LAB/RAD generated files)
    if session.get("role") == "reception":
        if "_LAB_" in safe_name or "_RAD_" in safe_name:
            abort(403)

    full = resolve_upload_path(safe_name)
    if not full:
        abort(404)

    # Build a patient-based download filename (keeps Arabic names via filename*)
    download_name = safe_name
    try:
        _vid = _fetch_one_val(row, "visit_id", 1)
    except Exception:
        _vid = None

    if _vid:
        try:
            vrow = cur.execute(
                """
                SELECT p.name, p.id_number, p.insurance, p.insurance_no
                FROM visits v
                JOIN patients p ON p.id=v.patient_id
                WHERE v.visit_id=?
                """,
                (_vid,),
            ).fetchone()
        except Exception:
            vrow = None

        try:
            base0, ext0 = os.path.splitext(safe_name)
            ext0 = (ext0 or "").lstrip(".") or None
            extra0 = _clean_filename_part(base0, max_len=50)
            if vrow:
                download_name = _patient_download_filename(
                    vrow,
                    doc_tag=f"Attachment-{att_id}",
                    ext=ext0,
                    visit_id=_vid,
                    extra=extra0,
                )
        except Exception as e:
            _log_noncritical_exception(
                f"Attachment download filename build failed for attachment={att_id}",
                e,
            )

    # Allow forcing download via ?download=1 (or ?dl=1)
    as_attach = False
    try:
        qd = request.args.get("download")
        if qd is None:
            qd = request.args.get("dl")
        if qd is not None:
            s = str(qd).strip().lower()
            if s not in ("0", "false", "no", "n", "off"):
                as_attach = True
    except Exception as e:
        _log_noncritical_exception(
            f"Attachment download flag parse failed for attachment={att_id}", e
        )

    try:
        return send_file(full, as_attachment=as_attach, download_name=download_name)
    except TypeError:
        # Older Flask fallback
        return send_file(full, as_attachment=as_attach)


