# ------------------------------------------------------------
# Patient Current Location / Movement Timeline
# ------------------------------------------------------------
CARE_AREA_CHOICES = ("ED", "ICU", "IP", "OR", "DR", "NICU", "CATH LAB", "RECOVERY", "ISOLATION", "OTHER")


def _movement_clean(value, max_len=120):
    try:
        value = clean_text(str(value or "").strip())
    except Exception:
        value = str(value or "").strip()
    if max_len and len(value) > max_len:
        value = value[:max_len].rstrip()
    return value


def _normalize_care_area(value, default="ED"):
    area = _movement_clean(value, 40).upper()
    if area in CARE_AREA_CHOICES:
        return area
    if area in ("WARD", "INPATIENT", "IPD"):
        return "IP"
    if area in ("CATH", "CATHLAB"):
        return "CATH LAB"
    if not area:
        return default or "ED"
    return "OTHER"


def _ensure_patient_location_movement_schema(cur):
    """Create the ED patient movement timeline table and repair visit columns."""
    try:
        if (DB_ENGINE or "").lower() == "postgres":
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS patient_location_movements (
                    id BIGSERIAL PRIMARY KEY,
                    visit_id TEXT,
                    from_area TEXT,
                    from_location TEXT,
                    from_bed TEXT,
                    to_area TEXT,
                    to_location TEXT,
                    to_bed TEXT,
                    status TEXT,
                    note TEXT,
                    moved_at TEXT,
                    moved_by TEXT
                )
                """
            )
            for col, typ in (
                ("movement_note", "TEXT"),
                ("location_updated_at", "TEXT"),
                ("location_updated_by", "TEXT"),
            ):
                cur.execute(f"ALTER TABLE visits ADD COLUMN IF NOT EXISTS {col} {typ}")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_patient_location_movements_visit_id ON patient_location_movements(visit_id)")
        else:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS patient_location_movements (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    visit_id TEXT,
                    from_area TEXT,
                    from_location TEXT,
                    from_bed TEXT,
                    to_area TEXT,
                    to_location TEXT,
                    to_bed TEXT,
                    status TEXT,
                    note TEXT,
                    moved_at TEXT,
                    moved_by TEXT
                )
                """
            )
            try:
                existing = {str(r[1]).lower() for r in cur.execute("PRAGMA table_info(visits)").fetchall()}
            except Exception:
                existing = set()
            for col, typ in (
                ("movement_note", "TEXT"),
                ("location_updated_at", "TEXT"),
                ("location_updated_by", "TEXT"),
            ):
                if col.lower() not in existing:
                    cur.execute(f"ALTER TABLE visits ADD COLUMN {col} {typ}")
            try:
                cur.execute("CREATE INDEX IF NOT EXISTS idx_patient_location_movements_visit_id ON patient_location_movements(visit_id)")
            except Exception:
                pass
    except Exception as exc:
        _log_noncritical_exception("Patient location movement schema repair failed", exc)


def _row_get_safe(row, key, default=""):
    try:
        val = row[key]
    except Exception:
        try:
            val = row.get(key, default)
        except Exception:
            val = default
    return default if val is None else val


def _read_visit_location_snapshot(cur, visit_id):
    try:
        row = cur.execute(
            "SELECT COALESCE(care_area,'') AS care_area, COALESCE(location,'') AS location, COALESCE(bed_no,'') AS bed_no, COALESCE(bed_status,'') AS bed_status FROM visits WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
    except Exception:
        row = None
    return {
        "care_area": _movement_clean(_row_get_safe(row, "care_area", "") if row else "", 40),
        "location": _movement_clean(_row_get_safe(row, "location", "") if row else "", 120),
        "bed_no": _movement_clean(_row_get_safe(row, "bed_no", "") if row else "", 80),
        "bed_status": _movement_clean(_row_get_safe(row, "bed_status", "") if row else "", 40),
    }


def _insert_patient_location_movement(cur, visit_id, before_loc, after_loc, status, note, moved_at, moved_by):
    try:
        cur.execute(
            """
            INSERT INTO patient_location_movements
                (visit_id, from_area, from_location, from_bed, to_area, to_location, to_bed, status, note, moved_at, moved_by)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                visit_id,
                before_loc.get("care_area") or "",
                before_loc.get("location") or "",
                before_loc.get("bed_no") or "",
                after_loc.get("care_area") or "",
                after_loc.get("location") or "",
                after_loc.get("bed_no") or "",
                status,
                note,
                moved_at,
                moved_by,
            ),
        )
    except Exception as exc:
        _log_noncritical_exception(f"Patient location movement insert failed visit={visit_id}", exc)


def _format_order_source_text(area, location, bed):
    parts = []
    if area:
        parts.append(str(area).strip())
    if location:
        parts.append(str(location).strip())
    if bed:
        parts.append("Bed " + str(bed).strip())
    return " - ".join([p for p in parts if p])

@app.route("/visit/<visit_id>/close", methods=["POST"])
@login_required
@role_required("nurse", "doctor", "admin", "reception")
def close_visit(visit_id):
    status = (request.form.get("status", "DISCHARGED") or "").strip().upper()

    allowed_statuses = [
        "DISCHARGED",
        "ADMITTED",
        "TRANSFERRED",
        "LAMA",
        "EXPIRED",
        "IN_TREATMENT",
        "CANCELLED",
        "CALLED",
        "VISIT_PROGRESS",
        "VISIT_COMPLETED",
        "REGISTERED",
    ]
    if status not in allowed_statuses:
        status = "DISCHARGED"

    # Extra data for certain statuses

    # Reception policy: reception can only CANCEL visits (with reason).
    if session.get("role") == "reception" and status != "CANCELLED":
        flash("Reception can only set status to CANCELLED.", "danger")
        return redirect(url_for("patient_details", visit_id=visit_id))

    lama_reason = (request.form.get("lama_reason") or "").strip()
    transfer_hospital = (request.form.get("transfer_hospital") or "").strip()
    transfer_doctor = (request.form.get("transfer_doctor") or "").strip()
    cancel_reason = (
        request.form.get("cancel_reason")
        or request.form.get("reason")
        or request.form.get("cancellation_reason")
        or ""
    ).strip()

    # Current location / movement fields. Blank fields keep the existing value;
    # selected fields update the visit and become the default source for new orders.
    requested_care_area_raw = (request.form.get("care_area") or "").strip()
    requested_location_raw = (request.form.get("location") or "").strip()
    requested_bed_raw = (request.form.get("bed_no") or "").strip()
    requested_bed_status_raw = (request.form.get("bed_status") or "").strip()
    movement_note = _movement_clean(request.form.get("movement_note") or "", 200)

    # Server-side validation (UI collects these via popups)
    if status == "LAMA" and not lama_reason:
        flash("LAMA reason is required.", "danger")
        return redirect(url_for("patient_details", visit_id=visit_id))

    if status == "TRANSFERRED":
        if not transfer_hospital or not transfer_doctor:
            flash("Transfer hospital and receiving physician are required.", "danger")
            return redirect(url_for("patient_details", visit_id=visit_id))
    if status == "CANCELLED" and not cancel_reason:
        flash("Cancel reason is required.", "danger")
        return redirect(url_for("patient_details", visit_id=visit_id))

    # Keep values only when relevant (clears old values on status change)
    lama_reason_db = lama_reason if status == "LAMA" else None
    transfer_hospital_db = transfer_hospital if status == "TRANSFERRED" else None
    transfer_doctor_db = transfer_doctor if status == "TRANSFERRED" else None

    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    user = session.get("username")
    cancel_reason_db = cancel_reason if status == "CANCELLED" else None
    cancelled_by_db = user if status == "CANCELLED" else None
    cancelled_at_db = now if status == "CANCELLED" else None

    close_updated = False
    last_close_exc = None
    for _attempt in range(3):
        pg_conn = None
        sqlite_conn = None
        try:
            if DB_ENGINE == "postgres":
                from db import pool_getconn, pool_putconn

                pg_conn = pool_getconn(timeout_s=1.5)
                pg_conn.autocommit = False
                close_db_conn = PostgresDBWrapper(pg_conn)
                try:
                    close_db_conn.execute("SET LOCAL lock_timeout = '1000ms'")
                    close_db_conn.execute("SET LOCAL statement_timeout = '8000ms'")
                except Exception:
                    pass
                _ensure_patient_location_movement_schema(close_db_conn.cursor())
                before_loc = _read_visit_location_snapshot(close_db_conn.cursor(), visit_id)
                new_care_area = _normalize_care_area(requested_care_area_raw, before_loc.get("care_area") or "ED")
                new_location = _movement_clean(requested_location_raw, 120) if requested_location_raw else before_loc.get("location", "")
                new_bed_no = _movement_clean(requested_bed_raw, 80) if requested_bed_raw else before_loc.get("bed_no", "")
                new_bed_status = _movement_clean(requested_bed_status_raw, 40).upper() if requested_bed_status_raw else before_loc.get("bed_status", "")
                after_loc = {"care_area": new_care_area, "location": new_location, "bed_no": new_bed_no, "bed_status": new_bed_status}
                try:
                    close_db_conn.execute(
                        """
                        UPDATE visits
                           SET status=?,
                               closed_at=?,
                               closed_by=?,
                               lama_reason=?,
                               transfer_hospital=?,
                               transfer_doctor=?,
                               cancel_reason=?,
                               cancelled_by=?,
                               cancelled_at=?,
                               care_area=?,
                               location=?,
                               bed_no=?,
                               bed_status=?,
                               movement_note=?,
                               location_updated_at=?,
                               location_updated_by=?
                         WHERE visit_id=?
                        """,
                        (
                            status,
                            now,
                            user,
                            lama_reason_db,
                            transfer_hospital_db,
                            transfer_doctor_db,
                            cancel_reason_db,
                            cancelled_by_db,
                            cancelled_at_db,
                            new_care_area,
                            new_location,
                            new_bed_no,
                            new_bed_status,
                            movement_note,
                            now,
                            user,
                            visit_id,
                        ),
                    )
                    if (before_loc.get("care_area") or before_loc.get("location") or before_loc.get("bed_no")) != (after_loc.get("care_area") or after_loc.get("location") or after_loc.get("bed_no")) or status:
                        _insert_patient_location_movement(close_db_conn.cursor(), visit_id, before_loc, after_loc, status, movement_note, now, user)
                except Exception:
                    close_db_conn.execute(
                        """
                        UPDATE visits
                           SET status=?,
                               closed_at=?,
                               closed_by=?
                         WHERE visit_id=?
                        """,
                        (status, now, user, visit_id),
                    )
                pg_conn.commit()
                close_updated = True
                break

            sqlite_conn = sqlite3.connect(DATABASE, check_same_thread=False)
            cur = sqlite_conn.cursor()
            _ensure_patient_location_movement_schema(cur)
            before_loc = _read_visit_location_snapshot(cur, visit_id)
            new_care_area = _normalize_care_area(requested_care_area_raw, before_loc.get("care_area") or "ED")
            new_location = _movement_clean(requested_location_raw, 120) if requested_location_raw else before_loc.get("location", "")
            new_bed_no = _movement_clean(requested_bed_raw, 80) if requested_bed_raw else before_loc.get("bed_no", "")
            new_bed_status = _movement_clean(requested_bed_status_raw, 40).upper() if requested_bed_status_raw else before_loc.get("bed_status", "")
            after_loc = {"care_area": new_care_area, "location": new_location, "bed_no": new_bed_no, "bed_status": new_bed_status}
            try:
                cur.execute(
                    """
                    UPDATE visits
                       SET status=?,
                           closed_at=?,
                           closed_by=?,
                           lama_reason=?,
                           transfer_hospital=?,
                           transfer_doctor=?,
                           cancel_reason=?,
                           cancelled_by=?,
                           cancelled_at=?,
                           care_area=?,
                           location=?,
                           bed_no=?,
                           bed_status=?,
                           movement_note=?,
                           location_updated_at=?,
                           location_updated_by=?
                     WHERE visit_id=?
                    """,
                    (
                        status,
                        now,
                        user,
                        lama_reason_db,
                        transfer_hospital_db,
                        transfer_doctor_db,
                        cancel_reason_db,
                        cancelled_by_db,
                        cancelled_at_db,
                        new_care_area,
                        new_location,
                        new_bed_no,
                        new_bed_status,
                        movement_note,
                        now,
                        user,
                        visit_id,
                    ),
                )
                if (before_loc.get("care_area") or before_loc.get("location") or before_loc.get("bed_no")) != (after_loc.get("care_area") or after_loc.get("location") or after_loc.get("bed_no")) or status:
                    _insert_patient_location_movement(cur, visit_id, before_loc, after_loc, status, movement_note, now, user)
            except Exception:
                cur.execute(
                    """
                    UPDATE visits
                       SET status=?,
                           closed_at=?,
                           closed_by=?
                     WHERE visit_id=?
                    """,
                    (status, now, user, visit_id),
                )
            sqlite_conn.commit()
            close_updated = True
            break
        except Exception as e:
            last_close_exc = e
            try:
                if pg_conn is not None:
                    pg_conn.rollback()
            except Exception:
                pass
            try:
                if sqlite_conn is not None:
                    sqlite_conn.rollback()
            except Exception:
                pass
            time.sleep(0.1 * (_attempt + 1))
        finally:
            if pg_conn is not None:
                try:
                    pool_putconn(pg_conn)
                except Exception:
                    pass
            if sqlite_conn is not None:
                try:
                    sqlite_conn.close()
                except Exception:
                    pass

    if not close_updated:
        flash("Visit is busy with another update right now. Please retry in a few seconds.", "warning")
        try:
            _log_noncritical_exception(f"close_visit busy visit_id={visit_id}", last_close_exc)
        except Exception:
            pass
        return redirect(url_for("patient_details", visit_id=visit_id))

    details = status
    loc_summary = _format_order_source_text(
        _normalize_care_area(requested_care_area_raw, ""),
        _movement_clean(requested_location_raw, 120),
        _movement_clean(requested_bed_raw, 80),
    )
    if status == "LAMA":
        details = f"{status}|Reason={lama_reason}"
    elif status == "TRANSFERRED":
        details = f"{status}|To={transfer_hospital}|ReceivingDr={transfer_doctor}"
    if loc_summary:
        details = f"{details}|Location={loc_summary}"

    log_action("CLOSE_VISIT", visit_id=visit_id, details=details)
    flash(f"Visit closed as {status}.", "success")
    return redirect(url_for("patient_details", visit_id=visit_id))


@app.route("/depart/<visit_id>", methods=["GET", "POST"])
@login_required
@role_required("reception", "nurse", "doctor", "admin")
def depart_workflow(visit_id):
    """
    ED Depart / Discharge workflow page.
    Shows a Cerner-like checklist (registration, sepsis, ECG)
    and quick links to discharge PDFs and close-visit.
    """
    db = get_db()
    cur = db.cursor()

    visit = cur.execute(
        """
        SELECT v.*,
               p.name,
               p.mrn,
               p.id_number,
               p.phone,
               p.insurance,
               p.insurance_no,
               p.dob,
               p.sex,
               p.nationality
        FROM visits v
        JOIN patients p ON p.id = v.patient_id
        WHERE v.visit_id=?
    """,
        (visit_id,),
    ).fetchone()

    if not visit:
        flash("Visit not found.", "danger")
        return redirect(url_for("ed_board"))

    if request.method == "POST":
        # Update simple checklist tasks
        task_reg = "YES" if request.form.get("task_reg") else ""
        task_ekg = "YES" if request.form.get("task_ekg") else ""
        task_sepsis = "YES" if request.form.get("task_sepsis") else ""

        cur.execute(
            "UPDATE visits SET task_reg=?, task_ekg=?, task_sepsis=? WHERE visit_id=?",
            (task_reg, task_ekg, task_sepsis, visit_id),
        )
        db.commit()

        log_action(
            "UPDATE_VISIT_TASKS",
            visit_id=visit_id,
            details=f"REG={task_reg or 'NO'},EKG={task_ekg or 'NO'},SEP={task_sepsis or 'NO'}",
        )
        flash("Checklist tasks updated.", "success")
        return redirect(url_for("depart_workflow", visit_id=visit_id))

    # Orders count
    try:
        row = cur.execute(
            "SELECT COUNT(*) AS c FROM clinical_orders WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
        orders_count = row["c"] if row is not None else 0
    except Exception as e:
        _log_noncritical_exception(
            f"Depart workflow orders count failed for visit={visit_id}", e
        )
        orders_count = 0

    # Lab counts
    labs_total = labs_pending = labs_reported = 0
    try:
        lab_rows = cur.execute(
            "SELECT status, COUNT(*) AS c FROM lab_requests WHERE visit_id=? GROUP BY status",
            (visit_id,),
        ).fetchall()
        for r in lab_rows:
            st = (r["status"] or "").upper()
            c = r["c"] or 0
            labs_total += c
            if st in ("REQUESTED", "RECEIVED"):
                labs_pending += c
            elif st == "REPORTED":
                labs_reported += c
    except Exception as e:
        _log_noncritical_exception(
            f"Depart workflow lab counters failed for visit={visit_id}", e
        )

    # Radiology counts
    rads_total = rads_pending = rads_reported = 0
    try:
        rad_rows = cur.execute(
            "SELECT status, COUNT(*) AS c FROM radiology_requests WHERE visit_id=? GROUP BY status",
            (visit_id,),
        ).fetchall()
        for r in rad_rows:
            st = (r["status"] or "").upper()
            c = r["c"] or 0
            rads_total += c
            if st in ("REQUESTED", "SENT", "RECEIVED", "UNDER_PROCESS", "DONE"):
                rads_pending += c
            elif st == "REPORTED":
                rads_reported += c
    except Exception as e:
        _log_noncritical_exception(
            f"Depart workflow radiology counters failed for visit={visit_id}", e
        )

    # Discharge summary presence
    try:
        discharge = cur.execute(
            "SELECT diagnosis_cc, summary_text FROM discharge_summaries WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
    except Exception as e:
        _log_noncritical_exception(
            f"Depart workflow discharge summary check failed for visit={visit_id}", e
        )
        discharge = None

    discharge_exists = discharge is not None
    discharge_diag = ""
    if discharge:
        discharge_diag = (discharge["diagnosis_cc"] or "").strip() or ""

    # Log view
    try:
        log_action("DEPART_VIEW", visit_id=visit_id)
    except Exception as e:
        _log_noncritical_exception(
            f"Depart workflow audit log failed for visit={visit_id}", e
        )

    return render_template(
        "depart_workflow.html",
        visit=visit,
        orders_count=orders_count,
        labs_total=labs_total,
        labs_pending=labs_pending,
        labs_reported=labs_reported,
        rads_total=rads_total,
        rads_pending=rads_pending,
        rads_reported=rads_reported,
        discharge_exists=discharge_exists,
        discharge_diag=discharge_diag,
    )


@app.route("/visit/<visit_id>/cancel", methods=["POST"])
@login_required
@role_required("reception", "admin")
def cancel_visit(visit_id):
    """Allow reception to cancel a visit that has not yet been seen by the doctor.

    Rules:
    - Visit must still be OPEN.
    - There must be no clinical orders for this visit.
    - A text reason is mandatory.
    """
    reason = (
        (request.form.get("cancel_reason") or request.form.get("reason")) or ""
    ).strip()
    if not reason:
        flash("Please enter a reason for cancellation.", "danger")
        return redirect(url_for("patient_details", visit_id=visit_id))

    db = get_db()
    cur = db.cursor()

    visit = cur.execute(
        "SELECT id, status FROM visits WHERE visit_id=?",
        (visit_id,),
    ).fetchone()
    if not visit:
        flash("Visit not found.", "danger")
        return redirect(url_for("ed_board"))

    if (visit["status"] or "").upper() not in ("OPEN", "REGISTERED"):
        flash("This visit is already closed or cancelled.", "danger")
        return redirect(url_for("patient_details", visit_id=visit_id))

    # If there are clinical orders, we assume the doctor has already seen the patient
    try:
        orders_row = cur.execute(
            "SELECT COUNT(*) AS c FROM clinical_orders WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
        orders_count = orders_row["c"] if orders_row is not None else 0
    except Exception as e:
        _log_critical_exception(
            f"Cancel-visit safety check failed while counting clinical orders for visit={visit_id}",
            e,
        )
        flash(
            "Unable to validate doctor activity for this visit. Cancellation is blocked for safety.",
            "danger",
        )
        return redirect(url_for("patient_details", visit_id=visit_id))

    if orders_count > 0:
        flash(
            "This visit cannot be cancelled because it has already been seen by a doctor.",
            "danger",
        )
        return redirect(url_for("patient_details", visit_id=visit_id))

    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    username = session.get("username", "")

    cur.execute(
        """UPDATE visits
               SET status='CANCELLED',
                   cancel_reason=?,
                   cancelled_by=?,
                   cancelled_at=?,
                   closed_at=?,
                   closed_by=?
             WHERE visit_id=? AND UPPER(COALESCE(status,'')) IN ('OPEN','REGISTERED')""",
        (reason, username, now, now, username, visit_id),
    )
    db.commit()

    log_action("CANCEL_VISIT", visit_id=visit_id, details=reason)
    flash("Visit has been cancelled successfully by Reception.", "info")
    return redirect(url_for("patient_details", visit_id=visit_id))


@app.route("/visit/<visit_id>/hard_delete", methods=["POST"])
@login_required
@role_required("admin")
def hard_delete_visit(visit_id):
    """Permanently delete a visit and (optionally) its patient record.

    This is an admin-only, destructive action.

    Notes:
    - We wrap the whole operation in try/except to avoid returning a 500 page
      in case logging/audit tables are missing or any single delete fails.
    - We also best-effort delete uploaded files linked to this visit.
    """
    db = get_db()
    cur = db.cursor()

    try:
        visit = cur.execute(
            "SELECT id, patient_id FROM visits WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
        if not visit:
            flash("Visit not found.", "danger")
            return redirect(url_for("ed_board"))

        patient_id = (
            visit.get("patient_id") if isinstance(visit, dict) else visit["patient_id"]
        )

        # -----------------------------
        # Delete uploaded files (best-effort)
        # -----------------------------
        try:
            att_rows = cur.execute(
                "SELECT filename FROM attachments WHERE visit_id=?",
                (visit_id,),
            ).fetchall()
            for a in att_rows or []:
                try:
                    fname = a.get("filename") if isinstance(a, dict) else a["filename"]
                    if fname:
                        remove_upload_file_if_exists(fname)
                except Exception as e:
                    _log_noncritical_exception(
                        f"Hard delete could not remove one attachment file for visit={visit_id}",
                        e,
                    )
        except Exception as e:
            _log_noncritical_exception(
                f"Hard delete could not enumerate attachments for visit={visit_id}", e
            )

        # -----------------------------
        # Delete dependent rows (best-effort)
        # -----------------------------
        delete_sqls = [
            "DELETE FROM attachments WHERE visit_id=?",
            "DELETE FROM patient_lab_results WHERE case_no=?",
            "DELETE FROM patient_home_meds WHERE visit_id=?",
            "DELETE FROM patient_vitals WHERE case_number=?",
            "DELETE FROM clinical_orders WHERE visit_id=?",
            "DELETE FROM nursing_notes WHERE visit_id=?",
            "DELETE FROM provider_notes WHERE visit_id=?",
            "DELETE FROM lab_requests WHERE visit_id=?",
            "DELETE FROM radiology_requests WHERE visit_id=?",
            "DELETE FROM vital_signs WHERE visit_id=?",
            "DELETE FROM discharge_summaries WHERE visit_id=?",
            "DELETE FROM chat_messages WHERE visit_id=?",
            # Logs are not FK-constrained, but should be removed for privacy.
            "DELETE FROM activity_log WHERE visit_id=?",
        ]
        for sql in delete_sqls:
            try:
                cur.execute(sql, (visit_id,))
            except Exception as e:
                _log_noncritical_exception(
                    f"Hard delete skipped dependent table delete for visit={visit_id}: {sql}",
                    e,
                )

        # Admission tables may not exist on some deployments/older schemas
        for sql in [
            "DELETE FROM admission_order_audit WHERE visit_id=?",
            "DELETE FROM admission_orders WHERE visit_id=?",
        ]:
            try:
                cur.execute(sql, (visit_id,))
            except Exception as e:
                _log_noncritical_exception(
                    f"Hard delete skipped admission cleanup for visit={visit_id}: {sql}",
                    e,
                )

        # Finally delete the visit row
        cur.execute("DELETE FROM visits WHERE visit_id=?", (visit_id,))

        # Delete the patient row if this was the last visit
        try:
            remaining = cur.execute(
                "SELECT COUNT(*) AS cnt FROM visits WHERE patient_id=?",
                (patient_id,),
            ).fetchone()
            if remaining:
                try:
                    cnt = (
                        remaining.get("cnt")
                        if isinstance(remaining, dict)
                        else remaining["cnt"]
                    )
                except Exception:
                    # Fallback for drivers that return tuples
                    cnt = list(remaining)[0]
            else:
                cnt = 0

            if int(cnt or 0) == 0:
                cur.execute("DELETE FROM patients WHERE id=?", (patient_id,))
        except Exception as e:
            _log_noncritical_exception(
                f"Hard delete failed while deleting orphan patient for visit={visit_id}",
                e,
            )

        db.commit()

        # Logging should never break hard delete
        try:
            log_action(
                "HARD_DELETE_VISIT", visit_id=visit_id, details="Admin hard delete"
            )
        except Exception as e:
            _log_noncritical_exception(
                f"Hard delete audit log failed for visit={visit_id}", e
            )

        flash("Patient record and visit deleted permanently.", "success")

    except Exception as e:
        try:
            db.rollback()
        except Exception as rb_exc:
            _log_noncritical_exception(
                f"Hard delete rollback failed for visit={visit_id}", rb_exc
            )
        flash(f"Hard delete failed: {e}", "danger")

    return redirect(url_for("ed_board"))


@app.route("/triage/<visit_id>", methods=["GET", "POST"])
@login_required
@role_required("nurse", "doctor", "admin")
def triage(visit_id):
    db = get_db()
    cur = db.cursor()
    visit = cur.execute(
        """
        SELECT v.*, 
               p.name, p.mrn, p.id_number, p.phone,
               p.insurance, p.insurance_no,
               p.dob, p.sex, p.nationality
        FROM visits v JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
    """,
        (visit_id,),
    ).fetchone()
    if not visit:
        flash("Visit not found.", "danger")
        return redirect(url_for("ed_board"))

    if request.method == "POST":
        # Core fields
        comment = (request.form.get("comment", "") or "").strip()
        cat = (request.form.get("triage_cat", "") or "").strip()
        assigned_doctor = (request.form.get("assigned_doctor", "") or "").strip()

        # Paper-form header fields
        facility = (request.form.get("facility", "") or "").strip()
        triage_date = (request.form.get("triage_date", "") or "").strip()
        triage_clock = (request.form.get("triage_clock", "") or "").strip()

        # Mode of arrival (multi)
        arrival_mode = ", ".join(
            [v for v in request.form.getlist("arrival_mode") if (v or "").strip()]
        )
        arrival_other = (request.form.get("arrival_other", "") or "").strip()

        # Primary caregiver
        caregiver_type = (request.form.get("caregiver_type", "") or "").strip()
        caregiver_names = (request.form.get("caregiver_names", "") or "").strip()

        # Stroke screen
        stroke_signs = (request.form.get("stroke_signs", "") or "").strip()
        stroke_specify = (request.form.get("stroke_specify", "") or "").strip()

        # Allergy
        allergy = (request.form.get("allergy_status", "") or "").strip()
        allergy_details = (request.form.get("allergy_details", "") or "").strip()

        # Vital signs
        pr = (request.form.get("pulse_rate", "") or "").strip()
        rr = (request.form.get("resp_rate", "") or "").strip()
        bp_sys = (request.form.get("bp_systolic", "") or "").strip()
        bp_dia = (request.form.get("bp_diastolic", "") or "").strip()
        temp = (request.form.get("temperature", "") or "").strip()
        consciousness_level = (
            request.form.get("consciousness_level", "") or ""
        ).strip()
        spo2 = (request.form.get("spo2", "") or "").strip()
        pain = (request.form.get("pain_score", "") or "").strip()
        weight = (request.form.get("weight", "") or "").strip()
        height = (request.form.get("height", "") or "").strip()

        # Pain scales
        wong_baker_score = (request.form.get("wong_baker_score", "") or "").strip()
        nips_score = (request.form.get("nips_score", "") or "").strip()

        # Fall risk / pregnancy
        fall_risk = (request.form.get("fall_risk", "") or "").strip()
        fall_risk_tool = (request.form.get("fall_risk_tool", "") or "").strip()
        fall_risk_score = (request.form.get("fall_risk_score", "") or "").strip()
        fall_risk_details = (request.form.get("fall_risk_details", "") or "").strip()

        pregnancy_status = (request.form.get("pregnancy_status", "") or "").strip()
        lmp = (request.form.get("lmp", "") or "").strip()

        # ESI decision helpers (Yes/No + resources)
        immediate_life_saving = (
            request.form.get("immediate_life_saving", "") or ""
        ).strip()
        high_risk_situation = (
            request.form.get("high_risk_situation", "") or ""
        ).strip()
        resources_needed = (request.form.get("resources_needed", "") or "").strip()
        danger_zone_vitals = (request.form.get("danger_zone_vitals", "") or "").strip()

        # Neuro / respiratory assessment
        orientation = ", ".join(
            [v for v in request.form.getlist("orientation") if (v or "").strip()]
        )
        orientation_other = (request.form.get("orientation_other", "") or "").strip()

        work_of_breathing = ", ".join(
            [v for v in request.form.getlist("work_of_breathing") if (v or "").strip()]
        )
        work_breathing_other = (
            request.form.get("work_breathing_other", "") or ""
        ).strip()

        respiratory_pattern = ", ".join(
            [
                v
                for v in request.form.getlist("respiratory_pattern")
                if (v or "").strip()
            ]
        )
        resp_pattern_other = (request.form.get("resp_pattern_other", "") or "").strip()

        # PHQ-9
        phq = {}
        phq_total_int = 0
        for i in range(1, 10):
            key = f"phq_q{i}"
            val = (request.form.get(key, "") or "").strip()
            phq[key] = val
            try:
                phq_total_int += int(val) if val != "" else 0
            except Exception as e:
                _log_noncritical_exception(
                    f"Invalid PHQ-9 value ignored in triage visit={visit_id} field={key}",
                    e,
                )
        phq_total = (
            str(phq_total_int)
            if any((phq.get(f"phq_q{i}") or "").strip() != "" for i in range(1, 10))
            else ""
        )

        # Travel / exposure / symptoms
        travel_history = (request.form.get("travel_history", "") or "").strip()
        travel_location = (request.form.get("travel_location", "") or "").strip()
        contact_travel_history = (
            request.form.get("contact_travel_history", "") or ""
        ).strip()
        contact_travel_location = (
            request.form.get("contact_travel_location", "") or ""
        ).strip()

        exposure_comm_disease = (
            request.form.get("exposure_comm_disease", "") or ""
        ).strip()
        exposure_details = (request.form.get("exposure_details", "") or "").strip()

        infectious_symptoms = ", ".join(
            [
                v
                for v in request.form.getlist("infectious_symptoms")
                if (v or "").strip()
            ]
        )

        pre_arrival_interventions = (
            request.form.get("pre_arrival_interventions", "") or ""
        ).strip()
        triage_interventions = (
            request.form.get("triage_interventions", "") or ""
        ).strip()
        other_notes = (request.form.get("other_notes", "") or "").strip()

        if not cat:
            flash("Triage Category (ESI) is required.", "danger")
            return redirect(url_for("triage", visit_id=visit_id))

        # Single timestamp used for both visit record and vitals history
        now_ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

        # Default triage date/time if user didn't fill it
        if not triage_date:
            triage_date = now_ts.split(" ")[0]
        if not triage_clock:
            triage_clock = now_ts.split(" ")[1][:5]

        db.execute(
            """
            UPDATE visits SET
                triage_status='YES',
                triage_cat=?,
                status=CASE WHEN UPPER(COALESCE(status,'')) IN ('OPEN','REGISTERED') THEN 'CALLED' ELSE status END,
                comment=?,
                assigned_doctor=COALESCE(NULLIF(?,''), assigned_doctor),

                facility=?,
                triage_date=?,
                triage_clock=?,
                arrival_mode=?,
                arrival_other=?,
                caregiver_type=?,
                caregiver_names=?,
                stroke_signs=?,
                stroke_specify=?,

                allergy_status=?,
                allergy_details=?,

                pulse_rate=?,
                resp_rate=?,
                bp_systolic=?,
                bp_diastolic=?,
                temperature=?,
                consciousness_level=?,
                spo2=?,
                pain_score=?,
                weight=?,
                height=?,

                wong_baker_score=?,
                nips_score=?,

                fall_risk=?,

                fall_risk_tool=?,
                fall_risk_score=?,
                fall_risk_details=?,

                pregnancy_status=?,
                lmp=?,

                immediate_life_saving=?,
                high_risk_situation=?,
                resources_needed=?,
                danger_zone_vitals=?,

                orientation=?,
                orientation_other=?,
                work_of_breathing=?,
                work_breathing_other=?,
                respiratory_pattern=?,
                resp_pattern_other=?,

                phq_q1=?,
                phq_q2=?,
                phq_q3=?,
                phq_q4=?,
                phq_q5=?,
                phq_q6=?,
                phq_q7=?,
                phq_q8=?,
                phq_q9=?,
                phq_total=?,

                travel_history=?,
                travel_location=?,
                contact_travel_history=?,
                contact_travel_location=?,
                exposure_comm_disease=?,
                exposure_details=?,
                infectious_symptoms=?,
                pre_arrival_interventions=?,
                triage_interventions=?,
                other_notes=?,

                triage_time=?
            WHERE visit_id=?
        """,
            (
                cat,
                comment,
                assigned_doctor,
                facility,
                triage_date,
                triage_clock,
                arrival_mode,
                arrival_other,
                caregiver_type,
                caregiver_names,
                stroke_signs,
                stroke_specify,
                allergy,
                allergy_details,
                pr,
                rr,
                bp_sys,
                bp_dia,
                temp,
                consciousness_level,
                spo2,
                pain,
                weight,
                height,
                wong_baker_score,
                nips_score,
                fall_risk,
                fall_risk_tool,
                fall_risk_score,
                fall_risk_details,
                pregnancy_status,
                lmp,
                immediate_life_saving,
                high_risk_situation,
                resources_needed,
                danger_zone_vitals,
                orientation,
                orientation_other,
                work_of_breathing,
                work_breathing_other,
                respiratory_pattern,
                resp_pattern_other,
                phq.get("phq_q1", ""),
                phq.get("phq_q2", ""),
                phq.get("phq_q3", ""),
                phq.get("phq_q4", ""),
                phq.get("phq_q5", ""),
                phq.get("phq_q6", ""),
                phq.get("phq_q7", ""),
                phq.get("phq_q8", ""),
                phq.get("phq_q9", ""),
                phq_total,
                travel_history,
                travel_location,
                contact_travel_history,
                contact_travel_location,
                exposure_comm_disease,
                exposure_details,
                infectious_symptoms,
                pre_arrival_interventions,
                triage_interventions,
                other_notes,
                now_ts,
                visit_id,
            ),
        )

        # Keep vitals history for trend graph
        try:
            db.execute(
                """
                INSERT INTO vital_signs (
                    visit_id, recorded_at,
                    pulse_rate, resp_rate,
                    bp_systolic, bp_diastolic,
                    temperature, consciousness_level,
                    spo2, pain_score,
                    weight, height,
                    recorded_by
                )
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)
            """,
                (
                    visit_id,
                    now_ts,
                    pr,
                    rr,
                    bp_sys,
                    bp_dia,
                    temp,
                    consciousness_level,
                    spo2,
                    pain,
                    weight,
                    height,
                    session.get("username", "UNKNOWN"),
                ),
            )
        except Exception as e:
            _log_noncritical_exception(
                f"Triage vitals history insert failed for visit={visit_id}", e
            )

        try:
            insert_patient_vitals_reading(
                visit_id,
                bp=_compose_bp_value(bp_sys, bp_dia),
                hr=pr,
                rr=rr,
                temp=temp,
                spo2=spo2,
                recorded_by=session.get("username", "UNKNOWN"),
                recorded_at=now_ts,
                db=db,
                commit=False,
            )
        except Exception as e:
            _log_noncritical_exception(
                f"Triage serial vitals insert failed for visit={visit_id}", e
            )

        try:
            if visit["patient_id"] not in (None, ""):
                db.execute(
                    """
                    UPDATE patients
                       SET latest_bp=?,
                           latest_bp_systolic=?,
                           latest_bp_diastolic=?,
                           latest_hr=?,
                           latest_rr=?,
                           latest_temp=?,
                           latest_spo2=?,
                           latest_vitals_recorded_by=?,
                           latest_vitals_recorded_at=?
                     WHERE id=?
                    """,
                    (
                        _compose_bp_value(bp_sys, bp_dia),
                        bp_sys,
                        bp_dia,
                        pr,
                        rr,
                        temp,
                        spo2,
                        session.get("username", "UNKNOWN"),
                        now_ts,
                        visit["patient_id"],
                    ),
                )
        except Exception as e:
            _log_noncritical_exception(
                f"Triage patient latest vitals sync failed for visit={visit_id}", e
            )

        db.commit()
        log_action("TRIAGE_UPDATE", visit_id=visit_id, details=f"CAT={cat}")
        flash("Triage saved successfully.", "success")
        return redirect(url_for("patient_details", visit_id=visit_id))

        # Doctor options (users + Physicians Directory picklist)
    doctor_options = []
    try:
        rows = db.execute(
            "SELECT username, gd_number FROM users WHERE is_active=1 AND role='doctor' ORDER BY LOWER(username), username"
        ).fetchall()
        for r in rows:
            username = (
                r["username"]
                if isinstance(r, sqlite3.Row)
                else (r[0] if len(r) > 0 else "")
            ) or ""
            gd = (
                r["gd_number"]
                if isinstance(r, sqlite3.Row)
                else (r[1] if len(r) > 1 else "")
            ) or ""
            username = username.strip()
            gd = gd.strip()
            if not username:
                continue
            label = f"{username} ({gd})" if gd else username
            doctor_options.append({"value": username, "label": label})
    except Exception as e:
        _log_noncritical_exception(
            f"Doctor options users query failed in triage visit={visit_id}", e
        )

    try:
        for d in picklist_get_doctors():
            username = (d.get("username") or "").strip()
            gd = (d.get("gd_number") or "").strip()
            spec = (d.get("specialty") or "").strip()
            if not username:
                continue

            exists = False
            for o in doctor_options:
                o_name = (o.get("value") or "").strip()
                if o_name.lower() == username.lower():
                    # If GD matches (or GD missing), treat as duplicate
                    if (not gd) or (f"({gd})" in (o.get("label") or "")):
                        exists = True
                        break
            if exists:
                continue

            label = f"{username} ({gd})" if gd else username
            if spec:
                label = f"{label} - {spec}"
            doctor_options.append({"value": username, "label": label})
    except Exception as e:
        _log_noncritical_exception(
            f"Doctor options picklist merge failed in triage visit={visit_id}", e
        )

    doctor_options.sort(key=lambda x: (x.get("label") or x.get("value") or "").lower())

    initial_visit_lock_others = prepare_visit_lock_context(visit_id, request.path)
    return render_template(
        "triage.html",
        visit=visit,
        doctor_options=doctor_options,
        initial_visit_lock_others=initial_visit_lock_others,
    )


# ============================================================
# Auto Summary Builder
# ============================================================


def build_auto_summary_sections(visit_id):
    """
    Build structured sections for the Auto ED Course Summary.

    Returns:
        list[tuple[str,str]]: [(section_title, section_text), ...]
    """
    db = get_db()
    cur = db.cursor()

    visit = cur.execute(
        """
        SELECT v.*, p.name, p.id_number, p.phone, p.insurance, p.insurance_no,
               p.dob, p.sex, p.nationality
        FROM visits v
        JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
    """,
        (visit_id,),
    ).fetchone()

    if not visit:
        return []

    def _g(row, key, default=""):
        try:
            v = row[key]
        except Exception:
            try:
                v = row.get(key, default)
            except Exception:
                v = default
        return v if v is not None else default

    def _fmt_ts(v):
        return format_dt_local(v) or (str(v).strip() if v else "-")

    def _clean_lines(val):
        # Split multi-line text into clean bullet lines
        out = []
        if val is None:
            return out
        for ln in str(val).splitlines():
            ln = ln.strip()
            if ln:
                out.append(ln)
        return out

    def _split_csv_items(val):
        s = (val or "").strip()
        if not s:
            return []
        # Split by comma for readability; keep original if no commas
        if "," not in s:
            return [s]
        parts = [p.strip() for p in s.split(",") if p.strip()]
        return parts or [s]

    # Clinical orders
    orders = cur.execute(
        """
        SELECT * FROM clinical_orders
        WHERE visit_id=?
        ORDER BY id ASC
    """,
        (visit_id,),
    ).fetchall()

    # Nursing notes
    notes = cur.execute(
        """
        SELECT * FROM nursing_notes
        WHERE visit_id=?
        ORDER BY id ASC
    """,
        (visit_id,),
    ).fetchall()

    # Provider note (ED Note)
    provider_note = None
    try:
        provider_note = cur.execute(
            "SELECT * FROM provider_notes WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
    except Exception:
        provider_note = None

    # Lab requests/results
    try:
        lab_reqs = cur.execute(
            """
            SELECT * FROM lab_requests
            WHERE visit_id=?
            ORDER BY id ASC
        """,
            (visit_id,),
        ).fetchall()
    except Exception:
        lab_reqs = []

    # Radiology requests/reports
    try:
        rad_reqs = cur.execute(
            """
            SELECT * FROM radiology_requests
            WHERE visit_id=?
            ORDER BY id ASC
        """,
            (visit_id,),
        ).fetchall()
    except Exception:
        rad_reqs = []

    # Discharge summary (all doctor fields)
    try:
        ds = cur.execute(
            """
            SELECT *
            FROM discharge_summaries
            WHERE visit_id=?
        """,
            (visit_id,),
        ).fetchone()
    except Exception:
        ds = None

    sections = []

    # ------------------------------------------------------------
    # Visit timeline & disposition
    # ------------------------------------------------------------
    tl = []
    tl.append(
        f"- Registered: {_fmt_ts(_g(visit,'created_at'))} by {_staff_display_with_ids(cur, _g(visit,'created_by') or '-')}"
    )
    if _g(visit, "triage_time"):
        tl.append(f"- Triage: {_fmt_ts(_g(visit,'triage_time'))}")
    if _g(visit, "closed_at"):
        tl.append(
            f"- Closed/Discharged: {_fmt_ts(_g(visit,'closed_at'))} by {_staff_display_with_ids(cur, _g(visit,'closed_by') or '-')}"
        )
    tl.append(f"- Current Status: {_g(visit,'status') or '-'}")

    # Extra disposition details (LAMA / TRANSFERRED)
    try:
        st_u = (_g(visit, "status") or "").upper()
    except Exception:
        st_u = ""
    if st_u == "LAMA":
        lr = (_g(visit, "lama_reason") or "").strip()
        if lr:
            tl.append(f"- LAMA Reason: {lr}")
    if st_u == "TRANSFERRED":
        th = (_g(visit, "transfer_hospital") or "").strip()
        td = (_g(visit, "transfer_doctor") or "").strip()
        if th or td:
            tl.append(
                f"- Transferred To: {th or '-'} | Receiving Physician: {td or '-'}"
            )

    sections.append(("Visit Timeline & Disposition", "\n".join(tl).strip() or "-"))

    # ------------------------------------------------------------
    # Patient Movement / Care Area Timeline
    # ------------------------------------------------------------
    movement_lines = []
    try:
        _initial_area = _g(visit, "clinic") or "ED"
        _initial_loc = _g(visit, "registration_location") or ""
        _initial_txt = _format_order_source_text(_initial_area, _initial_loc, "") or (_initial_area or "ED")
        movement_lines.append(f"- {_fmt_ts(_g(visit,'created_at'))}: Patient registered / initial care area: {_initial_txt} | By: {_staff_display_with_ids(cur, _g(visit,'created_by') or '-')}")
    except Exception:
        pass
    try:
        _ensure_patient_location_movement_schema(cur)
        movement_rows = cur.execute(
            """
            SELECT *
            FROM patient_location_movements
            WHERE visit_id=?
            ORDER BY COALESCE(moved_at,'') ASC, id ASC
            """,
            (visit_id,),
        ).fetchall()
    except Exception as e:
        _log_noncritical_exception(f"Auto summary movement timeline failed for visit={visit_id}", e)
        movement_rows = []

    if movement_rows:
        for mv in movement_rows:
            ts = _fmt_ts(_g(mv, "moved_at"))
            by = _staff_display_with_ids(cur, _g(mv, "moved_by") or "-")
            from_txt = _format_order_source_text(_g(mv, "from_area"), _g(mv, "from_location"), _g(mv, "from_bed")) or "-"
            to_txt = _format_order_source_text(_g(mv, "to_area"), _g(mv, "to_location"), _g(mv, "to_bed")) or "-"
            st = _g(mv, "status") or "-"
            note = (_g(mv, "note") or "").strip()
            line = f"- {ts}: {from_txt} -> {to_txt} | Status: {st} | By: {by}"
            if note:
                line += f" | Note: {note}"
            movement_lines.append(line)
    current_txt = _co_current_location_text_from_visit(visit)
    movement_lines.append(f"- Current Location Now: {current_txt or '-'}")

    sections.append(("Patient Movement / Care Area Timeline", "\n".join(movement_lines).strip() or "-"))

    # ------------------------------------------------------------
    # Chief complaint (optional)
    # ------------------------------------------------------------
    if _g(visit, "comment"):
        cc_lines = [f"- {ln}" for ln in _clean_lines(_g(visit, "comment"))]
        sections.append(("Chief Complaint", "\n".join(cc_lines).strip() or "-"))

    # ------------------------------------------------------------
    # Provider Note (ED Note)
    # ------------------------------------------------------------
    if provider_note and (_g(provider_note, "note_text") or "").strip():
        sections.append(
            (
                "Provider Note (ED Note)",
                _expand_provider_note_headings(
                    (_g(provider_note, "note_text") or "").strip()
                ),
            )
        )

    # ------------------------------------------------------------
    # Triage & Vitals
    # ------------------------------------------------------------
    tri = []
    tri.append(
        f"- Triage Status: {_g(visit,'triage_status') or '-'} | CAT: {display_esi_cat(_g(visit,'triage_cat') or '-')}"
    )

    allergy_text = _g(visit, "allergy_status") or "-"
    ad = (_g(visit, "allergy_details") or "").strip()
    if ad:
        allergy_text += f" ({ad})"
    tri.append(f"- Allergy: {allergy_text}")

    tri.append(
        f"- PR: {_g(visit,'pulse_rate') or '-'} bpm, RR: {_g(visit,'resp_rate') or '-'} /min, Temp: {_g(visit,'temperature') or '-'} C"
    )
    tri.append(
        f"- BP: {_g(visit,'bp_systolic') or '-'} / {_g(visit,'bp_diastolic') or '-'} , SpO2: {_g(visit,'spo2') or '-'}%"
    )
    tri.append(
        f"- Consciousness: {_g(visit,'consciousness_level') or '-'} , Pain: {_g(visit,'pain_score') or '-'} /10"
    )
    tri.append(
        f"- Weight: {_g(visit,'weight') or '-'} kg , Height: {_g(visit,'height') or '-'} m"
    )

    sections.append(("Triage & Vital Signs", "\n".join(tri).strip() or "-"))

    try:
        serial_vitals_text = format_serial_vitals_log_text(visit_id, limit=24)
    except Exception as e:
        _log_noncritical_exception(
            f"Auto summary serial vitals formatting failed for visit={visit_id}", e
        )
        serial_vitals_text = ""
    if serial_vitals_text:
        sections.append(("Serial Vitals Log", serial_vitals_text))

    # ------------------------------------------------------------
    # Clinical Orders (timeline)
    # ------------------------------------------------------------
    co_lines = []
    if orders:
        for o in orders:
            oid = _g(o, "id") or "-"
            created_at = _fmt_ts(_g(o, "created_at"))
            created_by = _g(o, "created_by") or "-"
            co_lines.append(
                f"Order #{oid}  |  {created_at}  |  by {_staff_display_with_ids(cur, created_by)}"
            )
            src_txt = _co_resolved_source_text(o, visit)
            if src_txt:
                co_lines.append(f"  Source Location: {src_txt}")

            diag = _g(o, "diagnosis")
            if diag:
                items = _split_csv_items(diag)
                co_lines.append("  Diagnosis:")
                for it in items:
                    co_lines.append(f"    - {it}")

            ro = _g(o, "radiology_orders")
            if ro:
                items = _split_csv_items(ro)
                co_lines.append("  Radiology:")
                for it in items:
                    co_lines.append(f"    - {it}")
                rfe = (_g(o, "reason_for_exam") or "").strip()
                if rfe:
                    co_lines.append(f"    Clinical indication: {rfe}")

            lo = _g(o, "lab_orders")
            if lo:
                items = _split_csv_items(lo)
                co_lines.append("  Labs:")
                for it in items:
                    co_lines.append(f"    - {it}")

            meds = _g(o, "medications")
            if meds:
                items = _split_csv_items(meds)
                co_lines.append("  Medications:")
                for it in items:
                    co_lines.append(f"    - {it}")
                mind = (_g(o, "med_indication") or "").strip()
                if mind:
                    co_lines.append(f"    Medication indication: {mind}")

            # spacer between orders
            co_lines.append("")
    else:
        co_lines.append("- None")

    sections.append(("Clinical Orders Timeline", "\n".join(co_lines).strip() or "-"))

    # ------------------------------------------------------------
    # Lab Tests & Results
    # ------------------------------------------------------------
    lab_lines = []
    if lab_reqs:
        for l in lab_reqs:
            lid = _g(l, "id") or "-"
            test_name = _g(l, "test_name") or "-"
            status = _g(l, "status") or "-"
            line = f"Lab #{lid}  |  {test_name}  |  Status: {status}"
            src_txt = _co_resolved_source_text(l, visit)
            if src_txt:
                line += f"  |  Source: {src_txt}"
            result = (_g(l, "result_text") or "").strip()
            if result:
                line += f"  |  Result: {result}"
            lab_lines.append(line)

            details = []
            if _g(l, "requested_at"):
                details.append(
                    f"Requested: {_fmt_ts(_g(l,'requested_at'))} by {_staff_display_with_ids(cur, _g(l,'requested_by') or '-')}"
                )
            if _g(l, "collected_at"):
                details.append(
                    f"Collected: {_fmt_ts(_g(l,'collected_at'))} by {_staff_display_with_ids(cur, _g(l,'collected_by') or '-')}"
                )
            if _g(l, "received_at"):
                details.append(
                    f"Received: {_fmt_ts(_g(l,'received_at'))} by {_staff_display_with_ids(cur, _g(l,'received_by') or '-')}"
                )
            if _g(l, "in_lab_at"):
                details.append(
                    f"In Lab: {_fmt_ts(_g(l,'in_lab_at'))} by {_staff_display_with_ids(cur, _g(l,'in_lab_by') or '-')}"
                )
            if _g(l, "reported_at"):
                details.append(
                    f"Reported: {_fmt_ts(_g(l,'reported_at'))} by {_staff_display_with_ids(cur, _g(l,'reported_by') or '-')}"
                )
            if details:
                lab_lines.append("  " + " | ".join(details))

            lab_lines.append("")
    else:
        lab_lines.append("- None")

    sections.append(("Lab Tests & Results", "\n".join(lab_lines).strip() or "-"))

    # ------------------------------------------------------------
    # Radiology Studies & Reports
    # ------------------------------------------------------------
    rad_lines = []
    if rad_reqs:
        for r in rad_reqs:
            rid = _g(r, "id") or "-"
            test_name = _g(r, "test_name") or "-"
            status = _g(r, "status") or "-"
            src_txt = _co_resolved_source_text(r, visit)
            src_part = f"  |  Source: {src_txt}" if src_txt else ""
            rad_lines.append(f"Study #{rid}  |  {test_name}  |  Status: {status}{src_part}")

            details = []
            if _g(r, "requested_at"):
                details.append(
                    f"Requested: {_fmt_ts(_g(r,'requested_at'))} by {_staff_display_with_ids(cur, _g(r,'requested_by') or '-')}"
                )
            if _g(r, "done_at"):
                details.append(
                    f"Done: {_fmt_ts(_g(r,'done_at'))} by {_staff_display_with_ids(cur, _g(r,'done_by') or '-')}"
                )
            if _g(r, "reported_at"):
                details.append(
                    f"Reported: {_fmt_ts(_g(r,'reported_at'))} by {_staff_display_with_ids(cur, _g(r,'reported_by') or '-')}"
                )
            if details:
                rad_lines.append("  " + " | ".join(details))

            rep = (_g(r, "report_text") or "").strip()
            if rep:
                rad_lines.append("  Report:")
                for ln in _clean_lines(rep):
                    rad_lines.append(f"    - {ln}")

            rad_lines.append("")
    else:
        rad_lines.append("- None")

    sections.append(
        ("Radiology Studies & Reports", "\n".join(rad_lines).strip() or "-")
    )

    # ------------------------------------------------------------
    # Nursing Notes
    # ------------------------------------------------------------
    nn_lines = []
    if notes:
        for n in notes:
            ts = _fmt_ts(_g(n, "created_at"))
            by = _g(n, "created_by") or "-"
            note_txt = (_g(n, "note_text") or "").strip()
            if note_txt:
                nn_lines.append(
                    f"{ts}  |  {_staff_display_with_ids(cur, by)}: {note_txt}"
                )
            else:
                nn_lines.append(f"{ts}  |  {_staff_display_with_ids(cur, by)}: -")
        nn_lines.append("")
    else:
        nn_lines.append("- None")

    sections.append(("Nursing Notes", "\n".join(nn_lines).strip() or "-"))

    # ------------------------------------------------------------
    # Admission Orders / IP Admission (audit trail)
    # ------------------------------------------------------------
    try:
        ensure_admission_orders_schema()
    except Exception as e:
        _log_noncritical_exception(
            f"Auto summary admission schema ensure failed for visit={visit_id}", e
        )

    try:
        adm_orders = cur.execute(
            """
            SELECT *
            FROM admission_orders
            WHERE visit_id=?
            ORDER BY id ASC
            """,
            (visit_id,),
        ).fetchall()
    except Exception:
        adm_orders = []

    adm_lines = []
    if adm_orders:

        def _g2(row, key, default=""):
            try:
                v = row[key]
            except Exception:
                try:
                    v = row.get(key, default)
                except Exception:
                    v = default
            return v if v is not None else default

        for ao in adm_orders:
            ao_id = _g2(ao, "id") or "-"
            ao_status = _g2(ao, "status") or "-"
            adm_lines.append(
                f"Order #{ao_id}  |  Status: {ao_status}  |  To: {_g2(ao,'destination') or '-'}  |  Type: {_g2(ao,'admission_type') or '-'}"
            )
            adm_lines.append(
                f"  - Requested: {_fmt_ts(_g2(ao,'ref_datetime'))} by {_staff_display_with_ids(cur, _g2(ao,'ref_by') or '-')} | Under: {_doctor_display_with_gd(cur, _g2(ao,'admit_dr') or '-')}"
            )

            # Audit trail (created/updated)
            created_at = (_g2(ao, "created_at") or "").strip()
            created_by = (_g2(ao, "created_by") or "").strip()
            updated_at = (_g2(ao, "updated_at") or "").strip()
            updated_by = (_g2(ao, "updated_by") or "").strip()
            if created_at or created_by or updated_at or updated_by:
                adm_lines.append(
                    f"  - Audit: Created {_fmt_ts(created_at)} by {_staff_display_with_ids(cur, created_by or '-')} | Updated {_fmt_ts(updated_at)} by {_staff_display_with_ids(cur, updated_by or '-')}"
                )

            dx = (_g2(ao, "dx") or "").strip()
            if dx:
                adm_lines.append(f"  - Diagnosis / Reason: {dx}")

            meta = []
            for label, key in (
                ("Patient Type", "patient_type"),
                ("Medical Service", "medical_service"),
                ("Accommodation", "accommodation"),
                ("Facility", "facility"),
                ("Future Admission", "future_admission"),
                ("Isolation", "isolation"),
                ("Authorization", "authorization_status"),
            ):
                v = (_g2(ao, key) or "").strip()
                if v:
                    meta.append(f"{label}: {v}")
            if meta:
                adm_lines.append("  - " + " | ".join(meta))

            staff = []
            for label, key in (
                ("Ward", "ward"),
                ("Room No", "bed_no"),
                ("Approval No", "approval_no"),
            ):
                v = (_g2(ao, key) or "").strip()
                if v:
                    staff.append(f"{label}: {v}")
            if staff:
                adm_lines.append("  - " + " | ".join(staff))

            # Workflow notes
            ao_status_u = (ao_status or "").upper()
            if ao_status_u == "CANCELLED":
                cr = (_g2(ao, "cancel_reason") or "").strip()
                ca = (_g2(ao, "cancelled_at") or "").strip()
                cb = (_g2(ao, "cancelled_by") or "").strip()
                if cr or ca or cb:
                    adm_lines.append(
                        f"  - Cancelled: {cr or '-'} ({ca or '-'} by {_staff_display_with_ids(cur, cb or '-')})"
                    )
            elif ao_status_u == "ADMITTED":
                aa = (_g2(ao, "admitted_at") or "").strip()
                ab = (_g2(ao, "admitted_by") or "").strip()
                if aa or ab:
                    adm_lines.append(
                        f"  - Admitted: {aa or '-'} by {_staff_display_with_ids(cur, ab or '-')}"
                    )

            adm_lines.append("")
    else:
        adm_lines.append("- None")

    sections.append(
        ("Admission Orders / IP Admission", "\n".join(adm_lines).strip() or "-")
    )

    # ------------------------------------------------------------
    # Discharge Summary (Physician)
    # ------------------------------------------------------------
    ds_lines = []
    if ds:
        # audit info
        created_at = (_g(ds, "created_at") or "").strip()
        created_by = (_g(ds, "created_by") or "").strip()
        updated_at = (_g(ds, "updated_at") or "").strip()
        updated_by = (_g(ds, "updated_by") or "").strip()
        if updated_at or updated_by:
            ds_lines.append(
                f"- Last update: {_fmt_ts(updated_at)} by {_staff_display_with_ids(cur, updated_by or '-')}"
            )
        elif created_at or created_by:
            ds_lines.append(
                f"- Created: {_fmt_ts(created_at)} by {_staff_display_with_ids(cur, created_by or '-')}"
            )
        ds_lines.append("")

        def _add_block(label, val):
            val = (val or "").strip()
            if not val:
                return
            ds_lines.append(f"{label}:")
            for ln in _clean_lines(val):
                ds_lines.append(f"  - {ln}")
            ds_lines.append("")

        _add_block("Diagnosis / Chief Complaint", _g(ds, "diagnosis_cc"))
        _add_block("Review of the System", _g(ds, "review_of_system"))
        _add_block("Physical Exam", _g(ds, "physical_exam"))
        _add_block("Final Diagnosis", _g(ds, "final_diagnosis"))
        _add_block("ED / Hospital Course", _g(ds, "summary_text"))
        _add_block("Investigations Summary", _g(ds, "investigations_summary"))
        _add_block("Procedures Performed", _g(ds, "procedures_text"))

        cond = (_g(ds, "condition_on_discharge") or "").strip()
        if cond:
            ds_lines.append(f"Condition on Discharge: {cond}")
            ds_lines.append("")

        ref = (_g(ds, "referral_clinic") or "").strip()
        if ref:
            ds_lines.append(f"Referral to Clinic: {ref}")
            ds_lines.append("")
    else:
        ds_lines.append("- None")

    sections.append(
        ("Discharge Summary (Physician)", "\n".join(ds_lines).strip() or "-")
    )

    # ------------------------------------------------------------
    # Home Medication (Discharge)
    # ------------------------------------------------------------
    hm_lines = []
    hm_raw = _g(ds, "home_medication") if ds else ""
    hm_rows = parse_home_medication_rows(hm_raw)
    if hm_rows:
        for r in hm_rows:
            med = (r.get("med") or "").strip()
            dx = (r.get("dx") or "").strip()
            if med:
                hm_lines.append(f"- {med}")
            if dx:
                hm_lines.append(f"  Dx: {dx}")
            hm_lines.append("")
    else:
        hm_lines.append("- None")

    sections.append(("Home Medication (Discharge)", "\n".join(hm_lines).strip() or "-"))

    # ------------------------------------------------------------
    # Follow-up & Instructions
    # ------------------------------------------------------------
    fu_lines = []
    fu = (_g(ds, "followup_instructions") if ds else "") or ""
    if str(fu).strip():
        for ln in _clean_lines(fu):
            fu_lines.append(f"- {ln}")
    else:
        fu_lines.append("- None")
    sections.append(("Follow-up & Instructions", "\n".join(fu_lines).strip() or "-"))

    return sections


def _build_auto_summary_uncached(visit_id):
    """Backward-compatible text format used in discharge_summaries.auto_summary_text."""
    sections = build_auto_summary_sections(visit_id)
    if not sections:
        return ""

    out = []
    for title, body in sections:
        title = (title or "").strip()
        if title:
            out.append(title)
            out.append("-" * min(len(title), 50))
        body = "" if body is None else str(body)
        body = body.strip("\n")
        if body.strip():
            out.extend(body.splitlines())
        else:
            out.append("-")
        out.append("")
    return "\n".join(out).strip()


def build_auto_summary(visit_id, *, force_refresh=False, use_cache=True):
    vid = str(visit_id or "").strip()
    if not vid:
        return ""

    def _compute():
        return _build_auto_summary_uncached(vid)

    if force_refresh or not use_cache:
        text = _compute()
        try:
            ttl = max(1.0, _cfg_float_runtime("AUTO_SUMMARY_CACHE_SECONDS", 30.0))
            _AUTO_SUMMARY_CACHE.set(("auto_summary", vid), text, ttl)
        except Exception:
            pass
        return text

    try:
        ttl = max(1.0, _cfg_float_runtime("AUTO_SUMMARY_CACHE_SECONDS", 30.0))
        return _AUTO_SUMMARY_CACHE.get_or_compute(("auto_summary", vid), ttl, _compute)
    except Exception:
        return _compute()


def _refresh_auto_summary_row_inline(visit_id, actor=None, now_ts=None):
    vid = str(visit_id or "").strip()
    if not vid:
        return ""
    now_ts = now_ts or datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    auto_text = build_auto_summary(vid, force_refresh=True, use_cache=True)
    db = get_db()
    cur = db.cursor()
    exists = cur.execute(
        "SELECT id FROM discharge_summaries WHERE visit_id=? LIMIT 1",
        (vid,),
    ).fetchone()
    actor = (actor or session.get("username") or "SYSTEM").strip()
    if exists:
        db.execute(
            "UPDATE discharge_summaries SET auto_summary_text=?, updated_at=?, updated_by=? WHERE visit_id=?",
            (auto_text, now_ts, actor, vid),
        )
    else:
        db.execute(
            "INSERT INTO discharge_summaries (visit_id, auto_summary_text, created_at, created_by) VALUES (?,?,?,?)",
            (vid, auto_text, now_ts, actor),
        )
    db.commit()
    return auto_text


def refresh_auto_summary_after_write(visit_id, actor=None, prefer_async=None):
    vid = str(visit_id or "").strip()
    if not vid:
        return None
    _invalidate_visit_runtime_caches(vid)

    if prefer_async is None:
        prefer_async = _cfg_bool_runtime("AUTO_SUMMARY_ASYNC_REFRESH", True)

    def _job():
        try:
            try:
                ctx = app.app_context()
            except Exception:
                ctx = None
            if ctx is None:
                _refresh_auto_summary_row_inline(vid, actor=actor)
            else:
                with ctx:
                    _refresh_auto_summary_row_inline(vid, actor=actor)
        except Exception:
            _log_noncritical_exception(f"auto summary refresh failed for visit={vid}")

    if prefer_async:
        try:
            bg_submit(f"auto_summary_refresh_{vid}", _job)
            return None
        except Exception:
            pass

    try:
        return _refresh_auto_summary_row_inline(vid, actor=actor)
    except Exception:
        _log_noncritical_exception(f"auto summary inline refresh failed for visit={vid}")
        return None


# ------------------------------------------------------------
# Investigations summary helper (auto from Lab/Radiology Requests)
# ------------------------------------------------------------


def format_investigations_from_requests(
    lab_reqs=None, rad_reqs=None, include_pending=True, max_line_len=160
):
    """Build a concise investigations summary from lab_requests / radiology_requests rows.

    lab_reqs rows expected keys: test_name, status, result_text
    rad_reqs rows expected keys: test_name, status, report_text

    - include_pending: include non-reported statuses (REQUESTED / COLLECTED / DONE ...) in the output.
    - max_line_len: truncate long result/report texts to keep the summary readable.
    """

    def _get(r, k, default=""):
        try:
            return r[k]
        except Exception:
            try:
                return r.get(k, default)
            except Exception:
                return default

    def _clean_one_line(s):
        s = (s or "").strip()
        # Replace newlines/tabs with spaces and collapse whitespace
        s = s.replace("\r", " ").replace("\n", " ").replace("\t", " ")
        try:
            s = re.sub(r"\s+", " ", s).strip()
        except Exception:
            # In case re is not available for some reason
            s = " ".join(s.split())
        return s

    def _short(s, n):
        s = _clean_one_line(s)
        if not s:
            return ""
        if len(s) <= n:
            return s
        return s[: max(0, n - 1)].rstrip() + "…"

    lines = []
    labs = lab_reqs or []
    rads = rad_reqs or []

    if labs:
        lines.append("Labs:")
        for r in labs:
            name = _get(r, "test_name", "-") or "-"
            st = (_get(r, "status", "") or "").strip()
            st_u = st.upper()
            res = _get(r, "result_text", "")
            if st_u == "REPORTED":
                if res and str(res).strip():
                    lines.append(f"- {name}: {_short(res, max_line_len)}")
                else:
                    lines.append(f"- {name}: Reported")
            elif include_pending:
                lines.append(f"- {name}: {st or 'PENDING'}")
        lines.append("")

    if rads:
        lines.append("Radiology:")
        for r in rads:
            name = _get(r, "test_name", "-") or "-"
            st = (_get(r, "status", "") or "").strip()
            st_u = st.upper()
            rep = _get(r, "report_text", "")
            if st_u == "REPORTED":
                if rep and str(rep).strip():
                    lines.append(f"- {name}: {_short(rep, max_line_len)}")
                else:
                    lines.append(f"- {name}: Reported")
            elif include_pending:
                lines.append(f"- {name}: {st or 'PENDING'}")
        lines.append("")

    return "\n".join(lines).strip()


# ------------------------------------------------------------
# Home Medication parsing/formatting (supports legacy text + JSON)
# ------------------------------------------------------------


def parse_home_medication_rows(raw_value):
    """
    discharge_summaries.home_medication may be:
      - legacy plain text (one medicine per line)
      - JSON list: [{"med": "...", "dx": "..."}]
    Returns: list of dicts [{"med": str, "dx": str}]
    """
    s = (raw_value or "").strip()
    if not s:
        return []

    if s.strip().lower() in ("none", "-", "n/a"):
        return [{"med": "None", "dx": ""}]

    # Try JSON first
    try:
        data = json.loads(s)
        if isinstance(data, list):
            rows = []
            for item in data:
                med = ""
                dx = ""
                if isinstance(item, dict):
                    med = str(
                        item.get("med")
                        or item.get("medicine")
                        or item.get("text")
                        or ""
                    ).strip()

                    # Dx may be stored as a display string (dx/diagnosis) or name/code fields (dx_name/dx_code)
                    dx = ""
                    _dx_val = item.get("dx")
                    if isinstance(_dx_val, dict):
                        dx = diagnosis_display(_dx_val.get("name"), _dx_val.get("code"))
                    else:
                        dx = str(item.get("dx") or item.get("diagnosis") or "").strip()

                    if not dx:
                        dx_name = str(item.get("dx_name") or "").strip()
                        dx_code = str(item.get("dx_code") or "").strip()
                        if dx_name:
                            dx = diagnosis_display(dx_name, dx_code)
                elif isinstance(item, str):
                    med = item.strip()
                if med or dx:
                    rows.append({"med": med, "dx": dx})
            if rows:
                return rows
    except Exception:
        _log_noncritical_exception(
            "Home medication structured payload parse failed; fallback to plain text parser"
        )

    # Fallback: legacy plain text (one medicine per line)
    rows = []
    for line in s.splitlines():
        t = (line or "").strip()
        if t:
            rows.append({"med": t, "dx": ""})
    return rows


def format_home_medication_for_print(raw_value, default_if_empty="None"):
    """Printable multi-line string; shows Dx under each med when present."""
    rows = (
        raw_value
        if isinstance(raw_value, list)
        else parse_home_medication_rows(raw_value)
    )
    if not rows:
        return default_if_empty

    out_lines = []
    for r in rows:
        if isinstance(r, dict):
            med = (r.get("med") or "").strip()
            dx = (r.get("dx") or "").strip()
            if not dx:
                dx = diagnosis_display(r.get("dx_name"), r.get("dx_code")).strip()
        else:
            med = (str(r) if r is not None else "").strip()
            dx = ""
        if med:
            out_lines.append(med)
        if dx:
            out_lines.append(f"  Dx: {dx}")

    return ("\n".join(out_lines).strip()) or default_if_empty


def mark_medication_as_dispensed(med_id, pharmacist_name):
    """Mark one home-med line as dispensed in patient_home_meds (PostgreSQL/SQLite)."""
    db = get_db()
    cur = db.cursor()
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        mid = int(med_id)
    except (TypeError, ValueError):
        return False
    try:
        cur.execute(
            """
            UPDATE patient_home_meds
               SET dispense_status = 'Dispensed',
                   dispensed_at = ?,
                   dispensed_by = ?,
                   last_updated_at = ?
             WHERE id = ?
               AND UPPER(COALESCE(TRIM(dispense_status), 'PENDING')) IN ('PENDING', 'UPDATED')
            """,
            (now, pharmacist_name, now, mid),
        )
        db.commit()
        rc = getattr(cur, "rowcount", None)
        if rc is not None:
            try:
                return int(rc) > 0
            except Exception:
                return rc > 0
        return True
    except Exception as e:
        _log_noncritical_exception("mark_medication_as_dispensed failed", e)
        try:
            db.rollback()
        except Exception:
            pass
        return False


def _sync_patient_home_meds_for_visit(
    db, visit_id, home_medication_raw, ordered_by, hm_changed
):
    """When discharge home_medication text changes, replace patient_home_meds rows for the visit.

    Returns:
      '' — no sync (unchanged HM or empty)
      'Pending' — first-time lines for pharmacy
      'Updated' — prescription changed after a previous sync (pharmacist sees new version)
    """
    if not hm_changed:
        return ""
    visit_id = (visit_id or "").strip()
    if not visit_id:
        return ""
    cur = db.cursor()
    had_prior = False
    try:
        prev = cur.execute(
            "SELECT COUNT(*) AS c FROM patient_home_meds WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
        if prev:
            try:
                had_prior = int(dict(prev).get("c") or 0) > 0
            except Exception:
                try:
                    had_prior = int(prev[0] or 0) > 0
                except Exception:
                    had_prior = False
    except Exception:
        had_prior = False
    try:
        cur.execute("DELETE FROM patient_home_meds WHERE visit_id=?", (visit_id,))
    except Exception as e:
        _log_noncritical_exception(
            f"_sync_patient_home_meds DELETE visit={visit_id}", e
        )
        return ""
    raw = (home_medication_raw or "").strip()
    if not raw or raw.upper() == "NONE":
        return ""
    rows = parse_home_medication_rows(home_medication_raw)
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    ordered_by = (ordered_by or "").strip() or ""
    initial_status = "Updated" if had_prior else "Pending"
    inserted = 0
    for r in rows:
        if isinstance(r, dict):
            med = (r.get("med") or "").strip()
            dx = (r.get("dx") or "").strip()
            if not dx:
                dx = diagnosis_display(r.get("dx_name"), r.get("dx_code")).strip()
        else:
            med = (str(r) if r is not None else "").strip()
            dx = ""
        if (not med) and (not dx):
            continue
        if med.upper() in ("NONE", "-", "N/A") and not dx:
            continue
        med_name = med or "-"
        try:
            cur.execute(
                """
                INSERT INTO patient_home_meds (
                    visit_id, medication_name, diagnosis_related, dosage_instructions,
                    dispense_status, ordered_at, ordered_by, last_updated_at
                ) VALUES (?,?,?,?,?,?,?,?)
                """,
                (
                    visit_id,
                    med_name,
                    dx or None,
                    None,
                    initial_status,
                    now,
                    ordered_by or None,
                    now,
                ),
            )
            inserted += 1
        except Exception as e:
            _log_noncritical_exception(
                f"_sync_patient_home_meds INSERT visit={visit_id}", e
            )
    return initial_status if inserted > 0 else ""


def build_patient_short_summary(visit_id):
    """Patient-friendly summary:
    - Diagnosis
    - Referral
    - ED medications given
    - Lab results (only REPORTED)
    - Radiology results (only REPORTED)
    - Home medication
    - Follow-up instructions
    """
    db = get_db()
    cur = db.cursor()

    visit = cur.execute(
        """
        SELECT v.visit_id, p.name, p.id_number, p.insurance
        FROM visits v
        JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
    """,
        (visit_id,),
    ).fetchone()

    if not visit:
        return ""

    summary = cur.execute(
        """
        SELECT diagnosis_cc,
               final_diagnosis,
               referral_clinic,
               home_medication,
               summary_text,
               investigations_summary,
               procedures_text,
               condition_on_discharge,
               followup_instructions
        FROM discharge_summaries
        WHERE visit_id=?
    """,
        (visit_id,),
    ).fetchone()

    # ED medications from clinical orders
    orders = cur.execute(
        """
        SELECT medications
        FROM clinical_orders
        WHERE visit_id=?
    """,
        (visit_id,),
    ).fetchall()

    # Only REPORTED labs
    labs = cur.execute(
        """
        SELECT test_name, status, result_text
        FROM lab_requests
        WHERE visit_id=?
    """,
        (visit_id,),
    ).fetchall()

    # Only REPORTED radiology
    rads = cur.execute(
        """
        SELECT test_name, status, report_text
        FROM radiology_requests
        WHERE visit_id=?
    """,
        (visit_id,),
    ).fetchall()

    lines = []

    # Header
    lines.append(f"Case No: {visit_id}")
    lines.append(
        f"Patient: {visit['name']} | ID: {visit['id_number'] or '-'} | INS: {visit['insurance'] or '-'}"
    )
    lines.append("")

    # Diagnosis
    lines.append("Diagnosis:")
    if summary:
        final_dx = summary["final_diagnosis"]
        diag_cc = summary["diagnosis_cc"]
        if final_dx:
            lines.append(f" - Final: {final_dx}")
        if diag_cc:
            lines.append(f" - Chief complaint / provisional: {diag_cc}")
        if not final_dx and not diag_cc:
            lines.append(" - Not documented")
    else:
        lines.append(" - Not documented")
    lines.append("")

    # ED / Hospital course
    if summary and summary["summary_text"]:
        lines.append("ED / Hospital Course:")
        for line in summary["summary_text"].splitlines():
            line = line.strip()
            if line:
                lines.append(f" - {line}")
        lines.append("")

    # Investigations summary (doctor text)
    if summary and summary["investigations_summary"]:
        lines.append("Investigations Summary:")
        for line in summary["investigations_summary"].splitlines():
            line = line.strip()
            if line:
                lines.append(f" - {line}")
        lines.append("")

    # Procedures performed
    if summary and summary["procedures_text"]:
        lines.append("Procedures Performed:")
        for line in summary["procedures_text"].splitlines():
            line = line.strip()
            if line:
                lines.append(f" - {line}")
        lines.append("")

    # Condition on discharge
    if summary and summary["condition_on_discharge"]:
        lines.append("Condition on discharge:")
        lines.append(f" - {summary['condition_on_discharge']}")
        lines.append("")

    # Referral
    if summary and summary["referral_clinic"]:
        lines.append("Referral Clinic:")
        lines.append(f" - {summary['referral_clinic']}")
        lines.append("")

    # ED Medications
    ed_meds = []
    for o in orders:
        meds_field = o["medications"]
        if meds_field:
            for m in meds_field.split(","):
                m = m.strip()
                if m and m not in ed_meds:
                    ed_meds.append(m)

    lines.append("Medications Given in ED:")
    if ed_meds:
        for m in ed_meds:
            lines.append(f" - {m}")
    else:
        lines.append(" - None")
    lines.append("")

    # Lab Results (ONLY reported)
    reported_labs = [l for l in labs if l["status"] == "REPORTED"]
    lines.append("Lab Results:")
    if reported_labs:
        for l in reported_labs:
            result = l["result_text"] or "-"
            lines.append(f" - {l['test_name']}: {result}")
    else:
        lines.append(" - No reported results yet")
    lines.append("")

    # Radiology Results (ONLY reported)
    reported_rads = [r for r in rads if r["status"] == "REPORTED"]
    lines.append("Radiology Reports:")
    if reported_rads:
        for r in reported_rads:
            report = r["report_text"] or "-"
            lines.append(f" - {r['test_name']}: {report}")
    else:
        lines.append(" - No reported imaging yet")
    lines.append("")

    # Home medication
    lines.append("Home Medication (Pharmacy):")
    if summary and summary["home_medication"]:
        hm_rows = parse_home_medication_rows(summary["home_medication"])
        if hm_rows:
            for r in hm_rows:
                med = (r.get("med") or "").strip()
                dx = (r.get("dx") or "").strip()
                if med:
                    lines.append(f" - {med}")
                if dx:
                    lines.append(f"    Dx: {dx}")
        else:
            lines.append(" - None")
    else:
        lines.append(" - None")
    lines.append("")

    # Follow-up instructions
    if summary and summary["followup_instructions"]:
        lines.append("Follow-up & instructions:")
        for line in summary["followup_instructions"].splitlines():
            line = line.strip()
            if line:
                lines.append(f" - {line}")
        lines.append("")

    return "\n".join(lines).strip()


# ============================================================
# Clinical Orders linkage helpers
# - keep lab / radiology / eMAR data tied to the parent clinical order
# - allow safe cleanup when a Previous Clinical Order is deleted
# ============================================================


def _co_row_get(row, key, default=None):
    try:
        val = row[key]
        return default if val is None else val
    except Exception:
        try:
            val = row.get(key, default)
            return default if val is None else val
        except Exception:
            return default


def _co_split_order_items(raw_value):
    s = (raw_value or "").replace("\r", "\n")
    if not s.strip():
        return []
    out = []
    seen = set()
    for line in s.splitlines():
        for part in str(line).split(","):
            item = clean_text((part or "").strip())
            if not item:
                continue
            norm = re.sub(r"\s+", " ", item).strip().lower()
            if norm in seen:
                continue
            seen.add(norm)
            out.append(item)
    return out


def _co_norm_item_name(value):
    return re.sub(r"\s+", " ", str(value or "")).strip().lower()


def _co_parse_dt(value):
    s = str(value or "").strip()
    if not s:
        return None
    for fmt in (
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%dT%H:%M",
    ):
        try:
            return datetime.strptime(s[: len(fmt)], fmt)
        except Exception:
            continue
    return None


def _co_same_request_moment(a, b, window_seconds=180):
    sa = str(a or "").strip()
    sb = str(b or "").strip()
    if not sa or not sb:
        return False
    if sa == sb:
        return True
    da = _co_parse_dt(sa)
    dbb = _co_parse_dt(sb)
    if da and dbb:
        try:
            return abs((da - dbb).total_seconds()) <= int(window_seconds)
        except Exception:
            return False
    return sa[:16] == sb[:16]


def _co_delete_rows_by_ids(cur, table_name, ids_to_delete):
    ids = [x for x in (ids_to_delete or []) if str(x or "").strip()]
    if not ids:
        return 0
    placeholders = ",".join(["?"] * len(ids))
    cur.execute(f"DELETE FROM {table_name} WHERE id IN ({placeholders})", tuple(ids))
    return len(ids)


# ------------------------------------------------------------
# Clinical Orders Manual Entry schema repair
# ------------------------------------------------------------
# The manual-entry/reason feature needs these columns to exist before INSERT/UPDATE.
# Some deployments block generic runtime DDL via ROOTFIX, so this helper performs a
# tiny, explicit, idempotent repair for this feature only, then caches the result.
_ORDER_REASON_SCHEMA_COLUMNS = (
    ("clinical_orders", "reason_for_exam", "TEXT"),
    ("clinical_orders", "reason_for_order", "TEXT"),
    ("clinical_orders", "med_indication", "TEXT"),
    ("clinical_orders", "order_source_area", "TEXT"),
    ("clinical_orders", "order_source_location", "TEXT"),
    ("clinical_orders", "order_source_bed", "TEXT"),
    ("visits", "care_area", "TEXT"),
    ("visits", "movement_note", "TEXT"),
    ("visits", "location_updated_at", "TEXT"),
    ("visits", "location_updated_by", "TEXT"),
    ("lab_requests", "source_order_id", "INTEGER"),
    ("lab_requests", "reason_for_order", "TEXT"),
    ("lab_requests", "order_source_area", "TEXT"),
    ("lab_requests", "order_source_location", "TEXT"),
    ("lab_requests", "order_source_bed", "TEXT"),
    ("radiology_requests", "source_order_id", "INTEGER"),
    ("radiology_requests", "reason_for_exam", "TEXT"),
    ("radiology_requests", "order_source_area", "TEXT"),
    ("radiology_requests", "order_source_location", "TEXT"),
    ("radiology_requests", "order_source_bed", "TEXT"),
)
_ORDER_REASON_SCHEMA_READY = False
_ORDER_REASON_SCHEMA_LOCK = threading.Lock()


def _order_reason_cols_lower(table_name):
    table_name = str(table_name or "").strip()
    if not table_name:
        return set()

    # Prefer existing ROOTFIX column cache helpers on PostgreSQL when available.
    try:
        rootfix_cols = globals().get("_rootfix_cols_lower_20260429c")
        if callable(rootfix_cols):
            cols = rootfix_cols(table_name)
            if cols:
                return {str(c).lower() for c in cols}
    except Exception as exc:
        _log_noncritical_exception(
            f"Manual-entry schema column check via ROOTFIX failed for {table_name}",
            exc,
        )

    db = get_db()
    cur = db.cursor()
    if (DB_ENGINE or "").lower() == "postgres":
        cur.execute(
            """
            SELECT column_name
              FROM information_schema.columns
             WHERE table_schema='public'
               AND table_name=?
            """,
            (table_name,),
        )
        rows = cur.fetchall() or []
        return {str(_co_row_get(r, "column_name", "") or _co_row_get(r, 0, "")).lower() for r in rows}

    rows = cur.execute(f"PRAGMA table_info({table_name})").fetchall() or []
    cols = set()
    for r in rows:
        try:
            cols.add(str(r["name"]).lower())
        except Exception:
            try:
                cols.add(str(r[1]).lower())
            except Exception:
                continue
    return cols


def _format_missing_order_reason_columns(missing):
    return ", ".join(f"{table}.{col}" for table, col, _typ in missing)


def _ensure_order_reason_schema_columns(strict=True):
    """Ensure schema required by manual lab/radiology entry and reasons.

    This is deliberately limited to the six columns used by Clinical Orders. It
    prevents the generic "Failed to save Clinical Order" path that occurred when
    the UI posted manual entries but PostgreSQL still lacked reason_for_order.
    """
    global _ORDER_REASON_SCHEMA_READY
    if _ORDER_REASON_SCHEMA_READY:
        return True

    with _ORDER_REASON_SCHEMA_LOCK:
        if _ORDER_REASON_SCHEMA_READY:
            return True

        missing = []
        for table_name, col_name, col_type in _ORDER_REASON_SCHEMA_COLUMNS:
            cols = _order_reason_cols_lower(table_name)
            if col_name.lower() in cols:
                try:
                    _ensured_columns_cache.add((table_name.lower(), col_name.lower()))
                except Exception:
                    pass
                continue
            missing.append((table_name, col_name, col_type))

        if not missing:
            _ORDER_REASON_SCHEMA_READY = True
            return True

        db = get_db()
        cur = db.cursor()
        try:
            if (DB_ENGINE or "").lower() == "postgres":
                # Transaction-scoped advisory lock serializes this one-time schema
                # repair across Gunicorn/Waitress workers and releases on commit/rollback.
                cur.execute("SELECT pg_advisory_xact_lock(2026051001)")
                # Re-check inside the lock in case another worker repaired it first.
                locked_missing = []
                for table_name, col_name, col_type in missing:
                    cols = _order_reason_cols_lower(table_name)
                    if col_name.lower() in cols:
                        try:
                            _ensured_columns_cache.add((table_name.lower(), col_name.lower()))
                        except Exception:
                            pass
                    else:
                        locked_missing.append((table_name, col_name, col_type))

                for table_name, col_name, col_type in locked_missing:
                    cur.execute(
                        f"ALTER TABLE {table_name} ADD COLUMN IF NOT EXISTS {col_name} {col_type}"
                    )
                    try:
                        _ensured_columns_cache.add((table_name.lower(), col_name.lower()))
                    except Exception:
                        pass
            else:
                for table_name, col_name, col_type in missing:
                    cur.execute(f"ALTER TABLE {table_name} ADD COLUMN {col_name} {col_type}")
                    try:
                        _ensured_columns_cache.add((table_name.lower(), col_name.lower()))
                    except Exception:
                        pass

            db.commit()
        except Exception as exc:
            _rollback_with_logging(db, "Manual-entry order reason schema repair")
            _log_critical_exception(
                "Manual-entry order reason schema repair failed; missing=" + _format_missing_order_reason_columns(missing),
                exc,
            )
            if strict:
                raise RuntimeError(
                    "Clinical Orders schema is missing required manual-entry reason columns: "
                    + _format_missing_order_reason_columns(missing)
                ) from exc
            return False

        # Final verification: do not mark ready unless every needed column exists.
        still_missing = []
        for table_name, col_name, col_type in _ORDER_REASON_SCHEMA_COLUMNS:
            if col_name.lower() not in _order_reason_cols_lower(table_name):
                still_missing.append((table_name, col_name, col_type))
        if still_missing:
            msg = "Clinical Orders schema repair did not create: " + _format_missing_order_reason_columns(still_missing)
            _log_critical_exception(msg)
            if strict:
                raise RuntimeError(msg)
            return False

        _ORDER_REASON_SCHEMA_READY = True
        return True


_CLINICAL_ORDER_REQUEST_LINKS_READY = False
_CLINICAL_ORDER_REQUEST_LINKS_LOCK = threading.Lock()


def _ensure_clinical_order_request_links():
    global _CLINICAL_ORDER_REQUEST_LINKS_READY
    if _CLINICAL_ORDER_REQUEST_LINKS_READY:
        return
    with _CLINICAL_ORDER_REQUEST_LINKS_LOCK:
        if _CLINICAL_ORDER_REQUEST_LINKS_READY:
            return

        # Manual Entry + reason fields are hard requirements for the INSERT/UPDATE
        # statements below. Ensure them explicitly and fail early with a precise
        # logged error instead of falling through to a generic save failure.
        _ensure_order_reason_schema_columns(strict=True)

        ok = True
        for table_name, col_name, col_type in _ORDER_REASON_SCHEMA_COLUMNS:
            try:
                ensure_column(table_name, col_name, col_type, strict=True)
            except Exception as e:
                ok = False
                _log_critical_exception(
                    f"Failed to ensure {col_name} on {table_name}", e
                )
        if ok:
            _CLINICAL_ORDER_REQUEST_LINKS_READY = True



def _co_bulk_insert_requests(cur, table_name, rows):
    rows = list(rows or [])
    if not rows:
        return 0
    table = (table_name or "").strip()
    if table not in ("lab_requests", "radiology_requests"):
        raise ValueError("Unsupported request table")

    if table == "radiology_requests":
        normalized_rows = []
        for row in rows:
            base = tuple(row[:7]) if len(row) >= 7 else tuple(row[:6]) + ("",)
            src = tuple(row[7:10]) if len(row) >= 10 else ("", "", "")
            normalized_rows.append(base + src)
        rows = normalized_rows
        qmark_stmt = (
            "INSERT INTO radiology_requests "
            "(visit_id, source_order_id, test_name, status, requested_at, requested_by, reason_for_exam, order_source_area, order_source_location, order_source_bed) "
            "VALUES (?,?,?,?,?,?,?,?,?,?)"
        )
        pg_stmt = (
            "INSERT INTO radiology_requests "
            "(visit_id, source_order_id, test_name, status, requested_at, requested_by, reason_for_exam, order_source_area, order_source_location, order_source_bed) VALUES %s"
        )
    else:
        normalized_rows = []
        for row in rows:
            base = tuple(row[:7]) if len(row) >= 7 else tuple(row[:6]) + ("",)
            src = tuple(row[7:10]) if len(row) >= 10 else ("", "", "")
            normalized_rows.append(base + src)
        rows = normalized_rows
        qmark_stmt = (
            "INSERT INTO lab_requests "
            "(visit_id, source_order_id, test_name, status, requested_at, requested_by, reason_for_order, order_source_area, order_source_location, order_source_bed) "
            "VALUES (?,?,?,?,?,?,?,?,?,?)"
        )
        pg_stmt = (
            "INSERT INTO lab_requests "
            "(visit_id, source_order_id, test_name, status, requested_at, requested_by, reason_for_order, order_source_area, order_source_location, order_source_bed) VALUES %s"
        )

    if (DB_ENGINE or "").lower() != "postgres":
        cur.executemany(qmark_stmt, rows)
        return len(rows)

    extras_mod = getattr(psycopg2, "extras", None) if psycopg2 is not None else None
    execute_values = getattr(extras_mod, "execute_values", None) if extras_mod is not None else None
    if execute_values is None:
        cur.executemany(qmark_stmt, rows)
        return len(rows)

    raw_cur = cur.connection.cursor()
    try:
        try:
            raw_cur.execute("SELECT pg_catalog.set_config('search_path', 'public', true)")
        except Exception as search_path_exc:
            _log_noncritical_exception(
                "Clinical order request insert search_path setup failed",
                search_path_exc,
            )
        execute_values(raw_cur, pg_stmt, rows, page_size=128)
        return len(rows)
    finally:
        try:
            raw_cur.close()
        except Exception as close_exc:
            _log_noncritical_exception(
                "Clinical order request insert cursor close failed",
                close_exc,
            )



def _co_sync_requests_for_source(
    db,
    visit_id,
    source_order_id,
    raw_items,
    created_by,
    table_name,
    auto_commit=True,
    reason_for_exam="",
    reason_for_order="",
    order_source_area="",
    order_source_location="",
    order_source_bed="",
):
    """Keep lab/radiology request rows aligned with one clinical order update.

    - New tests are inserted as REQUESTED.
    - Removed tests are cancelled (not hard-deleted) when they are still not final.
    - Reported rows are preserved for audit/history.
    """
    if table_name not in ("lab_requests", "radiology_requests"):
        return

    _ensure_clinical_order_request_links()
    cur = db.cursor()
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    actor = (created_by or session.get("username") or "UNKNOWN").strip() or "UNKNOWN"
    reason_for_exam = clean_text(str(reason_for_exam or "").strip())[:RAD_REASON_MAX_LEN]
    reason_for_order = clean_text(str(reason_for_order or "").strip())[:LAB_REASON_MAX_LEN]
    order_source_area = clean_text(str(order_source_area or "").strip())[:40]
    order_source_location = clean_text(str(order_source_location or "").strip())[:80]
    order_source_bed = clean_text(str(order_source_bed or "").strip())[:80]
    desired_items = _co_split_order_items(raw_items)
    desired_norm = [_co_norm_item_name(x) for x in desired_items if _co_norm_item_name(x)]
    desired_set = set(desired_norm)

    try:
        rows = (
            cur.execute(
                f"SELECT id, test_name, status FROM {table_name} WHERE visit_id=? AND source_order_id=? ORDER BY id ASC",
                (visit_id, int(source_order_id)),
            ).fetchall()
            or []
        )
    except Exception as e:
        _log_critical_exception(
            f"Clinical order linked request load failed for visit={visit_id} order={source_order_id} table={table_name}",
            e,
        )
        raise

    existing_active = {}
    for r in rows:
        name = _co_norm_item_name(_co_row_get(r, "test_name", ""))
        if not name:
            continue
        status = str(_co_row_get(r, "status", "") or "").strip().upper()
        rid = _co_row_get(r, "id", None)
        existing_active.setdefault(name, []).append((rid, status))

    rows_to_insert = []
    for item in desired_items:
        key = _co_norm_item_name(item)
        if not key:
            continue
        active_rows = [x for x in existing_active.get(key, []) if x[1] != "CANCELLED"]
        if active_rows:
            continue
        if table_name == "radiology_requests":
            rows_to_insert.append(
                (visit_id, int(source_order_id), item, "REQUESTED", now, actor, reason_for_exam, order_source_area, order_source_location, order_source_bed)
            )
        else:
            rows_to_insert.append(
                (visit_id, int(source_order_id), item, "REQUESTED", now, actor, reason_for_order, order_source_area, order_source_location, order_source_bed)
            )

    if table_name == "lab_requests":
        try:
            cur.execute(
                """
                UPDATE lab_requests
                   SET reason_for_order=?
                 WHERE visit_id=?
                   AND source_order_id=?
                   AND status <> 'CANCELLED'
                   AND COALESCE(reason_for_order,'') <> ?
                """,
                (reason_for_order, visit_id, int(source_order_id), reason_for_order),
            )
        except Exception as e:
            _log_critical_exception(
                f"Clinical order linked lab reason update failed for visit={visit_id} order={source_order_id}",
                e,
            )
            raise

    if table_name == "radiology_requests":
        try:
            cur.execute(
                """
                UPDATE radiology_requests
                   SET reason_for_exam=?
                 WHERE visit_id=?
                   AND source_order_id=?
                   AND status <> 'CANCELLED'
                   AND COALESCE(reason_for_exam,'') <> ?
                """,
                (reason_for_exam, visit_id, int(source_order_id), reason_for_exam),
            )
        except Exception as e:
            _log_critical_exception(
                f"Clinical order linked radiology reason update failed for visit={visit_id} order={source_order_id}",
                e,
            )
            raise

    try:
        cur.execute(
            f"""
            UPDATE {table_name}
               SET order_source_area=?,
                   order_source_location=?,
                   order_source_bed=?
             WHERE visit_id=?
               AND source_order_id=?
               AND status <> 'CANCELLED'
            """,
            (order_source_area, order_source_location, order_source_bed, visit_id, int(source_order_id)),
        )
    except Exception as e:
        _log_noncritical_exception(
            f"Clinical order linked request source-location update failed for visit={visit_id} order={source_order_id} table={table_name}",
            e,
        )

    if rows_to_insert:
        try:
            _co_bulk_insert_requests(cur, table_name, rows_to_insert)
        except Exception as e:
            _log_critical_exception(
                f"Clinical order linked request insert failed for visit={visit_id} order={source_order_id} table={table_name}",
                e,
            )
            raise

    for name_key, row_list in existing_active.items():
        if name_key in desired_set:
            continue
        for rid, status in row_list:
            status = (status or "").upper()
            if status in ("REPORTED", "CANCELLED"):
                continue
            try:
                if table_name == "radiology_requests":
                    cur.execute(
                        "UPDATE radiology_requests SET status='CANCELLED', cancelled_at=?, cancelled_by=?, cancel_reason=? WHERE id=? AND visit_id=?",
                        (now, actor, "Removed from Clinical Order update", rid, visit_id),
                    )
                else:
                    cur.execute(
                        f"UPDATE {table_name} SET status='CANCELLED' WHERE id=? AND visit_id=?",
                        (rid, visit_id),
                    )
            except Exception as e:
                _log_noncritical_exception(
                    f"Clinical order linked request detailed cancel fallback for visit={visit_id} order={source_order_id} table={table_name} request={rid}",
                    e,
                )
                try:
                    cur.execute(
                        f"UPDATE {table_name} SET status='CANCELLED' WHERE id=? AND visit_id=?",
                        (rid, visit_id),
                    )
                except Exception as fallback_error:
                    _log_critical_exception(
                        f"Clinical order linked request cancel failed for visit={visit_id} order={source_order_id} table={table_name} request={rid}",
                        fallback_error,
                    )
                    raise

    if auto_commit:
        db.commit()


def _delete_clinical_order_related_data(db, visit_id, oid, order_row=None):
    """Delete rows that belong to one clinical order only.

    Removes linked eMAR rows plus lab/radiology requests when they can be
    attributed to the order, including legacy requests created before the
    source_order_id linkage existed.
    """
    _ensure_clinical_order_request_links()
    try:
        ensure_emar_schema()
    except Exception as e:
        _log_critical_exception(
            f"Clinical order delete preflight failed for visit={visit_id} order={oid}", e
        )
        raise

    cur = db.cursor()
    counts = {
        "lab_requests": 0,
        "radiology_requests": 0,
        "med_orders": 0,
        "medication_orders": 0,
        "med_administrations": 0,
        "medication_administrations": 0,
    }

    try:
        med_rows = (
            cur.execute(
                "SELECT id FROM med_orders WHERE visit_id=? AND source_order_id=?",
                (visit_id, int(oid)),
            ).fetchall()
            or []
        )
        med_ids = [
            str(_co_row_get(r, "id", "")).strip()
            for r in med_rows
            if str(_co_row_get(r, "id", "")).strip()
        ]
        if med_ids:
            placeholders = ",".join(["?"] * len(med_ids))
            row = cur.execute(
                f"SELECT COUNT(*) AS c FROM med_administrations WHERE visit_id=? AND med_order_id IN ({placeholders})",
                tuple([visit_id] + med_ids),
            ).fetchone()
            counts["med_administrations"] += int(_co_row_get(row, "c", 0) or 0)
            cur.execute(
                f"DELETE FROM med_administrations WHERE visit_id=? AND med_order_id IN ({placeholders})",
                tuple([visit_id] + med_ids),
            )
        row = cur.execute(
            "SELECT COUNT(*) AS c FROM med_orders WHERE visit_id=? AND source_order_id=?",
            (visit_id, int(oid)),
        ).fetchone()
        counts["med_orders"] += int(_co_row_get(row, "c", 0) or 0)
        cur.execute(
            "DELETE FROM med_orders WHERE visit_id=? AND source_order_id=?",
            (visit_id, int(oid)),
        )
    except Exception as e:
        _log_critical_exception(
            f"Clinical order delete legacy eMAR cleanup failed for visit={visit_id} order={oid}",
            e,
        )
        raise

    try:
        med2_rows = (
            cur.execute(
                "SELECT id FROM medication_orders WHERE visit_id=? AND source_order_id=?",
                (visit_id, int(oid)),
            ).fetchall()
            or []
        )
        med2_ids = [
            str(_co_row_get(r, "id", "")).strip()
            for r in med2_rows
            if str(_co_row_get(r, "id", "")).strip()
        ]
        if med2_ids:
            placeholders = ",".join(["?"] * len(med2_ids))
            row = cur.execute(
                f"SELECT COUNT(*) AS c FROM medication_administrations WHERE visit_id=? AND med_order_id IN ({placeholders})",
                tuple([visit_id] + med2_ids),
            ).fetchone()
            counts["medication_administrations"] += int(_co_row_get(row, "c", 0) or 0)
            cur.execute(
                f"DELETE FROM medication_administrations WHERE visit_id=? AND med_order_id IN ({placeholders})",
                tuple([visit_id] + med2_ids),
            )
        row = cur.execute(
            "SELECT COUNT(*) AS c FROM medication_orders WHERE visit_id=? AND source_order_id=?",
            (visit_id, int(oid)),
        ).fetchone()
        counts["medication_orders"] += int(_co_row_get(row, "c", 0) or 0)
        cur.execute(
            "DELETE FROM medication_orders WHERE visit_id=? AND source_order_id=?",
            (visit_id, int(oid)),
        )
    except Exception as e:
        _log_critical_exception(
            f"Clinical order delete primary eMAR cleanup failed for visit={visit_id} order={oid}",
            e,
        )
        raise

    for table_name, key_name in (
        ("lab_requests", "lab_requests"),
        ("radiology_requests", "radiology_requests"),
    ):
        try:
            row = cur.execute(
                f"SELECT COUNT(*) AS c FROM {table_name} WHERE visit_id=? AND source_order_id=?",
                (visit_id, int(oid)),
            ).fetchone()
            counts[key_name] += int(_co_row_get(row, "c", 0) or 0)
            cur.execute(
                f"DELETE FROM {table_name} WHERE visit_id=? AND source_order_id=?",
                (visit_id, int(oid)),
            )
        except Exception as e:
            _log_critical_exception(
                f"Clinical order delete linked request cleanup failed for visit={visit_id} order={oid} table={table_name}",
                e,
            )
            raise

    if order_row:
        order_created_at = str(_co_row_get(order_row, "created_at", "") or "").strip()
        order_created_by = (
            str(_co_row_get(order_row, "created_by", "") or "").strip().lower()
        )
        legacy_specs = (
            ("lab_requests", "lab_orders", "lab_requests"),
            ("radiology_requests", "radiology_orders", "radiology_requests"),
        )
        for table_name, order_field, count_key in legacy_specs:
            try:
                desired_items = _co_split_order_items(
                    _co_row_get(order_row, order_field, "")
                )
                desired_norm = {_co_norm_item_name(x) for x in desired_items}
                if not desired_norm:
                    continue
                rows = (
                    cur.execute(
                        f"SELECT id, test_name, requested_at, requested_by FROM {table_name} WHERE visit_id=? AND COALESCE(source_order_id, 0)=0",
                        (visit_id,),
                    ).fetchall()
                    or []
                )
                legacy_ids = []
                matched_names = set()
                for r in rows:
                    test_name = _co_norm_item_name(_co_row_get(r, "test_name", ""))
                    if (
                        not test_name
                        or test_name not in desired_norm
                        or test_name in matched_names
                    ):
                        continue
                    requested_at = _co_row_get(r, "requested_at", "")
                    requested_by = (
                        str(_co_row_get(r, "requested_by", "") or "").strip().lower()
                    )
                    ts_match = _co_same_request_moment(requested_at, order_created_at)
                    user_match = bool(
                        order_created_by
                        and requested_by
                        and requested_by == order_created_by
                    )
                    if ts_match or (
                        user_match
                        and str(requested_at or "")[:16]
                        == str(order_created_at or "")[:16]
                    ):
                        rid = _co_row_get(r, "id", None)
                        if rid is not None:
                            legacy_ids.append(rid)
                            matched_names.add(test_name)
                counts[count_key] += _co_delete_rows_by_ids(cur, table_name, legacy_ids)
            except Exception as e:
                _log_critical_exception(
                    f"Clinical order delete legacy request cleanup failed for visit={visit_id} order={oid} table={table_name}",
                    e,
                )
                raise

    return counts
