@app.route("/provider_note/<visit_id>/save", methods=["POST"])
@login_required
@role_required("doctor", "admin")
def provider_note_save(visit_id):
    note_text = clean_text(request.form.get("note_text", "").strip())
    note_text = _expand_provider_note_headings(note_text)
    db = get_db()
    cur = db.cursor()
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    user = session.get("username", "UNKNOWN")

    if DB_ENGINE == "postgres":
        db.execute(
            """
            INSERT INTO provider_notes (visit_id, note_text, created_at, created_by, updated_at, updated_by)
            VALUES (?,?,?,?,NULL,NULL)
            ON CONFLICT (visit_id) DO UPDATE
               SET note_text=EXCLUDED.note_text,
                   updated_at=EXCLUDED.created_at,
                   updated_by=EXCLUDED.created_by
            """,
            (visit_id, note_text, now, user),
        )
    else:
        exists = cur.execute(
            "SELECT id FROM provider_notes WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
        if exists:
            db.execute(
                "UPDATE provider_notes SET note_text=?, updated_at=?, updated_by=? WHERE visit_id=?",
                (note_text, now, user, visit_id),
            )
        else:
            db.execute(
                "INSERT INTO provider_notes (visit_id, note_text, created_at, created_by) VALUES (?,?,?,?)",
                (visit_id, note_text, now, user),
            )
    db.commit()
    try:
        close_db(None)
    except Exception:
        pass

    refresh_auto_summary_after_write(visit_id, actor=user, prefer_async=True)

    log_action("SAVE_PROVIDER_NOTE", visit_id=visit_id)
    flash("Provider note saved.", "success")
    return redirect(
        url_for("clinical_orders_page", visit_id=visit_id) + "#co_provider_note"
    )


@app.route("/provider_note/<visit_id>/pdf")
@login_required
def provider_note_pdf(visit_id):
    cache_key = ("provider_note_pdf", str(visit_id or "").strip())
    cache_ttl = _pdf_cache_ttl_seconds()
    try:
        if cache_ttl > 0:
            cached = _PDF_RENDER_CACHE.get(cache_key)
            if cached:
                return Response(
                    cached,
                    mimetype="application/pdf",
                    headers=_patient_pdf_headers({"visit_id": visit_id}, "ProviderNote", visit_id=visit_id),
                )
    except Exception:
        pass
    db = get_db()
    cur = db.cursor()

    visit = cur.execute(
        """
        SELECT v.visit_id, p.name, p.id_number, p.insurance, p.insurance_no
        FROM visits v JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
    """,
        (visit_id,),
    ).fetchone()

    note = None
    try:
        note = cur.execute(
            "SELECT * FROM provider_notes WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
    except Exception:
        note = None

    if not visit:
        return "Not found", 404

    # Use a Unicode-capable font when available to avoid 500 errors on non-Latin text
    u_font = _get_pdf_unicode_font_name()
    text_font = u_font or "Helvetica"

    buffer = io.BytesIO()
    c = _pdf_attach_patient_mrn_stamp(
        canvas.Canvas(buffer, pagesize=A4), visit_row=visit, visit_id=visit_id, cur=cur
    )
    width, height = A4
    y = height - 2 * cm

    c.setFont("Helvetica-Bold", 16)
    _pdf_safe_drawString(c, 2 * cm, y, "Provider Note (ED Note)")
    y -= 1 * cm

    c.setFont(text_font, 11)
    _pdf_safe_drawString(c, 2 * cm, y, f"Case No: {visit_id}", max_chars=160)
    y -= 0.7 * cm
    _pdf_safe_drawString(
        c,
        2 * cm,
        y,
        f"Patient: {visit['name']}   ID: {visit['id_number']}",
        max_chars=160,
    )
    y -= 0.7 * cm
    try:
        ins = visit["insurance"]
    except Exception:
        ins = "-"
    _pdf_safe_drawString(c, 2 * cm, y, f"Insurance: {ins or '-'}", max_chars=160)
    y -= 1 * cm

    note_text = ""
    if note:
        try:
            note_text = note["note_text"] or ""
        except Exception:
            try:
                note_text = note.get("note_text") or ""
            except Exception:
                note_text = ""

    note_text = _expand_provider_note_headings(note_text)

    if not note_text.strip():
        _pdf_safe_drawString(c, 2 * cm, y, "No provider note.", max_chars=160)
    else:
        # Metadata
        def _rowget(row, key, default="-"):
            try:
                v = row[key]
                return v if v not in (None, "") else default
            except Exception:
                try:
                    v = row.get(key)
                    return v if v not in (None, "") else default
                except Exception:
                    return default

        created_at = _rowget(note, "created_at", "-")
        created_by = _rowget(note, "created_by", "-")
        updated_at = _rowget(note, "updated_at", "-")
        updated_by = _rowget(note, "updated_by", "-")

        c.setFont(text_font, 9)
        _pdf_safe_drawString(
            c,
            2 * cm,
            y,
            f"Created: {created_at} by {_staff_display_with_ids(cur, created_by)}",
            max_chars=180,
        )
        y -= 0.45 * cm
        if (updated_at and updated_at != "-") or (updated_by and updated_by != "-"):
            _pdf_safe_drawString(
                c,
                2 * cm,
                y,
                f"Updated: {updated_at} by {_staff_display_with_ids(cur, updated_by)}",
                max_chars=180,
            )
            y -= 0.6 * cm
        else:
            y -= 0.2 * cm

        c.setFont(text_font, 10)
        for line in note_text.splitlines():
            _pdf_safe_drawString(c, 2.2 * cm, y, line, max_chars=120)
            y -= 0.4 * cm
            if y < 2 * cm:
                c.showPage()
                y = height - 2 * cm
                c.setFont(text_font, 10)

    c.setFont("Helvetica-Oblique", 8)
    _pdf_safe_drawString(c, 2 * cm, 1.2 * cm, APP_FOOTER_TEXT, max_chars=180)
    c.showPage()
    # MRD downtime addendum pages appended at end
    try:
        v_add = _mrd_fetch_visit_for_addendum(cur, visit_id) or visit
        printed_at2, reg_dt2, triage_dt2, discharge_dt2, age2 = (
            _mrd_addendum_context_from_visit(v_add)
        )
        _mrd_draw_addendum_pages(
            c,
            cur=cur,
            visit=v_add,
            visit_id=visit_id,
            age=age2,
            printed_at=printed_at2,
            reg_dt=reg_dt2,
            triage_dt=triage_dt2,
            discharge_dt=discharge_dt2,
            report_label="Provider Note",
            include_labs=False,
            include_rads=False,
            include_meds=False,
            include_discharge_snapshot=False,
            page_break_after=False,
        )
    except Exception:
        _log_noncritical_exception(
            f"Discharge PDF timeline appendix failed for visit={visit_id}"
        )

    c.save()
    buffer.seek(0)

    pdf_bytes = buffer.getvalue()
    try:
        if cache_ttl > 0:
            _PDF_RENDER_CACHE.set(cache_key, pdf_bytes, cache_ttl)
    except Exception:
        pass
    return Response(
        pdf_bytes,
        mimetype="application/pdf",
        headers=_patient_pdf_headers(visit, "ProviderNote", visit_id=visit_id),
    )


