@app.route("/radiology_request/<int:rid>/upload_images", methods=["POST"])
@login_required
@role_required("radiology", "admin")
def radiology_upload_images(rid):
    """
    Upload radiology study images (CT/MRI/US/XR) for this request.
    Supports multiple files; stored as visit attachments with a filename tag.
    """
    next_url = (
        request.form.get("next") or request.referrer or url_for("radiology_board")
    )
    files = request.files.getlist("files")
    if not files:
        flash("No files selected.", "danger")
        return redirect(next_url)

    db = get_db()
    cur = db.cursor()
    row = cur.execute("SELECT * FROM radiology_requests WHERE id=?", (rid,)).fetchone()
    if not row:
        flash("Radiology request not found.", "danger")
        return redirect(next_url)

    visit_id = row["visit_id"]

    next_url = _rad_board_return_url(next_url, visit_id, rid)
    modality = (request.form.get("modality") or "").strip().upper()
    if modality in ("", "AUTO"):
        tname = (row["test_name"] or "").lower().strip()
        tnorm = re.sub(r"\s+", " ", tname)
        modality = "OTHER"
        if re.search(r"\bmri\b", tnorm) or tnorm.startswith("mri "):
            modality = "MRI"
        elif re.search(r"\bct\b", tnorm) or tnorm.startswith("ct "):
            modality = "CT"
        elif (
            re.search(r"\bus\b", tnorm)
            or tnorm.startswith("us ")
            or tnorm.startswith("u/s")
            or "ultrasound" in tnorm
            or "sonography" in tnorm
        ):
            modality = "US"
        elif (
            "x-ray" in tnorm
            or "xray" in tnorm
            or re.search(r"\bxr\b", tnorm)
            or " cxr" in (" " + tnorm)
            or " chest x" in (" " + tnorm)
        ):
            modality = "XR"
    if modality not in ("CT", "MRI", "US", "XR", "OTHER"):
        modality = "OTHER"

    saved = 0
    stamp = datetime.now().strftime("%Y%m%d%H%M%S")
    uploader = session.get("username", "UNKNOWN")

    for f in files:
        if not f or not getattr(f, "filename", ""):
            continue
        if f.filename.strip() == "":
            continue
        if not allowed_file(f.filename):
            continue

        safe_name = secure_filename(f.filename)
        uniq = secrets.token_hex(3)
        filename = f"{visit_id}_RAD_{rid}_IMG_{modality}_{stamp}_{uniq}_{safe_name}"

        save_err = _save_attachment_with_optional_async(
            visit_id,
            f,
            filename,
            uploader,
            context="radiology_upload_images",
        )
        if save_err:
            _log_noncritical_exception(
                f"Radiology image save failed for visit={visit_id} rid={rid} file={safe_name}",
                RuntimeError(save_err),
            )
            continue
        saved += 1

    if saved:
        log_action(
            "RAD_UPLOAD_IMAGES",
            visit_id=visit_id,
            details=f"RID={rid}|COUNT={saved}|MOD={modality}",
        )
        flash(f"Uploaded {saved} image(s) successfully.", "success")
    else:
        flash("No valid images were uploaded (allowed: png/jpg/jpeg/pdf).", "warning")

    return redirect(next_url)


@app.route("/radiology_request/<int:rid>/images")
@login_required
@role_required("doctor", "nurse", "radiology", "admin")
def radiology_view_images(rid):
    """
    View uploaded images/files for a radiology request.
    """
    cur = get_db().cursor()
    rr = cur.execute(
        """
        SELECT rr.*,
               v.visit_id,
               p.name AS patient_name,
               p.mrn,
               p.id_number
        FROM radiology_requests rr
        JOIN visits v ON v.visit_id = rr.visit_id
        JOIN patients p ON p.id = v.patient_id
        WHERE rr.id=?
        """,
        (rid,),
    ).fetchone()

    if not rr:
        return "Not found", 404

    visit_id = rr["visit_id"]
    pattern = f"{visit_id}_RAD_{rid}_IMG_%"
    images = cur.execute(
        "SELECT * FROM attachments WHERE visit_id=? AND filename LIKE ? ORDER BY id DESC",
        (visit_id, pattern),
    ).fetchall()

    return render_template("radiology_images.html", rr=dict(rr), images=images)


