# ============================================================
# Radiology Board (Requests / Reports)
# ============================================================


@app.route("/radiology_board")
@login_required
def radiology_board():
    """Radiology board for viewing and updating radiology requests.

    Supports simple search by patient, ID, visit or study.
    Adds ageing (minutes since requested) + stage-age alerts + summary counters.

    PERF:
    - Adds short-TTL single-flight caching to reduce DB pool pressure under load.
    - Uses lexical timestamp ranges (requested_at stored as ISO TEXT).
    """
    status_filter = (request.args.get("status", "ALL") or "ALL").strip().upper()
    q = (request.args.get("q", "") or "").strip()
    dfrom = (request.args.get("date_from", "") or "").strip()
    dto = (request.args.get("date_to", "") or "").strip()
    danger_only = (request.args.get("danger_only") or "").strip().lower() in (
        "1",
        "true",
        "yes",
        "on",
    )

    try:
        ttl = float(APP_CONFIG.get("RADIOLOGY_BOARD_CACHE_SECONDS", 0.0) or 0.0)
    except Exception:
        ttl = 0.0

    cache_base = (
        str(status_filter or ""),
        str(q or ""),
        str(dfrom or ""),
        str(dto or ""),
        bool(danger_only),
        str(DB_ENGINE or ""),
    )

    def _date_floor(d: str) -> str:
        return f"{d} 00:00:00"

    def _date_ceil_excl(d: str) -> str:
        try:
            dt = datetime.strptime(d, "%Y-%m-%d") + timedelta(days=1)
            return dt.strftime("%Y-%m-%d 00:00:00")
        except Exception:
            return f"{d} 23:59:59"

    def _compute():
        cur = get_db().cursor()
        sql = """
            SELECT rr.*, v.visit_id, COALESCE(v.created_at,'') AS visit_created_at,
                   COALESCE(v.clinic,'ED') AS clinic,
                   COALESCE(v.care_area,'') AS care_area,
                   COALESCE(v.location,'') AS current_location,
                   COALESCE(v.bed_no,'') AS current_bed_no,
                   COALESCE(v.bed_status,'') AS current_bed_status,
                   p.name, p.mrn, p.id_number
            FROM radiology_requests rr
            JOIN visits v ON v.visit_id = rr.visit_id
            JOIN patients p ON p.id = v.patient_id
            WHERE 1=1
        """
        params = []

        # Status filter
        if status_filter == "PENDING":
            sql += " AND rr.status IN ('REQUESTED','SENT','RECEIVED','UNDER_PROCESS','DONE')"
        elif status_filter == "REPORTED":
            sql += " AND rr.status='REPORTED'"
        elif status_filter == "ALL":
            pass
        else:
            sql += " AND rr.status=?"
            params.append(status_filter)

        # Date filters based on requested_at (ISO TEXT)
        if dfrom:
            sql += " AND rr.requested_at >= ?"
            params.append(_date_floor(dfrom))
        if dto:
            sql += " AND rr.requested_at < ?"
            params.append(_date_ceil_excl(dto))

        # Text search
        if q:
            like = f"%{q}%"
            if DB_ENGINE == "postgres":
                sql += " AND (p.name ILIKE ? OR p.mrn ILIKE ? OR p.id_number ILIKE ? OR v.visit_id ILIKE ? OR rr.test_name ILIKE ?)"
            else:
                sql += " AND (p.name LIKE ? OR p.mrn LIKE ? OR p.id_number LIKE ? OR v.visit_id LIKE ? OR rr.test_name LIKE ?)"
            params.extend([like, like, like, like, like])

        # Order: pending first, oldest requested_at first
        sql += (
            " ORDER BY "
            " CASE WHEN rr.status IN ('REQUESTED','SENT','RECEIVED','UNDER_PROCESS','DONE') THEN 0 ELSE 1 END, "
            " rr.requested_at ASC, rr.id ASC"
            " LIMIT 500"
        )

        rows_raw = cur.execute(sql, params).fetchall()

        rows = []
        status_counts = {}
        modality_counts = {}
        full_by_code, code_by_label = _clinic_display_maps()
        pending_count = 0
        reported_count = 0

        seen_active_radiology_keys = set()
        for r in rows_raw or []:
            d = dict(r)
            st_probe = str(d.get("status") or "").strip().upper()
            test_key_probe = re.sub(r"\s+", " ", str(d.get("test_name") or "").strip().lower())
            source_key_probe = str(d.get("source_order_id") or "").strip()
            if source_key_probe:
                dup_key = (str(d.get("visit_id") or ""), source_key_probe, test_key_probe)
            else:
                dup_key = (str(d.get("visit_id") or ""), "LEGACY", test_key_probe)
            # Clinical order edits can leave an old CANCELLED row plus the current active row
            # for the same visit/order/study. On the board, show the current row only.
            if status_filter == "ALL" and st_probe == "CANCELLED" and dup_key in seen_active_radiology_keys:
                continue
            if st_probe and st_probe != "CANCELLED":
                seen_active_radiology_keys.add(dup_key)
            clinic_raw = str(d.get("care_area") or d.get("clinic") or "ED").strip()
            clinic_key = clinic_raw.upper()
            clinic_code = clinic_key if clinic_key in full_by_code else code_by_label.get(clinic_key, clinic_key or "ED")
            d["clinic_short"] = clinic_code or clinic_raw or "ED"
            d["clinic_display"] = full_by_code.get(clinic_code, clinic_raw or "ED")
            current_area = d.get("care_area") or d.get("clinic") or "ED"
            d["current_location_text"] = _co_source_display(current_area, d.get("current_location") or "", d.get("current_bed_no") or "")
            source_area, source_location, source_bed, source_text = _co_resolve_order_source_components(
                d,
                current_area=current_area,
                current_location=d.get("current_location") or "",
                current_bed=d.get("current_bed_no") or "",
            )
            d["order_source_area"] = source_area
            d["order_source_location"] = source_location
            d["order_source_bed"] = source_bed
            d["order_source_text"] = source_text
            d["ordered_by_display"] = d.get("requested_by") or d.get("created_by") or ""
            st = (d.get("status") or "").upper().strip()
            status_counts[st] = status_counts.get(st, 0) + 1

            if st in ("REQUESTED", "SENT", "RECEIVED", "UNDER_PROCESS", "DONE"):
                pending_count += 1
            elif st == "REPORTED":
                reported_count += 1

            # Age / TAT in minutes
            req_ts = d.get("requested_at")
            rep_ts = d.get("reported_at")
            if st == "REPORTED" and rep_ts:
                mins = calc_minutes_between(req_ts, rep_ts)
            else:
                mins = calc_minutes_between(req_ts, None)
            d["age_minutes"] = mins

            if mins is None:
                d["age_text"] = "-"
                d["age_level"] = "none"
            else:
                try:
                    mins_int = int(mins)
                except Exception:
                    mins_int = mins

                # Human readable
                if isinstance(mins_int, int) and mins_int >= 60:
                    h = mins_int // 60
                    m = mins_int % 60
                    if h >= 24:
                        days = h // 24
                        rem_h = h % 24
                        d["age_text"] = f"{days}d {rem_h}h"
                    else:
                        d["age_text"] = f"{h}h {m:02d}m"
                else:
                    d["age_text"] = f"{mins_int}m"

                # Simple coloring
                if mins_int is None:
                    level = "none"
                elif mins_int < 30:
                    level = "short"
                elif mins_int < 60:
                    level = "medium"
                elif mins_int < 120:
                    level = "long"
                else:
                    level = "verylong"
                d["age_level"] = level

            # Stage age (minutes since last workflow step)
            st_upper = st
            if st_upper == "REQUESTED":
                stage_start = d.get("requested_at")
                stage_end = None
            elif st_upper == "SENT":
                stage_start = d.get("sent_at") or d.get("requested_at")
                stage_end = None
            elif st_upper == "RECEIVED":
                stage_start = (
                    d.get("received_at") or d.get("sent_at") or d.get("requested_at")
                )
                stage_end = None
            elif st_upper in ("UNDER_PROCESS", "DONE"):
                stage_start = (
                    d.get("in_process_at")
                    or d.get("done_at")
                    or d.get("received_at")
                    or d.get("sent_at")
                    or d.get("requested_at")
                )
                stage_end = None
            elif st_upper == "REPORTED":
                stage_start = (
                    d.get("in_process_at")
                    or d.get("done_at")
                    or d.get("received_at")
                    or d.get("sent_at")
                    or d.get("requested_at")
                )
                stage_end = d.get("reported_at")
            else:
                stage_start = d.get("requested_at")
                stage_end = None

            stage_mins = calc_minutes_between(stage_start, stage_end)
            d["stage_age_minutes"] = stage_mins

            stage_text = ""
            if stage_mins is not None:
                mins_i = int(stage_mins)
                if mins_i < 60:
                    stage_text = f"{mins_i}m"
                else:
                    stage_text = f"{mins_i//60}h {mins_i%60}m"
            d["stage_age_text"] = stage_text

            # Thresholds per stage (minutes)
            warn = danger = None
            if stage_mins is not None:
                if st_upper == "REQUESTED":
                    warn, danger = 10, 20  # nurse SEND
                elif st_upper == "SENT":
                    warn, danger = 10, 20  # radiology RECEIVE
                elif st_upper == "RECEIVED":
                    warn, danger = 20, 40  # start imaging
                elif st_upper in ("UNDER_PROCESS", "DONE"):
                    warn, danger = 60, 120  # reporting delay
                else:
                    warn, danger = 60, 120

            stage_level = "ok"
            if stage_mins is not None and warn is not None and danger is not None:
                if stage_mins >= danger:
                    stage_level = "danger"
                elif stage_mins >= warn:
                    stage_level = "warning"
                else:
                    stage_level = "ok"
            d["stage_level"] = stage_level

            # Modality grouping from test_name
            tname = (d.get("test_name") or "").lower().strip()
            tnorm = re.sub(r"\s+", " ", tname)
            modality = "Other"
            if re.search(r"\bmri\b", tnorm) or tnorm.startswith("mri "):
                modality = "MRI"
            elif re.search(r"\bct\b", tnorm) or tnorm.startswith("ct "):
                modality = "CT"
            elif (
                re.search(r"\bus\b", tnorm)
                or tnorm.startswith("us ")
                or tnorm.startswith("u/s")
                or "ultrasound" in tnorm
                or "sonography" in tnorm
            ):
                modality = "US"
            elif (
                "x-ray" in tnorm
                or "xray" in tnorm
                or re.search(r"\bxr\b", tnorm)
                or " cxr" in (" " + tnorm)
                or " chest x" in (" " + tnorm)
            ):
                modality = "XR"
            d["modality"] = modality
            modality_counts[modality] = modality_counts.get(modality, 0) + 1

            if danger_only and d.get("stage_level") != "danger":
                continue

            rows.append(d)

        # Attach radiology image counts (files uploaded as ..._RAD_<rid>_IMG_<MODALITY>_...)
        image_counts = {}
        try:
            if rows:
                visit_ids = sorted(
                    {r.get("visit_id") for r in rows if r.get("visit_id")}
                )
                if visit_ids:
                    placeholders = ",".join(["?"] * len(visit_ids))
                    att_rows = cur.execute(
                        f"SELECT filename FROM attachments WHERE visit_id IN ({placeholders}) AND filename LIKE '%_RAD_%' AND filename LIKE '%_IMG_%'",
                        visit_ids,
                    ).fetchall()
                    for a in att_rows or []:
                        fn = a.get("filename") if hasattr(a, "get") else a[0]
                        if fn and "_RAD_" in fn and "_IMG_" in fn:
                            m = re.search(r"_RAD_(\d+)_IMG_", fn)
                            if m:
                                try:
                                    rid_int = int(m.group(1))
                                except Exception:
                                    continue
                                image_counts[rid_int] = image_counts.get(rid_int, 0) + 1

            for rr in rows:
                rr["image_count"] = image_counts.get(rr.get("id"), 0)
        except Exception:
            for rr in rows:
                rr["image_count"] = 0

        return {
            "rows": rows,
            "status_counts": status_counts,
            "modality_counts": modality_counts,
            "pending_count": pending_count,
            "reported_count": reported_count,
        }

    if ttl and ttl > 0:
        ctx = _RAD_BOARD_CACHE.get_or_compute(
            ("radiology_board", cache_base), ttl, _compute
        )
    else:
        ctx = _compute()

    return render_template(
        "radiology_board.html",
        rows=ctx.get("rows", []),
        status_filter=status_filter,
        q=q,
        date_from=dfrom,
        date_to=dto,
        danger_only=danger_only,
        status_counts=ctx.get("status_counts", {}),
        modality_counts=ctx.get("modality_counts", {}),
        pending_count=ctx.get("pending_count", 0),
        reported_count=ctx.get("reported_count", 0),
    )


# ------------------------------------------------------------
# API: Radiology TAT Alerts (used by Radiology Board toast)
# ------------------------------------------------------------


@app.route("/api/radiology_alerts")
@login_required
def api_radiology_alerts():
    """
    Lightweight JSON endpoint to support UI alerts on the Radiology Board.

    Returns radiology requests that are currently in a given stage LEVEL:
    - danger (default)
    - warning
    - ok

    We compute Stage Age (minutes since last workflow step) using the same
    thresholds as the board, so the front-end can alert staff before delays.
    """
    level = (request.args.get("level", "danger") or "danger").lower().strip()
    try:
        limit = int(request.args.get("limit", "50") or 50)
    except Exception:
        limit = 50
    limit = max(1, min(limit, 500))

    cur = get_db().cursor()
    # Limit the raw scan to the latest 1000 to keep it fast.
    rows = cur.execute("""
        SELECT rr.id,
               rr.visit_id,
               rr.test_name,
               rr.status,
               rr.requested_at,
               rr.sent_at,
               rr.received_at,
               rr.in_process_at,
               rr.done_at,
               rr.reported_at,
               p.name AS patient_name,
               p.id_number
        FROM radiology_requests rr
        JOIN visits v ON v.visit_id = rr.visit_id
        JOIN patients p ON p.id = v.patient_id
        WHERE rr.status IN ('REQUESTED','SENT','RECEIVED','UNDER_PROCESS','DONE')
        ORDER BY rr.requested_at ASC, rr.id ASC
        LIMIT 1000
        """).fetchall()

    items = []
    for r in rows or []:
        d = dict(r)
        st = (d.get("status") or "").upper().strip()

        # Stage start + thresholds
        stage_label = "Stage"
        warn = 60
        danger = 120

        if st == "REQUESTED":
            stage_start = d.get("requested_at")
            stage_label = "Awaiting SEND (Nursing)"
            warn, danger = 10, 20
        elif st == "SENT":
            stage_start = d.get("sent_at") or d.get("requested_at")
            stage_label = "Awaiting RECEIVED (Radiology)"
            warn, danger = 10, 20
        elif st == "RECEIVED":
            stage_start = (
                d.get("received_at") or d.get("sent_at") or d.get("requested_at")
            )
            stage_label = "Awaiting UNDER PROCESS (Imaging)"
            warn, danger = 20, 40
        elif st in ("UNDER_PROCESS", "DONE"):
            stage_start = (
                d.get("in_process_at")
                or d.get("done_at")
                or d.get("received_at")
                or d.get("sent_at")
                or d.get("requested_at")
            )
            stage_label = "Awaiting REPORT (Radiology)"
            warn, danger = 60, 120
        else:
            stage_start = d.get("requested_at")

        stage_mins = calc_minutes_between(stage_start, None)

        stage_level = "ok"
        if stage_mins is not None:
            try:
                m = int(stage_mins)
            except Exception:
                m = stage_mins
            if m >= danger:
                stage_level = "danger"
            elif m >= warn:
                stage_level = "warning"
            else:
                stage_level = "ok"

        # Filter by requested level
        if level in ("danger", "warning", "ok"):
            if stage_level != level:
                continue

        stage_text = ""
        if stage_mins is not None:
            try:
                m = int(stage_mins)
            except Exception:
                m = stage_mins
            if isinstance(m, int) and m < 60:
                stage_text = f"{m}m"
            elif isinstance(m, int):
                stage_text = f"{m//60}h {m%60}m"
            else:
                stage_text = str(m)

        items.append(
            {
                "id": d.get("id"),
                "visit_id": d.get("visit_id"),
                "patient_name": d.get("patient_name"),
                "id_number": d.get("id_number"),
                "test_name": d.get("test_name"),
                "status": st,
                "stage_label": stage_label,
                "stage_age_minutes": (
                    int(stage_mins) if stage_mins is not None else None
                ),
                "stage_age_text": stage_text,
                "warn_threshold": warn,
                "danger_threshold": danger,
                "stage_level": stage_level,
            }
        )

    # Worst first
    items.sort(key=lambda x: (x.get("stage_age_minutes") or 0), reverse=True)
    items = items[:limit]

    return jsonify(
        {
            "level": level,
            "count": len(items),
            "items": items,
            "server_time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        }
    )


@app.route("/radiology_request/<int:rid>/send", methods=["POST"])
@login_required
@role_required("nurse", "admin")
def radiology_mark_sent(rid):
    """
    Nursing handoff:
    - REQUESTED  -> SENT  (nurse hands the patient to radiology team)
    """
    db = get_db()
    cur = db.cursor()
    next_url = (
        request.form.get("next") or request.referrer or url_for("radiology_board")
    )

    row = cur.execute("SELECT * FROM radiology_requests WHERE id=?", (rid,)).fetchone()
    if not row:
        flash("Radiology request not found.", "danger")
        return redirect(next_url)

    next_url = _rad_board_return_url(next_url, row["visit_id"], rid)

    st = (row["status"] or "").upper().strip()
    if st not in ("REQUESTED", "SENT"):
        flash("Cannot mark as SENT in current status.", "warning")
        return redirect(next_url)

    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    user = session.get("username", "UNKNOWN")

    db.execute(
        """
        UPDATE radiology_requests
           SET status='SENT',
               sent_at=COALESCE(sent_at, ?),
               sent_by=COALESCE(sent_by, ?)
         WHERE id=?
        """,
        (now, user, rid),
    )
    db.commit()

    log_action(
        "RAD_SENT", visit_id=row["visit_id"], details=f"RID={rid}|{row['test_name']}"
    )
    flash("Radiology request marked as SENT.", "success")
    return redirect(next_url)


@app.route("/radiology_request/<int:rid>/receive", methods=["POST"])
@login_required
@role_required("radiology", "admin")
def radiology_mark_received(rid):
    """
    Radiology reception:
    - SENT -> RECEIVED  (radiology receives the patient / request)
    """
    db = get_db()
    cur = db.cursor()
    next_url = (
        request.form.get("next") or request.referrer or url_for("radiology_board")
    )

    row = cur.execute("SELECT * FROM radiology_requests WHERE id=?", (rid,)).fetchone()
    if not row:
        flash("Radiology request not found.", "danger")
        return redirect(next_url)

    next_url = _rad_board_return_url(next_url, row["visit_id"], rid)

    st = (row["status"] or "").upper().strip()
    role = (session.get("role") or "").lower()

    if st == "REQUESTED" and role != "admin":
        flash(
            "This request must be SENT by Nursing before it can be RECEIVED in Radiology.",
            "warning",
        )
        return redirect(next_url)

    if st not in ("SENT", "RECEIVED") and not (st == "REQUESTED" and role == "admin"):
        flash("Cannot mark as RECEIVED in current status.", "warning")
        return redirect(next_url)

    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    user = session.get("username", "UNKNOWN")

    db.execute(
        """
        UPDATE radiology_requests
           SET status='RECEIVED',
               received_at=COALESCE(received_at, ?),
               received_by=COALESCE(received_by, ?)
         WHERE id=?
        """,
        (now, user, rid),
    )
    db.commit()

    log_action(
        "RAD_RECEIVED",
        visit_id=row["visit_id"],
        details=f"RID={rid}|{row['test_name']}",
    )
    flash("Radiology request marked as RECEIVED.", "success")
    return redirect(next_url)


@app.route("/radiology_request/<int:rid>/process", methods=["POST"])
@login_required
@role_required("radiology", "admin")
def radiology_mark_under_process(rid):
    """
    Radiology workflow:
    - RECEIVED -> UNDER_PROCESS  (patient is doing imaging / imaging started)
    """
    db = get_db()
    cur = db.cursor()
    next_url = (
        request.form.get("next") or request.referrer or url_for("radiology_board")
    )

    row = cur.execute("SELECT * FROM radiology_requests WHERE id=?", (rid,)).fetchone()
    if not row:
        flash("Radiology request not found.", "danger")
        return redirect(next_url)

    next_url = _rad_board_return_url(next_url, row["visit_id"], rid)

    st = (row["status"] or "").upper().strip()
    role = (session.get("role") or "").lower()

    if st in ("REQUESTED", "SENT") and role != "admin":
        flash(
            "This request must be RECEIVED in Radiology before marking UNDER PROCESS.",
            "warning",
        )
        return redirect(next_url)

    if st not in ("RECEIVED", "UNDER_PROCESS", "DONE") and not (
        st in ("REQUESTED", "SENT") and role == "admin"
    ):
        flash("Cannot mark as UNDER PROCESS in current status.", "warning")
        return redirect(next_url)

    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    user = session.get("username", "UNKNOWN")

    db.execute(
        """
        UPDATE radiology_requests
           SET status='UNDER_PROCESS',
               in_process_at=COALESCE(in_process_at, ?),
               in_process_by=COALESCE(in_process_by, ?),
               -- Backward compatibility columns:
               done_at=COALESCE(done_at, ?),
               done_by=COALESCE(done_by, ?)
         WHERE id=?
        """,
        (now, user, now, user, rid),
    )
    db.commit()

    log_action(
        "RAD_UNDER_PROCESS",
        visit_id=row["visit_id"],
        details=f"RID={rid}|{row['test_name']}",
    )
    flash("Radiology request marked as UNDER PROCESS.", "success")
    return redirect(next_url)


@app.route("/radiology_request/<int:rid>/done", methods=["POST"])
@login_required
@role_required("radiology", "admin")
def radiology_mark_done(rid):
    """
    Backward compatible alias:
    - DONE == UNDER_PROCESS
    """
    return radiology_mark_under_process(rid)


