# ============================================================
# MRD Downtime Addendum (Auto ED Course Summary)
# ------------------------------------------------------------
# Purpose:
#   - Attribute every order/request/medication to the requesting provider
#   - Provide MRD-friendly re-entry checklists during downtime recovery
# Default:
#   Enabled (set MRD_ADDENDUM=0 to disable)
# ============================================================


def mrd_addendum_enabled() -> bool:
    """Return True if MRD addendum pages should be rendered.

    Env vars:
      - MRD_ADDENDUM=1/0 (preferred)
      - MRD_ADDENDUM_ENABLED=1/0 (legacy)
    """
    try:
        val = os.environ.get("MRD_ADDENDUM")
        if val is None:
            val = os.environ.get("MRD_ADDENDUM_ENABLED")
        if val is None:
            return True
        return str(val).strip().lower() not in ("0", "false", "no", "off")
    except Exception:
        return True


def mrd_addendum_allowed(report_key: str = "") -> bool:
    """Return True if MRD addendum pages should be rendered for this report & current user.

    Policy:
      - If MRD addendum is globally disabled (MRD_ADDENDUM=0) -> False
      - Admin and MRD roles always see the addendum (internal use)
      - Some patient-facing reports (e.g. patient copy) hide addendum unless Admin/MRD

    Env vars:
      - MRD_ADDENDUM_RESTRICTED_REPORTS: comma-separated report keys (default: patient_copy)
    """
    if not mrd_addendum_enabled():
        return False

    try:
        role = (session.get("role") or "").strip().lower()
    except Exception:
        role = ""

    if role in ("admin", "mrd"):
        return True

    rk = (report_key or "").strip().lower()

    restricted = {"patient_copy"}
    try:
        env = os.environ.get("MRD_ADDENDUM_RESTRICTED_REPORTS") or ""
        if str(env).strip():
            restricted = {s.strip().lower() for s in str(env).split(",") if s.strip()}
    except Exception:
        pass

    if rk and rk in restricted:
        return False

    return True


def _mrd_clean_one_line(s: str) -> str:
    s = "" if s is None else str(s)
    s = s.replace("\r", " ").replace("\n", " ").replace("\t", " ")
    try:
        s = re.sub(r"\s+", " ", s).strip()
    except Exception:
        s = " ".join(s.split()).strip()
    return s


def _mrd_split_items(val):
    """Split a medications/orders string into readable items.

    Handles:
      - comma separated
      - newline separated
      - mixed
    """
    s = (val or "").strip()
    if not s:
        return []
    s = s.replace("\r", "\n")
    out = []
    for ln in s.splitlines():
        ln = (ln or "").strip()
        if not ln:
            continue
        if "," in ln:
            parts = [p.strip() for p in ln.split(",") if p.strip()]
            out.extend(parts)
        else:
            out.append(ln)
    # de-dup while preserving order
    seen = set()
    dedup = []
    for x in out:
        if x in seen:
            continue
        seen.add(x)
        dedup.append(x)
    return dedup


def _mrd_row_get(row, key, default=""):
    try:
        v = row[key]
        return default if v is None else v
    except Exception:
        try:
            v = row.get(key, default)
            return default if v is None else v
        except Exception:
            return default


def _mrd_collect_addendum_data(cur, visit_id):
    """Collect data needed for MRD addendum pages (safe across sqlite/postgres)."""
    # Chief complaint / comment
    chief_complaint = ""
    try:
        r = cur.execute(
            "SELECT comment FROM visits WHERE visit_id=?", (visit_id,)
        ).fetchone()
        chief_complaint = (_mrd_row_get(r, "comment", "") or "").strip()
    except Exception:
        chief_complaint = ""

    # Clinical orders (for ED meds attribution)
    try:
        clinical_orders = cur.execute(
            "SELECT id, created_at, created_by, medications FROM clinical_orders WHERE visit_id=? ORDER BY id ASC",
            (visit_id,),
        ).fetchall()
    except Exception:
        clinical_orders = []

    # Lab requests
    try:
        lab_reqs = cur.execute(
            "SELECT id, test_name, status, requested_at, requested_by FROM lab_requests WHERE visit_id=? ORDER BY id ASC",
            (visit_id,),
        ).fetchall()
    except Exception:
        lab_reqs = []

    # Radiology requests
    try:
        rad_reqs = cur.execute(
            "SELECT id, test_name, status, requested_at, requested_by FROM radiology_requests WHERE visit_id=? ORDER BY id ASC",
            (visit_id,),
        ).fetchall()
    except Exception:
        rad_reqs = []

    # Discharge summary (snapshot + discharge meds attribution)
    try:
        ds = cur.execute(
            """
            SELECT final_diagnosis, referral_clinic, followup_instructions, home_medication,
                   created_at, created_by, updated_at, updated_by
            FROM discharge_summaries
            WHERE visit_id=?
            """,
            (visit_id,),
        ).fetchone()
    except Exception:
        ds = None

    # Build ED medications list (one row per medication item)
    ed_meds_rows = []
    for o in clinical_orders or []:
        oid = _mrd_row_get(o, "id", "") or "-"
        created_at = _mrd_row_get(o, "created_at", "")
        created_by = _mrd_row_get(o, "created_by", "")
        meds = _mrd_split_items(_mrd_row_get(o, "medications", ""))
        for m in meds:
            ed_meds_rows.append(
                {
                    "source": f"ED#{oid}",
                    "med": _mrd_clean_one_line(m),
                    "by": (created_by or "").strip(),
                    "at": (created_at or "").strip(),
                }
            )

    # Discharge medication rows (parsed)
    discharge_meds_rows = []
    if ds is not None:
        hm_raw = _mrd_row_get(ds, "home_medication", "")
        hm_rows = parse_home_medication_rows(hm_raw)
        ds_at = (
            _mrd_row_get(ds, "updated_at", "")
            or _mrd_row_get(ds, "created_at", "")
            or ""
        ).strip()
        ds_by = (
            _mrd_row_get(ds, "updated_by", "")
            or _mrd_row_get(ds, "created_by", "")
            or ""
        ).strip()
        for r in hm_rows or []:
            med = (
                (r.get("med") or "").strip()
                if isinstance(r, dict)
                else (str(r) if r is not None else "").strip()
            )
            dx = ""
            if isinstance(r, dict):
                dx = (r.get("dx") or "").strip()
            line = med
            if dx:
                line = f"{med} | Dx: {dx}"
            if line.strip():
                discharge_meds_rows.append(
                    {
                        "source": "Disch",
                        "med": _mrd_clean_one_line(line),
                        "by": ds_by,
                        "at": ds_at,
                    }
                )

    # Provider attribution summary (counts + last activity)
    prov = {}

    def _add_provider(username, key, ts, inc=1):
        u = (username or "").strip() or "-"
        d = prov.get(u)
        if not d:
            d = {"orders": 0, "labs": 0, "rads": 0, "meds": 0, "disch": 0, "last": ""}
            prov[u] = d
        if key in d:
            d[key] += int(inc or 0)
        # keep last timestamp as raw string (ISO) for sorting
        ts = (ts or "").strip()
        if ts and (not d["last"] or ts > d["last"]):
            d["last"] = ts

    # Orders + ED meds attribution
    for o in clinical_orders or []:
        _add_provider(
            _mrd_row_get(o, "created_by", ""),
            "orders",
            _mrd_row_get(o, "created_at", ""),
            1,
        )
        meds_count = len(_mrd_split_items(_mrd_row_get(o, "medications", "")))
        if meds_count:
            _add_provider(
                _mrd_row_get(o, "created_by", ""),
                "meds",
                _mrd_row_get(o, "created_at", ""),
                meds_count,
            )

    # Labs attribution
    for l in lab_reqs or []:
        _add_provider(
            _mrd_row_get(l, "requested_by", ""),
            "labs",
            _mrd_row_get(l, "requested_at", ""),
            1,
        )

    # Radiology attribution
    for r in rad_reqs or []:
        _add_provider(
            _mrd_row_get(r, "requested_by", ""),
            "rads",
            _mrd_row_get(r, "requested_at", ""),
            1,
        )

    # Discharge attribution + discharge meds
    if ds is not None:
        ds_ts = (
            _mrd_row_get(ds, "updated_at", "")
            or _mrd_row_get(ds, "created_at", "")
            or ""
        ).strip()
        ds_user = (
            _mrd_row_get(ds, "updated_by", "")
            or _mrd_row_get(ds, "created_by", "")
            or ""
        ).strip()
        if ds_user or ds_ts:
            _add_provider(ds_user, "disch", ds_ts, 1)
        if discharge_meds_rows:
            _add_provider(ds_user, "meds", ds_ts, len(discharge_meds_rows))

    # Key timestamps summary (first/last for each stream)
    def _minmax(values):
        vals = [v for v in values if v]
        if not vals:
            return ("", "")
        vals = sorted(vals)
        return (vals[0], vals[-1])

    orders_times = [_mrd_row_get(o, "created_at", "") for o in clinical_orders or []]
    labs_times = [_mrd_row_get(l, "requested_at", "") for l in lab_reqs or []]
    rads_times = [_mrd_row_get(r, "requested_at", "") for r in rad_reqs or []]
    disch_times = []
    if ds is not None:
        disch_times = [
            (
                _mrd_row_get(ds, "updated_at", "")
                or _mrd_row_get(ds, "created_at", "")
                or ""
            )
        ]

    return {
        "chief_complaint": chief_complaint,
        "clinical_orders": clinical_orders,
        "lab_reqs": lab_reqs,
        "rad_reqs": rad_reqs,
        "ds": ds,
        "ed_meds_rows": ed_meds_rows,
        "discharge_meds_rows": discharge_meds_rows,
        "providers": prov,
        "minmax_orders": _minmax([x for x in orders_times if x]),
        "minmax_labs": _minmax([x for x in labs_times if x]),
        "minmax_rads": _minmax([x for x in rads_times if x]),
        "minmax_disch": _minmax([x for x in disch_times if x]),
    }


def _mrd_draw_checkbox(c, x, y, size=9, checked=False):
    """Draw a checkbox (top-left aligned at x,y). If checked=True, draw a tick mark."""
    try:
        c.rect(x, y - size, size, size, stroke=1, fill=0)
        if checked:
            # Simple check mark (works well even at small sizes)
            try:
                prev_lw = getattr(c, "_lineWidth", 1)
            except Exception:
                prev_lw = 1
            try:
                c.setLineWidth(1.2)
            except Exception:
                pass
            # Tick coordinates inside the box
            x1 = x + (size * 0.18)
            y1 = y - (size * 0.55)
            x2 = x + (size * 0.40)
            y2 = y - (size * 0.78)
            x3 = x + (size * 0.82)
            y3 = y - (size * 0.22)
            c.line(x1, y1, x2, y2)
            c.line(x2, y2, x3, y3)
            try:
                c.setLineWidth(prev_lw)
            except Exception:
                pass
    except Exception:
        pass


def _mrd_draw_table(
    c,
    *,
    x,
    y_top,
    w,
    col_widths,
    header,
    rows,
    row_h=0.66 * cm,
    header_h=0.78 * cm,
    font_size=8.6,
    header_font_size=9.0,
    max_rows_per_page=None,
    bottom_y=1.5 * cm,
    draw_page_header_fn=None,
    wrap_cols=None,
    checkbox_cols=None,
):
    """Draw a simple grid table with optional wrapping + checkboxes.

    Improvements over the legacy drawer:
    - Better vertical alignment (prevents text sitting on top of grid lines)
    - Slightly roomier default row/header heights for readability
    - Optional text wrapping (2 lines max) for selected columns
    - Compact E/V checkbox rendering

    Args:
      - col_widths: list of floats summing to 1.0 (fractions of w)
      - header: list[str]
      - rows: list[list[str]]
      - wrap_cols: set of column indexes to wrap (2 lines max)
      - checkbox_cols: set of column indexes where value is special tokens: "EV" or "E" or "V"
    """
    wrap_cols = set(wrap_cols or [])
    checkbox_cols = set(checkbox_cols or [])

    # Thin grid lines look cleaner + reduce "underline" effect under text
    try:
        c.setLineWidth(0.6)
    except Exception:
        pass

    # Compute absolute widths
    abs_ws = [w * float(fr) for fr in col_widths]
    try:
        assert abs(sum(abs_ws) - w) < 2.0, "Column widths must sum ~ to total width"
    except Exception:
        pass

    # Padding (points)
    pad_x = 3.5
    pad_top = 4.6
    pad_bottom = 3.8
    line_step = max(11.0, font_size + 3.4)

    def _wrap(text, col_w, max_lines=2):
        t = _mrd_clean_one_line(text or "")
        if not t:
            return [""]
        # Rough chars-per-line estimation; 5.2 is empirical for Helvetica 8-9
        max_chars = max(10, int(col_w / (font_size * 0.52)))
        lines = textwrap.wrap(t, max_chars) or [t]
        if len(lines) > max_lines:
            last = lines[max_lines - 1]
            if len(last) > 1:
                last = last[: max(1, len(last) - 1)].rstrip() + "…"
            lines = lines[: max_lines - 1] + [last]
        return lines

    def _header_baseline(y):
        # Center-ish baseline for header text (prevents overlap with bottom grid line)
        return (y - header_h) + (header_h - header_font_size) / 2.0 + 1.6

    def _draw_header_row(y):
        c.setStrokeColor(colors.black)
        c.setFillColor(colors.HexColor("#f2f2f2"))
        c.rect(x, y - header_h, w, header_h, stroke=1, fill=1)

        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", header_font_size)

        cy = _header_baseline(y)
        cx = x
        for i, title in enumerate(header):
            cw = abs_ws[i]
            c.rect(cx, y - header_h, cw, header_h, stroke=1, fill=0)
            c.drawString(cx + pad_x, cy, _mrd_clean_one_line(title)[:80])
            cx += cw
        return y - header_h

    y = y_top
    y = _draw_header_row(y)
    y -= 3

    c.setFont("Helvetica", font_size)
    c.setFillColor(colors.black)

    for row in rows or []:
        # Page break check (use a conservative minimum height)
        if (y - row_h) < bottom_y and draw_page_header_fn:
            c.showPage()
            draw_page_header_fn()
            y = y_top
            y = _draw_header_row(y)
            y -= 3
            c.setFont("Helvetica", font_size)
            c.setFillColor(colors.black)

        # Prepare wrapped content per cell
        wrapped_cells = []
        max_lines = 1
        for ci, cell in enumerate(row):
            cw = abs_ws[ci]
            if ci in checkbox_cols:
                wrapped = [cell]
            elif ci in wrap_cols:
                wrapped = _wrap(cell, cw, max_lines=2)
            else:
                wrapped = [_mrd_clean_one_line(cell)]
            wrapped_cells.append(wrapped)
            max_lines = max(max_lines, len(wrapped))

        # Dynamic row height for wrapped text
        effective_h = row_h
        if max_lines >= 2:
            # Provide enough room for the 2 lines with padding
            effective_h = max(
                row_h * 1.9, pad_top + pad_bottom + (max_lines * line_step) - 2
            )

        # If not enough space, page break (if allowed)
        if (y - effective_h) < bottom_y and draw_page_header_fn:
            c.showPage()
            draw_page_header_fn()
            y = y_top
            y = _draw_header_row(y)
            y -= 3
            c.setFont("Helvetica", font_size)
            c.setFillColor(colors.black)

        # Row outer border
        c.setFillColor(colors.black)
        c.rect(x, y - effective_h, w, effective_h, stroke=1, fill=0)

        cx = x
        for ci, cell_lines in enumerate(wrapped_cells):
            cw = abs_ws[ci]
            c.rect(cx, y - effective_h, cw, effective_h, stroke=1, fill=0)

            if ci in checkbox_cols:
                token = (cell_lines[0] or "").strip().upper()

                box = 8
                # Center the checkbox vertically in the cell
                top_y = y - (effective_h - box) / 2.0
                start_x = cx + pad_x

                # Entered (E) / Verified (V)  (supports checked markers like E1/V1)
                token_u = token  # already uppercased
                checked_e = (
                    ("E1" in token_u)
                    or ("E✓" in token_u)
                    or ("E✔" in token_u)
                    or ("E[X]" in token_u)
                )
                checked_v = (
                    ("V1" in token_u)
                    or ("V✓" in token_u)
                    or ("V✔" in token_u)
                    or ("V[X]" in token_u)
                )

                if "E" in token_u:
                    _mrd_draw_checkbox(c, start_x, top_y, size=box, checked=checked_e)
                    c.setFont("Helvetica-Bold", max(7.5, font_size - 0.8))
                    c.drawString(start_x + box + 2, top_y - box + 2, "E")

                if "V" in token_u:
                    vx = start_x + (box + 18)
                    _mrd_draw_checkbox(c, vx, top_y, size=box, checked=checked_v)
                    c.setFont("Helvetica-Bold", max(7.5, font_size - 0.8))
                    c.drawString(vx + box + 2, top_y - box + 2, "V")

                c.setFont("Helvetica", font_size)
                continue
            else:
                c.setFillColor(colors.black)

                # Single line: vertically centered baseline (prevents sitting on grid lines)
                if len(cell_lines) <= 1:
                    ln = (cell_lines[0] if cell_lines else "") or ""
                    if ln:
                        baseline = y - (effective_h + font_size) / 2.0 + 1.2
                        # Clamp inside padding
                        min_b = (y - effective_h) + pad_bottom + 1.0
                        max_b = y - pad_top - 1.0
                        baseline = max(min_b, min(max_b, baseline))
                        c.drawString(cx + pad_x, baseline, ln[:200])
                else:
                    # Multi-line: top aligned with padding
                    baseline0 = y - pad_top - font_size
                    for li, ln in enumerate(cell_lines):
                        if not ln:
                            continue
                        by = baseline0 - (li * line_step)
                        if by < ((y - effective_h) + pad_bottom):
                            break
                        c.drawString(cx + pad_x, by, ln[:200])

            cx += cw

        y -= effective_h

    return y


def _mrd_fetch_visit_for_addendum(cur, visit_id):
    """Fetch a complete visit+patient row for MRD addendum rendering.

    This helper is intentionally small and safe: if anything fails, it returns None.
    """
    try:
        return cur.execute(
            """
            SELECT v.visit_id,
                   v.status,
                   v.created_at,
                   v.triage_time,
                   v.closed_at,
                   v.created_by,
                   v.closed_by,
                   p.name,
                   p.id_number,
                   p.phone,
                   p.dob,
                   p.sex,
                   p.nationality,
                   p.insurance,
                   p.insurance_no
            FROM visits v
            JOIN patients p ON p.id=v.patient_id
            WHERE v.visit_id=?
            """,
            (visit_id,),
        ).fetchone()
    except Exception:
        return None


def _mrd_addendum_context_from_visit(visit):
    """Compute standard timestamps for the MRD addendum from any visit-like row.

    Returns: (printed_at, reg_dt, triage_dt, discharge_dt, age)
    """
    try:
        printed_at = now_display_str("%Y-%m-%d %H:%M")
    except Exception:
        try:
            printed_at = datetime.now().strftime("%Y-%m-%d %H:%M")
        except Exception:
            printed_at = ""

    # Try common field aliases (some reports use visit_created_at / visit_closed_at).
    reg_raw = (
        _mrd_row_get(visit, "created_at", "")
        or _mrd_row_get(visit, "visit_created_at", "")
        or _mrd_row_get(visit, "visit_created_at", "")
        or ""
    )
    triage_raw = (
        _mrd_row_get(visit, "triage_time", "")
        or _mrd_row_get(visit, "triage_time", "")
        or ""
    )
    disch_raw = (
        _mrd_row_get(visit, "closed_at", "")
        or _mrd_row_get(visit, "visit_closed_at", "")
        or _mrd_row_get(visit, "visit_closed_at", "")
        or ""
    )

    try:
        reg_dt = format_dt_local(reg_raw) or (str(reg_raw) if reg_raw else "")
    except Exception:
        reg_dt = str(reg_raw) if reg_raw else ""

    try:
        triage_dt = format_dt_local(triage_raw) or (
            str(triage_raw) if triage_raw else ""
        )
    except Exception:
        triage_dt = str(triage_raw) if triage_raw else ""

    try:
        discharge_dt = format_dt_local(disch_raw) or (
            str(disch_raw) if disch_raw else ""
        )
    except Exception:
        discharge_dt = str(disch_raw) if disch_raw else ""

    age = None
    try:
        dob = _mrd_row_get(visit, "dob", "")
        if dob:
            age = calc_age(dob)
    except Exception:
        age = None

    return printed_at, reg_dt, triage_dt, discharge_dt, age


def _mrd_draw_addendum_pages(
    c,
    *,
    cur,
    visit,
    visit_id,
    age=None,
    printed_at=None,
    reg_dt="",
    triage_dt="",
    discharge_dt="",
    report_label="report",
    include_labs=True,
    include_rads=True,
    include_meds=True,
    include_discharge_snapshot=True,
    page_break_after=True,
):
    """Render MRD addendum pages onto the provided reportlab canvas.

    Adds supplement pages:
      - S1: Snapshot + Provider attribution + Key timestamps  (always)
      - S2: Labs re-entry checklist                           (optional)
      - S3: Radiology checklist / Medications checklist / Discharge snapshot (optional)

    Then leaves the canvas ready for the original report pages.
    """
    if not mrd_addendum_enabled():
        return

    width, height = A4
    ml = 1.3 * cm
    mr = 1.3 * cm
    mt = 1.2 * cm
    mb = 1.2 * cm
    usable_w = width - ml - mr

    data = _mrd_collect_addendum_data(cur, visit_id)

    # MRD re-entry marks (so PDF checkboxes reflect what was Entered/Verified in the system)
    mrd_marks = {}
    try:
        ensure_mrd_reentry_schema()
        mrd_marks = mrd_get_marks_for_visit(cur, visit_id) or {}
    except Exception:
        mrd_marks = {}

    def _ev_token(key: str) -> str:
        mk = mrd_marks.get(key) or {}
        e = 1 if mk.get("entered_at") else 0
        v = 1 if mk.get("verified_at") else 0
        return f"E{e}V{v}"

    report_label = (report_label or "report").strip() or "report"
    if len(report_label) > 70:
        report_label = report_label[:67].rstrip() + "…"

    def _s(v, default="-"):
        if v is None:
            return default
        t = str(v).strip()
        return t if t else default

    def _draw_signoff_line():
        c.setFont("Helvetica-Bold", 9)
        c.drawString(
            ml,
            mb + 34,
            "MRD sign-off: Entered by ____________  Date/Time ____________  Verified by ____________",
        )

    def _addendum_header(supplement_code, subtitle=None):
        c.setFont("Helvetica-Bold", 16)
        c.setFillColor(colors.black)
        c.drawString(ml, height - mt, "MRD Downtime Addendum")

        c.setFont("Helvetica", 10)
        c.drawRightString(ml + usable_w, height - mt + 2, f"Case No: {_s(visit_id)}")
        c.drawRightString(
            ml + usable_w, height - mt - 12, f"Supplement: {supplement_code}"
        )

        c.setFont("Helvetica", 8.8)
        c.drawString(
            ml,
            height - mt - 18,
            f"For downtime/re-entry use. Original {report_label} pages included unchanged.",
        )

        # Patient line
        pat_line = (
            f"Patient: {_s(_mrd_row_get(visit,'name','-'))}    "
            f"ID: {_s(_mrd_row_get(visit,'id_number','-'))}    "
            f"INS: {_s(_mrd_row_get(visit,'insurance','-'))} (No: {_s(_mrd_row_get(visit,'insurance_no','-'))})"
        )
        c.setFont("Helvetica", 9.2)
        c.drawString(ml, height - mt - 34, pat_line[:140])

        if subtitle:
            c.setFont("Helvetica-Bold", 10)
            c.drawString(ml, height - mt - 50, subtitle)

        return height - mt - 60  # y start below header block (extra breathing room)

    def _kv_box(y_top, rows, title="Quick snapshot"):
        """Key/value snapshot box with comfortable spacing (readable in PDF viewers).

        Notes:
        - Uses generous padding + leading to avoid any overlap with the box borders.
        - Wraps long lines safely.
        """
        x = ml
        w = usable_w

        bar_h = 0.62 * cm
        font_size = 9.2
        leading = 14.8  # points (line spacing)
        pad_left = 10
        pad_top = 12
        pad_bottom = 10
        max_wrap = 118

        wrapped_lines = []
        for ln in rows or []:
            ln = _mrd_clean_one_line(ln)
            for wln in textwrap.wrap(ln, max_wrap) or ["-"]:
                wrapped_lines.append(wln)

        if not wrapped_lines:
            wrapped_lines = ["-"]

        content_h = pad_top + pad_bottom + (len(wrapped_lines) * leading)
        total_h = bar_h + content_h

        # Minimum height for consistent look
        min_total_h = 4.2 * cm
        if total_h < min_total_h:
            total_h = min_total_h

        y0 = y_top
        y_bottom = y0 - total_h

        # Outer border
        c.setStrokeColor(colors.black)
        c.setFillColor(colors.white)
        c.rect(x, y_bottom, w, total_h, stroke=1, fill=0)

        # Title bar
        c.setFillColor(colors.HexColor("#f2f2f2"))
        c.rect(x, y0 - bar_h, w, bar_h, stroke=1, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 10)
        c.drawString(x + 6, y0 - bar_h + 4, title)

        # Content
        c.setFillColor(colors.black)
        c.setFont("Helvetica", font_size)

        ty = y0 - bar_h - pad_top  # baseline for first line
        min_ty = y_bottom + pad_bottom
        for ln in wrapped_lines:
            if ty < min_ty:
                break
            c.drawString(x + pad_left, ty, ln[:220])
            ty -= leading

        return y_bottom - 18

    # --------------------------------------------------------
    # S1: Provider Attribution Summary + Key Timestamps
    # --------------------------------------------------------
    y = _addendum_header("S1")
    primary_doc = _doctor_display_with_gd(
        cur, _resolve_doctor_name_for_visit(cur, visit, visit_id)
    )
    snapshot = [
        f"Primary physician: {primary_doc}",
        f"Status: {_s(_mrd_row_get(visit,'status','-'))}",
        f"Registered: {_s(reg_dt)} by {_staff_display_with_ids(cur, _mrd_row_get(visit,'created_by','-'))}",
        f"Triage: {_s(triage_dt)} by {_staff_display_with_ids(cur, _latest_activity_username(cur, visit_id, 'TRIAGE_UPDATE') or (_mrd_row_get(visit,'created_by','-')))}",
        f"Discharge: {_s(discharge_dt)} by {_staff_display_with_ids(cur, _mrd_row_get(visit,'closed_by','-'))}",
        f"Chief complaint: {(_mrd_clean_one_line(data.get('chief_complaint') or '-') or '-')}",
    ]
    y = _kv_box(y, snapshot)

    # Providers table
    prov = data.get("providers") or {}
    prov_rows = []
    for uname, d in prov.items():
        disp = _staff_display_with_ids(cur, uname, default="-")
        prov_rows.append(
            [
                disp,
                str(d.get("orders", 0)),
                str(d.get("labs", 0)),
                str(d.get("rads", 0)),
                str(d.get("meds", 0)),
                format_dt_local(d.get("last", "")) or "-",
            ]
        )

    prov_rows = sorted(
        prov_rows,
        key=lambda r: (r[5] != "-", r[5]),
        reverse=True,
    )

    c.setFont("Helvetica-Bold", 10)
    c.drawString(ml, y, "Provider attribution summary")
    y -= 16

    y = _mrd_draw_table(
        c,
        x=ml,
        y_top=y,
        w=usable_w,
        col_widths=[0.44, 0.10, 0.10, 0.10, 0.10, 0.16],
        header=["Provider", "Orders", "Labs", "Rads", "Meds", "Last activity"],
        rows=prov_rows if prov_rows else [["-", "0", "0", "0", "0", "-"]],
        row_h=0.78 * cm,
        header_h=0.90 * cm,
        font_size=8.7,
        wrap_cols={0},
        bottom_y=mb + 2.6 * cm,
        draw_page_header_fn=lambda: _addendum_header("S1 (cont.)"),
    )

    # Key timestamps
    def _fmt_pair(label, pair):
        a, b = pair
        a2 = format_dt_local(a) or "-"
        b2 = format_dt_local(b) or "-"
        if a2 == "-" and b2 == "-":
            return f"- {label}: -"
        if a2 == b2:
            return f"- {label}: {a2}"
        return f"- {label}: {a2} → {b2}"

    key_lines = [
        _fmt_pair("Orders (first→last)", data.get("minmax_orders") or ("", "")),
        _fmt_pair("Labs requested (first→last)", data.get("minmax_labs") or ("", "")),
        _fmt_pair(
            "Radiology requested (first→last)", data.get("minmax_rads") or ("", "")
        ),
        _fmt_pair(
            "Discharge updated (first→last)", data.get("minmax_disch") or ("", "")
        ),
    ]
    # Ensure enough room for timestamps + explanatory note near the footer.
    if y < (mb + 5.6 * cm):
        c.showPage()
        y = _addendum_header("S1 (cont.)")

    # Extra breathing room between provider table and key timestamps.
    y -= 8
    c.setFont("Helvetica-Bold", 10)
    c.drawString(ml, y - 6, "Key timestamps")
    c.setFont("Helvetica", 9.2)
    ty = y - 30
    for ln in key_lines:
        c.drawString(ml + 12, ty, ln[:220])
        ty -= 18

    c.setFont("Helvetica-Oblique", 8)
    note = (
        "This addendum groups and labels each item by its requesting provider. "
        "Duplicate tests appear as separate rows (different timestamps/owners) "
        "to prevent overwriting."
    )
    note_lines = textwrap.wrap(note, width=120) or [note]
    note_y = mb + 30
    for i, ln in enumerate(note_lines):
        c.drawString(ml, note_y - (i * 10), ln[:220])

    # If S1 is the only rendered supplement, place sign-off on S1
    if (not include_labs) and (
        not (include_rads or include_meds or include_discharge_snapshot)
    ):
        _draw_signoff_line()

    if (
        include_labs
        or (include_rads or include_meds or include_discharge_snapshot)
        or page_break_after
    ):
        c.showPage()

    # --------------------------------------------------------
    # S2: Labs re-entry checklist (optional)
    # --------------------------------------------------------
    if include_labs:
        y = _addendum_header("S2", subtitle="MRD Re-entry checklist")
        c.setFont("Helvetica", 9)
        c.drawString(
            ml,
            y,
            "Mark each item as entered into the HIS/EMR during downtime recovery.",
        )
        y -= 18

        c.setFont("Helvetica-Bold", 10)
        c.drawString(ml, y, "Lab orders")
        y -= 16

        lab_rows = []
        for l in data.get("lab_reqs") or []:
            _lid = str(_mrd_row_get(l, "id", "-") or "-")
            lab_rows.append(
                [
                    _lid,
                    _mrd_row_get(l, "test_name", "-") or "-",
                    _staff_display_with_ids(
                        cur, _mrd_row_get(l, "requested_by", "-") or "-", default="-"
                    ),
                    format_dt_local(_mrd_row_get(l, "requested_at", "")) or "-",
                    _ev_token(f"lab_request:{_lid}"),
                    "",
                ]
            )
        if not lab_rows:
            lab_rows = [["-", "-", "-", "-", "E0V0", ""]]

        def _s2_header():
            _addendum_header("S2 (cont.)", subtitle="MRD Re-entry checklist")
            c.setFont("Helvetica-Bold", 10)
            c.drawString(ml, height - mt - 72, "Lab orders")

        y = _mrd_draw_table(
            c,
            x=ml,
            y_top=y,
            w=usable_w,
            col_widths=[0.07, 0.30, 0.23, 0.14, 0.14, 0.12],
            header=["Lab #", "Test", "Requested by", "Requested at", "MRD", "Remarks"],
            rows=lab_rows,
            row_h=0.76 * cm,
            header_h=0.90 * cm,
            font_size=8.6,
            wrap_cols={1, 2},
            checkbox_cols={4},
            bottom_y=mb + 2.4 * cm,
            draw_page_header_fn=_s2_header,
        )

        # If we are not rendering S3, place sign-off on S2
        if not (include_rads or include_meds or include_discharge_snapshot):
            _draw_signoff_line()

        if (
            include_rads or include_meds or include_discharge_snapshot
        ) or page_break_after:
            c.showPage()

    # --------------------------------------------------------
    # S3: Radiology + Medications + Discharge snapshot (optional)
    # --------------------------------------------------------
    if include_rads or include_meds or include_discharge_snapshot:
        y = _addendum_header("S3")

        # ---------------- Radiology ----------------
        if include_rads:
            c.setFont("Helvetica-Bold", 10)
            c.drawString(ml, y, "Radiology orders")
            y -= 16

            rad_rows = []
            for r in data.get("rad_reqs") or []:
                _rid = str(_mrd_row_get(r, "id", "-") or "-")
                rad_rows.append(
                    [
                        _rid,
                        _mrd_row_get(r, "test_name", "-") or "-",
                        _staff_display_with_ids(
                            cur,
                            _mrd_row_get(r, "requested_by", "-") or "-",
                            default="-",
                        ),
                        format_dt_local(_mrd_row_get(r, "requested_at", "")) or "-",
                        _ev_token(f"radiology_request:{_rid}"),
                        "",
                    ]
                )
            if not rad_rows:
                rad_rows = [["-", "-", "-", "-", "E0V0", ""]]

            def _s3_rad_header():
                _addendum_header("S3 (cont.)")
                c.setFont("Helvetica-Bold", 10)
                c.drawString(ml, height - mt - 72, "Radiology orders")

            # Leave room if meds/snapshot are also included; otherwise use the full page.
            bottom_y_rad = mb + (
                5.8 * cm if (include_meds or include_discharge_snapshot) else 2.4 * cm
            )

            y = _mrd_draw_table(
                c,
                x=ml,
                y_top=y,
                w=usable_w,
                col_widths=[0.08, 0.33, 0.22, 0.14, 0.14, 0.09],
                header=[
                    "Study #",
                    "Study",
                    "Requested by",
                    "Requested at",
                    "MRD",
                    "Notes",
                ],
                rows=rad_rows,
                row_h=0.76 * cm,
                header_h=0.90 * cm,
                font_size=8.6,
                wrap_cols={1, 2},
                checkbox_cols={4},
                bottom_y=bottom_y_rad,
                draw_page_header_fn=_s3_rad_header,
            )

        # ---------------- Medications ----------------
        if include_meds:
            # Add spacing and handle tight page space
            if y < (mb + 7.0 * cm):
                c.showPage()
                _addendum_header("S3 (cont.)")
                y = height - mt - 56

            c.setFont("Helvetica-Bold", 10)
            c.drawString(ml, y - 6, "Medication re-entry (ED & Discharge)")
            y -= 22

            med_rows = []
            for m in data.get("ed_meds_rows") or []:
                med_rows.append(
                    [
                        m.get("source", "-"),
                        m.get("med", "-"),
                        _staff_display_with_ids(cur, m.get("by", "-"), default="-"),
                        format_dt_local(m.get("at", "")) or "-",
                        "EV",
                    ]
                )
            for m in data.get("discharge_meds_rows") or []:
                med_rows.append(
                    [
                        m.get("source", "Disch"),
                        m.get("med", "-"),
                        _staff_display_with_ids(cur, m.get("by", "-"), default="-"),
                        format_dt_local(m.get("at", "")) or "-",
                        "EV",
                    ]
                )
            if not med_rows:
                med_rows = [["-", "-", "-", "-", "EV"]]

            def _s3_med_header():
                _addendum_header("S3 (cont.)")
                c.setFont("Helvetica-Bold", 10)
                c.drawString(
                    ml, height - mt - 72, "Medication re-entry (ED & Discharge)"
                )

            bottom_y_med = mb + (3.0 * cm if include_discharge_snapshot else 2.4 * cm)

            y = _mrd_draw_table(
                c,
                x=ml,
                y_top=y,
                w=usable_w,
                col_widths=[0.09, 0.44, 0.23, 0.14, 0.10],
                header=["Src", "Medication", "Ordered by", "Ordered at", "MRD"],
                rows=med_rows,
                row_h=0.74 * cm,
                header_h=0.88 * cm,
                font_size=8.4,
                wrap_cols={1, 2},
                checkbox_cols={4},
                bottom_y=bottom_y_med,
                draw_page_header_fn=_s3_med_header,
            )

        # ---------------- Discharge snapshot ----------------
        if include_discharge_snapshot:
            ds = data.get("ds")
            snap_lines = []
            if ds is not None:
                ds_ts = (
                    _mrd_row_get(ds, "updated_at", "")
                    or _mrd_row_get(ds, "created_at", "")
                    or ""
                ).strip()
                ds_by = (
                    _mrd_row_get(ds, "updated_by", "")
                    or _mrd_row_get(ds, "created_by", "")
                    or ""
                ).strip()
                if ds_ts or ds_by:
                    snap_lines.append(
                        f"Last update: {format_dt_local(ds_ts) or '-'} by {_staff_display_with_ids(cur, ds_by or '-', default='-')}"
                    )
                fd = (_mrd_row_get(ds, "final_diagnosis", "") or "").strip()
                if fd:
                    snap_lines.append(f"Final diagnosis: {_mrd_clean_one_line(fd)}")
                ref = (_mrd_row_get(ds, "referral_clinic", "") or "").strip()
                if ref:
                    snap_lines.append(f"Referral: {_mrd_clean_one_line(ref)}")
                fu = (_mrd_row_get(ds, "followup_instructions", "") or "").strip()
                if fu:
                    snap_lines.append(f"Follow-up: {_mrd_clean_one_line(fu)}")
            else:
                snap_lines.append("No discharge summary yet.")

            # Draw snapshot box
            box_h = 2.8 * cm
            if (y - box_h) < (mb + 2.4 * cm):
                c.showPage()
                _addendum_header("S3 (cont.)")
                y = height - mt - 60

            c.setStrokeColor(colors.black)
            c.setFillColor(colors.HexColor("#f2f2f2"))
            c.rect(ml, y - 0.55 * cm, usable_w, 0.55 * cm, stroke=1, fill=1)
            c.setFillColor(colors.black)
            c.setFont("Helvetica-Bold", 10)
            c.drawString(ml + 4, y - 0.55 * cm + 2, "Discharge snapshot (for re-entry)")

            c.setFillColor(colors.white)
            c.rect(ml, y - box_h, usable_w, box_h - 0.55 * cm, stroke=1, fill=0)

            # Ensure text is visible (avoid white-on-white)
            c.setFillColor(colors.black)
            c.setFont("Helvetica", 8.8)
            ty = y - 0.55 * cm - 10
            for ln in snap_lines:
                for wln in textwrap.wrap(_mrd_clean_one_line(ln), 125) or [ln]:
                    if ty < (y - box_h + 10):
                        break
                    c.drawString(ml + 8, ty, wln[:200])
                    ty -= 14

        # Always place sign-off on the final S3 page.
        _draw_signoff_line()

        if page_break_after:
            c.showPage()


# Backward compatible alias (older code paths / patches)
def _mrd_draw_addendum_pages_for_auto_summary(
    c,
    *,
    cur,
    visit,
    visit_id,
    age,
    printed_at,
    reg_dt,
    triage_dt,
    discharge_dt,
):
    return _mrd_draw_addendum_pages(
        c,
        cur=cur,
        visit=visit,
        visit_id=visit_id,
        age=age,
        printed_at=printed_at,
        reg_dt=reg_dt,
        triage_dt=triage_dt,
        discharge_dt=discharge_dt,
        report_label="Auto ED Course Summary",
        include_labs=True,
        include_rads=True,
        include_meds=True,
        include_discharge_snapshot=True,
    )


@app.route("/auto_summary/<visit_id>/pdf")
@login_required
@role_required("nurse", "doctor", "admin")
def auto_summary_pdf(visit_id):
    """Auto ED Course Summary (professional PDF).

    Includes:
    - Registration time
    - Triage time
    - Discharge time
    All displayed automatically in the configured local (display) timezone.
    """
    db = get_db()
    cur = db.cursor()

    visit = cur.execute(
        """
        SELECT v.visit_id,
               v.queue_no,
               v.status,
               v.created_at,
               v.triage_time,
               v.closed_at,
               v.created_by,
               v.closed_by,
               p.name,
               p.mrn,
               p.cerner_mrn,
               p.id_number,
               p.phone,
               p.dob,
               p.sex,
               p.nationality,
               p.insurance,
               p.insurance_no
        FROM visits v
        JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
    """,
        (visit_id,),
    ).fetchone()

    if not visit:
        return "Not found", 404

    sections = build_auto_summary_sections(visit_id)

    # Local times (display timezone)
    printed_at = now_display_str("%Y-%m-%d %H:%M")
    reg_dt = format_dt_local(visit["created_at"]) or (visit["created_at"] or "")
    triage_dt = format_dt_local(visit["triage_time"]) or ""
    discharge_dt = format_dt_local(visit["closed_at"]) or ""
    age = calc_age(visit["dob"])
    mrn_display = (
        _pdf_resolve_patient_mrn(visit_row=visit, visit_id=visit_id, cur=cur) or "-"
    )

    buffer = io.BytesIO()
    c = _pdf_attach_patient_mrn_stamp(
        canvas.Canvas(buffer, pagesize=A4), visit_row=visit, visit_id=visit_id, cur=cur
    )
    width, height = A4

    ml = 1.3 * cm
    mr = 1.3 * cm
    mt = 1.2 * cm
    mb = 1.2 * cm

    usable_w = width - ml - mr

    page_no = 1
    y_top = height - mt

    def _s(val, default="-"):
        if val is None:
            return default
        s = str(val).strip()
        return s if s else default

    def _draw_header():
        nonlocal y_top
        header_h = 1.25 * cm
        y0 = y_top - header_h

        c.setStrokeColor(colors.black)
        c.setFillColor(colors.lightgrey)
        c.rect(ml, y0, usable_w, header_h, stroke=1, fill=1)

        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 14)
        c.drawString(ml + 0.25 * cm, y0 + 0.42 * cm, "Auto ED Course Summary")

        c.setFont("Helvetica", 8.5)
        info_right = ml + usable_w - 0.25 * cm
        c.drawRightString(
            info_right, y0 + 0.72 * cm, f"Case No: {_s(visit['visit_id'])}"
        )
        c.drawRightString(
            info_right,
            y0 + 0.30 * cm,
            f"Downtime MRN: {mrn_display}  |  Cerner MRN: {cerner_mrn_display(_pdf_resolve_patient_cerner_mrn(visit_row=visit, visit_id=visit_id, cur=cur), 'N/A')}  |  Printed: {printed_at}  |  Page: {page_no}",
        )

        y_top = y0 - 0.35 * cm

    def _new_page():
        nonlocal y_top, page_no
        c.showPage()
        page_no += 1
        y_top = height - mt
        _draw_header()

    def _draw_section(
        x,
        y_top_sec,
        w,
        title,
        text_lines,
        font_size=9,
        max_chars=120,
        line_h=0.42 * cm,
        min_content_h=0.9 * cm,
    ):
        """Boxed section with title bar + wrapped content."""
        nonlocal y_top

        bar_h = 0.6 * cm

        # Normalize content to a list of lines
        lines = []
        if isinstance(text_lines, list):
            for t in text_lines:
                t = "" if t is None else str(t)
                if t.strip() == "":
                    lines.append("-")
                else:
                    lines.extend(t.splitlines())
        else:
            t = "" if text_lines is None else str(text_lines)
            lines = t.splitlines() if t.strip() else ["-"]

        wrapped = []
        for raw in lines:
            raw = (raw or "").rstrip()
            if raw == "":
                wrapped.append("")
                continue
            wrapped.extend(textwrap.wrap(raw, max_chars) or [""])

        wrapped = wrapped or ["-"]

        content_h = max(min_content_h, (len(wrapped) * line_h) + 0.35 * cm)
        total_h = bar_h + content_h
        y_bottom = y_top_sec - total_h

        if y_bottom < mb + 1.2 * cm:
            _new_page()
            y_top_sec = y_top
            y_bottom = y_top_sec - total_h

        c.setStrokeColor(colors.black)
        c.setFillColor(colors.white)
        c.rect(x, y_bottom, w, total_h, stroke=1, fill=0)

        c.setFillColor(colors.whitesmoke)
        c.rect(x, y_top_sec - bar_h, w, bar_h, stroke=0, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 10)
        c.drawString(x + 0.2 * cm, y_top_sec - bar_h + 0.18 * cm, title)

        tx = x + 0.2 * cm
        ty = y_top_sec - bar_h - 0.32 * cm
        c.setFont("Helvetica", font_size)
        for ln in wrapped:
            if ln == "":
                ty -= line_h
                continue
            c.drawString(tx, ty, ln[:200])
            ty -= line_h

        y_top = y_bottom - 0.35 * cm
        return y_top

    def _draw_title_bar(title):
        nonlocal y_top
        bar_h = 0.6 * cm
        if (y_top - bar_h) < (mb + 1.2 * cm):
            _new_page()
        c.setStrokeColor(colors.black)
        c.setFillColor(colors.whitesmoke)
        c.rect(ml, y_top - bar_h, usable_w, bar_h, stroke=1, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 10)
        c.drawString(ml + 0.2 * cm, y_top - bar_h + 0.18 * cm, title)
        y_top = y_top - bar_h - 0.35 * cm

    def _draw_flow_text(
        text, max_chars=120, line_h=0.42 * cm, font_size=9, cont_title=None
    ):
        """Draw long wrapped text that can flow across pages."""
        nonlocal y_top
        c.setFont("Helvetica", font_size)

        if text is None or str(text).strip() == "":
            text = "-"

        for raw in str(text).splitlines():
            raw = raw.rstrip()
            if raw == "":
                y_top -= line_h
                if y_top < mb + 1.2 * cm:
                    _new_page()
                    if cont_title:
                        _draw_title_bar(cont_title)
                        c.setFont("Helvetica", font_size)
                continue

            for ln in textwrap.wrap(raw, max_chars) or [""]:
                if y_top < mb + 1.2 * cm:
                    _new_page()
                    if cont_title:
                        _draw_title_bar(cont_title)
                        c.setFont("Helvetica", font_size)
                c.drawString(ml + 0.2 * cm, y_top, ln[:200])
                y_top -= line_h

    # -----------------------
    # Build PDF
    # -----------------------

    _draw_header()

    patient_lines = [
        f"Patient: {_s(visit['name'])}",
        f"Age: {_s(age) if age else '-'}",
        f"MRN / ID: {mrn_display} / {_s(visit['id_number'])}",
        f"Physician: {_doctor_display_with_gd(cur, _resolve_doctor_name_for_visit(cur, visit, visit_id))}",
        f"Phone: {_s(visit['phone'])}",
        f"Sex / Nationality: {_s(visit['sex'])} / {_s(visit['nationality'])}",
        f"Insurance: {_s(visit['insurance'])}  (No: {_s(visit['insurance_no'])})",
        f"Registered: {_s(reg_dt)}  by {_staff_display_with_ids(cur, visit['created_by'] or '-')}",
        f"Triage: {_s(triage_dt)}  by {_staff_display_with_ids(cur, _latest_activity_username(cur, visit_id, 'TRIAGE_UPDATE') or (visit['created_by'] or '-'))}",
        f"Discharge: {_s(discharge_dt)}  by {_staff_display_with_ids(cur, visit['closed_by'] or '-')}",
        f"Status: {_s(visit['status'])}",
    ]

    # ID photo path (if available)
    id_photo_path = get_visit_id_photo_path(cur, visit_id)

    # Draw Patient & Visit box + ID / Eligibility box (same layout as ED TRIAGE SHEET)
    gap = 0.35 * cm
    id_box_w = min(7.6 * cm, usable_w * 0.42)
    top_boxes_h = 5.6 * cm
    patient_box_w = usable_w - id_box_w - gap
    patient_x = ml
    id_x = ml + patient_box_w + gap

    def _draw_box_with_title(x, y_top_box, w, h, title):
        bar_h = 0.55 * cm
        c.setStrokeColor(colors.black)
        c.rect(x, y_top_box - h, w, h, stroke=1, fill=0)
        c.setFillColor(colors.HexColor("#f2f2f2"))
        c.rect(x, y_top_box - bar_h, w, bar_h, stroke=1, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 10)
        c.drawString(x + 0.25 * cm, y_top_box - bar_h + 0.18 * cm, title)
        return y_top_box - h, bar_h

    patient_bottom, patient_bar_h = _draw_box_with_title(
        patient_x, y_top, patient_box_w, top_boxes_h, "Patient & Case No"
    )
    id_bottom, id_bar_h = _draw_box_with_title(
        id_x, y_top, id_box_w, top_boxes_h, "ID / Eligibility Attachment"
    )

    # Patient lines (wrapped)
    pad = 0.35 * cm
    y = y_top - patient_bar_h - pad
    line_h = 0.42 * cm
    c.setFont("Helvetica", 9)
    max_chars = 62
    for ln in patient_lines:
        for wln in textwrap.wrap(str(ln), max_chars) or ["-"]:
            if y < patient_bottom + pad:
                break
            c.drawString(patient_x + pad, y, _s(wln))
            y -= line_h

    # ID image (fit into box)
    img_pad = 0.25 * cm
    img_area_x = id_x + img_pad
    img_area_y = id_bottom + img_pad
    img_area_w = id_box_w - 2 * img_pad
    img_area_h = top_boxes_h - id_bar_h - 2 * img_pad

    if id_photo_path:
        try:
            c.drawImage(
                id_photo_path,
                img_area_x,
                img_area_y,
                width=img_area_w,
                height=img_area_h,
                preserveAspectRatio=True,
                anchor="c",
                mask="auto",
            )
        except Exception:
            c.setFont("Helvetica-Oblique", 8)
            c.drawString(
                img_area_x, img_area_y + img_area_h / 2, "Attachment is not an image."
            )
    else:
        c.setFont("Helvetica-Oblique", 8)
        c.drawString(
            img_area_x, img_area_y + img_area_h / 2, "No ID attachment uploaded."
        )

    # Move below top boxes
    y_top = min(patient_bottom, id_bottom) - 0.5 * cm
    # Render each section in a clean, readable layout (like ED TRIAGE SHEET)
    for sec_title, sec_body in sections or []:
        sec_title = (sec_title or "Summary").strip() or "Summary"
        _draw_title_bar(sec_title)
        _draw_flow_text(
            sec_body,
            max_chars=120,
            line_h=0.46 * cm,
            font_size=9,
            cont_title=f"{sec_title} (cont.)",
        )
        y_top -= 0.15 * cm

    c.setFont("Helvetica-Oblique", 8)
    c.drawString(ml, 1.2 * cm, APP_FOOTER_TEXT)

    if mrd_addendum_allowed("auto_summary"):
        c.showPage()
        # MRD downtime addendum pages appended at end
        try:
            v_add = _mrd_fetch_visit_for_addendum(cur, visit_id) or visit
            printed_at2, reg_dt2, triage_dt2, discharge_dt2, age2 = (
                _mrd_addendum_context_from_visit(v_add)
            )
            _mrd_draw_addendum_pages(
                c,
                cur=cur,
                visit=v_add,
                visit_id=visit_id,
                age=age2,
                printed_at=printed_at2,
                reg_dt=reg_dt2,
                triage_dt=triage_dt2,
                discharge_dt=discharge_dt2,
                report_label="Auto ED Course Summary",
                include_labs=True,
                include_rads=True,
                include_meds=True,
                include_discharge_snapshot=True,
                page_break_after=False,
            )
        except Exception:
            pass

    c.save()
    buffer.seek(0)

    return Response(
        buffer.getvalue(),
        mimetype="application/pdf",
        headers=_patient_pdf_headers(visit, "AutoEDCourseSummary", visit_id=visit_id),
    )


def _resolve_doctor_name_for_visit(cur, visit_row, visit_id):
    """
    Try to determine the doctor username for this visit.

    Priority:
      1) discharge_summaries.updated_by / created_by
      2) clinical_orders.updated_by / created_by (latest row)
      3) visits.closed_by / created_by

    Only returns usernames whose users.role is 'doctor' or 'admin'
    (and is_active=1). If no matching doctor is found, returns "".
    """

    def _add_candidates_from_row(row, field_names, dest_list):
        if not row:
            return
        for fname in field_names:
            val = ""
            # Row may be a sqlite3.Row (dict-like) or tuple
            if isinstance(row, sqlite3.Row):
                try:
                    val = (row.get(fname) or "").strip()
                except Exception:
                    # Some sqlite3.Row versions do not implement .get()
                    try:
                        val = (row[fname] or "").strip()
                    except Exception:
                        val = ""
            else:
                # Fallback: try using column order if it is a tuple
                try:
                    idx = field_names.index(fname)
                    val = (row[idx] or "").strip()
                except Exception:
                    val = ""
            if val:
                dest_list.append(val)

    candidates = []

    # 1) Prefer explicit discharge summary doctor if available
    try:
        ds_row = cur.execute(
            "SELECT updated_by, created_by FROM discharge_summaries WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
    except Exception:
        ds_row = None

    _add_candidates_from_row(ds_row, ["updated_by", "created_by"], candidates)

    # 2) Latest clinical_orders row (often entered by doctor)
    try:
        co_row = cur.execute(
            """
            SELECT updated_by, created_by
            FROM clinical_orders
            WHERE visit_id=?
            ORDER BY id DESC
            LIMIT 1
            """,
            (visit_id,),
        ).fetchone()
    except Exception:
        co_row = None

    _add_candidates_from_row(co_row, ["updated_by", "created_by"], candidates)

    # 3) Fallback to visit closed_by / created_by
    if visit_row is not None:
        for fname in ("closed_by", "created_by"):
            try:
                val = (visit_row[fname] or "").strip()
            except Exception:
                val = ""
            if val:
                candidates.append(val)

    # Normalise, drop blanks / UNKNOWN, remove duplicates preserving order
    cleaned = []
    seen = set()
    for name in candidates:
        name = (name or "").strip()
        if not name:
            continue
        if name.upper() == "UNKNOWN":
            continue
        if name in seen:
            continue
        seen.add(name)
        cleaned.append(name)

    if not cleaned:
        return ""

    # Only accept real doctors/admins based on users table
    for uname in cleaned:
        try:
            user_row = cur.execute(
                "SELECT role FROM users WHERE username=? AND is_active=1",
                (uname,),
            ).fetchone()
        except Exception:
            user_row = None

        role = ""
        if user_row is not None:
            try:
                # sqlite3.Row supports dict-style access
                role = (user_row["role"] or "").lower()
            except Exception:
                try:
                    role = (user_row[0] or "").lower()
                except Exception:
                    role = ""

        if role in ("doctor", "admin"):
            return uname

    # No valid doctor/admin found -> return empty so PDF shows blank line
    return ""


_PHYSICIAN_DIR_CACHE_TTL_SECONDS = int(os.environ.get("PHYSICIAN_DIR_CACHE_TTL_SECONDS", "60") or 60)
_PHYSICIAN_DIR_CACHE = {"expires_at": 0.0, "by_gd": {}, "by_name": {}}


def _get_physician_directory_maps(cur=None, force=False):
    """Return cached physician directory lookups keyed by GD and lowercase name."""
    global _PHYSICIAN_DIR_CACHE
    now_ts = time.time()
    if (not force) and _PHYSICIAN_DIR_CACHE.get("expires_at", 0.0) > now_ts:
        return _PHYSICIAN_DIR_CACHE.get("by_gd", {}), _PHYSICIAN_DIR_CACHE.get("by_name", {})

    try:
        ensure_admission_picklists_schema()
    except Exception as ensure_exc:
        _log_noncritical_exception("_get_physician_directory_maps: ensure_admission_picklists_schema", ensure_exc)

    if cur is None:
        cur = get_db().cursor()

    try:
        rows = cur.execute("""
            SELECT value, extra
            FROM admission_order_picklists
            WHERE category='doctor' AND is_active=1
            ORDER BY id DESC
            """).fetchall()
    except Exception:
        rows = []

    by_gd = {}
    by_name = {}
    for r in rows or []:
        try:
            name = (r["value"] or "").strip()
            extra = r["extra"] or ""
        except Exception:
            try:
                name = (r[0] or "").strip()
                extra = (r[1] if len(r) > 1 else "") or ""
            except Exception:
                continue

        if not name:
            continue
        gd, _spec = doctor_extra_parse(extra or "")
        gd = (gd or "").strip()
        nm_key = name.lower()
        if gd and gd not in by_gd:
            by_gd[gd] = name
        if nm_key and nm_key not in by_name:
            by_name[nm_key] = gd

    _PHYSICIAN_DIR_CACHE = {
        "expires_at": now_ts + max(5, int(_PHYSICIAN_DIR_CACHE_TTL_SECONDS or 60)),
        "by_gd": by_gd,
        "by_name": by_name,
    }
    return by_gd, by_name


def _physician_directory_lookup_by_gd(cur, gd_number):
    """Return physician full name from Physicians Directory (picklist) by GD number."""
    gd = (gd_number or "").strip()
    if not gd:
        return ""
    by_gd, _by_name = _get_physician_directory_maps(cur)
    return (by_gd.get(gd) or "").strip()


def _physician_directory_lookup_gd_by_name(cur, physician_name):
    """Return GD number from Physicians Directory by physician name (case-insensitive exact match)."""
    nm = (physician_name or "").strip()
    if not nm:
        return ""
    _by_gd, by_name = _get_physician_directory_maps(cur)
    return (by_name.get(nm.lower()) or "").strip()



def _resolve_physician_display_from_username(cur, username):
    """Return (display_name, gd_number) for a doctor/admin username.

    - display_name: full name from Physicians Directory if GD is matched; otherwise username.
    - gd_number: from users.gd_number (may be blank).
    """
    uname = (username or "").strip()
    if not uname:
        return ("", "")

    try:
        user_row = cur.execute(
            "SELECT role, gd_number FROM users WHERE username=? AND is_active=1",
            (uname,),
        ).fetchone()
    except Exception:
        user_row = None

    if not user_row:
        return ("", "")

    role = ""
    gd = ""
    try:
        role = (user_row["role"] or "").lower()
        gd = (user_row["gd_number"] or "").strip()
    except Exception:
        try:
            role = (user_row[0] or "").lower()
        except Exception:
            role = ""
        try:
            gd = (user_row[1] or "").strip()
        except Exception:
            gd = ""

    if role not in ("doctor", "admin"):
        return ("", "")

    display = _physician_directory_lookup_by_gd(cur, gd) or uname
    return (display, gd)


def _assigned_physician_display(cur, assigned_value):
    """Return a readable physician display name for board/template rendering.

    If the stored value is a doctor/admin username, resolve it to the
    Physicians Directory display name. Otherwise keep the original text.
    """
    raw = (assigned_value or "").strip()
    if not raw:
        return ""
    try:
        display, _gd = _resolve_physician_display_from_username(cur, raw)
    except Exception:
        display = ""
    return (display or raw).strip()


def _autofill_visit_assigned_physician(cur, visit_id, prefer_username=None):
    """Ensure visits.assigned_doctor holds a readable physician name.

    - If assigned_doctor is empty and prefer_username is a doctor/admin, fill it using Physicians Directory.
    - If assigned_doctor is a doctor/admin username and a directory name exists for its GD, convert it.
    """
    try:
        row = cur.execute(
            "SELECT assigned_doctor FROM visits WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
    except Exception:
        return

    assigned = ""
    if row is not None:
        try:
            assigned = (row["assigned_doctor"] or "").strip()
        except Exception:
            try:
                assigned = (row[0] or "").strip()
            except Exception:
                assigned = ""

    updated_value = None

    # Case 1: empty -> fill from current user (doctor/admin)
    if not assigned and prefer_username:
        display, _gd = _resolve_physician_display_from_username(cur, prefer_username)
        if display:
            updated_value = display

    # Case 2: assigned is username -> convert to directory name if available
    if assigned and updated_value is None:
        display, _gd = _resolve_physician_display_from_username(cur, assigned)
        if display and display != assigned:
            updated_value = display

    if updated_value is not None:
        try:
            cur.execute(
                "UPDATE visits SET assigned_doctor=? WHERE visit_id=?",
                (updated_value, visit_id),
            )
            get_db().commit()
        except Exception:
            try:
                get_db().rollback()
            except Exception:
                pass


def _safe_row_get(row, key, default=""):
    """Safe dict-style accessor for sqlite3.Row / psycopg2 DictRow."""
    if row is None:
        return default
    try:
        v = row[key]
        return default if v is None else v
    except Exception:
        return default


def _find_active_username_by_gd(cur, gd_number, roles=("doctor", "admin")):
    """Find an active username linked to a given GD/License number (usually doctor)."""
    gd_number = (gd_number or "").strip()
    if not gd_number:
        return ""
    try:
        if roles:
            placeholders = ",".join(["?"] * len(roles))
            row = cur.execute(
                f"SELECT username FROM users WHERE gd_number=? AND is_active=1 AND role IN ({placeholders}) ORDER BY id ASC LIMIT 1",
                (gd_number, *roles),
            ).fetchone()
        else:
            row = cur.execute(
                "SELECT username FROM users WHERE gd_number=? AND is_active=1 ORDER BY id ASC LIMIT 1",
                (gd_number,),
            ).fetchone()
    except Exception:
        row = None

    if row is None:
        return ""
    try:
        return (row["username"] or "").strip()
    except Exception:
        try:
            return (row[0] or "").strip()
        except Exception:
            return ""


def _format_staff_ids(
    emp, gd, *, include_emp=True, include_gd=True, emp_label="EMP", gd_label="GD/Lic"
):
    """Format staff identifiers in a consistent compact form.

    - emp: usually the login username / employee number
    - gd:  license / GD number
    """
    emp = (emp or "").strip()
    gd = (gd or "").strip()
    parts = []
    if include_emp and emp:
        parts.append(f"{emp_label}:{emp}")
    if include_gd and gd:
        parts.append(f"{gd_label}:{gd}")
    return " | ".join(parts)


def _ensure_dr_prefix(name: str) -> str:
    """Ensure physician names are displayed with a 'Dr.' prefix (without double prefix)."""
    n = (name or "").strip()
    if not n:
        return n
    low = n.lower()
    if low.startswith("dr ") or low.startswith("dr.") or low.startswith("doctor "):
        return n
    return f"Dr. {n}"


def _expand_provider_note_headings(note_text: str) -> str:
    """Expand Provider Note headings (CC/HPI/Exam/MDM) to full words for print clarity."""
    t = note_text or ""
    replacements = [
        (r"(?im)^\s*CC\s*:\s*", "Chief Complaint: "),
        (r"(?im)^\s*HPI\s*:\s*", "History of Present Illness: "),
        (r"(?im)^\s*EXAM\s*:\s*", "Examination: "),
        (r"(?im)^\s*MDM\s*:\s*", "Medical Decision Making: "),
        (r"(?im)^\s*PLAN\s*:\s*", "Plan: "),
    ]
    for pat, rep in replacements:
        try:
            t = re.sub(pat, rep, t)
        except Exception:
            continue
    return t


def _staff_display_with_ids(cur, username, default="-"):
    """Format staff for UI/PDF (name + identifiers) with physician-name resolution.

    Key requirement (Downtime traceability):
      - Always show a human-readable staff name when possible.
      - Keep identifiers for traceability.

    Special rule requested by site:
      - For doctors: show **Name + GD/Lic only** (NO EMP/username).
      - For non-doctors: show **Name + EMP + GD/Lic** (when available).

    Display name rules:
      - Doctors: prefer Physicians Directory name by GD/Lic.
      - Other roles: prefer users.full_name (if present) else username.
      - If not a system user (free text), return the original value.
    """
    u = (username or "").strip()
    if not u or u in ("-", "None", "none"):
        return default

    # Try to read user row (with/without full_name depending on schema)
    user_row = None
    try:
        user_row = cur.execute(
            "SELECT username, full_name, role, gd_number, is_active FROM users WHERE username=?",
            (u,),
        ).fetchone()
    except Exception:
        try:
            user_row = cur.execute(
                "SELECT username, role, gd_number, is_active FROM users WHERE username=?",
                (u,),
            ).fetchone()
        except Exception:
            user_row = None

    if user_row is None:
        # Not a system user; keep as-is (e.g., free text).
        # Also: if the value is a pure GD/Lic that exists in the directory, resolve it as a physician.
        dir_name = _physician_directory_lookup_by_gd(cur, u)
        if dir_name:
            dir_name = _ensure_dr_prefix(dir_name)
            ids = _format_staff_ids(
                "", u, include_emp=False, include_gd=True, gd_label="GD"
            )
            return f"{dir_name} ({ids})" if ids else dir_name
        return u

    role = (_safe_row_get(user_row, "role", "") or "").lower()
    emp = (_safe_row_get(user_row, "username", "") or "").strip() or u
    gd = (_safe_row_get(user_row, "gd_number", "") or "").strip()
    full_name = (_safe_row_get(user_row, "full_name", "") or "").strip()

    # If doctor has no gd_number stored, but username looks like a number, treat it as GD.
    if role == "doctor" and not gd and emp.isdigit():
        gd = emp

    # Display name preference
    if role == "doctor":
        display_name = _physician_directory_lookup_by_gd(cur, gd) or full_name or emp
        display_name = _ensure_dr_prefix(display_name)
        ids = _format_staff_ids(
            "", gd, include_emp=False, include_gd=True, gd_label="GD"
        )
        return f"{display_name} ({ids})" if ids else display_name

    if role == "admin":
        # Admin is not necessarily a doctor; keep EMP for traceability.
        display_name = full_name or emp
        ids = _format_staff_ids(emp, gd, include_emp=True, include_gd=bool(gd))
        return f"{display_name} ({ids})" if ids else display_name

    # Other roles (nurse/lab/radiology/reception/...)
    display_name = full_name or emp
    ids = _format_staff_ids(emp, gd, include_emp=True, include_gd=bool(gd))
    return f"{display_name} ({ids})" if ids else display_name


def _physician_display_with_ids(cur, doctor_name, blank_line="______________________"):
    """
    Physician display (name + EMP + GD/Lic), accepting:
      - doctor/admin username (preferred)
      - free-text physician name (from visits/picklists)
      - a pure GD/License number
    Safety:
      - If doctor_name matches an ACTIVE user but NOT role doctor/admin, return blank_line.
    """
    if not doctor_name:
        return blank_line

    val = (doctor_name or "").strip()
    if not val:
        return blank_line

    # 1) If val is a real active user, enforce role check, then format using staff formatter
    try:
        user_row = cur.execute(
            "SELECT role, is_active FROM users WHERE username=?",
            (val,),
        ).fetchone()
    except Exception:
        user_row = None

    if user_row is not None:
        role = (_safe_row_get(user_row, "role", "") or "").lower()
        is_active = _safe_row_get(user_row, "is_active", 1)
        try:
            is_active = int(is_active)
        except Exception:
            is_active = 1

        if is_active == 1 and role not in ("doctor", "admin"):
            return blank_line
        return _staff_display_with_ids(cur, val, default=blank_line)

    # 2) If val looks like a GD/Lic and exists in directory
    dir_name = _physician_directory_lookup_by_gd(cur, val)
    if dir_name:
        dir_name = _ensure_dr_prefix(dir_name)
        emp = _find_active_username_by_gd(cur, val, roles=("doctor", "admin"))
        ids = (
            _format_staff_ids(
                "", val, include_emp=False, include_gd=True, gd_label="GD"
            )
            if emp
            else _format_staff_ids(
                "", val, include_emp=False, include_gd=True, gd_label="GD"
            )
        )
        return f"{dir_name} ({ids})" if ids else dir_name

    # 3) Free-text physician name -> attach GD if known, and try to map back to a user for EMP
    dir_gd = _physician_directory_lookup_gd_by_name(cur, val)
    if dir_gd:
        emp = _find_active_username_by_gd(cur, dir_gd, roles=("doctor", "admin"))
        ids = (
            _format_staff_ids(
                "", dir_gd, include_emp=False, include_gd=True, gd_label="GD"
            )
            if emp
            else _format_staff_ids(
                "", dir_gd, include_emp=False, include_gd=True, gd_label="GD"
            )
        )
        disp = _ensure_dr_prefix(val)
        return f"{disp} ({ids})" if ids else disp
    return _ensure_dr_prefix(val)


def _latest_activity_username(cur, visit_id, action):
    """Return the latest activity_log.username for a given visit/action, if available."""
    vid = (visit_id or "").strip()
    act = (action or "").strip()
    if not vid or not act:
        return ""
    try:
        row = cur.execute(
            "SELECT username FROM activity_log WHERE visit_id=? AND action=? ORDER BY id DESC LIMIT 1",
            (vid, act),
        ).fetchone()
    except Exception:
        row = None
    if not row:
        return ""
    try:
        return (row["username"] or "").strip()
    except Exception:
        try:
            return (row[0] or "").strip()
        except Exception:
            return ""


def _doctor_display_with_gd(cur, doctor_name):
    """
    Return physician display label for print/PDF.

    Output format (when available):
        <Physician Name> (EMP:<username> | GD/Lic:<gd_number>)

    Accepts either:
      - a doctor/admin username (preferred)
      - a free-text physician name stored in visits/picklists
      - a pure GD/License number

    Safety rule:
      - If doctor_name matches an ACTIVE user but NOT role doctor/admin,
        returns a blank signature line to avoid printing wrong staff (e.g. reception).
    """
    return _physician_display_with_ids(
        cur, doctor_name, blank_line="______________________"
    )


@app.route("/patient_summary/<visit_id>/pdf")
@login_required
def patient_summary_pdf(visit_id):
    """ED Visit Summary - Patient Copy (professional PDF).

    Includes Registration / Triage / Discharge times in the configured local timezone.
    """
    db = get_db()
    cur = db.cursor()

    visit = cur.execute(
        """
        SELECT v.visit_id,
               v.queue_no,
               v.comment,
               v.status,
               v.created_at,
               v.triage_time,
               v.closed_at,
               v.created_by,
               v.closed_by,
               p.name,
               p.mrn,
               p.id_number,
               p.phone,
               p.dob,
               p.sex,
               p.nationality,
               p.insurance,
               p.insurance_no
        FROM visits v
        JOIN patients p ON p.id = v.patient_id
        WHERE v.visit_id = ?
    """,
        (visit_id,),
    ).fetchone()

    if not visit:
        return "Not found", 404

    # Discharge summary (patient-friendly fields)
    summary = cur.execute(
        """
        SELECT diagnosis_cc,
               review_of_system,
               physical_exam,
               final_diagnosis,
               referral_clinic,
               home_medication,
               summary_text,
               investigations_summary,
               procedures_text,
               condition_on_discharge,
               followup_instructions
        FROM discharge_summaries
        WHERE visit_id = ?
    """,
        (visit_id,),
    ).fetchone()

    # Latest clinical order (for medications / diagnosis if discharge summary missing)
    latest_order = cur.execute(
        """
        SELECT diagnosis, medications
        FROM clinical_orders
        WHERE visit_id=?
        ORDER BY id DESC
        LIMIT 1
    """,
        (visit_id,),
    ).fetchone()

    # Investigations
    labs = cur.execute(
        """
        SELECT test_name, status, result_text
        FROM lab_requests
        WHERE visit_id=?
        ORDER BY id ASC
    """,
        (visit_id,),
    ).fetchall()

    rads = cur.execute(
        """
        SELECT test_name, status, report_text
        FROM radiology_requests
        WHERE visit_id=?
        ORDER BY id ASC
    """,
        (visit_id,),
    ).fetchall()

    # Physician name + GD
    doctor_name = _resolve_doctor_name_for_visit(cur, visit, visit_id)
    doctor_display = _doctor_display_with_gd(cur, doctor_name)

    # Local times (display timezone)
    printed_at = now_display_str("%Y-%m-%d %H:%M")
    reg_dt = format_dt_local(visit["created_at"]) or (visit["created_at"] or "")
    triage_dt = format_dt_local(visit["triage_time"]) or ""
    discharge_dt = format_dt_local(visit["closed_at"]) or ""
    age = calc_age(visit["dob"])
    mrn_display = (
        _pdf_resolve_patient_mrn(visit_row=visit, visit_id=visit_id, cur=cur) or "-"
    )

    def _s(val, default="-"):
        if val is None:
            return default
        s = str(val).strip()
        return s if s else default

    def _choose(*vals, default="-"):
        for v in vals:
            if v is None:
                continue
            vv = str(v).strip()
            if vv:
                return vv
        return default

    # Build section texts
    diagnosis_cc = _choose(
        summary["diagnosis_cc"] if summary else "",
        visit["comment"],
        latest_order["diagnosis"] if latest_order else "",
        default="-",
    )

    review_of_system = _choose(
        summary["review_of_system"] if summary else "", default="-"
    )

    physical_exam = _choose(summary["physical_exam"] if summary else "", default="-")

    final_diagnosis = _choose(
        summary["final_diagnosis"] if summary else "",
        latest_order["diagnosis"] if latest_order else "",
        default="-",
    )

    referral_clinic = _choose(
        summary["referral_clinic"] if summary else "", default="-"
    )
    raw_home_med = (summary["home_medication"] if summary else "") or ""
    home_medication = format_home_medication_for_print(
        raw_home_med, default_if_empty="-"
    )
    ed_course = _choose(summary["summary_text"] if summary else "", default="-")
    investigations_summary = _choose(
        summary["investigations_summary"] if summary else "", default="-"
    )
    procedures_text = _choose(
        summary["procedures_text"] if summary else "", default="-"
    )
    condition_on_discharge = _choose(
        summary["condition_on_discharge"] if summary else "", default="-"
    )
    followup_instructions = _choose(
        summary["followup_instructions"] if summary else "", default="-"
    )

    meds_given = _choose(
        latest_order["medications"] if latest_order else "", default="-"
    )

    # Lab/Rad formatted lists
    lab_lines = []
    for l in labs or []:
        st = (l["status"] or "").upper()
        if st == "REPORTED":
            lab_lines.append(f"{_s(l['test_name'])}: {_s(l['result_text'])}")
        else:
            lab_lines.append(f"{_s(l['test_name'])} - {_s(l['status'])}")
    if not lab_lines:
        lab_lines = ["No lab requests for this visit."]

    rad_lines = []
    for r in rads or []:
        st = (r["status"] or "").upper()
        if st == "REPORTED":
            rad_lines.append(f"{_s(r['test_name'])}: {_s(r['report_text'])}")
        else:
            rad_lines.append(f"{_s(r['test_name'])} - {_s(r['status'])}")
    if not rad_lines:
        rad_lines = ["No radiology requests for this visit."]

    # -----------------------
    # PDF setup
    # -----------------------
    buffer = io.BytesIO()
    c = _pdf_attach_patient_mrn_stamp(
        canvas.Canvas(buffer, pagesize=A4), visit_row=visit, visit_id=visit_id, cur=cur
    )
    width, height = A4

    ml = 1.3 * cm
    mr = 1.3 * cm
    mt = 1.2 * cm
    mb = 1.2 * cm

    usable_w = width - ml - mr

    page_no = 1
    y_top = height - mt

    def _draw_header():
        nonlocal y_top
        header_h = 1.25 * cm
        y0 = y_top - header_h

        c.setStrokeColor(colors.black)
        c.setFillColor(colors.lightgrey)
        c.rect(ml, y0, usable_w, header_h, stroke=1, fill=1)

        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 14)
        c.drawString(ml + 0.25 * cm, y0 + 0.42 * cm, "ED Visit Summary - Patient Copy")

        c.setFont("Helvetica", 8.5)
        info_right = ml + usable_w - 0.25 * cm
        c.drawRightString(
            info_right, y0 + 0.72 * cm, f"Case No: {_s(visit['visit_id'])}"
        )
        c.drawRightString(
            info_right,
            y0 + 0.30 * cm,
            f"MRN: {mrn_display}  |  Printed: {printed_at}  |  Page: {page_no}",
        )

        y_top = y0 - 0.35 * cm

    def _new_page():
        nonlocal y_top, page_no
        c.showPage()
        page_no += 1
        y_top = height - mt
        _draw_header()

    def _draw_section(
        x,
        y_top_sec,
        w,
        title,
        text_lines,
        font_size=9,
        max_chars=120,
        line_h=0.42 * cm,
        min_content_h=0.9 * cm,
    ):
        """Boxed section with title bar + wrapped content."""
        nonlocal y_top

        bar_h = 0.6 * cm

        # Normalize content to list of lines
        lines = []
        if isinstance(text_lines, list):
            for t in text_lines:
                t = "" if t is None else str(t)
                if t.strip() == "":
                    lines.append("-")
                else:
                    lines.extend(t.splitlines())
        else:
            t = "" if text_lines is None else str(text_lines)
            lines = t.splitlines() if t.strip() else ["-"]

        wrapped = []
        for raw in lines:
            raw = (raw or "").rstrip()
            if raw == "":
                wrapped.append("")
                continue
            wrapped.extend(textwrap.wrap(raw, max_chars) or [""])

        wrapped = wrapped or ["-"]

        content_h = max(min_content_h, (len(wrapped) * line_h) + 0.35 * cm)
        total_h = bar_h + content_h
        y_bottom = y_top_sec - total_h

        if y_bottom < mb + 1.2 * cm:
            _new_page()
            y_top_sec = y_top
            y_bottom = y_top_sec - total_h

        c.setStrokeColor(colors.black)
        c.setFillColor(colors.white)
        c.rect(x, y_bottom, w, total_h, stroke=1, fill=0)

        c.setFillColor(colors.whitesmoke)
        c.rect(x, y_top_sec - bar_h, w, bar_h, stroke=0, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 10)
        c.drawString(x + 0.2 * cm, y_top_sec - bar_h + 0.18 * cm, title)

        tx = x + 0.2 * cm
        ty = y_top_sec - bar_h - 0.32 * cm
        c.setFont("Helvetica", font_size)
        for ln in wrapped:
            if ln == "":
                ty -= line_h
                continue
            c.drawString(tx, ty, ln[:200])
            ty -= line_h

        y_top = y_bottom - 0.35 * cm
        return y_top

    def _draw_title_bar(title):
        nonlocal y_top
        bar_h = 0.6 * cm
        if (y_top - bar_h) < (mb + 1.2 * cm):
            _new_page()
        c.setStrokeColor(colors.black)
        c.setFillColor(colors.whitesmoke)
        c.rect(ml, y_top - bar_h, usable_w, bar_h, stroke=1, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 10)
        c.drawString(ml + 0.2 * cm, y_top - bar_h + 0.18 * cm, title)
        y_top = y_top - bar_h - 0.35 * cm

    def _draw_flow_text(
        text, max_chars=120, line_h=0.42 * cm, font_size=9, cont_title=None
    ):
        """Draw long wrapped text that can flow across pages."""
        nonlocal y_top
        c.setFont("Helvetica", font_size)

        if text is None or str(text).strip() == "":
            text = "-"

        for raw in str(text).splitlines():
            raw = raw.rstrip()
            if raw == "":
                y_top -= line_h
                if y_top < mb + 1.2 * cm:
                    _new_page()
                    if cont_title:
                        _draw_title_bar(cont_title)
                        c.setFont("Helvetica", font_size)
                continue

            for ln in textwrap.wrap(raw, max_chars) or [""]:
                if y_top < mb + 1.2 * cm:
                    _new_page()
                    if cont_title:
                        _draw_title_bar(cont_title)
                        c.setFont("Helvetica", font_size)
                c.drawString(ml + 0.2 * cm, y_top, ln[:200])
                y_top -= line_h

    # -----------------------
    # Build PDF
    # -----------------------

    _draw_header()

    patient_lines = [
        f"Patient: {_s(visit['name'])}",
        f"Age: {_s(age) if age else '-'}",
        f"MRN / ID: {mrn_display} / {_s(visit['id_number'])}",
        f"Phone: {_s(visit['phone'])}",
        f"DOB / Sex: {_s(visit['dob'])} / {_s(visit['sex'])}",
        f"Nationality: {_s(visit['nationality'])}",
        f"Insurance: {_s(visit['insurance'])}  (No: {_s(visit['insurance_no'])})",
        f"Registered: {_s(reg_dt)}  by {_staff_display_with_ids(cur, visit['created_by'] or '-')}",
        f"Triage: {_s(triage_dt)}  by {_staff_display_with_ids(cur, _latest_activity_username(cur, visit_id, 'TRIAGE_UPDATE') or (visit['created_by'] or '-'))}",
        f"Discharge: {_s(discharge_dt)}  by {_staff_display_with_ids(cur, visit['closed_by'] or '-')}",
        f"Status: {_s(visit['status'])}",
    ]

    # Admission / Disposition (brief reflection - no detailed fields)
    admission_brief = ""
    try:
        ensure_admission_orders_schema()
    except Exception:
        pass

    try:
        ao = cur.execute(
            """
            SELECT status, destination, admission_type, ward, bed_no
            FROM admission_orders
            WHERE visit_id=?
            ORDER BY id DESC
            LIMIT 1
            """,
            (visit_id,),
        ).fetchone()
    except Exception:
        ao = None

    if ao:
        try:
            ao_status = (ao["status"] or "").upper()
        except Exception:
            ao_status = ""
        try:
            dest = (ao["destination"] or "").strip() or "-"
        except Exception:
            dest = "-"
        try:
            typ = (ao["admission_type"] or "").strip() or "-"
        except Exception:
            typ = "-"
        try:
            ward = (ao["ward"] or "").strip()
        except Exception:
            ward = ""
        try:
            room = (ao["bed_no"] or "").strip()
        except Exception:
            room = ""

        if ao_status == "ORDERED":
            admission_brief = f"Admission Requested: {dest} ({typ})"
        elif ao_status == "ADMITTED":
            if ward or room:
                admission_brief = (
                    f"Admission: ADMITTED (Ward: {_s(ward)} / Room: {_s(room)})"
                )
            else:
                admission_brief = "Admission: ADMITTED"
        elif ao_status == "CANCELLED":
            admission_brief = "Admission Request: CANCELLED"
        else:
            if dest != "-" or typ != "-":
                admission_brief = f"Admission: {ao_status} ({dest} / {typ})"
            else:
                admission_brief = f"Admission: {ao_status}"

    if admission_brief:
        patient_lines.append(admission_brief)

    # LAMA / Transfer extra notes (if available)
    try:
        extra = cur.execute(
            "SELECT lama_reason, transfer_hospital, transfer_doctor FROM visits WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
    except Exception:
        extra = None

    try:
        st_visit = (visit["status"] or "").upper()
    except Exception:
        st_visit = ""
    if st_visit == "LAMA" and extra:
        try:
            lr = (extra["lama_reason"] or "").strip()
        except Exception:
            lr = ""
        if lr:
            patient_lines.append(f"LAMA Reason: {_s(lr)}")
    if st_visit == "TRANSFERRED" and extra:
        try:
            th = (extra["transfer_hospital"] or "").strip()
        except Exception:
            th = ""
        try:
            td = (extra["transfer_doctor"] or "").strip()
        except Exception:
            td = ""
        if th or td:
            patient_lines.append(
                f"Transferred To: {_s(th)} / Receiving Physician: {_s(td)}"
            )

    _draw_section(
        ml,
        y_top,
        usable_w,
        "Patient & Case No",
        patient_lines,
        font_size=9,
        max_chars=120,
    )

    # Sections
    _draw_title_bar("Diagnosis / Chief Complaint")
    _draw_flow_text(diagnosis_cc, cont_title="Diagnosis / Chief Complaint (cont.)")

    _draw_title_bar("Review of the System")
    _draw_flow_text(review_of_system, cont_title="Review of the System (cont.)")

    _draw_title_bar("Physical Exam")
    _draw_flow_text(physical_exam, cont_title="Physical Exam (cont.)")

    _draw_title_bar("Final Diagnosis")
    _draw_flow_text(final_diagnosis, cont_title="Final Diagnosis (cont.)")

    _draw_title_bar("ED / Hospital Course")
    _draw_flow_text(ed_course, cont_title="ED / Hospital Course (cont.)")

    _draw_title_bar("Investigations Summary")
    _draw_flow_text(investigations_summary, cont_title="Investigations Summary (cont.)")

    _draw_title_bar("Procedures")
    _draw_flow_text(procedures_text, cont_title="Procedures (cont.)")

    _draw_title_bar("Condition on Discharge")
    _draw_flow_text(condition_on_discharge, cont_title="Condition on Discharge (cont.)")

    _draw_title_bar("Referral")
    _draw_flow_text(referral_clinic, cont_title="Referral (cont.)")

    _draw_title_bar("Medications Given in ED")
    _draw_flow_text(meds_given, cont_title="Medications Given in ED (cont.)")

    _draw_title_bar("LAB RESULTS")
    _draw_flow_text("\n".join(lab_lines), cont_title="LAB RESULTS (cont.)")

    _draw_title_bar("RADIOLOGY REPORTS")
    _draw_flow_text("\n".join(rad_lines), cont_title="RADIOLOGY REPORTS (cont.)")

    _draw_title_bar("Home Medication")
    _draw_flow_text(home_medication, cont_title="Home Medication (cont.)")

    _draw_title_bar("Follow-up & Instructions")
    _draw_flow_text(
        followup_instructions, cont_title="Follow-up & Instructions (cont.)"
    )

    # Doctor / signature
    _draw_title_bar("Physician")
    _draw_flow_text(
        f"Physician: {doctor_display}\n\nSignature: ____________________________",
        cont_title="Physician (cont.)",
    )

    c.setFont("Helvetica-Oblique", 8)
    c.drawString(ml, 1.2 * cm, APP_FOOTER_TEXT)

    c.showPage()
    # MRD downtime addendum pages appended at end
    try:
        if mrd_addendum_allowed("patient_copy"):
            v_add = _mrd_fetch_visit_for_addendum(cur, visit_id) or visit
            printed_at2, reg_dt2, triage_dt2, discharge_dt2, age2 = (
                _mrd_addendum_context_from_visit(v_add)
            )
            _mrd_draw_addendum_pages(
                c,
                cur=cur,
                visit=v_add,
                visit_id=visit_id,
                age=age2,
                printed_at=printed_at2,
                reg_dt=reg_dt2,
                triage_dt=triage_dt2,
                discharge_dt=discharge_dt2,
                report_label="ED Visit Summary",
                include_labs=True,
                include_rads=True,
                include_meds=True,
                include_discharge_snapshot=True,
                page_break_after=False,
            )
    except Exception:
        pass

    c.save()
    buffer.seek(0)

    return Response(
        buffer.getvalue(),
        mimetype="application/pdf",
        headers=_patient_pdf_headers(visit, "PatientSummary", visit_id=visit_id),
    )


# ============================================================
# IP Admission Report PDF (Summary - no audit/details)
# ============================================================


@app.route("/ip_admission_report/<visit_id>/pdf")
@login_required
@role_required("admin", "inpatient_billing", "doctor", "nurse")
def ip_admission_report_pdf(visit_id):
    """IP Admission Report (summary).

    This is a clean admission report for printing (no audit trail / no history table).
    Includes:
    - Patient demographics
    - Admission Order key fields
    - Admission Processing (Ward/Room/Approval/Payment)
    """
    try:
        ensure_clinic_schema()
    except Exception:
        pass
    try:
        ensure_admission_orders_enterprise_upgrade()
    except Exception:
        pass

    db = get_db()
    cur = db.cursor()

    visit = cur.execute(
        """
        SELECT v.visit_id,
               v.status,
               v.created_at,
               v.closed_at,
               v.ward,
               v.bed_no,
               v.admission_type,
               v.approval_no,
               v.payment_details,
               v.ip_payment_details,
               p.name,
               p.mrn,
               p.id_number,
               p.phone,
               p.dob,
               p.sex,
               p.nationality,
               p.insurance,
               p.insurance_no
        FROM visits v
        JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
        """,
        (visit_id,),
    ).fetchone()

    if not visit:
        return "Not found", 404

    try:
        v = dict(visit)
    except Exception:
        v = {k: visit[k] for k in visit.keys()}

    preferred = None
    try:
        preferred = get_preferred_admission_order_for_visit(visit_id)
    except Exception:
        preferred = None

    printed_at = now_display_str("%Y-%m-%d %H:%M")
    age = calc_age(v.get("dob"))

    def _s(val, default="-"):
        if val is None:
            return default
        s = str(val).strip()
        return s if s else default

    # Key fields from preferred order
    o = preferred or {}

    # Use the ORDER admission type separately from processing admission_type if available
    order_type = _s(o.get("admission_type"), "-")
    proc_type = _s(v.get("admission_type"), "-")

    buffer = io.BytesIO()
    c = _pdf_attach_patient_mrn_stamp(
        canvas.Canvas(buffer, pagesize=A4), visit_row=visit, visit_id=visit_id, cur=cur
    )
    width, height = A4

    ml = 1.3 * cm
    mr = 1.3 * cm
    mt = 1.2 * cm
    mb = 1.2 * cm
    usable_w = width - ml - mr

    y = height - mt

    def header(title):
        nonlocal y
        h = 1.25 * cm
        y0 = y - h
        c.setStrokeColor(colors.black)
        c.setFillColor(colors.lightgrey)
        c.rect(ml, y0, usable_w, h, stroke=1, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 14)
        c.drawString(ml + 0.25 * cm, y0 + 0.42 * cm, title)
        c.setFont("Helvetica", 8.5)
        right = ml + usable_w - 0.25 * cm
        c.drawRightString(right, y0 + 0.72 * cm, f"Case No: {_s(v.get('visit_id'))}")
        c.drawRightString(right, y0 + 0.30 * cm, f"Printed: {printed_at}")
        y = y0 - 0.85 * cm  # extra gap so header is not tight with first section

    def section(title):
        nonlocal y
        bar_h = 0.55 * cm
        if y - (bar_h + 0.4 * cm) < mb:
            c.showPage()
            y = height - mt
            header("IP Admission Report")
        y0 = y - bar_h
        c.setFillColor(colors.HexColor("#efefef"))
        c.setStrokeColor(colors.black)
        c.rect(ml, y0, usable_w, bar_h, stroke=1, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 10)
        c.drawString(ml + 0.2 * cm, y0 + 0.18 * cm, title)
        y = y0 - 0.35 * cm  # padding under section title bar for readability

    def _value_x(label, x):
        c.setFont("Helvetica-Bold", 9)
        return x + max(2.7 * cm, c.stringWidth(str(label or ""), "Helvetica-Bold", 9) + 0.18 * cm)

    def _wrap_for_width(text, max_w, font_name="Helvetica", font_size=9):
        max_w = max(float(max_w or 0), 1.0)
        out = []
        for raw in str(text or "").splitlines():
            line = raw.strip()
            if not line:
                continue
            current = ""
            for word in line.split():
                candidate = word if not current else f"{current} {word}"
                if c.stringWidth(candidate, font_name, font_size) <= max_w:
                    current = candidate
                    continue
                if current:
                    out.append(current)
                    current = word
                else:
                    chunk = ""
                    for ch in word:
                        next_chunk = f"{chunk}{ch}"
                        if not chunk or c.stringWidth(next_chunk, font_name, font_size) <= max_w:
                            chunk = next_chunk
                        else:
                            out.append(chunk)
                            chunk = ch
                    current = chunk
            if current:
                out.append(current)
        return out or ["-"]

    def kv(label, value, x, y0, w):
        c.setFont("Helvetica-Bold", 9)
        c.drawString(x, y0, label)
        c.setFont("Helvetica", 9)
        c.drawString(_value_x(label, x), y0, _s(value))

    def kv_wrap(label, value, max_chars=110):
        nonlocal y
        txt = _s(value)
        val_x = _value_x(label, ml)
        val_w = (ml + usable_w) - val_x - 0.10 * cm
        lines = _wrap_for_width(txt, val_w)
        c.setFont("Helvetica-Bold", 9)
        c.drawString(ml, y, label)
        c.setFont("Helvetica", 9)
        y_line = y
        for i, ln in enumerate(lines):
            c.drawString(val_x, y_line, ln)
            y_line -= 0.42 * cm
        y = y_line - 0.1 * cm

    header("IP Admission Report")

    # Patient
    section("Patient")
    c.setFont("Helvetica", 9)
    row_h = 0.46 * cm
    kv("Name:", v.get("name"), ml, y, usable_w)
    kv("ID:", v.get("id_number"), ml + usable_w / 2, y, usable_w / 2)
    y -= row_h
    kv("Phone:", v.get("phone"), ml, y, usable_w)
    kv("Sex:", v.get("sex"), ml + usable_w / 2, y, usable_w / 2)
    y -= row_h
    kv("DOB/Age:", f"{_s(v.get('dob'))}  ({_s(age,'-')} yrs)", ml, y, usable_w)
    kv(
        "Nationality:",
        nationality_full(v.get("nationality")) or v.get("nationality"),
        ml + usable_w / 2,
        y,
        usable_w / 2,
    )
    y -= row_h
    kv("Insurance:", v.get("insurance"), ml, y, usable_w)
    kv("Insurance No:", v.get("insurance_no"), ml + usable_w / 2, y, usable_w / 2)
    y -= row_h
    kv_wrap("Payment Details:", v.get("payment_details"), max_chars=115)

    # Admission Request
    section("Admission Request")
    kv("Status:", _s(o.get("status")), ml, y, usable_w)
    kv("Destination:", _s(o.get("destination")), ml + usable_w / 2, y, usable_w / 2)
    y -= row_h
    kv("Referral DT:", _s(o.get("ref_datetime")), ml, y, usable_w)
    kv("Referring Dr:", _s(o.get("ref_by")), ml + usable_w / 2, y, usable_w / 2)
    y -= row_h
    kv("Admit Under:", _s(o.get("admit_dr")), ml, y, usable_w)
    kv("Type (Order):", order_type, ml + usable_w / 2, y, usable_w / 2)
    y -= row_h
    kv("Patient Type:", _s(o.get("patient_type")), ml, y, usable_w)
    kv(
        "Medical Service:",
        _s(o.get("medical_service")),
        ml + usable_w / 2,
        y,
        usable_w / 2,
    )
    y -= row_h
    kv("Accommodation:", _s(o.get("accommodation")), ml, y, usable_w)
    kv("Facility:", _s(o.get("facility")), ml + usable_w / 2, y, usable_w / 2)
    y -= row_h
    kv("Future Adm:", _s(o.get("future_admission")), ml, y, usable_w)
    kv("Isolation:", _s(o.get("isolation")), ml + usable_w / 2, y, usable_w / 2)
    y -= row_h
    kv("Auth Status:", _s(o.get("authorization_status")), ml, y, usable_w)
    y -= row_h
    kv_wrap("Diagnosis/Reason:", o.get("dx"), max_chars=110)

    # Admission Processing
    section("Admission Processing")
    kv("Ward:", v.get("ward"), ml, y, usable_w)
    kv("Room No:", v.get("bed_no"), ml + usable_w / 2, y, usable_w / 2)
    y -= row_h
    kv("Type (Processing):", proc_type, ml, y, usable_w)
    kv("Approval No:", v.get("approval_no"), ml + usable_w / 2, y, usable_w / 2)
    y -= row_h
    kv_wrap(
        "Payment Details (Admission):",
        v.get("ip_payment_details") or "-",
        max_chars=115,
    )
    y -= row_h

    # Footer
    c.setFont("Helvetica-Oblique", 8)
    c.drawString(ml, mb, APP_FOOTER_TEXT)

    c.showPage()
    # MRD downtime addendum pages appended at end
    try:
        v_add = _mrd_fetch_visit_for_addendum(cur, visit_id) or visit
        printed_at2, reg_dt2, triage_dt2, discharge_dt2, age2 = (
            _mrd_addendum_context_from_visit(v_add)
        )
        _mrd_draw_addendum_pages(
            c,
            cur=cur,
            visit=v_add,
            visit_id=visit_id,
            age=age2,
            printed_at=printed_at2,
            reg_dt=reg_dt2,
            triage_dt=triage_dt2,
            discharge_dt=discharge_dt2,
            report_label="IP Admission Report",
            include_labs=True,
            include_rads=True,
            include_meds=True,
            include_discharge_snapshot=True,
            page_break_after=False,
        )
    except Exception:
        pass

    c.save()
    buffer.seek(0)

    return Response(
        buffer.getvalue(),
        mimetype="application/pdf",
        headers=_patient_pdf_headers(v, "IPAdmissionReport", visit_id=visit_id),
    )


@app.route("/triage/<visit_id>/pdf")
@login_required
@role_required("reception", "nurse", "doctor", "admin")
def triage_pdf(visit_id):
    """
    Print-friendly ED Triage Sheet PDF.
    Layout updated for better readability when printed (boxed sections, table vitals, ID image in header area).
    """
    db = get_db()
    cur = db.cursor()

    visit = cur.execute(
        """
        SELECT v.*,
               p.name, p.mrn, p.id_number, p.phone,
               p.insurance, p.insurance_no,
               p.dob, p.sex, p.nationality
        FROM visits v
        JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
    """,
        (visit_id,),
    ).fetchone()

    if not visit:
        return "Not found", 404

    def _v(key, default=None):
        try:
            return visit[key]
        except Exception:
            return default

    # Triage time (fallback to created_at) - displayed in hospital local time
    triage_ts = _v("triage_time") or _v("created_at", "-")
    triage_time = format_dt_local(triage_ts) or (str(triage_ts) if triage_ts else "-")

    printed_at = now_display_str("%Y-%m-%d %H:%M")
    mrn_display = (
        _pdf_resolve_patient_mrn(visit_row=visit, visit_id=visit_id, cur=cur) or "-"
    )

    # Resolve ID / Eligibility attachment for this visit (prefer image so it can render in PDF)
    id_image_path = get_visit_id_photo_path(cur, visit_id)

    # Keep the latest non-lab/non-rad attachment filename for messaging (PDFs cannot be rendered as images)
    id_doc_filename = None
    try:
        row = cur.execute(
            """
            SELECT filename
              FROM attachments
             WHERE visit_id=?
               AND filename NOT LIKE '%_LAB_%'
               AND filename NOT LIKE '%_RAD_%'
             ORDER BY id DESC
             LIMIT 1
            """,
            (visit_id,),
        ).fetchone()
        id_doc_filename = _fetch_one_val(row, "filename", 0)
    except Exception:
        id_doc_filename = None

    # -----------------------
    # PDF canvas & helpers
    # -----------------------
    buffer = io.BytesIO()
    c = _pdf_attach_patient_mrn_stamp(
        canvas.Canvas(buffer, pagesize=A4), visit_row=visit, visit_id=visit_id, cur=cur
    )
    width, height = A4

    ml = 1.3 * cm
    mr = 1.3 * cm
    mt = 1.2 * cm
    mb = 1.2 * cm

    usable_w = width - ml - mr
    y_top = height - mt

    def _s(val, default="-"):
        if val is None:
            return default
        s = str(val).strip()
        return s if s else default

    def _wrap_lines(text, max_chars):
        """Return list of wrapped lines (preserves explicit newlines)."""
        out = []
        txt = _s(text, "-")
        for raw in str(txt).splitlines():
            raw = raw.rstrip()
            if raw == "":
                out.append("")
                continue
            out.extend(textwrap.wrap(raw, max_chars) or [""])
        return out or ["-"]

    def _draw_cat_badge(x, y, cat_text):
        cat = normalize_esi_cat((cat_text or "").upper().strip())
        label = display_esi_cat(cat) if cat else "-"
        badge_w = 2.1 * cm
        badge_h = 0.75 * cm
        col = colors.grey
        if cat == "ES1":
            col = colors.red
        elif cat == "ES2":
            col = colors.orange
        elif cat == "ES3":
            col = colors.HexColor("#F5C542")  # amber/yellow-ish
        elif cat == "ES4":
            col = colors.green
        elif cat == "ES5":
            col = colors.HexColor("#0AA66E")  # darker green

        c.setFillColor(col)
        c.setStrokeColor(col)
        c.rect(x, y, badge_w, badge_h, fill=1, stroke=1)
        c.setFillColor(colors.white if cat in ("ES1", "ES4", "ES5") else colors.black)
        c.setFont("Helvetica-Bold", 11)
        c.drawCentredString(x + badge_w / 2, y + 0.23 * cm, label)
        c.setFillColor(colors.black)
        c.setStrokeColor(colors.black)
        return badge_w, badge_h

    def _draw_header():
        nonlocal y_top
        header_h = 1.25 * cm
        y0 = y_top - header_h

        # Outer header bar
        c.setStrokeColor(colors.black)
        c.setFillColor(colors.lightgrey)
        c.rect(ml, y0, usable_w, header_h, stroke=1, fill=1)

        # Title
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 14)
        c.drawString(ml + 0.25 * cm, y0 + 0.42 * cm, "ED TRIAGE SHEET")

        # CAT badge at far right
        badge_x = ml + usable_w - 2.1 * cm - 0.2 * cm
        badge_y = y0 + (header_h - 0.75 * cm) / 2
        _draw_cat_badge(badge_x, badge_y, _v("triage_cat"))

        # Visit / Printed info (right-aligned just left of badge)
        c.setFont("Helvetica", 8.5)
        info_right = badge_x - 0.15 * cm
        c.drawRightString(info_right, y0 + 0.72 * cm, f"Case No: {_s(_v('visit_id'))}")
        c.drawRightString(
            info_right, y0 + 0.30 * cm, f"MRN: {mrn_display}  |  Printed: {printed_at}"
        )

        y_top = y0 - 0.35 * cm

    def _draw_box_with_title(x, y_top_box, w, h, title):
        """
        Draw a rectangle box with a small shaded title bar.
        y_top_box is the TOP of the box.
        """
        bar_h = 0.55 * cm
        y_bottom = y_top_box - h

        # Outer border
        c.setStrokeColor(colors.black)
        c.setFillColor(colors.white)
        c.rect(x, y_bottom, w, h, stroke=1, fill=0)

        # Title bar
        c.setFillColor(colors.whitesmoke)
        c.rect(x, y_top_box - bar_h, w, bar_h, stroke=0, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 9.5)
        c.drawString(x + 0.2 * cm, y_top_box - bar_h + 0.17 * cm, title)

        return y_bottom, bar_h

    def _draw_section(
        x,
        y_top_sec,
        w,
        title,
        lines,
        font_size=9,
        max_chars=115,
        line_h=0.42 * cm,
        min_content_h=0.9 * cm,
    ):
        """
        Draw a boxed section (title bar + content) and return next y_top.
        """
        nonlocal y_top
        bar_h = 0.6 * cm
        wrapped = []
        for ln in lines:
            wrapped.extend(_wrap_lines(ln, max_chars))
        wrapped = wrapped or ["-"]

        content_h = max(min_content_h, (len(wrapped) * line_h) + 0.35 * cm)
        total_h = bar_h + content_h
        y_bottom = y_top_sec - total_h

        # If we don't have enough space, start a new page (simple continuation)
        if y_bottom < mb + 1.2 * cm:
            c.showPage()
            y_top = height - mt
            _draw_header()
            y_top_sec = y_top
            y_bottom = y_top_sec - total_h

        # Outer border
        c.setStrokeColor(colors.black)
        c.setFillColor(colors.white)
        c.rect(x, y_bottom, w, total_h, stroke=1, fill=0)

        # Title bar
        c.setFillColor(colors.whitesmoke)
        c.rect(x, y_top_sec - bar_h, w, bar_h, stroke=0, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 10)
        c.drawString(x + 0.2 * cm, y_top_sec - bar_h + 0.18 * cm, title)

        # Content
        tx = x + 0.2 * cm
        ty = y_top_sec - bar_h - 0.32 * cm
        c.setFont("Helvetica", font_size)
        for ln in wrapped:
            c.drawString(tx, ty, ln[:200])
            ty -= line_h

        return y_bottom - 0.35 * cm

    # -----------------------
    # Header + Top boxes
    # -----------------------
    _draw_header()

    gap = 0.35 * cm
    id_box_w = 7.6 * cm
    top_boxes_h = 5.6 * cm
    patient_box_w = usable_w - id_box_w - gap

    patient_x = ml
    id_x = ml + patient_box_w + gap

    # Patient/Visit box
    patient_bottom, bar_h = _draw_box_with_title(
        patient_x, y_top, patient_box_w, top_boxes_h, "Patient & Case No"
    )
    pad = 0.25 * cm
    lx = patient_x + pad
    rx = patient_x + (patient_box_w / 2) + pad / 2
    line_h = 0.42 * cm
    y = y_top - bar_h - 0.30 * cm

    c.setFont("Helvetica", 9)

    # Row 1: Visit & Queue
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(lx, y, "Case No:")
    c.setFont("Helvetica", 9)
    c.drawString(lx + 1.5 * cm, y, _s(_v("visit_id")))
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(rx, y, "Queue:")
    c.setFont("Helvetica", 9)
    c.drawString(rx + 1.5 * cm, y, _s(_v("queue_no"), "-"))
    y -= line_h

    # Row 2: Patient Name (wrapped across full box)
    name_lines = _wrap_lines(_s(_v("name")), 50)
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(lx, y, "Patient:")
    c.setFont("Helvetica", 9)
    if name_lines:
        c.drawString(lx + 1.5 * cm, y, name_lines[0])
        y -= line_h
        for extra in name_lines[1:]:
            c.drawString(lx + 1.5 * cm, y, extra)
            y -= line_h
    else:
        c.drawString(lx + 1.5 * cm, y, "-")
        y -= line_h

    # Row 3: MRN (full row)
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(lx, y, "MRN:")
    c.setFont("Helvetica", 9)
    c.drawString(lx + 1.5 * cm, y, mrn_display)
    y -= line_h

    # Row 4: ID + Phone
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(lx, y, "ID No:")
    c.setFont("Helvetica", 9)
    c.drawString(lx + 1.5 * cm, y, _s(_v("id_number")))
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(rx, y, "Phone:")
    c.setFont("Helvetica", 9)
    c.drawString(rx + 1.5 * cm, y, _s(_v("phone")))
    y -= line_h

    # Row 4: DOB + Sex
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(lx, y, "DOB:")
    c.setFont("Helvetica", 9)
    c.drawString(lx + 1.5 * cm, y, _s(_v("dob")))
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(rx, y, "Sex:")
    c.setFont("Helvetica", 9)
    c.drawString(rx + 1.5 * cm, y, _s(_v("sex")))
    y -= line_h

    # Row 5: Nationality + Insurance
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(lx, y, "Nat:")
    c.setFont("Helvetica", 9)
    c.drawString(lx + 1.5 * cm, y, _s(_v("nationality")))
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(rx, y, "Ins:")
    c.setFont("Helvetica", 9)
    ins_lines = _wrap_lines(_s(_v("insurance")), 32)
    if ins_lines:
        c.drawString(rx + 1.5 * cm, y, ins_lines[0])
        y -= line_h
        for extra in ins_lines[1:]:
            c.drawString(rx + 1.5 * cm, y, extra)
            y -= line_h
        y += (
            line_h  # compensate because loop already moved y too far for the shared row
        )
    else:
        c.drawString(rx + 1.5 * cm, y, "-")
    y -= line_h

    # Row 6: Insurance No + Triage time
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(lx, y, "Ins No:")
    c.setFont("Helvetica", 9)
    c.drawString(lx + 1.5 * cm, y, _s(_v("insurance_no")))
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(rx, y, "Triage:")
    c.setFont("Helvetica", 9)
    c.drawString(rx + 1.5 * cm, y, _s(triage_time))
    y -= line_h

    # Row 7: Allergy status quick hint
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(lx, y, "Allergy:")
    alg = _s(_v("allergy_status"))
    c.setFont("Helvetica", 9)
    c.drawString(lx + 1.5 * cm, y, alg)
    # Bed No (from Location / Bed)
    c.setFont("Helvetica-Bold", 8.2)
    c.drawString(rx, y, "Bed:")
    c.setFont("Helvetica", 9)
    c.drawString(rx + 1.5 * cm, y, _s(_v("bed_no") or _v("bed_number") or _v("bed")))

    # ID / Eligibility box (top right)
    id_bottom, id_bar_h = _draw_box_with_title(
        id_x, y_top, id_box_w, top_boxes_h, "ID / Eligibility Attachment"
    )
    img_pad = 0.25 * cm
    img_area_x = id_x + img_pad
    img_area_y = id_bottom + img_pad
    img_area_w = id_box_w - 2 * img_pad
    img_area_h = top_boxes_h - id_bar_h - 2 * img_pad

    if id_image_path:
        try:
            c.drawImage(
                id_image_path,
                img_area_x,
                img_area_y,
                width=img_area_w,
                height=img_area_h,
                preserveAspectRatio=True,
                anchor="c",
                mask="auto",
            )
        except Exception:
            c.setFont("Helvetica-Oblique", 8)
            c.drawString(
                img_area_x, img_area_y + img_area_h / 2, "Attachment is not an image."
            )
    else:
        c.setFont("Helvetica-Oblique", 8)
        msg_lines = []
        if id_doc_filename:
            try:
                ext = os.path.splitext(str(id_doc_filename))[1].lower()
            except Exception:
                ext = ""
            p = resolve_upload_path(id_doc_filename)
            if p:
                if ext == ".pdf":
                    msg_lines = _wrap_lines(f"Attachment (PDF): {id_doc_filename}", 45)
                    msg_lines += _wrap_lines(
                        "PDF cannot be embedded in this printout.", 45
                    )
                else:
                    msg_lines = _wrap_lines(f"Attachment: {id_doc_filename}", 45)
            else:
                msg_lines = _wrap_lines(
                    f"Attachment record found but file missing: {id_doc_filename}", 45
                )
        else:
            msg_lines = ["No ID attachment uploaded."]

        yy = img_area_y + img_area_h - 0.6 * cm
        for ln in (msg_lines or [])[:5]:
            c.drawString(img_area_x, yy, str(ln)[:95])
            yy -= 0.35 * cm

    # Move below top boxes
    y_top = min(patient_bottom, id_bottom) - 0.45 * cm

    # -----------------------
    # Chief Complaint
    # -----------------------
    y_top = _draw_section(
        ml,
        y_top,
        usable_w,
        "Chief Complaint",
        [_v("comment") or "-"],
        font_size=9,
        max_chars=120,
        line_h=0.42 * cm,
        min_content_h=1.0 * cm,
    )

    # -----------------------
    # Allergy (details)
    # -----------------------
    allergy_lines = [f"Status: {_s(_v('allergy_status'))}"]
    if _v("allergy_details"):
        allergy_lines.append(f"Details: {_s(_v('allergy_details'))}")
    y_top = _draw_section(
        ml,
        y_top,
        usable_w,
        "Allergy",
        allergy_lines,
        font_size=9,
        max_chars=120,
        line_h=0.40 * cm,
        min_content_h=0.8 * cm,
    )

    # -----------------------
    # Vital Signs (grid)
    # -----------------------
    vit_h = 2.6 * cm
    if y_top - vit_h < mb + 1.2 * cm:
        c.showPage()
        y_top = height - mt
        _draw_header()

    table_top = y_top
    table_bottom = table_top - vit_h

    c.setStrokeColor(colors.black)
    c.rect(ml, table_bottom, usable_w, vit_h, stroke=1, fill=0)

    # Header band inside the vitals box
    band_h = 0.55 * cm
    c.setFillColor(colors.whitesmoke)
    c.rect(ml, table_top - band_h, usable_w, band_h, stroke=0, fill=1)
    c.setFillColor(colors.black)
    c.setFont("Helvetica-Bold", 10)
    c.drawString(ml + 0.2 * cm, table_top - band_h + 0.18 * cm, "Vital Signs")

    # Grid area below header band
    grid_top = table_top - band_h
    grid_h = vit_h - band_h
    cols = 4
    rows = 2
    cell_w = usable_w / cols
    cell_h = grid_h / rows

    # Draw grid lines
    for i in range(1, cols):
        x = ml + i * cell_w
        c.line(x, table_bottom, x, grid_top)
    c.line(ml, table_bottom + cell_h, ml + usable_w, table_bottom + cell_h)

    def _cell(col, row, label, value):
        x0 = ml + col * cell_w
        y0 = grid_top - (row + 1) * cell_h
        # label
        c.setFont("Helvetica", 7.5)
        c.setFillColor(colors.black)
        c.drawString(x0 + 0.18 * cm, y0 + cell_h - 0.42 * cm, label)
        # value
        c.setFont("Helvetica-Bold", 10)
        c.drawString(x0 + 0.18 * cm, y0 + 0.30 * cm, _s(value))

    _cell(0, 0, "Pulse (bpm)", _v("pulse_rate"))
    _cell(1, 0, "Resp (/min)", _v("resp_rate"))
    _cell(2, 0, "BP (mmHg)", f"{_s(_v('bp_systolic'))}/{_s(_v('bp_diastolic'))}")
    _cell(3, 0, "Temp (°C)", _v("temperature"))

    _cell(0, 1, "SpO2 (%)", _v("spo2"))
    _cell(1, 1, "Pain (/10)", _v("pain_score"))
    _cell(2, 1, "Weight / Height", f"{_s(_v('weight'))} kg / {_s(_v('height'))}")
    _cell(3, 1, "Consciousness", _v("consciousness_level"))

    y_top = table_bottom - 0.45 * cm

    # ------------------------------------------------------------
    # Additional paper-form fields (Arrival / ESI / Assessments)
    # ------------------------------------------------------------
    facility = _v("facility")
    triage_date = _v("triage_date")
    triage_clock = _v("triage_clock")

    arrival_mode = _v("arrival_mode")
    arrival_other = _v("arrival_other")
    caregiver_type = _v("caregiver_type")
    caregiver_names = _v("caregiver_names")

    stroke_signs = _v("stroke_signs")
    stroke_specify = _v("stroke_specify")

    wong_baker_score = _v("wong_baker_score")
    nips_score = _v("nips_score")

    fall_risk = _v("fall_risk")
    fall_risk_tool = _v("fall_risk_tool")
    fall_risk_score = _v("fall_risk_score")

    pregnancy_status = _v("pregnancy_status")
    lmp = _v("lmp")

    immediate_life_saving = _v("immediate_life_saving")
    high_risk_situation = _v("high_risk_situation")
    resources_needed = _v("resources_needed")
    danger_zone_vitals = _v("danger_zone_vitals")

    orientation = _v("orientation")
    orientation_other = _v("orientation_other")
    work_of_breathing = _v("work_of_breathing")
    work_breathing_other = _v("work_breathing_other")
    respiratory_pattern = _v("respiratory_pattern")
    resp_pattern_other = _v("resp_pattern_other")

    phq_total = _v("phq_total")
    travel_history = _v("travel_history")
    travel_location = _v("travel_location")
    contact_travel_history = _v("contact_travel_history")
    contact_travel_location = _v("contact_travel_location")
    exposure_comm_disease = _v("exposure_comm_disease")
    exposure_details = _v("exposure_details")
    infectious_symptoms = _v("infectious_symptoms")
    pre_arrival_interventions = _v("pre_arrival_interventions")
    triage_interventions = _v("triage_interventions")
    other_notes = _v("other_notes")

    left_lines = []
    right_lines = []

    if facility or triage_date or triage_clock:
        left_lines.append(
            f"Facility: {_s(facility)}   Date: {_s(triage_date)}   Time: {_s(triage_clock)}"
        )

    if arrival_mode or arrival_other:
        s = f"Mode of Arrival: {_s(arrival_mode)}"
        if arrival_other:
            s += f" (Other: {_s(arrival_other)})"
        left_lines.append(s)

    if caregiver_type or caregiver_names:
        s = f"Primary Caregiver: {_s(caregiver_type)}"
        if caregiver_names:
            s += f" (Name/s: {_s(caregiver_names)})"
        left_lines.append(s)

    if stroke_signs or stroke_specify:
        s = f"Stroke signs/symptoms: {_s(stroke_signs)}"
        if stroke_specify:
            s += f" (Specify: {_s(stroke_specify)})"
        left_lines.append(s)

    if wong_baker_score or nips_score:
        left_lines.append(
            f"Wong-Baker: {_s(wong_baker_score)}   NIPS: {_s(nips_score)}"
        )

    if fall_risk or fall_risk_tool or fall_risk_score:
        s = f"Fall Risk: {_s(fall_risk)}"
        extra = []
        if fall_risk_tool:
            extra.append(f"Tool: {_s(fall_risk_tool)}")
        if fall_risk_score:
            extra.append(f"Score: {_s(fall_risk_score)}")
        if extra:
            s += " (" + ", ".join(extra) + ")"
        left_lines.append(s)

    if pregnancy_status or lmp:
        s = f"Pregnancy: {_s(pregnancy_status)}"
        if lmp:
            s += f" (LMP: {_s(lmp)})"
        left_lines.append(s)

    if (
        immediate_life_saving
        or high_risk_situation
        or resources_needed
        or danger_zone_vitals
    ):
        left_lines.append("ESI Screening:")
        left_lines.append(f"- Life-saving intervention: {_s(immediate_life_saving)}")
        left_lines.append(
            f"- High risk / severe pain/distress: {_s(high_risk_situation)}"
        )
        left_lines.append(f"- Resources needed: {_s(resources_needed)}")
        left_lines.append(f"- Danger zone vitals: {_s(danger_zone_vitals)}")

    if orientation or orientation_other:
        s = f"Orientation: {_s(orientation)}"
        if orientation_other:
            s += f" (Other: {_s(orientation_other)})"
        right_lines.append(s)

    if work_of_breathing or work_breathing_other:
        s = f"Work of Breathing: {_s(work_of_breathing)}"
        if work_breathing_other:
            s += f" (Other: {_s(work_breathing_other)})"
        right_lines.append(s)

    if respiratory_pattern or resp_pattern_other:
        s = f"Respiratory Pattern: {_s(respiratory_pattern)}"
        if resp_pattern_other:
            s += f" (Other: {_s(resp_pattern_other)})"
        right_lines.append(s)

    if phq_total:
        right_lines.append(f"PHQ Total Score: {_s(phq_total)}")

    if travel_history or travel_location:
        s = f"Recent Travel: {_s(travel_history)}"
        if travel_location:
            s += f" (Location: {_s(travel_location)})"
        right_lines.append(s)

    if contact_travel_history or contact_travel_location:
        s = f"Contact Travel: {_s(contact_travel_history)}"
        if contact_travel_location:
            s += f" (Location: {_s(contact_travel_location)})"
        right_lines.append(s)

    if exposure_comm_disease or exposure_details:
        s = f"Exposure to communicable disease: {_s(exposure_comm_disease)}"
        if exposure_details:
            s += f" (Details: {_s(exposure_details)})"
        right_lines.append(s)

    if infectious_symptoms:
        right_lines.append(f"Infectious symptoms: {_s(infectious_symptoms)}")

    if pre_arrival_interventions:
        right_lines.append(
            f"Pre-Arrival Interventions: {_s(pre_arrival_interventions)}"
        )
    if triage_interventions:
        right_lines.append(f"Triage Interventions: {_s(triage_interventions)}")
    if other_notes:
        right_lines.append(f"Other Notes: {_s(other_notes)}")

    if not left_lines and not right_lines:
        left_lines = ["-"]

    # Draw Additional Assessment section as 2-column box
    bar_h = 0.6 * cm
    col_gap = 0.4 * cm
    col_w = (usable_w - col_gap) / 2
    max_chars_col = 60
    line_h2 = 0.38 * cm

    # Estimate height (based on wrapped line count)
    def _count(lines):
        n = 0
        for ln in lines or []:
            ln = _s(ln, "")
            if ln == "":
                n += 1
            else:
                n += max(1, len(textwrap.wrap(ln, max_chars_col)))
        return n

    n1 = _count(left_lines)
    n2 = _count(right_lines)
    content_h = max(1.0 * cm, (max(n1, n2) * line_h2) + 0.30 * cm)
    total_h = bar_h + content_h

    # New page if needed
    if y_top - total_h < mb + 1.2 * cm:
        c.showPage()
        y_top = height - mt
        _draw_header()

    sec_top = y_top
    sec_bottom = sec_top - total_h

    c.setStrokeColor(colors.black)
    c.setFillColor(colors.white)
    c.rect(ml, sec_bottom, usable_w, total_h, stroke=1, fill=0)

    # Title bar
    c.setFillColor(colors.whitesmoke)
    c.rect(ml, sec_top - bar_h, usable_w, bar_h, stroke=0, fill=1)
    c.setFillColor(colors.black)
    c.setFont("Helvetica-Bold", 10)
    c.drawString(ml + 0.2 * cm, sec_top - bar_h + 0.18 * cm, "Additional Assessment")

    # Column divider
    c.setStrokeColor(colors.lightgrey)
    c.line(ml + col_w, sec_bottom, ml + col_w, sec_top - bar_h)
    c.setStrokeColor(colors.black)

    # Draw columns
    c.setFont("Helvetica", 8.5)
    x1 = ml + 0.2 * cm
    x2 = ml + col_w + col_gap + 0.2 * cm
    y1 = sec_top - bar_h - 0.32 * cm
    y2 = y1

    def _draw_col(lines, x, y_start):
        yv = y_start
        for ln in lines or []:
            ln = _s(ln, "")
            if ln == "":
                yv -= line_h2
                continue
            wrapped = textwrap.wrap(ln, max_chars_col) or [""]
            for wln in wrapped:
                c.drawString(x, yv, wln[:200])
                yv -= line_h2
        return yv

    _draw_col(left_lines, x1, y1)
    _draw_col(right_lines, x2, y2)

    # Footer
    c.setFont("Helvetica-Oblique", 8)
    c.setFillColor(colors.black)
    c.drawString(ml, mb - 0.35 * cm, APP_FOOTER_TEXT)

    # MRD addendum should be page 2 for ED TRIAGE SHEET (keep the original triage page as page 1)
    try:
        v_add = _mrd_fetch_visit_for_addendum(cur, visit_id) or visit
        printed_at2, reg_dt2, triage_dt2, discharge_dt2, age2 = (
            _mrd_addendum_context_from_visit(v_add)
        )
        c.showPage()
        _mrd_draw_addendum_pages(
            c,
            cur=cur,
            visit=v_add,
            visit_id=visit_id,
            age=age2,
            printed_at=printed_at2,
            reg_dt=reg_dt2,
            triage_dt=triage_dt2,
            discharge_dt=discharge_dt2,
            report_label="ED Triage Sheet",
            include_labs=False,
            include_rads=False,
            include_meds=False,
            include_discharge_snapshot=False,
            page_break_after=False,
        )
    except Exception:
        # If addendum fails, still return the triage PDF (without addendum)
        pass

    c.save()
    buffer.seek(0)
    return Response(
        buffer.getvalue(),
        mimetype="application/pdf",
        headers=_patient_pdf_headers(visit, "Triage", visit_id=visit_id),
    )


@app.route("/lab_results/<visit_id>/pdf")
@login_required
@role_required("nurse", "doctor", "admin", "lab", "radiology")
def lab_results_pdf(visit_id):
    """
    Print-friendly Lab Results PDF (boxed layout similar to ED TRIAGE SHEET).
    """
    db = get_db()
    cur = db.cursor()

    visit = cur.execute(
        """
        SELECT v.visit_id,
               p.name,
               p.mrn,
               p.id_number,
               p.phone,
               p.dob,
               p.sex,
               p.insurance,
               p.insurance_no,
               v.created_at AS visit_created_at,
               v.triage_time,
               v.closed_at,
               v.status,
               v.created_by,
               v.closed_by
        FROM visits v
        JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
    """,
        (visit_id,),
    ).fetchone()

    if not visit:
        return "Not found", 404

    labs_raw = cur.execute(
        """
        SELECT * FROM lab_requests
        WHERE visit_id=?
        ORDER BY id ASC
    """,
        (visit_id,),
    ).fetchall()

    # Enrich for doctor-friendly display (units + reference range by age/sex)
    patient_dob = ""
    patient_sex = ""
    try:
        if isinstance(visit, dict):
            patient_dob = visit.get("dob") or ""
            patient_sex = visit.get("sex") or ""
        else:
            patient_dob = (
                visit["dob"]
                if visit and hasattr(visit, "keys") and "dob" in visit.keys()
                else ""
            )
            patient_sex = (
                visit["sex"]
                if visit and hasattr(visit, "keys") and "sex" in visit.keys()
                else ""
            )
    except Exception:
        pass

    labs = []
    for _l in labs_raw:
        d = dict(_l)
        enrich_lab_request_row(d, patient_dob=patient_dob, patient_sex=patient_sex)
        labs.append(d)

    # -----------------------
    # PDF canvas & helpers
    # -----------------------
    buffer = io.BytesIO()
    c = _pdf_attach_patient_mrn_stamp(
        canvas.Canvas(buffer, pagesize=A4), visit_row=visit, visit_id=visit_id, cur=cur
    )
    width, height = A4

    ml = 1.3 * cm
    mr = 1.3 * cm
    mt = 1.2 * cm
    mb = 1.2 * cm

    usable_w = width - ml - mr
    y_top = height - mt

    printed_at = now_display_str("%Y-%m-%d %H:%M")
    mrn_display = (
        _pdf_resolve_patient_mrn(visit_row=visit, visit_id=visit_id, cur=cur) or "-"
    )

    def _s(val, default="-"):
        if val is None:
            return default
        s = str(val).strip()
        return s if s else default

    def _normalize_line(ln):
        """
        Allow section lines to be either:
          - "text"
          - ("text", reportlab_color)
        """
        try:
            if isinstance(ln, tuple) and len(ln) == 2:
                return (str(ln[0] or ""), ln[1] or colors.black)
        except Exception:
            pass
        return (str(ln or ""), colors.black)

    def _draw_header():
        nonlocal y_top
        header_h = 1.25 * cm
        y0 = y_top - header_h

        # Outer header bar
        c.setStrokeColor(colors.black)
        c.setFillColor(colors.lightgrey)
        c.rect(ml, y0, usable_w, header_h, stroke=1, fill=1)

        # Title
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 14)
        c.drawString(ml + 0.25 * cm, y0 + 0.42 * cm, "LAB RESULTS")

        # Visit / Printed info (right-aligned)
        c.setFont("Helvetica", 8.5)
        info_right = ml + usable_w - 0.25 * cm
        c.drawRightString(
            info_right, y0 + 0.72 * cm, f"Case No: {_s(visit['visit_id'])}"
        )
        c.drawRightString(
            info_right, y0 + 0.30 * cm, f"MRN: {mrn_display}  |  Printed: {printed_at}"
        )

        y_top = y0 - 0.35 * cm

    def _draw_section(
        x,
        y_top_sec,
        w,
        title,
        lines,
        font_size=9,
        max_chars=115,
        line_h=0.42 * cm,
        min_content_h=0.9 * cm,
    ):
        """
        Draw a boxed section (title bar + wrapped content) and return next y_top.
        """
        nonlocal y_top
        bar_h = 0.6 * cm

        wrapped = []
        for ln in lines:
            txt, col = _normalize_line(ln)
            for raw in str(txt).splitlines() if str(txt) != "" else [""]:
                raw = raw.rstrip()
                if raw == "":
                    wrapped.append(("", col))
                    continue
                for part in textwrap.wrap(raw, max_chars) or [""]:
                    wrapped.append((part, col))

        wrapped = wrapped or [("-", colors.black)]

        content_h = max(min_content_h, (len(wrapped) * line_h) + 0.35 * cm)
        total_h = bar_h + content_h
        y_bottom = y_top_sec - total_h

        # If we don't have enough space, start a new page (repeat header)
        if y_bottom < mb + 1.2 * cm:
            c.showPage()
            y_top = height - mt
            _draw_header()
            y_top_sec = y_top
            y_bottom = y_top_sec - total_h

        # Outer border
        c.setStrokeColor(colors.black)
        c.setFillColor(colors.white)
        c.rect(x, y_bottom, w, total_h, stroke=1, fill=0)

        # Title bar
        c.setFillColor(colors.whitesmoke)
        c.rect(x, y_top_sec - bar_h, w, bar_h, stroke=0, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 10)
        c.drawString(x + 0.2 * cm, y_top_sec - bar_h + 0.18 * cm, title)

        # Content
        tx = x + 0.2 * cm
        ty = y_top_sec - bar_h - 0.32 * cm
        c.setFont("Helvetica", font_size)
        for ln, col in wrapped:
            if ln == "":
                ty -= line_h
                continue
            c.setFillColor(col or colors.black)
            c.drawString(tx, ty, ln[:200])
            ty -= line_h
        c.setFillColor(colors.black)

        return y_bottom - 0.35 * cm

    # -----------------------
    # Build PDF
    # -----------------------
    _draw_header()

    reg_dt = format_dt_local(visit["visit_created_at"]) or _s(visit["visit_created_at"])
    triage_dt = format_dt_local(visit["triage_time"])
    discharge_dt = format_dt_local(visit["closed_at"])
    age = calc_age(visit["dob"])

    patient_lines = [
        f"Patient: {_s(visit['name'])}",
        f"Age: {_s(age) if age else '-'}",
        f"MRN / ID: {mrn_display} / {_s(visit['id_number'])}",
        f"Phone: {_s(visit['phone'])}",
        f"DOB / Sex: {_s(visit['dob'])} / {_s(visit['sex'])}",
        f"Insurance: {_s(visit['insurance'])}",
        f"Registered: {_s(reg_dt)}",
        f"Triage: {_s(triage_dt)}",
        f"Discharge: {_s(discharge_dt)}",
        f"Status: {_s(visit['status'])}",
    ]
    y_top = _draw_section(
        ml,
        y_top,
        usable_w,
        "Patient & Case No",
        patient_lines,
        font_size=9,
        max_chars=120,
    )

    if not labs:
        y_top = _draw_section(
            ml,
            y_top,
            usable_w,
            "Results",
            ["No lab requests/results for this visit."],
            font_size=9,
        )
    else:
        for l in labs:
            # Abnormal results detection (simple heuristic)
            abn = False
            rt = str(l["result_text"] or "").strip()
            rt_low = rt.lower()

            if rt and (
                "high" in rt_low
                or "low" in rt_low
                or "crit" in rt_low
                or "abnormal" in rt_low
                or "positive" in rt_low
                or "pos " in rt_low
                or "pos." in rt_low
                or "مرتفع" in rt_low
                or "منخفض" in rt_low
                or "ايجابي" in rt_low
                or "إيجابي" in rt_low
            ):
                abn = True

            sec_title = f"Lab #{l['id']} - {l['test_name']}"

            lines = [f"Status: {_s(l['status'])}"]
            if rt:
                lines.append((f"Result: {rt}", colors.red if abn else colors.black))

            # Reference range / units / CPT (if configured)
            meta_parts = []
            if l.get("catalog_units"):
                meta_parts.append(f"Unit: {l.get('catalog_units')}")
            if l.get("catalog_ref"):
                meta_parts.append(f"Ref: {l.get('catalog_ref')}")
            if l.get("catalog_cpt"):
                meta_parts.append(f"CPT: {l.get('catalog_cpt')}")
            if meta_parts:
                lines.append((" | ".join(meta_parts), colors.grey))

            details = []
            if l["requested_at"]:
                details.append(
                    f"Req: {format_dt_local(l['requested_at']) or l['requested_at']} by {_staff_display_with_ids(cur, l['requested_by'] or '-')}"
                )
            if l["received_at"]:
                details.append(
                    f"Sample: {format_dt_local(l['received_at']) or l['received_at']} by {_staff_display_with_ids(cur, l['received_by'] or '-')}"
                )
            if l["reported_at"]:
                details.append(
                    f"Reported: {format_dt_local(l['reported_at']) or l['reported_at']} by {_staff_display_with_ids(cur, l['reported_by'] or '-')}"
                )
            if details:
                lines.append(" | ".join(details))

            y_top = _draw_section(
                ml, y_top, usable_w, sec_title, lines, font_size=9, max_chars=120
            )

    # Footer
    c.setFont("Helvetica-Oblique", 8)
    c.drawString(ml, 1.2 * cm, APP_FOOTER_TEXT)

    c.showPage()
    # MRD downtime addendum pages appended at end
    try:
        v_add = _mrd_fetch_visit_for_addendum(cur, visit_id) or visit
        printed_at2, reg_dt2, triage_dt2, discharge_dt2, age2 = (
            _mrd_addendum_context_from_visit(v_add)
        )
        _mrd_draw_addendum_pages(
            c,
            cur=cur,
            visit=v_add,
            visit_id=visit_id,
            age=age2,
            printed_at=printed_at2,
            reg_dt=reg_dt2,
            triage_dt=triage_dt2,
            discharge_dt=discharge_dt2,
            report_label="Lab Results",
            include_labs=True,
            include_rads=False,
            include_meds=False,
            include_discharge_snapshot=False,
            page_break_after=False,
        )
    except Exception:
        pass

    c.save()
    buffer.seek(0)

    return Response(
        buffer.getvalue(),
        mimetype="application/pdf",
        headers=_patient_pdf_headers(visit, "LabResults", visit_id=visit_id),
    )


@app.route("/radiology_results/<visit_id>/pdf")
@login_required
@role_required("nurse", "doctor", "admin", "lab", "radiology")
def radiology_results_pdf(visit_id):
    """
    Print-friendly Radiology Reports PDF (boxed layout similar to ED TRIAGE SHEET).
    """
    db = get_db()
    cur = db.cursor()

    visit = cur.execute(
        """
        SELECT v.visit_id,
               p.name,
               p.mrn,
               p.id_number,
               p.phone,
               p.dob,
               p.sex,
               p.insurance,
               p.insurance_no,
               v.created_at,
               v.triage_time,
               v.closed_at,
               v.status
        FROM visits v
        JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
    """,
        (visit_id,),
    ).fetchone()

    if not visit:
        return "Not found", 404

    rads = cur.execute(
        """
        SELECT * FROM radiology_requests
        WHERE visit_id=?
        ORDER BY id ASC
    """,
        (visit_id,),
    ).fetchall()

    # Convert sqlite rows to dict for safe .get usage
    rads = [dict(r) for r in (rads or [])]

    # -----------------------
    # PDF canvas & helpers
    # -----------------------
    buffer = io.BytesIO()
    c = _pdf_attach_patient_mrn_stamp(
        canvas.Canvas(buffer, pagesize=A4), visit_row=visit, visit_id=visit_id, cur=cur
    )
    width, height = A4

    ml = 1.3 * cm
    mr = 1.3 * cm
    mt = 1.2 * cm
    mb = 1.2 * cm

    usable_w = width - ml - mr
    y_top = height - mt

    printed_at = now_display_str("%Y-%m-%d %H:%M")
    mrn_display = (
        _pdf_resolve_patient_mrn(visit_row=visit, visit_id=visit_id, cur=cur) or "-"
    )

    def _s(val, default="-"):
        if val is None:
            return default
        s = str(val).strip()
        return s if s else default

    def _normalize_line(ln):
        # Accept either "text" or ("text", color)
        try:
            if isinstance(ln, tuple) and len(ln) == 2:
                return (str(ln[0] or ""), ln[1] or colors.black)
        except Exception:
            pass
        return (str(ln or ""), colors.black)

    def _draw_header():
        nonlocal y_top
        header_h = 1.25 * cm
        y0 = y_top - header_h

        c.setStrokeColor(colors.black)
        c.setFillColor(colors.lightgrey)
        c.rect(ml, y0, usable_w, header_h, stroke=1, fill=1)

        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 14)
        c.drawString(ml + 0.25 * cm, y0 + 0.42 * cm, "RADIOLOGY REPORTS")

        c.setFont("Helvetica", 8.5)
        info_right = ml + usable_w - 0.25 * cm
        c.drawRightString(
            info_right, y0 + 0.72 * cm, f"Case No: {_s(visit['visit_id'])}"
        )
        c.drawRightString(
            info_right, y0 + 0.30 * cm, f"MRN: {mrn_display}  |  Printed: {printed_at}"
        )

        y_top = y0 - 0.35 * cm

    def _draw_section(
        x,
        y_top_sec,
        w,
        title,
        lines,
        font_size=9,
        max_chars=115,
        line_h=0.42 * cm,
        min_content_h=0.9 * cm,
    ):
        nonlocal y_top
        bar_h = 0.6 * cm

        wrapped = []
        for ln in lines:
            txt, col = _normalize_line(ln)
            for raw in str(txt).splitlines() if str(txt) != "" else [""]:
                raw = raw.rstrip()
                if raw == "":
                    wrapped.append(("", col))
                    continue
                for part in textwrap.wrap(raw, max_chars) or [""]:
                    wrapped.append((part, col))
        wrapped = wrapped or [("-", colors.black)]

        content_h = max(min_content_h, (len(wrapped) * line_h) + 0.35 * cm)
        total_h = bar_h + content_h
        y_bottom = y_top_sec - total_h

        if y_bottom < mb + 1.2 * cm:
            c.showPage()
            y_top = height - mt
            _draw_header()
            y_top_sec = y_top
            y_bottom = y_top_sec - total_h

        c.setStrokeColor(colors.black)
        c.setFillColor(colors.white)
        c.rect(x, y_bottom, w, total_h, stroke=1, fill=0)

        c.setFillColor(colors.whitesmoke)
        c.rect(x, y_top_sec - bar_h, w, bar_h, stroke=0, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 10)
        c.drawString(x + 0.2 * cm, y_top_sec - bar_h + 0.18 * cm, title)

        tx = x + 0.2 * cm
        ty = y_top_sec - bar_h - 0.32 * cm
        c.setFont("Helvetica", font_size)
        for ln, col in wrapped:
            if ln == "":
                ty -= line_h
                continue
            c.setFillColor(col or colors.black)
            c.drawString(tx, ty, ln[:200])
            ty -= line_h
        c.setFillColor(colors.black)

        return y_bottom - 0.35 * cm

    # -----------------------
    # Build PDF
    # -----------------------
    _draw_header()

    reg_dt = format_dt_local(visit["created_at"]) or _s(visit["created_at"])
    triage_dt = format_dt_local(visit["triage_time"])
    discharge_dt = format_dt_local(visit["closed_at"])
    age = calc_age(visit["dob"])

    patient_lines = [
        f"Patient: {_s(visit['name'])}",
        f"Age: {_s(age) if age else '-'}",
        f"MRN / ID: {mrn_display} / {_s(visit['id_number'])}",
        f"Phone: {_s(visit['phone'])}",
        f"DOB / Sex: {_s(visit['dob'])} / {_s(visit['sex'])}",
        f"Insurance: {_s(visit['insurance'])}",
        f"Registered: {_s(reg_dt)}",
        f"Triage: {_s(triage_dt)}",
        f"Discharge: {_s(discharge_dt)}",
        f"Status: {_s(visit['status'])}",
    ]
    y_top = _draw_section(
        ml,
        y_top,
        usable_w,
        "Patient & Case No",
        patient_lines,
        font_size=9,
        max_chars=120,
    )

    if not rads:
        y_top = _draw_section(
            ml,
            y_top,
            usable_w,
            "Reports",
            ["No radiology requests/reports for this visit."],
            font_size=9,
        )
    else:
        for r in rads:
            sec_title = f"Study #{r['id']} - {r['test_name']}"
            lines = [f"Status: {_s(r['status'])}"]

            details = []
            if r.get("requested_at"):
                details.append(
                    f"Req: {format_dt_local(r['requested_at']) or r['requested_at']} by {_staff_display_with_ids(cur, r.get('requested_by') or '-')}"
                )
            if r.get("sent_at"):
                details.append(
                    f"Sent: {format_dt_local(r['sent_at']) or r['sent_at']} by {_staff_display_with_ids(cur, r.get('sent_by') or '-')}"
                )
            if r.get("received_at"):
                details.append(
                    f"Received: {format_dt_local(r['received_at']) or r['received_at']} by {_staff_display_with_ids(cur, r.get('received_by') or '-')}"
                )
            proc_at = r.get("in_process_at") or r.get("done_at")
            proc_by = r.get("in_process_by") or r.get("done_by")
            if proc_at:
                details.append(
                    f"Process: {format_dt_local(proc_at) or proc_at} by {_staff_display_with_ids(cur, proc_by or '-')}"
                )
            if r.get("reported_at"):
                details.append(
                    f"Reported: {format_dt_local(r['reported_at']) or r['reported_at']} by {_staff_display_with_ids(cur, r.get('reported_by') or '-')}"
                )
            if details:
                lines.append(" | ".join(details))

            report_txt = str(r["report_text"] or "").strip()
            if report_txt:
                lines.append("")
                lines.append("Report:")
                lines.append(report_txt)
            else:
                lines.append("Report: -")

            y_top = _draw_section(
                ml, y_top, usable_w, sec_title, lines, font_size=9, max_chars=120
            )

    c.setFont("Helvetica-Oblique", 8)
    c.drawString(ml, 1.2 * cm, APP_FOOTER_TEXT)

    c.showPage()
    # MRD downtime addendum pages appended at end
    try:
        v_add = _mrd_fetch_visit_for_addendum(cur, visit_id) or visit
        printed_at2, reg_dt2, triage_dt2, discharge_dt2, age2 = (
            _mrd_addendum_context_from_visit(v_add)
        )
        _mrd_draw_addendum_pages(
            c,
            cur=cur,
            visit=v_add,
            visit_id=visit_id,
            age=age2,
            printed_at=printed_at2,
            reg_dt=reg_dt2,
            triage_dt=triage_dt2,
            discharge_dt=discharge_dt2,
            report_label="Radiology Results",
            include_labs=False,
            include_rads=True,
            include_meds=False,
            include_discharge_snapshot=False,
            page_break_after=False,
        )
    except Exception:
        pass

    c.save()
    buffer.seek(0)

    return Response(
        buffer.getvalue(),
        mimetype="application/pdf",
        headers=_patient_pdf_headers(visit, "RadiologyResults", visit_id=visit_id),
    )


@app.route("/home_med/<visit_id>/pdf")
@login_required
def home_med_pdf(visit_id):
    """
    Print-friendly Home Medication PDF (boxed layout similar to ED TRIAGE SHEET).
    """
    db = get_db()
    cur = db.cursor()

    # 1) Visit data (to resolve doctor name)
    visit = cur.execute(
        """
        SELECT v.visit_id,
               p.name,
               p.mrn,
               p.id_number,
               p.insurance,
               p.insurance_no,
               v.created_at,
               v.created_by,
               v.closed_by
        FROM visits v
        JOIN patients p ON p.id = v.patient_id
        WHERE v.visit_id = ?
    """,
        (visit_id,),
    ).fetchone()

    # 2) Home medication text
    summary = cur.execute(
        """
        SELECT home_medication
        FROM discharge_summaries
        WHERE visit_id = ?
    """,
        (visit_id,),
    ).fetchone()

    if not visit:
        return "Not found", 404

    # 3) Physician name + GD
    doctor_name = _resolve_doctor_name_for_visit(cur, visit, visit_id)
    doctor_display = _doctor_display_with_gd(cur, doctor_name)

    raw_home_med = (
        summary["home_medication"] if summary and summary["home_medication"] else ""
    )
    home_med = format_home_medication_for_print(raw_home_med, default_if_empty="None")

    # -----------------------
    # PDF canvas & helpers
    # -----------------------
    buffer = io.BytesIO()
    c = _pdf_attach_patient_mrn_stamp(
        canvas.Canvas(buffer, pagesize=A4), visit_row=visit, visit_id=visit_id, cur=cur
    )
    width, height = A4

    ml = 1.3 * cm
    mr = 1.3 * cm
    mt = 1.2 * cm
    mb = 1.2 * cm

    usable_w = width - ml - mr
    y_top = height - mt

    printed_at = now_display_str("%Y-%m-%d %H:%M")
    mrn_display = (
        _pdf_resolve_patient_mrn(visit_row=visit, visit_id=visit_id, cur=cur) or "-"
    )

    def _s(val, default="-"):
        if val is None:
            return default
        s = str(val).strip()
        return s if s else default

    def _draw_header():
        nonlocal y_top
        header_h = 1.25 * cm
        y0 = y_top - header_h

        c.setStrokeColor(colors.black)
        c.setFillColor(colors.lightgrey)
        c.rect(ml, y0, usable_w, header_h, stroke=1, fill=1)

        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 14)
        c.drawString(ml + 0.25 * cm, y0 + 0.42 * cm, "HOME MEDICATION")

        c.setFont("Helvetica", 8.5)
        info_right = ml + usable_w - 0.25 * cm
        c.drawRightString(
            info_right, y0 + 0.72 * cm, f"Case No: {_s(visit['visit_id'])}"
        )
        c.drawRightString(
            info_right, y0 + 0.30 * cm, f"MRN: {mrn_display}  |  Printed: {printed_at}"
        )

        y_top = y0 - 0.35 * cm

    def _draw_section(
        x,
        y_top_sec,
        w,
        title,
        text,
        font_size=9,
        max_chars=120,
        line_h=0.42 * cm,
        min_content_h=0.9 * cm,
    ):
        """
        Boxed section with title bar and wrapped content.
        `text` can be a string (multi-line supported) or list of strings.
        """
        nonlocal y_top
        bar_h = 0.6 * cm

        # Normalize content to lines
        lines = []
        if isinstance(text, list):
            for t in text:
                lines.extend(
                    str(t or "").splitlines() if str(t or "").strip() else ["-"]
                )
        else:
            t = str(text or "").strip()
            lines = t.splitlines() if t else ["-"]

        wrapped = []
        for raw in lines:
            raw = (raw or "").rstrip()
            if raw == "":
                wrapped.append("")
                continue
            wrapped.extend(textwrap.wrap(raw, max_chars) or [""])

        wrapped = wrapped or ["-"]

        content_h = max(min_content_h, (len(wrapped) * line_h) + 0.35 * cm)
        total_h = bar_h + content_h
        y_bottom = y_top_sec - total_h

        if y_bottom < mb + 1.2 * cm:
            c.showPage()
            y_top = height - mt
            _draw_header()
            y_top_sec = y_top
            y_bottom = y_top_sec - total_h

        c.setStrokeColor(colors.black)
        c.setFillColor(colors.white)
        c.rect(x, y_bottom, w, total_h, stroke=1, fill=0)

        c.setFillColor(colors.whitesmoke)
        c.rect(x, y_top_sec - bar_h, w, bar_h, stroke=0, fill=1)
        c.setFillColor(colors.black)
        c.setFont("Helvetica-Bold", 10)
        c.drawString(x + 0.2 * cm, y_top_sec - bar_h + 0.18 * cm, title)

        tx = x + 0.2 * cm
        ty = y_top_sec - bar_h - 0.32 * cm
        c.setFont("Helvetica", font_size)
        for ln in wrapped:
            if ln == "":
                ty -= line_h
                continue
            c.drawString(tx, ty, ln[:200])
            ty -= line_h

        return y_bottom - 0.35 * cm

    # -----------------------
    # Build PDF
    # -----------------------
    _draw_header()

    reg_date = format_date_yyyy_mm_dd(visit["created_at"])
    reg_time = format_time_hhmm(visit["created_at"])
    reg_dt = " ".join([x for x in [reg_date, reg_time] if x]).strip() or _s(
        visit["created_at"]
    )

    patient_lines = [
        f"Patient: {_s(visit['name'])}",
        f"MRN / ID: {mrn_display} / {_s(visit['id_number'])}",
        f"Insurance: {_s(visit['insurance'])}",
        f"Registered: {_s(reg_dt)}",
    ]
    y_top = _draw_section(
        ml,
        y_top,
        usable_w,
        "Patient & Case No",
        patient_lines,
        font_size=9,
        max_chars=120,
    )

    med_text = home_med.strip() if home_med and home_med.strip() else "None"
    y_top = _draw_section(
        ml,
        y_top,
        usable_w,
        "Medication",
        med_text,
        font_size=9,
        max_chars=120,
        line_h=0.45 * cm,
        min_content_h=3.0 * cm,
    )

    # Physician name & signature line near bottom
    sig_y = 2.0 * cm
    c.setFont("Helvetica", 9)
    c.drawString(ml, sig_y, f"Physician: {doctor_display}")
    c.drawString(width / 2, sig_y, "Signature: ______________________")

    # Footer
    c.setFont("Helvetica-Oblique", 8)
    c.drawString(ml, 1.2 * cm, APP_FOOTER_TEXT)

    c.showPage()
    # MRD downtime addendum pages appended at end
    try:
        v_add = _mrd_fetch_visit_for_addendum(cur, visit_id) or visit
        printed_at2, reg_dt2, triage_dt2, discharge_dt2, age2 = (
            _mrd_addendum_context_from_visit(v_add)
        )
        _mrd_draw_addendum_pages(
            c,
            cur=cur,
            visit=v_add,
            visit_id=visit_id,
            age=age2,
            printed_at=printed_at2,
            reg_dt=reg_dt2,
            triage_dt=triage_dt2,
            discharge_dt=discharge_dt2,
            report_label="Home Medication",
            include_labs=False,
            include_rads=False,
            include_meds=True,
            include_discharge_snapshot=False,
            page_break_after=False,
        )
    except Exception:
        pass

    c.save()
    buffer.seek(0)

    return Response(
        buffer.getvalue(),
        mimetype="application/pdf",
        headers=_patient_pdf_headers(visit, "HomeMedication", visit_id=visit_id),
    )


