def _xml_escape(s: str) -> str:
    s = "" if s is None else str(s)
    # Minimal XML escaping for text nodes / attributes.
    return (
        s.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
        .replace("'", "&#39;")
    )


def _code128_encode_values_b(value: str):
    """Encode a string into Code128 values using Code Set B only.

    Returns a list of code values including:
    [StartB, data..., checksum, Stop]
    """
    value = "" if value is None else str(value)
    # Start Code B = 104
    codes = [104]

    for ch in value:
        o = ord(ch)
        # Code Set B supports ASCII 32..126
        if o < 32 or o > 126:
            ch = "?"
            o = ord(ch)
        codes.append(o - 32)

    # Checksum: start + Σ(code_i * position) mod 103
    checksum = codes[0]
    for pos, code in enumerate(codes[1:], start=1):
        checksum += code * pos
    checksum %= 103

    codes.append(checksum)
    # Stop Code = 106
    codes.append(106)
    return codes


def _code128_encode_values_auto(value: str):
    """Encode a string into Code128 values (auto mode).

    Why:
      - For numeric-only strings (MRN/ID numbers), Code Set C makes the barcode
        MUCH narrower (pairs of digits) which is more reliable on small labels
        like 5x3 cm.
      - For mixed strings, we fall back to Code Set B.
    """
    value = "" if value is None else str(value)
    value = value.strip()
    if not value:
        return []

    # Numeric-only → prefer Code Set C (denser)
    try:
        if re.fullmatch(r"\d+", value):
            codes = [105]  # Start Code C
            i = 0
            n = len(value)
            while i + 1 < n:
                pair = value[i : i + 2]
                try:
                    codes.append(int(pair))
                except Exception:
                    # fallback if anything unexpected
                    return _code128_encode_values_b(value)
                i += 2

            # Odd number of digits → switch to Code B for the last digit
            if i < n:
                codes.append(100)  # Code B
                o = ord(value[i])
                codes.append(o - 32)

            # Checksum: start + Σ(code_i * position) mod 103
            checksum = codes[0]
            for pos, code in enumerate(codes[1:], start=1):
                checksum += code * pos
            checksum %= 103

            codes.append(checksum)
            codes.append(106)  # Stop
            return codes
    except Exception:
        pass

    # Fallback: Code Set B
    return _code128_encode_values_b(value)


def _code128_svg(value: str, bar_height: int = 30, human_readable: int = 0) -> str:
    """Generate a Code128 barcode as SVG (offline, no external libs).

    Notes:
    - Uses Code Set B only (suitable for IDs like MRN/Visit/Passport).
    - bar_height is in SVG user units (pixels by default).
    """
    value = (value or "").strip()
    if not value:
        return ""

    # Safety limits (keep URL small & fast)
    if len(value) > 120:
        value = value[:120]

    try:
        bar_height = int(bar_height or 30)
    except Exception:
        bar_height = 30
    bar_height = max(12, min(bar_height, 120))

    try:
        human_readable = 1 if int(human_readable or 0) != 0 else 0
    except Exception:
        human_readable = 0

    codes = _code128_encode_values_auto(value)

    quiet = 10  # quiet zone in modules
    module = 1  # module width in SVG units

    total_modules = quiet * 2
    for code in codes:
        try:
            pat = _CODE128_PATTERNS[int(code)]
        except Exception:
            return ""
        total_modules += sum(int(x) for x in pat)

    width = int(total_modules * module)
    text_h = 0
    if human_readable:
        text_h = 14  # extra space for text
    height = int(bar_height + text_h)

    # Build SVG
    x = quiet * module
    rects = []
    for code in codes:
        pat = _CODE128_PATTERNS[int(code)]
        black = True
        for wch in pat:
            w = int(wch) * module
            if black and w > 0:
                rects.append(
                    f'<rect x="{x}" y="0" width="{w}" height="{bar_height}" />'
                )
            x += w
            black = not black

    text_el = ""
    if human_readable:
        # Center text under the bars
        txt = _xml_escape(value)
        # baseline at bar_height + 12
        y = int(bar_height + 12)
        text_el = f'<text x="{width//2}" y="{y}" text-anchor="middle" font-size="12" font-family="Arial, sans-serif">{txt}</text>'

    svg = (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}" shape-rendering="crispEdges">'
        f'<rect width="100%" height="100%" fill="white"/>'
        f'<g fill="black">' + "".join(rects) + f"</g>" + text_el + f"</svg>"
    )
    return svg


@lru_cache(maxsize=2048)
def _barcode_svg_cached(
    value: str, bar_height: int = 30, human_readable: int = 1
) -> str:
    """Cached barcode SVG generator used by /barcode.svg"""
    return _code128_svg(value, bar_height=bar_height, human_readable=human_readable)


@app.route("/barcode.svg")
@login_required
def barcode_svg():
    """Return Code128 barcode as SVG (used by Sticker HTML)."""
    value = (request.args.get("data") or "").strip()
    if not value:
        return "Missing data", 400
    h = request.args.get("h", "30")
    human = request.args.get(
        "human", "0"
    )  # default: no human-readable text (matches old tec-it PNG look)

    try:
        h_int = int(h) if str(h).isdigit() else 30
    except Exception:
        h_int = 30

    human_int = 0 if str(human).lower() in ("0", "false", "no", "n") else 1
    svg = _barcode_svg_cached(value, h_int, human_int)
    if not svg:
        return "Barcode error", 500

    resp = Response(svg, mimetype="image/svg+xml")
    # Cache barcode for a day (reduces CPU on repeated prints). Dynamic pages remain no-store.
    resp.headers["Cache-Control"] = "public, max-age=86400"
    return resp


