    "\n"
    '    <div class="col-md-4">\n'
    '      <label class="form-label fw-bold">Ins. Plan</label>\n'
    '      <input class="form-control" id="ins_plan">\n'
    "    </div>\n"
    "\n"
    '    <div class="col-md-4">\n'
    '      <label class="form-label fw-bold">Policy No</label>\n'
