# =======================================================
# PWA (Add to Home Screen)
#   IMPORTANT: /sw.js must be served from ROOT for proper scope.
@app.route("/manifest.webmanifest")
def pwa_manifest():
    return send_from_directory(
        STATIC_DIR, "manifest.webmanifest", mimetype="application/manifest+json"
    )


@app.route("/sw.js")
def pwa_sw():
    resp = send_from_directory(STATIC_DIR, "sw.js", mimetype="application/javascript")
    resp.headers["Cache-Control"] = "no-cache"
    return resp


# ============================================================
# Bootstrap (works for Gunicorn/Render/PythonAnywhere)

# ============================================================
# ER Bed Occupancy (Manual + Automatic Snapshots)
# ============================================================
#
# Mirrors the uploaded Excel "ER Bed Occupancy" sheet (Data tab):
# - Total beds
# - Beds occupied
# - Bed occupancy %
# - Adult beds (total/occupied/vacant)
# - Pediatric beds (total/occupied/vacant)
# - Patients waiting pre triage
# - Patient waiting post triage
# - Patients waiting for IP admission
#
# Automatic mode:
# - Takes snapshots every SHIFT time(s) or every N minutes (default: 120)
# - Uses visits.bed_status (EMPTY/OCCUPIED/DIRTY) which is set via update_location_bed()
# - Uses visits.triage_time to determine pre/post triage waiting

import re


# --- Time helpers (hospital local time) ---
def er_occ_now_aware():
    """Return current datetime as timezone-aware in hospital local time (if configured).

    Fallback: server local timezone-aware datetime.
    """
    try:
        tz = get_display_tzinfo()
        if tz:
            return datetime.now(tz)
    except Exception:
        pass
    try:
        return datetime.now().astimezone()
    except Exception:
        return datetime.now()


def er_occ_now_str():
    """Timestamp string stored for ER occupancy rows (ISO 8601 with offset when possible)."""
    try:
        dt = er_occ_now_aware().replace(microsecond=0)
        return dt.isoformat(sep=" ")
    except Exception:
        try:
            return datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        except Exception:
            return ""


def er_occ_now_local_dt():
    """Naive datetime in hospital local time (used for bucket calculations)."""
    try:
        tz = get_display_tzinfo()
        if tz:
            return datetime.now(tz).replace(tzinfo=None, microsecond=0)
    except Exception:
        pass
    try:
        return datetime.now().replace(microsecond=0)
    except Exception:
        return datetime.now()


ER_OCCUPANCY_DEFAULTS = {
    "manual_enabled": 0,
    "auto_enabled": 1,
    "schedule_mode": "INTERVAL",  # INTERVAL | SHIFT
    "interval_minutes": 120,
    "shift_times": "00:00",  # comma-separated HH:MM
    "total_beds": 0,
    "adult_total": 0,
    "peds_total": 0,
    "adult_age_cutoff": 17,  # < cutoff => pediatric
}


def ensure_er_bed_occupancy_schema():
    """Create ER occupancy tables + seed default settings row (id=1). Idempotent."""
    db = get_db()
    cur = db.cursor()
    try:
        if DB_ENGINE == "postgres":
            cur.execute("""
                CREATE TABLE IF NOT EXISTS er_bed_occupancy_settings (
                    id INTEGER PRIMARY KEY,
                    manual_enabled INTEGER DEFAULT 0,
                    auto_enabled INTEGER DEFAULT 1,
                    schedule_mode TEXT DEFAULT 'INTERVAL',
                    interval_minutes INTEGER DEFAULT 120,
                    shift_times TEXT DEFAULT '00:00',
                    total_beds INTEGER DEFAULT 0,
                    adult_total INTEGER DEFAULT 0,
                    peds_total INTEGER DEFAULT 0,
                    adult_age_cutoff INTEGER DEFAULT 17,
                    updated_at TEXT
                )
                """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS er_bed_occupancy_snapshots (
                    id BIGSERIAL PRIMARY KEY,
                    snapshot_at TEXT NOT NULL,
                    bucket TEXT NOT NULL,
                    source TEXT NOT NULL,          -- MANUAL | AUTO
                    created_by TEXT,
                    notes TEXT,
                    total_beds INTEGER,
                    beds_occupied INTEGER,
                    beds_vacant INTEGER,
                    occupancy_pct REAL,
                    adult_total INTEGER,
                    adult_occupied INTEGER,
                    adult_vacant INTEGER,
                    adult_occupancy_pct REAL,
                    peds_total INTEGER,
                    peds_occupied INTEGER,
                    peds_vacant INTEGER,
                    peds_occupancy_pct REAL,
                    waiting_pre_triage INTEGER,
                    waiting_post_triage INTEGER,
                    waiting_ip_admission INTEGER,
                    waiting_ip_ready_boarders INTEGER,
                    created_at TEXT
                )
                """)
        else:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS er_bed_occupancy_settings (
                    id INTEGER PRIMARY KEY,
                    manual_enabled INTEGER DEFAULT 0,
                    auto_enabled INTEGER DEFAULT 1,
                    schedule_mode TEXT DEFAULT 'INTERVAL',
                    interval_minutes INTEGER DEFAULT 120,
                    shift_times TEXT DEFAULT '00:00',
                    total_beds INTEGER DEFAULT 0,
                    adult_total INTEGER DEFAULT 0,
                    peds_total INTEGER DEFAULT 0,
                    adult_age_cutoff INTEGER DEFAULT 17,
                    updated_at TEXT
                )
                """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS er_bed_occupancy_snapshots (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    snapshot_at TEXT NOT NULL,
                    bucket TEXT NOT NULL,
                    source TEXT NOT NULL,
                    created_by TEXT,
                    notes TEXT,
                    total_beds INTEGER,
                    beds_occupied INTEGER,
                    beds_vacant INTEGER,
                    occupancy_pct REAL,
                    adult_total INTEGER,
                    adult_occupied INTEGER,
                    adult_vacant INTEGER,
                    adult_occupancy_pct REAL,
                    peds_total INTEGER,
                    peds_occupied INTEGER,
                    peds_vacant INTEGER,
                    peds_occupancy_pct REAL,
                    waiting_pre_triage INTEGER,
                    waiting_post_triage INTEGER,
                    waiting_ip_admission INTEGER,
                    waiting_ip_ready_boarders INTEGER,
                    created_at TEXT
                )
                """)

        # Add new columns (safe upgrades)
        try:
            ensure_column(
                "er_bed_occupancy_snapshots", "waiting_ip_ready_boarders", "INTEGER"
            )
        except Exception:
            pass

        # One snapshot per bucket per source (prevents duplicate AUTO snapshots)
        cur.execute("""
            CREATE UNIQUE INDEX IF NOT EXISTS ux_er_occ_bucket_source
            ON er_bed_occupancy_snapshots(bucket, source)
            """)

        # Seed settings row
        row = cur.execute(
            "SELECT id FROM er_bed_occupancy_settings WHERE id=1"
        ).fetchone()
        if not row:
            now = er_occ_now_str()
            cur.execute(
                """
                INSERT INTO er_bed_occupancy_settings
                (id, manual_enabled, auto_enabled, schedule_mode, interval_minutes, shift_times,
                 total_beds, adult_total, peds_total, adult_age_cutoff, updated_at)
                VALUES (?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    1,
                    ER_OCCUPANCY_DEFAULTS["manual_enabled"],
                    ER_OCCUPANCY_DEFAULTS["auto_enabled"],
                    ER_OCCUPANCY_DEFAULTS["schedule_mode"],
                    ER_OCCUPANCY_DEFAULTS["interval_minutes"],
                    ER_OCCUPANCY_DEFAULTS["shift_times"],
                    ER_OCCUPANCY_DEFAULTS["total_beds"],
                    ER_OCCUPANCY_DEFAULTS["adult_total"],
                    ER_OCCUPANCY_DEFAULTS["peds_total"],
                    ER_OCCUPANCY_DEFAULTS["adult_age_cutoff"],
                    now,
                ),
            )

        else:
            # Migrate legacy defaults -> new defaults (safe: only if still using old default values)
            try:
                srow = cur.execute("""
                    SELECT manual_enabled, auto_enabled, shift_times, adult_age_cutoff
                    FROM er_bed_occupancy_settings
                    WHERE id=1
                    """).fetchone()

                def _to_int(v, default=0):
                    try:
                        return int(v)
                    except Exception:
                        return default

                man = _to_int(_fetch_one_val(srow, "manual_enabled", 0), 0)
                auto = _to_int(_fetch_one_val(srow, "auto_enabled", 1), 0)
                st = str(_fetch_one_val(srow, "shift_times", 2) or "").strip()
                cutoff = _to_int(_fetch_one_val(srow, "adult_age_cutoff", 3), 0)

                if (
                    man == 1
                    and auto == 0
                    and (st in ("", "07:00,19:00"))
                    and (cutoff in (0, 14))
                ):
                    now = er_occ_now_str()
                    cur.execute(
                        """
                        UPDATE er_bed_occupancy_settings
                        SET manual_enabled=?, auto_enabled=?, shift_times=?, adult_age_cutoff=?, updated_at=?
                        WHERE id=1
                        """,
                        (
                            ER_OCCUPANCY_DEFAULTS["manual_enabled"],
                            ER_OCCUPANCY_DEFAULTS["auto_enabled"],
                            ER_OCCUPANCY_DEFAULTS["shift_times"],
                            ER_OCCUPANCY_DEFAULTS["adult_age_cutoff"],
                            now,
                        ),
                    )
            except Exception:
                pass

        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass
        raise


def _row_to_dict(row, cur=None):
    """Convert a DB row (sqlite3.Row, psycopg2 DictRow, or tuple) to a plain dict.

    If `cur` is provided, tuple rows can be mapped using cursor.description.
    """
    if row is None:
        return None

    if isinstance(row, dict):
        return row

    # Most cases: sqlite3.Row or psycopg2 DictRow
    try:
        return dict(row)
    except Exception:
        pass

    # Mapping-style access (e.g. sqlite3.Row / DictRow)
    try:
        keys = row.keys()
        return {k: row[k] for k in keys}
    except Exception:
        pass

    # Fallback: map tuple/list using cursor description
    if cur is not None:
        try:
            desc = getattr(cur, "description", None)
            if desc:
                cols = []
                for d in desc:
                    try:
                        cols.append(d[0])
                    except Exception:
                        cols.append(getattr(d, "name", None) or str(d))

                out = {}
                for i, c in enumerate(cols):
                    if i >= len(row):
                        break
                    out[c] = row[i]
                return out
        except Exception:
            pass

    return None


def get_er_bed_occupancy_settings():
    try:
        ensure_er_bed_occupancy_schema()
    except Exception:
        pass
    cur = get_db().cursor()
    row = cur.execute("SELECT * FROM er_bed_occupancy_settings WHERE id=1").fetchone()
    s = _row_to_dict(row) or {}
    # normalize defaults
    out = dict(ER_OCCUPANCY_DEFAULTS)
    out.update({k: s.get(k) for k in out.keys() if k in s})
    # plus any extra columns
    out.update(s)
    return out


def update_er_bed_occupancy_settings(**kwargs):
    ensure_er_bed_occupancy_schema()
    s = get_er_bed_occupancy_settings()
    s.update(kwargs or {})
    now = er_occ_now_str()
    s["updated_at"] = now
    cur = get_db().cursor()
    cur.execute(
        """
        UPDATE er_bed_occupancy_settings
           SET manual_enabled=?,
               auto_enabled=?,
               schedule_mode=?,
               interval_minutes=?,
               shift_times=?,
               total_beds=?,
               adult_total=?,
               peds_total=?,
               adult_age_cutoff=?,
               updated_at=?
         WHERE id=1
        """,
        (
            int(s.get("manual_enabled") or 0),
            int(s.get("auto_enabled") or 0),
            (s.get("schedule_mode") or "INTERVAL").strip().upper(),
            int(s.get("interval_minutes") or 120),
            (s.get("shift_times") or "07:00,19:00").strip(),
            int(s.get("total_beds") or 0),
            int(s.get("adult_total") or 0),
            int(s.get("peds_total") or 0),
            int(s.get("adult_age_cutoff") or 14),
            now,
        ),
    )
    get_db().commit()


def _safe_int(x, default=0):
    try:
        if x is None:
            return default
        if isinstance(x, (int, float)):
            return int(x)
        s = str(x).strip()
        if s == "":
            return default
        return int(float(s))
    except Exception:
        return default


def _pct(occ, total):
    try:
        occ = float(occ or 0)
        total = float(total or 0)
        if total <= 0:
            return 0.0
        return round((occ / total) * 100.0, 1)
    except Exception:
        return 0.0


def _vacant(total, occ):
    try:
        total = int(total or 0)
        occ = int(occ or 0)
        return max(total - occ, 0)
    except Exception:
        return 0


def _safe_count(cur, sql: str, params=None):
    # Reuse existing helper if present; otherwise this local is used.
    try:
        row = cur.execute(sql, params or ()).fetchone()
        if row is None:
            return 0
        try:
            return int(row["c"])
        except Exception:
            try:
                return int(row[0])
            except Exception:
                return 0
    except Exception:
        return 0


def compute_er_bed_occupancy_auto(settings=None):
    """Compute current values from the live system (for AUTO snapshots and live preview)."""
    ensure_er_bed_occupancy_schema()
    s = settings or get_er_bed_occupancy_settings()
    cur = get_db().cursor()

    adult_cutoff = _safe_int(s.get("adult_age_cutoff"), 14)

    # Totals from settings (if missing, derive)
    adult_total = _safe_int(s.get("adult_total"), 0)
    peds_total = _safe_int(s.get("peds_total"), 0)
    total_beds = _safe_int(s.get("total_beds"), 0)
    if total_beds <= 0:
        total_beds = max(0, adult_total + peds_total)

    # Occupied beds (based on bed_status='OCCUPIED')
    # We split adult/peds using calc_age(p.dob) to keep DB-agnostic.
    rows = []
    try:
        rows = cur.execute("""
            SELECT p.dob AS dob
              FROM visits v
              JOIN patients p ON p.id=v.patient_id
             WHERE UPPER(COALESCE(v.clinic,'ED'))='ED'
               AND UPPER(TRIM(COALESCE(v.status,''))) NOT IN ('DISCHARGED','TRANSFERRED','LAMA','EXPIRED','CANCELLED','CLOSED','VISIT_COMPLETED','COMPLETED')
               AND UPPER(COALESCE(v.bed_status,''))='OCCUPIED'
            """).fetchall()
    except Exception:
        rows = []

    adult_occ = peds_occ = 0
    for r in rows or []:
        dob = None
        try:
            dob = r["dob"]
        except Exception:
            try:
                dob = r[0]
            except Exception:
                dob = None
        age = calc_age(dob)
        try:
            age_i = int(age)
        except Exception:
            age_i = None
        if age_i is not None and age_i < adult_cutoff:
            peds_occ += 1
        else:
            adult_occ += 1

    beds_occupied = adult_occ + peds_occ

    # Waiting counts based on triage_time (pre vs post triage)
    waiting_pre = _safe_count(
        cur,
        """
        SELECT COUNT(*) AS c
          FROM visits v
         WHERE UPPER(COALESCE(v.clinic,'ED'))='ED'
           AND UPPER(TRIM(COALESCE(v.status,''))) NOT IN ('DISCHARGED','TRANSFERRED','LAMA','EXPIRED','CANCELLED','CLOSED','VISIT_COMPLETED','COMPLETED')
           AND (v.triage_time IS NULL OR TRIM(v.triage_time)='')
        """,
    )

    waiting_post = _safe_count(
        cur,
        """
        SELECT COUNT(*) AS c
          FROM visits v
         WHERE UPPER(COALESCE(v.clinic,'ED'))='ED'
           AND UPPER(TRIM(COALESCE(v.status,''))) NOT IN ('DISCHARGED','TRANSFERRED','LAMA','EXPIRED','CANCELLED','CLOSED','VISIT_COMPLETED','COMPLETED')
           AND NOT (v.triage_time IS NULL OR TRIM(v.triage_time)='')
           AND UPPER(COALESCE(v.bed_status,'')) <> 'OCCUPIED'
        """,
    )

    # Waiting for IP admission
    # - Count ED OPEN visits that have a non-terminal Admission Order in a "waiting" stage.
    # - IMPORTANT: When inpatient billing assigns and the stage becomes READY,
    #   we remove it from this waiting counter (it is no longer "waiting").
    try:
        if "ensure_admission_orders_enterprise_upgrade" in globals():
            ensure_admission_orders_enterprise_upgrade()
    except Exception:
        pass

    active = (
        AO_ACTIVE_STATUSES[:]
        if "AO_ACTIVE_STATUSES" in globals()
        else ["ORDERED", "UNDER_REVIEW", "PENDING_BED", "PENDING_APPROVAL", "READY"]
    )
    waiting_statuses = [s for s in (active or []) if str(s).upper() != "READY"]

    waiting_ip = 0
    if waiting_statuses:
        ph = ",".join(["?"] * len(waiting_statuses))
        waiting_ip = _safe_count(
            cur,
            f"""
            SELECT COUNT(*) AS c
              FROM visits v
              JOIN admission_orders ao ON ao.id = (
                    SELECT ao2.id
                      FROM admission_orders ao2
                     WHERE ao2.visit_id=v.visit_id
                     ORDER BY
                        CASE WHEN UPPER(COALESCE(ao2.status,'')) IN ({ph}) THEN 0 ELSE 1 END,
                        ao2.id DESC
                     LIMIT 1
              )
             WHERE UPPER(COALESCE(v.clinic,'ED'))='ED'
               AND UPPER(TRIM(COALESCE(v.status,''))) NOT IN ('DISCHARGED','TRANSFERRED','LAMA','EXPIRED','CANCELLED','CLOSED','VISIT_COMPLETED','COMPLETED')
               AND UPPER(COALESCE(ao.status,'')) IN ({ph})
            """,
            waiting_statuses + waiting_statuses,
        )

    # IP READY (Boarders): READY but still occupying an ED bed
    ip_ready_boarders = 0
    try:
        active_all = (
            AO_ACTIVE_STATUSES[:]
            if "AO_ACTIVE_STATUSES" in globals()
            else ["ORDERED", "UNDER_REVIEW", "PENDING_BED", "PENDING_APPROVAL", "READY"]
        )
        active_all = [
            str(x).upper() for x in (active_all or []) if str(x).strip() != ""
        ]
        if active_all:
            ph2 = ",".join(["?"] * len(active_all))
            ip_ready_boarders = _safe_count(
                cur,
                f"""
                SELECT COUNT(*) AS c
                  FROM visits v
                  JOIN admission_orders ao ON ao.id = (
                        SELECT ao2.id
                          FROM admission_orders ao2
                         WHERE ao2.visit_id=v.visit_id
                         ORDER BY
                            CASE WHEN UPPER(COALESCE(ao2.status,'')) IN ({ph2}) THEN 0 ELSE 1 END,
                            ao2.id DESC
                         LIMIT 1
                  )
                 WHERE UPPER(COALESCE(v.clinic,'ED'))='ED'
                   AND UPPER(TRIM(COALESCE(v.status,''))) NOT IN ('DISCHARGED','TRANSFERRED','LAMA','EXPIRED','CANCELLED','CLOSED','VISIT_COMPLETED','COMPLETED')
                   AND UPPER(COALESCE(v.bed_status,''))='OCCUPIED'
                   AND UPPER(COALESCE(ao.status,''))='READY'
                """,
                active_all,
            )
        else:
            ip_ready_boarders = _safe_count(
                cur,
                """
                SELECT COUNT(*) AS c
                  FROM visits v
                  JOIN admission_orders ao ON ao.id = (
                        SELECT ao2.id
                          FROM admission_orders ao2
                         WHERE ao2.visit_id=v.visit_id
                         ORDER BY ao2.id DESC
                         LIMIT 1
                  )
                 WHERE UPPER(COALESCE(v.clinic,'ED'))='ED'
                   AND UPPER(TRIM(COALESCE(v.status,''))) NOT IN ('DISCHARGED','TRANSFERRED','LAMA','EXPIRED','CANCELLED','CLOSED','VISIT_COMPLETED','COMPLETED')
                   AND UPPER(COALESCE(v.bed_status,''))='OCCUPIED'
                   AND UPPER(COALESCE(ao.status,''))='READY'
                """,
            )
    except Exception:
        ip_ready_boarders = 0

    out = {
        "total_beds": total_beds,
        "beds_occupied": beds_occupied,
        "beds_vacant": _vacant(total_beds, beds_occupied),
        "occupancy_pct": _pct(beds_occupied, total_beds),
        "adult_total": adult_total,
        "adult_occupied": adult_occ,
        "adult_vacant": _vacant(adult_total, adult_occ),
        "adult_occupancy_pct": _pct(adult_occ, adult_total),
        "peds_total": peds_total,
        "peds_occupied": peds_occ,
        "peds_vacant": _vacant(peds_total, peds_occ),
        "peds_occupancy_pct": _pct(peds_occ, peds_total),
        "waiting_pre_triage": waiting_pre,
        "waiting_post_triage": waiting_post,
        "waiting_ip_admission": waiting_ip,
        "waiting_ip_ready_boarders": ip_ready_boarders,
    }
    return out


def insert_er_bed_occupancy_snapshot(
    data: dict, source="MANUAL", bucket=None, created_by=None, notes=None
):
    ensure_er_bed_occupancy_schema()
    now = er_occ_now_str()
    src = (source or "MANUAL").strip().upper()
    created_by = created_by or (
        "SYSTEM" if src == "AUTO" else session.get("username", "UNKNOWN")
    )

    snapshot_at = (data or {}).get("snapshot_at") or now
    bucket = (bucket or "").strip()
    if not bucket:
        # For MANUAL we make bucket unique by using seconds resolution
        bucket = snapshot_at

    total_beds = _safe_int((data or {}).get("total_beds"), 0)
    beds_occupied = _safe_int((data or {}).get("beds_occupied"), 0)

    adult_total = _safe_int((data or {}).get("adult_total"), 0)
    adult_occ = _safe_int((data or {}).get("adult_occupied"), 0)

    peds_total = _safe_int((data or {}).get("peds_total"), 0)
    peds_occ = _safe_int((data or {}).get("peds_occupied"), 0)

    waiting_pre = _safe_int((data or {}).get("waiting_pre_triage"), 0)
    waiting_post = _safe_int((data or {}).get("waiting_post_triage"), 0)
    waiting_ip = _safe_int((data or {}).get("waiting_ip_admission"), 0)
    waiting_ip_ready = _safe_int((data or {}).get("waiting_ip_ready_boarders"), 0)

    # Derived
    beds_vacant = _vacant(total_beds, beds_occupied)
    occ_pct = _pct(beds_occupied, total_beds)

    adult_vac = _vacant(adult_total, adult_occ)
    adult_pct = _pct(adult_occ, adult_total)

    peds_vac = _vacant(peds_total, peds_occ)
    peds_pct = _pct(peds_occ, peds_total)

    cur = get_db().cursor()
    cur.execute(
        """
        INSERT INTO er_bed_occupancy_snapshots
        (snapshot_at, bucket, source, created_by, notes,
         total_beds, beds_occupied, beds_vacant, occupancy_pct,
         adult_total, adult_occupied, adult_vacant, adult_occupancy_pct,
         peds_total, peds_occupied, peds_vacant, peds_occupancy_pct,
         waiting_pre_triage, waiting_post_triage, waiting_ip_admission, waiting_ip_ready_boarders,
         created_at)
        VALUES (?,?,?,?,?,
                ?,?,?,?,
                ?,?,?,?,
                ?,?,?,?,
                ?,?,?,?,
                ?)
        ON CONFLICT(bucket, source) DO UPDATE SET
            snapshot_at=excluded.snapshot_at,
            created_by=excluded.created_by,
            notes=excluded.notes,
            total_beds=excluded.total_beds,
            beds_occupied=excluded.beds_occupied,
            beds_vacant=excluded.beds_vacant,
            occupancy_pct=excluded.occupancy_pct,
            adult_total=excluded.adult_total,
            adult_occupied=excluded.adult_occupied,
            adult_vacant=excluded.adult_vacant,
            adult_occupancy_pct=excluded.adult_occupancy_pct,
            peds_total=excluded.peds_total,
            peds_occupied=excluded.peds_occupied,
            peds_vacant=excluded.peds_vacant,
            peds_occupancy_pct=excluded.peds_occupancy_pct,
            waiting_pre_triage=excluded.waiting_pre_triage,
            waiting_post_triage=excluded.waiting_post_triage,
            waiting_ip_admission=excluded.waiting_ip_admission,
            waiting_ip_ready_boarders=excluded.waiting_ip_ready_boarders,
            created_at=excluded.created_at
        """,
        (
            snapshot_at,
            bucket,
            src,
            created_by,
            (notes or "").strip() or None,
            total_beds,
            beds_occupied,
            beds_vacant,
            occ_pct,
            adult_total,
            adult_occ,
            adult_vac,
            adult_pct,
            peds_total,
            peds_occ,
            peds_vac,
            peds_pct,
            waiting_pre,
            waiting_post,
            waiting_ip,
            waiting_ip_ready,
            now,
        ),
    )
    get_db().commit()


def _parse_shift_times(s: str):
    out = []
    for part in (s or "").split(","):
        t = part.strip()
        if not t:
            continue
        # HH:MM
        if re.match(r"^\d{2}:\d{2}$", t):
            out.append(t)
    return out


def _interval_bucket(now_dt: datetime, minutes: int):
    minutes = max(1, int(minutes or 120))
    midnight = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
    mins_since = int((now_dt - midnight).total_seconds() // 60)
    bucket_start_min = (mins_since // minutes) * minutes
    bucket_dt = midnight + timedelta(minutes=bucket_start_min)
    return bucket_dt.strftime("%Y-%m-%d %H:%M")


def _shift_bucket(now_dt: datetime, shift_times):
    # shift_times: list of "HH:MM" for shift starts. We choose the latest shift start <= now.
    if not shift_times:
        shift_times = ["07:00", "19:00"]
    shift_starts = []
    for t in shift_times:
        hh, mm = t.split(":")
        shift_starts.append((int(hh), int(mm), t))

    candidates = []
    for d_off in (
        0,
        -1,
    ):  # today and yesterday, to handle night shift spanning midnight
        base = now_dt.date() + timedelta(days=d_off)
        for hh, mm, label in shift_starts:
            candidates.append(
                (
                    datetime.combine(base, datetime.min.time()).replace(
                        hour=hh, minute=mm
                    ),
                    label,
                )
            )
    candidates.sort(key=lambda x: x[0])

    last_start = None
    last_label = None
    for dt0, label in candidates:
        if dt0 <= now_dt:
            last_start, last_label = dt0, label
        else:
            break
    if last_start is None:
        # before first shift start today => use yesterday's last shift
        last_start, last_label = candidates[-1]
    return last_start.strftime("%Y-%m-%d %H:%M"), last_start


def _auto_snapshot_bucket(now_dt: datetime, settings):
    mode = (settings.get("schedule_mode") or "INTERVAL").strip().upper()
    if mode == "SHIFT":
        st = _parse_shift_times(settings.get("shift_times") or "")
        bucket, start_dt = _shift_bucket(now_dt, st)
        # Trigger window: first 30 minutes of the shift (to avoid creating mid-shift by restart)
        if now_dt >= start_dt and now_dt < (start_dt + timedelta(minutes=30)):
            return bucket
        return None
    # default INTERVAL
    interval = _safe_int(settings.get("interval_minutes"), 120)
    return _interval_bucket(now_dt, interval)


def er_bed_occupancy_scheduler_loop():
    while True:
        try:
            with app.app_context():
                s = get_er_bed_occupancy_settings()
                if int(s.get("auto_enabled") or 0) != 1:
                    time.sleep(60)
                    continue

                now_dt = er_occ_now_local_dt()
                bucket = _auto_snapshot_bucket(now_dt, s)
                if not bucket:
                    time.sleep(30)
                    continue

                cur = get_db().cursor()
                exists = cur.execute(
                    "SELECT id FROM er_bed_occupancy_snapshots WHERE bucket=? AND source='AUTO' LIMIT 1",
                    (bucket,),
                ).fetchone()
                if not exists:
                    payload = compute_er_bed_occupancy_auto(s)
                    insert_er_bed_occupancy_snapshot(
                        payload, source="AUTO", bucket=bucket, created_by="SYSTEM"
                    )
        except Exception:
            # never crash background thread
            pass
        time.sleep(30)


def start_er_bed_occupancy_scheduler_once():
    # Same pattern as backup scheduler: avoid duplicate threads on Flask debug reload
    if app.config.get("DEBUG") and os.environ.get("WERKZEUG_RUN_MAIN") != "true":
        return
    # Avoid duplicates in a single process
    if app.config.get("ER_OCCUPANCY_SCHED_STARTED"):
        return
    app.config["ER_OCCUPANCY_SCHED_STARTED"] = True
    t = threading.Thread(target=er_bed_occupancy_scheduler_loop, daemon=True)
    t.start()


