def er_occupancy():
    s = get_er_bed_occupancy_settings()
    live = compute_er_bed_occupancy_auto(s)

    cur = get_db().cursor()
    rows = cur.execute("""
        SELECT *
          FROM er_bed_occupancy_snapshots
         ORDER BY id DESC
         LIMIT 120
        """).fetchall()
    snaps = [_row_to_dict(r) for r in (rows or [])]

    # Display-friendly time (hospital local timezone)
    for d in snaps:
        if not d:
            continue
        try:
            d["snapshot_at_disp"] = format_dt_local(d.get("snapshot_at")) or (
                d.get("snapshot_at") or ""
            )
        except Exception:
            d["snapshot_at_disp"] = d.get("snapshot_at") or ""

