@app.route("/er_occupancy/manual", methods=["POST"])
@login_required
@role_required("nurse", "doctor", "admin")
def er_occupancy_manual_snapshot():
    try:
        payload = {
            "total_beds": _safe_int(request.form.get("total_beds"), 0),
            "beds_occupied": _safe_int(request.form.get("beds_occupied"), 0),
            "adult_total": _safe_int(request.form.get("adult_total"), 0),
            "adult_occupied": _safe_int(request.form.get("adult_occupied"), 0),
            "peds_total": _safe_int(request.form.get("peds_total"), 0),
            "peds_occupied": _safe_int(request.form.get("peds_occupied"), 0),
            "waiting_pre_triage": _safe_int(request.form.get("waiting_pre_triage"), 0),
            "waiting_post_triage": _safe_int(
                request.form.get("waiting_post_triage"), 0
            ),
            "waiting_ip_admission": _safe_int(
                request.form.get("waiting_ip_admission"), 0
            ),
            "waiting_ip_ready_boarders": _safe_int(
                request.form.get("waiting_ip_ready_boarders"), 0
            ),
        }
        notes = (request.form.get("notes") or "").strip() or None
        insert_er_bed_occupancy_snapshot(payload, source="MANUAL", notes=notes)
        flash("Snapshot saved.", "success")
        try:
            log_action(
                "ER_OCC_SNAPSHOT_MANUAL",
                details=json.dumps(payload, ensure_ascii=False)[:1000],
            )
        except Exception:
            pass
    except Exception as e:
        flash(f"Failed to save snapshot: {e}", "danger")
    return redirect(url_for("er_occupancy"))


