@app.route("/er_occupancy/export.csv")
@login_required
@role_required("nurse", "doctor", "admin", "reception")
def er_occupancy_export_csv():
    ensure_er_bed_occupancy_schema()
    cur = get_db().cursor()
    rows = cur.execute(
        "SELECT * FROM er_bed_occupancy_snapshots ORDER BY id DESC LIMIT 5000"
    ).fetchall()
    out_rows = []
    for r in rows or []:
        d = _row_to_dict(r) or {}
        out_rows.append(d)

    # CSV
    cols = [
        "snapshot_at",
        "source",
        "bucket",
        "created_by",
        "notes",
        "total_beds",
        "beds_occupied",
        "beds_vacant",
        "occupancy_pct",
        "adult_total",
        "adult_occupied",
        "adult_vacant",
        "adult_occupancy_pct",
        "peds_total",
        "peds_occupied",
        "peds_vacant",
        "peds_occupancy_pct",
        "waiting_pre_triage",
        "waiting_post_triage",
        "waiting_ip_admission",
        "waiting_ip_ready_boarders",
        "created_at",
    ]
    import csv, io as _io

    buf = _io.StringIO()
    w = csv.DictWriter(buf, fieldnames=cols, extrasaction="ignore")
    w.writeheader()
    for d in out_rows:
        w.writerow({k: d.get(k) for k in cols})
    csv_text = buf.getvalue()
    resp = Response(csv_text, mimetype="text/csv")
    resp.headers["Content-Disposition"] = (
        "attachment; filename=er_bed_occupancy_snapshots.csv"
    )
    return resp


# ============================================================

_bootstrapped = False
_BOOTSTRAP_LAST_ERROR = ""


def _env_flag(name: str, default: bool = False) -> bool:
    try:
        v = os.environ.get(name)
    except Exception:
        v = None
    if v is None:
        return bool(default)
    try:
        return str(v).strip().lower() in ("1", "true", "yes", "y", "on")
    except Exception:
        return bool(default)


def ensure_perf_indexes():
    """Create performance indexes (idempotent).

    Focus areas:
    - ED / Clinic / IP boards (visits + admission orders)
    - Hot result queues (lab / radiology / pharmacy)
    - Attachment lookups used by boards
    - Frequent user / patient search paths
    """
    try:
        db = get_db()
        cur = db.cursor()
    except Exception:
        return

    stmts = []
    if DB_ENGINE == "postgres":
        stmts = [
            # Visits hot filters / ordering
            "CREATE INDEX IF NOT EXISTS idx_visits_clinic_id_desc ON visits (clinic, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_visits_clinic_status ON visits (clinic, status)",
            "CREATE INDEX IF NOT EXISTS idx_visits_clinic_triage_cat ON visits (clinic, triage_cat)",
            "CREATE INDEX IF NOT EXISTS idx_visits_clinic_status_id_desc ON visits (clinic, status, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_visits_clinic_created_at ON visits (clinic, created_at)",
            "CREATE INDEX IF NOT EXISTS idx_visits_clinic_created_by ON visits (clinic, created_by)",
            "CREATE INDEX IF NOT EXISTS idx_visits_clinic_eff_id_desc ON visits ((COALESCE(clinic,'ED')), id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_visits_clinic_eff_status_id_desc ON visits ((COALESCE(clinic,'ED')), status, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_visits_clinic_eff_created_at ON visits ((COALESCE(clinic,'ED')), created_at)",
            "CREATE INDEX IF NOT EXISTS idx_visits_created_at ON visits (created_at)",
            "CREATE INDEX IF NOT EXISTS idx_visits_created_by ON visits (created_by)",
            "CREATE INDEX IF NOT EXISTS idx_visits_patient_id_id_desc ON visits (patient_id, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_visits_patient_id_status ON visits (patient_id, status)",
            "CREATE INDEX IF NOT EXISTS idx_visits_patient_clinic_id_desc ON visits (patient_id, clinic, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_visits_patient_clinic_eff_id_desc ON visits (patient_id, (COALESCE(clinic,'ED')), id DESC)",
            # Admission orders
            "CREATE INDEX IF NOT EXISTS idx_admission_orders_visit_id_desc ON admission_orders (visit_id, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_admission_orders_visit_status_id_desc ON admission_orders (visit_id, status, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_admission_orders_admitted_at ON admission_orders (admitted_at)",
            # Attachments used by boards / patient pages
            "CREATE INDEX IF NOT EXISTS idx_attachments_visit_uploaded_desc ON attachments (visit_id, uploaded_at DESC)",
            "CREATE INDEX IF NOT EXISTS idx_attachments_visit_filename_uploaded_desc ON attachments (visit_id, filename, uploaded_at DESC)",
            # Lab / radiology queues
            "CREATE INDEX IF NOT EXISTS idx_lab_requests_status_requested_at_id_desc ON lab_requests (status, requested_at, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_lab_requests_visit_id ON lab_requests (visit_id)",
            "CREATE INDEX IF NOT EXISTS idx_lab_requests_visit_source_order_id_desc ON lab_requests (visit_id, source_order_id, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_radiology_requests_status_requested_at_id_desc ON radiology_requests (status, requested_at, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_radiology_requests_visit_id ON radiology_requests (visit_id)",
            "CREATE INDEX IF NOT EXISTS idx_radiology_requests_visit_source_order_id_desc ON radiology_requests (visit_id, source_order_id, id DESC)",
            # Clinical orders / notes / provider note
            "CREATE INDEX IF NOT EXISTS idx_clinical_orders_visit_id_desc ON clinical_orders (visit_id, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_clinical_orders_visit_created_at_desc ON clinical_orders (visit_id, created_at DESC)",
            "CREATE INDEX IF NOT EXISTS idx_nursing_notes_visit_id_desc ON nursing_notes (visit_id, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_nursing_notes_visit_created_at_desc ON nursing_notes (visit_id, created_at DESC)",
            "CREATE INDEX IF NOT EXISTS idx_provider_notes_visit_id ON provider_notes (visit_id)",
            # Pharmacy / discharge workflow
            "CREATE INDEX IF NOT EXISTS idx_discharge_summaries_visit_id ON discharge_summaries (visit_id)",
            "CREATE INDEX IF NOT EXISTS idx_discharge_summaries_updated_at ON discharge_summaries (updated_at)",
            "CREATE INDEX IF NOT EXISTS idx_discharge_summaries_dispense_status_updated_at ON discharge_summaries (dispense_status, updated_at)",
            # Search helpers
            "CREATE INDEX IF NOT EXISTS idx_patients_id_number ON patients (id_number)",
            "CREATE INDEX IF NOT EXISTS idx_patients_name ON patients (name)",
            "CREATE INDEX IF NOT EXISTS idx_patients_mrn ON patients (mrn)",
            "CREATE INDEX IF NOT EXISTS idx_patients_phone ON patients (phone)",
            "CREATE INDEX IF NOT EXISTS idx_patients_dob ON patients (dob)",
            "CREATE INDEX IF NOT EXISTS idx_patients_phone_dob ON patients (phone, dob)",
            "CREATE INDEX IF NOT EXISTS idx_patients_lookup_mrn_id ON patients (mrn, id_number)",
            "CREATE INDEX IF NOT EXISTS idx_visits_visit_id_status ON visits (visit_id, status)",
            # Users / locks
            "CREATE INDEX IF NOT EXISTS idx_users_username_active ON users (username, is_active)",
            "CREATE INDEX IF NOT EXISTS idx_users_role_active_username ON users (role, is_active, username)",
            "CREATE INDEX IF NOT EXISTS idx_visit_locks_username_last_seen ON visit_locks(username, last_seen_ts)",
            "CREATE INDEX IF NOT EXISTS idx_visit_locks_sessions_username_last_seen ON visit_locks_sessions(username, last_seen_ts)",
            "CREATE INDEX IF NOT EXISTS idx_visit_locks_sessions_viewer_token ON visit_locks_sessions(viewer_token)",
        ]
    else:
        stmts = [
            "CREATE INDEX IF NOT EXISTS idx_visits_clinic ON visits (clinic)",
            "CREATE INDEX IF NOT EXISTS idx_visits_status ON visits (status)",
            "CREATE INDEX IF NOT EXISTS idx_visits_triage_cat ON visits (triage_cat)",
            "CREATE INDEX IF NOT EXISTS idx_visits_clinic_status_id ON visits (clinic, status, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_visits_clinic_created_at ON visits (clinic, created_at)",
            "CREATE INDEX IF NOT EXISTS idx_visits_patient_clinic_id ON visits (patient_id, clinic, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_visits_visit_id_status ON visits (visit_id, status)",
            "CREATE INDEX IF NOT EXISTS idx_visits_created_at ON visits (created_at)",
            "CREATE INDEX IF NOT EXISTS idx_visits_created_by ON visits (created_by)",
            "CREATE INDEX IF NOT EXISTS idx_admission_orders_visit_id_desc ON admission_orders (visit_id, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_admission_orders_admitted_at ON admission_orders (admitted_at)",
            "CREATE INDEX IF NOT EXISTS idx_attachments_visit_uploaded ON attachments (visit_id, uploaded_at)",
            "CREATE INDEX IF NOT EXISTS idx_attachments_visit_filename_uploaded ON attachments (visit_id, filename, uploaded_at)",
            "CREATE INDEX IF NOT EXISTS idx_lab_requests_status_requested_at_id ON lab_requests (status, requested_at, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_lab_requests_visit_id ON lab_requests (visit_id)",
            "CREATE INDEX IF NOT EXISTS idx_lab_requests_visit_source_order_id_desc ON lab_requests (visit_id, source_order_id, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_radiology_requests_status_requested_at_id ON radiology_requests (status, requested_at, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_radiology_requests_visit_id ON radiology_requests (visit_id)",
            "CREATE INDEX IF NOT EXISTS idx_radiology_requests_visit_source_order_id_desc ON radiology_requests (visit_id, source_order_id, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_clinical_orders_visit_id_desc ON clinical_orders (visit_id, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_clinical_orders_visit_created_at_desc ON clinical_orders (visit_id, created_at DESC)",
            "CREATE INDEX IF NOT EXISTS idx_nursing_notes_visit_id_desc ON nursing_notes (visit_id, id DESC)",
            "CREATE INDEX IF NOT EXISTS idx_nursing_notes_visit_created_at_desc ON nursing_notes (visit_id, created_at DESC)",
            "CREATE INDEX IF NOT EXISTS idx_provider_notes_visit_id ON provider_notes (visit_id)",
            "CREATE INDEX IF NOT EXISTS idx_discharge_summaries_visit_id ON discharge_summaries (visit_id)",
            "CREATE INDEX IF NOT EXISTS idx_discharge_summaries_updated_at ON discharge_summaries (updated_at)",
            "CREATE INDEX IF NOT EXISTS idx_discharge_summaries_dispense_status_updated_at ON discharge_summaries (dispense_status, updated_at)",
            "CREATE INDEX IF NOT EXISTS idx_patients_id_number ON patients (id_number)",
            "CREATE INDEX IF NOT EXISTS idx_patients_name ON patients (name)",
            "CREATE INDEX IF NOT EXISTS idx_patients_mrn ON patients (mrn)",
            "CREATE INDEX IF NOT EXISTS idx_patients_phone ON patients (phone)",
            "CREATE INDEX IF NOT EXISTS idx_patients_dob ON patients (dob)",
        ]

    for s in stmts:
        try:
            cur.execute(s)
        except Exception:
            pass

    try:
        db.commit()
    except Exception:
        pass

    if DB_ENGINE == "postgres":
        # Railway can boot multiple workers/replicas at the same time. Running
        # ANALYZE for several hot tables inside concurrent bootstrap transactions
        # can deadlock (seen in production logs for visits/patients). PostgreSQL
        # autovacuum/auto-analyze keeps stats fresh, so the startup ANALYZE is
        # opt-in only. If needed, set ED_BOOTSTRAP_ANALYZE=1; each table is then
        # analyzed in its own short transaction with a small lock timeout.
        run_pg_analyze = str(
            os.environ.get("ED_BOOTSTRAP_ANALYZE", APP_CONFIG.get("ED_BOOTSTRAP_ANALYZE", "0"))
        ).strip().lower() in ("1", "true", "yes", "y", "on")
        if run_pg_analyze:
            for s in (
                "ANALYZE visits",
                "ANALYZE admission_orders",
                "ANALYZE attachments",
                "ANALYZE lab_requests",
                "ANALYZE radiology_requests",
                "ANALYZE discharge_summaries",
                "ANALYZE patients",
                "ANALYZE users",
            ):
                try:
                    try:
                        cur.execute("SET LOCAL lock_timeout = '750ms'")
                    except Exception:
                        pass
                    cur.execute(s)
                    try:
                        db.commit()
                    except Exception:
                        pass
                except Exception:
                    try:
                        db.rollback()
                    except Exception:
                        pass
    else:
        try:
            cur.execute("ANALYZE")
        except Exception:
            pass
        try:
            db.commit()
        except Exception:
            pass

def bootstrap_once():
    """Initialize DB, default admin, and background scheduler once per process.

    Secondary load-balanced instances may opt into a light bootstrap by setting
    ED_LIGHT_BOOTSTRAP=1. This keeps startup fast after the primary instance has
    already repaired/seeded the PostgreSQL schema.
    """
    global _bootstrapped, _BOOTSTRAP_LAST_ERROR
    if _bootstrapped:
        return
    _bootstrapped = True
    _BOOTSTRAP_LAST_ERROR = ""
    _light_bootstrap = _env_flag("ED_LIGHT_BOOTSTRAP", False)
    try:
        with app.app_context():
            init_db()
            if _light_bootstrap:
                try:
                    db2 = get_db()
                    cur2 = db2.cursor()
                    cur2.execute("SELECT 1")
                    db2.commit()
                except Exception:
                    try:
                        get_db().rollback()
                    except Exception:
                        pass
                return
            # Audit schema (safe/idempotent)
            try:
                security.ensure_audit_schema()
            except Exception:
                pass
            # Status migration: store REGISTERED in DB (migrate legacy OPEN).
            try:
                db2 = get_db()
                cur2 = db2.cursor()
                cur2.execute(
                    "UPDATE visits SET status='REGISTERED' WHERE status IS NULL OR TRIM(status)=''"
                )
                cur2.execute(
                    "UPDATE visits SET status='REGISTERED' WHERE UPPER(COALESCE(status,''))='OPEN'"
                )
                if DB_ENGINE == "postgres":
                    try:
                        db2.execute(
                            "ALTER TABLE visits ALTER COLUMN status SET DEFAULT 'REGISTERED'"
                        )
                    except Exception:
                        pass
                db2.commit()
            except Exception:
                try:
                    get_db().rollback()
                except Exception:
                    pass

            # Ensure Clinic Board columns exist even on upgraded/old DBs
            try:
                ensure_clinic_schema()
            except Exception:
                pass

            # Ensure Admission Orders table exists (enterprise)
            try:
                ensure_admission_orders_schema()
            except Exception:
                pass

            # Ensure patient extra fields exist (email / NOK)
            try:
                ensure_patients_extra_schema()
            except Exception:
                pass

            # Admission Order picklists table (safe/idempotent)
            try:
                ensure_admission_picklists_schema()
            except Exception as ensure_exc:
                _log_noncritical_exception(
                    "bootstrap_once: ensure_admission_picklists_schema",
                    ensure_exc,
                )
            # Seed bundled Physicians directory (CSV) so Admin > Orders Items shows it by default
            try:
                seed_physicians_from_csv(force=False)
            except Exception:
                pass
            try:
                ensure_nursing_directory_schema()
            except Exception:
                pass
            # Diagnosis master list (global) used for Home Medication Dx
            try:
                ensure_diagnosis_master_schema()
                seed_default_diagnoses()
            except Exception:
                pass

            # Clinic registry (Register / Clinic Board) — seed from CLINICS once
            try:
                ensure_system_picklists_schema(seed_defaults=True)
                seed_clinic_system_picklists()
            except Exception:
                pass

            # Enhanced search indexes (SQLite FTS5 when available)
            try:
                ensure_fts_schema()
            except Exception:
                pass

            # Performance indexes (safe/idempotent)
            try:
                ensure_perf_indexes()
            except Exception:
                pass

            # Inventory schema (lightweight)
            try:
                ensure_inventory_schema()
            except Exception:
                pass

            # Hot-path schema warmup: never let the first real user request pay for DDL.
            for _ensure_fn, _args, _kwargs in (
                (ensure_daily_counters_schema, (), {}),
                (ensure_user_presence_schema, (), {}),
                (ensure_visit_lock_schema, (), {}),
                (ensure_chat_media_schema, (), {}),
                (ensure_patients_mrn_schema, (), {}),
                (ensure_visit_financial_schema, (), {}),
                (ensure_contract_schemes_schema, (), {}),
                (_ensure_single_session_db_schema, (), {}),
                (ensure_mrd_reentry_schema, (), {}),
                (_ensure_clinical_order_request_links, (), {}),
                (get_register_reference_data, (), {}),
            ):
                try:
                    _ensure_fn(*_args, **_kwargs)
                except Exception as _warm_exc:
                    _log_noncritical_exception(
                        f"bootstrap_once hot-path warmup failed: {getattr(_ensure_fn, '__name__', 'unknown')}",
                        _warm_exc,
                    )

            # Serial vitals history (safe/idempotent)
            try:
                ensure_patient_vitals_schema()
            except Exception:
                pass

            cur = get_db().cursor()
            admin = cur.execute("SELECT * FROM users WHERE username='admin'").fetchone()
            if not admin:
                cur.execute(
                    "INSERT INTO users (username,password_hash,role,created_at) VALUES (?,?,?,?)",
                    (
                        "admin",
                        generate_password_hash("admin12"),
                        "admin",
                        datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                    ),
                )
                get_db().commit()
            # Start backup thread (guarded inside function)
            start_backup_scheduler_once()

            # ER occupancy schema + auto snapshot scheduler
            try:
                ensure_er_bed_occupancy_schema()
            except Exception:
                pass
            try:
                start_er_bed_occupancy_scheduler_once()
            except Exception:
                pass
    except Exception as e:
        # Don't kill WSGI import; errors will show in logs
        try:
            _BOOTSTRAP_LAST_ERROR = str(e)[:300]
        except Exception:
            _BOOTSTRAP_LAST_ERROR = "bootstrap_failed"
        try:
            print("Bootstrap error:", e)
        except Exception:
            pass


@app.before_request
def _ensure_bootstrap():
    # First real user request triggers bootstrap on WSGI servers.
    # Do not make tablet browsers or platform health checks wait for heavy,
    # idempotent schema warmup/backup initialization. Health checks may kick off
    # a background warmup, but static assets and health probes must stay fast.
    try:
        ep = (request.endpoint or "").rsplit(".", 1)[-1]
        path = request.path or ""
        if path.startswith("/static/") or ep in {
            "static",
            "healthz",
            "pwa_manifest",
            "pwa_sw",
            "csrf_token_api",
            "session_status",
        }:
            if ep == "healthz" and _env_flag("ED_HEALTHZ_BACKGROUND_BOOTSTRAP", True):
                try:
                    start_background_bootstrap_once()
                except Exception:
                    pass
            return
    except Exception:
        pass
    bootstrap_once()


