CHAT_UPLOAD_DIR_NAME = "chat_uploads"


def _chat_media_search_paths():
    """Return shared/persistent candidate folders for chat media.

    Why this matters:
    - In multi-instance / load-balanced deployments, storing media under BASE_DIR
      can break previews when processes do not share the same extracted/runtime dir.
    - We therefore prefer the external data root, then fall back to legacy paths
      so older uploads continue to open.
    """
    paths = []
    candidates = []
    try:
        candidates.append(os.path.join(_data_root, CHAT_UPLOAD_DIR_NAME))
    except Exception:
        pass
    try:
        up = (app.config.get("UPLOAD_FOLDER") or UPLOAD_FOLDER or "").strip()
        if up:
            candidates.append(os.path.join(os.path.dirname(up), CHAT_UPLOAD_DIR_NAME))
            candidates.append(os.path.join(up, CHAT_UPLOAD_DIR_NAME))
    except Exception:
        pass
    try:
        candidates.append(os.path.join(BASE_DIR, "data", CHAT_UPLOAD_DIR_NAME))
    except Exception:
        pass
    try:
        candidates.append(os.path.join(os.getcwd(), "data", CHAT_UPLOAD_DIR_NAME))
    except Exception:
        pass

    for c in candidates:
        if not c:
            continue
        try:
            c = os.path.abspath(str(c))
        except Exception:
            c = str(c)
        if c not in paths:
            paths.append(c)
    return paths


def get_chat_upload_folder():
    """Folder for chat media uploads.

    Prefer the shared external data root so media survives restarts and remains
    visible across multi-process deployments. Falls back safely if needed.
    """
    paths = _chat_media_search_paths()
    for base in paths:
        try:
            os.makedirs(base, exist_ok=True)
            test_path = os.path.join(base, '.write_test')
            with open(test_path, 'wb') as fp:
                fp.write(b'1')
            try:
                os.remove(test_path)
            except Exception:
                pass
            return base
        except Exception:
            continue
    # Last resort
    return paths[0] if paths else os.path.join(BASE_DIR, 'data', CHAT_UPLOAD_DIR_NAME)


def _resolve_chat_media_path(filename):
    safe = os.path.basename((filename or '').split('?')[0].strip())
    if not safe:
        return None
    for folder in _chat_media_search_paths():
        try:
            path = os.path.join(folder, safe)
            if os.path.exists(path):
                return path
        except Exception:
            continue
    return None


_chat_media_schema_ready = False


def ensure_chat_media_schema():
    global _chat_media_schema_ready
    if _chat_media_schema_ready:
        return
    db = get_db()
    cur = db.cursor()
    try:
        if DB_ENGINE == "postgres":
            cur.execute("""
                CREATE TABLE IF NOT EXISTS chat_media (
                    id BIGSERIAL PRIMARY KEY,
                    message_id BIGINT NOT NULL,
                    stored_name TEXT NOT NULL,
                    original_name TEXT NOT NULL,
                    mime_type TEXT NOT NULL,
                    size_bytes BIGINT NOT NULL DEFAULT 0,
                    created_at TEXT NOT NULL
                )
                """)
        else:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS chat_media (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    message_id INTEGER NOT NULL,
                    stored_name TEXT NOT NULL,
                    original_name TEXT NOT NULL,
                    mime_type TEXT NOT NULL,
                    size_bytes INTEGER NOT NULL DEFAULT 0,
                    created_at TEXT NOT NULL
                )
                """)
        try:
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_chat_media_message ON chat_media(message_id)"
            )
        except Exception:
            pass
        db.commit()
        _chat_media_schema_ready = True
    except Exception:
        _chat_media_schema_ready = False
        try:
            db.rollback()
        except Exception:
            pass


def _chat_file_kind(mime_type: str, filename: str):
    mt = (mime_type or "").lower()
    if mt.startswith("image/"):
        return "image"
    if mt.startswith("video/"):
        return "video"
    # fallback by extension
    ext = (os.path.splitext(filename or "")[1] or "").lower().lstrip(".")
    if ext in ("png", "jpg", "jpeg", "gif", "bmp", "webp", "svg", "heic", "heif"):
        return "image"
    if ext in ("mp4", "webm", "mov", "avi", "mkv", "m4v", "3gp", "wmv"):
        return "video"
    return "file"


def save_chat_attachment(file, message_id, username, room, visit_id, created_at):
    """
    Save attachment to disk + record in DB.
    Returns attachment dict for UI.
    """
    ensure_chat_media_schema()
    folder = get_chat_upload_folder()
    orig = secure_filename(file.filename or "")
    if not orig:
        raise ValueError("Invalid filename")
    mime = file.mimetype or file.content_type or "application/octet-stream"
    kind = _chat_file_kind(mime, orig)

    # Allow only images/videos
    if kind not in ("image", "video"):
        raise ValueError("Only images/videos are allowed")

    # Generate unique stored name
    import uuid as _uuid

    ext = os.path.splitext(orig)[1].lower()
    stored = f"{_uuid.uuid4().hex}{ext}"
    path = os.path.join(folder, stored)

    file.save(path)

    try:
        size = os.path.getsize(path)
    except Exception:
        size = 0

    db = get_db()
    if DB_ENGINE == "postgres":
        db.execute(
            """
            INSERT INTO chat_media (message_id, stored_name, original_name, mime_type, size_bytes, created_at)
            VALUES (?,?,?,?,?,?)
            """,
            (message_id, stored, orig, mime, size, created_at),
        )
        db.commit()
    else:
        db.execute(
            """
            INSERT INTO chat_media (message_id, stored_name, original_name, mime_type, size_bytes, created_at)
            VALUES (?,?,?,?,?,?)
            """,
            (message_id, stored, orig, mime, size, created_at),
        )
        db.commit()

    return {
        "url": f"/chat/media/{stored}",
        "filename": stored,
        "original_name": orig,
        "mime_type": mime,
        "size_bytes": size,
        "kind": kind,
        "created_at": created_at,
    }


