def ensure_spell_schema():
    """Custom learned words table (best-effort)."""
    db = get_db()
    cur = db.cursor()
    try:
        if DB_ENGINE == "postgres":
            cur.execute("""
                CREATE TABLE IF NOT EXISTS spell_custom_terms (
                    id BIGSERIAL PRIMARY KEY,
                    word TEXT NOT NULL UNIQUE,
                    seen_count INTEGER NOT NULL DEFAULT 1,
                    created_at TEXT NOT NULL,
                    last_seen_at TEXT NOT NULL
                )
                """)
        else:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS spell_custom_terms (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    word TEXT NOT NULL UNIQUE,
                    seen_count INTEGER NOT NULL DEFAULT 1,
                    created_at TEXT NOT NULL,
                    last_seen_at TEXT NOT NULL
                )
                """)
        try:
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_spell_custom_terms_seen ON spell_custom_terms(seen_count)"
            )
        except Exception:
            pass
        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass


def _spell_tokenize(term: str):
    # Extract english word tokens
    import re as _re

    term = (term or "").strip()
    if not term:
        return []
    toks = _re.findall(r"[A-Za-z]{3,32}", term)
    return [t.lower() for t in toks if t]


_SPELL_CACHE = {"ts": 0, "version": "", "terms": []}


def spell_collect_terms(force=False):
    """Collect medical dictionary terms from master data tables (words only)."""
    import time as _time
    import hashlib as _hashlib

    now = _time.time()
    # Refresh every 10 minutes
    if not force and _SPELL_CACHE["terms"] and (now - _SPELL_CACHE["ts"] < 600):
        return _SPELL_CACHE["terms"], _SPELL_CACHE["version"]

    ensure_spell_schema()
    cur = get_db().cursor()

    sources = []
    # Diagnoses (master)
    try:
        rows = cur.execute(
            "SELECT name, icd_code FROM diagnosis_master WHERE is_active=1"
        ).fetchall()
        for r in rows:
            sources.append(r["name"])
            icd = None
            try:
                icd = r["icd_code"]
            except Exception:
                icd = None
            if icd:
                sources.append(icd)
    except Exception:
        pass

    # Meds/Labs/Radiology/Home meds master data
    for table in (
        "items_medications",
        "items_labs",
        "items_radiology",
        "items_home_meds",
    ):
        try:
            rows = cur.execute(f"SELECT name FROM {table} WHERE is_active=1").fetchall()
            for r in rows:
                sources.append(r["name"])
        except Exception:
            pass

    # Learned custom words (only if frequently seen)
    try:
        rows = cur.execute(
            "SELECT word FROM spell_custom_terms WHERE seen_count >= 3 ORDER BY seen_count DESC LIMIT 3000"
        ).fetchall()
        for r in rows:
            sources.append(r["word"])
    except Exception:
        pass

    # Tokenize to words
    terms = set()
    for s in sources:
        for w in _spell_tokenize(s):
            terms.add(w)

    # Fallback: small baseline if DB empty
    if not terms:
        terms.update(
            [
                "abdomen",
                "pelvis",
                "triage",
                "radiology",
                "ultrasound",
                "pneumonia",
                "hypertension",
            ]
        )

    terms_list = sorted(terms)

    # version = short hash
    ver = _hashlib.sha1(
        (",".join(terms_list)).encode("utf-8", errors="ignore")
    ).hexdigest()[:12]

    _SPELL_CACHE["terms"] = terms_list
    _SPELL_CACHE["version"] = ver
    _SPELL_CACHE["ts"] = now
    return terms_list, ver


def _spell_suggest(word: str, terms: list, n=6):
    import difflib as _difflib

    w = (word or "").strip().lower()
    if len(w) < 3:
        return []
    try:
        out = _difflib.get_close_matches(w, terms, n=n, cutoff=0.6)
        if not out:
            out = _difflib.get_close_matches(w, terms, n=n, cutoff=0.5)
        return out[:n]
    except Exception:
        return []


@app.route("/api/spell/bootstrap")
@login_required
def api_spell_bootstrap():
    terms, ver = spell_collect_terms(force=False)
    max_terms = int(APP_CONFIG.get("SPELL_BOOTSTRAP_MAX_TERMS", 12000))
    terms = terms[:max_terms]
    return jsonify({"ok": True, "version": ver, "terms": terms})


@app.route("/api/spell/suggest")
@login_required
def api_spell_suggest():
    word = (request.args.get("word") or "").strip()
    terms, ver = spell_collect_terms(force=False)
    suggestions = _spell_suggest(
        word, terms, n=int(APP_CONFIG.get("SPELL_MAX_SUGGEST", 6))
    )
    return jsonify(
        {"ok": True, "version": ver, "word": word, "suggestions": suggestions}
    )


@app.route("/api/spell/learn", methods=["POST"])
@login_required
def api_spell_learn():
    """Receive a word candidate from the browser (auto-learn)."""
    ensure_spell_schema()
    data = request.get_json(silent=True) or {}
    w = (data.get("word") or "").strip().lower()

    import re as _re

    if not _re.fullmatch(r"[a-z]{4,32}", w or ""):
        return jsonify({"ok": True, "ignored": True})

    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    db = get_db()
    cur = db.cursor()
    try:
        row = cur.execute(
            "SELECT id, seen_count FROM spell_custom_terms WHERE word = ?", (w,)
        ).fetchone()
        if row:
            newc = int(row["seen_count"] or 1) + 1
            cur.execute(
                "UPDATE spell_custom_terms SET seen_count = ?, last_seen_at = ? WHERE word = ?",
                (newc, now, w),
            )
        else:
            cur.execute(
                "INSERT INTO spell_custom_terms (word, seen_count, created_at, last_seen_at) VALUES (?,?,?,?)",
                (w, 1, now, now),
            )
        db.commit()
        _SPELL_CACHE["ts"] = 0
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass

    return jsonify({"ok": True})


