def get_system_picklist_options(category, fallback_options=None):
    """Return list of dicts: [{'value':..,'label':..}] for a category."""
    fallback_options = fallback_options or []
    try:
        ensure_system_picklists_schema(seed_defaults=True)
    except Exception:
        return [{"value": v, "label": v} for v in fallback_options]

    db = get_db()
    cur = db.cursor()
    try:
        rows = cur.execute(
            """
            SELECT value, COALESCE(NULLIF(TRIM(label),''), value) AS label
            FROM system_picklists
            WHERE category=? AND is_active=1
            ORDER BY sort_order ASC, id ASC
            """,
            (category,),
        ).fetchall()
        out = []
        for r in rows:
            try:
                out.append({"value": r["value"], "label": r["label"]})
            except Exception:
                out.append({"value": r[0], "label": r[1]})
        if out:
            return out
    except Exception:
        pass
    return [{"value": v, "label": v} for v in fallback_options]


def _ao_status_upper(x):
    return (x or "").strip().upper()


def ao_badge_class(status):
    s = _ao_status_upper(status)
    if s == "ORDERED":
        return "bg-primary"
    if s == "UNDER_REVIEW":
        return "bg-info text-dark"
    if s == "PENDING_BED":
        return "bg-warning text-dark"
    if s == "PENDING_APPROVAL":
        return "bg-warning text-dark"
    if s == "READY":
        return "bg-success"
    if s == "ADMITTED":
        return "bg-success"
    if s == "CANCELLED":
        return "bg-secondary"
    if s == "REPLACED":
        return "bg-secondary"
    return "bg-light text-dark border"


def ao_sla_badge_class(age_min):
    try:
        age = int(age_min)
    except Exception:
        return "bg-light text-dark border"
    # Simple SLA: <30 green, <120 yellow, else red
    if age < 30:
        return "bg-success"
    if age < 120:
        return "bg-warning text-dark"
    return "bg-danger"


def get_preferred_admission_order_for_visit(visit_id):
    """Active order first; else latest order for visit. Returns dict or None."""
    try:
        ensure_admission_orders_enterprise_upgrade()
    except Exception:
        pass
    db = get_db()
    cur = db.cursor()
    try:
        q = """
            SELECT *
            FROM admission_orders
            WHERE visit_id=?
            ORDER BY
              CASE WHEN UPPER(COALESCE(status,'')) IN ({active}) THEN 0 ELSE 1 END,
              id DESC
            LIMIT 1
        """.format(active=",".join(["?"] * len(AO_ACTIVE_STATUSES)))
        params = [visit_id] + AO_ACTIVE_STATUSES
        row = cur.execute(q, params).fetchone()
        if row:
            try:
                return dict(row)
            except Exception:
                return {k: row[k] for k in row.keys()}
    except Exception:
        pass
    return None


def get_admission_order_summary(visit_id):
    """
    Return lightweight admission order summary for boards.
    Keys:
      - admission_orders_count
      - admission_order_id
      - admission_order_status
      - admission_order_created_at
      - admission_order_age_min
      - adm_badge_class
      - adm_sla_badge_class
      - admission_order_assigned_to
    """
    summary = {
        "admission_orders_count": 0,
        "admission_order_id": None,
        "admission_order_status": "",
        "admission_order_created_at": "",
        "admission_order_age_min": None,
        "adm_badge_class": "",
        "adm_sla_badge_class": "",
        "admission_order_assigned_to": "",
    }
    try:
        ensure_admission_orders_enterprise_upgrade()
    except Exception:
        return summary

    db = get_db()
    cur = db.cursor()
    try:
        cnt = cur.execute(
            "SELECT COUNT(*) AS c FROM admission_orders WHERE visit_id=?", (visit_id,)
        ).fetchone()
        c = cnt["c"] if hasattr(cnt, "__getitem__") else cnt[0]
        summary["admission_orders_count"] = int(c or 0)
    except Exception:
        pass

    row = get_preferred_admission_order_for_visit(visit_id)
    if not row:
        return summary

    summary["admission_order_id"] = row.get("id")
    summary["admission_order_status"] = row.get("status") or ""
    summary["admission_order_created_at"] = row.get("created_at") or ""
    summary["admission_order_assigned_to"] = row.get("assigned_to") or ""
    age = calc_minutes_between(row.get("created_at"), now_display_str("%Y-%m-%d %H:%M"))
    try:
        summary["admission_order_age_min"] = int(age) if age is not None else None
    except Exception:
        summary["admission_order_age_min"] = age
    summary["adm_badge_class"] = ao_badge_class(summary["admission_order_status"])
    summary["adm_sla_badge_class"] = ao_sla_badge_class(
        summary["admission_order_age_min"]
    )
    return summary


def _update_visit_admission_order_status_snapshot(visit_id, status):
    try:
        db = get_db()
        db.execute(
            "UPDATE visits SET admission_order_status=? WHERE visit_id=?",
            ((status or "").strip().upper(), visit_id),
        )
        db.commit()
    except Exception:
        try:
            get_db().rollback()
        except Exception:
            pass



