def _master_data_now_ts():
    try:
        return now_display_str("%Y-%m-%d %H:%M")
    except Exception:
        return datetime.now().strftime("%Y-%m-%d %H:%M:%S")



def _master_data_row_to_dict(row):
    try:
        return dict(row)
    except Exception:
        data = {}
        try:
            keys = getattr(row, "keys", lambda: [])()
            for k in keys:
                data[k] = row[k]
            if data:
                return data
        except Exception:
            pass
        return data




def _master_data_load_system_rows(cur, selected_category=None):
    rows = []
    selected_category = (selected_category or "").strip().lower()
    try:
        if selected_category:
            rows = cur.execute(
                """
                SELECT *
                  FROM system_picklists
                 WHERE category=?
                 ORDER BY is_active DESC,
                          sort_order ASC,
                          COALESCE(label, value) ASC,
                          value ASC,
                          id ASC
                """,
                (selected_category,),
            ).fetchall()
        else:
            rows = cur.execute(
                """
                SELECT *
                  FROM system_picklists
                 ORDER BY category ASC,
                          is_active DESC,
                          sort_order ASC,
                          COALESCE(label, value) ASC,
                          value ASC,
                          id ASC
                """
            ).fetchall()
    except Exception:
        rows = []
    return [_master_data_row_to_dict(r) for r in (rows or [])]



