def _master_data_normalize_category(value, choices, allow_blank=True):
    raw = (value or "").strip().lower()
    allowed = [str(v or "").strip().lower() for v, _label in (choices or []) if str(v or "").strip()]
    if raw in allowed:
        return raw
    if allow_blank:
        return ""
    return allowed[0] if allowed else ""



def _master_data_default_category(choices):
    try:
        return str((choices or [])[0][0] or "").strip().lower()
    except Exception:
        return ""



def _admin_master_data_redirect(tab="registration", reg_category=None, adm_category=None):
    tab = (tab or "registration").strip().lower() or "registration"
    if tab not in ("registration", "admission"):
        tab = "registration"

    if reg_category is None:
        reg_category = request.values.get("reg_category")
        if not reg_category and tab == "registration":
            reg_category = request.values.get("category")
    if adm_category is None:
        adm_category = request.values.get("adm_category")
        if not adm_category and tab == "admission":
            adm_category = request.values.get("category")

    reg_category = _master_data_normalize_category(reg_category, MASTER_DATA_SYSTEM_CATEGORY_CHOICES, allow_blank=True)
    adm_category = _master_data_normalize_category(adm_category, MASTER_DATA_ADMISSION_CATEGORY_CHOICES, allow_blank=True)

    return redirect(
        url_for(
            "admin_master_data",
            tab=tab,
            reg_category=reg_category,
            adm_category=adm_category,
        )
    )


