def _admin_master_data_add_system(db, cur, actor):
    category = (request.form.get("category") or "").strip()
    value = (request.form.get("value") or "").strip()
    label = (request.form.get("label") or "").strip()
    sort_order_raw = (request.form.get("sort_order") or "100").strip()
    try:
        sort_order = int(sort_order_raw)
    except Exception:
        sort_order = 100

    if not category or not value:
        flash("Category and value are required.", "danger")
        return _admin_master_data_redirect("registration")

    now_ts = _master_data_now_ts()
    try:
        if DB_ENGINE == "postgres":
            cur.execute(
                """
                INSERT INTO system_picklists
                    (category, value, label, sort_order, is_active, created_at, created_by, updated_at, updated_by)
                VALUES (%s, %s, %s, %s, 1, %s, %s, %s, %s)
                ON CONFLICT (category, value) DO UPDATE SET
                    label=EXCLUDED.label,
                    sort_order=EXCLUDED.sort_order,
                    is_active=1,
                    updated_at=EXCLUDED.updated_at,
                    updated_by=EXCLUDED.updated_by
                """,
                (category, value, label or value, sort_order, now_ts, actor, now_ts, actor),
            )
        else:
            cur.execute(
                """
                INSERT OR IGNORE INTO system_picklists
                    (category, value, label, sort_order, is_active, created_at, created_by, updated_at, updated_by)
                VALUES (?, ?, ?, ?, 1, ?, ?, ?, ?)
                """,
                (category, value, label or value, sort_order, now_ts, actor, now_ts, actor),
            )
            cur.execute(
                """
                UPDATE system_picklists
                   SET label=?,
                       sort_order=?,
                       is_active=1,
                       updated_at=?,
                       updated_by=?
                 WHERE category=? AND value=?
                """,
                (label or value, sort_order, now_ts, actor, category, value),
            )
        db.commit()
        flash("Registration master data saved.", "success")
    except Exception as e:
        _rollback_with_logging(db, "admin_master_data add_system")
        flash(f"Failed to save registration item: {e}", "danger")
    return _admin_master_data_redirect("registration")



def _admin_master_data_edit_system(db, cur, actor):
    item_id = (request.form.get("id") or "").strip()
    category = (request.form.get("category") or "").strip()
    value = (request.form.get("value") or "").strip()
    label = (request.form.get("label") or "").strip()
    sort_order_raw = (request.form.get("sort_order") or "100").strip()
    is_active_raw = (request.form.get("is_active") or "1").strip()
    try:
        sort_order = int(sort_order_raw)
    except Exception:
        sort_order = 100
    try:
        is_active = int(is_active_raw)
    except Exception:
        is_active = 1

    if not item_id or not category or not value:
        flash("Missing registration row data.", "danger")
        return _admin_master_data_redirect("registration")

    try:
        cur.execute(
            """
            UPDATE system_picklists
               SET category=?,
                   value=?,
                   label=?,
                   sort_order=?,
                   is_active=?,
                   updated_at=?,
                   updated_by=?
             WHERE id=?
            """,
            (category, value, label or value, sort_order, is_active, _master_data_now_ts(), actor, int(item_id)),
        )
        db.commit()
        flash("Registration item updated.", "success")
    except Exception as e:
        _rollback_with_logging(db, "admin_master_data edit_system")
        flash(f"Failed to update registration item: {e}", "danger")
    return _admin_master_data_redirect("registration")



def _admin_master_data_delete_system(db, cur):
    item_id = (request.form.get("id") or "").strip()
    if not item_id:
        flash("Missing registration item id.", "danger")
        return _admin_master_data_redirect("registration")
    try:
        cur.execute("DELETE FROM system_picklists WHERE id=?", (int(item_id),))
        db.commit()
        try:
            log_action("SYS_PICKLIST_DELETE", details=f"id={item_id}")
        except Exception:
            pass
        flash("Registration item deleted.", "success")
    except Exception as e:
        _rollback_with_logging(db, "admin_master_data delete_system")
        flash(f"Failed to delete registration item: {e}", "danger")
    return _admin_master_data_redirect("registration")



def _admin_master_data_add_admission(db, cur, actor):
    category = (request.form.get("category") or "").strip().lower()
    value = (request.form.get("value") or "").strip()
    label = (request.form.get("label") or "").strip()
    extra = (request.form.get("extra") or "").strip()

    if not category or not value:
        flash("Category and value are required.", "danger")
        return _admin_master_data_redirect("admission")

    try:
        add_admission_picklist_item(category, value, label, extra, actor=actor)
        flash("Admission master data saved.", "success")
    except Exception as e:
        flash(f"Failed to save admission item: {e}", "danger")
    return _admin_master_data_redirect("admission")



def _admin_master_data_edit_admission(db, cur):
    item_id = (request.form.get("id") or "").strip()
    category = (request.form.get("category") or "").strip().lower()
    value = (request.form.get("value") or "").strip()
    label = (request.form.get("label") or "").strip()
    extra = (request.form.get("extra") or "").strip()
    is_active_raw = (request.form.get("is_active") or "1").strip()
    try:
        is_active = int(is_active_raw)
    except Exception:
        is_active = 1

    if not item_id or not category or not value:
        flash("Missing admission row data.", "danger")
        return _admin_master_data_redirect("admission")

    try:
        cur.execute(
            """
            UPDATE admission_order_picklists
               SET category=?,
                   value=?,
                   label=?,
                   extra=?,
                   is_active=?
             WHERE id=?
            """,
            (category, value, label, extra, is_active, int(item_id)),
        )
        db.commit()
        flash("Admission item updated.", "success")
    except Exception as e:
        _rollback_with_logging(db, "admin_master_data edit_admission")
        flash(f"Failed to update admission item: {e}", "danger")
    return _admin_master_data_redirect("admission")



