@app.route("/admin/master_data", methods=["GET", "POST"])
@login_required
@role_required("admin")
def admin_master_data():
    try:
        ensure_admission_picklists_schema()
    except Exception as ensure_exc:
        _log_noncritical_exception("admin_master_data: ensure_admission_picklists_schema", ensure_exc)
    try:
        ensure_system_picklists_schema(seed_defaults=True)
    except Exception as ensure_exc:
        _log_noncritical_exception("admin_master_data: ensure_system_picklists_schema", ensure_exc)
    try:
        ensure_code_orange_config_schema(seed_defaults=True)
    except Exception as ensure_exc:
        _log_noncritical_exception("admin_master_data: ensure_code_orange_config_schema", ensure_exc)

    db = get_db()
    cur = db.cursor()
    actor = session.get("username", "")

    if request.method == "POST":
        action = (request.form.get("action") or "").strip()
        if action == "add_system":
            return _admin_master_data_add_system(db, cur, actor)
        if action == "edit_system":
            return _admin_master_data_edit_system(db, cur, actor)
        if action == "delete_system":
            return _admin_master_data_delete_system(db, cur)
        if action == "add_adm":
            return _admin_master_data_add_admission(db, cur, actor)
        if action == "edit_adm":
            return _admin_master_data_edit_admission(db, cur)
        if action == "delete_adm":
            return _admin_master_data_delete_admission(db, cur)
        flash("Unsupported master data action.", "warning")
        return _admin_master_data_redirect(request.form.get("tab") or "registration")

    active_tab = (request.args.get("tab") or "registration").strip().lower()
    if active_tab not in ("registration", "admission", "code_orange"):
        active_tab = "registration"

    selected_reg_category = _master_data_normalize_category(
        request.args.get("reg_category"),
        MASTER_DATA_SYSTEM_CATEGORY_CHOICES,
        allow_blank=False,
    )
    selected_adm_category = _master_data_normalize_category(
        request.args.get("adm_category"),
        MASTER_DATA_ADMISSION_CATEGORY_CHOICES,
        allow_blank=False,
    )
    if not selected_reg_category:
        selected_reg_category = _master_data_default_category(MASTER_DATA_SYSTEM_CATEGORY_CHOICES)
    if not selected_adm_category:
        selected_adm_category = _master_data_default_category(MASTER_DATA_ADMISSION_CATEGORY_CHOICES)

    system_rows = _master_data_load_system_rows(cur, selected_reg_category)
    admission_rows = _master_data_load_admission_rows(cur, selected_adm_category)
    code_orange_rows = _co_config_rows(cur=cur, include_inactive=True)

    return render_template(
        "admin_master_data.html",
        active_tab=active_tab,
        registration_rows=system_rows,
        admission_rows=admission_rows,
        registration_categories=_master_data_registration_category_options(),
        admission_categories=_master_data_admission_category_options(),
        selected_reg_category=selected_reg_category,
        selected_adm_category=selected_adm_category,
        code_orange_rows=code_orange_rows,
        code_orange_categories=[{"value": v, "label": label} for v, label in CODE_ORANGE_CONFIG_CATEGORY_CHOICES],
    )


