@login_required
@role_required("admin")
def admin_code_orange_add():
    try:
        ensure_code_orange_config_schema(seed_defaults=True)
    except Exception as exc:
        _log_noncritical_exception("admin_code_orange_add: ensure schema", exc)
    category = (request.form.get("item_category") or "").strip()
    item_name = (request.form.get("item_name") or "").strip()
