# ------------------------------------------------------------
# Admission Reports (Enterprise)
# ------------------------------------------------------------
def _report_row_get(row, key, idx=None, default=""):
    try:
        val = row[key]
        return default if val is None else val
    except Exception:
        pass
    if idx is not None:
        try:
            val = row[idx]
            return default if val is None else val
        except Exception:
            pass
    try:
        val = row.get(key)
        return default if val is None else val
    except Exception:
        return default


def _report_clean_label(val, default_label="UNKNOWN"):
    try:
        s = str(val or "").strip()
    except Exception:
        s = ""
    return s if s else default_label


def _report_to_date_only(val):
    """Normalize report date input/timestamp into date object or None."""
    if val is None:
        return None
    try:
        if hasattr(val, "year") and hasattr(val, "month") and hasattr(val, "day"):
            # datetime/date objects
            try:
                return val.date()
            except Exception:
                return val
    except Exception:
        pass
    s = str(val or "").strip()
    if not s:
        return None
    # Keep report filters stable: prefer explicit date text as stored
    # (avoid timezone shifting naive DB strings into the next/previous day).
    m = re.match(r"^\s*(\d{4}-\d{2}-\d{2})", s)
    if m:
        try:
            return datetime.strptime(m.group(1), "%Y-%m-%d").date()
        except Exception:
            pass
    m = re.match(r"^\s*(\d{2}/\d{2}/\d{4})", s)
    if m:
        for fmt in ("%d/%m/%Y", "%m/%d/%Y"):
            try:
                return datetime.strptime(m.group(1), fmt).date()
            except Exception:
                continue
    try:
        d = _parse_to_local_naive(val)
        if d:
            return d.date()
    except Exception:
        pass
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%m/%d/%Y"):
        try:
            return datetime.strptime(s, fmt).date()
        except Exception:
            continue
    return None


def _report_date_in_range(dt_val, dfrom, dto):
    d = _report_to_date_only(dt_val)
    if not d:
        return False
    dfrom_d = _report_to_date_only(dfrom) if dfrom else None
    dto_d = _report_to_date_only(dto) if dto else None
    if dfrom_d and d < dfrom_d:
        return False
    if dto_d and d > dto_d:
        return False
    return True


def _report_any_date_in_range(dfrom, dto, *date_values):
    """True when at least one provided timestamp falls inside the range."""
    for dv in date_values or ():
        if _report_date_in_range(dv, dfrom, dto):
            return True
    return False


def _report_sorted_rows(counter_map, key_name):
    rows = [{key_name: k, "c": int(v or 0)} for k, v in (counter_map or {}).items()]
    rows.sort(key=lambda item: (-int(item.get("c", 0) or 0), str(item.get(key_name, "")).upper()))
    return rows


def _collect_admission_report_data(cur, dfrom, dto):
    visits_with_orders = set()
    by_dest_map = {}
    by_status_map = {}
    durations = []

    def _inc(bucket, key):
        key = _report_clean_label(key)
        bucket[key] = int(bucket.get(key, 0) or 0) + 1

    # Destination should prefer doctor's Admission Order picklist codes,
    # but must still include legacy/processing values (e.g. IPADM, WARD).
    allowed_dest_codes = set()
    allowed_dest_labels_to_code = {}
    try:
        for code, label in picklist_merge_destinations(
            [("IP", "IP"), ("DC", "DC"), ("ICU", "ICU"), ("LDR", "LDR"), ("SCBU", "SCBU")]
        ):
            c = str(code or "").strip().upper()
            l = str(label or "").strip().upper()
            if c:
                allowed_dest_codes.add(c)
                allowed_dest_labels_to_code[c] = c
            if l:
                allowed_dest_labels_to_code[l] = c or l
    except Exception:
        allowed_dest_codes = {"IP", "DC", "ICU", "LDR", "SCBU"}
        allowed_dest_labels_to_code = {k: k for k in allowed_dest_codes}

    def _normalize_destination(raw_dest):
        d = str(raw_dest or "").strip().upper()
        if not d:
            return ""
        if d in allowed_dest_codes:
            return d
        # Map known labels -> code; otherwise keep raw destination value.
        return allowed_dest_labels_to_code.get(d, d)

    order_rows = []
    try:
        order_rows = cur.execute(
            """
            SELECT visit_id, destination, status, created_at, ref_datetime, admitted_at
            FROM admission_orders
            ORDER BY id DESC
            """
        ).fetchall()
    except Exception:
        order_rows = []

    for r in order_rows or []:
        visit_id = str(_report_row_get(r, "visit_id", 0, "") or "").strip()
        if visit_id:
            visits_with_orders.add(visit_id)

        destination = _normalize_destination(_report_row_get(r, "destination", 1, ""))
        status = _report_clean_label(_report_row_get(r, "status", 2, "")).upper()
        created_at = _report_row_get(r, "created_at", 3, "")
        ref_datetime = _report_row_get(r, "ref_datetime", 4, "")
        admitted_at = _report_row_get(r, "admitted_at", 5, "")

        # Some sites backfill/adjust created_at later than referral date; count row if
        # any clinically relevant timestamp is inside the selected date range.
        if not _report_any_date_in_range(
            dfrom, dto, created_at, ref_datetime, admitted_at
        ):
            continue

        if destination:
            _inc(by_dest_map, destination)
        _inc(by_status_map, status)

        if status == "ADMITTED" and admitted_at:
            mins = calc_minutes_between(created_at or ref_datetime or admitted_at, admitted_at)
            if mins is not None:
                try:
                    mins = int(mins)
                    if mins >= 0:
                        durations.append(mins)
                except Exception:
                    pass

    legacy_rows = []
    try:
        legacy_rows = cur.execute(
            """
            SELECT visit_id, admission_destination, admission_order_status, admission_ref_datetime, created_at
            FROM visits
            WHERE COALESCE(NULLIF(TRIM(admission_destination),''), '') <> ''
               OR COALESCE(NULLIF(TRIM(admission_order_status),''), '') <> ''
               OR COALESCE(NULLIF(TRIM(admission_ref_datetime),''), '') <> ''
            """
        ).fetchall()
    except Exception:
        legacy_rows = []

    for r in legacy_rows or []:
        visit_id = str(_report_row_get(r, "visit_id", 0, "") or "").strip()
        if visit_id and visit_id in visits_with_orders:
            continue

        destination = _normalize_destination(_report_row_get(r, "admission_destination", 1, ""))
        status = _report_clean_label(_report_row_get(r, "admission_order_status", 2, "")).upper()
        ref_datetime = _report_row_get(r, "admission_ref_datetime", 3, "")
        created_at = _report_row_get(r, "created_at", 4, "")
        order_ts = ref_datetime or created_at

        if not _report_date_in_range(order_ts, dfrom, dto):
            continue

        if destination:
            _inc(by_dest_map, destination)
        _inc(by_status_map, status)

    # Fallback for sites that never populated admission_orders/admission_* columns:
    # derive operational counts from visits table so cards still show patient workload.
    if not by_dest_map and not by_status_map:
        visit_rows = []
        try:
            visit_rows = cur.execute(
                """
                SELECT visit_id, clinic, status, admission_destination, admission_order_status, created_at
                FROM visits
                """
            ).fetchall()
        except Exception:
            visit_rows = []

        for r in visit_rows or []:
            created_at = _report_row_get(r, "created_at", 5, "")
            if not _report_date_in_range(created_at, dfrom, dto):
                continue

            status = _report_clean_label(
                _report_row_get(r, "admission_order_status", 4, "")
            ).upper()
            if status in ("", "UNKNOWN"):
                status = _report_clean_label(_report_row_get(r, "status", 2, "")).upper()
            if status in ("", "UNKNOWN"):
                continue

            destination = _normalize_destination(_report_row_get(r, "admission_destination", 3, ""))
            if destination:
                _inc(by_dest_map, destination)
            _inc(by_status_map, status)

    avg_mins = int(sum(durations) / len(durations)) if durations else None
    return _report_sorted_rows(by_dest_map, "destination"), _report_sorted_rows(by_status_map, "status"), avg_mins


def _collect_visit_outcome_counts(cur, dfrom, dto, wanted_status, value_field, key_name, empty_label):
    rows = []
    try:
        rows = cur.execute(
            f"SELECT created_at, {value_field} AS report_value FROM visits WHERE UPPER(COALESCE(status,''))=?",
            (wanted_status,),
        ).fetchall()
    except Exception:
        rows = []

    counter_map = {}
    for r in rows or []:
        created_at = _report_row_get(r, "created_at", 0, "")
        if not _report_date_in_range(created_at, dfrom, dto):
            continue
        label = _report_clean_label(_report_row_get(r, "report_value", 1, ""), empty_label)
        counter_map[label] = int(counter_map.get(label, 0) or 0) + 1

    return _report_sorted_rows(counter_map, key_name)

@app.route("/reports/admission")
@login_required
def admission_reports():
    try:
        ensure_admission_orders_enterprise_upgrade()
    except Exception:
        pass

    dfrom = (request.args.get("date_from", "") or "").strip()
    dto = (request.args.get("date_to", "") or "").strip()

    # Default: last 7 days
    if not dfrom or not dto:
        today = datetime.today().date()
        dto = today.strftime("%Y-%m-%d")
        dfrom = (today - timedelta(days=6)).strftime("%Y-%m-%d")
    else:
        # Accept browser locale inputs too (e.g. MM/DD/YYYY or DD/MM/YYYY)
        dfrom_n = _report_to_date_only(dfrom)
        dto_n = _report_to_date_only(dto)
        if dfrom_n:
            dfrom = dfrom_n.strftime("%Y-%m-%d")
        if dto_n:
            dto = dto_n.strftime("%Y-%m-%d")

    if dfrom and not dto:
        dto = dfrom
    if dto and not dfrom:
        dfrom = dto

    start_ts = f"{dfrom} 00:00"
    end_ts = f"{dto} 23:59"

    db = get_db()
    cur = db.cursor()

    by_dest, by_status, avg_mins = _collect_admission_report_data(cur, dfrom, dto)
    lama_counts = _collect_visit_outcome_counts(
        cur, dfrom, dto, "LAMA", "lama_reason", "reason", "(no reason)"
    )
    transfer_counts = _collect_visit_outcome_counts(
        cur, dfrom, dto, "TRANSFERRED", "transfer_hospital", "hospital", "(no hospital)"
    )
    total_admission = sum(int(r.get("c", 0) or 0) for r in (by_status or []))
    admitted_count = sum(
        int(r.get("c", 0) or 0)
        for r in (by_status or [])
        if str(r.get("status", "")).upper() == "ADMITTED"
    )
    total_lama = sum(int(r.get("c", 0) or 0) for r in (lama_counts or []))
    total_transferred = sum(int(r.get("c", 0) or 0) for r in (transfer_counts or []))

    return render_template(
        "admission_reports.html",
        dfrom=dfrom,
        dto=dto,
        by_dest=by_dest,
        by_status=by_status,
        avg_mins=avg_mins,
        lama_counts=lama_counts,
        transfer_counts=transfer_counts,
        total_admission=total_admission,
        admitted_count=admitted_count,
        total_lama=total_lama,
        total_transferred=total_transferred,
    )


@app.route("/reports/admission.csv")
@login_required
def admission_reports_csv():
    """Export admission orders in date range as CSV."""
    try:
        ensure_admission_orders_enterprise_upgrade()
    except Exception:
        pass

    dfrom = (request.args.get("date_from", "") or "").strip()
    dto = (request.args.get("date_to", "") or "").strip()

    if not dfrom or not dto:
        today = datetime.today().date()
        dto = today.strftime("%Y-%m-%d")
        dfrom = (today - timedelta(days=6)).strftime("%Y-%m-%d")
    else:
        dfrom_n = _report_to_date_only(dfrom)
        dto_n = _report_to_date_only(dto)
        if dfrom_n:
            dfrom = dfrom_n.strftime("%Y-%m-%d")
        if dto_n:
            dto = dto_n.strftime("%Y-%m-%d")

    start_ts = f"{dfrom} 00:00"
    end_ts = f"{dto} 23:59"

    db = get_db()
    cur = db.cursor()
    rows = []
    try:
        rows = cur.execute(
            """
            SELECT id, visit_id, destination, admit_dr, admission_type, dx,
                   ward, bed_no, approval_no,
                   status, assigned_to, created_at, created_by, admitted_at, admitted_by,
                   cancelled_at, cancelled_by, cancel_reason, status_note
            FROM admission_orders
            WHERE created_at >= ? AND created_at <= ?
            ORDER BY id DESC
            """,
            (start_ts, end_ts),
        ).fetchall()
    except Exception:
        rows = []

    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(
        [
            "id",
            "visit_id",
            "destination",
            "admit_dr",
            "admission_type",
            "dx",
            "ward",
            "room_no",
            "approval_no",
            "status",
            "assigned_to",
            "created_at",
            "created_by",
            "admitted_at",
            "admitted_by",
            "cancelled_at",
            "cancelled_by",
            "cancel_reason",
            "status_note",
        ]
    )
    for r in rows:
        try:
            writer.writerow(
                [
                    r["id"],
                    r["visit_id"],
                    r["destination"],
                    r["admit_dr"],
                    r["admission_type"],
                    r["dx"],
                    r["ward"],
                    r["bed_no"],
                    r["approval_no"],
                    r["status"],
                    r.get("assigned_to", ""),
                    r["created_at"],
                    r["created_by"],
                    r["admitted_at"],
                    r["admitted_by"],
                    r["cancelled_at"],
                    r["cancelled_by"],
                    r["cancel_reason"],
                    r.get("status_note", ""),
                ]
            )
        except Exception:
            writer.writerow(list(r))

    resp = Response(output.getvalue(), mimetype="text/csv")
    resp.headers["Content-Disposition"] = (
        f"attachment; filename=admission_orders_{dfrom}_to_{dto}.csv"
    )
    return resp


# ------------------------------------------------------------
# IPADM Bulk Action (Enterprise)
# ------------------------------------------------------------
@app.route("/ipadm/bulk", methods=["POST"])
@login_required
@role_required("admin", "inpatient_billing")
def ipadm_bulk_action():
    try:
        ensure_admission_orders_enterprise_upgrade()
    except Exception:
        pass

    order_ids = request.form.getlist("order_ids")
    action = (request.form.get("bulk_action") or "").strip()
    new_stage = (request.form.get("bulk_stage") or "").strip().upper()
    assign_to = (request.form.get("bulk_assign_to") or "").strip()
    actor = session.get("username", "")
    now_ts = now_display_str("%Y-%m-%d %H:%M")

    if not order_ids:
        flash("No rows selected.", "warning")
        return redirect(url_for("clinic_board", clinic="IPADM"))

    db = get_db()
    cur = db.cursor()

    updated = 0
    skipped = 0

    for oid in order_ids:
        try:
            oid_int = int(oid)
        except Exception:
            continue
        try:
            row = cur.execute(
                "SELECT * FROM admission_orders WHERE id=?", (oid_int,)
            ).fetchone()
        except Exception:
            row = None
        if not row:
            continue
        try:
            o = dict(row)
        except Exception:
            o = {k: row[k] for k in row.keys()}
        st = _ao_status_upper(o.get("status"))
        if st in AO_TERMINAL_STATUSES:
            skipped += 1
            continue

        try:
            if action == "assign_me":
                cur.execute(
                    """
                    UPDATE admission_orders
                       SET assigned_to=?, assigned_at=?, assigned_by=?, updated_at=?, updated_by=?
                     WHERE id=?
                    """,
                    (actor, now_ts, actor, now_ts, actor, oid_int),
                )
                ao_audit(
                    oid_int,
                    o.get("visit_id"),
                    "ASSIGN",
                    field_name="assigned_to",
                    old_value=o.get("assigned_to", ""),
                    new_value=actor,
                    note="Bulk assign to me",
                    actor=actor,
                )
                updated += 1

            elif action == "assign_to":
                if not assign_to:
                    skipped += 1
                    continue
                cur.execute(
                    """
                    UPDATE admission_orders
                       SET assigned_to=?, assigned_at=?, assigned_by=?, updated_at=?, updated_by=?
                     WHERE id=?
                    """,
                    (assign_to, now_ts, actor, now_ts, actor, oid_int),
                )
                ao_audit(
                    oid_int,
                    o.get("visit_id"),
                    "ASSIGN",
                    field_name="assigned_to",
                    old_value=o.get("assigned_to", ""),
                    new_value=assign_to,
                    note="Bulk assign",
                    actor=actor,
                )
                updated += 1

            elif action == "unassign":
                cur.execute(
                    """
                    UPDATE admission_orders
                       SET assigned_to=NULL, assigned_at=?, assigned_by=?, updated_at=?, updated_by=?
                     WHERE id=?
                    """,
                    (now_ts, actor, now_ts, actor, oid_int),
                )
                ao_audit(
                    oid_int,
                    o.get("visit_id"),
                    "UNASSIGN",
                    field_name="assigned_to",
                    old_value=o.get("assigned_to", ""),
                    new_value="",
                    note="Bulk unassign",
                    actor=actor,
                )
                updated += 1

            elif action == "set_stage":
                if new_stage not in AO_STAGE_OPTIONS:
                    skipped += 1
                    continue
                cur.execute(
                    """
                    UPDATE admission_orders
                       SET status=?, status_note=?, stage_updated_at=?, stage_updated_by=?, updated_at=?, updated_by=?
                     WHERE id=?
                    """,
                    (
                        new_stage,
                        (o.get("status_note") or ""),
                        now_ts,
                        actor,
                        now_ts,
                        actor,
                        oid_int,
                    ),
                )
                ao_audit(
                    oid_int,
                    o.get("visit_id"),
                    "STAGE_CHANGE",
                    field_name="status",
                    old_value=o.get("status", ""),
                    new_value=new_stage,
                    note="Bulk stage update",
                    actor=actor,
                )
                _update_visit_admission_order_status_snapshot(
                    o.get("visit_id"), new_stage
                )
                updated += 1
            else:
                skipped += 1
        except Exception:
            skipped += 1

    try:
        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass

    flash(f"Bulk action done. Updated: {updated} | Skipped: {skipped}", "success")
    return redirect(url_for("clinic_board", clinic="IPADM"))


# ------------------------------------------------------------
# Enterprise Overrides: Boards + Admission Order actions
# ------------------------------------------------------------
@login_required
def ed_board_enterprise():
    """
    ED Board (enterprise override): keeps same filters/paging,
    plus admission order badge & action visibility.
    """
    try:
        ensure_admission_orders_enterprise_upgrade()
    except Exception:
        pass

    # Ensure clinic column exists (so we can filter ED-only)
    try:
        ensure_clinic_schema()
    except Exception:
        pass

    status_filter = (request.args.get("status", "ALL") or "ALL").strip().upper()
    cat_filter = request.args.get("cat", "ALL")
    visit_f = (request.args.get("visit_id", "") or "").strip()
    user_f = (request.args.get("user", "") or "").strip()
    q = (request.args.get("q", "") or "").strip()
    dfrom = (request.args.get("date_from", "") or "").strip()
    dto = (request.args.get("date_to", "") or "").strip()

    sql = """
        SELECT v.visit_id,
               v.queue_no,
               v.triage_status,
               v.triage_cat,
               v.status,
               v.payment_details,
               v.created_at,
               v.created_by,
               v.closed_at,
               v.location,
               v.bed_no,
               v.bed_status,
               v.task_reg,
               v.task_ekg,
               v.task_sepsis,
               v.task_iv,
               v.task_blood,
               v.task_meds,
               v.task_ct,
               v.task_xray,
               v.task_lab,
               v.task_ua,
               v.task_dc,
               v.visit_type,
               v.assigned_doctor,
               p.name,
               p.mrn,
               p.id_number,
               p.insurance,
               p.dob AS dob,
               (
                   SELECT a.id
                   FROM attachments a
                   WHERE a.visit_id = v.visit_id
                     AND a.filename NOT LIKE '%_LAB_%'
                     AND a.filename NOT LIKE '%_RAD_%'
                   ORDER BY a.uploaded_at DESC
                   LIMIT 1
               ) AS id_attachment_id,
               (
                   SELECT a.filename
                   FROM attachments a
                   WHERE a.visit_id = v.visit_id
                     AND a.filename NOT LIKE '%_LAB_%'
                     AND a.filename NOT LIKE '%_RAD_%'
                   ORDER BY a.uploaded_at DESC
                   LIMIT 1
               ) AS id_attachment
        FROM visits v
        JOIN patients p ON p.id = v.patient_id
        WHERE 1=1
    """
    params = []

    # Show ED visits only (other clinics are on Clinic Board)
    sql += " AND COALESCE(v.clinic,'ED')='ED'"

    if status_filter and status_filter != "ALL":
        if status_filter.upper() in ("OPEN", "REGISTERED"):
            sql += " AND UPPER(COALESCE(v.status,'')) IN ('OPEN','REGISTERED')"
        else:
            sql += " AND UPPER(COALESCE(v.status,''))=?"
            params.append(status_filter.upper())

    if cat_filter and cat_filter != "ALL":
        sql += " AND UPPER(COALESCE(v.triage_cat,''))=?"
        params.append(cat_filter.upper())

    if visit_f:
        if DB_ENGINE == "postgres":
            sql += " AND v.visit_id ILIKE ?"
        else:
            sql += " AND v.visit_id LIKE ?"
        params.append(f"%{visit_f}%")

    if user_f:
        sql += " AND v.created_by LIKE ?"
        params.append(f"%{user_f}%")

    if q:
        sql, params = _append_patient_search_sql(
            sql, params, q, patient_alias="p", visit_alias="v"
        )

    if dfrom:
        sql += " AND date(v.created_at) >= date(?)"
        params.append(dfrom)
    if dto:
        sql += " AND date(v.created_at) <= date(?)"
        params.append(dto)

    page, per_page, offset = get_page_args(30)
    db = get_db()
    cur = db.cursor()

    base_sql = sql
    base_params = list(params)

    status_counts = {}
    triage_counts = {}
    card_stats = {
        "total": 0,
        "registered": 0,
        "visit_progress": 0,
        "high_acuity": 0,
        "visit_completed": 0,
        "called": 0,
        "cancelled": 0,
    }
    try:
        for row in cur.execute(
            "SELECT status, COUNT(*) AS c FROM (" + base_sql + ") AS s GROUP BY status",
            base_params,
        ).fetchall():
            key = (row["status"] or "UNKNOWN").upper()
            status_counts[key] = row["c"]
        # Merge OPEN + REGISTERED as one workflow group (Registered)
        try:
            _open_c = int(status_counts.get("OPEN", 0) or 0) + int(
                status_counts.get("REGISTERED", 0) or 0
            )
            if _open_c:
                status_counts["REGISTERED"] = _open_c
                status_counts["OPEN"] = _open_c  # alias for backward compatibility
        except Exception:
            pass
        for row in cur.execute(
            "SELECT triage_cat, COUNT(*) AS c FROM ("
            + base_sql
            + ") AS s GROUP BY triage_cat",
            base_params,
        ).fetchall():
            key = row["triage_cat"] or "UNK"
            triage_counts[key] = row["c"]
    except Exception:
        status_counts = {}
        triage_counts = {}

    total = 0
    try:
        # IMPORTANT (PostgreSQL + psycopg2):
        # base_sql contains literal '%' patterns in attachment subqueries.
        # When there are no '?' placeholders, our qmark converter does not run,
        # and psycopg2 may treat '%' literals as formatting tokens, causing COUNT to fail.
        # Add a harmless placeholder pair to force conversion/escaping consistently.
        count_sql = "SELECT COUNT(*) FROM (" + base_sql + " AND (?=?) ) AS t"
        total = cur.execute(count_sql, list(base_params) + [1, 1]).fetchone()[0]
    except Exception:
        total = 0

    pages = (total + per_page - 1) // per_page if per_page else 1
    if pages <= 0:
        pages = 1
    if page > pages:
        page = pages
        offset = (page - 1) * per_page

    sql_page = base_sql + " ORDER BY v.created_at DESC LIMIT ? OFFSET ?"
    params_page = list(base_params) + [per_page, offset]
    rows = cur.execute(sql_page, params_page).fetchall()

    # Safety fallback: if COUNT failed but page rows exist, keep pagination usable.
    if (not total) and rows:
        total = offset + len(rows) + (1 if len(rows) >= per_page else 0)
        pages = max(1, (total + per_page - 1) // per_page)

    visits = []
    for r in rows:
        d = dict(r)
        d["age"] = calc_age(d.get("dob"))
        # Resolve ID/Eligibility attachments robustly (handles legacy/generic filenames too).
        try:
            d.update(
                _resolve_board_attachment_pair(
                    cur,
                    d.get("visit_id"),
                    preset={
                        "id_attachment_id": d.get("id_attachment_id"),
                        "id_attachment": d.get("id_attachment"),
                        "elig_attachment_id": d.get("elig_attachment_id"),
                        "elig_attachment": d.get("elig_attachment"),
                    },
                )
            )
        except Exception:
            pass
        d["assigned_doctor_display"] = _assigned_physician_display(
            cur, d.get("assigned_doctor")
        )
        d["assigned_doctor_label"] = _ensure_dr_prefix(
            d.get("assigned_doctor_display") or d.get("assigned_doctor")
        )

        created_at = d.get("created_at")
        closed_at = d.get("closed_at")
        status_val = (d.get("status") or "").upper()
        if (
            status_val
            in ("DISCHARGED", "TRANSFERRED", "LAMA", "EXPIRED", "CANCELLED", "CLOSED")
            and closed_at
        ):
            mins = calc_minutes_between(created_at, closed_at)
        else:
            mins = calc_minutes_between(
                created_at, datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            )

        if mins is None:
            d["waiting_text"] = "-"
            d["waiting_level"] = "none"
        else:
            try:
                mins_int = int(mins)
            except Exception:
                mins_int = mins
            if isinstance(mins_int, int) and mins_int >= 60:
                h = mins_int // 60
                m = mins_int % 60
                if h >= 24:
                    days = h // 24
                    rem_h = h % 24
                    d["waiting_text"] = f"{days}d {rem_h}h"
                else:
                    d["waiting_text"] = f"{h}h {m:02d}m"
            else:
                d["waiting_text"] = f"{mins_int}m"

            if mins_int is None:
                level = "none"
            elif mins_int < 30:
                level = "short"
            elif mins_int < 90:
                level = "medium"
            else:
                level = "long"
            d["waiting_level"] = level

        try:
            s = get_admission_order_summary(d.get("visit_id"))
            d.update(s)
        except Exception:
            pass

        visits.append(d)

    try:
        card_stats = _compute_ed_board_auto_card_stats(cur)
    except Exception:
        pass

    users = []
    try:
        urows = cur.execute(
            "SELECT DISTINCT created_by AS username FROM visits WHERE created_by IS NOT NULL"
        ).fetchall()
        users = [
            (ur["username"] if hasattr(ur, "__getitem__") else ur[0]) for ur in urows
        ]
    except Exception:
        users = []

    return render_template(
        "ed_board.html",
        visits=visits,
        status_filter=status_filter,
        cat_filter=cat_filter,
        visit_f=visit_f,
        user_f=user_f,
        q=q,
        dfrom=dfrom,
        dto=dto,
        users=users,
        page=page,
        pages=pages,
        per_page=per_page,
        total=total,
        status_counts=status_counts,
        triage_counts=triage_counts,
        card_stats=card_stats,
    )


@login_required
def clinic_board_enterprise():
    """Clinic Board (enterprise override) with admission workflow filters & bulk controls."""
    try:
        ensure_clinic_schema()
    except Exception:
        pass
    try:
        ensure_admission_orders_enterprise_upgrade()
    except Exception:
        pass

    default_clinic = "OPD"
    if (session.get("role") or "").lower() == "inpatient_billing":
        default_clinic = "IPADM"

    clinic_filter = (request.args.get("clinic") or default_clinic).upper()
    status_filter = (request.args.get("status", "ALL") or "ALL").strip().upper()
    ward_filter = request.args.get("ward", "").strip()
    visit_f = request.args.get("visit_id", "").strip()
    user_f = request.args.get("user", "").strip()
    q = (request.args.get("q", "") or "").strip()
    dfrom = request.args.get("date_from", "").strip()
    dto = request.args.get("date_to", "").strip()

    ao_status_filter = (request.args.get("ao_status", "ALL") or "ALL").upper()
    assigned_filter = (request.args.get("assigned", "ALL") or "ALL").strip()

    page, per_page, offset = get_page_args(25)

    db = get_db()
    cur = db.cursor()

    sql = """
        SELECT v.visit_id,
               v.queue_no,
               v.triage_status,
               v.triage_cat,
               v.status,
               COALESCE(v.clinic,'ED') AS clinic,
               v.ward,
               v.bed_no,
               v.admission_type,
               v.approval_no,
               v.assigned_doctor,

               ao.id AS admission_order_id,
               ao.status AS admission_order_status,
               ao.created_at AS admission_order_created_at,
               ao.assigned_to AS admission_order_assigned_to,
               ao.status_note AS admission_order_status_note,
               ao.destination AS admission_destination,
               ao.admit_dr AS admission_admit_dr,
               ao.dx AS admission_dx,
               ao.ref_datetime AS admission_ref_datetime,
               ao.ref_by AS admission_ref_by,
               ao.admission_type AS admission_order_admission_type,

               (SELECT COUNT(*) FROM admission_orders ao2 WHERE ao2.visit_id=v.visit_id) AS admission_orders_count,

               v.payment_details,
               v.created_at,
               v.created_by,
               p.name,
               p.mrn,
               p.id_number,
               (SELECT id FROM attachments
                 WHERE visit_id=v.visit_id
                   AND filename NOT LIKE '%_LAB_%'
                   AND filename NOT LIKE '%_RAD_%'
                 ORDER BY id DESC
                 LIMIT 1) AS id_attachment_id,
               (SELECT filename FROM attachments
                 WHERE visit_id=v.visit_id
                   AND filename NOT LIKE '%_LAB_%'
                   AND filename NOT LIKE '%_RAD_%'
                 ORDER BY id DESC
                 LIMIT 1) AS id_attachment,
               p.insurance,
               p.dob AS dob
        FROM visits v
        JOIN patients p ON p.id = v.patient_id
        LEFT JOIN admission_orders ao
               ON ao.id = (
                    SELECT id
                    FROM admission_orders
                    WHERE visit_id = v.visit_id
                    ORDER BY
                      CASE WHEN UPPER(COALESCE(status,'')) IN ({active}) THEN 0 ELSE 1 END,
                      id DESC
                    LIMIT 1
               )
        WHERE 1=1
    """.format(active=",".join(["?"] * len(AO_ACTIVE_STATUSES)))
    params = list(AO_ACTIVE_STATUSES)

    if clinic_filter == "IPADM":
        sql += " AND (UPPER(COALESCE(v.clinic,'ED'))='IPADM' OR (SELECT COUNT(*) FROM admission_orders ao3 WHERE ao3.visit_id=v.visit_id) > 0)"
    elif clinic_filter and clinic_filter != "ALL":
        sql += " AND UPPER(COALESCE(v.clinic,'ED'))=?"
        params.append(clinic_filter)

    if status_filter and status_filter != "ALL":
        if status_filter.upper() in ("OPEN", "REGISTERED"):
            sql += " AND UPPER(COALESCE(v.status,'')) IN ('OPEN','REGISTERED')"
        else:
            sql += " AND UPPER(COALESCE(v.status,''))=?"
            params.append(status_filter.upper())

    if ward_filter:
        sql += " AND COALESCE(v.ward,'') LIKE ?"
        params.append(f"%{ward_filter}%")

    if visit_f:
        if DB_ENGINE == "postgres":
            sql += " AND v.visit_id ILIKE ?"
        else:
            sql += " AND v.visit_id LIKE ?"
        params.append(f"%{visit_f}%")

    if user_f:
        sql += " AND COALESCE(v.created_by,'') LIKE ?"
        params.append(f"%{user_f}%")

    if q:
        sql, params = _append_patient_search_sql(
            sql, params, q, patient_alias="p", visit_alias="v"
        )

    if dfrom:
        sql += " AND date(v.created_at) >= date(?)"
        params.append(dfrom)
    if dto:
        sql += " AND date(v.created_at) <= date(?)"
        params.append(dto)

    if clinic_filter == "IPADM":
        if ao_status_filter and ao_status_filter != "ALL":
            sql += " AND UPPER(COALESCE(ao.status,''))=?"
            params.append(ao_status_filter)
        if assigned_filter == "UNASSIGNED":
            sql += " AND (ao.assigned_to IS NULL OR TRIM(ao.assigned_to)='')"
        elif assigned_filter and assigned_filter != "ALL":
            sql += " AND COALESCE(ao.assigned_to,'')=?"
            params.append(assigned_filter)

    total = 0
    try:
        total = cur.execute(
            "SELECT COUNT(*) FROM (" + sql + ") AS t", params
        ).fetchone()[0]
    except Exception:
        total = 0

    sql_page = sql + " ORDER BY v.created_at DESC LIMIT ? OFFSET ?"
    params_page = list(params) + [per_page, offset]
    rows = cur.execute(sql_page, params_page).fetchall()

    visits = []
    for r in rows:
        d = dict(r)
        d["age"] = calc_age(d.get("dob"))
        # Resolve ID/Eligibility attachments robustly (same behavior as ED board).
        try:
            d.update(
                _resolve_board_attachment_pair(
                    cur,
                    d.get("visit_id"),
                    preset={
                        "id_attachment_id": d.get("id_attachment_id"),
                        "id_attachment": d.get("id_attachment"),
                        "elig_attachment_id": d.get("elig_attachment_id"),
                        "elig_attachment": d.get("elig_attachment"),
                    },
                )
            )
        except Exception:
            pass
        d["assigned_doctor_display"] = _assigned_physician_display(
            cur, d.get("assigned_doctor")
        )
        d["assigned_doctor_label"] = _ensure_dr_prefix(
            d.get("assigned_doctor_display") or d.get("assigned_doctor")
        )
        try:
            ao_created = d.get("admission_order_created_at")
            if ao_created:
                age = calc_minutes_between(
                    ao_created, now_display_str("%Y-%m-%d %H:%M")
                )
                try:
                    d["admission_order_age_min"] = int(age) if age is not None else None
                except Exception:
                    d["admission_order_age_min"] = age
                d["adm_badge_class"] = ao_badge_class(d.get("admission_order_status"))
                d["adm_sla_badge_class"] = ao_sla_badge_class(
                    d.get("admission_order_age_min")
                )
            else:
                d["admission_order_age_min"] = None
                d["adm_badge_class"] = ""
                d["adm_sla_badge_class"] = ""
        except Exception:
            pass
        visits.append(d)

    wards = []
    if clinic_filter == "IPADM":
        try:
            wrows = cur.execute("""
                SELECT DISTINCT ward
                FROM visits
                WHERE ward IS NOT NULL AND TRIM(ward) <> ''
                ORDER BY ward
                """).fetchall()
            wards = [
                (wr["ward"] if hasattr(wr, "__getitem__") else wr[0]) for wr in wrows
            ]
        except Exception:
            wards = []

    users = []
    try:
        urows = cur.execute(
            "SELECT DISTINCT created_by AS username FROM visits WHERE created_by IS NOT NULL"
        ).fetchall()
        users = [
            (ur["username"] if hasattr(ur, "__getitem__") else ur[0]) for ur in urows
        ]
    except Exception:
        users = []

    assignees = []
    try:
        arows = cur.execute(
            "SELECT username FROM users WHERE role IN ('inpatient_billing','admin') ORDER BY username"
        ).fetchall()
        assignees = [
            (ar["username"] if hasattr(ar, "__getitem__") else ar[0]) for ar in arows
        ]
    except Exception:
        assignees = []

    pages = max(1, (total + per_page - 1) // per_page)
    bulk_enabled = (session.get("role") in ["admin", "inpatient_billing"]) and (
        clinic_filter == "IPADM"
    )

    return render_template(
        "clinic_board.html",
        visits=visits,
        clinic_filter=clinic_filter,
        status_filter=status_filter,
        ward_filter=ward_filter,
        wards=wards,
        visit_f=visit_f,
        user_f=user_f,
        q=q,
        dfrom=dfrom,
        dto=dto,
        users=users,
        clinics=get_clinics_for_ui(),
        page=page,
        pages=pages,
        per_page=per_page,
        total=total,
        ao_status_filter=ao_status_filter,
        assigned_filter=assigned_filter,
        ao_statuses=AO_ALL_STATUSES,
        assignees=assignees,
        bulk_enabled=bulk_enabled,
    )


@app.route("/ip_admission_form/<visit_id>", methods=["GET", "POST"], endpoint="ip_admission_form")
@login_required
def ip_admission_form_enterprise(visit_id):
    """Enterprise Admission Form: assignment + stage + audit trail."""
    try:
        ensure_clinic_schema()
    except Exception:
        pass
    try:
        ensure_admission_orders_enterprise_upgrade()
    except Exception:
        pass

    cur = get_db().cursor()
    row = cur.execute(
        """
        SELECT v.*, p.name, p.id_number, p.insurance, p.insurance_no, p.dob AS dob
        FROM visits v
        JOIN patients p ON p.id = v.patient_id
        WHERE v.visit_id=?
        """,
        (visit_id,),
    ).fetchone()
    if not row:
        flash("Visit not found.", "danger")
        return redirect(url_for("clinic_board", clinic="IPADM"))

    try:
        v = dict(row)
    except Exception:
        v = {k: row[k] for k in row.keys()}
    v["age"] = calc_age(v.get("dob"))

    orders = []
    try:
        orders = cur.execute(
            "SELECT * FROM admission_orders WHERE visit_id=? ORDER BY id DESC",
            (visit_id,),
        ).fetchall()
        orders = [dict(o) if not isinstance(o, dict) else o for o in orders]
    except Exception:
        orders = []

    preferred = get_preferred_admission_order_for_visit(visit_id)
    has_order = True if preferred else False

    if preferred:
        v["admission_ref_datetime"] = preferred.get("ref_datetime", "")
        v["admission_ref_by"] = preferred.get("ref_by", "")
        v["admission_admit_dr"] = preferred.get("admit_dr", "")
        v["admission_dx"] = preferred.get("dx", "")
        v["admission_destination"] = preferred.get("destination", "")
        v["admission_type"] = preferred.get("admission_type") or v.get("admission_type")
        v["admission_order_status"] = preferred.get("status", "")
        v["ward"] = preferred.get("ward") or v.get("ward")
        v["bed_no"] = preferred.get("bed_no") or v.get("bed_no")
        v["approval_no"] = preferred.get("approval_no") or v.get("approval_no")

    can_edit = session.get("role") in ["admin", "inpatient_billing"]
    open_edit_modal = (request.args.get("edit") or "").strip() == "1"

    assignees = []
    try:
        arows = cur.execute(
            "SELECT username FROM users WHERE role IN ('inpatient_billing','admin') ORDER BY username"
        ).fetchall()
        assignees = [
            (ar["username"] if hasattr(ar, "__getitem__") else ar[0]) for ar in arows
        ]
    except Exception:
        assignees = []

    active_order_status = _ao_status_upper(preferred.get("status") if preferred else "")
    active_order_assigned_to = (preferred.get("assigned_to") if preferred else "") or ""
    active_order_created_at = preferred.get("created_at") if preferred else ""
    active_order_age_min = None
    if active_order_created_at:
        active_order_age_min = calc_minutes_between(
            active_order_created_at, now_display_str("%Y-%m-%d %H:%M")
        )
        try:
            active_order_age_min = (
                int(active_order_age_min) if active_order_age_min is not None else None
            )
        except Exception:
            pass

    if request.method == "POST":
        if not can_edit:
            flash("You do not have permission to update this admission form.", "danger")
            return redirect(url_for("ip_admission_form", visit_id=visit_id))

        action = (request.form.get("action") or "update_processing").strip()
        db = get_db()
        now_ts = now_display_str("%Y-%m-%d %H:%M")
        actor = session.get("username", "")

        if not preferred:
            flash("No Admission Order found for this visit.", "warning")
            return redirect(url_for("ip_admission_form", visit_id=visit_id))

        oid = preferred.get("id")

        terminal = _ao_status_upper(preferred.get("status")) in AO_TERMINAL_STATUSES
        override_reason = (request.form.get("override_reason") or "").strip()

        if terminal and session.get("role") != "admin":
            flash(
                "Admission Order is locked after finalization (ADMITTED/CANCELLED/REPLACED). Admin override only.",
                "warning",
            )
            return redirect(url_for("ip_admission_form", visit_id=visit_id))

        if (
            terminal
            and session.get("role") == "admin"
            and action == "update_processing"
            and not override_reason
        ):
            flash(
                "Override reason is required for editing finalized Admission Orders.",
                "warning",
            )
            return redirect(
                url_for("ip_admission_form", visit_id=visit_id, edit="1")
            )

        if action == "update_processing":
            ward = (request.form.get("ward") or "").strip()
            bed_no = (request.form.get("bed_no") or "").strip()
            admission_type = (request.form.get("admission_type") or "").strip()
            approval_no = (request.form.get("approval_no") or "").strip()
            ip_payment_details = (request.form.get("ip_payment_details") or "").strip()
            insurance = (request.form.get("insurance") or "").strip()
            insurance_no = (request.form.get("insurance_no") or "").strip()

            before = preferred
            update_errors = []

            try:
                db.execute(
                    """
                    UPDATE admission_orders
                       SET ward=?,
                           bed_no=?,
                           approval_no=?,
                           admission_type=CASE WHEN ? IS NULL OR TRIM(?)='' THEN admission_type ELSE ? END,
                           updated_at=?,
                           updated_by=?
                     WHERE id=?
                    """,
                    (
                        ward,
                        bed_no,
                        approval_no,
                        admission_type,
                        admission_type,
                        admission_type,
                        now_ts,
                        actor,
                        oid,
                    ),
                )
            except Exception as e:
                update_errors.append("admission_orders")
                _log_critical_exception(
                    f"IP update_processing failed for admission_orders visit={visit_id} oid={oid}",
                    e,
                )

            try:
                db.execute(
                    """
                    UPDATE visits
                       SET ward=?,
                           bed_no=?,
                           admission_type=?,
                           approval_no=?,
                           ip_payment_details=?
                     WHERE visit_id=?
                    """,
                    (
                        ward,
                        bed_no,
                        admission_type,
                        approval_no,
                        ip_payment_details,
                        visit_id,
                    ),
                )
            except Exception as e:
                update_errors.append("visits")
                _log_critical_exception(
                    f"IP update_processing failed for visits snapshot visit={visit_id} oid={oid}",
                    e,
                )

            # Update patient insurance fields (stored in patients table)
            try:
                pid = v.get("patient_id")
            except Exception:
                pid = None
            if pid:
                try:
                    db.execute(
                        """
                        UPDATE patients
                           SET insurance=?,
                               insurance_no=?
                         WHERE id=?
                        """,
                        (insurance, insurance_no, pid),
                    )
                except Exception as e:
                    update_errors.append("patients")
                    _log_noncritical_exception(
                        f"IP update_processing failed for patient insurance visit={visit_id} patient_id={pid}",
                        e,
                    )

            try:
                db.execute(
                    "UPDATE visits SET admission_order_status=? WHERE visit_id=?",
                    (_ao_status_upper(before.get("status")), visit_id),
                )
            except Exception as e:
                update_errors.append("visit_status")
                _log_noncritical_exception(
                    f"IP update_processing failed to refresh admission_order_status visit={visit_id}",
                    e,
                )

            if update_errors:
                try:
                    db.rollback()
                except Exception as rb_exc:
                    _log_noncritical_exception(
                        f"IP update_processing rollback failed for visit={visit_id} oid={oid}",
                        rb_exc,
                    )
                flash(
                    "Failed to save one or more admission processing fields. No partial updates were applied.",
                    "danger",
                )
                return redirect(url_for("ip_admission_form", visit_id=visit_id))

            try:
                db.commit()
            except Exception as e:
                _log_critical_exception(
                    f"IP update_processing commit failed for visit={visit_id} oid={oid}",
                    e,
                )
                try:
                    db.rollback()
                except Exception as rb_exc:
                    _log_noncritical_exception(
                        f"IP update_processing rollback after commit failure failed visit={visit_id} oid={oid}",
                        rb_exc,
                    )
                flash(
                    "Admission processing update could not be committed. Please retry.",
                    "danger",
                )
                return redirect(url_for("ip_admission_form", visit_id=visit_id))

            for field, new_val, old_val in [
                ("ward", ward, before.get("ward", "")),
                ("bed_no", bed_no, before.get("bed_no", "")),
                ("approval_no", approval_no, before.get("approval_no", "")),
                ("admission_type", admission_type, before.get("admission_type", "")),
            ]:
                if (old_val or "") != (new_val or ""):
                    ao_audit(
                        oid,
                        visit_id,
                        "FIELD_CHANGE",
                        field_name=field,
                        old_value=old_val,
                        new_value=new_val,
                        note=(
                            ("Override: " + override_reason) if override_reason else ""
                        ),
                        actor=actor,
                    )

            # Also log processing fields stored on the visit/patient
            for field, new_val, old_val in [
                (
                    "ip_payment_details",
                    ip_payment_details,
                    v.get("ip_payment_details", ""),
                ),
                ("insurance", insurance, v.get("insurance", "")),
                ("insurance_no", insurance_no, v.get("insurance_no", "")),
            ]:
                if (old_val or "") != (new_val or ""):
                    ao_audit(
                        oid,
                        visit_id,
                        "FIELD_CHANGE",
                        field_name=field,
                        old_value=old_val,
                        new_value=new_val,
                        note=(
                            ("Override: " + override_reason) if override_reason else ""
                        ),
                        actor=actor,
                    )

            if override_reason:
                ao_audit(
                    oid,
                    visit_id,
                    "OVERRIDE_EDIT",
                    field_name="",
                    old_value="",
                    new_value="",
                    note=override_reason,
                    actor=actor,
                )

            log_action(
                "IP_UPDATE_FIELDS",
                visit_id=visit_id,
                details=f"Ward={ward}|Room={bed_no}|Type={admission_type}|Appr={approval_no}",
            )
            flash("IP admission processing updated.", "success")
            return redirect(url_for("ip_admission_form", visit_id=visit_id))

        if action == "assign":
            assign_to = (request.form.get("assign_to") or "").strip()
            old_assignee = preferred.get("assigned_to") or ""
            try:
                if assign_to:
                    db.execute(
                        """
                        UPDATE admission_orders
                           SET assigned_to=?,
                               assigned_at=?,
                               assigned_by=?,
                               updated_at=?,
                               updated_by=?
                         WHERE id=?
                        """,
                        (assign_to, now_ts, actor, now_ts, actor, oid),
                    )
                    ao_audit(
                        oid,
                        visit_id,
                        "ASSIGN",
                        field_name="assigned_to",
                        old_value=old_assignee,
                        new_value=assign_to,
                        note="",
                        actor=actor,
                    )
                else:
                    db.execute(
                        """
                        UPDATE admission_orders
                           SET assigned_to=NULL,
                               assigned_at=?,
                               assigned_by=?,
                               updated_at=?,
                               updated_by=?
                         WHERE id=?
                        """,
                        (now_ts, actor, now_ts, actor, oid),
                    )
                    ao_audit(
                        oid,
                        visit_id,
                        "UNASSIGN",
                        field_name="assigned_to",
                        old_value=old_assignee,
                        new_value="",
                        note="",
                        actor=actor,
                    )
                db.commit()
                flash("Assignment updated.", "success")
            except Exception as e:
                try:
                    db.rollback()
                except Exception:
                    pass
                flash(f"Failed to update assignment: {e}", "danger")
            return redirect(url_for("ip_admission_form", visit_id=visit_id))

        if action == "set_stage":
            new_status = (request.form.get("new_status") or "").strip().upper()
            status_note = (request.form.get("status_note") or "").strip()
            old_status = preferred.get("status") or ""
            if new_status not in AO_STAGE_OPTIONS:
                flash("Invalid stage.", "warning")
                return redirect(
                    url_for("ip_admission_form", visit_id=visit_id)
                )
            try:
                db.execute(
                    """
                    UPDATE admission_orders
                       SET status=?,
                           status_note=?,
                           stage_updated_at=?,
                           stage_updated_by=?,
                           updated_at=?,
                           updated_by=?
                     WHERE id=?
                    """,
                    (new_status, status_note, now_ts, actor, now_ts, actor, oid),
                )
                db.commit()
                _update_visit_admission_order_status_snapshot(visit_id, new_status)
                ao_audit(
                    oid,
                    visit_id,
                    "STAGE_CHANGE",
                    field_name="status",
                    old_value=old_status,
                    new_value=new_status,
                    note=status_note,
                    actor=actor,
                )
                flash("Admission stage updated.", "success")
            except Exception as e:
                try:
                    db.rollback()
                except Exception:
                    pass
                flash(f"Failed to update stage: {e}", "danger")
            return redirect(url_for("ip_admission_form", visit_id=visit_id))

        flash("Unknown action.", "warning")
        return redirect(url_for("ip_admission_form", visit_id=visit_id))

    audit_rows = []
    if preferred:
        try:
            ensure_admission_audit_schema()
        except Exception:
            pass
        try:
            audit_rows = cur.execute(
                """
                SELECT *
                FROM admission_order_audit
                WHERE order_id=?
                ORDER BY id DESC
                LIMIT 50
                """,
                (preferred.get("id"),),
            ).fetchall()
            audit_rows = [dict(a) if not isinstance(a, dict) else a for a in audit_rows]
        except Exception:
            audit_rows = []

    return render_template(
        "ip_admission_form.html",
        v=v,
        has_order=has_order,
        can_edit=can_edit,
        active_order_status=active_order_status,
        active_order_assigned_to=active_order_assigned_to,
        active_order_age_min=active_order_age_min,
        active_order_badge_class=ao_badge_class(active_order_status),
        active_order_sla_class=ao_sla_badge_class(active_order_age_min),
        stage_options=AO_STAGE_OPTIONS,
        assignees=assignees,
        audit_rows=audit_rows,
        open_edit_modal=open_edit_modal,
        is_ipadm=((v.get("clinic") or "").upper() == "IPADM"),
        orders=orders,
    )


# ------------------------------------------------------------
# Doctor Admission Order (override) with enterprise statuses + audit
# ------------------------------------------------------------
@app.route("/patient/<visit_id>/admission_order", methods=["POST"], endpoint="create_admission_order")
@login_required
@role_required("admin", "doctor", "inpatient_billing")
def create_admission_order_enterprise(visit_id):
    try:
        ensure_clinic_schema()
    except Exception:
        pass
    try:
        ensure_admission_orders_enterprise_upgrade()
    except Exception:
        pass

    ref_dt = (request.form.get("admission_ref_datetime") or "").strip()
    ref_by = (request.form.get("admission_ref_by") or "").strip()
    admit_dr = (request.form.get("admission_admit_dr") or "").strip()
    dest = (request.form.get("admission_destination") or "").strip().upper()
    adm_type = (request.form.get("admission_type") or "").strip()
    patient_type = (request.form.get("admission_patient_type") or "").strip()
    medical_service = (request.form.get("admission_medical_service") or "").strip()
    accommodation = (request.form.get("admission_accommodation") or "").strip()
    facility = (request.form.get("admission_facility") or "").strip()
    future_adm = (request.form.get("admission_future_admission") or "").strip()
    isolation = (request.form.get("admission_isolation") or "").strip()
    auth_status = (request.form.get("admission_authorization_status") or "").strip()
    approval_instr = (request.form.get("admission_approval_instructions") or "").strip()
    order_comments = (request.form.get("admission_order_comments") or "").strip()
    dx = (request.form.get("admission_dx") or "").strip()

    if ref_dt and "T" in ref_dt:
        ref_dt = ref_dt.replace("T", " ").strip()
    if not ref_dt:
        ref_dt = now_display_str("%Y-%m-%d %H:%M")

    actor = session.get("username", "") or ref_by or "doctor"
    now_ts = now_display_str("%Y-%m-%d %H:%M")

    if not dest:
        flash("Destination is required.", "warning")
        return redirect(url_for("patient_details", visit_id=visit_id))
    if not admit_dr:
        flash("Attending Physician (Admit Under) is required.", "warning")
        return redirect(url_for("patient_details", visit_id=visit_id))

    db = get_db()
    cur = db.cursor()

    prev = None
    try:
        q = """
            SELECT id, status
            FROM admission_orders
            WHERE visit_id=?
              AND UPPER(COALESCE(status,'')) IN ({active})
            ORDER BY id DESC
            LIMIT 1
        """.format(active=",".join(["?"] * len(AO_ACTIVE_STATUSES)))
        prev = cur.execute(q, [visit_id] + AO_ACTIVE_STATUSES).fetchone()
    except Exception:
        prev = None

    if prev:
        try:
            prev_id = prev["id"]
            prev_status = prev["status"]
        except Exception:
            prev_id = prev[0]
            prev_status = prev[1] if len(prev) > 1 else ""
        try:
            db.execute(
                """
                UPDATE admission_orders
                   SET status='REPLACED',
                       updated_at=?,
                       updated_by=?,
                       stage_updated_at=?,
                       stage_updated_by=?
                 WHERE id=?
                """,
                (now_ts, actor, now_ts, actor, prev_id),
            )
            ao_audit(
                prev_id,
                visit_id,
                "REPLACED",
                field_name="status",
                old_value=prev_status,
                new_value="REPLACED",
                note="Superseded by new Admission Order",
                actor=actor,
            )
        except Exception:
            pass

    cur2 = db.execute(
        """
        INSERT INTO admission_orders
        (visit_id, ref_datetime, ref_by, admit_dr, dx, destination, admission_type,
         patient_type, medical_service, accommodation, facility, future_admission, isolation,
         authorization_status, approval_instructions, order_comments,
         status, status_note, stage_updated_at, stage_updated_by,
         created_at, created_by, updated_at, updated_by)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """,
        (
            visit_id,
            ref_dt,
            ref_by or actor,
            admit_dr,
            dx,
            dest,
            adm_type,
            patient_type,
            medical_service,
            accommodation,
            facility,
            future_adm,
            isolation,
            auth_status,
            approval_instr,
            order_comments,
            "ORDERED",
            "",
            now_ts,
            actor,
            now_ts,
            actor,
            now_ts,
            actor,
        ),
    )

    new_id = None
    try:
        new_id = cur2.lastrowid
    except Exception:
        new_id = None
    if not new_id:
        try:
            rr = db.execute(
                "SELECT id FROM admission_orders WHERE visit_id=? ORDER BY id DESC LIMIT 1",
                (visit_id,),
            ).fetchone()
            new_id = rr["id"] if hasattr(rr, "__getitem__") else rr[0]
        except Exception:
            new_id = None

    if new_id:
        ao_audit(
            new_id,
            visit_id,
            "CREATE_ORDER",
            field_name="",
            old_value="",
            new_value="",
            note="Admission Order created",
            actor=actor,
        )

    try:
        db.execute(
            """
            UPDATE visits
               SET admission_ref_datetime=?,
                   admission_ref_by=?,
                   admission_admit_dr=?,
                   admission_dx=?,
                   admission_destination=?,
                   admission_type=?,
                   admission_patient_type=?,
                   admission_medical_service=?,
                   admission_accommodation=?,
                   admission_facility=?,
                   admission_future_admission=?,
                   admission_isolation=?,
                   admission_authorization_status=?,
                   admission_approval_instructions=?,
                   admission_order_comments=?,
                   admission_order_status='ORDERED'
             WHERE visit_id=?
            """,
            (
                ref_dt,
                ref_by or actor,
                admit_dr,
                dx,
                dest,
                adm_type,
                patient_type,
                medical_service,
                accommodation,
                facility,
                future_adm,
                isolation,
                auth_status,
                approval_instr,
                order_comments,
                visit_id,
            ),
        )
    except Exception:
        pass

    try:
        db.commit()
    except Exception:
        pass

    log_action(
        "ADMISSION_ORDER",
        visit_id=visit_id,
        details=f"dest={dest}|under={admit_dr}|type={adm_type}",
    )
    flash("Admission Order sent to IP Admission board.", "success")
    return redirect(url_for("patient_details", visit_id=visit_id))


