@app.route("/ip_admit/<visit_id>", methods=["POST"])
@login_required
@role_required("admin", "inpatient_billing")
def ip_admit_enterprise(visit_id):
    try:
        ensure_clinic_schema()
    except Exception:
        pass
    try:
        ensure_admission_orders_enterprise_upgrade()
    except Exception:
        pass

    clinic = (request.form.get("clinic") or "IPADM").upper()
    actor = session.get("username", "")
    now_ts = now_display_str("%Y-%m-%d %H:%M")

    db = get_db()
    cur = db.cursor()

    # pick latest ACTIVE order (any active stage)
    order = None
    try:
        q = """
            SELECT *
            FROM admission_orders
            WHERE visit_id=?
              AND UPPER(COALESCE(status,'')) IN ({active})
            ORDER BY id DESC
            LIMIT 1
        """.format(active=",".join(["?"] * len(AO_ACTIVE_STATUSES)))
        order = cur.execute(q, [visit_id] + AO_ACTIVE_STATUSES).fetchone()
    except Exception:
        order = None

    if not order:
        flash("No active Admission Order to admit.", "warning")
        return redirect(url_for("ip_admission_form", visit_id=visit_id))

    try:
        o = dict(order)
    except Exception:
        o = {k: order[k] for k in order.keys()}

    oid = o.get("id")
    old_status = o.get("status") or ""

    try:
        db.execute(
            """
            UPDATE admission_orders
               SET status='ADMITTED',
                   admitted_at=?,
                   admitted_by=?,
                   stage_updated_at=?,
                   stage_updated_by=?,
                   updated_at=?,
                   updated_by=?
             WHERE id=?
            """,
            (now_ts, actor, now_ts, actor, now_ts, actor, oid),
        )
        try:
            db.execute(
                "UPDATE visits SET admission_order_status='ADMITTED' WHERE visit_id=?",
                (visit_id,),
            )
        except Exception:
            pass
        db.commit()
    except Exception as e:
        try:
            db.rollback()
        except Exception:
            pass
        flash(f"Failed to admit: {e}", "danger")
        return redirect(url_for("ip_admission_form", visit_id=visit_id))

    ao_audit(
        oid,
        visit_id,
        "ADMIT",
        field_name="status",
        old_value=old_status,
        new_value="ADMITTED",
        note="",
        actor=actor,
    )
    log_action("IP_ADMIT", visit_id=visit_id)
    flash("Admission marked as ADMITTED.", "success")
    return redirect(url_for("clinic_board", clinic=clinic))


