@app.route("/admin/user_permissions", methods=["GET", "POST"])
@login_required
@role_required("admin")
def admin_user_permissions():
    """Admin UI to manage per-role permissions."""
    try:
        init_role_permissions_table()
        seed_role_permissions_defaults()
        migrate_role_permissions_add_new_keys()
    except Exception:
        pass

    db = get_db()
    cur = db.cursor()

    # Roles to show in dropdown: from users + a few common ones
    roles = set(
        [
            "admin",
            "doctor",
            "call_center_agent",
            "clinic_manager",
            "nurse",
            "nurse_supervisor",
            "lab",
            "pharmacist",
            "radiology",
            "reception",
            "inpatient_billing",
            "mrd",
        ]
    )
    try:
        rows = cur.execute("SELECT DISTINCT role FROM users ORDER BY role").fetchall()
        for r in rows or []:
            rv = None
            try:
                rv = r["role"]
            except Exception:
                try:
                    rv = r[0]
                except Exception:
                    rv = None
            if rv:
                roles.add(str(rv))
    except Exception:
        pass

    # Include roles that were created from Manage Roles but are not yet assigned
    # to any user. Manage Roles stores those roles in role_permissions, so the
    # User Permissions dropdown must read the same source to stay in sync.
    try:
        rows = cur.execute("SELECT role FROM role_permissions WHERE COALESCE(role,'')<>'' ORDER BY role").fetchall()
        for r in rows or []:
            rv = None
            try:
                rv = r["role"]
            except Exception:
                try:
                    rv = r[0]
                except Exception:
                    rv = None
            if rv:
                roles.add(str(rv).strip())
    except Exception:
        pass

    roles = sorted([r for r in roles if r], key=lambda r: role_display(r).lower())

    selected_role = (
        request.args.get("role") or request.form.get("role") or "admin"
    ).strip()
    if selected_role not in roles and roles:
        selected_role = roles[0]

    if request.method == "POST":
        perms = request.form.getlist("perms")
        perms_set = {p for p in perms if p in ALL_PERMISSION_KEYS}

        # Safety: keep admin panel access
        if selected_role.lower() == "admin":
            perms_set |= {"admin_control_panel", "admin_user_permissions"}

        ok = save_role_permissions(
            selected_role, perms_set, actor=session.get("username", "")
        )

        if ok:
            try:
                log_action(
                    "UPDATE_ROLE_PERMISSIONS",
                    details=f"role={selected_role}|count={len(perms_set)}",
                )
            except Exception:
                pass
            flash("Permissions saved.", "success")
        else:
            flash("Failed to save permissions.", "danger")

        return redirect(url_for("admin_user_permissions", role=selected_role))

    role_perms = get_role_permissions(selected_role)

    return render_template(
        "admin_user_permissions.html",
        roles=roles,
        selected_role=selected_role,
        role_perms=role_perms,
        core_perms=PERMISSION_GROUPS.get("core", []),
        board_perms=PERMISSION_GROUPS.get("boards", []),
        admin_perms=PERMISSION_GROUPS.get("admin", []),
    )


# ------------------------------------------------------------
# Admin Control Panel + Tools Center (v19)
# ------------------------------------------------------------
import zipfile
import shlex
from pathlib import Path


def _looks_like_project_root(d: str) -> bool:
    """Return True when directory looks like the *deployment root*.

    We intentionally require *strong* markers (SQL / launcher files) to avoid
    accidentally treating a code subfolder as the root. This prevents missing
    tool files such as indexes_postgres.sql during EXE/service runs.
    """
    try:
        if not d:
            return False
        strong_markers = [
            "schema_postgres.sql",
            "indexes_postgres.sql",
            "Run_ED_Downtime.bat",
            "Run_ED_Downtime_With_Nginx_Domain.bat",
            "ED_Downtime_Server.spec",
        ]
        return any(os.path.exists(os.path.join(d, m)) for m in strong_markers)
    except Exception:
        return False


def _project_root_score(d: str) -> int:
    """Score directory candidates for deployment root detection."""
    try:
        if not d:
            return -1

        strong = [
            "schema_postgres.sql",
            "indexes_postgres.sql",
            "Run_ED_Downtime.bat",
            "Run_ED_Downtime_With_Nginx_Domain.bat",
        ]
        medium = [
            "requirements.txt",
            "ED_Downtime_Server.spec",
            "ED_Service_Launcher.ps1",
            "README_AR.md",
        ]
        weak = [
            "appy_pg_latest.py",
            "run_waitress.py",
            "config.py",
            "db.py",
        ]

        score = 0
        for m in strong:
            if os.path.exists(os.path.join(d, m)):
                score += 5
        for m in medium:
            if os.path.exists(os.path.join(d, m)):
                score += 2
        for m in weak:
            if os.path.exists(os.path.join(d, m)):
                score += 1
        return score
    except Exception:
        return -1


def _app_root_dir() -> str:
    """Return best guess of deployment root folder (works for .py and frozen EXE).

    We walk up a few parent directories and pick the one with the best marker score.
    """
    # Candidate base
    try:
        if getattr(sys, "frozen", False):
            base = os.path.dirname(sys.executable)
        else:
            base = os.path.dirname(os.path.abspath(__file__))
    except Exception:
        try:
            base = os.getcwd()
        except Exception:
            base = os.path.abspath(".")

    best = base
    best_score = _project_root_score(base)

    try:
        d = base
        for _ in range(7):
            s = _project_root_score(d)
            if s > best_score:
                best, best_score = d, s
            if _looks_like_project_root(d):
                best, best_score = d, max(best_score, s)
                break
            parent = os.path.dirname(d) if d else None
            if not parent or parent == d:
                break
            d = parent
    except Exception:
        pass

    return best


def _mask_pg_dsn(dsn: str) -> str:
    """Mask password inside a PostgreSQL DSN for safe display."""
    if not dsn:
        return ""
    try:
        parts = {}
        for tok in shlex.split(dsn):
            if "=" in tok:
                k, v = tok.split("=", 1)
                parts[k.strip()] = v.strip()
        if "password" in parts:
            parts["password"] = "********"
        order = ["dbname", "user", "host", "port", "password"]
        out = []
        for k in order:
            if k in parts:
                out.append(f"{k}={parts[k]}")
        for k in sorted([k for k in parts.keys() if k not in order]):
            out.append(f"{k}={parts[k]}")
        return " ".join(out)
    except Exception:
        return dsn.replace("password=", "password=********")


def _dir_health(path: str):
    """Return (exists, writable) for a directory."""
    try:
        if not path:
            return False, False
        os.makedirs(path, exist_ok=True)
        test_file = os.path.join(path, f"__write_test_{int(time.time())}.tmp")
        with open(test_file, "w", encoding="utf-8") as f:
            f.write("ok")
        try:
            os.remove(test_file)
        except Exception:
            pass
        return True, True
    except Exception:
        try:
            return os.path.isdir(path), False
        except Exception:
            return False, False


def _stat_file(path: str):
    try:
        st = os.stat(path)
        return {
            "exists": True,
            "size_kb": round(st.st_size / 1024.0, 1),
            "mtime": datetime.fromtimestamp(st.st_mtime).strftime("%Y-%m-%d %H:%M:%S"),
        }
    except Exception:
        return {"exists": False, "size_kb": None, "mtime": None}


