def _tools_root():
    """Return folder that contains admin tools (SQL/bat/spec/ps1 files).

    Some deployments keep the application code in a subfolder, while tools live
    at the deployment root. Also, some environments may set TOOLS_ROOT to an
    incorrect/empty folder. We therefore evaluate multiple candidates and pick
    the one that contains the most known tool files.
    """
    configured = (
        APP_CONFIG.get("TOOLS_ROOT") or os.environ.get("TOOLS_ROOT") or ""
    ).strip()

    # Candidate roots (order does not matter; we will score them)
    app_root = _app_root_dir()
    candidates = []
    if configured:
        candidates.append(configured)
        candidates.append(os.path.join(configured, "tools"))
        # sometimes TOOLS_ROOT mistakenly points to a file; still try its dir
        try:
            if os.path.isfile(configured):
                candidates.append(os.path.dirname(configured))
        except Exception:
            pass

    candidates.extend(
        [
            app_root,
            os.path.join(app_root, "tools"),
            os.path.dirname(app_root),
        ]
    )

    manifest = _tools_manifest()

    def _score(d: str) -> int:
        try:
            if not d:
                return -1
            score = 0
            for _, fname, _, _ in manifest:
                if os.path.exists(os.path.join(d, fname)):
                    score += 1
            return score
        except Exception:
            return -1

    best = app_root
    best_score = _score(app_root)

    for c in candidates:
        s = _score(c)
        if s > best_score:
            best, best_score = c, s

    return best


def inject_system_context():
    return dict(db_engine=DB_ENGINE)


@app.route("/admin/panel")
@login_required
@role_required("admin")
def admin_panel():
    db = get_db()
    cur = db.cursor()

    db_ok = True
    db_message = "OK"
    try:
        cur.execute("SELECT 1 AS ok").fetchone()
    except Exception as e:
        db_ok = False
        db_message = str(e)

    users_total = _safe_count(cur, "SELECT COUNT(*) AS c FROM users")
    users_enabled = (
        _safe_count(cur, "SELECT COUNT(*) AS c FROM users WHERE is_active=1")
        if users_total
        else 0
    )
    # Online users (recent activity heartbeat)
    users_online = get_users_online_count(cur)
    # Backward compat: keep users_active as online
    users_active = users_online
    # "Registered visits" = any non-terminal visit (includes IN_TREATMENT / ADMITTED / etc.)
    visits_open = _safe_count(
        cur,
        "SELECT COUNT(*) AS c FROM visits WHERE UPPER(TRIM(COALESCE(status,''))) NOT IN ('DISCHARGED','TRANSFERRED','LAMA','EXPIRED','CANCELLED','CLOSED','VISIT_COMPLETED','COMPLETED')",
    )
    visits_cancelled = _safe_count(
        cur,
        "SELECT COUNT(*) AS c FROM visits WHERE UPPER(TRIM(COALESCE(status,'')))='CANCELLED'",
    )
    visits_total = _safe_count(cur, "SELECT COUNT(*) AS c FROM visits")
    lab_pending = _safe_count(
        cur,
        "SELECT COUNT(*) AS c FROM lab_requests WHERE status IN ('REQUESTED','RECEIVED')",
    )
    rad_pending = _safe_count(
        cur,
        "SELECT COUNT(*) AS c FROM radiology_requests WHERE status IN ('REQUESTED','SENT','RECEIVED','UNDER_PROCESS','DONE')",
    )

    chat_recent = 0
    try:
        cutoff = (datetime.now() - timedelta(minutes=15)).strftime("%Y-%m-%d %H:%M:%S")
        chat_recent = _safe_count(
            cur,
            "SELECT COUNT(*) AS c FROM chat_messages WHERE created_at >= ?",
            (cutoff,),
        )
    except Exception:
        chat_recent = 0

    attachments_total = _safe_count(cur, "SELECT COUNT(*) AS c FROM attachments")

    uploads_path = app.config.get("UPLOAD_FOLDER") or UPLOAD_FOLDER
    backups_path = BACKUP_FOLDER

    uploads_exists, uploads_writable = _dir_health(uploads_path)
    backups_exists, backups_writable = _dir_health(backups_path)

    backups_count = 0
    backups_last = ""
    try:
        if os.path.isdir(backups_path):
            files = []
            for fn in os.listdir(backups_path):
                full = os.path.join(backups_path, fn)
                if not os.path.isfile(full):
                    continue
                if not (
                    fn.lower().endswith(".db")
                    or fn.lower().endswith(".dump")
                    or fn.lower().endswith(".sql")
                ):
                    continue
                st = os.stat(full)
                files.append((st.st_mtime, fn))
            files.sort(reverse=True)
            backups_count = len(files)
            backups_last = files[0][1] if files else ""
    except Exception:
        backups_count = 0
        backups_last = ""

    db_identity = ""
    db_size_kb = None
    try:
        if DB_ENGINE == "postgres":
            db_identity = _mask_pg_dsn(PG_DSN)
        else:
            db_identity = os.path.abspath(DATABASE)
            try:
                st = os.stat(DATABASE)
                db_size_kb = round(st.st_size / 1024.0, 1)
            except Exception:
                db_size_kb = None
    except Exception:
        pass

    tools_root = _tools_root()
    manifest = _tools_manifest()
    found = 0
    for section, fname, title, desc in manifest:
        if os.path.exists(os.path.join(tools_root, fname)):
            found += 1

    return render_template(
        "admin_panel.html",
        now=datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        db_ok=db_ok,
        db_message=db_message,
        db_identity=db_identity,
        db_size_kb=db_size_kb,
        uploads_path=uploads_path,
        backups_path=backups_path,
        uploads_exists=uploads_exists,
        uploads_writable=uploads_writable,
        backups_exists=backups_exists,
        backups_writable=backups_writable,
        stats=dict(
            users_total=users_total,
            users_enabled=users_enabled,
            users_online=users_online,
            users_active=users_active,
            visits_open=visits_open,
            visits_cancelled=visits_cancelled,
            visits_total=visits_total,
            lab_pending=lab_pending,
            rad_pending=rad_pending,
            chat_recent=chat_recent,
            attachments_total=attachments_total,
            backups_count=backups_count,
            backups_last=backups_last,
            tools_found=found,
            tools_total=len(manifest),
        ),
    )


@app.route("/admin/tools")
@login_required
@role_required("admin")
def admin_tools():
    tools_root = _tools_root()
    manifest = _tools_manifest()

    sections = {}
    for section, fname, title, desc in manifest:
        full = os.path.join(tools_root, fname)
        meta = _stat_file(full)
        meta.update({"file": fname, "title": title, "desc": desc})
        sections.setdefault(section, []).append(meta)

    available = sum(1 for s in sections.values() for it in s if it.get("exists"))

    return render_template(
        "admin_tools.html",
        tools_root=tools_root,
        sections=sections,
        available=available,
        total=len(manifest),
    )


@app.route("/admin/tools/download/<path:filename>")
@login_required
@role_required("admin")
def admin_tool_download(filename):
    tools_root = _tools_root()
    safe_name = secure_filename(filename)

    allowed = {fname for _, fname, _, _ in _tools_manifest()}
    if safe_name not in allowed:
        return "Not allowed", 403

    full = os.path.join(tools_root, safe_name)
    if not os.path.exists(full):
        return "File not found", 404

    return send_from_directory(tools_root, safe_name, as_attachment=True)


@app.route("/admin/tools/bundle.zip")
@login_required
@role_required("admin")
def admin_tools_bundle():
    """Download a compact bundle (scripts + SQL + docs)."""
    tools_root = _tools_root()
    manifest = _tools_manifest()

    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", compression=zipfile.ZIP_DEFLATED) as z:
        for section, fname, title, desc in manifest:
            if fname.lower().endswith(".zip"):
                continue
            full = os.path.join(tools_root, fname)
            if not os.path.exists(full):
                continue
            try:
                z.write(full, arcname=fname)
            except Exception:
                pass
    buf.seek(0)
    download_name = (
        f"ED_Downtime_tools_bundle_{datetime.now().strftime('%Y%m%d_%H%M%S')}.zip"
    )
    headers = {"Content-Disposition": f'attachment; filename="{download_name}"'}
    return Response(buf.getvalue(), mimetype="application/zip", headers=headers)


@app.route("/admin/db/apply_indexes", methods=["POST"])
@login_required
@role_required("admin")
def admin_apply_postgres_indexes():
    if DB_ENGINE != "postgres":
        flash("This tool is available for PostgreSQL only.", "warning")
        return redirect(url_for("admin_panel"))

    tools_root = _tools_root()
    sql_path = os.path.join(tools_root, "indexes_postgres.sql")
    if not os.path.exists(sql_path):
        # Fallbacks: some deployments keep SQL files in the app root.
        alt1 = os.path.join(_app_root_dir(), "indexes_postgres.sql")
        alt2 = os.path.join(_app_root_dir(), "sql", "indexes_postgres.sql")
        if os.path.exists(alt1):
            sql_path = alt1
        elif os.path.exists(alt2):
            sql_path = alt2
        else:
            flash("indexes_postgres.sql not found in tools folder.", "danger")
            return redirect(url_for("admin_panel"))

    try:
        sql_text = Path(sql_path).read_text(encoding="utf-8", errors="ignore")
    except Exception as e:
        flash(f"Failed to read SQL file: {e}", "danger")
        return redirect(url_for("admin_panel"))

    # ------------------------------------------------------------
    # IMPORTANT:
    # indexes_postgres.sql may contain a DO $$ ... $$; block
    # which includes many internal semicolons.
    # A naive split(";") breaks the DO block and causes errors like:
    #   syntax error at or near "IF"  (executing "END IF" alone)
    #
    # We therefore split ONLY on semicolons that are OUTSIDE:
    # - single-quoted strings
    # - double-quoted identifiers
    # - dollar-quoted blocks ($$...$$ or $tag$...$tag$)
    # - SQL comments (-- ... or /* ... */)
    # ------------------------------------------------------------
    def _split_sql_statements(sql: str):
        out = []
        buf = []

        in_squote = False
        in_dquote = False
        in_line_comment = False
        in_block_comment = False
        dollar_tag = None  # e.g. $$ or $BODY$

        i = 0
        n = len(sql)
        while i < n:
            ch = sql[i]
            nxt = sql[i + 1] if i + 1 < n else ""

            # -- line comment
            if (
                not (in_squote or in_dquote or dollar_tag or in_block_comment)
                and ch == "-"
                and nxt == "-"
            ):
                in_line_comment = True
                buf.append(ch)
                buf.append(nxt)
                i += 2
                continue

            if in_line_comment:
                buf.append(ch)
                if ch == "\n":
                    in_line_comment = False
                i += 1
                continue

            # /* block comment */
            if (
                not (in_squote or in_dquote or dollar_tag or in_block_comment)
                and ch == "/"
                and nxt == "*"
            ):
                in_block_comment = True
                buf.append(ch)
                buf.append(nxt)
                i += 2
                continue

            if in_block_comment:
                buf.append(ch)
                if ch == "*" and nxt == "/":
                    buf.append(nxt)
                    i += 2
                    in_block_comment = False
                    continue
                i += 1
                continue

            # Dollar-quoted string delimiter: $$ or $TAG$
            if not (in_squote or in_dquote) and ch == "$":
                j = i + 1
                while j < n and (sql[j].isalnum() or sql[j] == "_"):
                    j += 1
                if j < n and sql[j] == "$":
                    delim = sql[i : j + 1]  # includes both '$'
                    if dollar_tag is None:
                        dollar_tag = delim
                    elif dollar_tag == delim:
                        dollar_tag = None
                    buf.append(delim)
                    i = j + 1
                    continue

            # Single-quoted string (skip escaped '')
            if dollar_tag is None and not in_dquote and ch == "'":
                if in_squote and nxt == "'":
                    buf.append(ch)
                    buf.append(nxt)
                    i += 2
                    continue
                in_squote = not in_squote
                buf.append(ch)
                i += 1
                continue

            # Double-quoted identifier (skip escaped "")
            if dollar_tag is None and not in_squote and ch == '"':
                if in_dquote and nxt == '"':
                    buf.append(ch)
                    buf.append(nxt)
                    i += 2
                    continue
                in_dquote = not in_dquote
                buf.append(ch)
                i += 1
                continue

            # Statement delimiter
            if ch == ";" and not (
                in_squote
                or in_dquote
                or dollar_tag
                or in_line_comment
                or in_block_comment
            ):
                stmt = "".join(buf).strip()
                if stmt:
                    out.append(stmt)
                buf = []
                i += 1
                continue

            buf.append(ch)
            i += 1

        tail = "".join(buf).strip()
        if tail:
            out.append(tail)

        # Drop statements that are only comments/whitespace
        cleaned = []
        for s in out:
            lines = [
                ln
                for ln in s.splitlines()
                if ln.strip() and not ln.strip().startswith("--")
            ]
            if lines:
                cleaned.append(s.strip())
        return cleaned

    stmts = _split_sql_statements(sql_text)
    if not stmts:
        flash("No SQL statements found in indexes_postgres.sql", "warning")
        return redirect(url_for("admin_panel"))

    db = get_db()
    ran = 0
    try:
        for s in stmts:
            cur = db.cursor()
            cur.execute(s)
            ran += 1

        db.commit()

        analyze_after = request.form.get("analyze") == "1"
        analyze_ok = False
        analyze_err = ""

        if analyze_after:
            try:
                cur2 = db.cursor()
                for t in (
                    "visits",
                    "patients",
                    "lab_requests",
                    "radiology_requests",
                    "attachments",
                ):
                    try:
                        cur2.execute(f"ANALYZE {t}")
                    except Exception:
                        # some installs may not have all tables or privileges
                        pass
                db.commit()
                analyze_ok = True
            except Exception as e2:
                analyze_err = str(e2)
                try:
                    db.rollback()
                except Exception:
                    pass

        log_action(
            "ADMIN_APPLY_INDEXES",
            details=f"statements={ran}, analyze={(1 if (analyze_after and analyze_ok) else 0)}",
        )

        msg = f"Indexes applied successfully (statements: {ran})."
        if analyze_after:
            if analyze_ok:
                msg += " ANALYZE completed."
            else:
                msg += " ANALYZE failed."
                if analyze_err:
                    try:
                        flash(f"ANALYZE failed: {analyze_err}", "warning")
                    except Exception:
                        pass

        flash(msg, "success")
    except Exception as e:
        try:
            db.rollback()
        except Exception:
            pass
        flash(f"Failed to apply indexes: {e}", "danger")

    return redirect(url_for("admin_panel"))


