# 2) Bulk Collect endpoint (nurse/lab/admin)
@app.route("/lab_requests/bulk_collect", methods=["POST"])
@login_required
@role_required("nurse", "lab", "admin")
def lab_bulk_collect():
    """Mark multiple lab requests as COLLECTED (bulk action)."""
    raw_rids = []
    next_url = (
        (request.form.get("next_url") or "").strip()
        or (request.args.get("next_url") or "").strip()
        or request.referrer
        or url_for("lab_board")
    )
    open_visit = (
        (request.form.get("open_visit") or "").strip()
        or (request.args.get("open_visit") or "").strip()
    )

    for key in ("rids", "rids[]"):
        try:
            raw_rids.extend(request.form.getlist(key) or [])
        except Exception:
            pass

    if not raw_rids:
        try:
            payload = request.get_json(silent=True) or {}
            next_url = (payload.get("next_url") or next_url or "").strip() or next_url
            open_visit = (payload.get("open_visit") or open_visit or "").strip() or open_visit
            for key in ("rids", "rids[]"):
                val = payload.get(key)
                if isinstance(val, (list, tuple, set)):
                    raw_rids.extend(list(val))
                elif val not in (None, ""):
                    raw_rids.append(val)
        except Exception:
            pass

    ids = []
    seen = set()
    for x in raw_rids:
        try:
            rid = int(str(x).strip())
        except Exception:
            continue
        if rid in seen:
            continue
        seen.add(rid)
        ids.append(rid)

    db = get_db()
    cur = db.cursor()
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    user = session.get("username", "UNKNOWN")

    if not open_visit and ids:
        try:
            _visit_row = cur.execute(
                "SELECT visit_id FROM lab_requests WHERE id=? LIMIT 1", (ids[0],)
            ).fetchone()
            if _visit_row is not None:
                try:
                    open_visit = str(_visit_row["visit_id"] or "").strip()
                except Exception:
                    open_visit = str(_visit_row[0] or "").strip()
        except Exception:
            pass

    if not ids:
        flash("No tests selected.", "warning")
        if open_visit:
            next_url = _lab_board_return_url(next_url, open_visit)
        return redirect(next_url or url_for("lab_board"))

    ph = ",".join(["?"] * len(ids))
    sql = f"""
        UPDATE lab_requests
           SET status='COLLECTED',
               collected_at=COALESCE(collected_at, ?),
               collected_by=COALESCE(collected_by, ?)
         WHERE id IN ({ph})
           AND status='REQUESTED'
    """
    try:
        cur.execute(sql, [now, user] + ids)
        db.commit()
        updated = getattr(cur, "rowcount", 0) or 0
        try:
            log_action(
                "LAB_BULK_COLLECT",
                visit_id=(open_visit or None),
                details=f"updated={updated} ids={ids}",
            )
        except Exception:
            pass

        if updated:
            flash(f"Collected {updated} lab sample(s).", "success")
        else:
            flash("No lab requests were updated (already collected/reported).", "info")
    except Exception as e:
        try:
            db.rollback()
        except Exception:
            pass
        flash("Bulk collect failed.", "danger")
        try:
            log_action(
                "LAB_BULK_COLLECT_FAIL",
                visit_id=(open_visit or None),
                details=str(e),
            )
        except Exception:
            pass

    if open_visit:
        next_url = _lab_board_return_url(next_url, open_visit)
    return redirect(next_url or url_for("lab_board"))


