# Patch: Clinical Orders — add dropdown (datalist) to Search/Add inputs (Radiology/Lab/Medications) like Home Medication
try:
    if "clinical_orders.html" in TEMPLATES:
        _c = TEMPLATES["clinical_orders.html"]

        def _ensure_datalist(
            html: str, input_id: str, list_id: str, items_var: str
        ) -> str:
            # Add list attribute (idempotent)
            target = f'id="{input_id}"'
            wanted = f'id="{input_id}" list="{list_id}"'
            if wanted not in html:
                html = html.replace(target, wanted, 1)

            # Insert datalist once (after the input-group)
            if f'<datalist id="{list_id}">' in html:
                return html

            idx = html.find(wanted)
            if idx == -1:
                return html

            end = html.find("</div>", idx)
            if end == -1:
                return html
            insert_pos = end + len("</div>")

            dl = f"""
<datalist id="{list_id}">
  {{% for item in {items_var} or [] %}}
    <option value="{{{{ item.name }}}}"></option>
  {{% endfor %}}
</datalist>"""
            return html[:insert_pos] + dl + html[insert_pos:]

        _c = _ensure_datalist(_c, "rad_other", "rad_orders_list", "rad_items")
        _c = _ensure_datalist(_c, "lab_other", "lab_orders_list", "lab_items")
        _c = _ensure_datalist(_c, "med_other", "med_orders_list", "med_items")

        TEMPLATES["clinical_orders.html"] = _c
except Exception:
    pass


