# 3) API endpoint for Payment Details popup (prevents HTML data-attr truncation)
try:
    # Avoid double-registering on reload
    if "api_visit_payment_details" not in globals():

        @app.route("/api/visit/<visit_id>/payment_details")
        @login_required
        @role_required("admin", "reception", "mrd")
        def api_visit_payment_details(visit_id):
            """Payment details API for the popup.

            Returns:
              - payment_details (short board summary)
              - ip_payment_details (if any)
              - popup_text (rich, human-readable text built from insurance_json / financial_json when available)
              - insurance / financial (parsed dicts when available)
            """
            db = get_db()
            cur = db.cursor()

            # Ensure optional columns exist if the helper exists
            try:
                if "ensure_visit_financial_schema" in globals():
                    ensure_visit_financial_schema()
            except Exception:
                pass

            row = None
            try:
                row = cur.execute(
                    "SELECT payment_details, ip_payment_details, insurance_json, financial_json FROM visits WHERE visit_id=?",
                    (visit_id,),
                ).fetchone()
            except Exception:
                row = cur.execute(
                    "SELECT payment_details, ip_payment_details FROM visits WHERE visit_id=?",
                    (visit_id,),
                ).fetchone()

            if not row:
                abort(404)

            # Safe getters for sqlite3.Row / dict / tuple
            def _get(row, key, idx=None):
                try:
                    if isinstance(row, dict):
                        return row.get(key)
                    if hasattr(row, "keys") and key in row.keys():
                        return row[key]
                except Exception:
                    pass
                if idx is not None:
                    try:
                        return row[idx]
                    except Exception:
                        pass
                return None

            pd = _get(row, "payment_details", 0) or ""
            ipd = _get(row, "ip_payment_details", 1) or ""
            ins_json = _get(row, "insurance_json", 2) or ""
            fin_json = _get(row, "financial_json", 3) or ""

            # Parse JSON (best-effort)
            ins = {}
            fin = {}
            try:
                if ins_json:
                    ins = json.loads(ins_json)
            except Exception:
                ins = {}
            try:
                if fin_json:
                    fin = json.loads(fin_json)
            except Exception:
                fin = {}

            def _split_summary(s):
                if not s:
                    return []
                return [p.strip() for p in str(s).split("|") if p.strip()]

            lines = []

            # Insurance section (if structured data exists)
            if isinstance(ins, dict) and any(
                str(v).strip() for v in ins.values() if v is not None
            ):
                lines.append("Insurance")

                def add(label, val):
                    val = "" if val is None else str(val).strip()
                    if val:
                        lines.append(f"{label}: {val}")

                add("Provider", ins.get("provider") or ins.get("insurance"))
                add("Member No", ins.get("member_no"))
                add("Plan", ins.get("plan"))
                add("Card No", ins.get("card_no"))
                add("DHA Member ID", ins.get("dha_member_id"))
                add("Policy No", ins.get("policy_no"))
                add("Policy Name", ins.get("policy_name"))
                add("Valid From", ins.get("valid_from"))
                add("Valid To", ins.get("valid_to"))
                add("Eligibility", ins.get("eligibility_status"))
                add("Eligibility Notes", ins.get("eligibility_notes"))

            # Financial section (if structured data exists)
            if isinstance(fin, dict) and any(
                str(v).strip() for v in fin.values() if v is not None
            ):
                if lines:
                    lines.append("")
                lines.append("Financial")

                def addf(label, val):
                    val = "" if val is None else str(val).strip()
                    if val:
                        # If this line represents a percentage, show the % symbol for clarity.
                        if "%" in str(label) and "%" not in val:
                            val = f"{val}%"
                        lines.append(f"{label}: {val}")

                addf("Payment Method", fin.get("payment_method"))
                addf("Receipt No", fin.get("receipt_no"))

                copay = fin.get("copay_amount")
                if copay is not None and str(copay).strip() != "":
                    addf("Copay Amount", copay)

                addf("Notes", fin.get("notes"))

                cs = fin.get("contract_scheme")
                if isinstance(cs, dict) and any(
                    str(v).strip() for v in cs.values() if v is not None
                ):
                    lines.append("")
                    lines.append("Contract Scheme")
                    for lbl, key in [
                        ("Consult %", "consult_deduct_percent"),
                        ("Consult Amt", "consult_deduct_amount"),
                        ("Lab %", "lab_percent"),
                        ("Lab Amt", "lab_amount"),
                        ("Radiology %", "radiology_percent"),
                        ("Radiology Amt", "radiology_amount"),
                        ("Investigation %", "investigation_percent"),
                        ("Investigation Amt", "investigation_amount"),
                        ("Inpatient %", "inpatient_percent"),
                        ("Inpatient Amt", "inpatient_amount"),
                        ("Pharmacy %", "pharmacy_percent"),
                        ("Pharmacy Amt", "pharmacy_amount"),
                        ("Dental %", "dental_percent"),
                        ("Dental Amt", "dental_amount"),
                    ]:
                        val = cs.get(key)
                        if val is None:
                            # Backward-compat keys (older JSON field names)
                            fallback_keys = {
                                "consult_deduct_percent": [
                                    "consult_deduct",
                                    "consult_percent",
                                    "consult_pct",
                                ],
                                "consult_deduct_amount": [
                                    "consult_amount",
                                    "consult_amt",
                                ],
                                "lab_percent": [
                                    "lab_deduct_percent",
                                    "lab_deduct",
                                    "lab_pct",
                                ],
                                "lab_amount": ["lab_amt"],
                                "radiology_percent": [
                                    "radiology_deduct_percent",
                                    "radiology_deduct",
                                    "rad_percent",
                                    "rad_pct",
                                ],
                                "radiology_amount": ["radiology_amt", "rad_amount"],
                                "investigation_percent": [
                                    "investigation_deduct_percent",
                                    "investigation_deduct",
                                    "invest_percent",
                                    "invest_pct",
                                ],
                                "investigation_amount": ["investigation_amt"],
                                "inpatient_percent": [
                                    "inpatient_deduct_percent",
                                    "inpatient_deduct",
                                    "ip_percent",
                                    "ip_pct",
                                ],
                                "inpatient_amount": ["inpatient_amt", "ip_amount"],
                                "pharmacy_percent": [
                                    "pharmacy_deduct_percent",
                                    "pharmacy_deduct",
                                    "pharm_percent",
                                    "pharm_pct",
                                ],
                                "pharmacy_amount": ["pharmacy_amt"],
                                "dental_percent": [
                                    "dental_deduct_percent",
                                    "dental_deduct",
                                    "dent_percent",
                                    "dent_pct",
                                ],
                                "dental_amount": ["dental_amt"],
                            }.get(key, [])
                            for fk in fallback_keys:
                                v2 = cs.get(fk)
                                if v2 is None:
                                    continue
                                if isinstance(v2, str) and not v2.strip():
                                    continue
                                val = v2
                                break

                        if val is None:
                            continue

                        sv = str(val).strip()
                        # Make % explicit for percentage fields
                        if "%" in lbl and sv and ("%" not in sv):
                            sv = f"{sv}%"
                        lines.append(f"{lbl}: {sv}")
            # Always include stored summaries so nothing is lost
            if pd:
                if lines:
                    lines.append("")
                lines.append("Visit Payment Summary")
                lines.extend(_split_summary(pd))

            if ipd:
                if lines:
                    lines.append("")
                lines.append("IP Payment Details")
                lines.extend(_split_summary(ipd))

            popup_text = "\n".join(lines).strip()

            return jsonify(
                {
                    "ok": True,
                    "visit_id": visit_id,
                    "payment_details": pd or "",
                    "ip_payment_details": ipd or "",
                    "popup_text": popup_text or "",
                    "insurance": ins if isinstance(ins, dict) else {},
                    "financial": fin if isinstance(fin, dict) else {},
                }
            )

except Exception:
    pass


