@app.route("/export/scan.xlsx")
@login_required
def export_scan_xlsx():
    """Download a 1-row Excel sheet for a scanned patient (Case No or ID number).

    Columns requested by operations (Excel paste/workflow):
      Name, DOB, Age, ID number, Insurance No, Visit date, Registration time,
      Clinic (if any), Treating doctor.

    Usage:
      /export/scan.xlsx?code=<visit_id_or_id_number>

    NOTE: We keep the barcode itself short (ID/Case No) for print + scan reliability.
    """
    code = normalize_scan_code(request.args.get("code") or "")
    if not code:
        return "Missing code", 400

    cur = get_db().cursor()

    # Prefer exact visit_id match first
    row = None
    try:
        row = cur.execute(
            """
            SELECT
                v.visit_id,
                v.created_at,
                COALESCE(v.clinic,'ED') AS clinic,
                v.assigned_doctor,
                p.name,
                p.dob,
                p.mrn,
                p.id_number,
                p.insurance,
                p.insurance_no
            FROM visits v
            JOIN patients p ON p.id = v.patient_id
            WHERE v.visit_id = ?
            LIMIT 1
            """,
            (code,),
        ).fetchone()
    except Exception:
        row = None

    if not row:
        try:
            row = cur.execute(
                """
                SELECT
                    v.visit_id,
                    v.created_at,
                    COALESCE(v.clinic,'ED') AS clinic,
                    v.assigned_doctor,
                    p.name,
                    p.dob,
                    p.mrn,
                    p.id_number,
                    p.insurance,
                    p.insurance_no
                FROM visits v
                JOIN patients p ON p.id = v.patient_id
                WHERE p.id_number = ? OR p.mrn = ?
                ORDER BY v.created_at DESC
                LIMIT 1
                """,
                (code, code),
            ).fetchone()
        except Exception:
            row = None

    if not row:
        return "Not found", 404

    # Normalize row access for sqlite.Row / dict
    def rget(k, default=""):
        try:
            v = row[k]
            return v if v is not None else default
        except Exception:
            return default

    name = rget("name", "")
    dob = (rget("dob", "") or "").strip()
    id_number = rget("id_number", "")
    insurance = rget("insurance", "")
    insurance_no = rget("insurance_no", "")
    visit_id = rget("visit_id", "")
    created_at = rget("created_at", "")
    clinic_code = (rget("clinic", "") or "").strip() or "ED"
    doctor = rget("assigned_doctor", "")

    # Clinic label
    clinic_label = _clinic_label_from_code(clinic_code) or clinic_code

    # Age
    try:
        age = calc_age(dob) if dob else ""
    except Exception:
        age = ""

    visit_date = format_date_yyyy_mm_dd(created_at)
    reg_time = format_time_hhmm(created_at)

    headers = [
        "Name",
        "DOB",
        "Age",
        "ID Number",
        "Insurance",
        "Insurance No",
        "Visit Date",
        "Registration Time",
        "Clinic",
        "Treating Doctor",
        "Case No",
    ]

    row_vals = [
        name,
        dob,
        age,
        id_number,
        insurance,
        insurance_no,
        visit_date,
        reg_time,
        clinic_label,
        doctor,
        visit_id,
    ]

    # If openpyxl isn't available, fall back to CSV (still opens in Excel)
    if "Workbook" not in globals() or Workbook is None:
        import csv, io

        buf = io.StringIO()
        w = csv.writer(buf)
        w.writerow(headers)
        w.writerow(row_vals)
        csv_text = buf.getvalue()
        resp = Response(csv_text, mimetype="text/csv")
        resp.headers["Content-Disposition"] = (
            f"attachment; filename=scan_{visit_id or code}.csv"
        )
        return resp

    wb = Workbook()
    ws = wb.active
    ws.title = "Scan"
    ws.append(headers)
    ws.append(row_vals)

    # Freeze header row
    try:
        ws.freeze_panes = "A2"
    except Exception:
        pass

    # Simple column widths (optional)
    try:
        widths = [24, 12, 8, 16, 16, 16, 12, 16, 18, 22, 14]
        for i, w in enumerate(widths, start=1):
            ws.column_dimensions[chr(64 + i)].width = w
    except Exception:
        pass

    import io

    bio = io.BytesIO()
    wb.save(bio)
    bio.seek(0)

    fname = f"scan_{visit_id or code}.xlsx"
    return send_file(
        bio,
        as_attachment=True,
        download_name=fname,
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    )


# ------------------------------------------------------------
# Scan Log (daily Excel) - auto append on each successful scan
# ------------------------------------------------------------
SCAN_LOG_HEADERS = [
    "Name",
    "DOB",
    "Age",
    "ID Number",
    "Insurance",
    "Insurance No",
    "Visit Date",
    "Registration Time",
    "Clinic",
    "Treating Doctor",
    "Case No",
]

_SCAN_LOG_LOCK = threading.Lock()


def _scan_logs_dir() -> str:
    """Folder that stores daily scan logs (best-effort)."""
    base = app.config.get("BACKUP_FOLDER") or BACKUP_FOLDER
    try:
        d = os.path.join(base, "scan_logs")
        os.makedirs(d, exist_ok=True)
        return d
    except Exception:
        try:
            os.makedirs(base, exist_ok=True)
            return base
        except Exception:
            # last resort: local folder
            d = os.path.join(BASE_DIR, "scan_logs")
            try:
                os.makedirs(d, exist_ok=True)
            except Exception:
                pass
            return d


def _scan_log_file_paths(date_str: str = ""):
    """Return (xlsx_path, csv_path, safe_date_str)."""
    if not date_str:
        date_str = datetime.now().strftime("%Y-%m-%d")
    safe = re.sub(r"[^0-9\-]", "", str(date_str)) or datetime.now().strftime("%Y-%m-%d")
    d = _scan_logs_dir()
    xlsx_path = os.path.join(d, f"scan_log_{safe}.xlsx")
    csv_path = os.path.join(d, f"scan_log_{safe}.csv")
    return xlsx_path, csv_path, safe


def _scan_visit_to_rowvals(v: dict):
    return [
        v.get("name") or "",
        (v.get("dob") or "").strip(),
        v.get("age_years") or v.get("age") or "",
        v.get("id_number") or "",
        v.get("insurance") or "",
        v.get("insurance_no") or "",
        v.get("visit_date") or "",
        v.get("reg_time") or "",
        v.get("clinic_label") or v.get("clinic") or "",
        v.get("assigned_doctor") or "",
        v.get("visit_id") or "",
    ]


def append_to_daily_scan_log(scan_visit: dict, date_str: str = "") -> dict:
    """Append 1 row to today's scan log.

    Returns:
      {ok: bool, path: str, fmt: 'xlsx'|'csv', warning?: str}
    """
    if not scan_visit:
        return {"ok": False, "error": "empty"}

    xlsx_path, csv_path, safe = _scan_log_file_paths(date_str)

    row_vals = _scan_visit_to_rowvals(scan_visit)

    with _SCAN_LOG_LOCK:
        # If openpyxl isn't available, fall back to CSV (still opens in Excel)
        if Workbook is None or load_workbook is None:
            try:
                is_new = not os.path.exists(csv_path)
                with open(csv_path, "a", newline="", encoding="utf-8") as f:
                    w = csv.writer(f)
                    if is_new:
                        w.writerow(SCAN_LOG_HEADERS)
                    w.writerow(row_vals)
                return {"ok": True, "path": csv_path, "fmt": "csv"}
            except Exception as e:
                return {"ok": False, "error": str(e), "path": csv_path, "fmt": "csv"}

        # XLSX
        try:
            if os.path.exists(xlsx_path):
                wb = load_workbook(xlsx_path)
                ws = wb.active
            else:
                wb = Workbook()
                ws = wb.active
                ws.title = "ScanLog"
                ws.append(SCAN_LOG_HEADERS)
                try:
                    ws.freeze_panes = "A2"
                except Exception:
                    pass
                # basic widths
                try:
                    widths = [24, 12, 8, 18, 16, 16, 12, 16, 18, 22, 14]
                    for i, w in enumerate(widths, start=1):
                        ws.column_dimensions[chr(64 + i)].width = w
                except Exception:
                    pass

            ws.append(row_vals)
            try:
                wb.save(xlsx_path)
            except PermissionError:
                # File may be open in Excel -> write a side file so we don't lose scans
                alt = xlsx_path.replace(
                    f"scan_log_{safe}.xlsx", f"scan_log_{safe}_{int(time.time())}.xlsx"
                )
                wb.save(alt)
                return {
                    "ok": True,
                    "path": alt,
                    "fmt": "xlsx",
                    "warning": "Main scan log file is open in Excel; saved to an alternate file. Close Excel to keep a single daily file.",
                }
            return {"ok": True, "path": xlsx_path, "fmt": "xlsx"}
        except Exception as e:
            # As a last resort, try CSV
            try:
                is_new = not os.path.exists(csv_path)
                with open(csv_path, "a", newline="", encoding="utf-8") as f:
                    w = csv.writer(f)
                    if is_new:
                        w.writerow(SCAN_LOG_HEADERS)
                    w.writerow(row_vals)
                return {
                    "ok": True,
                    "path": csv_path,
                    "fmt": "csv",
                    "warning": f"XLSX failed; saved CSV instead ({e}).",
                }
            except Exception:
                return {"ok": False, "error": str(e)}


def _maybe_log_scan_once(scan_visit: dict, raw_code: str = ""):
    """Avoid duplicate log entries on fast refresh (same code within a few seconds)."""
    if not scan_visit:
        return

    try:
        key = f"{scan_visit.get('visit_id','')}|{(raw_code or '').strip()}"
        now_ts = int(time.time())
        last = session.get("_last_scan_log") or {}
        last_key = last.get("k")
        last_ts = int(last.get("t") or 0)
        if last_key == key and (now_ts - last_ts) <= 3:
            return
        session["_last_scan_log"] = {"k": key, "t": now_ts}
    except Exception:
        pass

    try:
        res = append_to_daily_scan_log(scan_visit)
        # If we had to write an alternate file because Excel is open, warn once
        if res.get("warning"):
            try:
                flash(res["warning"], "warning")
            except Exception:
                pass
    except Exception:
        pass


@app.route("/export/scan_log.xlsx")
@login_required
def export_scan_log():
    """Download the daily scan log (XLSX preferred)."""
    date_str = (request.args.get("date") or "").strip()
    xlsx_path, csv_path, safe = _scan_log_file_paths(date_str)

    if os.path.exists(xlsx_path):
        return send_file(
            xlsx_path,
            as_attachment=True,
            download_name=os.path.basename(xlsx_path),
            mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        )

    if os.path.exists(csv_path):
        return send_file(
            csv_path,
            as_attachment=True,
            download_name=os.path.basename(csv_path),
            mimetype="text/csv",
        )

    return "Scan log not found", 404


