@app.route("/api/scan_lookup")
@login_required
def api_scan_lookup():
    """AJAX helper: resolve a scanned code into a visit + patient details.

    Accepts Case No or patient ID number.
    Returns:
      { ok: true/false, found: bool, code: normalized_code, visit: {...} }
    """
    raw_code = request.args.get("code") or request.values.get("code") or ""
    code = normalize_scan_code(raw_code)
    if not code:
        return jsonify({"ok": True, "found": False, "code": ""})

    try:
        db = get_db()
        cur = db.cursor()

        row = cur.execute(
            """
            SELECT
                v.visit_id,
                v.created_at AS visit_created_at,
                COALESCE(v.clinic,'') AS clinic,
                COALESCE(v.assigned_doctor,'') AS doctor,
                COALESCE(v.status,'') AS status,
                p.name,
                p.dob,
                p.mrn,
                p.id_number,
                COALESCE(p.insurance,'') AS insurance,
                COALESCE(p.insurance_no,'') AS insurance_no
            FROM visits v
            JOIN patients p ON p.id = v.patient_id
            WHERE v.visit_id = ?
            LIMIT 1
            """,
            (code,),
        ).fetchone()

        if not row:
            row = cur.execute(
                """
                SELECT
                    v.visit_id,
                    v.created_at AS visit_created_at,
                    COALESCE(v.clinic,'') AS clinic,
                    COALESCE(v.assigned_doctor,'') AS doctor,
                    COALESCE(v.status,'') AS status,
                    p.name,
                    p.dob,
                    p.mrn,
                    p.id_number,
                    COALESCE(p.insurance,'') AS insurance,
                    COALESCE(p.insurance_no,'') AS insurance_no
                FROM visits v
                JOIN patients p ON p.id = v.patient_id
                WHERE p.id_number = ? OR p.mrn = ?
                ORDER BY v.created_at DESC
                LIMIT 1
                """,
                (code, code),
            ).fetchone()

        if not row:
            return jsonify({"ok": True, "found": False, "code": code})

        visit = _row_to_dict(row)
        dob = visit.get("dob")
        try:
            visit["age"] = calc_age(dob) if dob else ""
        except Exception:
            visit["age"] = ""

        ts = visit.get("visit_created_at") or visit.get("created_at")
        visit["visit_date"] = format_date_yyyy_mm_dd(ts)
        visit["registration_time"] = format_time_hhmm(ts)
        visit["registered"] = format_dt_local(ts)

        # Normalized fields
        visit["clinic"] = visit.get("clinic") or ""
        visit["doctor"] = visit.get("doctor") or ""
        visit["insurance"] = visit.get("insurance") or ""
        visit["insurance_no"] = visit.get("insurance_no") or ""
        visit["mrn"] = visit.get("mrn") or ""
        visit["id_number"] = visit.get("id_number") or ""

        return jsonify({"ok": True, "found": True, "code": code, "visit": visit})
    except Exception as e:
        return jsonify({"ok": False, "found": False, "code": code, "error": str(e)})


@app.route("/scan", methods=["GET", "POST"])
@login_required
def scan_barcode():
    raw_code = request.values.get("code") or ""
    code = normalize_scan_code(raw_code)
    auto_open = request.values.get("auto_open") == "1"
    visit = None
    if code:
        try:
            db = get_db()
            cur = db.cursor()

            row = cur.execute(
                "SELECT v.visit_id, v.created_at, COALESCE(v.clinic,'ED') AS clinic, v.assigned_doctor, v.status, p.name, p.dob, p.mrn, p.id_number, p.insurance, p.insurance_no "
                "FROM visits v JOIN patients p ON p.id = v.patient_id "
                "WHERE v.visit_id = ? LIMIT 1",
                (code,),
            ).fetchone()

            if not row:
                # Allow scanning / typing the patient ID number as well (returns latest visit).
                row = cur.execute(
                    "SELECT v.visit_id, v.created_at, COALESCE(v.clinic,'ED') AS clinic, v.assigned_doctor, v.status, p.name, p.dob, p.mrn, p.id_number, p.insurance, p.insurance_no "
                    "FROM visits v JOIN patients p ON p.id = v.patient_id "
                    "WHERE p.id_number = ? OR p.mrn = ? ORDER BY v.created_at DESC LIMIT 1",
                    (code, code),
                ).fetchone()

            if row:
                visit = _row_to_dict(row)
                dob = visit.get("dob")
                try:
                    visit["age"] = calc_age(dob) if dob else ""
                except Exception:
                    visit["age"] = ""
                try:
                    visit["registered_at"] = format_dt_local(visit.get("created_at"))
                    visit["visit_date"] = format_date_yyyy_mm_dd(
                        visit.get("created_at")
                    )
                    visit["reg_time"] = format_time_hhmm(visit.get("created_at"))
                    # Clinic label (human readable)
                    try:
                        cl = (visit.get("clinic") or "").strip() or "ED"
                        visit["clinic_label"] = _clinic_label_from_code(cl) or cl
                    except Exception:
                        visit["clinic_label"] = visit.get("clinic") or ""

                except Exception:
                    visit["registered_at"] = str(visit.get("created_at") or "")
        except Exception as e:
            flash(f"Scan lookup error: {e}", "danger")
            visit = None

    if visit:
        _maybe_log_scan_once(visit, raw_code)

    if (
        auto_open
        and visit
        and visit.get("visit_id")
        and code
        and (code != visit.get("visit_id"))
    ):
        return redirect(url_for("patient_details", visit_id=visit["visit_id"]))

    return render_template_string(
        SCAN_TEMPLATE, code=code, visit=visit, auto_open=auto_open
    )


