def sqlite_fts_available(table_name: str) -> bool:
    """Return True if a given SQLite FTS virtual table exists."""
    try:
        if DB_ENGINE == "postgres":
            return False
        name = (table_name or "").strip()
        if not name:
            return False
        row = (
            get_db()
            .execute(
                "SELECT name FROM sqlite_master WHERE type='table' AND name=?",
                (name,),
            )
            .fetchone()
        )
        return bool(row)
    except Exception:
        return False


def fts5_query(q: str) -> str:
    """Build a forgiving FTS5 query (prefix match for each token)."""
    q = (q or "").strip()
    if not q:
        return ""
    # Split by whitespace; keep unicode tokens (Arabic supported)
    tokens = [t.strip() for t in re.split(r"\s+", q) if t.strip()]
    parts = []
    for t in tokens:
        t = t.replace('"', "")
        if len(t) >= 2 and not t.endswith("*"):
            parts.append(t + "*")
        else:
            parts.append(t)
    return " ".join(parts)


def ensure_fts_schema():
    """Create search indexes for faster lookup (idempotent).

    - SQLite: FTS5 virtual tables + triggers
    - PostgreSQL: GIN indexes on to_tsvector expressions
    """
    if DB_ENGINE == "postgres":
        try:
            ensure_postgres_fts_schema()
        except Exception:
            pass
        return
    db = get_db()
    cur = db.cursor()
    try:
        # Patients
        cur.execute("""
            CREATE VIRTUAL TABLE IF NOT EXISTS patients_fts USING fts5(
                name, id_number, phone, insurance, insurance_no,
                content='patients', content_rowid='id'
            )
            """)
        cur.execute("""
            CREATE TRIGGER IF NOT EXISTS patients_ai AFTER INSERT ON patients BEGIN
              INSERT INTO patients_fts(rowid, name, id_number, phone, insurance, insurance_no)
              VALUES (new.id, new.name, new.id_number, new.phone, new.insurance, new.insurance_no);
            END;
            """)
        cur.execute("""
            CREATE TRIGGER IF NOT EXISTS patients_ad AFTER DELETE ON patients BEGIN
              INSERT INTO patients_fts(patients_fts, rowid, name, id_number, phone, insurance, insurance_no)
              VALUES('delete', old.id, old.name, old.id_number, old.phone, old.insurance, old.insurance_no);
            END;
            """)
        cur.execute("""
            CREATE TRIGGER IF NOT EXISTS patients_au AFTER UPDATE ON patients BEGIN
              INSERT INTO patients_fts(patients_fts, rowid, name, id_number, phone, insurance, insurance_no)
              VALUES('delete', old.id, old.name, old.id_number, old.phone, old.insurance, old.insurance_no);
              INSERT INTO patients_fts(rowid, name, id_number, phone, insurance, insurance_no)
              VALUES (new.id, new.name, new.id_number, new.phone, new.insurance, new.insurance_no);
            END;
            """)
        try:
            cur.execute("INSERT INTO patients_fts(patients_fts) VALUES('rebuild')")
        except Exception:
            pass

        # Diagnosis Master
        cur.execute("""
            CREATE VIRTUAL TABLE IF NOT EXISTS diagnosis_master_fts USING fts5(
                name, icd_code, synonyms,
                content='diagnosis_master', content_rowid='id'
            )
            """)
        cur.execute("""
            CREATE TRIGGER IF NOT EXISTS dx_ai AFTER INSERT ON diagnosis_master BEGIN
              INSERT INTO diagnosis_master_fts(rowid, name, icd_code, synonyms)
              VALUES (new.id, new.name, new.icd_code, new.synonyms);
            END;
            """)
        cur.execute("""
            CREATE TRIGGER IF NOT EXISTS dx_ad AFTER DELETE ON diagnosis_master BEGIN
              INSERT INTO diagnosis_master_fts(diagnosis_master_fts, rowid, name, icd_code, synonyms)
              VALUES('delete', old.id, old.name, old.icd_code, old.synonyms);
            END;
            """)
        cur.execute("""
            CREATE TRIGGER IF NOT EXISTS dx_au AFTER UPDATE ON diagnosis_master BEGIN
              INSERT INTO diagnosis_master_fts(diagnosis_master_fts, rowid, name, icd_code, synonyms)
              VALUES('delete', old.id, old.name, old.icd_code, old.synonyms);
              INSERT INTO diagnosis_master_fts(rowid, name, icd_code, synonyms)
              VALUES(new.id, new.name, new.icd_code, new.synonyms);
            END;
            """)
        try:
            cur.execute(
                "INSERT INTO diagnosis_master_fts(diagnosis_master_fts) VALUES('rebuild')"
            )
        except Exception:
            pass

        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass


def ensure_postgres_fts_schema():
    """Create PostgreSQL Full-Text Search (FTS) indexes (idempotent).

    We keep the implementation lightweight (expression GIN indexes), so no schema migrations
    or triggers are required.
    """
    if DB_ENGINE != "postgres":
        return
    db = get_db()
    cur = db.cursor()
    try:
        # Patients: search over name / id / phone / insurance fields
        cur.execute("""
            CREATE INDEX IF NOT EXISTS idx_patients_fts_v2
            ON patients
            USING GIN (
                to_tsvector(
                    'simple',
                    coalesce(name,'') || ' ' ||
                    coalesce(mrn,'') || ' ' ||
                    coalesce(id_number,'') || ' ' ||
                    coalesce(phone,'') || ' ' ||
                    coalesce(insurance,'') || ' ' ||
                    coalesce(insurance_no,'')
                )
            )
            """)
        # Diagnosis Master: search over name / ICD-10 / synonyms
        cur.execute("""
            CREATE INDEX IF NOT EXISTS idx_diagnosis_master_fts
            ON diagnosis_master
            USING GIN (
                to_tsvector(
                    'simple',
                    coalesce(name,'') || ' ' ||
                    coalesce(icd_code,'') || ' ' ||
                    coalesce(synonyms,'')
                )
            )
            """)
        try:
            db.commit()
        except Exception:
            pass
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass


def calc_mews_from_visit_row(visit_row):
    """Simple MEWS scoring from visit vitals."""

    def _f(x):
        try:
            s = str(x).strip().replace(",", ".")
            return float(s)
        except Exception:
            return None

    def _i(x):
        v = _f(x)
        try:
            return int(round(v)) if v is not None else None
        except Exception:
            return None

    def _g(k):
        try:
            return visit_row.get(k)
        except Exception:
            try:
                return visit_row[k]
            except Exception:
                return None

    hr = _i(_g("pulse_rate"))
    rr = _i(_g("resp_rate"))
    sbp = _i(_g("bp_systolic"))
    temp = _f(_g("temperature"))
    avpu = str(_g("consciousness_level") or "").strip().upper() or "A"

    score = 0

    # RR
    if rr is not None:
        if rr <= 8:
            score += 3
        elif 9 <= rr <= 14:
            score += 0
        elif 15 <= rr <= 20:
            score += 1
        elif 21 <= rr <= 29:
            score += 2
        elif rr >= 30:
            score += 3

    # HR
    if hr is not None:
        if hr <= 40:
            score += 2
        elif 41 <= hr <= 50:
            score += 1
        elif 51 <= hr <= 100:
            score += 0
        elif 101 <= hr <= 110:
            score += 1
        elif 111 <= hr <= 129:
            score += 2
        elif hr >= 130:
            score += 3

    # SBP
    if sbp is not None:
        if sbp <= 70:
            score += 3
        elif 71 <= sbp <= 80:
            score += 2
        elif 81 <= sbp <= 100:
            score += 1
        elif 101 <= sbp <= 199:
            score += 0
        elif sbp >= 200:
            score += 2

    # Temp
    if temp is not None:
        if temp <= 35.0:
            score += 2
        elif 35.1 <= temp <= 38.0:
            score += 0
        elif 38.1 <= temp <= 38.5:
            score += 1
        elif temp >= 38.6:
            score += 2

    # AVPU / consciousness
    avpu_map = {
        "A": 0,
        "ALERT": 0,
        "V": 1,
        "VOICE": 1,
        "P": 2,
        "PAIN": 2,
        "U": 3,
        "UNRESPONSIVE": 3,
    }
    score += avpu_map.get(avpu, 0)

    level = "low"
    if score >= 5:
        level = "high"
    elif score >= 3:
        level = "medium"
    return score, level


_ALLERGY_MAP = {
    "penicillin": [
        "amoxicillin",
        "ampicillin",
        "augmentin",
        "piperacillin",
        "tazobactam",
    ],
    "amoxicillin": ["amoxicillin", "augmentin"],
    "cephalosporin": ["cef", "cephal"],
    "sulfa": ["sulf", "trimethoprim"],
}


def allergy_med_conflicts(visit_id: str, meds_text: str):
    """Return list of warnings if meds likely conflict with recorded allergy text."""
    meds = (meds_text or "").strip().lower()
    if not meds:
        return []

    try:
        row = (
            get_db()
            .execute(
                "SELECT allergy_status, allergy_details FROM visits WHERE visit_id=?",
                (visit_id,),
            )
            .fetchone()
        )
    except Exception:
        row = None

    if not row:
        return []

    try:
        alg_status = (row["allergy_status"] or "").strip().upper()
        alg_details = (row["allergy_details"] or "").strip().lower()
    except Exception:
        alg_status = (row[0] or "").strip().upper() if len(row) > 0 else ""
        alg_details = (row[1] or "").strip().lower() if len(row) > 1 else ""

    if alg_status not in ("YES", "Y", "TRUE", "1"):
        return []

    warnings = []
    for allergy_key, triggers in _ALLERGY_MAP.items():
        if allergy_key in alg_details:
            for t in triggers:
                if t in meds:
                    warnings.append(f"{allergy_key} allergy ↔ {t}")
                    break
    return warnings


# --- SSE realtime chat (replace polling) ---
_CHAT_SSE_LOCK = _threading.Lock()
_CHAT_SSE_SUBS = {}  # (room, visit_id) -> set(queue.Queue)


# --- Background task runner (keeps heavy work out of request/response) ---
BG_EXECUTOR = _ThreadPoolExecutor(max_workers=int(os.environ.get("ED_BG_WORKERS", "4")))
BG_TASKS = {}  # task_id -> dict(status, name, created_at, finished_at, result, error)
BG_LOCK = _threading.Lock()


def bg_submit(name, fn, *args, **kwargs):
    """Submit a background task and return task_id."""
    task_id = str(_uuid.uuid4())
    with BG_LOCK:
        BG_TASKS[task_id] = {
            "id": task_id,
            "name": name,
            "status": "queued",
            "created_at": datetime.now().isoformat(sep=" ", timespec="seconds"),
            "finished_at": None,
            "result": None,
            "error": None,
        }

    def _run():
        with BG_LOCK:
            BG_TASKS[task_id]["status"] = "running"
        try:
            res = fn(*args, **kwargs)
            with BG_LOCK:
                BG_TASKS[task_id]["status"] = "done"
                BG_TASKS[task_id]["result"] = res
                BG_TASKS[task_id]["finished_at"] = datetime.now().isoformat(
                    sep=" ", timespec="seconds"
                )
        except Exception as e:
            app.logger.exception("Background task failed (%s): %s", name, e)
            with BG_LOCK:
                BG_TASKS[task_id]["status"] = "error"
                BG_TASKS[task_id]["error"] = str(e)
                BG_TASKS[task_id]["finished_at"] = datetime.now().isoformat(
                    sep=" ", timespec="seconds"
                )
        return True

    BG_EXECUTOR.submit(_run)
    return task_id


def bg_get(task_id):
    with BG_LOCK:
        return BG_TASKS.get(task_id)


def chat_sse_publish(room: str, visit_id: str, payload: dict):
    room = (room or "general").strip().lower() or "general"
    vid = (visit_id or "").strip()
    keys = [(room, ""), (room, vid)]
    targets = []
    with _CHAT_SSE_LOCK:
        for k in keys:
            for q in _CHAT_SSE_SUBS.get(k, set()):
                targets.append(q)
    for q in targets:
        try:
            q.put_nowait(payload)
        except Exception:
            pass


def _resp_text(rv):
    try:
        if isinstance(rv, Response):
            return rv.get_data(as_text=True)
    except Exception:
        pass
    return rv if isinstance(rv, str) else str(rv)


def _extract_between(html: str, start: str, end: str) -> str:
    try:
        s = html.find(start)
        e = html.find(end)
        if s >= 0 and e >= 0 and e > s:
            return html[s + len(start) : e]
    except Exception:
        pass
    return ""


@app.route("/chat/stream")
@login_required
def chat_stream():
    """
    Server-Sent Events (SSE) stream for chat.

    ⚠️ Scaling note:
    - With WSGI/Waitress, each open SSE connection can occupy a worker thread.
    - Also, keeping a DB connection open for the lifetime of the stream can exhaust the PG pool.
      لذلك بنجيب backlog الأول ونقفل الـ DB connection قبل ما نبدأ الستريم.
    """
    ensure_chat_media_schema()

    room = (request.args.get("room") or "general").strip().lower() or "general"
    visit_id = (request.args.get("visit_id") or "").strip()
    after_raw = (request.args.get("after_id") or "").strip()
    try:
        after_id = int(after_raw) if after_raw else 0
    except Exception:
        after_id = 0

    # ------------------------------------------------------------
    # Fetch backlog ONCE (best-effort) then RELEASE DB connection.
    # ------------------------------------------------------------
    backlog_msgs = []
    try:
        cur = get_db().cursor()
        sql = """
            SELECT cm.id, cm.username, cm.message, cm.room, cm.visit_id, cm.created_at,
                   u.full_name
            FROM chat_messages cm
            LEFT JOIN users u ON u.username = cm.username
            WHERE lower(cm.room)=? AND cm.id > ?
        """
        params = [room, after_id]
        if visit_id:
            sql += " AND cm.visit_id=?"
            params.append(visit_id)
        sql += " ORDER BY cm.id ASC LIMIT 200"
        rows = cur.execute(sql, tuple(params)).fetchall()
        for r in rows or []:
            try:
                m = {
                    "id": r["id"],
                    "username": r["username"],
                    "display_name": (r["full_name"] or r["username"]),
                    "message": r["message"],
                    "room": r["room"],
                    "visit_id": r["visit_id"],
                    "created_at": r["created_at"],
                    "attachments": [],
                }
            except Exception:
                m = {
                    "id": r[0],
                    "username": r[1],
                    "display_name": r[6] or r[1],
                    "message": r[2],
                    "room": r[3],
                    "visit_id": r[4],
                    "created_at": r[5],
                    "attachments": [],
                }
            backlog_msgs.append(m)
    except Exception:
        pass

    # Release DB connection so SSE does NOT hold PG pool connection.
    try:
        close_db(None)
    except Exception:
        pass

    # ------------------------------------------------------------
    # Subscribe + stream
    # ------------------------------------------------------------
    q = _queue.Queue(maxsize=200)
    key = (room, visit_id)
    with _CHAT_SSE_LOCK:
        _CHAT_SSE_SUBS.setdefault(key, set()).add(q)

    def gen():
        try:
            # Send backlog immediately
            for m in backlog_msgs:
                yield f"data: {_json.dumps(m, ensure_ascii=False)}\n\n"

            # Live stream
            while True:
                try:
                    item = q.get(timeout=25)
                    if item is None:
                        yield ": ping\n\n"
                    else:
                        yield f"data: {_json.dumps(item, ensure_ascii=False)}\n\n"
                except _queue.Empty:
                    yield ": ping\n\n"
        finally:
            try:
                with _CHAT_SSE_LOCK:
                    s = _CHAT_SSE_SUBS.get(key)
                    if s and q in s:
                        s.remove(q)
            except Exception:
                pass

    return Response(
        gen(),
        mimetype="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
        },
    )


