# --- Inventory (lightweight) ---
def ensure_inventory_schema():
    db = get_db()
    cur = db.cursor()
    try:
        if DB_ENGINE == "postgres":
            cur.execute("""
                CREATE TABLE IF NOT EXISTS inventory_items (
                  id BIGSERIAL PRIMARY KEY,
                  name TEXT NOT NULL,
                  category TEXT,
                  unit TEXT,
                  qty_on_hand INTEGER NOT NULL DEFAULT 0,
                  reorder_level INTEGER NOT NULL DEFAULT 0,
                  updated_at TEXT,
                  updated_by TEXT
                )
                """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS inventory_txn (
                  id BIGSERIAL PRIMARY KEY,
                  item_id BIGINT NOT NULL,
                  delta_qty INTEGER NOT NULL,
                  reason TEXT,
                  created_at TEXT NOT NULL,
                  created_by TEXT NOT NULL
                )
                """)
        else:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS inventory_items (
                  id INTEGER PRIMARY KEY AUTOINCREMENT,
                  name TEXT NOT NULL,
                  category TEXT,
                  unit TEXT,
                  qty_on_hand INTEGER NOT NULL DEFAULT 0,
                  reorder_level INTEGER NOT NULL DEFAULT 0,
                  updated_at TEXT,
                  updated_by TEXT
                )
                """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS inventory_txn (
                  id INTEGER PRIMARY KEY AUTOINCREMENT,
                  item_id INTEGER NOT NULL,
                  delta_qty INTEGER NOT NULL,
                  reason TEXT,
                  created_at TEXT NOT NULL,
                  created_by TEXT NOT NULL
                )
                """)
        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass


@app.route("/inventory", methods=["GET", "POST"])
@login_required
@role_required("admin", "nurse", "doctor")
def inventory():
    ensure_inventory_schema()
    db = get_db()
    cur = db.cursor()
    if request.method == "POST":
        name = (request.form.get("name") or "").strip()
        category = (request.form.get("category") or "").strip()
        unit = (request.form.get("unit") or "").strip()
        try:
            qty = int((request.form.get("qty_on_hand") or "0").strip() or 0)
        except Exception:
            qty = 0
        try:
            reorder = int((request.form.get("reorder_level") or "0").strip() or 0)
        except Exception:
            reorder = 0

        if not name:
            flash("Item name is required", "danger")
        else:
            now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            user = session.get("username") or "SYSTEM"
            cur.execute(
                """
                INSERT INTO inventory_items (name, category, unit, qty_on_hand, reorder_level, updated_at, updated_by)
                VALUES (?,?,?,?,?,?,?)
                """,
                (name, category, unit, qty, reorder, now, user),
            )
            db.commit()
            flash("Inventory item added", "success")
            return redirect(url_for("inventory"))

    items = cur.execute(
        "SELECT * FROM inventory_items ORDER BY category, name"
    ).fetchall()
    return render_template("inventory.html", items=items)


@app.route("/inventory/adjust", methods=["POST"])
@login_required
@role_required("admin", "nurse", "doctor")
def inventory_adjust():
    ensure_inventory_schema()
    db = get_db()
    cur = db.cursor()
    item_id = (request.form.get("item_id") or "").strip()
    try:
        delta = int((request.form.get("delta_qty") or "0").strip() or 0)
    except Exception:
        delta = 0
    reason = (request.form.get("reason") or "").strip()
    if not item_id or delta == 0:
        flash("Select item and enter non-zero adjustment", "warning")
        return redirect(url_for("inventory"))
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    user = session.get("username") or "SYSTEM"
    try:
        cur.execute(
            "UPDATE inventory_items SET qty_on_hand=COALESCE(qty_on_hand,0)+?, updated_at=?, updated_by=? WHERE id=?",
            (delta, now, user, item_id),
        )
        cur.execute(
            "INSERT INTO inventory_txn (item_id, delta_qty, reason, created_at, created_by) VALUES (?,?,?,?,?)",
            (item_id, delta, reason, now, user),
        )
        db.commit()
        flash("Inventory adjusted", "success")
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass
        flash("Failed to adjust inventory (check logs)", "danger")
    return redirect(url_for("inventory"))


