@app.route("/analytics")
@login_required
@role_required("admin", "nurse", "doctor")
def analytics_dashboard():
    cur = get_db().cursor()
    # Visits in last 24h
    try:
        rows = cur.execute("""
            SELECT strftime('%Y-%m-%d %H:00', created_at) AS hr, COUNT(*) AS cnt
            FROM visits
            WHERE created_at >= datetime('now','-24 hours')
            GROUP BY hr
            ORDER BY hr
            """).fetchall()
    except Exception:
        rows = []
    buckets = []
    total = 0
    for r in rows or []:
        try:
            hr = r["hr"]
            cnt = int(r["cnt"])
        except Exception:
            hr = r[0]
            cnt = int(r[1]) if len(r) > 1 else 0
        buckets.append({"hour": hr, "count": cnt})
        total += cnt

    # Door-to-doctor: first clinical order time - created_at (minutes)
    avg_d2d = None
    try:
        d2d_rows = cur.execute("""
            SELECT AVG((julianday(min(co.created_at)) - julianday(v.created_at)) * 24 * 60) AS avg_min
            FROM visits v
            JOIN clinical_orders co ON co.visit_id = v.visit_id
            WHERE v.created_at >= datetime('now','-24 hours')
            GROUP BY v.visit_id
            """).fetchall()
        # d2d_rows is list of averages per visit; take avg again
        vals = []
        for r in d2d_rows or []:
            try:
                vals.append(float(r[0]))
            except Exception:
                pass
        if vals:
            avg_d2d = sum(vals) / len(vals)
    except Exception:
        avg_d2d = None

    return render_template(
        "analytics.html",
        buckets=buckets,
        total=total,
        avg_d2d=avg_d2d,
        fts_enabled=(
            sqlite_fts_available("patients_fts") if DB_ENGINE != "postgres" else True
        ),
    )


