# --- HL7 export (minimal) ---
@app.route("/visit/<visit_id>/export_hl7")
@login_required
def export_hl7(visit_id):
    cur = get_db().cursor()
    v = cur.execute(
        """
        SELECT v.*, p.name, p.id_number, p.dob, p.sex, p.phone
        FROM visits v JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
        """,
        (visit_id,),
    ).fetchone()
    if not v:
        abort(404)

    def _g(row, k, default=""):
        try:
            return row[k] or default
        except Exception:
            return default

    def _hl7_ts(ts: str):
        ts = (ts or "").replace("-", "").replace(":", "").replace(" ", "")
        return ts[:14] if ts else ""

    now = _hl7_ts(datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
    mrn = _g(v, "id_number")
    pname = _g(v, "name")
    dob = (_g(v, "dob") or "").replace("-", "")
    sex = (_g(v, "sex") or "").upper()[:1]
    created = _hl7_ts(_g(v, "created_at"))

    # Minimal ADT^A04
    msh = f"MSH|^~\\&|EDDT|ED|HIS|HIS|{now}||ADT^A04|{visit_id}|P|2.3"
    pid = f"PID|||{mrn}||{pname}||{dob}|{sex}|||"  # basic
    pv1 = f"PV1||E|{_g(v,'location')}^{_g(v,'bed_no')}||||||||||||||||{visit_id}|||||||||||||||||||||||||{created}"

    msg = "\r".join([msh, pid, pv1]) + "\r"
    fn = f"HL7_{visit_id}.hl7"
    return Response(
        msg,
        mimetype="text/plain",
        headers={"Content-Disposition": f"attachment; filename={fn}"},
    )


