def _append_patient_search_sql(
    sql, params, query, patient_alias="p", visit_alias="v", extra_columns=None
):
    """Append a broad patient/visit text search to existing SQL + params.
    Covers: name, MRN, ID number, case no, phone, plus optional extra columns.
    """
    q = (query or "").strip()
    if not q:
        return sql, params

    like = f"%{q}%"
    cols = [
        f"{patient_alias}.name",
        f"{patient_alias}.mrn",
        f"{patient_alias}.id_number",
        f"{visit_alias}.visit_id",
        f"{patient_alias}.phone",
    ]
    for c in extra_columns or []:
        if c and c not in cols:
            cols.append(c)

    op = "ILIKE" if DB_ENGINE == "postgres" else "LIKE"
    conds = [f"COALESCE({c},'') {op} ?" for c in cols]
    sql += " AND (" + " OR ".join(conds) + ")"
    params.extend([like] * len(cols))
    return sql, params


