# ------------------------------------------------------------
# Single Session Management persisted in users table (token + IP)
# ------------------------------------------------------------
try:
    _FINAL_SINGLE_SESSION_USERS_READY = False
    _orig_single_session_registry_set = _single_session_registry_set
    _orig_single_session_clear_registry = _single_session_clear_registry
    _orig_single_session_check_current = _single_session_check_current

    def _final_get_client_ip():
        try:
            return (security.get_client_ip(request) or "").strip()
        except Exception:
            try:
                return (request.headers.get("X-Forwarded-For", "").split(",")[0].strip() or request.remote_addr or "").strip()
            except Exception:
                return ""

    def _ensure_single_session_users_columns():
        global _FINAL_SINGLE_SESSION_USERS_READY
        if _FINAL_SINGLE_SESSION_USERS_READY:
            return
        try:
            with app.app_context():
                ensure_column("users", "active_session_token", "TEXT")
                ensure_column("users", "active_session_ip", "TEXT")
                ensure_column("users", "active_session_updated_at", "TEXT")
                ensure_column("users", "active_session_user_agent", "TEXT")
            _FINAL_SINGLE_SESSION_USERS_READY = True
        except Exception as _e:
            try:
                _log_noncritical_exception("ensure users single-session columns failed", _e)
            except Exception:
                pass

    def _user_table_active_session_token(user_id):
        if not user_id:
            return ""
        try:
            _ensure_single_session_users_columns()
            db = get_db()
            cur = db.cursor()
            row = cur.execute(
                "SELECT active_session_token FROM users WHERE id=? LIMIT 1",
                (user_id,),
            ).fetchone()
            if not row:
                return ""
            try:
                return (row["active_session_token"] or "").strip()
            except Exception:
                return (row[0] or "").strip()
        except Exception:
            return ""

    def _single_session_registry_set(user_id, username, session_token):
        _orig_single_session_registry_set(user_id, username, session_token)
        if not user_id or not session_token:
            return
        try:
            _ensure_single_session_users_columns()
            db = get_db()
            now_s = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            db.execute(
                "UPDATE users SET active_session_token=?, active_session_ip=?, active_session_updated_at=?, active_session_user_agent=? WHERE id=?",
                (
                    str(session_token),
                    _final_get_client_ip(),
                    now_s,
                    (request.headers.get("User-Agent") or "")[:500] if request else "",
                    user_id,
                ),
            )
            db.commit()
        except Exception as _e:
            try:
                db.rollback()
            except Exception:
                pass
            try:
                _log_noncritical_exception("user-table single-session set failed", _e)
            except Exception:
                pass

    def _single_session_clear_registry(user_id=None, session_token=None):
        _orig_single_session_clear_registry(user_id, session_token)
        user_id = user_id or session.get("user_id")
        if not user_id:
            return
        try:
            _ensure_single_session_users_columns()
            db = get_db()
            if session_token:
                db.execute(
                    "UPDATE users SET active_session_token=NULL, active_session_ip=NULL, active_session_updated_at=NULL, active_session_user_agent=NULL WHERE id=? AND COALESCE(active_session_token,'')=?",
                    (user_id, str(session_token)),
                )
            else:
                db.execute(
                    "UPDATE users SET active_session_token=NULL, active_session_ip=NULL, active_session_updated_at=NULL, active_session_user_agent=NULL WHERE id=?",
                    (user_id,),
                )
            db.commit()
        except Exception as _e:
            try:
                db.rollback()
            except Exception:
                pass
            try:
                _log_noncritical_exception("user-table single-session clear failed", _e)
            except Exception:
                pass

    def _single_session_check_current(force=False):
        user_id = session.get("user_id")
        token = (session.get("_session_token") or "").strip()
        if not user_id or not token:
            return _orig_single_session_check_current(force=force)
        try:
            table_token = _user_table_active_session_token(user_id)
            if table_token and table_token != token:
                return False
            if not table_token:
                try:
                    _single_session_registry_set(user_id, session.get("username"), token)
                except Exception:
                    pass
        except Exception:
            pass
        return _orig_single_session_check_current(force=force)
except Exception as _single_session_users_patch_exc:
    try:
        _log_noncritical_exception("FINAL single-session users-table patch failed", _single_session_users_patch_exc)
    except Exception:
        pass

# ------------------------------------------------------------
# Reports override: accurate daily counts for Admission / Cancelled
# ------------------------------------------------------------
try:
    @login_required
    def _reports_patch_final_v1():
        dfrom = (request.args.get("date_from", "") or "").strip()
        dto = (request.args.get("date_to", "") or "").strip()

        if dfrom and not dto:
            dto = dfrom
        elif dto and not dfrom:
            dfrom = dto

        if not dfrom or not dto:
            today = datetime.today().date()
            dfrom = (today - timedelta(days=6)).strftime("%Y-%m-%d")
            dto = today.strftime("%Y-%m-%d")

        db = get_db()
        cur = db.cursor()

        def _scalar(_sql, _params=()):
            row = cur.execute(_sql, _params).fetchone()
            if row is None:
                return 0
            try:
                return int(row[0] or 0)
            except Exception:
                try:
                    if hasattr(row, 'keys'):
                        _keys = list(row.keys())
                        if _keys:
                            return int((row[_keys[0]] or 0))
                except Exception:
                    pass
            try:
                return int(row)
            except Exception:
                return 0

        total_visits = _scalar(
            "SELECT COUNT(*) FROM visits WHERE date(created_at) BETWEEN date(?) AND date(?)",
            (dfrom, dto),
        )

        open_visits = _scalar(
            "SELECT COUNT(*) FROM visits WHERE UPPER(TRIM(COALESCE(status,''))) IN ('OPEN','REGISTERED') AND date(created_at) BETWEEN date(?) AND date(?)",
            (dfrom, dto),
        )

        active_visits = _scalar(
            "SELECT COUNT(*) FROM visits WHERE UPPER(TRIM(COALESCE(status,''))) NOT IN ('DISCHARGED','TRANSFERRED','LAMA','EXPIRED','CANCELLED','CLOSED','VISIT_COMPLETED','COMPLETED') AND date(created_at) BETWEEN date(?) AND date(?)",
            (dfrom, dto),
        )

        # Accurate event-based metrics
        try:
            ensure_admission_orders_schema()
        except Exception:
            pass

        admitted_visits = _scalar(
            "SELECT COUNT(DISTINCT visit_id) FROM admission_orders WHERE admitted_at IS NOT NULL AND TRIM(COALESCE(admitted_at,''))<>'' AND UPPER(TRIM(COALESCE(status,''))) <> 'CANCELLED' AND date(admitted_at) BETWEEN date(?) AND date(?)",
            (dfrom, dto),
        )

        cancelled_visits = _scalar(
            "SELECT COUNT(*) FROM visits WHERE TRIM(COALESCE(cancelled_at,''))<>'' AND date(cancelled_at) BETWEEN date(?) AND date(?)",
            (dfrom, dto),
        )

        lama_visits = _scalar(
            "SELECT COUNT(*) FROM visits WHERE UPPER(TRIM(COALESCE(status,'')))='LAMA' AND date(created_at) BETWEEN date(?) AND date(?)",
            (dfrom, dto),
        )

        lab_requests = _scalar(
            "SELECT COUNT(*) FROM lab_requests WHERE date(requested_at) BETWEEN date(?) AND date(?)",
            (dfrom, dto),
        )
        radiology_requests = _scalar(
            "SELECT COUNT(*) FROM radiology_requests WHERE date(requested_at) BETWEEN date(?) AND date(?)",
            (dfrom, dto),
        )

        visit_status_counts = {}
        try:
            rows = cur.execute(
                """
                SELECT UPPER(TRIM(COALESCE(status,''))) AS status_norm, COUNT(*) AS c
                FROM visits
                WHERE date(created_at) BETWEEN date(?) AND date(?)
                GROUP BY UPPER(TRIM(COALESCE(status,'')))
                """,
                (dfrom, dto),
            ).fetchall()
            for r in rows or []:
                key = (_safe_row_get(r, "status_norm", "UNKNOWN") or "UNKNOWN").upper()
                visit_status_counts[key] = int(_safe_row_get(r, "c", 0) or 0)
            _open_c = int(visit_status_counts.get("OPEN", 0) or 0) + int(visit_status_counts.get("REGISTERED", 0) or 0)
            if _open_c:
                visit_status_counts["REGISTERED"] = _open_c
                visit_status_counts["OPEN"] = _open_c
            _vp = int(visit_status_counts.get("VISIT_PROGRESS", 0) or 0) + int(visit_status_counts.get("IN_TREATMENT", 0) or 0)
            if _vp:
                visit_status_counts["VISIT_PROGRESS"] = _vp
                visit_status_counts["IN_TREATMENT"] = _vp
            _vc = int(visit_status_counts.get("VISIT_COMPLETED", 0) or 0) + int(visit_status_counts.get("COMPLETED", 0) or 0)
            if _vc:
                visit_status_counts["VISIT_COMPLETED"] = _vc
                visit_status_counts["COMPLETED"] = _vc
        except Exception:
            visit_status_counts = {}

        # Keep dashboard status badge in sync with event-based admission figure
        visit_status_counts["ADMITTED"] = admitted_visits
        visit_status_counts["CANCELLED"] = cancelled_visits

        lab_status_counts = {}
        try:
            rows = cur.execute(
                "SELECT status, COUNT(*) AS c FROM lab_requests WHERE date(requested_at) BETWEEN date(?) AND date(?) GROUP BY status",
                (dfrom, dto),
            ).fetchall()
            for r in rows or []:
                key = (_safe_row_get(r, "status", "UNKNOWN") or "UNKNOWN").upper()
                lab_status_counts[key] = int(_safe_row_get(r, "c", 0) or 0)
        except Exception:
            lab_status_counts = {}

        rad_status_counts = {}
        try:
            rows = cur.execute(
                "SELECT status, COUNT(*) AS c FROM radiology_requests WHERE date(requested_at) BETWEEN date(?) AND date(?) GROUP BY status",
                (dfrom, dto),
            ).fetchall()
            for r in rows or []:
                key = (_safe_row_get(r, "status", "UNKNOWN") or "UNKNOWN").upper()
                rad_status_counts[key] = int(_safe_row_get(r, "c", 0) or 0)
        except Exception:
            rad_status_counts = {}

        v_rows = cur.execute(
            "SELECT date(created_at) AS d, COUNT(*) AS c FROM visits WHERE date(created_at) BETWEEN date(?) AND date(?) GROUP BY date(created_at) ORDER BY d",
            (dfrom, dto),
        ).fetchall()
        l_rows = cur.execute(
            "SELECT date(requested_at) AS d, COUNT(*) AS c FROM lab_requests WHERE date(requested_at) BETWEEN date(?) AND date(?) GROUP BY date(requested_at) ORDER BY d",
            (dfrom, dto),
        ).fetchall()
        r_rows = cur.execute(
            "SELECT date(requested_at) AS d, COUNT(*) AS c FROM radiology_requests WHERE date(requested_at) BETWEEN date(?) AND date(?) GROUP BY date(requested_at) ORDER BY d",
            (dfrom, dto),
        ).fetchall()

        def _d_to_str(v):
            try:
                if hasattr(v, "strftime"):
                    return v.strftime("%Y-%m-%d")
            except Exception:
                pass
            return str(v) if v is not None else ""

        v_map = {_d_to_str(_safe_row_get(row, "d", "")): int(_safe_row_get(row, "c", 0) or 0) for row in v_rows or []}
        l_map = {_d_to_str(_safe_row_get(row, "d", "")): int(_safe_row_get(row, "c", 0) or 0) for row in l_rows or []}
        r_map = {_d_to_str(_safe_row_get(row, "d", "")): int(_safe_row_get(row, "c", 0) or 0) for row in r_rows or []}

        lama_rows = cur.execute(
            "SELECT date(created_at) AS d, COUNT(*) AS c FROM visits WHERE UPPER(TRIM(COALESCE(status,'')))='LAMA' AND date(created_at) BETWEEN date(?) AND date(?) GROUP BY date(created_at) ORDER BY d",
            (dfrom, dto),
        ).fetchall()
        lama_map = {_d_to_str(_safe_row_get(row, "d", "")): int(_safe_row_get(row, "c", 0) or 0) for row in lama_rows or []}

        admitted_rows = []
        try:
            admitted_rows = cur.execute(
                "SELECT date(admitted_at) AS d, COUNT(DISTINCT visit_id) AS c FROM admission_orders WHERE admitted_at IS NOT NULL AND TRIM(COALESCE(admitted_at,''))<>'' AND UPPER(TRIM(COALESCE(status,''))) <> 'CANCELLED' AND date(admitted_at) BETWEEN date(?) AND date(?) GROUP BY date(admitted_at) ORDER BY d",
                (dfrom, dto),
            ).fetchall()
        except Exception:
            admitted_rows = []
        admitted_map = {_d_to_str(_safe_row_get(row, "d", "")): int(_safe_row_get(row, "c", 0) or 0) for row in admitted_rows or []}

        cancelled_rows = cur.execute(
            "SELECT date(cancelled_at) AS d, COUNT(*) AS c FROM visits WHERE TRIM(COALESCE(cancelled_at,''))<>'' AND date(cancelled_at) BETWEEN date(?) AND date(?) GROUP BY date(cancelled_at) ORDER BY d",
            (dfrom, dto),
        ).fetchall()
        cancelled_map = {_d_to_str(_safe_row_get(row, "d", "")): int(_safe_row_get(row, "c", 0) or 0) for row in cancelled_rows or []}

        daily = []
        try:
            start_dt = datetime.strptime(dfrom, "%Y-%m-%d")
            end_dt = datetime.strptime(dto, "%Y-%m-%d")
            d = start_dt
            while d <= end_dt:
                ds = d.strftime("%Y-%m-%d")
                daily.append(
                    {
                        "date": ds,
                        "visits": v_map.get(ds, 0),
                        "admitted": admitted_map.get(ds, 0),
                        "lama": lama_map.get(ds, 0),
                        "cancelled": cancelled_map.get(ds, 0),
                        "lab": l_map.get(ds, 0),
                        "rad": r_map.get(ds, 0),
                    }
                )
                d += timedelta(days=1)
        except Exception:
            daily = []

        mrd_stats = {"pending_visits": 0, "pending_labs": 0, "pending_rads": 0}
        if has_perm("mrd_reentry_mark"):
            try:
                ensure_mrd_reentry_schema()
                lab_tot = {}
                for row in cur.execute(
                    """
                    SELECT lr.visit_id AS visit_id, COUNT(*) AS cnt
                    FROM lab_requests lr
                    JOIN visits v ON v.visit_id = lr.visit_id
                    WHERE substr(v.created_at,1,10) BETWEEN ? AND ?
                    GROUP BY lr.visit_id
                    """,
                    (dfrom, dto),
                ).fetchall():
                    lab_tot[str(_safe_row_get(row, "visit_id", ""))] = int(_safe_row_get(row, "cnt", 0) or 0)

                rad_tot = {}
                for row in cur.execute(
                    """
                    SELECT rr.visit_id AS visit_id, COUNT(*) AS cnt
                    FROM radiology_requests rr
                    JOIN visits v ON v.visit_id = rr.visit_id
                    WHERE substr(v.created_at,1,10) BETWEEN ? AND ?
                    GROUP BY rr.visit_id
                    """,
                    (dfrom, dto),
                ).fetchall():
                    rad_tot[str(_safe_row_get(row, "visit_id", ""))] = int(_safe_row_get(row, "cnt", 0) or 0)

                marks = {}
                for row in cur.execute(
                    """
                    SELECT m.visit_id AS visit_id, m.entity_type AS entity_type,
                           SUM(CASE WHEN m.entered_at IS NOT NULL AND m.entered_at<>'' THEN 1 ELSE 0 END) AS entered_cnt,
                           SUM(CASE WHEN m.verified_at IS NOT NULL AND m.verified_at<>'' THEN 1 ELSE 0 END) AS verified_cnt
                    FROM mrd_reentry_marks m
                    JOIN visits v ON v.visit_id = m.visit_id
                    WHERE substr(v.created_at,1,10) BETWEEN ? AND ?
                      AND m.entity_type IN ('lab_request','radiology_request')
                    GROUP BY m.visit_id, m.entity_type
                    """,
                    (dfrom, dto),
                ).fetchall():
                    vid = str(_safe_row_get(row, "visit_id", ""))
                    et = str(_safe_row_get(row, "entity_type", ""))
                    marks[(vid, et)] = (
                        int(_safe_row_get(row, "entered_cnt", 0) or 0),
                        int(_safe_row_get(row, "verified_cnt", 0) or 0),
                    )

                pending_visits = set()
                pending_labs = 0
                pending_rads = 0

                for vid, tot in lab_tot.items():
                    ent, ver = marks.get((vid, "lab_request"), (0, 0))
                    if ent < tot or ver < tot:
                        pending_visits.add(vid)
                        pending_labs += max(0, tot - ver)

                for vid, tot in rad_tot.items():
                    ent, ver = marks.get((vid, "radiology_request"), (0, 0))
                    if ent < tot or ver < tot:
                        pending_visits.add(vid)
                        pending_rads += max(0, tot - ver)

                mrd_stats["pending_visits"] = len(pending_visits)
                mrd_stats["pending_labs"] = pending_labs
                mrd_stats["pending_rads"] = pending_rads
            except Exception:
                pass

        return render_template_string(
            REPORTS_TEMPLATE,
            dfrom=dfrom,
            dto=dto,
            total_visits=total_visits,
            open_visits=open_visits,
            active_visits=active_visits,
            admitted_visits=admitted_visits,
            lama_visits=lama_visits,
            cancelled_visits=cancelled_visits,
            lab_requests=lab_requests,
            radiology_requests=radiology_requests,
            daily=daily,
            visit_status_counts=visit_status_counts,
            lab_status_counts=lab_status_counts,
            rad_status_counts=rad_status_counts,
            mrd_stats=mrd_stats,
        )

    app.view_functions["reports"] = _reports_patch_final_v1
except Exception as _reports_patch_exc:
    try:
        _log_noncritical_exception("FINAL reports override patch failed", _reports_patch_exc)
    except Exception:
        pass

# ------------------------------------------------------------
# Live Chat UI override: remove Case No field + better media layout
# ------------------------------------------------------------
try:
    _FINAL_CHAT_TEMPLATE = _final_patch_textwrap.dedent("""
    {% extends "base.html" %}
    {% block content %}
    <style>
      .staff-chat-shell .chat-card{height:calc(100vh - 220px);min-height:64vh;}
      .staff-chat-shell .chat-messages{background:#f8fafc;padding:.85rem;}
      .staff-chat-shell .chat-row{display:flex;margin-bottom:.85rem;}
      .staff-chat-shell .chat-bubble{width:min(100%,780px);background:#fff;border:1px solid #dbe3ee;border-radius:16px;padding:.75rem .85rem;box-shadow:0 4px 14px rgba(15,23,42,.05);}
      .staff-chat-shell .chat-row.mine{justify-content:flex-end;}
      .staff-chat-shell .chat-row.mine .chat-bubble{background:#eef6ff;border-color:#cfe2ff;}
      .staff-chat-shell .chat-meta{display:flex;flex-wrap:wrap;align-items:center;gap:.4rem .5rem;margin-bottom:.35rem;}
      .staff-chat-shell .chat-text{white-space:pre-wrap;word-break:break-word;line-height:1.5;}
      .staff-chat-shell .chat-media-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:.65rem;margin-top:.65rem;}
      .staff-chat-shell .chat-media-card{border:1px solid #e5e7eb;border-radius:14px;background:#fff;overflow:hidden;}
      .staff-chat-shell .chat-media-card img,.staff-chat-shell .chat-media-card video{width:100%;display:block;max-height:360px;object-fit:contain;background:#000;}
      .staff-chat-shell .chat-media-actions{display:flex;justify-content:space-between;align-items:center;gap:.5rem;flex-wrap:wrap;}
      .staff-chat-shell .chat-media-open-btn{white-space:nowrap;}
      .staff-chat-shell .chat-media-card .meta{padding:.45rem .6rem;background:#f8fafc;border-top:1px solid #eef2f7;}
      .staff-chat-shell .chat-media-link{display:block;text-decoration:none;cursor:pointer;}
      .staff-chat-shell .chat-toolbar-note{font-size:.84rem;color:#6b7280;}
      .staff-chat-shell #emoji-panel{display:none;right:12px;bottom:96px;max-width:320px;z-index:2100;}
      .staff-chat-shell .chat-activity-box{max-height:35vh;overflow-y:auto;}
      .staff-chat-shell .chat-search-panel{border-top:1px solid #eef2f7;padding-top:.75rem;margin-top:.75rem;}
      @media (max-width: 991.98px){
        .staff-chat-shell .chat-card{height:auto;min-height:58vh;}
      }
    </style>

    <div class="staff-chat-shell">
      <h4 class="mb-3">Live Chat - Staff</h4>

      <div class="row g-3">
        <div class="col-lg-8">
          <div class="card bg-white mb-3 chat-card d-flex flex-column position-relative">
            <div class="card-header py-2">
              <div class="d-flex flex-wrap align-items-end gap-2">
                <div>
                  <label class="form-label small mb-0">Room</label>
                  <select id="chat-room" class="form-select form-select-sm">
                    <option value="general">General</option>
                    <option value="triage">Triage</option>
                    <option value="lab">Lab</option>
                    <option value="radiology">Radiology</option>
                    <option value="reception">Reception</option>
                    <option value="inpatient_billing">Inpatient Billing</option>
                    <option value="doctor">Physicians</option>
                  </select>
                </div>

                <div class="ms-auto d-flex align-items-center gap-2 flex-wrap justify-content-end">
                  <button class="btn btn-sm btn-outline-secondary" id="chat-search-toggle" type="button" title="Search in chat">🔎 Search</button>
                  <div class="small text-muted">Last update: <span id="chat-last-update">-</span></div>
                  {% if session.get('role') == 'admin' %}
                  <button class="btn btn-sm btn-outline-danger" id="chat-clear-btn" type="button" title="Clear current room">Clear</button>
                  {% endif %}
                </div>
              </div>

              <div id="chat-search-panel" class="chat-search-panel d-none">
                <div class="input-group input-group-sm">
                  <span class="input-group-text">Search</span>
                  <input type="text" id="chat-search-q" class="form-control" placeholder="Search messages in this room">
                  <button class="btn btn-outline-primary" type="button" id="chat-search-btn">Go</button>
                  <button class="btn btn-outline-secondary" type="button" id="chat-search-close">Close</button>
                </div>
                <div class="small text-muted mt-1" id="chat-search-hint"></div>
              </div>
            </div>

            <div class="card-body chat-messages flex-grow-1 overflow-auto" id="chat-box">
              <div class="text-muted small">Loading messages...</div>
            </div>

            <div id="emoji-panel" class="border rounded bg-white shadow-sm p-2 position-absolute">
              <div class="d-flex flex-wrap gap-1">
                {% set emojis = ["😀","😁","😂","🤣","😊","😍","😢","😭","😡","😷","🤒","🤕","👍","👎","✅","❌","⚠️","📌","📞","🩺","💊","🧪","🩻","🧾","🧠","🫁","🫀"] %}
                {% for e in emojis %}
                  <button class="btn btn-sm btn-light emoji-btn" type="button" data-emoji="{{ e }}">{{ e }}</button>
                {% endfor %}
              </div>
              <div class="small text-muted mt-2">Tip: you can also use your phone/OS emoji keyboard.</div>
            </div>

            <div class="card-footer">
              <div class="input-group">
                <button class="btn btn-outline-secondary" type="button" id="chat-emoji-btn" title="Emoji">😊</button>
                <button class="btn btn-outline-secondary" type="button" id="chat-attach-btn" title="Attach image/video">📎</button>
                <input type="file" id="chat-file" accept="image/*,video/*" style="display:none;">
                <input type="text" id="chat-input" class="form-control" placeholder="Type your message and press Enter or click Send ...">
                <button class="btn btn-primary" id="chat-send-btn">Send</button>
              </div>
              <div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mt-2">
                <div class="chat-toolbar-note">Room is visible to all staff. Images and videos open in a larger preview or a new tab.</div>
                <div class="small text-muted" id="chat-attach-name"></div>
              </div>
            </div>
          </div>
        </div>

        <div class="col-lg-4">
          <div class="card bg-white mb-3">
            <div class="card-header py-2 d-flex justify-content-between align-items-center">
              <span class="small fw-bold">Users activity</span>
              <button class="btn btn-sm btn-outline-secondary btn-refresh-activity" type="button">Refresh</button>
            </div>
            <div class="card-body small chat-activity-box" id="chat-activity-box">
              <div class="text-muted small">Loading activity...</div>
            </div>
          </div>

          <div class="alert alert-info small mb-0">
            <div class="fw-bold mb-1">Tips:</div>
            <ul class="mb-0 ps-3">
              <li>Choose a room first to organize the discussion.</li>
              <li>Images and videos are shown in a clearer preview card.</li>
              <li>Click any media preview to open it larger.</li>
              <li>Use <strong>Search</strong> to find any text in the current room.</li>
            </ul>
          </div>
        </div>
      </div>
    </div>

    <div class="modal fade" id="chatMediaModal" tabindex="-1" aria-hidden="true">
      <div class="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable">
        <div class="modal-content">
          <div class="modal-header">
            <h5 class="modal-title" id="chatMediaModalTitle">Media Preview</h5>
            <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
          </div>
          <div class="modal-body text-center" id="chatMediaModalBody"></div>
          <div class="modal-footer">
            <a href="#" class="btn btn-primary" target="_blank" id="chatMediaModalOpenLink">Open in new tab</a>
            <button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Close</button>
          </div>
        </div>
      </div>
    </div>

    <script>
    document.addEventListener("DOMContentLoaded", function(){
      const currentUsername = {{ (session.get('username') or '')|tojson }};
      const chatBox = document.getElementById("chat-box");
      const chatInput = document.getElementById("chat-input");
      const sendBtn = document.getElementById("chat-send-btn");
      const roomSelect = document.getElementById("chat-room");
      const lastUpdateSpan = document.getElementById("chat-last-update");
      const activityBox = document.getElementById("chat-activity-box");
      const refreshActivityBtns = document.querySelectorAll(".btn-refresh-activity");
      const attachBtn = document.getElementById("chat-attach-btn");
      const fileInput = document.getElementById("chat-file");
      const attachName = document.getElementById("chat-attach-name");
      const emojiBtn = document.getElementById("chat-emoji-btn");
      const emojiPanel = document.getElementById("emoji-panel");
      const clearBtn = document.getElementById("chat-clear-btn");
      const searchToggleBtn = document.getElementById("chat-search-toggle");
      const searchPanel = document.getElementById("chat-search-panel");
      const searchQ = document.getElementById("chat-search-q");
      const searchBtn = document.getElementById("chat-search-btn");
      const searchCloseBtn = document.getElementById("chat-search-close");
      const searchHint = document.getElementById("chat-search-hint");
      const mediaModalEl = document.getElementById("chatMediaModal");
      const mediaModalTitle = document.getElementById("chatMediaModalTitle");
      const mediaModalBody = document.getElementById("chatMediaModalBody");
      const mediaModalOpenLink = document.getElementById("chatMediaModalOpenLink");
      const mediaModal = (window.bootstrap && mediaModalEl) ? new window.bootstrap.Modal(mediaModalEl) : null;

      let lastId = 0;
      let lastAt = "";
      let currentRoom = (roomSelect.value || "general").toLowerCase();
      let inSearch = false;
      let pollTimer = null;
      let es = null;

      function escapeHtml(str) {
        str = (str === undefined || str === null) ? "" : String(str);
        return str
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/\"/g, "&quot;")
          .replace(/'/g, "&#039;");
      }

      function normalizeRoom(r){
        r = (r || "general").toString().trim().toLowerCase();
        return r || "general";
      }

      function scrollChatToBottom(){
        chatBox.scrollTop = chatBox.scrollHeight;
      }

      function formatTimestamp(ts){
        return ts || "";
      }

      function renderAttachment(att){
        if (!att || !att.url) return "";
        const rawUrl = att.url || "";
        const url = escapeHtml(rawUrl);
        const orig = escapeHtml(att.original_name || att.filename || "attachment");
        const kind = (att.kind || "").toLowerCase();
        if (kind === "image") {
          return `
            <div class="chat-media-card">
              <button type="button" class="chat-media-link btn btn-link p-0 border-0 w-100 text-start" data-preview="1" data-kind="image" data-url="${url}" data-name="${orig}" aria-label="Preview ${orig}">
                <img src="${url}" alt="${orig}" loading="lazy" onerror="this.closest('.chat-media-card').classList.add('border','border-danger-subtle');">
              </button>
              <div class="meta small text-muted">
                <div class="chat-media-actions">
                  <span class="text-truncate">${orig}</span>
                  <span class="d-flex gap-2 flex-wrap">
                    <button type="button" class="btn btn-sm btn-outline-primary chat-media-link" data-preview="1" data-kind="image" data-url="${url}" data-name="${orig}">Preview</button>
                    <a href="${url}" target="_blank" rel="noopener" class="chat-media-open-btn">Open</a>
                  </span>
                </div>
              </div>
            </div>`;
        }
        if (kind === "video") {
          const mime = escapeHtml(att.mime_type || "video/mp4");
          return `
            <div class="chat-media-card">
              <div class="w-100">
                <video controls playsinline preload="metadata" style="cursor:default;" onerror="this.closest('.chat-media-card').classList.add('border','border-danger-subtle');">
                  <source src="${url}" type="${mime}">
                  Your browser cannot play this video.
                </video>
              </div>
              <div class="meta small text-muted">
                <div class="chat-media-actions">
                  <span class="text-truncate">${orig}</span>
                  <span class="d-flex gap-2 flex-wrap">
                    <button type="button" class="btn btn-sm btn-outline-primary chat-media-link" data-preview="1" data-kind="video" data-url="${url}" data-name="${orig}" data-mime="${mime}">Preview</button>
                    <a href="${url}" target="_blank" rel="noopener" class="chat-media-open-btn">Open</a>
                  </span>
                </div>
              </div>
            </div>`;
        }
        return `<div class="chat-media-card"><div class="meta small d-flex justify-content-between gap-2"><span class="text-truncate">${orig}</span><a href="${url}" target="_blank" rel="noopener">Open</a></div></div>`;
      }

      function appendMessage(msg, highlight){
        const whoUser = (msg.username || "").toString();
        const isMine = currentUsername && whoUser && currentUsername === whoUser;
        const row = document.createElement("div");
        row.className = "chat-row" + (isMine ? " mine" : "");

        const roomTag = msg.room && msg.room !== "general"
          ? '<span class="badge bg-secondary-subtle text-secondary border border-secondary">' + escapeHtml(msg.room) + '</span>'
          : '';
        const who = escapeHtml(msg.display_name || msg.username || "User");
        const when = escapeHtml(formatTimestamp(msg.created_at));
        const text = (msg.message || "").trim();
        const attachments = (msg.attachments && msg.attachments.length)
          ? '<div class="chat-media-grid">' + msg.attachments.map(renderAttachment).join("") + '</div>'
          : '';

        row.innerHTML = `
          <div class="chat-bubble${highlight ? ' border-primary' : ''}">
            <div class="chat-meta">
              ${roomTag}
              <span class="badge bg-light text-dark border">${who}</span>
              <span class="small text-muted">${when}</span>
            </div>
            ${text ? '<div class="chat-text">' + escapeHtml(text) + '</div>' : ''}
            ${attachments}
          </div>`;
        chatBox.appendChild(row);
      }

      function updateLastUpdate(ts){
        lastAt = ts || lastAt;
        if (lastAt) lastUpdateSpan.textContent = lastAt;
      }

      async function fetchMessages(initial){
        if (inSearch) return;
        const params = new URLSearchParams();
        if (lastId && !initial) params.append("after_id", String(lastId));
        params.append("room", currentRoom);
        params.append("_ts", String(Date.now()));
        try {
          const res = await fetch("/chat/messages?" + params.toString(), {cache:"no-store", credentials:"same-origin"});
          const data = await res.json();
          if (!data.ok) return;

          if (initial) {
            chatBox.innerHTML = "";
            lastId = 0;
          }

          const msgs = data.messages || [];
          if (initial && !msgs.length) {
            chatBox.innerHTML = '<div class="text-muted small">No messages yet.</div>';
            return;
          }

          if (msgs.length) {
            const atBottom = Math.abs(chatBox.scrollHeight - chatBox.scrollTop - chatBox.clientHeight) < 80;
            msgs.forEach((m, idx) => {
              appendMessage(m, !initial && idx === msgs.length - 1);
              const mid = parseInt(m.id || 0, 10);
              if (!isNaN(mid) && mid > lastId) lastId = mid;
              if (m.created_at) updateLastUpdate(m.created_at);
            });
            if (atBottom || initial) scrollChatToBottom();
          }
        } catch (err) {
          console.error(err);
        }
      }

      function resetAttachment(){
        try { fileInput.value = ""; } catch(e) {}
        attachName.textContent = "";
      }

      async function sendMessage(){
        const text = (chatInput.value || "").trim();
        const hasFile = fileInput.files && fileInput.files.length > 0;
        if (!text && !hasFile) return;

        if (hasFile) {
          const f = fileInput.files[0];
          if (f && f.size && f.size > (50 * 1024 * 1024)) {
            alert("Attachment too large. Max 50 MB.");
            resetAttachment();
            return;
          }
        }

        const form = new FormData();
        form.append("room", currentRoom);
        form.append("visit_id", "");
        form.append("message", text);
        if (hasFile) form.append("file", fileInput.files[0]);

        try {
          sendBtn.disabled = true;
          const res = await fetch("/chat/send?_ts=" + Date.now(), {
            method: "POST",
            headers: {"X-CSRFToken": "{{ csrf_token() }}"},
            body: form,
            cache: "no-store",
            credentials: "same-origin"
          });
          let data = null;
          try { data = await res.json(); } catch(e) {}
          if (!res.ok || !data || !data.ok) {
            alert((data && data.error) ? data.error : "Failed to send message");
            return;
          }
          chatInput.value = "";
          resetAttachment();
          await fetchMessages(false);
          scrollChatToBottom();
          fetchActivity();
        } catch (err) {
          console.error(err);
          alert("Error sending message");
        } finally {
          sendBtn.disabled = false;
        }
      }

      chatInput.addEventListener("keydown", function(e){
        if (e.key === "Enter" && !e.shiftKey) {
          e.preventDefault();
          sendMessage();
        }
      });
      sendBtn.addEventListener("click", sendMessage);

      roomSelect.addEventListener("change", function(){
        currentRoom = normalizeRoom(this.value);
        lastId = 0;
        chatBox.innerHTML = '<div class="text-muted small">Loading messages...</div>';
        fetchMessages(true);
        fetchActivity();
        connectStream();
      });

      attachBtn.addEventListener("click", function(){ fileInput.click(); });
      fileInput.addEventListener("change", function(){
        if (fileInput.files && fileInput.files.length) {
          const f = fileInput.files[0];
          attachName.textContent = "Attached: " + f.name + " (" + (Math.round((f.size || 0) / 1024 / 102.4) / 10) + " MB)";
          if (f.size && f.size > (50 * 1024 * 1024)) {
            alert("Attachment too large. Max 50 MB.");
            resetAttachment();
          }
        } else {
          attachName.textContent = "";
        }
      });

      emojiBtn.addEventListener("click", function(){
        emojiPanel.style.display = (emojiPanel.style.display === "none" || !emojiPanel.style.display) ? "block" : "none";
      });
      document.querySelectorAll(".emoji-btn").forEach(function(btn){
        btn.addEventListener("click", function(){
          chatInput.value = (chatInput.value || "") + (btn.getAttribute("data-emoji") || "");
          chatInput.focus();
          emojiPanel.style.display = "none";
        });
      });
      document.addEventListener("click", function(e){
        if (emojiPanel && !emojiPanel.contains(e.target) && e.target !== emojiBtn) {
          emojiPanel.style.display = "none";
        }
      });

      async function fetchActivity(){
        try {
          const res = await fetch("/chat/users_activity?_ts=" + Date.now(), {cache:"no-store", credentials:"same-origin"});
          const data = await res.json();
          if (!data.ok) return;
          if (!data.items || !data.items.length) {
            activityBox.innerHTML = '<div class="text-muted small">No recent activity.</div>';
            return;
          }
          activityBox.innerHTML = "";
          data.items.forEach(function(u){
            const div = document.createElement("div");
            div.className = "d-flex justify-content-between align-items-center mb-1";
            div.innerHTML = '<span class="fw-bold small">' + escapeHtml(u.display_name || u.username) + '</span>' +
                            '<span class="small text-muted">' + escapeHtml(u.last_at || "") + '</span>';
            activityBox.appendChild(div);
          });
        } catch (e) {
          console.error(e);
        }
      }

      refreshActivityBtns.forEach(function(btn){
        btn.addEventListener("click", function(){ fetchActivity(); });
      });

      if (clearBtn) {
        clearBtn.addEventListener("click", async function(){
          if (!confirm("Clear chat for this room? This will remove messages and attachments.")) return;
          try {
            const res = await fetch("/chat/clear?_ts=" + Date.now(), {
              method: "POST",
              headers: {"Content-Type":"application/json", "X-CSRFToken":"{{ csrf_token() }}"},
              body: JSON.stringify({room: currentRoom}),
              cache: "no-store",
              credentials: "same-origin"
            });
            const data = await res.json();
            if (!data.ok) {
              alert(data.error || "Failed");
              return;
            }
            lastId = 0;
            chatBox.innerHTML = '<div class="text-muted small">No messages yet.</div>';
            fetchActivity();
          } catch(e) {
            console.error(e);
            alert("Error clearing chat");
          }
        });
      }

      function toggleSearch(on){
        if (!searchPanel) return;
        if (on) {
          searchPanel.classList.remove("d-none");
          searchQ && searchQ.focus();
        } else {
          searchPanel.classList.add("d-none");
          if (searchHint) searchHint.textContent = "";
        }
      }

      if (searchToggleBtn) {
        searchToggleBtn.addEventListener("click", function(){
          const isHidden = searchPanel.classList.contains("d-none");
          toggleSearch(isHidden);
        });
      }
      if (searchCloseBtn) {
        searchCloseBtn.addEventListener("click", function(){
          inSearch = false;
          toggleSearch(false);
          if (searchQ) searchQ.value = "";
          lastId = 0;
          fetchMessages(true);
        });
      }

      async function doSearch(){
        const q = (searchQ && searchQ.value) ? searchQ.value.trim() : "";
        if (!q) {
          if (searchHint) searchHint.textContent = "Type something to search.";
          return;
        }
        try {
          inSearch = true;
          if (searchHint) searchHint.textContent = "Searching...";
          const params = new URLSearchParams();
          params.append("q", q);
          params.append("room", currentRoom);
          params.append("_ts", String(Date.now()));
          const res = await fetch("/chat/search?" + params.toString(), {cache:"no-store", credentials:"same-origin"});
          const data = await res.json();
          if (!data.ok) {
            if (searchHint) searchHint.textContent = data.error || "Search failed.";
            return;
          }
          const results = data.messages || [];
          chatBox.innerHTML = "";
          if (!results.length) {
            chatBox.innerHTML = '<div class="text-muted small">No matches.</div>';
          } else {
            results.forEach((m) => appendMessage(m, false));
          }
          if (searchHint) searchHint.textContent = "Matches: " + results.length + " (Close to return to live chat)";
          scrollChatToBottom();
        } catch(e) {
          console.error(e);
          if (searchHint) searchHint.textContent = "Search error.";
        }
      }

      if (searchBtn) searchBtn.addEventListener("click", doSearch);
      if (searchQ) searchQ.addEventListener("keydown", function(e){
        if (e.key === "Enter") {
          e.preventDefault();
          doSearch();
        }
      });

      function connectStream(){
        try { if (es) { es.close(); } } catch(e) {}
        es = null;
        if (!window.EventSource) {
          if (pollTimer) clearInterval(pollTimer);
          pollTimer = setInterval(function(){ fetchMessages(false); }, 3000);
          return;
        }
        try {
          const params = new URLSearchParams();
          params.append("room", currentRoom);
          params.append("after_id", String(lastId || 0));
          params.append("_ts", String(Date.now()));
          es = new EventSource("/chat/stream?" + params.toString(), {withCredentials:true});
          es.onmessage = function(ev){
            try {
              const m = JSON.parse(ev.data);
              if (m && m.id) {
                appendMessage(m, false);
                lastId = Math.max(lastId, parseInt(m.id || 0, 10) || 0);
                scrollChatToBottom();
              }
            } catch(e) {}
          };
          es.onerror = function(){
            try { es.close(); } catch(e) {}
            es = null;
            if (pollTimer) clearInterval(pollTimer);
            pollTimer = setInterval(function(){ fetchMessages(false); }, 3000);
          };
        } catch(e) {
          if (pollTimer) clearInterval(pollTimer);
          pollTimer = setInterval(function(){ fetchMessages(false); }, 3000);
        }
      }

      if (chatBox) {
        chatBox.addEventListener("click", function(e){
          const link = e.target.closest(".chat-media-link[data-preview='1']");
          if (!link) return;
          e.preventDefault();
          e.stopPropagation();
          const url = link.getAttribute("data-url") || link.href || "#";
          const kind = (link.getAttribute("data-kind") || "image").toLowerCase();
          const name = link.getAttribute("data-name") || "Media Preview";
          const mime = link.getAttribute("data-mime") || "video/mp4";
          if (!mediaModal) {
            try { window.open(url, "_blank", "noopener"); } catch(err) {}
            return;
          }
          mediaModalTitle.textContent = name;
          mediaModalOpenLink.href = url;
          if (kind === "video") {
            mediaModalBody.innerHTML = '<video controls playsinline preload="metadata" style="width:100%; max-height:70vh; background:#000; border-radius:12px;"><source src="' + escapeHtml(url) + '" type="' + escapeHtml(mime) + '">Your browser cannot play this video.</video>';
          } else {
            mediaModalBody.innerHTML = '<img src="' + escapeHtml(url) + '" alt="' + escapeHtml(name) + '" style="width:100%; max-height:70vh; object-fit:contain; border-radius:12px;">';
          }
          mediaModal.show();
        });
        chatBox.addEventListener("click", function(e){
          if (e.target && (e.target.closest("video") || e.target.closest("audio"))) {
            e.stopPropagation();
          }
        }, true);
      }

      fetchMessages(true).then(function(){
        fetchActivity();
        connectStream();
      });
      setInterval(function(){ fetchActivity(); }, 15000);
      window.addEventListener("focus", function(){ fetchMessages(false); fetchActivity(); });
      document.addEventListener("visibilitychange", function(){ if (!document.hidden) { fetchMessages(false); fetchActivity(); } });
    });
    </script>
    {% endblock %}
    """).strip()

    TEMPLATES["chat_page_v2.html"] = _FINAL_CHAT_TEMPLATE

    @login_required
    def _chat_page_patch_final_v1():
        return render_template("chat_page_v2.html")

    app.view_functions["chat_page"] = _chat_page_patch_final_v1
except Exception as _chat_patch_exc:
    try:
        _log_noncritical_exception("FINAL live chat override patch failed", _chat_patch_exc)
    except Exception:
        pass

try:
    app.jinja_loader = DictLoader(TEMPLATES)
except Exception:
    pass


