# ============================================================
# SINGLE_SESSION_TAKEOVER_FINAL_V5
# - New login always becomes the active authoritative session.
# - Previous device is auto-logged-out on its next request/poll.
# - Removes false hard-blocks caused by stale active_session_* values.
# - Uses users.active_session_* as the primary source of truth.
# ============================================================
try:
    def _single_session_check_current_users_authoritative(force=False):
        user_id = session.get('user_id')
        token = (session.get('_session_token') or '').strip()
        if not user_id or not token:
            try:
                return _orig_single_session_check_current(force=force)
            except Exception:
                return True
        try:
            now_ts = int(time.time())
        except Exception:
            now_ts = 0
        try:
            last_check = int(session.get('single_session_last_check') or 0)
        except Exception:
            last_check = 0
        try:
            if (not force) and last_check and now_ts and (now_ts - last_check) < max(5, int(SINGLE_SESSION_CHECK_INTERVAL_SECONDS or 15)):
                return True
        except Exception:
            pass

        row = None
        try:
            row = _users_row_quick_by_id(user_id, timeout_s=0.5) if '_users_row_quick_by_id' in globals() else None
        except Exception:
            row = None

        if row is None:
            try:
                ok = _orig_single_session_check_current(force=force)
            except Exception:
                ok = True
            if ok:
                try:
                    session['single_session_last_check'] = now_ts
                    session.modified = True
                except Exception:
                    pass
            return ok

        active_token = (row.get('active_session_token') or '').strip()
        active_updated_at = (row.get('active_session_updated_at') or '').strip()

        # No authoritative token in users table yet -> register this session lazily.
        if not active_token:
            try:
                _single_session_register_quick(user_id, session.get('username') or '', token)
            except Exception:
                pass
            try:
                session['single_session_last_check'] = now_ts
                session.modified = True
            except Exception:
                pass
            return True

        # This browser is still the active session.
        if active_token == token:
            try:
                if not _session_recent_enough(active_updated_at):
                    _single_session_register_quick(user_id, session.get('username') or '', token)
            except Exception:
                pass
            try:
                session['single_session_last_check'] = now_ts
                session.modified = True
            except Exception:
                pass
            return True

        # Different authoritative token exists -> another login took over.
        return False

    _single_session_check_current = _single_session_check_current_users_authoritative

    def login_v5():
        if request.method == 'GET' and session.get('user_id'):
            return login_redirect_for_role(session.get('role'))

        if request.method == 'GET' and request.args.get('forced_logout') == 'other_device':
            flash('Your account has been opened on another computer. This session was closed automatically.', 'warning')

        if request.method == 'POST':
            username = request.form.get('username', '').strip()
            password = request.form.get('password', '').strip()
            if not username or not password:
                flash('Please enter username and password.', 'warning')
                return render_template('login.html'), 400

            try:
                _ip = security.get_client_ip(request)
                _allowed, _retry_after = security.login_rate_limit_check(username, _ip)
                if not _allowed:
                    mins = max(1, int((_retry_after or 60) / 60))
                    flash(f'Too many login attempts. Please try again after {mins} minute(s).', 'danger')
                    return render_template('login.html'), 429
            except Exception:
                pass

            u, fetch_err = _users_login_row_fast(username, timeout_s=_LOGIN_FAST_TIMEOUT_SECONDS)
            if fetch_err and not u:
                flash('Login service is busy right now. Please try again in a few seconds.', 'warning')
                return render_template('login.html'), 503

            if u and _verify_login_password_cached(username, (u.get('password_hash') or ''), password):
                previous_token = (u.get('active_session_token') or '').strip()
                previous_updated_at = (u.get('active_session_updated_at') or '').strip()
                previous_ip = (u.get('active_session_ip') or '').strip()
                previous_ua = (u.get('active_session_user_agent') or '').strip()[:500]
                took_over_other_device = bool(previous_token and _session_recent_enough(previous_updated_at))

                session.clear()
                session['user_id'] = u['id']
                session['username'] = u['username']
                session['role'] = normalize_role_key(u.get('role') if isinstance(u, dict) else u['role']) or (u.get('role') if isinstance(u, dict) else u['role'])
                session['full_name'] = u.get('full_name') or ''
                session['gd_number'] = u.get('gd_number') or ''
                session['_session_token'] = uuid.uuid4().hex
                session['single_session_last_check'] = 0
                session['_single_session_users_touch_ts'] = 0
                session.permanent = False
                session['last_activity'] = int(time.time())

                _single_session_register_quick(u['id'], u.get('username') or '', session.get('_session_token'))
                try:
                    _touch_active_session_users_row(force=True)
                except Exception:
                    pass
                try:
                    _cleanup_stale_visit_locks_after_login(u.get('username') or '')
                except Exception:
                    pass
                try:
                    security.login_rate_limit_reset(username, security.get_client_ip(request))
                except Exception:
                    pass
                try:
                    security.audit_event('LOGIN_OK', {'username': username}, status=200)
                except Exception:
                    pass
                try:
                    if took_over_other_device:
                        log_action(
                            'SINGLE_SESSION_TAKEOVER',
                            details=(
                                f"username={username}; prev_ip={previous_ip}; prev_ua={(previous_ua or '')[:120]}"
                            ),
                        )
                except Exception:
                    pass
                return login_redirect_for_role(u.get('role'))

            try:
                security.login_rate_limit_fail(username, security.get_client_ip(request))
                security.audit_event('LOGIN_FAIL', {'username': username}, status=401)
            except Exception:
                pass
            flash('Invalid username or password.', 'danger')
            return render_template('login.html'), 401

        return render_template('login.html')

    app.view_functions['login'] = login_v5
except Exception as _single_session_takeover_final_exc:
    try:
        _log_noncritical_exception('SINGLE_SESSION_TAKEOVER_FINAL_V5 failed', _single_session_takeover_final_exc)
    except Exception:
        pass

