# SERIAL_VITALS_BOARD_PDF_PATCH_V2
try:
    from markupsafe import Markup, escape as _ms_escape
except Exception:
    Markup = lambda s: s
    def _ms_escape(v):
        return str(v if v is not None else "")


def _serial_vitals_patient_snapshot_dict(patient_row):
    d = _row_to_dict(patient_row) or {}
    bp = (d.get("latest_bp") or "").strip() or _compose_bp_value(
        d.get("latest_bp_systolic"), d.get("latest_bp_diastolic")
    )
    return {
        "bp": bp,
        "bp_sys": (d.get("latest_bp_systolic") or "").strip(),
        "bp_dia": (d.get("latest_bp_diastolic") or "").strip(),
        "hr": (d.get("latest_hr") or "").strip(),
        "rr": (d.get("latest_rr") or "").strip(),
        "temp": (d.get("latest_temp") or "").strip(),
        "spo2": (d.get("latest_spo2") or "").strip(),
        "recorded_by": (d.get("latest_vitals_recorded_by") or "").strip(),
        "recorded_at": format_dt_local((d.get("latest_vitals_recorded_at") or "").strip()) or (d.get("latest_vitals_recorded_at") or "").strip(),
        "recorded_at_raw": (d.get("latest_vitals_recorded_at") or "").strip(),
    }


def board_latest_vitals_for_visit(visit_row):
    try:
        visit = _row_to_dict(visit_row) or {}
    except Exception:
        visit = {}
    visit_id = (visit.get("visit_id") or "").strip()
    if not visit_id:
        return build_current_vitals_snapshot(visit_row, None)
    cache = getattr(g, "_board_serial_vitals_cache", None)
    if cache is None:
        cache = {}
        g._board_serial_vitals_cache = cache
    if visit_id in cache:
        return cache[visit_id]

    latest = None
    patient_snapshot = None
    db_row = None
    try:
        cur = get_db().cursor()
        db_row = cur.execute(
            """
            SELECT v.visit_id, v.patient_id, v.triage_time, v.created_at,
                   v.pulse_rate, v.resp_rate, v.bp_systolic, v.bp_diastolic,
                   v.temperature, v.spo2,
                   p.latest_bp, p.latest_bp_systolic, p.latest_bp_diastolic,
                   p.latest_hr, p.latest_rr, p.latest_temp, p.latest_spo2,
                   p.latest_vitals_recorded_by, p.latest_vitals_recorded_at
            FROM visits v
            LEFT JOIN patients p ON p.id = v.patient_id
            WHERE v.visit_id=?
            """,
            (visit_id,),
        ).fetchone()
    except Exception as e:
        _log_noncritical_exception(
            f"Board serial vitals snapshot query failed for visit={visit_id}",
            e,
        )
        db_row = None

    if db_row:
        patient_snapshot = _serial_vitals_patient_snapshot_dict(db_row)
        if any(
            [
                patient_snapshot.get("bp"),
                patient_snapshot.get("hr"),
                patient_snapshot.get("rr"),
                patient_snapshot.get("temp"),
                patient_snapshot.get("spo2"),
            ]
        ):
            latest = patient_snapshot

    if not latest:
        try:
            latest = get_patient_vitals_latest(visit_id)
        except Exception:
            latest = None

    snap = build_current_vitals_snapshot(db_row or visit_row, latest)
    cache[visit_id] = snap
    return snap


def board_vitals_cell(visit_row):
    snap = board_latest_vitals_for_visit(visit_row)
    flags = snap.get("flags") or {}
    def _line(label, value, abnormal=False):
        cls = ' class="text-danger fw-bold"' if abnormal else ''
        return f'<div{cls}>{_ms_escape(label)}: {_ms_escape(value or "-")}</div>'
    html = ['<div class="small lh-sm">']
    html.append(_line('BP', snap.get('bp'), flags.get('bp')))
    html.append(_line('HR', snap.get('hr'), flags.get('hr')))
    html.append(_line('RR', snap.get('rr'), flags.get('rr')))
    html.append(_line('Temp', snap.get('temp'), flags.get('temp')))
    html.append(_line('SpO2', (str(snap.get('spo2') or '-') + ('%' if str(snap.get('spo2') or '').strip() else '')), flags.get('spo2')))
    if snap.get('recorded_at'):
        html.append(f'<div class="text-muted mt-1">{_ms_escape(snap.get("recorded_at"))}</div>')
    html.append('</div>')
    return Markup(''.join(html))


def board_vitals_summary(visit_row):
    snap = board_latest_vitals_for_visit(visit_row)
    flags = snap.get("flags") or {}
    def _badge(label, value, abnormal=False, suffix=''):
        cls = 'badge text-bg-danger fw-bold' if abnormal else 'badge text-bg-light'
        txt = f'{label}: {value if str(value or "").strip() else "-"}{suffix if str(value or "").strip() else ""}'
        return f'<span class="{cls}">{_ms_escape(txt)}</span>'
    chips = [
        _badge('BP', snap.get('bp'), flags.get('bp')),
        _badge('HR', snap.get('hr'), flags.get('hr')),
        _badge('RR', snap.get('rr'), flags.get('rr')),
        _badge('Temp', snap.get('temp'), flags.get('temp'), ' °C'),
        _badge('SpO2', snap.get('spo2'), flags.get('spo2'), '%'),
    ]
    meta = ''
    if snap.get('recorded_at'):
        meta = f'<div class="small text-muted mt-1">Last vitals update: {_ms_escape(snap.get("recorded_at"))}</div>'
    return Markup(
        '<div><div class="board-section-title">Latest Vitals</div><div class="d-flex flex-wrap gap-1 small">'
        + ''.join(chips)
        + '</div>'
        + meta
        + '</div>'
    )


def _serial_vitals_pdf_addendum_bytes(visit_id):
    try:
        rows = get_patient_vitals_log(visit_id, limit=500)
    except Exception:
        rows = []
    try:
        cur = get_db().cursor()
        visit = cur.execute(
            """
            SELECT v.visit_id, v.created_at, p.name, p.mrn
            FROM visits v
            LEFT JOIN patients p ON p.id=v.patient_id
            WHERE v.visit_id=?
            """,
            (visit_id,),
        ).fetchone()
    except Exception:
        visit = None
    visit_d = _row_to_dict(visit) or {}
    if not rows:
        try:
            latest = board_latest_vitals_for_visit({"visit_id": visit_id})
        except Exception:
            latest = None
        if latest and any([latest.get('bp'), latest.get('hr'), latest.get('rr'), latest.get('temp'), latest.get('spo2')]):
            rows = [
                {
                    "recorded_at": latest.get("recorded_at") or "",
                    "bp": latest.get("bp") or "",
                    "hr": latest.get("hr") or "",
                    "rr": latest.get("rr") or "",
                    "temp": latest.get("temp") or "",
                    "spo2": latest.get("spo2") or "",
                    "recorded_by": latest.get("recorded_by") or "",
                    "flags": latest.get("flags") or {},
                }
            ]
    if not rows:
        return b""
    import io as _io_local
    buf = _io_local.BytesIO()
    c = canvas.Canvas(buf, pagesize=A4)
    width, height = A4
    margin = 1.4 * cm
    line_h = 0.65 * cm

    def _start_page(page_no):
        c.setFont("Helvetica-Bold", 15)
        c.drawString(margin, height - margin, "Serial Vitals Log")
        c.setFont("Helvetica", 9)
        header_y = height - margin - 0.6 * cm
        c.drawString(margin, header_y, f"Case No: {visit_id}")
        if visit_d.get("name"):
            c.drawString(margin + 6.2 * cm, header_y, f"Patient: {visit_d.get('name')}")
        if visit_d.get("mrn"):
            c.drawString(margin + 13.0 * cm, header_y, f"MRN: {visit_d.get('mrn')}")
        c.drawString(margin, header_y - 0.45 * cm, f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
        c.drawRightString(width - margin, header_y - 0.45 * cm, f"Page {page_no}")
        table_y = header_y - 1.0 * cm
        c.setFont("Helvetica-Bold", 9)
        cols = [
            (margin, 'Date / Time'),
            (margin + 4.4 * cm, 'BP'),
            (margin + 7.5 * cm, 'HR'),
            (margin + 9.0 * cm, 'RR'),
            (margin + 10.6 * cm, 'Temp'),
            (margin + 13.0 * cm, 'SpO2'),
            (margin + 15.0 * cm, 'Recorded By'),
        ]
        for x, label in cols:
            c.drawString(x, table_y, label)
        c.setStrokeColor(colors.grey)
        c.line(margin, table_y - 0.15 * cm, width - margin, table_y - 0.15 * cm)
        return table_y - 0.65 * cm

    y = _start_page(1)
    page_no = 1
    c.setFont("Helvetica", 8.5)
    for row in rows:
        if y < margin + 1.5 * cm:
            c.showPage()
            page_no += 1
            y = _start_page(page_no)
            c.setFont("Helvetica", 8.5)
        flags = row.get('flags') or {}
        def _draw(x, txt, abnormal=False):
            c.setFillColor(colors.red if abnormal else colors.black)
            c.setFont("Helvetica-Bold" if abnormal else "Helvetica", 8.5)
            c.drawString(x, y, str(txt or '-'))
        _draw(margin, row.get('recorded_at') or '-', False)
        _draw(margin + 4.4 * cm, row.get('bp') or '-', flags.get('bp'))
        _draw(margin + 7.5 * cm, row.get('hr') or '-', flags.get('hr'))
        _draw(margin + 9.0 * cm, row.get('rr') or '-', flags.get('rr'))
        _draw(margin + 10.6 * cm, row.get('temp') or '-', flags.get('temp'))
        spo2_txt = str(row.get('spo2') or '-') + ('%' if str(row.get('spo2') or '').strip() else '')
        _draw(margin + 13.0 * cm, spo2_txt, flags.get('spo2'))
        _draw(margin + 15.0 * cm, row.get('recorded_by') or '-', False)
        c.setStrokeColor(colors.lightgrey)
        c.line(margin, y - 0.12 * cm, width - margin, y - 0.12 * cm)
        y -= line_h
    c.save()
    return buf.getvalue()


def _serial_vitals_pdf_append(base_pdf_bytes, addendum_pdf_bytes):
    if not base_pdf_bytes or not addendum_pdf_bytes:
        return base_pdf_bytes
    try:
        try:
            from pypdf import PdfReader, PdfWriter
        except Exception:
            from PyPDF2 import PdfReader, PdfWriter
        import io as _io_local
        writer = PdfWriter()
        for payload in (base_pdf_bytes, addendum_pdf_bytes):
            reader = PdfReader(_io_local.BytesIO(payload))
            for page in reader.pages:
                writer.add_page(page)
        out = _io_local.BytesIO()
        writer.write(out)
        return out.getvalue()
    except Exception:
        return base_pdf_bytes


@app.after_request
def _serial_vitals_append_to_patient_pdfs(response):
    try:
        content_type = (response.headers.get('Content-Type') or getattr(response, 'mimetype', '') or '').lower()
        visit_id = ((request.view_args or {}).get('visit_id') or request.args.get('visit_id') or '').strip()
        if not visit_id or 'application/pdf' not in content_type:
            return response
        endpoint_name = (request.endpoint or '').strip()
        mode_name = (request.args.get('mode', '') or '').strip().lower()
        if endpoint_name == 'auto_summary_pdf':
            return response
        if endpoint_name == 'discharge_summary_pdf' and mode_name == 'short':
            return response
        try:
            response.direct_passthrough = False
        except Exception:
            pass
        base_pdf = response.get_data()
        addendum_pdf = _serial_vitals_pdf_addendum_bytes(visit_id)
        if not addendum_pdf:
            return response
        merged_pdf = _serial_vitals_pdf_append(base_pdf, addendum_pdf)
        if merged_pdf and merged_pdf != base_pdf:
            response.set_data(merged_pdf)
            response.headers['Content-Length'] = str(len(merged_pdf))
    except Exception as e:
        _log_noncritical_exception(
            f"Serial vitals PDF append failed for endpoint={getattr(request, 'endpoint', '')}",
            e,
        )
    return response


