try:
    def get_serial_vitals_timeline(visit_id, limit=500):
        visit_id = str(visit_id or "").strip()
        if not visit_id:
            return []

        try:
            limit = int(limit or 0)
        except Exception:
            limit = 0

        rows_out = []
        seen = set()

        def _push(row_dict, source=""):
            row = _row_to_dict(row_dict) or {}
            bp = str(row.get("bp") or "").strip() or _compose_bp_value(
                row.get("bp_systolic"), row.get("bp_diastolic")
            )
            hr = str(row.get("hr") or row.get("pulse_rate") or "").strip()
            rr = str(row.get("rr") or row.get("resp_rate") or "").strip()
            temp = str(row.get("temp") or row.get("temperature") or "").strip()
            spo2 = str(row.get("spo2") or "").strip()
            recorded_at_raw = str(row.get("recorded_at_raw") or row.get("recorded_at") or row.get("time") or row.get("triage_time") or row.get("created_at") or "").strip()
            recorded_at = format_dt_local(recorded_at_raw) or recorded_at_raw
            recorded_by = str(row.get("recorded_by") or row.get("created_by") or "").strip()
            if not any([bp, hr, rr, temp, spo2]):
                return
            dedupe_key = (recorded_at_raw, bp, hr, rr, temp, spo2, recorded_by)
            if dedupe_key in seen:
                return
            seen.add(dedupe_key)
            item = {
                "recorded_at": recorded_at,
                "recorded_at_raw": recorded_at_raw,
                "bp": bp,
                "bp_sys": _split_bp_value(bp)[0],
                "bp_dia": _split_bp_value(bp)[1],
                "hr": hr,
                "rr": rr,
                "temp": temp,
                "spo2": spo2,
                "recorded_by": recorded_by,
                "source": source,
            }
            item["flags"] = _serial_vitals_flags(bp=bp, hr=hr, rr=rr, temp=temp, spo2=spo2)
            rows_out.append(item)

        try:
            for r in get_patient_vitals_log(visit_id, limit=limit or 5000):
                _push(r, source="patient_vitals")
        except Exception as e:
            _log_noncritical_exception(
                f"Serial vitals timeline patient_vitals failed for visit={visit_id}",
                e,
            )

        try:
            cur = get_db().cursor()
            sql = """
                SELECT recorded_at,
                       pulse_rate, resp_rate,
                       bp_systolic, bp_diastolic,
                       temperature, spo2, recorded_by
                FROM vital_signs
                WHERE visit_id=?
                ORDER BY recorded_at DESC, id DESC
            """
            params = [visit_id]
            if limit and limit > 0:
                sql += " LIMIT ?"
                params.append(limit)
            for r in cur.execute(sql, tuple(params)).fetchall():
                _push(r, source="vital_signs")
        except Exception as e:
            _log_noncritical_exception(
                f"Serial vitals timeline vital_signs failed for visit={visit_id}",
                e,
            )

        try:
            cur = get_db().cursor()
            v = cur.execute(
                """
                SELECT triage_time, created_at, created_by,
                       pulse_rate, resp_rate,
                       bp_systolic, bp_diastolic,
                       temperature, spo2
                FROM visits
                WHERE visit_id=?
                """,
                (visit_id,),
            ).fetchone()
            if v:
                _push(v, source="visit")
        except Exception as e:
            _log_noncritical_exception(
                f"Serial vitals timeline visit snapshot failed for visit={visit_id}",
                e,
            )

        def _sort_key(item):
            return str(item.get("recorded_at_raw") or item.get("recorded_at") or "")

        rows_out.sort(key=_sort_key, reverse=True)
        if limit and limit > 0:
            rows_out = rows_out[:limit]
        return rows_out


    def format_serial_vitals_log_text(visit_id, limit=12, include_source=False):
        try:
            rows = get_serial_vitals_timeline(visit_id, limit=limit or 12)
        except Exception:
            rows = []
        if not rows:
            return ""
        out_lines = []
        for row in rows:
            metrics = []
            if row.get("bp"):
                metrics.append(f"BP {row.get('bp')}")
            if row.get("hr"):
                metrics.append(f"HR {row.get('hr')}")
            if row.get("rr"):
                metrics.append(f"RR {row.get('rr')}")
            if row.get("temp"):
                metrics.append(f"Temp {row.get('temp')} C")
            if row.get("spo2"):
                metrics.append(f"SpO2 {row.get('spo2')}%")
            details = [str(row.get("recorded_at") or "-")]
            if metrics:
                details.append(" | ".join(metrics))
            actor = (row.get("recorded_by") or "-").strip() or "-"
            tail = f"by {actor}"
            source = (row.get("source") or "").strip()
            if include_source and source:
                tail += f" [{source}]"
            details.append(tail)
            out_lines.append("- " + " | ".join(details))
        return "\n".join(out_lines)


    def _serial_vitals_pdf_addendum_bytes(visit_id):
        try:
            rows = get_serial_vitals_timeline(visit_id, limit=500)
        except Exception:
            rows = []
        try:
            cur = get_db().cursor()
            visit = cur.execute(
                """
                SELECT v.visit_id, v.created_at, p.name, p.mrn
                FROM visits v
                LEFT JOIN patients p ON p.id=v.patient_id
                WHERE v.visit_id=?
                """,
                (visit_id,),
            ).fetchone()
        except Exception:
            visit = None
        visit_d = _row_to_dict(visit) or {}
        if not rows:
            return b""
        import io as _io_local
        buf = _io_local.BytesIO()
        c = canvas.Canvas(buf, pagesize=A4)
        width, height = A4
        margin = 1.35 * cm
        line_h = 0.62 * cm

        def _start_page(page_no):
            c.setFont("Helvetica-Bold", 15)
            c.drawString(margin, height - margin, "Serial Vitals Log")
            c.setFont("Helvetica", 9)
            header_y = height - margin - 0.58 * cm
            c.drawString(margin, header_y, f"Case No: {visit_id}")
            if visit_d.get("name"):
                c.drawString(margin + 6.0 * cm, header_y, f"Patient: {visit_d.get('name')}")
            if visit_d.get("mrn"):
                c.drawString(margin + 13.0 * cm, header_y, f"MRN: {visit_d.get('mrn')}")
            c.drawString(margin, header_y - 0.42 * cm, f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
            c.drawRightString(width - margin, header_y - 0.42 * cm, f"Page {page_no}")
            table_y = header_y - 0.95 * cm
            c.setFont("Helvetica-Bold", 8.8)
            cols = [
                (margin, "Date / Time"),
                (margin + 4.45 * cm, "BP"),
                (margin + 7.55 * cm, "HR"),
                (margin + 9.10 * cm, "RR"),
                (margin + 10.75 * cm, "Temp"),
                (margin + 13.10 * cm, "SpO2"),
                (margin + 15.10 * cm, "Recorded By"),
            ]
            for x, label in cols:
                c.drawString(x, table_y, label)
            c.setStrokeColor(colors.grey)
            c.line(margin, table_y - 0.15 * cm, width - margin, table_y - 0.15 * cm)
            return table_y - 0.62 * cm

        y = _start_page(1)
        page_no = 1
        c.setFont("Helvetica", 8.4)
        for row in rows:
            if y < margin + 1.4 * cm:
                c.showPage()
                page_no += 1
                y = _start_page(page_no)
                c.setFont("Helvetica", 8.4)
            flags = row.get("flags") or {}

            def _draw(x, txt, abnormal=False):
                c.setFillColor(colors.red if abnormal else colors.black)
                c.setFont("Helvetica-Bold" if abnormal else "Helvetica", 8.4)
                c.drawString(x, y, str(txt or "-"))

            _draw(margin, row.get("recorded_at") or "-", False)
            _draw(margin + 4.45 * cm, row.get("bp") or "-", flags.get("bp"))
            _draw(margin + 7.55 * cm, row.get("hr") or "-", flags.get("hr"))
            _draw(margin + 9.10 * cm, row.get("rr") or "-", flags.get("rr"))
            _draw(margin + 10.75 * cm, row.get("temp") or "-", flags.get("temp"))
            spo2_txt = str(row.get("spo2") or "-") + ("%" if str(row.get("spo2") or "").strip() else "")
            _draw(margin + 13.10 * cm, spo2_txt, flags.get("spo2"))
            _draw(margin + 15.10 * cm, row.get("recorded_by") or "-", False)
            c.setStrokeColor(colors.lightgrey)
            c.line(margin, y - 0.12 * cm, width - margin, y - 0.12 * cm)
            y -= line_h
        c.save()
        return buf.getvalue()
except Exception:
    pass


