def _lab_flowsheet_clean_token(val):
    s = str(val or '').strip()
    s = re.sub(r'\s+', ' ', s)
    return s


def _lab_flowsheet_token_key(val):
    s = _lab_flowsheet_clean_token(val).upper()
    s = s.replace('%', ' %')
    s = re.sub(r'[^A-Z0-9%+()/. -]+', '', s)
    s = re.sub(r'\s+', ' ', s).strip()
    return s


def _lab_flowsheet_category_label(category: str, test_name: str = '') -> str:
    raw_category = _lab_flowsheet_clean_token(category).lower()
    if raw_category in _LAB_FLOWSHEET_CATEGORY_LABELS:
        return _LAB_FLOWSHEET_CATEGORY_LABELS[raw_category]

    test_up = _lab_flowsheet_clean_token(test_name).upper()
    if 'CBC' in test_up or 'HEMATO' in test_up:
        return 'CBC'
    if 'ABG' in test_up or 'VBG' in test_up or 'BLOOD GAS' in test_up or 'BLOOD GASES' in test_up:
        return 'Blood Gases'
    if any(x in test_up for x in ('BMP', 'CMP', 'CHEM', 'LFT', 'RFT', 'METABOLIC')):
        return 'Chemistry'
    if raw_category:
        return raw_category.title()
    return 'Other Labs'


def _lab_flowsheet_panel_title(row_dict: dict, catalog_info: dict, patient_dob: str = '', patient_sex: str = '') -> str:
    test_name = _lab_flowsheet_clean_token(row_dict.get('test_name') or '')
    test_up = test_name.upper()
    result_type = _lab_flowsheet_clean_token((catalog_info or {}).get('result_type') or '').lower()
    if result_type == 'panel' and test_name:
        return test_name
    if any(x in test_up for x in ('CBC', 'BMP', 'CMP', 'ABG', 'VBG', 'PANEL', 'PROFILE', 'LFT', 'RFT')):
        return test_name

    source_text = _lab_flowsheet_clean_token(row_dict.get('source_lab_orders') or '')
    if source_text:
        panel_candidates = []
        try:
            for item in _co_split_order_items(source_text):
                info = get_lab_catalog_info(item, dob_str=patient_dob, sex=patient_sex) or {}
                item_type = _lab_flowsheet_clean_token(info.get('result_type') or '').lower()
                if item_type == 'panel':
                    panel_candidates.append(_lab_flowsheet_clean_token(item))
        except Exception as source_parse_exc:
            _log_noncritical_exception(
                f"Lab flowsheet source order parsing failed for visit={row_dict.get('visit_id')}",
                source_parse_exc,
            )
        if len(panel_candidates) == 1:
            return panel_candidates[0]

    return _lab_flowsheet_category_label((catalog_info or {}).get('category') or '', test_name=test_name)


def _lab_flowsheet_canonical_name(label: str, panel_title: str = '') -> str:
    clean_label = _lab_flowsheet_clean_token(label)
    key = _lab_flowsheet_token_key(clean_label)
    panel_key = _lab_flowsheet_token_key(panel_title)

    if panel_key in ('ABG', 'ARTERIAL BLOOD GAS') and key in _LAB_ABG_ALIAS_MAP:
        return _LAB_ABG_ALIAS_MAP[key]
    if panel_key in ('VBG', 'VENOUS BLOOD GAS') and key in _LAB_VBG_ALIAS_MAP:
        return _LAB_VBG_ALIAS_MAP[key]
    if key in _LAB_ANALYTE_ALIAS_MAP:
        return _LAB_ANALYTE_ALIAS_MAP[key]
    return clean_label


def _lab_flowsheet_normalize_flag(flag_text: str) -> str:
    s = _lab_flowsheet_clean_token(flag_text).upper()
    if not s:
        return ''
    if s in ('C', 'CRIT', 'CRITICAL', 'CRIT HIGH', 'CRIT LOW', 'PANIC'):
        return 'C'
    if s in ('H', 'HIGH'):
        return 'H'
    if s in ('L', 'LOW'):
        return 'L'
    if s in ('N', 'NORMAL'):
        return 'N'
    return ''


def _lab_flowsheet_compute_flag(value_text: str, catalog_info: dict = None, explicit_flag: str = '') -> str:
    normalized = _lab_flowsheet_normalize_flag(explicit_flag)
    if normalized:
        return normalized

    value_str = str(value_text or '').strip()
    if value_str:
        trailing_flag = re.search(r'(?:\(|\[)?\s*(H|L|C|N)\s*(?:\)|\])?\s*$', value_str, re.I)
        if trailing_flag:
            normalized_trailing = _lab_flowsheet_normalize_flag(trailing_flag.group(1))
            if normalized_trailing:
                return normalized_trailing
        upper_val = value_str.upper()
        if 'CRITICAL' in upper_val or 'PANIC' in upper_val:
            return 'C'
        if re.search(r'\bHIGH\b', upper_val):
            return 'H'
        if re.search(r'\bLOW\b', upper_val):
            return 'L'
        if re.search(r'\bNORMAL\b', upper_val):
            return 'N'

    info = catalog_info or {}
    numeric_value = _parse_first_float(value_str)
    if numeric_value is None:
        return ''

    low = info.get('ref_low')
    high = info.get('ref_high')
    crit_low = info.get('critical_low')
    crit_high = info.get('critical_high')

    try:
        if crit_low is not None and numeric_value < float(crit_low):
            return 'C'
        if crit_high is not None and numeric_value > float(crit_high):
            return 'C'
        if low is not None and numeric_value < float(low):
            return 'L'
        if high is not None and numeric_value > float(high):
            return 'H'
        return 'N' if (low is not None or high is not None) else ''
    except Exception as flag_exc:
        _log_noncritical_exception('Lab flowsheet numeric flagging failed', flag_exc)
        return ''


def _lab_flowsheet_value_class(flag: str) -> str:
    normalized = _lab_flowsheet_normalize_flag(flag)
    if normalized == 'H':
        return 'lab-value-high'
    if normalized == 'L':
        return 'lab-value-low'
    if normalized == 'C':
        return 'lab-value-critical'
    return 'lab-value-normal'


def _lab_flowsheet_flag_badge_class(flag: str) -> str:
    normalized = _lab_flowsheet_normalize_flag(flag)
    if normalized == 'H':
        return 'text-bg-danger'
    if normalized == 'L':
        return 'text-bg-primary'
    if normalized == 'C':
        return 'text-bg-danger'
    return 'text-bg-light text-dark border'


def _lab_flowsheet_segment_looks_like_result(label: str, value_text: str) -> bool:
    lbl = _lab_flowsheet_clean_token(label)
    val = _lab_flowsheet_clean_token(value_text)
    if not lbl or not val:
        return False
    if len(lbl) > 64:
        return False
    if not re.search(r'[A-Za-z]', lbl):
        return False
    if _parse_first_float(val) is not None:
        return True
    if re.search(r'\b(pos|positive|neg|negative|reactive|non[- ]reactive|normal|abnormal|detected|not detected)\b', val, re.I):
        return True
    return False


def _lab_flowsheet_parse_component_segment(segment: str, panel_title: str = '', patient_dob: str = '', patient_sex: str = ''):
    seg = str(segment or '').strip()
    seg = re.sub(r'^[-•*\d\.)\s]+', '', seg).strip()
    if not seg:
        return None

    match = re.match(r'^([A-Za-z][A-Za-z0-9/%() .+\-]{0,64}?)\s*(?:[:=]|-)\s*(.+)$', seg)
    if not match:
        return None

    label = _lab_flowsheet_clean_token(match.group(1))
    value_part = _lab_flowsheet_clean_token(match.group(2))
    if not _lab_flowsheet_segment_looks_like_result(label, value_part):
        return None

    explicit_flag = ''
    trailing_flag = re.search(r'(?:\(|\[)?\s*(H|L|C|N)\s*(?:\)|\])?\s*$', value_part, re.I)
    if trailing_flag:
        explicit_flag = trailing_flag.group(1).upper()
        value_part = value_part[: trailing_flag.start()].strip(' ;,|')

    inline_ref = ''
    ref_match = re.search(r'\b(?:ref(?:erence)?(?:\s*range)?|normal)\s*[:=]\s*(.+)$', value_part, re.I)
    if ref_match:
        inline_ref = _lab_flowsheet_clean_token(ref_match.group(1))
        value_part = value_part[: ref_match.start()].strip(' ;,|')

    canonical_name = _lab_flowsheet_canonical_name(label, panel_title=panel_title)
    catalog_info = get_lab_catalog_info(canonical_name, dob_str=patient_dob, sex=patient_sex) or {}
    if not catalog_info and canonical_name != label:
        catalog_info = get_lab_catalog_info(label, dob_str=patient_dob, sex=patient_sex) or {}

    flag = _lab_flowsheet_compute_flag(value_part, catalog_info=catalog_info, explicit_flag=explicit_flag)
    reference_range = catalog_info.get('ref_range_disp') or inline_ref or ''
    units = catalog_info.get('units') or ''

    return {
        'display_name': label,
        'canonical_name': canonical_name or label,
        'value': value_part or '-',
        'units': units,
        'reference_range': reference_range,
        'flag': flag,
        'value_class': _lab_flowsheet_value_class(flag),
        'flag_badge_class': _lab_flowsheet_flag_badge_class(flag),
        'sort_rank': _LAB_COMMON_TEST_ORDER.get(canonical_name or label, 9999),
    }


def _lab_flowsheet_parse_result_row(row_dict: dict, panel_title: str, patient_dob: str = '', patient_sex: str = ''):
    raw_text = str(row_dict.get('result_text') or '').strip()
    parsed_components = []
    if raw_text:
        normalized_text = raw_text.replace('\r', '\n')
        raw_segments = []
        for line in normalized_text.split('\n'):
            line = line.strip()
            if not line:
                continue
            pieces = [x.strip() for x in re.split(r'\s*[;|]\s*', line) if x.strip()]
            raw_segments.extend(pieces or [line])

        for segment in raw_segments:
            parsed = _lab_flowsheet_parse_component_segment(
                segment,
                panel_title=panel_title,
                patient_dob=patient_dob,
                patient_sex=patient_sex,
            )
            if parsed:
                parsed_components.append(parsed)

    if len(parsed_components) >= 2:
        return parsed_components

    test_name = _lab_flowsheet_clean_token(row_dict.get('test_name') or 'Lab Result')
    fallback_info = get_lab_catalog_info(test_name, dob_str=patient_dob, sex=patient_sex) or {}
    if not fallback_info:
        canonical_test = _lab_flowsheet_canonical_name(test_name, panel_title=panel_title)
        if canonical_test != test_name:
            fallback_info = get_lab_catalog_info(canonical_test, dob_str=patient_dob, sex=patient_sex) or {}
            if fallback_info:
                test_name = canonical_test

    explicit_flag = row_dict.get('result_flag') or row_dict.get('abnormal_flag') or ''
    flag = _lab_flowsheet_compute_flag(raw_text, catalog_info=fallback_info, explicit_flag=explicit_flag)
    return [{
        'display_name': test_name,
        'canonical_name': test_name,
        'value': raw_text or '-',
        'units': fallback_info.get('units') or '',
        'reference_range': fallback_info.get('ref_range_disp') or '',
        'flag': flag,
        'value_class': _lab_flowsheet_value_class(flag),
        'flag_badge_class': _lab_flowsheet_flag_badge_class(flag),
        'sort_rank': _LAB_COMMON_TEST_ORDER.get(test_name, 9999),
    }]


def _lab_flowsheet_header_meta(sample_ts_raw: str, reported_ts_raw: str = '') -> dict:
    sample_text = format_dt_local(sample_ts_raw) or str(sample_ts_raw or '')
    reported_text = format_dt_local(reported_ts_raw) or str(reported_ts_raw or '')

    def _split_parts(text_value: str):
        text_value = _lab_flowsheet_clean_token(text_value)
        if not text_value:
            return '-', ''
        parts = text_value.split(' ')
        if len(parts) >= 2:
            return parts[0], parts[1][:5]
        return text_value, ''

    date_label, time_label = _split_parts(sample_text)
    _reported_date, reported_time = _split_parts(reported_text)
    return {
        'key': str(sample_ts_raw or reported_ts_raw or ''),
        'sort_key': str(sample_ts_raw or reported_ts_raw or ''),
        'date_label': date_label,
        'time_label': time_label,
        'reported_time': reported_time,
        'sample_label': sample_text,
        'reported_label': reported_text,
    }


def _lab_flowsheet_test_sort_key(test_row: dict):
    name = _lab_flowsheet_clean_token(test_row.get('canonical_name') or test_row.get('display_name') or '')
    return (
        int(test_row.get('sort_rank') or 9999),
        name.lower(),
    )


def _lab_flowsheet_build_context(visit_id: str) -> dict:
    db = get_db()
    cur = db.cursor()

    try:
        visit_row = cur.execute(
            """
            SELECT v.visit_id,
                   v.status,
                   v.created_at,
                   v.location,
                   v.bed_no,
                   p.name,
                   p.mrn,
                   p.id_number,
                   p.dob,
                   p.sex,
                   p.insurance,
                   p.insurance_no
            FROM visits v
            JOIN patients p ON p.id = v.patient_id
            WHERE v.visit_id = ?
            LIMIT 1
            """,
            (visit_id,),
        ).fetchone()
    except Exception as visit_exc:
        _log_critical_exception(f'Lab flowsheet visit lookup failed for visit={visit_id}', visit_exc)
        raise

    visit_dict = _row_to_dict(visit_row, cur) or {}
    if not visit_dict:
        return {'patient': None, 'panels': [], 'has_results': False}

    patient_dob = visit_dict.get('dob') or ''
    patient_sex = visit_dict.get('sex') or ''

    try:
        result_rows = cur.execute(
            """
            SELECT lr.id,
                   lr.visit_id,
                   lr.source_order_id,
                   lr.test_name,
                   lr.status,
                   lr.result_text,
                   lr.requested_at,
                   lr.collected_at,
                   lr.reported_at,
                   lr.reported_by,
                   co.lab_orders AS source_lab_orders
            FROM lab_requests lr
            LEFT JOIN clinical_orders co ON co.id = lr.source_order_id
            WHERE lr.visit_id = ?
              AND UPPER(COALESCE(lr.status, '')) = 'REPORTED'
            ORDER BY COALESCE(lr.collected_at, lr.reported_at, lr.requested_at) DESC,
                     lr.reported_at DESC,
                     lr.id DESC
            """,
            (visit_id,),
        ).fetchall() or []
    except Exception as rows_exc:
        _log_critical_exception(f'Lab flowsheet result lookup failed for visit={visit_id}', rows_exc)
        raise

    panel_store = _LabOrderedDict()

    for raw_row in result_rows:
        row_dict = _row_to_dict(raw_row, cur) or {}
        try:
            enrich_lab_request_row(row_dict, patient_dob=patient_dob, patient_sex=patient_sex)
        except Exception as enrich_exc:
            _log_noncritical_exception(
                f"Lab flowsheet enrichment failed for visit={visit_id} request={row_dict.get('id')}",
                enrich_exc,
            )

        catalog_info = get_lab_catalog_info(
            row_dict.get('test_name') or '',
            dob_str=patient_dob,
            sex=patient_sex,
        ) or {}
        panel_title = _lab_flowsheet_panel_title(
            row_dict,
            catalog_info,
            patient_dob=patient_dob,
            patient_sex=patient_sex,
        )
        panel_label = panel_title or 'Other Labs'
        panel_category = _lab_flowsheet_category_label(catalog_info.get('category') or '', test_name=row_dict.get('test_name') or '')
        panel_rank = _LAB_FLOWSHEET_CATEGORY_ORDER.get(panel_category, 9999)
        sample_ts_raw = row_dict.get('collected_at') or row_dict.get('reported_at') or row_dict.get('requested_at') or ''
        reported_ts_raw = row_dict.get('reported_at') or ''
        column_meta = _lab_flowsheet_header_meta(sample_ts_raw, reported_ts_raw)
        column_key = column_meta.get('key') or f"request-{row_dict.get('id')}"

        panel_entry = panel_store.get(panel_label)
        if panel_entry is None:
            panel_entry = {
                'title': panel_label,
                'subtitle': panel_category,
                'sort_rank': panel_rank,
                'columns_map': _LabOrderedDict(),
                'tests_map': _LabOrderedDict(),
            }
            panel_store[panel_label] = panel_entry

        if column_key not in panel_entry['columns_map']:
            panel_entry['columns_map'][column_key] = column_meta

        parsed_components = _lab_flowsheet_parse_result_row(
            row_dict,
            panel_title=panel_label,
            patient_dob=patient_dob,
            patient_sex=patient_sex,
        )

        for component in parsed_components:
            display_name = _lab_flowsheet_clean_token(component.get('display_name') or row_dict.get('test_name') or 'Lab Result')
            canonical_name = _lab_flowsheet_clean_token(component.get('canonical_name') or display_name)
            test_key = canonical_name or display_name
            test_entry = panel_entry['tests_map'].get(test_key)
            if test_entry is None:
                test_entry = {
                    'display_name': display_name,
                    'canonical_name': canonical_name,
                    'units': component.get('units') or '',
                    'sort_rank': component.get('sort_rank') or 9999,
                    'cells': {},
                }
                panel_entry['tests_map'][test_key] = test_entry
            elif not test_entry.get('units') and component.get('units'):
                test_entry['units'] = component.get('units') or ''

            if column_key not in test_entry['cells']:
                test_entry['cells'][column_key] = {
                    'value': component.get('value') or '-',
                    'reference_range': component.get('reference_range') or '',
                    'flag': component.get('flag') or '',
                    'value_class': component.get('value_class') or 'lab-value-normal',
                    'flag_badge_class': component.get('flag_badge_class') or 'text-bg-light text-dark border',
                    'reported_by': row_dict.get('reported_by') or '',
                    'reported_at': column_meta.get('reported_label') or '',
                }

    panels = []
    for panel_entry in sorted(
        panel_store.values(),
        key=lambda item: (item.get('sort_rank') or 9999, _lab_flowsheet_clean_token(item.get('title') or '').lower()),
    ):
        columns = sorted(
            panel_entry.get('columns_map', {}).values(),
            key=lambda item: str(item.get('sort_key') or ''),
            reverse=True,
        )
        tests = sorted(
            panel_entry.get('tests_map', {}).values(),
            key=_lab_flowsheet_test_sort_key,
        )
        result_count = sum(len(test.get('cells') or {}) for test in tests)
        panels.append({
            'title': panel_entry.get('title') or 'Other Labs',
            'subtitle': panel_entry.get('subtitle') or 'Reported results',
            'columns': columns,
            'tests': tests,
            'column_count': len(columns),
            'result_count': result_count,
        })

    back_url = url_for('patient_details', visit_id=visit_id)
    return {
        'patient': visit_dict,
        'panels': panels,
        'has_results': bool(panels),
        'back_url': back_url,
    }


@app.route('/lab_results/<visit_id>')
@login_required
def lab_results_view(visit_id):
    try:
        ctx = _lab_flowsheet_build_context(visit_id)
    except Exception as view_exc:
        _log_critical_exception(f'Lab flowsheet render failed for visit={visit_id}', view_exc)
        flash('Unable to load the lab results flowsheet right now. The issue has been logged.', 'danger')
        try:
            return redirect(url_for('patient_details', visit_id=visit_id))
        except Exception as redirect_exc:
            _log_noncritical_exception(
                f'Lab flowsheet fallback redirect failed for visit={visit_id}',
                redirect_exc,
            )
            abort(500)

    if not (ctx or {}).get('patient'):
        flash('Visit not found.', 'danger')
        return redirect(url_for('lab_board'))

    return render_template('lab_results_view.html', **ctx)


