def _normalize_board_physician_filter(value):
    s = str(value or "").strip()
    if not s:
        return ""
    try:
        s = re.sub(r"^\s*dr\.?\s*", "", s, flags=re.I)
        s = re.sub(r"\s+", " ", s).strip()
    except Exception:
        s = s.strip()
    return s


def _append_assigned_physician_filter_sql(where_sql, params, physician_value, visit_alias="v"):
    """Append a forgiving Assigned Physician filter using visits.assigned_doctor.

    The project increasingly stores readable physician names in visits.assigned_doctor,
    so a normalized LIKE filter works for current data while remaining safe for SQLite
    and PostgreSQL.
    """
    raw = str(physician_value or "").strip()
    norm = _normalize_board_physician_filter(raw)

    terms = []
    for term in (raw, norm):
        t = str(term or "").strip()
        if not t:
            continue
        if not any(t.lower() == existing.lower() for existing in terms):
            terms.append(t)

    if not terms:
        return where_sql, params

    clauses = []
    out_params = list(params or [])
    for term in terms:
        clauses.append(f"UPPER(COALESCE({visit_alias}.assigned_doctor,'')) LIKE ?")
        out_params.append(f"%{term.upper()}%")

    return where_sql + " AND (" + " OR ".join(clauses) + ")", out_params


def _board_collect_assigned_physician_options(visits):
    seen = set()
    out = []
    for row in visits or []:
        label = ""
        try:
            label = (
                row.get("assigned_doctor_label")
                or row.get("assigned_doctor_display")
                or row.get("assigned_doctor")
                or ""
            )
        except Exception:
            label = ""
        label = str(label or "").strip()
        if not label:
            continue
        key = _normalize_board_physician_filter(label).lower()
        if not key or key in seen:
            continue
        seen.add(key)
        out.append(label)
    try:
        out.sort(key=lambda item: _normalize_board_physician_filter(item).lower())
    except Exception:
        pass
    return out


def _lab_board_fetch_rows_for_visit(visit_id):
    visit_id = str(visit_id or "").strip()
    if not visit_id:
        return [], {}, 0, 0

    cur = get_db().cursor()
    rows_raw = cur.execute(
        """
        SELECT lr.*,
               v.visit_id,
               p.name,
               p.mrn,
               p.id_number,
               p.dob AS patient_dob,
               p.sex AS patient_sex
          FROM lab_requests lr
          JOIN visits v ON v.visit_id = lr.visit_id
          JOIN patients p ON p.id = v.patient_id
         WHERE v.visit_id = ?
         ORDER BY lr.requested_at ASC, lr.id ASC
        """,
        (visit_id,),
    ).fetchall()

    rows = []
    status_counts = {}
    for r in rows_raw or []:
        try:
            d = dict(r)
        except Exception:
            try:
                d = {k: r[k] for k in r.keys()}
            except Exception:
                d = {}

        st = str(d.get("status") or "").strip().upper()
        status_counts[st] = status_counts.get(st, 0) + 1

        req_ts = d.get("requested_at")
        rep_ts = d.get("reported_at")
        mins = calc_minutes_between(req_ts, rep_ts) if (st == "REPORTED" and rep_ts) else calc_minutes_between(req_ts, None)
        d["age_minutes"] = mins
        if mins is None:
            d["age_text"] = ""
            d["age_level"] = ""
        else:
            try:
                mins_int = int(mins)
            except Exception:
                mins_int = mins
            hours = mins_int // 60 if isinstance(mins_int, int) else 0
            mm = mins_int % 60 if isinstance(mins_int, int) else 0
            d["age_text"] = f"{hours}h {mm:02d}m" if hours else f"{mm}m"
            if st in ("REQUESTED", "COLLECTED", "RECEIVED", "IN_LAB"):
                if mins_int >= 120:
                    d["age_level"] = "long"
                elif mins_int >= 60:
                    d["age_level"] = "medium"
                else:
                    d["age_level"] = "short"
            else:
                d["age_level"] = ""

        d["collected_at"] = d.get("collected_at")
        d["received_at"] = d.get("received_at")
        d["in_lab_at"] = d.get("in_lab_at")

        try:
            enrich_lab_request_row(
                d,
                patient_dob=d.get("patient_dob") or "",
                patient_sex=d.get("patient_sex") or "",
            )
        except Exception:
            pass

        rows.append(d)

    pending_count = (
        status_counts.get("REQUESTED", 0)
        + status_counts.get("COLLECTED", 0)
        + status_counts.get("RECEIVED", 0)
        + status_counts.get("IN_LAB", 0)
    )
    reported_count = status_counts.get("REPORTED", 0)
    return rows, status_counts, pending_count, reported_count


def _extract_lab_visit_fragment_from_page(html, visit_id):
    visit_id = str(visit_id or "").strip()
    if not html or not visit_id:
        return ""
    vid = re.escape(visit_id)
    group_match = re.search(
        rf'<tr class="lab-group-row"[^>]*data-visit="{vid}"[^>]*>.*?</tr>',
        html,
        flags=re.S,
    )
    if not group_match:
        return ""
    test_rows = re.findall(
        rf'<tr class="lab-test-row[^\"]*"[^>]*data-visit="{vid}"[^>]*>.*?</tr>',
        html,
        flags=re.S,
    )
    parts = [group_match.group(0)] + list(test_rows or [])
    return "\n".join(parts)


if "lab_board_visit_fragment" not in app.view_functions:

    @app.route("/lab_board/visit_fragment/<visit_id>")
    @login_required
    def lab_board_visit_fragment(visit_id):
        visit_id = str(visit_id or "").strip()
        if not visit_id:
            return Response("Missing visit_id", status=400)

        rows, status_counts, pending_count, reported_count = _lab_board_fetch_rows_for_visit(visit_id)
        if not rows:
            return Response("Visit not found", status=404)

        html = render_template(
            "lab_board.html",
            rows=rows,
            status_filter="ALL",
            q=visit_id,
            date_from="",
            date_to="",
            status_counts=status_counts,
            pending_count=pending_count,
            reported_count=reported_count,
        )
        fragment = _extract_lab_visit_fragment_from_page(html, visit_id)
        if not fragment:
            return Response("Visit fragment not found", status=404)
        return Response(fragment, mimetype="text/html")


