try:
    _SEARCH_PATIENTS_BASE_V3 = globals().get("search_patients")

    @login_required
    def search_patients_perf_cached_v3():
        try:
            ensure_patients_mrn_schema()
        except Exception:
            pass

        query = (request.args.get("q", "") or "").strip()
        visit_f = (request.args.get("visit_id", "") or "").strip()
        user_f = (request.args.get("user", "") or "").strip()
        dfrom = (request.args.get("date_from", "") or "").strip()
        dto = (request.args.get("date_to", "") or "").strip()
        raw_scan_code = request.args.get("scan_code", "")
        scan_code = normalize_scan_code(raw_scan_code)
        scan_auto_open = request.args.get("scan_auto_open") == "1"

        # Scanner / auto-open flow is correctness-sensitive; keep the original logic.
        if (scan_code or raw_scan_code or scan_auto_open) and callable(_SEARCH_PATIENTS_BASE_V3):
            return _SEARCH_PATIENTS_BASE_V3()

        page, per_page, offset = get_page_args(25)
        ttl = _cfg_float_runtime("SEARCH_PATIENTS_CACHE_SECONDS", 15.0)
        cache_key = (
            "search_patients_v3",
            str(query or ""),
            str(visit_f or ""),
            str(user_f or ""),
            str(dfrom or ""),
            str(dto or ""),
            int(page),
            int(per_page),
            str(DB_ENGINE or ""),
        )

        def _date_floor(d: str) -> str:
            return f"{d} 00:00:00"

        def _date_ceil_excl(d: str) -> str:
            try:
                dt = datetime.strptime(d, "%Y-%m-%d") + timedelta(days=1)
                return dt.strftime("%Y-%m-%d 00:00:00")
            except Exception:
                return f"{d} 23:59:59"

        def _row_to_mapping(row):
            if row is None:
                return None
            try:
                return dict(row)
            except Exception:
                try:
                    return _row_to_dict(row) or row
                except Exception:
                    return row

        def _compute():
            cur = get_db().cursor()
            sql = """
                SELECT v.visit_id, v.queue_no, v.triage_status, v.triage_cat, v.status, v.payment_details, v.created_at, v.created_by,
                       v.assigned_doctor,
                       p.name, p.mrn, p.id_number, p.phone, p.insurance, p.insurance_no
                FROM visits v
                JOIN patients p ON p.id = v.patient_id
                WHERE 1=1
            """
            params = []

            if query:
                like = f"%{query}%"
                if DB_ENGINE == "postgres":
                    sql += " AND (v.visit_id ILIKE ? OR to_tsvector('simple', coalesce(p.name,'') || ' ' || coalesce(p.mrn,'') || ' ' || coalesce(p.id_number,'') || ' ' || coalesce(p.phone,'') || ' ' || coalesce(p.insurance,'') || ' ' || coalesce(p.insurance_no,'')) @@ plainto_tsquery('simple', ?))"
                    params += [like, query]
                elif sqlite_fts_available("patients_fts"):
                    ftsq = fts5_query(query)
                    sql += " AND (v.visit_id LIKE ? OR p.id IN (SELECT rowid FROM patients_fts WHERE patients_fts MATCH ?) OR p.name LIKE ? OR p.mrn LIKE ? OR p.id_number LIKE ? OR p.phone LIKE ? OR p.insurance LIKE ? OR p.insurance_no LIKE ?)"
                    params += [like, ftsq, like, like, like, like, like, like]
                else:
                    sql += " AND (p.name LIKE ? OR p.mrn LIKE ? OR p.id_number LIKE ? OR p.phone LIKE ? OR p.insurance LIKE ? OR p.insurance_no LIKE ? OR v.visit_id LIKE ?)"
                    params += [like, like, like, like, like, like, like]

            if visit_f:
                if DB_ENGINE == "postgres":
                    sql += " AND v.visit_id ILIKE ?"
                else:
                    sql += " AND v.visit_id LIKE ?"
                params.append(f"%{visit_f}%")

            if user_f:
                sql += " AND v.created_by=?"
                params.append(user_f)

            if dfrom:
                sql += " AND v.created_at >= ?"
                params.append(_date_floor(dfrom))
            if dto:
                sql += " AND v.created_at < ?"
                params.append(_date_ceil_excl(dto))

            count_sql = "SELECT COUNT(*) FROM (" + sql + ") AS q_count"
            total_row = cur.execute(count_sql, params).fetchone()
            try:
                total = int((total_row[0] if not hasattr(total_row, 'get') else total_row.get('count', total_row.get('cnt', 0))) or 0)
            except Exception:
                try:
                    total = int(total_row[0])
                except Exception:
                    total = 0
            pages = max(1, (int(total or 0) + int(per_page or 1) - 1) // int(per_page or 1))

            rows = cur.execute(
                sql + " ORDER BY v.created_at DESC, v.id DESC LIMIT ? OFFSET ?",
                params + [per_page, offset],
            ).fetchall()
            results = []
            for row in rows or []:
                try:
                    results.append(dict(row))
                except Exception:
                    results.append(_row_to_mapping(row))

            users_rows = cur.execute(
                "SELECT DISTINCT created_by FROM visits WHERE created_by IS NOT NULL AND TRIM(COALESCE(created_by,'')) <> '' ORDER BY created_by"
            ).fetchall()
            users = []
            for row in users_rows or []:
                try:
                    val = row.get("created_by")
                except Exception:
                    try:
                        val = row[0]
                    except Exception:
                        val = None
                if val is None:
                    continue
                sval = str(val).strip()
                if sval:
                    users.append({"created_by": sval})

            return {
                "results": results,
                "users": users,
                "total": int(total or 0),
                "pages": int(pages or 1),
            }

        if ttl and ttl > 0:
            ctx = _SEARCH_PATIENTS_CACHE_V3.get_or_compute(cache_key, ttl, _compute)
        else:
            ctx = _compute()

        try:
            close_db(None)
        except Exception:
            pass

        return render_template(
            "search.html",
            q=query,
            results=ctx.get("results", []),
            visit_f=visit_f,
            user_f=user_f,
            dfrom=dfrom,
            dto=dto,
            users=ctx.get("users", []),
            scan_code=scan_code,
            scan_auto_open=scan_auto_open,
            scan_visit=None,
            page=page,
            pages=ctx.get("pages", 1),
            per_page=per_page,
            total=ctx.get("total", 0),
        )

    app.view_functions["search_patients"] = search_patients_perf_cached_v3
except Exception as _search_patients_perf_cached_v3_exc:
    try:
        _log_noncritical_exception(
            "Search landing cache patch v3 failed",
            _search_patients_perf_cached_v3_exc,
        )
    except Exception:
        pass


