def _patch_template_text_v20260420(template_name, replacements):
    template_text = TEMPLATES.get(template_name, "") or ""
    original_text = template_text
    for old_text, new_text in replacements:
        if old_text in template_text:
            template_text = template_text.replace(old_text, new_text)
    if template_text != original_text:
        TEMPLATES[template_name] = template_text


