try:
    def _board_lab_where_sql_v20260421(status_filter: str, q: str, dfrom: str, dto: str, physician_f: str, *, include_patient_join: bool):
        status_filter = (status_filter or 'ALL').strip().upper()
        q = (q or '').strip()
        q_normalized = normalize_scan_code(q) if q else ''
        dfrom = (dfrom or '').strip()
        dto = (dto or '').strip()
        physician_f = (physician_f or '').strip()

        def _date_floor(d: str) -> str:
            return f"{d} 00:00:00"

        def _date_ceil_excl(d: str) -> str:
            try:
                dt = datetime.strptime(d, '%Y-%m-%d') + timedelta(days=1)
                return dt.strftime('%Y-%m-%d 00:00:00')
            except Exception:
                return f"{d} 23:59:59"

        joins = []
        if physician_f or include_patient_join:
            joins.append('JOIN visits v ON v.visit_id = lr.visit_id')
        if include_patient_join:
            joins.append('JOIN patients p ON p.id = v.patient_id')

        where = ['1=1']
        params = []

        if status_filter == 'PENDING':
            where.append("lr.status IN ('REQUESTED','COLLECTED','RECEIVED','IN_LAB')")
        elif status_filter == 'REPORTED':
            where.append("lr.status='REPORTED'")
        elif status_filter != 'ALL':
            where.append('lr.status=?')
            params.append(status_filter)

        if dfrom:
            where.append('lr.requested_at >= ?')
            params.append(_date_floor(dfrom))
        if dto:
            where.append('lr.requested_at < ?')
            params.append(_date_ceil_excl(dto))

        if q and include_patient_join:
            search_terms = []
            for term in (q, q_normalized):
                term = (term or '').strip()
                if not term or term in search_terms:
                    continue
                search_terms.append(term)
            search_clauses = []
            for idx, term in enumerate(search_terms):
                like = f"%{term}%"
                if idx == 0:
                    if DB_ENGINE == 'postgres':
                        search_clauses.append('(p.name ILIKE ? OR p.mrn ILIKE ? OR p.id_number ILIKE ? OR v.visit_id ILIKE ? OR lr.test_name ILIKE ?)')
                    else:
                        search_clauses.append('(p.name LIKE ? OR p.mrn LIKE ? OR p.id_number LIKE ? OR v.visit_id LIKE ? OR lr.test_name LIKE ?)')
                    params.extend([like, like, like, like, like])
                else:
                    if DB_ENGINE == 'postgres':
                        search_clauses.append('(p.mrn ILIKE ? OR p.id_number ILIKE ? OR v.visit_id ILIKE ?)')
                    else:
                        search_clauses.append('(p.mrn LIKE ? OR p.id_number LIKE ? OR v.visit_id LIKE ?)')
                    params.extend([like, like, like])
            if search_clauses:
                where.append('(' + ' OR '.join(search_clauses) + ')')

        if physician_f:
            _sql = 'SELECT 1 FROM visits v WHERE 1=1'
            _params = []
            _sql, _params = _append_assigned_physician_filter_sql(_sql, _params, physician_f, visit_alias='v')
            _where_tail = _sql.split('WHERE 1=1', 1)[1]
            if _where_tail.strip():
                where.append('EXISTS (SELECT 1 FROM visits v WHERE v.visit_id = lr.visit_id ' + _where_tail + ')')
                params.extend(_params)

        return '\n'.join(joins), ' AND '.join(where), params

    def _lab_assigned_physician_options_v20260421(status_filter: str, q: str, dfrom: str, dto: str):
        include_patient_join = bool((q or '').strip())
        joins, where_sql, params = _board_lab_where_sql_v20260421(status_filter, q, dfrom, dto, '', include_patient_join=include_patient_join)
        cur = get_db().cursor()
        sql = f"""
            SELECT DISTINCT COALESCE(v.assigned_doctor, '') AS assigned_doctor
            FROM lab_requests lr
            JOIN visits v ON v.visit_id = lr.visit_id
            {'JOIN patients p ON p.id = v.patient_id' if include_patient_join else ''}
            WHERE {where_sql}
              AND COALESCE(v.assigned_doctor, '') <> ''
            ORDER BY assigned_doctor
        """
        rows = cur.execute(sql, params).fetchall() or []
        out = []
        seen = set()
        for r in rows:
            try:
                val = (r['assigned_doctor'] or '').strip()
            except Exception:
                val = (r[0] or '').strip() if r else ''
            if val and val not in seen:
                seen.add(val)
                out.append(val)
        return out

    def _lab_board_page_payload_v20260421(status_filter: str, q: str, dfrom: str, dto: str, physician_f: str, page: int, per_page: int):
        include_patient_join = bool((q or '').strip())
        joins_for_filter, where_sql, params = _board_lab_where_sql_v20260421(status_filter, q, dfrom, dto, physician_f, include_patient_join=include_patient_join)
        cur = get_db().cursor()

        counts_sql = f"SELECT lr.status, COUNT(*) AS c FROM lab_requests lr {joins_for_filter} WHERE {where_sql} GROUP BY lr.status"
        count_rows = cur.execute(counts_sql, params).fetchall() or []
        status_counts = {}
        for r in count_rows:
            try:
                st = str(r['status'] or '')
                c = int(r['c'] or 0)
            except Exception:
                st = str(r[0] or '')
                c = int(r[1] or 0)
            status_counts[st] = c
        total_count = sum(int(v or 0) for v in status_counts.values())
        pending_count = sum(status_counts.get(k, 0) for k in ('REQUESTED', 'COLLECTED', 'RECEIVED', 'IN_LAB'))
        reported_count = status_counts.get('REPORTED', 0)

        page = max(1, int(page or 1))
        per_page = max(1, min(100, int(per_page or 50)))

        order_sql = " CASE WHEN lr.status IN ('REQUESTED','COLLECTED','RECEIVED','IN_LAB') THEN 0 ELSE 1 END, lr.requested_at ASC, lr.id ASC "

        # --- ROOTFIX 20260601: paginate by VISIT (case), not by individual lab
        # request rows. The board groups every visit's lab tests into a single
        # case card, so paginating per-request (LIMIT 25 rows) collapsed a whole
        # page into only a handful of visible cases. We now count and page by
        # distinct visit and then fetch *all* lab requests for the visits shown
        # on the current page. Default page size is 50 cases. ---
        visit_count_sql = (
            "SELECT COUNT(*) AS c FROM ("
            f"SELECT lr.visit_id FROM lab_requests lr {joins_for_filter} "
            f"WHERE {where_sql} GROUP BY lr.visit_id) AS _vc"
        )
        try:
            _vc_row = cur.execute(visit_count_sql, params).fetchone()
            if _vc_row is None:
                total_visits = 0
            else:
                try:
                    total_visits = int(_vc_row['c'] or 0)
                except Exception:
                    total_visits = int(_vc_row[0] or 0)
        except Exception:
            total_visits = 0

        # Board "Total" reflects the number of cases (visits), matching what the
        # user actually sees on screen.
        total_count = total_visits

        pages = max(1, (total_visits + per_page - 1) // per_page) if per_page else 1
        if page > pages:
            page = pages
        offset = (page - 1) * per_page

        # Order visits by their most urgent pending request, mirroring the old
        # per-request ordering, then take the slice for this page.
        visit_page_sql = f"""
            SELECT lr.visit_id AS vid,
                   MIN(CASE WHEN lr.status IN ('REQUESTED','COLLECTED','RECEIVED','IN_LAB') THEN 0 ELSE 1 END) AS prio,
                   MIN(lr.requested_at) AS first_req,
                   MIN(lr.id) AS first_id
            FROM lab_requests lr {joins_for_filter}
            WHERE {where_sql}
            GROUP BY lr.visit_id
            ORDER BY prio ASC, first_req ASC, first_id ASC
            LIMIT ? OFFSET ?
        """
        vid_rows = cur.execute(visit_page_sql, list(params) + [per_page, offset]).fetchall() or []
        page_visit_ids = []
        for _vr in vid_rows:
            try:
                page_visit_ids.append(_vr['vid'])
            except Exception:
                page_visit_ids.append(_vr[0])

        if not page_visit_ids:
            rows_raw = []
        else:
            _ph = ','.join(['?'] * len(page_visit_ids))
            page_sql = f"""
                SELECT lr.*, v.visit_id,
                       COALESCE(v.created_at,'') AS visit_created_at,
                       COALESCE(v.clinic,'ED') AS clinic,
                       v.assigned_doctor,
                       p.name,
                       p.mrn,
                       p.id_number,
                       p.dob AS patient_dob,
                       p.sex AS patient_sex
                FROM lab_requests lr
                JOIN visits v ON v.visit_id = lr.visit_id
                JOIN patients p ON p.id = v.patient_id
                WHERE lr.visit_id IN ({_ph})
                ORDER BY {order_sql}
            """
            rows_raw = cur.execute(page_sql, list(page_visit_ids)).fetchall() or []
        _lab_page_visit_order = {str(_v): _i for _i, _v in enumerate(page_visit_ids)}

        full_by_code, code_by_label = _clinic_display_maps()
        rows = []
        for r in rows_raw:
            try:
                d = dict(r)
            except Exception:
                d = _row_to_dict(r, cur) or {}
            clinic_raw = str(d.get('clinic') or 'ED').strip()
            clinic_key = clinic_raw.upper()
            clinic_code = clinic_key if clinic_key in full_by_code else code_by_label.get(clinic_key, clinic_key or 'ED')
            d['clinic_short'] = clinic_code or 'ED'
            d['clinic_display'] = full_by_code.get(clinic_code, clinic_raw or 'ED')
            st = d.get('status') or ''
            req_ts = d.get('requested_at')
            rep_ts = d.get('reported_at')
            mins = calc_minutes_between(req_ts, rep_ts) if st == 'REPORTED' and rep_ts else calc_minutes_between(req_ts, None)
            d['age_minutes'] = mins
            if mins is None:
                d['age_text'] = ''
                d['age_level'] = ''
            else:
                try:
                    mins_int = int(mins)
                except Exception:
                    mins_int = mins
                hours = mins_int // 60 if isinstance(mins_int, int) else 0
                mm = mins_int % 60 if isinstance(mins_int, int) else 0
                d['age_text'] = f"{hours}h {mm:02d}m" if hours else f"{mm}m"
                if st in ('REQUESTED', 'COLLECTED', 'RECEIVED', 'IN_LAB'):
                    if mins_int >= 120:
                        d['age_level'] = 'long'
                    elif mins_int >= 60:
                        d['age_level'] = 'medium'
                    else:
                        d['age_level'] = 'short'
                else:
                    d['age_level'] = ''
            d['assigned_doctor_display'] = d.get('assigned_doctor') or ''
            try:
                enrich_lab_request_row(d, patient_dob=d.get('patient_dob') or '', patient_sex=d.get('patient_sex') or '')
            except Exception:
                pass
            rows.append(d)

        # Keep every visit's lab tests contiguous and in the same case order the
        # page slice was selected in (stable sort preserves the per-visit
        # status/requested_at ordering already applied by SQL).
        try:
            _big = len(_lab_page_visit_order) + 1
            rows.sort(key=lambda _d: _lab_page_visit_order.get(str(_d.get('visit_id') or ''), _big))
        except Exception:
            pass

        assigned_physicians = _lab_assigned_physician_options_v20260421(status_filter, q, dfrom, dto)
        return {
            'rows': rows,
            'status_counts': status_counts,
            'pending_count': pending_count,
            'reported_count': reported_count,
            'total_count': total_count,
            'assigned_physicians': assigned_physicians,
            'page': page,
            'pages': pages,
            'per_page': per_page,
            'has_prev': page > 1,
            'has_next': page < pages,
        }

    @login_required
    def lab_board_loadtest_fast_v20260421():
        status_filter = (request.args.get('status', 'ALL') or 'ALL').strip().upper()
        physician_f = (request.args.get('assigned_physician', '') or '').strip()
        q = (request.args.get('q', '') or '').strip()
        dfrom = (request.args.get('date_from', '') or '').strip()
        dto = (request.args.get('date_to', '') or '').strip()
        page, per_page, _offset = get_page_args(50)
        # ROOTFIX 20260601: default board cache to 0s so a workflow action
        # (collect / receive / start in lab) is reflected on the very next
        # render instead of being masked by a stale cached page that made the
        # button look like it "did nothing" and forced repeated clicks.
        ttl = _cfg_float_runtime('LAB_BOARD_CACHE_SECONDS', 0.0)
        cache_key = ('lab_board_fast_v20260421', status_filter, physician_f, q, dfrom, dto, int(page), int(per_page), str(DB_ENGINE or ''))
        if ttl and ttl > 0:
            ctx = _LAB_BOARD_CACHE.get_or_compute(
                cache_key,
                ttl,
                lambda: _lab_board_page_payload_v20260421(status_filter, q, dfrom, dto, physician_f, page, per_page),
            )
        else:
            ctx = _lab_board_page_payload_v20260421(status_filter, q, dfrom, dto, physician_f, page, per_page)
        return render_template(
            'lab_board.html',
            rows=ctx.get('rows', []),
            status_filter=status_filter,
            physician_f=physician_f,
            assigned_physicians=ctx.get('assigned_physicians', []),
            q=q,
            date_from=dfrom,
            date_to=dto,
            status_counts=ctx.get('status_counts', {}),
            pending_count=ctx.get('pending_count', 0),
            reported_count=ctx.get('reported_count', 0),
            total_count=ctx.get('total_count', 0),
            page=ctx.get('page', page),
            pages=ctx.get('pages', 1),
            per_page=ctx.get('per_page', per_page),
            has_prev=ctx.get('has_prev', False),
            has_next=ctx.get('has_next', False),
        )

    app.view_functions['lab_board'] = lab_board_loadtest_fast_v20260421
    globals()['lab_board'] = lab_board_loadtest_fast_v20260421
except Exception as _lab_board_loadtest_fix_exc:
    try:
        _log_noncritical_exception('Final lab board load-test fast patch failed', _lab_board_loadtest_fix_exc)
    except Exception:
        pass


