# ============================================================
# FINAL_FIXSET_20260423D_ATTACHMENT_SYNC
# - Make Edit Patient ID / Eligibility uploads immediately visible
#   by saving synchronously instead of queueing in the background.
# ============================================================
try:
    _FINAL_FIXSET4_TAG = "FINAL_FIXSET_20260423D"

    def _save_attachment_sync_immediate(visit_id, file_storage, filename, actor, *, context="attachment"):
        if not file_storage or not getattr(file_storage, "filename", ""):
            return "No file selected."
        if not allowed_file(file_storage.filename):
            return "Attachment file type is not allowed."
        save_path = os.path.join(UPLOAD_FOLDER, filename)
        file_saved = False
        db = get_db()
        try:
            os.makedirs(UPLOAD_FOLDER, exist_ok=True)
            file_storage.save(save_path)
            file_saved = True
            db.execute(
                """
                INSERT INTO attachments (visit_id, filename, uploaded_at, uploaded_by)
                VALUES (?,?,?,?)
                """,
                (
                    visit_id,
                    filename,
                    datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                    actor,
                ),
            )
            db.commit()
            return None
        except Exception as exc:
            _rollback_with_logging(db, f"{_FINAL_FIXSET4_TAG}: {context} sync save")
            if file_saved:
                try:
                    os.remove(save_path)
                except Exception as remove_exc:
                    _log_noncritical_exception(
                        f"{_FINAL_FIXSET4_TAG}: attachment cleanup failed visit_id={visit_id} filename={filename}",
                        remove_exc,
                    )
            _log_critical_exception(
                f"{_FINAL_FIXSET4_TAG}: attachment sync save failed visit_id={visit_id} filename={filename}",
                exc,
            )
            return "Failed to save attachment."

    @login_required
    @role_required("reception", "nurse", "mrd", "admin")
    def upload_id_fixset4(visit_id):
        redirect_target = _fixset2_redirect_target(visit_id)
        file = _fixset3_pick_attachment_file()
        if file is None:
            flash("No file selected.", "danger")
            return redirect(redirect_target)
        if str(getattr(file, "filename", "") or "").strip() == "":
            flash("Please choose a file.", "danger")
            return redirect(redirect_target)
        if not allowed_file(file.filename):
            flash("Invalid file type.", "danger")
            return redirect(redirect_target)

        safe_name = secure_filename(file.filename)
        requested_kind = (request.form.get("attachment_kind") or request.args.get("attachment_kind") or "").strip().lower()
        if requested_kind not in ("elig", "id"):
            requested_kind = _attachment_kind_from_filename(safe_name)

        if requested_kind == "elig":
            filename = f"{visit_id}_{int(datetime.now().timestamp())}_ELIG_{safe_name}"
        elif requested_kind == "id":
            filename = f"{visit_id}_{int(datetime.now().timestamp())}_ID_{safe_name}"
        else:
            filename = f"{visit_id}_{int(datetime.now().timestamp())}_{safe_name}"

        save_err = _save_attachment_sync_immediate(
            visit_id,
            file,
            filename,
            session.get("username"),
            context="upload_id_fixset4",
        )
        if save_err:
            flash(save_err, "danger")
            return redirect(redirect_target)
        try:
            log_action("UPLOAD_ATTACHMENT", visit_id=visit_id, details=filename)
        except Exception as exc:
            _log_noncritical_exception(
                f"{_FINAL_FIXSET4_TAG}: UPLOAD_ATTACHMENT audit failed for visit={visit_id}",
                exc,
            )
        flash("Attachment uploaded successfully.", "success")
        return redirect(redirect_target)

    app.view_functions["upload_id"] = upload_id_fixset4
    globals()["upload_id"] = upload_id_fixset4
except Exception as _final_fixset4_exc:
    _log_critical_exception("FINAL_FIXSET_20260423D_ATTACHMENT_SYNC failed", _final_fixset4_exc)


# ============================================================
# Final Railway-safe runner
# - Kept at the physical end of the file so all hot-patches above are loaded
#   before the web server starts when running: python app.py
# ============================================================
def _run_production_server():
    try:
        bootstrap_once()
    except Exception as _bootstrap_exc:
        try:
            _log_critical_exception("Bootstrap failed before server start", _bootstrap_exc)
        except Exception:
            raise

    host = os.environ.get("HOST", "0.0.0.0")
    try:
        port = int(str(os.environ.get("PORT", "5000")).strip() or "5000")
    except Exception:
        port = 5000

    debug = str(os.environ.get("FLASK_DEBUG", "0")).strip() == "1"
    if debug:
        app.run(host=host, port=port, debug=True)
        return

    try:
        from waitress import serve
    except Exception:
        # Last-resort fallback for minimal Railway images; requirements should
        # include waitress for production.
        app.run(host=host, port=port, debug=False)
        return

    def _as_int(v, default):
        try:
            return int(str(v).strip())
        except Exception:
            return int(default)

    threads = _as_int(os.environ.get("THREADS") or os.environ.get("WAITRESS_THREADS"), 6)
    connection_limit = _as_int(
        os.environ.get("CONNECTION_LIMIT") or os.environ.get("WAITRESS_CONNECTION_LIMIT"),
        1024,
    )
    backlog = _as_int(os.environ.get("BACKLOG") or os.environ.get("WAITRESS_BACKLOG"), 1024)
    channel_timeout = _as_int(
        os.environ.get("CHANNEL_TIMEOUT") or os.environ.get("WAITRESS_CHANNEL_TIMEOUT"),
        120,
    )
    cleanup_interval = _as_int(
        os.environ.get("CLEANUP_INTERVAL") or os.environ.get("WAITRESS_CLEANUP_INTERVAL"),
        30,
    )

    try:
        import select as _waitress_select
        _use_poll_env = os.environ.get("WAITRESS_USE_POLL", "").strip().lower()
        if _use_poll_env in ("1", "true", "yes", "on"):
            use_poll = True
        elif _use_poll_env in ("0", "false", "no", "off"):
            use_poll = False
        else:
            use_poll = bool(hasattr(_waitress_select, "poll")) and int(connection_limit or 0) > 900
    except Exception:
        use_poll = False

    connection_limit_cap = _as_int(
        os.environ.get("WAITRESS_CONNECTION_LIMIT_CAP") or APP_CONFIG.get("WAITRESS_CONNECTION_LIMIT_CAP", 900),
        900,
    )
    if connection_limit_cap < 0:
        connection_limit_cap = 0
    if (not use_poll) and connection_limit_cap > 0 and connection_limit > connection_limit_cap:
        connection_limit = connection_limit_cap

    try:
        serve(
            app,
            host=host,
            port=port,
            threads=threads,
            connection_limit=connection_limit,
            backlog=backlog,
            channel_timeout=channel_timeout,
            cleanup_interval=cleanup_interval,
            asyncore_use_poll=use_poll,
        )
    except TypeError:
        try:
            serve(
                app,
                host=host,
                port=port,
                threads=threads,
                connection_limit=connection_limit,
                backlog=backlog,
                channel_timeout=channel_timeout,
                asyncore_use_poll=use_poll,
            )
        except TypeError:
            serve(
                app,
                host=host,
                port=port,
                threads=threads,
                connection_limit=connection_limit,
                backlog=backlog,
                channel_timeout=channel_timeout,
            )



