def _co_config_active_clause():
    if DB_ENGINE == "postgres":
        return "COALESCE(is_active, TRUE) IS TRUE"
    return "COALESCE(is_active, 1)=1"


def _co_config_bool(value):
    if isinstance(value, bool):
        return value
    try:
        if value is None:
            return False
        if isinstance(value, (int, float)):
            return bool(value)
        return str(value).strip().lower() in ("1", "true", "t", "yes", "y", "on")
    except Exception:
        return False


def _co_config_row_to_dict(row):
    try:
        data = dict(row)
    except Exception:
        data = {}
        try:
            keys = getattr(row, "keys", lambda: [])()
            for k in keys:
                data[k] = row[k]
        except Exception:
            pass
    if data:
        data["is_active"] = _co_config_bool(data.get("is_active"))
    return data


def _co_create_or_repair_config(cur=None, seed_defaults=True):
    """Create/repair the Code Orange configuration table for PostgreSQL/SQLite."""
    cur = cur or get_db().cursor()
    if DB_ENGINE == "postgres":
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS code_orange_config (
                id SERIAL PRIMARY KEY,
                item_category VARCHAR(120) NOT NULL,
                item_name TEXT NOT NULL,
                is_active BOOLEAN DEFAULT TRUE
            )
            """
        )
        cur.execute("ALTER TABLE code_orange_config ADD COLUMN IF NOT EXISTS item_category VARCHAR(120)")
        cur.execute("ALTER TABLE code_orange_config ADD COLUMN IF NOT EXISTS item_name TEXT")
        cur.execute("ALTER TABLE code_orange_config ADD COLUMN IF NOT EXISTS is_active BOOLEAN DEFAULT TRUE")
    else:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS code_orange_config (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                item_category TEXT NOT NULL,
                item_name TEXT NOT NULL,
                is_active INTEGER DEFAULT 1
            )
            """
        )
        try:
            existing = set()
            for r in cur.execute("PRAGMA table_info(code_orange_config)").fetchall():
                try:
                    existing.add(str(r["name"]).lower())
                except Exception:
                    existing.add(str(r[1]).lower())
            if "item_category" not in existing:
                cur.execute("ALTER TABLE code_orange_config ADD COLUMN item_category TEXT")
            if "item_name" not in existing:
                cur.execute("ALTER TABLE code_orange_config ADD COLUMN item_name TEXT")
            if "is_active" not in existing:
                cur.execute("ALTER TABLE code_orange_config ADD COLUMN is_active INTEGER DEFAULT 1")
        except Exception:
            pass
    try:
        cur.execute("CREATE INDEX IF NOT EXISTS idx_code_orange_config_category ON code_orange_config(item_category, is_active)")
    except Exception:
        pass

    if not seed_defaults:
        return
    try:
        count_row = cur.execute("SELECT COUNT(*) AS c FROM code_orange_config").fetchone()
        try:
            total = int(count_row["c"])
        except Exception:
            total = int(count_row[0])
        if total > 0:
            return
    except Exception:
        return

    for category, item_name in CODE_ORANGE_CONFIG_DEFAULTS:
        category = str(category or "").strip()
        item_name = str(item_name or "").strip()
        if not category or not item_name:
            continue
        try:
            cur.execute(
                "INSERT INTO code_orange_config (item_category, item_name, is_active) VALUES (?, ?, ?)",
                (category, item_name, True if DB_ENGINE == "postgres" else 1),
            )
        except Exception:
            # Keep startup/migration resilient; duplicate defaults are harmlessly skipped.
            try:
                cur.connection.rollback()
            except Exception:
                pass


def ensure_code_orange_config_schema(seed_defaults=True):
    """Idempotent Code Orange config schema upgrade used by startup/admin/dashboard."""
    global CODE_ORANGE_CONFIG_READY
    if CODE_ORANGE_CONFIG_READY:
        return True
    db = get_db()
    cur = db.cursor()
    try:
        _co_create_or_repair_config(cur, seed_defaults=seed_defaults)
        db.commit()
        CODE_ORANGE_CONFIG_READY = True
        return True
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass
        raise


def _co_config_rows(cur=None, include_inactive=False):
    try:
        ensure_code_orange_config_schema(seed_defaults=True)
    except Exception:
        pass
    cur = cur or get_db().cursor()
    rows = []
    try:
        where = "" if include_inactive else (" WHERE " + _co_config_active_clause())
        rows = cur.execute(
            f"""
            SELECT id, item_category, item_name, is_active
              FROM code_orange_config
              {where}
             ORDER BY item_category ASC, id ASC
            """
        ).fetchall()
    except Exception:
        rows = []
    return [_co_config_row_to_dict(r) for r in (rows or [])]


def _co_config_grouped(cur=None, include_inactive=False):
    grouped = {}
    for row in _co_config_rows(cur=cur, include_inactive=include_inactive):
        category = str(row.get("item_category") or "").strip()
        item_name = str(row.get("item_name") or "").strip()
        if not category or not item_name:
            continue
        grouped.setdefault(category, []).append(item_name)
    return grouped


def _co_config_items(grouped, category, fallback):
    items = []
    try:
        items = [str(x or "").strip() for x in (grouped or {}).get(category, [])]
        items = [x for x in items if x]
    except Exception:
        items = []
    return items if items else list(fallback or [])


def _co_runtime_location_groups(grouped):
    groups = []
    for default_group, default_items in CODE_ORANGE_LOCATION_GROUPS:
        cat = f"Location - {default_group}"
        items = _co_config_items(grouped, cat, default_items)
        if items:
            groups.append((default_group, items))
    # Preserve any extra admin-defined location groups without code changes.
    try:
        known = {f"Location - {g}" for g, _items in CODE_ORANGE_LOCATION_GROUPS}
        for category, items in (grouped or {}).items():
            if not str(category or "").startswith("Location - ") or category in known:
                continue
            label = str(category).replace("Location - ", "", 1).strip() or "OTHER"
            clean_items = [str(x or "").strip() for x in (items or []) if str(x or "").strip()]
            if clean_items:
                groups.append((label, clean_items))
    except Exception:
        pass
    return groups


def _co_runtime_options(cur=None):
    grouped = _co_config_grouped(cur=cur, include_inactive=False)
    triage_options = _co_config_items(grouped, "Triage", CODE_ORANGE_TRIAGE_OPTIONS)
    zone_options = _co_config_items(grouped, "Destination Zones", CODE_ORANGE_ZONE_OPTIONS)
    disposition_options = [""] + _co_config_items(
        grouped,
        "Disposition",
        [x for x in CODE_ORANGE_DISPOSITION_OPTIONS if str(x or "").strip()],
    )
    location_groups = _co_runtime_location_groups(grouped)
    location_options = [loc for _group, locs in location_groups for loc in locs] + [CODE_ORANGE_MANUAL_LOCATION_LABEL]
    display_groups = []
    for category in CODE_ORANGE_CONFIG_DISPLAY_CATEGORIES:
        items = _co_config_items(grouped, category, [])
        if items:
            display_groups.append({
                "category": category,
                "label": CODE_ORANGE_CONFIG_CATEGORY_LABELS.get(category, category),
                "items": items,
            })
    return {
        "grouped": grouped,
        "display_groups": display_groups,
        "triage_options": triage_options,
        "zone_options": zone_options,
        "location_groups": location_groups,
        "location_options": location_options,
        "disposition_options": disposition_options,
    }


def _co_active_triage_options():
    try:
        return _co_runtime_options().get("triage_options") or list(CODE_ORANGE_TRIAGE_OPTIONS)
    except Exception:
        return list(CODE_ORANGE_TRIAGE_OPTIONS)


def _co_active_zone_options():
    try:
        return _co_runtime_options().get("zone_options") or list(CODE_ORANGE_ZONE_OPTIONS)
    except Exception:
        return list(CODE_ORANGE_ZONE_OPTIONS)


def _co_active_location_options():
    try:
        return _co_runtime_options().get("location_options") or list(CODE_ORANGE_LOCATION_OPTIONS)
    except Exception:
        return list(CODE_ORANGE_LOCATION_OPTIONS)


def _co_active_disposition_options():
    try:
        return _co_runtime_options().get("disposition_options") or list(CODE_ORANGE_DISPOSITION_OPTIONS)
    except Exception:
        return list(CODE_ORANGE_DISPOSITION_OPTIONS)



def _co_now_text():
    """Return Code Orange timestamp in UAE / hospital local time."""
    try:
        return now_display_str("%Y-%m-%d %H:%M:%S") or datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def _co_actor_username(default="SYSTEM"):
    """Return the staff username for Code Orange audit trails."""
    try:
        for key in ("user_name", "username", "user", "email"):
            value = session.get(key)
            if value is not None and str(value).strip():
                return str(value).strip()
    except Exception:
        pass
    return default or "SYSTEM"


def _co_format_local_text(value, fmt="%Y-%m-%d %H:%M:%S"):
    """Display stored Code Orange timestamps in UAE / hospital local time."""
    if value is None:
        return ""
    try:
        s = str(value).strip()
        if not s:
            return ""
    except Exception:
        s = ""
    try:
        d = _parse_to_local_naive(value)
        if d:
            return d.strftime(fmt)
    except Exception:
        pass
    return s


try:
    app.jinja_env.globals["co_format_datetime"] = _co_format_local_text
except Exception:
    pass


def _co_row_get(row, key, default=None):
    if row is None:
        return default
    try:
        v = row[key]
        return default if v is None else v
    except Exception:
        try:
            v = row.get(key)
            return default if v is None else v
        except Exception:
            return default


def _co_bool_text(value):
    s = str(value or "").strip().lower()
    return "Yes" if s in ("1", "true", "yes", "y", "on", "checked") else "No"


def _co_normalize_triage(value):
    s = str(value or "").strip().upper()
    aliases = {
        "IMMEDIATE": "RED",
        "RED AREA": "RED",
        "R": "RED",
        "DELAYED": "YELLOW",
        "YELLOW AREA": "YELLOW",
        "Y": "YELLOW",
        "MINOR": "GREEN",
        "GREEN AREA": "GREEN",
        "G": "GREEN",
        "DECEASED": "BLACK",
        "EXPECTANT": "BLACK",
        "BLACK AREA": "BLACK",
        "B": "BLACK",
    }
    s = aliases.get(s, s)
    triage_options = _co_active_triage_options()
    if s not in triage_options:
        s = "GREEN" if "GREEN" in triage_options else (triage_options[0] if triage_options else "GREEN")
    return s


def _co_normalize_zone(value, triage=None, cbrn=False):
    s = str(value or "").strip()
    zone_options = _co_active_zone_options()
    if s in zone_options:
        return s
    if cbrn:
        preferred = "Decontamination"
        return preferred if preferred in zone_options else (zone_options[0] if zone_options else preferred)
    t = _co_normalize_triage(triage or "GREEN")
    if t == "RED":
        preferred = "Immediate Red Area"
    elif t == "YELLOW":
        preferred = "Delayed Yellow Area"
    elif t == "BLACK":
        preferred = "Black / Deceased Area"
    else:
        preferred = "Minor Green Area"
    return preferred if preferred in zone_options else (zone_options[0] if zone_options else preferred)


def _co_default_zone_for_triage(triage, cbrn=False):
    """Return the suggested Destination Zone for a START triage category.

    This is the operational destination, not the editable current physical
    location. CBRN always goes to Decontamination first.
    """
    return _co_normalize_zone("", triage=triage, cbrn=cbrn)


def _co_default_location_for_triage(triage, cbrn=False):
    """Return the suggested Current Location for special routing only.

    Normal START triage colours (RED/YELLOW/GREEN/BLACK) must not auto-select
    a physical Current Location. Staff choose the actual location manually.
    CBRN remains the only automatic Current Location exception.
    """
    if cbrn:
        return "Decontamination"
    return ""


def _co_normalize_location(value, triage=None, cbrn=False):
    # Hybrid input: predefined locations or free-text manual locations.
    # Selecting the manual sentinel clears the field and lets staff type a custom place.
    s = str(value or "").strip()[:120]
    if s == CODE_ORANGE_MANUAL_LOCATION_LABEL:
        s = ""
    # Do not invent a physical bed/current location from a blank input.
    # New registrations must begin blank; smart defaults are UI suggestions only after staff action.
    return s


def _co_managed_location_values():
    """Return locations that behave like single-occupancy clinical resources."""
    return [loc for loc in _co_active_location_options() if loc and loc != CODE_ORANGE_MANUAL_LOCATION_LABEL]


def _co_is_managed_location(value):
    return _co_normalize_location(value) in set(_co_managed_location_values())


def _co_is_active_for_bed_occupancy(row):
    """True when a live patient should still reserve a Resus/Bed resource."""
    if not row:
        return False
    triage = _co_normalize_triage(_co_row_get(row, "triage_category", "GREEN"))
    if triage == "BLACK":
        return False
    disp = str(_co_row_get(row, "disposition", "") or "").strip().lower()
    if disp in {"d - discharge", "t - transfer", "expired"}:
        return False
    return True


def _co_bed_occupancy_payload(row, location=""):
    if not row:
        return None
    pid = _co_row_get(row, "id", "")
    tag = _co_row_get(row, "hospital_tag_no", "") or _co_row_get(row, "ems_tag_no", "") or str(pid or "")
    return {
        "patient_id": pid,
        "id": pid,
        "location": location or _co_row_get(row, "current_location", "") or "",
        "hospital_tag_no": _co_row_get(row, "hospital_tag_no", "") or "",
        "ems_tag_no": _co_row_get(row, "ems_tag_no", "") or "",
        "tag": tag,
        "patient_name": _co_row_get(row, "patient_name", "") or "Unknown",
        "triage_category": _co_normalize_triage(_co_row_get(row, "triage_category", "GREEN")),
        "current_zone": _co_row_get(row, "current_zone", "") or "",
        "url": _co_patient_dashboard_url(pid),
    }


def _co_location_conflict(cur, incident_id, location, patient_id=None):
    """Return another active patient occupying the same managed location, if any."""
    loc = _co_normalize_location(location)
    if not loc or not _co_is_managed_location(loc):
        return None
    try:
        pid = int(patient_id or 0)
    except Exception:
        pid = 0
    rows = cur.execute(
        """
        SELECT * FROM code_orange_patients
        WHERE incident_id=?
          AND TRIM(COALESCE(current_location,''))=?
          AND (?=0 OR id<>?)
        ORDER BY id ASC
        """,
        (incident_id, loc, pid, pid),
    ).fetchall()
    for r in rows or []:
        if _co_is_active_for_bed_occupancy(r):
            return r
    return None


def _co_location_occupancy_map(cur, incident_id):
    """Map managed occupied locations to the occupying patient payload."""
    occupied = {}
    if not incident_id:
        return occupied
    rows = cur.execute(
        """
        SELECT * FROM code_orange_patients
        WHERE incident_id=?
          AND TRIM(COALESCE(current_location,''))<>''
        ORDER BY id ASC
        """,
        (incident_id,),
    ).fetchall()
    for r in rows or []:
        loc = _co_normalize_location(_co_row_get(r, "current_location", ""))
        if not loc or loc in occupied or not _co_is_managed_location(loc):
            continue
        if not _co_is_active_for_bed_occupancy(r):
            continue
        occupied[loc] = _co_bed_occupancy_payload(r, loc)
    return occupied


def _co_can_force_bed_transfer():
    """Only admins can override a bed/resource occupancy conflict."""
    try:
        return normalize_role_key(session.get("role")) == "admin"
    except Exception:
        return str(session.get("role") or "").strip().lower() == "admin"


def _co_occupancy_conflict_response(conflict_row, location):
    return jsonify(
        success=False,
        conflict=True,
        error="Resource Conflict: This bed is already in use.",
        location=_co_normalize_location(location),
        occupied_by=_co_bed_occupancy_payload(conflict_row, _co_normalize_location(location)),
        can_force_transfer=_co_can_force_bed_transfer(),
    )



def _co_current_location_to_visit_location_bed(current_location):
    """Map a Code Orange Current Location string to the ED visit Location / Bed fields.

    This is a one-way sync helper only. It does not choose or change the Code Orange
    location; it translates the already-selected physical slot into the normal visit
    fields used by the Patient Details Location / Bed card.

    Important: Resus slots are critical locations, not observation beds.  They must
    stay visible as the full location text ("Resus 1" / "Resus 2") and must not be
    split into Location=Resus, Bed=1/2, otherwise ED Board displays them as Bed 1/2.
    Only explicit Bed-style labels are split into the Bed field.
    """
    raw = _co_normalize_location(current_location)
    if not raw or raw == CODE_ORANGE_MANUAL_LOCATION_LABEL:
        return {"care_area": "ED", "location": "", "bed_no": "", "bed_status": ""}

    area = ""
    try:
        area = _co_infer_care_area_from_text(raw) or ""
    except Exception:
        area = ""
    if not area:
        try:
            area = _finalfix_infer_area_from_location_text(raw) or ""
        except Exception:
            area = ""
    try:
        area = _normalize_care_area(area or "ED", "ED")
    except Exception:
        area = "ED"

    compact = re.sub(r"\s+", " ", str(raw or "")).strip()
    location = compact
    bed_no = ""
    try:
        is_resus_slot = bool(re.match(r"^resus\s*\d+[A-Za-z]?$", compact, re.IGNORECASE))
        if not is_resus_slot:
            # Split only explicit bed labels.  Examples:
            # "Bed 01" -> Location=Bed, Bed=01;
            # "treat Bed 01" -> Location=treat Bed, Bed=01.
            m = re.match(r"^(?P<loc>.*?\bBed)\s*(?P<bed>\d+[A-Za-z]?)$", compact, re.IGNORECASE)
            if m:
                parsed_loc = re.sub(r"\s+", " ", (m.group("loc") or "").strip(" -/"))
                parsed_bed = (m.group("bed") or "").strip()
                if parsed_loc and parsed_bed:
                    location = parsed_loc
                    bed_no = parsed_bed
    except Exception:
        pass

    bed_status = ""
    try:
        if compact and (bed_no or _co_is_managed_location(compact)):
            bed_status = "OCCUPIED"
    except Exception:
        if compact and (bed_no or location):
            bed_status = "OCCUPIED"

    return {"care_area": area or "ED", "location": location, "bed_no": bed_no, "bed_status": bed_status}


def _co_find_existing_ed_visit_for_victim(cur, co_row):
    """Best-effort lookup for older Code Orange rows that already have an ED visit but no ed_visit_id link."""
    if not co_row:
        return ""
    try:
        linked = str(_co_row_get(co_row, "ed_visit_id", "") or "").strip()
        if linked and _co_ed_existing_visit(cur, linked):
            return linked
    except Exception:
        pass
    tag = str(_co_row_get(co_row, "hospital_tag_no", "") or "").strip()
    if not tag:
        return ""
    try:
        row = cur.execute(
            """
            SELECT v.visit_id
            FROM visits v
            JOIN patients p ON p.id = v.patient_id
            WHERE TRIM(COALESCE(p.id_number,'')) = ?
            ORDER BY COALESCE(v.created_at,'' ) DESC, v.id DESC
            LIMIT 1
            """,
            (tag,),
        ).fetchone()
        visit_id = str(_co_row_get(row, "visit_id", "") or "").strip() if row else ""
        if visit_id and _co_row_get(co_row, "id", None):
            try:
                cur.execute(
                    "UPDATE code_orange_patients SET ed_visit_id=?, updated_at=?, updated_by=? WHERE id=?",
                    (visit_id, _co_now_text(), session.get("username") or "Code Orange", _co_row_get(co_row, "id")),
                )
            except Exception:
                pass
        return visit_id
    except Exception:
        return ""


def _co_sync_current_location_to_ed_location_bed(cur, co_patient_id=None, co_row=None, current_location=None, actor=None, note=None):
    """Sync a Code Orange victim's selected Current Location into the linked ED visit.

    The Code Orange board remains the source of truth for triage/zone/current-location.
    This function only updates the normal visits.location / visits.bed_no / visits.bed_status
    columns so the Patient Details Location / Bed card reflects the same slot after refresh.
    """
    row = co_row
    try:
        if row is None and co_patient_id:
            row = cur.execute("SELECT * FROM code_orange_patients WHERE id=? LIMIT 1", (co_patient_id,)).fetchone()
    except Exception:
        row = co_row
    if not row:
        return False

    ed_visit_id = _co_find_existing_ed_visit_for_victim(cur, row)
    if not ed_visit_id:
        return False

    loc_raw = current_location
    if loc_raw is None:
        loc_raw = _co_row_get(row, "current_location", "") or ""
    target = _co_current_location_to_visit_location_bed(loc_raw)

    try:
        _ensure_patient_location_movement_schema(cur)
    except Exception:
        pass

    before = _read_visit_location_snapshot(cur, ed_visit_id)
    if not str(loc_raw or "").strip():
        target["care_area"] = before.get("care_area") or "ED"
    else:
        target["care_area"] = target.get("care_area") or before.get("care_area") or "ED"

    before_key = (
        before.get("care_area") or "",
        before.get("location") or "",
        before.get("bed_no") or "",
        before.get("bed_status") or "",
    )
    after_key = (
        target.get("care_area") or "",
        target.get("location") or "",
        target.get("bed_no") or "",
        target.get("bed_status") or "",
    )
    if before_key == after_key:
        return False

    now = _co_now_text()
    user = actor or session.get("username") or _co_row_get(row, "updated_by", "") or _co_row_get(row, "created_by", "") or "Code Orange"
    sync_note = note or "Code Orange Current Location sync"
    cur.execute(
        """
        UPDATE visits
           SET care_area=?,
               location=?,
               bed_no=?,
               bed_status=?,
               movement_note=?,
               location_updated_at=?,
               location_updated_by=?
         WHERE visit_id=?
        """,
        (
            target.get("care_area") or "ED",
            target.get("location") or "",
            target.get("bed_no") or "",
            target.get("bed_status") or "",
            sync_note,
            now,
            user,
            ed_visit_id,
        ),
    )
    try:
        _insert_patient_location_movement(
            cur,
            ed_visit_id,
            before,
            target,
            "LOCATION_UPDATE",
            sync_note,
            now,
            user,
        )
    except Exception as exc:
        try:
            _log_noncritical_exception(f"Code Orange Location / Bed movement audit skipped visit={ed_visit_id}", exc)
        except Exception:
            pass
    return True

def _co_normalize_tag_value(value):
    """Normalize Code Orange tag input for duplicate checks."""
    return re.sub(r"\s+", " ", str(value or "").strip())[:80]


def _co_wants_json_response():
    """Return True for AJAX/JSON clients while preserving normal form fallback."""
    try:
        if request.is_json:
            return True
        accept = (request.headers.get("Accept") or "").lower()
        requested = (request.headers.get("X-Requested-With") or "").lower()
        return "application/json" in accept or requested == "xmlhttprequest"
    except Exception:
        return False


def _co_is_unique_violation(exc):
    """Detect database unique violations across PostgreSQL/psycopg2 and SQLite."""
    try:
        if psycopg2 is not None and hasattr(psycopg2, "errors") and isinstance(exc, psycopg2.errors.UniqueViolation):
            return True
    except Exception:
        pass
    try:
        if str(getattr(exc, "pgcode", "") or "") == "23505":
            return True
    except Exception:
        pass
    try:
        if isinstance(exc, sqlite3.IntegrityError) and "unique" in str(exc).lower():
            return True
    except Exception:
        pass
    return False


def _co_patient_dashboard_url(patient_id):
    try:
        return url_for("code_orange_dashboard", focus_patient=str(patient_id or ""), _anchor=f"co-patient-{patient_id}")
    except Exception:
        return f"/code_orange?focus_patient={patient_id}#co-patient-{patient_id}"


def _co_duplicate_patient_payload(row, matched_field=""):
    if not row:
        return None
    pid = _co_row_get(row, "id", "")
    return {
        "patient_id": pid,
        "id": pid,
        "hospital_tag_no": _co_row_get(row, "hospital_tag_no", "") or "",
        "ems_tag_no": _co_row_get(row, "ems_tag_no", "") or "",
        "patient_name": _co_row_get(row, "patient_name", "") or "Unknown",
        "triage_category": _co_normalize_triage(_co_row_get(row, "triage_category", "GREEN")),
        "current_zone": _co_row_get(row, "current_zone", "") or "",
        "current_location": _co_row_get(row, "current_location", "") or "",
        "matched_field": matched_field or "tag_number",
        "url": _co_patient_dashboard_url(pid),
    }


def _co_find_duplicate_patient_by_tag(cur, incident_id, tag_value, tag_kind="any"):
    """Find an existing live Code Orange patient by tag.

    tag_kind can be: ems, hospital, or any. The check is scoped to the active
    incident so archived/closed incidents do not block a new incident.
    """
    tag = _co_normalize_tag_value(tag_value)
    if not tag or not incident_id:
        return None, ""
    kind = str(tag_kind or "any").strip().lower()
    params = [incident_id, tag]
    if kind in ("ems", "ems_tag", "ems_tag_no"):
        where = "LOWER(TRIM(ems_tag_no)) = LOWER(TRIM(?))"
        matched = "ems_tag_no"
    elif kind in ("hospital", "hospital_tag", "hospital_tag_no", "tag", "tag_number"):
        where = "LOWER(TRIM(hospital_tag_no)) = LOWER(TRIM(?))"
        matched = "hospital_tag_no"
    else:
        where = "(LOWER(TRIM(hospital_tag_no)) = LOWER(TRIM(?)) OR LOWER(TRIM(ems_tag_no)) = LOWER(TRIM(?)))"
        params.append(tag)
        matched = "tag_number"
    row = cur.execute(
        f"""
        SELECT * FROM code_orange_patients
         WHERE incident_id=? AND {where}
         LIMIT 1
        """,
        tuple(params),
    ).fetchone()
    if row and matched == "tag_number":
        try:
            if _co_normalize_tag_value(_co_row_get(row, "hospital_tag_no", "")).lower() == tag.lower():
                matched = "hospital_tag_no"
            elif _co_normalize_tag_value(_co_row_get(row, "ems_tag_no", "")).lower() == tag.lower():
                matched = "ems_tag_no"
        except Exception:
            pass
    return row, matched



def _co_history_columns_definitions():
    """Column definitions used by code_orange_history.

    The Close Incident action writes to this table. Older PostgreSQL deployments
    may have been upgraded before the history table existed, so creation and
    column repair must not depend only on the global schema-ready flag.
    """
    id_type = "BIGSERIAL PRIMARY KEY" if DB_ENGINE == "postgres" else "INTEGER PRIMARY KEY AUTOINCREMENT"
    incident_id_type = "BIGINT" if DB_ENGINE == "postgres" else "INTEGER"
    return [
        ("id", id_type),
        ("archived_incident_id", f"{incident_id_type} NOT NULL"),
        ("original_patient_id", incident_id_type),
        ("incident_name", "TEXT"),
        ("area", "TEXT"),
        ("operational_period", "TEXT"),
        ("ems_tag_no", "TEXT"),
        ("hospital_tag_no", "TEXT"),
        ("patient_mrn", "TEXT"),
        ("patient_name", "TEXT"),
        ("mobile_number", "TEXT"),
        ("sex", "TEXT"),
        ("dob", "TEXT"),
        ("age", "TEXT"),
        ("triage_category", "TEXT"),
        ("current_zone", "TEXT"),
        ("current_location", "TEXT"),
        ("cbrn_contaminated", "TEXT"),
        ("start_walks", "TEXT"),
        ("start_no_resp_after_airway", "TEXT"),
        ("start_no_radial_or_cr_gt2", "TEXT"),
        ("start_rr_gt30", "TEXT"),
        ("start_unable_follow_commands", "TEXT"),
        ("procedure_location_time", "TEXT"),
        ("disposition", "TEXT"),
        ("tag_photo_path", "TEXT"),
        ("created_at", "TEXT"),
        ("created_by", "TEXT"),
        ("updated_at", "TEXT"),
        ("updated_by", "TEXT"),
        ("archived_at", "TEXT NOT NULL"),
        ("archived_by", "TEXT"),
        ("archive_pdf_path", "TEXT"),
    ]


def _co_create_history_table(cur=None):
    """Create/repair code_orange_history for the Close Incident workflow."""
    cur = cur or get_db().cursor()
    cols = _co_history_columns_definitions()
    ddl_cols = ",\n                ".join(f"{name} {definition}" for name, definition in cols)
    cur.execute(
        f"""
        CREATE TABLE IF NOT EXISTS code_orange_history (
                {ddl_cols}
        )
        """
    )

    existing = set()
    if DB_ENGINE == "postgres":
        rows = cur.execute(
            """
            SELECT column_name
              FROM information_schema.columns
             WHERE table_schema = current_schema()
               AND table_name = ?
            """,
            ("code_orange_history",),
        ).fetchall()
        for r in rows:
            try:
                existing.add(str(r["column_name"]).lower())
            except Exception:
                existing.add(str(r[0]).lower())
    else:
        rows = cur.execute("PRAGMA table_info(code_orange_history)").fetchall()
        for r in rows:
            try:
                existing.add(str(r["name"]).lower())
            except Exception:
                existing.add(str(r[1]).lower())

    for name, definition in cols:
        if name.lower() in existing:
            continue
        if name == "id":
            continue
        clean_definition = definition.replace(" NOT NULL", "")
        cur.execute(f"ALTER TABLE code_orange_history ADD COLUMN {name} {clean_definition}")


def _co_ensure_history_table_committed():
    """Ensure code_orange_history exists even when global schema is already ready."""
    db = get_db()
    cur = db.cursor()
    _co_create_history_table(cur)
    try:
        db.commit()
    except Exception:
        pass



def _co_create_or_repair_movement_log(cur=None):
    """Create/repair patient_movement_log safely across PostgreSQL and SQLite.

    Earlier deployments may have created this table before hospital_tag_no,
    old_location, or new_location existed. PostgreSQL aborts a transaction after
    duplicate-column errors, so this routine uses ADD COLUMN IF NOT EXISTS on
    PostgreSQL and explicit column checks on SQLite.
    """
    cur = cur or get_db().cursor()
    if DB_ENGINE == "postgres":
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS patient_movement_log (
                id BIGSERIAL PRIMARY KEY,
                patient_id BIGINT NOT NULL,
                incident_id BIGINT,
                hospital_tag_no TEXT,
                ems_tag_no TEXT,
                old_status TEXT,
                new_status TEXT,
                old_zone TEXT,
                new_zone TEXT,
                old_location TEXT,
                new_location TEXT,
                old_procedure_location_time TEXT,
                new_procedure_location_time TEXT,
                procedure_location_time TEXT,
                old_disposition TEXT,
                new_disposition TEXT,
                disposition TEXT,
                username TEXT,
                updated_by TEXT,
                timestamp TEXT NOT NULL,
                notes TEXT
            )
            """
        )
        for col, definition in (
            ("incident_id", "BIGINT"),
            ("hospital_tag_no", "TEXT"),
            ("ems_tag_no", "TEXT"),
            ("old_status", "TEXT"),
            ("new_status", "TEXT"),
            ("old_zone", "TEXT"),
            ("new_zone", "TEXT"),
            ("old_location", "TEXT"),
            ("new_location", "TEXT"),
            ("old_procedure_location_time", "TEXT"),
            ("new_procedure_location_time", "TEXT"),
            ("procedure_location_time", "TEXT"),
            ("old_disposition", "TEXT"),
            ("new_disposition", "TEXT"),
            ("disposition", "TEXT"),
            ("username", "TEXT"),
            ("updated_by", "TEXT"),
            ("notes", "TEXT"),
        ):
            cur.execute(f"ALTER TABLE patient_movement_log ADD COLUMN IF NOT EXISTS {col} {definition}")
    else:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS patient_movement_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                patient_id INTEGER NOT NULL,
                incident_id INTEGER,
                hospital_tag_no TEXT,
                ems_tag_no TEXT,
                old_status TEXT,
                new_status TEXT,
                old_zone TEXT,
                new_zone TEXT,
                old_location TEXT,
                new_location TEXT,
                old_procedure_location_time TEXT,
                new_procedure_location_time TEXT,
                procedure_location_time TEXT,
                old_disposition TEXT,
                new_disposition TEXT,
                disposition TEXT,
                username TEXT,
                updated_by TEXT,
                timestamp TEXT NOT NULL,
                notes TEXT
            )
            """
        )
        try:
            existing = set()
            for r in cur.execute("PRAGMA table_info(patient_movement_log)").fetchall():
                try:
                    existing.add(str(r["name"]).lower())
                except Exception:
                    existing.add(str(r[1]).lower())
            for col, definition in (
                ("incident_id", "INTEGER"),
                ("hospital_tag_no", "TEXT"),
                ("ems_tag_no", "TEXT"),
                ("old_status", "TEXT"),
                ("new_status", "TEXT"),
                ("old_zone", "TEXT"),
                ("new_zone", "TEXT"),
                ("old_location", "TEXT"),
                ("new_location", "TEXT"),
                ("username", "TEXT"),
                ("notes", "TEXT"),
            ):
                if col.lower() not in existing:
                    cur.execute(f"ALTER TABLE patient_movement_log ADD COLUMN {col} {definition}")
        except Exception:
            pass


def _co_ensure_movement_log_schema_committed():
    """Ensure patient_movement_log has all columns before any log insert/select."""
    db = get_db()
    cur = db.cursor()
    _co_create_or_repair_movement_log(cur)
    try:
        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass


# ROOTFIX_20260430H_DUPLICATE_MOVEMENT_LOG_UPSERT
# Prevent duplicate patient_movement_log rows caused by quick corrections on the
# Live Victim Board.  Real re-triage and Destination Zone transitions still
# create a new row; quick corrections inside the same zone update the last row.
CODE_ORANGE_MOVEMENT_LOG_UPSERT_WINDOW_MINUTES = 10


def _co_movement_log_upsert_window_minutes(default=CODE_ORANGE_MOVEMENT_LOG_UPSERT_WINDOW_MINUTES):
    try:
        raw = (
            os.environ.get("ED_CO_MOVEMENT_LOG_UPSERT_MINUTES")
            or os.environ.get("ED_MOVEMENT_LOG_UPSERT_MINUTES")
            or default
        )
        value = int(float(raw))
    except Exception:
        value = int(default or 10)
    if value < 0:
        value = 0
    return min(value, 1440)


def _co_log_norm(value):
    try:
        return " ".join(str(value or "").strip().split()).casefold()
    except Exception:
        return ""


def _co_movement_log_timestamp_dt(value):
    try:
        parsed = _parse_to_local_naive(value)
        if parsed:
            return parsed.replace(microsecond=0)
    except Exception:
        pass
    try:
        s = str(value or "").strip()
        if not s:
            return None
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M"):
            try:
                return datetime.strptime(s[:19], fmt).replace(microsecond=0)
            except Exception:
                continue
    except Exception:
        pass
    return None


def _co_fetch_last_movement_log_for_upsert(cur, patient_id, incident_id):
    """Fetch the newest movement row for one patient and lock it on PostgreSQL."""
    incident_key = str(incident_id or "").strip()
    query = """
        SELECT *
        FROM patient_movement_log
        WHERE patient_id=?
          AND COALESCE(CAST(incident_id AS TEXT), '')=?
        ORDER BY id DESC
        LIMIT 1
    """
    if DB_ENGINE == "postgres":
        query = query.rstrip() + " FOR UPDATE"
    return cur.execute(query, (patient_id, incident_key)).fetchone()


def _co_should_update_last_movement_log(last_row, new_zone, now_dt=None, window_minutes=None):
    """Return True when a new audit event should be merged into the last row."""
    if not last_row:
        return False
    if window_minutes is None:
        window_minutes = _co_movement_log_upsert_window_minutes()
    try:
        window_minutes = int(window_minutes)
    except Exception:
        window_minutes = CODE_ORANGE_MOVEMENT_LOG_UPSERT_WINDOW_MINUTES
    if window_minutes <= 0:
        return False
    if _co_log_norm(_co_row_get(last_row, "new_zone", "")) != _co_log_norm(new_zone):
        return False
    last_dt = _co_movement_log_timestamp_dt(_co_row_get(last_row, "timestamp", ""))
    if not last_dt:
        return False
    try:
        current_dt = (now_dt or _now_local_naive()).replace(microsecond=0)
    except Exception:
        current_dt = datetime.now().replace(microsecond=0)
    try:
        delta_seconds = abs((current_dt - last_dt).total_seconds())
    except Exception:
        return False
    return delta_seconds <= (window_minutes * 60)


def _co_insert_or_update_movement_log(
    cur,
    *,
    patient_id,
    incident_id,
    hospital_tag_no,
    ems_tag_no,
    old_status,
    new_status,
    old_zone,
    new_zone,
    old_location,
    new_location,
    old_procedure_location_time,
    new_procedure_location_time,
    old_disposition,
    new_disposition,
    actor,
    notes,
    force_insert=False,
):
    """Insert a real movement row or update the last row for quick corrections.

    INSERT is kept for true re-triage and Destination Zone transitions.  Quick
    correction edits inside the same zone and inside the configured 10-minute
    window update the newest patient_movement_log row instead of creating a
    duplicate row.  The SQL uses '?' placeholders for sqlite3 and the project's
    psycopg2 QmarkDictCursor wrapper.
    """
    now_text = _co_now_text()
    now_dt = _co_movement_log_timestamp_dt(now_text) or _now_local_naive()
    clean_notes = str(notes or "Victim Board update").strip() or "Victim Board update"

    last_row = None
    if not force_insert:
        try:
            last_row = _co_fetch_last_movement_log_for_upsert(cur, patient_id, incident_id)
        except Exception:
            last_row = None

    if (not force_insert) and _co_should_update_last_movement_log(last_row, new_zone, now_dt=now_dt):
        merge_note = "Upsert correction within 10 minutes: " + clean_notes
        cur.execute(
            """
            UPDATE patient_movement_log
               SET hospital_tag_no=?,
                   ems_tag_no=?,
                   new_status=?,
                   new_zone=?,
                   new_location=?,
                   new_procedure_location_time=?,
                   procedure_location_time=?,
                   new_disposition=?,
                   disposition=?,
                   username=?,
                   updated_by=?,
                   timestamp=?,
                   notes=CASE
                           WHEN COALESCE(notes,'')='' THEN ?
                           ELSE notes || ' | ' || ?
                         END
             WHERE id=?
            """,
            (
                hospital_tag_no or "",
                ems_tag_no or "",
                new_status or "",
                new_zone or "",
                new_location or "",
                new_procedure_location_time or "",
                new_procedure_location_time or "",
                new_disposition or "",
                new_disposition or "",
                actor or "SYSTEM",
                actor or "SYSTEM",
                now_text,
                merge_note,
                merge_note,
                _co_row_get(last_row, "id", None),
            ),
        )
        return "updated"

    cur.execute(
        """
        INSERT INTO patient_movement_log
          (patient_id, incident_id, hospital_tag_no, ems_tag_no,
           old_status, new_status, old_zone, new_zone, old_location, new_location,
           old_procedure_location_time, new_procedure_location_time, procedure_location_time,
           old_disposition, new_disposition, disposition,
           username, updated_by, timestamp, notes)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """,
        (
            patient_id,
            incident_id,
            hospital_tag_no or "",
            ems_tag_no or "",
            old_status or "",
            new_status or "",
            old_zone or "",
            new_zone or "",
            old_location or "",
            new_location or "",
            old_procedure_location_time or "",
            new_procedure_location_time or "",
            new_procedure_location_time or "",
            old_disposition or "",
            new_disposition or "",
            new_disposition or "",
            actor or "SYSTEM",
            actor or "SYSTEM",
            now_text,
            clean_notes,
        ),
    )
    return "inserted"


