def _co_pdf_request_has_cache_buster():
    """Return True when a PDF request already has a unique cache-buster query."""
    try:
        return bool((request.args.get("t") or request.args.get("_t") or request.args.get("v") or "").strip())
    except Exception:
        return False


def _co_redirect_with_cache_buster(endpoint, **values):
    """Redirect direct PDF opens to a unique URL so mobile PDF viewers cannot reuse old inline content."""
    try:
        merged = request.args.to_dict(flat=True)
    except Exception:
        merged = {}
    try:
        merged.update(values)
        merged["t"] = str(int(time.time() * 1000))
        return redirect(url_for(endpoint, **merged), code=302)
    except Exception:
        return None


def _co_wants_pdf_download():
    """Support ?download=1 / ?dl=1 while keeping normal browser opening inline."""
    try:
        raw = request.args.get("download")
        if raw is None:
            raw = request.args.get("dl")
        if raw is None:
            return False
        return str(raw).strip().lower() not in ("", "0", "false", "no", "off")
    except Exception:
        return False


def _co_pdf_response(pdf_bytes, filename, inline=True):
    """Return a Code Orange PDF with headers that are safe for Safari/iPad inline viewing."""
    data = pdf_bytes or b""
    if not isinstance(data, (bytes, bytearray)):
        try:
            data = bytes(data)
        except Exception:
            data = b""
    resp = Response(bytes(data), mimetype="application/pdf", direct_passthrough=False)
    resp.headers["Content-Disposition"] = _content_disposition(filename, inline=bool(inline))
    resp.headers["Content-Length"] = str(len(data))
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["Accept-Ranges"] = "none"
    resp.headers["X-Accel-Buffering"] = "no"
    resp.headers["X-Robots-Tag"] = "noindex, noarchive"
    try:
        resp.headers.pop("ETag", None)
        resp.headers.pop("Last-Modified", None)
    except Exception:
        pass
    try:
        return _apply_export_no_cache_headers(resp)
    except Exception:
        return resp


@app.route("/code_orange/archive/<int:incident_id>/pdf")
@login_required
def code_orange_archive_pdf(incident_id):
    ensure_code_orange_schema()
    if not _co_pdf_request_has_cache_buster():
        redirected = _co_redirect_with_cache_buster("code_orange_archive_pdf", incident_id=incident_id)
        if redirected is not None:
            return redirected

    row = get_db().execute("SELECT archive_pdf_path FROM code_orange_incidents WHERE id=? LIMIT 1", (incident_id,)).fetchone()
    filename = os.path.basename(str(_co_row_get(row, "archive_pdf_path", "") or "").strip()) if row else ""
    if not filename:
        return "No archived PDF found for this Code Orange incident.", 404
    full = resolve_upload_path(filename)
    if not full or not os.path.exists(full):
        return "Archived PDF file is missing from disk.", 404
    try:
        with open(full, "rb") as fp:
            pdf_bytes = fp.read()
    except Exception:
        return "Archived PDF file could not be opened.", 500
    return _co_pdf_response(
        pdf_bytes,
        filename or f"Code_Orange_Archive_{incident_id}.pdf",
        inline=not _co_wants_pdf_download(),
    )


