@app.route("/code_orange/patient/<int:patient_id>/update", methods=["POST"])
@login_required
def code_orange_patient_update(patient_id):
    # Live Victim Board combined save endpoint. When triage_category and
    # current_location arrive together, both fields are updated in one DB
    # transaction and one patient_movement_log row is inserted below.
    ensure_code_orange_schema()
    _co_ensure_movement_log_schema_committed()
    data = request.get_json(silent=True) or request.form.to_dict() or {}
    db = get_db()
    cur = db.cursor()
    patient_lock_sql = "SELECT * FROM code_orange_patients WHERE id=?"
    if DB_ENGINE == "postgres":
        patient_lock_sql += " FOR UPDATE"
    row = cur.execute(patient_lock_sql, (patient_id,)).fetchone()
    if not row:
        return jsonify(success=False, error="Patient/tag record not found."), 404

    old_status = _co_normalize_triage(_co_row_get(row, "triage_category", "GREEN"))
    old_zone = _co_row_get(row, "current_zone", "Triage") or "Triage"
    old_location = _co_normalize_location(_co_row_get(row, "current_location", ""))
    old_proc = str(_co_row_get(row, "procedure_location_time", "") or "").strip()
    old_disp = str(_co_row_get(row, "disposition", "") or "").strip()
    old_cbrn = _co_bool_text(_co_row_get(row, "cbrn_contaminated", "No"))
    new_status = old_status
    new_zone = old_zone
    new_location = old_location
    new_proc = old_proc
    new_disp = old_disp
    new_cbrn = old_cbrn
    actor = _co_actor_username()
    updates = []
    params = []

    if "triage_category" in data or "new_status" in data:
        new_status = _co_normalize_triage(data.get("triage_category") or data.get("new_status"))
        updates.append("triage_category=?")
        params.append(new_status)
    if "cbrn_contaminated" in data:
        new_cbrn = _co_bool_text(data.get("cbrn_contaminated"))
        updates.append("cbrn_contaminated=?")
        params.append(new_cbrn)
    if "current_zone" in data or "new_zone" in data:
        new_zone = _co_normalize_zone(data.get("current_zone") or data.get("new_zone"), triage=new_status, cbrn=(new_cbrn == "Yes"))
        updates.append("current_zone=?")
        params.append(new_zone)

    # Smart default: a triage/status or CBRN change also updates Destination Zone
    # unless the user explicitly sent a manual destination zone in this request.
    if ("triage_category" in data or "new_status" in data or "cbrn_contaminated" in data) and not ("current_zone" in data or "new_zone" in data):
        mapped_zone = _co_default_zone_for_triage(new_status, cbrn=(new_cbrn == "Yes"))
        if mapped_zone and mapped_zone != old_zone:
            new_zone = mapped_zone
            updates.append("current_zone=?")
            params.append(new_zone)

    # Current Location must remain a manual staff choice for all START triage colours.
    # Keep automatic Current Location assignment only for CBRN/Decontamination.
    # Manual user input wins whenever current_location/new_location is sent.
    if ("triage_category" in data or "new_status" in data or "cbrn_contaminated" in data) and not ("current_location" in data or "new_location" in data):
        mapped_location = _co_default_location_for_triage(new_status, cbrn=(new_cbrn == "Yes"))
        if mapped_location and mapped_location != old_location:
            new_location = mapped_location
            updates.append("current_location=?")
            params.append(new_location)

    if "current_location" in data or "new_location" in data:
        new_location = _co_normalize_location(data.get("current_location") if "current_location" in data else data.get("new_location"))
        updates.append("current_location=?")
        params.append(new_location)

    if "procedure_location_time" in data:
        new_proc = str(data.get("procedure_location_time") or "").strip()[:500]
        updates.append("procedure_location_time=?")
        params.append(new_proc)
    if "disposition" in data:
        disp = str(data.get("disposition") or "").strip()
        if disp not in _co_active_disposition_options():
            disp = disp[:120]
        new_disp = disp
        updates.append("disposition=?")
        params.append(new_disp)

    location_changed = new_location != old_location
    force_transfer = str(data.get("force_transfer") or "").strip().lower() in ("1", "true", "yes", "on")
    if force_transfer and not _co_can_force_bed_transfer():
        force_transfer = False
    if location_changed:
        conflict_row = _co_location_conflict(cur, _co_row_get(row, "incident_id", None), new_location, patient_id=patient_id)
        if conflict_row and not force_transfer:
            return _co_occupancy_conflict_response(conflict_row, new_location), 409

    if not updates:
        return jsonify(success=False, error="No supported fields were provided."), 400

    updates.extend(["updated_at=?", "updated_by=?"])
    params.extend([_co_now_text(), actor])
    params.append(patient_id)
    try:
        cur.execute(f"UPDATE code_orange_patients SET {', '.join(updates)} WHERE id=?", params)
        if new_location != old_location:
            try:
                _co_sync_current_location_to_ed_location_bed(
                    cur,
                    co_row=row,
                    current_location=new_location,
                    actor=actor,
                    note="Code Orange Live Victim Board Current Location sync",
                )
            except Exception as _co_loc_sync_exc:
                _log_noncritical_exception("Code Orange Live Victim Board Location / Bed sync skipped", _co_loc_sync_exc)
        moved = (new_status != old_status) or (new_zone != old_zone) or (new_location != old_location)
        clinical_changed = (new_proc != old_proc) or (new_disp != old_disp)
        if moved or clinical_changed:
            note_parts = []
            if moved:
                note_parts.append("re-triage/zone/location")
            if new_proc != old_proc:
                note_parts.append("procedure/location time")
            if new_disp != old_disp:
                note_parts.append("disposition")
            _co_insert_or_update_movement_log(
                cur,
                patient_id=patient_id,
                incident_id=_co_row_get(row, "incident_id", None),
                hospital_tag_no=_co_row_get(row, "hospital_tag_no", ""),
                ems_tag_no=_co_row_get(row, "ems_tag_no", ""),
                old_status=old_status,
                new_status=new_status,
                old_zone=old_zone,
                new_zone=new_zone,
                old_location=old_location,
                new_location=new_location,
                old_procedure_location_time=old_proc,
                new_procedure_location_time=new_proc,
                old_disposition=old_disp,
                new_disposition=new_disp,
                actor=actor,
                notes="AJAX update: " + (", ".join(note_parts) if note_parts else "clinical audit"),
                force_insert=((new_status != old_status) or (new_zone != old_zone)),
            )
        db.commit()
    except Exception as exc:
        try:
            db.rollback()
        except Exception:
            pass
        return jsonify(success=False, error=str(exc)), 500

    updated = cur.execute("SELECT * FROM code_orange_patients WHERE id=?", (patient_id,)).fetchone()
    try:
        log_action("CODE_ORANGE_UPDATE", details=f"patient_id={patient_id}, {old_status}/{old_zone}/{old_location}->{new_status}/{new_zone}/{new_location}")
    except Exception:
        pass
    visual_alert = bool(new_status != old_status and _co_is_visual_alert_status(new_status))
    return jsonify(success=True, patient=_co_patient_to_dict(updated, visual_alert=visual_alert), visual_alert=visual_alert)


@app.route("/code_orange/patient/<int:patient_id>/location", methods=["POST"])
@login_required
def code_orange_patient_location_update(patient_id):
    """Dedicated endpoint for hybrid Current Location updates with bed occupancy protection.

    Accepts predefined locations and custom free-text strings. Managed locations
    such as Resus/Bed/treat Bed are single-occupancy unless an admin sends
    force_transfer=1.
    """
    ensure_code_orange_schema()
    _co_ensure_movement_log_schema_committed()
    data = request.get_json(silent=True) or request.form.to_dict() or {}
    loc = data.get("current_location") if "current_location" in data else (data.get("new_location") if "new_location" in data else data.get("location", ""))
    force_transfer = str(data.get("force_transfer") or "").strip().lower() in ("1", "true", "yes", "on")
    if force_transfer and not _co_can_force_bed_transfer():
        force_transfer = False

    db = get_db()
    cur = db.cursor()
    patient_lock_sql = "SELECT * FROM code_orange_patients WHERE id=?"
    if DB_ENGINE == "postgres":
        patient_lock_sql += " FOR UPDATE"
    row = cur.execute(patient_lock_sql, (patient_id,)).fetchone()
    if not row:
        return jsonify(success=False, error="Patient/tag record not found."), 404

    old_status = _co_normalize_triage(_co_row_get(row, "triage_category", "GREEN"))
    old_zone = _co_row_get(row, "current_zone", "Triage") or "Triage"
    old_location = _co_normalize_location(_co_row_get(row, "current_location", ""))
    old_proc = str(_co_row_get(row, "procedure_location_time", "") or "").strip()
    old_disp = str(_co_row_get(row, "disposition", "") or "").strip()
    actor = _co_actor_username()
    new_location = _co_normalize_location(loc)

    conflict_row = _co_location_conflict(cur, _co_row_get(row, "incident_id", None), new_location, patient_id=patient_id)
    if conflict_row and not force_transfer:
        return _co_occupancy_conflict_response(conflict_row, new_location), 409

    try:
        cur.execute(
            "UPDATE code_orange_patients SET current_location=?, updated_at=?, updated_by=? WHERE id=?",
            (new_location, _co_now_text(), actor, patient_id),
        )
        if new_location != old_location:
            try:
                _co_sync_current_location_to_ed_location_bed(
                    cur,
                    co_row=row,
                    current_location=new_location,
                    actor=actor,
                    note="Code Orange Current Location button sync",
                )
            except Exception as _co_loc_sync_exc:
                _log_noncritical_exception("Code Orange dedicated Location / Bed sync skipped", _co_loc_sync_exc)
            notes = "Current Location update"
            if conflict_row and force_transfer:
                notes = "Current Location update - Force Transfer override"
            _co_insert_or_update_movement_log(
                cur,
                patient_id=patient_id,
                incident_id=_co_row_get(row, "incident_id", None),
                hospital_tag_no=_co_row_get(row, "hospital_tag_no", ""),
                ems_tag_no=_co_row_get(row, "ems_tag_no", ""),
                old_status=old_status,
                new_status=old_status,
                old_zone=old_zone,
                new_zone=old_zone,
                old_location=old_location,
                new_location=new_location,
                old_procedure_location_time=old_proc,
                new_procedure_location_time=old_proc,
                old_disposition=old_disp,
                new_disposition=old_disp,
                actor=actor,
                notes=notes,
                force_insert=False,
            )
        db.commit()
    except Exception as exc:
        try:
            db.rollback()
        except Exception:
            pass
        return jsonify(success=False, error=str(exc)), 500
    updated = cur.execute("SELECT * FROM code_orange_patients WHERE id=?", (patient_id,)).fetchone()
    return jsonify(success=True, patient=_co_patient_to_dict(updated), force_transfer=bool(force_transfer))


@app.route("/code_orange/export.csv")
@login_required
def code_orange_export_csv():
    ensure_code_orange_schema()
