            _co_row_get(p, "mobile_number", ""),
            _co_row_get(p, "sex", ""),
            _co_row_get(p, "dob", ""),
            _co_row_get(p, "age", ""),
            _co_row_get(p, "triage_category", ""),
            _co_row_get(p, "current_zone", ""),
            _co_row_get(p, "current_location", ""),
            _co_row_get(p, "cbrn_contaminated", ""),
            _co_row_get(p, "procedure_location_time", ""),
            _co_row_get(p, "disposition", ""),
            _co_row_get(p, "created_at", ""),
            _co_row_get(p, "created_by", ""),
            _co_row_get(p, "updated_at", ""),
