# ---- Clinical Orders: enrich lab catalog items with category metadata ----
def _ed_dt_norm_key_20260503(value):
    try:
        value = unicodedata.normalize("NFKD", str(value or ""))
    except Exception:
        value = str(value or "")
    try:
        value = value.encode("ascii", "ignore").decode("ascii")
    except Exception:
        pass
    try:
        value = re.sub(r"[^a-zA-Z0-9]+", " ", value).strip().lower()
        value = re.sub(r"\s+", " ", value)
    except Exception:
        value = str(value or "").strip().lower()
    return value

try:
    _ED_LAB_CATEGORY_BY_NAME_20260503 = {}
    for _ed_lab_catalog_item in globals().get("DEFAULT_LAB_CATALOG", []) or []:
        try:
            _ed_lab_name = _ed_lab_catalog_item.get("name") or ""
            _ed_lab_category = _ed_lab_catalog_item.get("category") or "General / Other"
            if _ed_lab_name:
                _ED_LAB_CATEGORY_BY_NAME_20260503[_ed_dt_norm_key_20260503(_ed_lab_name)] = _ed_lab_category
        except Exception:
            pass
except Exception:
    _ED_LAB_CATEGORY_BY_NAME_20260503 = {}


def _ed_dt_infer_lab_category_20260503(name):
    """Return a practical lab category for UI grouping when the DB item has no category column."""
    n = _ed_dt_norm_key_20260503(name)
    if not n:
        return "General / Other"
    exact = _ED_LAB_CATEGORY_BY_NAME_20260503.get(n)
    if exact:
        return exact

    rules = [
        ("Hematology", ("cbc", "hemoglobin", "haemoglobin", "hematocrit", "haematocrit", "wbc", "rbc", "platelet", "mcv", "mch", "mchc", "rdw", "neutroph", "lymph", "monocyte", "eosinoph", "basoph", "retic", "esr", "sickle", "g6pd", "blood film")),
        ("Coagulation", ("pt", "inr", "aptt", "ptt", "coag", "fibrinogen", "d dimer", "d-dimer", "anti xa", "thrombin")),
        ("Cardiac", ("troponin", "ck mb", "ckmb", "ck total", "bnp", "nt probnp", "nt-probnp", "cardiac enzyme")),
        ("Blood Gas", ("abg", "vbg", "blood gas", "pco2", "po2", "base excess", "carboxy", "methemoglobin")),
        ("Urinalysis", ("urine", "urinalysis", "pregnancy", "hcg", "specific gravity", "ketone")),
        ("Microbiology", ("culture", "gram stain", "afb", "tb pcr", "mrsa", "clostridio", "wound", "sputum", "stool", "csf", "blood culture")),
        ("Virology", ("covid", "influenza", "rsv", "hepatitis", "hiv", "rpr", "dengue", "malaria", "strep", "antigen", "pcr")),
        ("Toxicology", ("toxic", "drug", "ethanol", "alcohol", "salicylate", "acetaminophen", "paracetamol level", "valpro", "carbamazepine", "phenytoin", "digoxin", "amphet", "benzodiazep", "cannabinoid", "cocaine", "opiate", "methadone", "barbiturate")),
        ("Blood Bank", ("type screen", "crossmatch", "abo", "rh", "antibody", "dat", "blood bank")),
        ("Endocrine", ("tsh", "free t4", "free t3", "total t4", "hba1c", "insulin", "c peptide", "c-peptide", "cortisol", "prolactin", "thyroid")),
        ("Lipids", ("cholesterol", "ldl", "hdl", "triglyceride", "lipid")),
        ("Chemistry", ("bmp", "cmp", "chem", "electrolyte", "sodium", "potassium", "chloride", "bicarbonate", "hco3", "anion", "urea", "bun", "creatinine", "egfr", "calcium", "magnesium", "phosphate", "protein", "albumin", "ast", "alt", "alp", "ggt", "bilirubin", "ldh", "amylase", "lipase", "crp", "procalcitonin", "lactate", "uric", "glucose", "rbs", "lft", "rft", "osmolality", "ammonia", "ferritin", "iron", "tibc", "transferrin", "vitamin", "psa")),
    ]
    for cat, tokens in rules:
        try:
            if any(tok in n for tok in tokens):
                return cat
        except Exception:
            continue
    return "General / Other"


try:
    _ED_PREV_GET_CLINICAL_ORDER_CATALOGS_20260503 = globals().get("get_clinical_order_catalogs")

    def get_clinical_order_catalogs():
        if callable(_ED_PREV_GET_CLINICAL_ORDER_CATALOGS_20260503):
            data = _ED_PREV_GET_CLINICAL_ORDER_CATALOGS_20260503() or {}
        else:
            data = {}
        try:
            data = dict(data)
        except Exception:
            data = {}

        enriched_labs = []
        for item in data.get("lab_items") or []:
            try:
                d = dict(item)
            except Exception:
                try:
                    d = {"name": item["name"]}
                except Exception:
                    d = {"name": str(item or "")}
            try:
                if not str(d.get("category") or "").strip():
                    d["category"] = _ed_dt_infer_lab_category_20260503(d.get("name") or "")
            except Exception:
                d["category"] = "General / Other"
            enriched_labs.append(d)
        data["lab_items"] = enriched_labs
        return data

    globals()["get_clinical_order_catalogs"] = get_clinical_order_catalogs
except Exception as _ed_catalog_patch_exc_20260503:
    try:
        _log_noncritical_exception("ED UI performance patch: catalog category wrapper failed", _ed_catalog_patch_exc_20260503)
    except Exception:
        pass


# ---- Lab Board: one JSON request for batch sample collection ----
if "lab_bulk_collect_json" not in app.view_functions:

    @app.route("/lab_requests/bulk_collect_json", methods=["POST"])
    @login_required
    @role_required("nurse", "lab", "admin")
    def lab_bulk_collect_json():
        payload = request.get_json(silent=True) or {}
        raw_ids = payload.get("rids") or payload.get("rids[]") or payload.get("ids") or payload.get("order_ids") or []
        if not isinstance(raw_ids, (list, tuple, set)):
            raw_ids = [raw_ids]
        try:
            ids = _lab_batch_ui_dedupe_int_list(raw_ids)
        except Exception:
            ids = []
            seen = set()
            for x in raw_ids:
                try:
                    rid = int(str(x).strip())
                except Exception:
                    continue
                if rid in seen:
                    continue
                seen.add(rid)
                ids.append(rid)

        if not ids:
            return jsonify({"ok": False, "error": "No lab requests selected."}), 400
        if len(ids) > 500:
            return jsonify({"ok": False, "error": "Too many rows selected. Please select up to 500 at a time."}), 400

        db = get_db()
        cur = db.cursor()
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        user = session.get("username", "UNKNOWN")
        ph = ",".join(["?"] * len(ids))
        open_visit = str(payload.get("open_visit") or "").strip()

        try:
            rows = cur.execute(
                f"SELECT id, visit_id, status FROM lab_requests WHERE id IN ({ph}) ORDER BY id",
                ids,
            ).fetchall()
            found_ids = []
            visits = set()
            for row in rows or []:
                try:
                    found_ids.append(int(row["id"]))
                    if row["visit_id"]:
                        visits.add(str(row["visit_id"]))
                except Exception:
                    try:
                        found_ids.append(int(row[0]))
                        if row[1]:
                            visits.add(str(row[1]))
                    except Exception:
                        pass
            if len(found_ids) != len(ids):
                return jsonify({"ok": False, "error": "One or more selected lab requests were not found."}), 404
            if not open_visit and visits:
                open_visit = sorted(visits)[0]

            cur.execute(
                f"""
                UPDATE lab_requests
                   SET status='COLLECTED',
                       collected_at=COALESCE(collected_at, ?),
                       collected_by=COALESCE(collected_by, ?)
                 WHERE id IN ({ph})
                   AND UPPER(COALESCE(status,'')) IN ('REQUESTED','SENT')
                """,
                [now, user] + ids,
            )
            updated = int(getattr(cur, "rowcount", 0) or 0)
            db.commit()

            try:
                if callable(globals().get("_invalidate_lab_board_runtime_caches")):
                    _invalidate_lab_board_runtime_caches(open_visit)
            except Exception:
                pass
            try:
                if callable(globals().get("_invalidate_ed_board_runtime_caches")):
                    _invalidate_ed_board_runtime_caches()
            except Exception:
                pass
            try:
                log_action("LAB_BULK_COLLECT_JSON", visit_id=(open_visit or None), details=f"updated={updated} ids={ids}")
            except Exception:
                pass

            refreshed = cur.execute(
                f"SELECT id, visit_id, status FROM lab_requests WHERE id IN ({ph}) ORDER BY id",
                ids,
            ).fetchall()
            return jsonify({
                "ok": True,
                "updated_count": updated,
                "selected_count": len(ids),
                "open_visit": open_visit,
                "rows": [
                    {
                        "id": int((r["id"] if hasattr(r, "keys") and "id" in r.keys() else r[0]) or 0),
                        "visit_id": str((r["visit_id"] if hasattr(r, "keys") and "visit_id" in r.keys() else r[1]) or ""),
                        "status": str((r["status"] if hasattr(r, "keys") and "status" in r.keys() else r[2]) or "").upper(),
                    }
                    for r in (refreshed or [])
                ],
            })
        except Exception as exc:
            try:
                db.rollback()
            except Exception:
                pass
            try:
                _log_noncritical_exception("lab_bulk_collect_json failed", exc)
            except Exception:
                pass
            return jsonify({"ok": False, "error": "Bulk collect failed. Please refresh and try again."}), 500


# ---- Discharge Summary / Pharmacy: fail the save if pharmacy sync fails, using the same DB transaction ----
try:
    _ED_PREV_SYNC_PATIENT_HOME_MEDS_20260503 = globals().get("_sync_patient_home_meds_for_visit")

    def _sync_patient_home_meds_for_visit(db, visit_id, home_medication_raw, ordered_by, hm_changed):
        if not hm_changed:
            return ""
        visit_id = (visit_id or "").strip()
        if not visit_id:
            return ""
        cur = db.cursor()
        had_prior = False
        prev = cur.execute(
            "SELECT COUNT(*) AS c FROM patient_home_meds WHERE visit_id=?",
            (visit_id,),
        ).fetchone()
        if prev:
            try:
                had_prior = int(dict(prev).get("c") or 0) > 0
            except Exception:
                try:
                    had_prior = int(prev[0] or 0) > 0
                except Exception:
                    had_prior = False

        cur.execute("DELETE FROM patient_home_meds WHERE visit_id=?", (visit_id,))
        raw = (home_medication_raw or "").strip()
        if not raw or raw.upper() == "NONE":
            return ""
        rows = parse_home_medication_rows(home_medication_raw)
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        ordered_by = (ordered_by or "").strip() or ""
        initial_status = "Updated" if had_prior else "Pending"
        inserted = 0
        for r in rows:
            if isinstance(r, dict):
                med = (r.get("med") or "").strip()
                dx = (r.get("dx") or "").strip()
                if not dx:
                    dx = diagnosis_display(r.get("dx_name"), r.get("dx_code")).strip()
            else:
                med = (str(r) if r is not None else "").strip()
                dx = ""
            if (not med) and (not dx):
                continue
            if med.upper() in ("NONE", "-", "N/A") and not dx:
                continue
            cur.execute(
                """
                INSERT INTO patient_home_meds (
                    visit_id, medication_name, diagnosis_related, dosage_instructions,
                    dispense_status, ordered_at, ordered_by, last_updated_at
                ) VALUES (?,?,?,?,?,?,?,?)
                """,
                (
                    visit_id,
                    med or "-",
                    dx or None,
                    None,
                    initial_status,
                    now,
                    ordered_by or None,
                    now,
                ),
            )
            inserted += 1
        return initial_status if inserted > 0 else ""

    globals()["_sync_patient_home_meds_for_visit"] = _sync_patient_home_meds_for_visit
except Exception as _ed_pharmacy_sync_patch_exc_20260503:
    try:
        _log_noncritical_exception("ED UI performance patch: pharmacy sync wrapper failed", _ed_pharmacy_sync_patch_exc_20260503)
    except Exception:
        pass


