def _ed_dt_tpl_insert_before_endblock_20260503(template_text, block, marker_text):
    template_text = template_text or ""
    if marker_text in template_text:
        return template_text
    pos = template_text.rfind("{% endblock %}")
    if pos < 0:
        return template_text + "\n" + block + "\n"
    return template_text[:pos] + "\n" + block + "\n" + template_text[pos:]


def _ed_dt_tpl_insert_before_head_close_20260503(template_text, block, marker_text):
    template_text = template_text or ""
    if marker_text in template_text:
        return template_text
    low = template_text.lower()
    pos = low.rfind("</head>")
    if pos < 0:
        return block + "\n" + template_text
    return template_text[:pos] + "\n" + block + "\n" + template_text[pos:]


