@app.route("/scheduling")
@login_required
@role_required("reception", "nurse", "doctor", "admin", "inpatient_billing", "clinic_manager")
def scheduling_book():
    ensure_scheduling_schema()
    resources = _scheduling_resources()
    clinics = _scheduling_clinic_list(resources)
    selected_clinic = (request.args.get("clinic") or (clinics[0]["code"] if clinics else "OPD")).strip().upper()
    date_str = (request.args.get("date") or _sched_today()).strip()
    mrn = (request.args.get("mrn") or "").strip()
    step_minutes = max(5, _sched_int(request.args.get("step"), 15))

    # All active doctors assigned to this clinic.
    clinic_resources_all = _scheduling_resources_for_clinic(selected_clinic, resources)

    # Default operational view: show only doctors with an active schedule/template for this date,
    # plus any doctor with existing appointments that day so bookings never disappear.
    scheduled_resources = _scheduling_resources_open_for_day(clinic_resources_all, date_str)
    scheduled_resource_ids = {str(_sched_row_get(r, "id", 0, "")) for r in scheduled_resources}

    requested_resource_id = (request.args.get("resource_id") or "").strip()
    doctor_view = (request.args.get("doctor_view") or "scheduled").strip().lower()
    if doctor_view not in {"scheduled", "all", "available"}:
        doctor_view = "scheduled"

    if requested_resource_id:
        selected_resource_rows = [r for r in clinic_resources_all if str(_sched_row_get(r, "id", 0, "")) == str(requested_resource_id)]
        if selected_resource_rows:
            clinic_resources = selected_resource_rows
            resource_id = requested_resource_id
            effective_doctor_view = "single"
        else:
            clinic_resources = scheduled_resources or clinic_resources_all
            resource_id = ""
            effective_doctor_view = doctor_view
    else:
        resource_id = ""
        if doctor_view == "all":
            clinic_resources = clinic_resources_all
        elif doctor_view == "available":
            clinic_resources = _scheduling_resources_with_available_slots(scheduled_resources or clinic_resources_all, date_str)
        else:
            clinic_resources = scheduled_resources or clinic_resources_all
        effective_doctor_view = doctor_view

    selected_clinic_label = next((c["label"] for c in clinics if c["code"] == selected_clinic), selected_clinic)
    patient_matches = _scheduling_search_patient_by_mrn(mrn) if mrn else []
    grid_rows = _build_scheduling_grid(clinic_resources, date_str, step_minutes=step_minutes)
    rids = [_sched_row_get(r, "id", 0, 0) for r in clinic_resources_all]
    all_appointments = _scheduling_appointments_for_resources(rids, date_str)
    dashboard = _scheduling_dashboard(selected_clinic, date_str, clinic_resources_all)
    waitlist = _scheduling_waitlist_for_clinic(selected_clinic, date_str=date_str, limit=30)
    active_blocks = _scheduling_blocks_for_resources(rids, date_str)
    block_time_options = _scheduling_time_options(step_minutes=15, start_hour=0, end_hour=24)
    return render_template(
        "scheduling_book.html",
        resources=resources,
        clinics=clinics,
        clinic_resources=clinic_resources,
        clinic_resources_all=clinic_resources_all,
        scheduled_resources=scheduled_resources,
        scheduled_resource_ids=scheduled_resource_ids,
        doctor_view=doctor_view,
        effective_doctor_view=effective_doctor_view,
        selected_clinic=selected_clinic,
        selected_clinic_label=selected_clinic_label,
        resource_id=resource_id,
        date_str=date_str,
        mrn=mrn,
        step_minutes=step_minutes,
        patient_matches=patient_matches,
        grid_rows=grid_rows,
        all_appointments=all_appointments,
        dashboard=dashboard,
        waitlist=waitlist,
        active_blocks=active_blocks,
        block_time_options=block_time_options,
    )


@app.route("/scheduling/book", methods=["POST"])
@login_required
@role_required("reception", "nurse", "doctor", "admin", "inpatient_billing", "clinic_manager", "supervisor")
def scheduling_book_appointment():
    resource_id = (request.form.get("resource_id") or "").strip()
    patient_id = (request.form.get("patient_id") or "").strip()
    date_str = (request.form.get("date") or _sched_today()).strip()
    mrn = (request.form.get("mrn") or "").strip()
    clinic = (request.form.get("clinic") or "").strip().upper()
    start_time = (request.form.get("start_time") or "").strip()
    manual_hhmm = (request.form.get("manual_start_time") or "").strip()
    if manual_hhmm:
        start_time = f"{date_str} {manual_hhmm[:5]}:00"
    duration = _sched_int(request.form.get("duration"), 0)
    appointment_type = (request.form.get("appointment_type") or "Consultation").strip()
    try:
        appt_id = create_scheduled_appointment(patient_id, resource_id, start_time, notes=(request.form.get("notes") or ""), appointment_type=appointment_type, duration_override_minutes=duration or None)
        flash(f"Appointment #{appt_id} scheduled.", "success")
    except Exception as exc:
        flash(str(exc), "danger")
    return redirect(_scheduling_book_url(resource_id=None, date_str=date_str, mrn=mrn, clinic=clinic))


@app.route("/api/scheduling/patient_lookup")
@login_required
@role_required("reception", "nurse", "doctor", "admin", "inpatient_billing")
def api_scheduling_patient_lookup():
    q = (request.args.get("mrn") or request.args.get("q") or "").strip()
    rows = _scheduling_search_patient_by_mrn(q, limit=10)
    data = []
    for r in rows:
        data.append({
            "id": _sched_row_get(r, "id", 0, ""),
            "name": _sched_row_get(r, "name", 1, ""),
            "mrn": _sched_row_get(r, "mrn", 2, ""),
            "id_number": _sched_row_get(r, "id_number", 3, ""),
            "phone": _sched_row_get(r, "phone", 4, ""),
        })
    return jsonify(ok=True, patients=data)


