@app.route("/scheduling/appointments/<int:appointment_id>/cancel", methods=["POST"])
@login_required
@role_required("reception", "nurse", "doctor", "admin", "clinic_manager", "inpatient_billing", "supervisor")
def scheduling_cancel_appointment(appointment_id):
    ensure_scheduling_schema()
    db = get_db()
    cur = db.cursor()
    try:
        appt = _scheduling_lock_appointment(cur, appointment_id)
        if _sched_normalize_status(_sched_row_get(appt, "status", 5, "")) == SCHEDULING_STATUS_ARRIVED:
            raise ValueError("Arrived appointment already has an encounter. Cancel/close the encounter from the patient workflow if needed.")
        now_ts = _sched_now()
        actor = session.get("username") or "SYSTEM"
        reason = (request.form.get("reason") or request.form.get("cancel_reason") or "Canceled from Scheduling Book").strip()
        cur.execute(
            """
            UPDATE appointments
               SET status=?, canceled_at=?, canceled_by=?, cancel_reason=?
             WHERE id=?
            """,
            (SCHEDULING_STATUS_CANCELED, now_ts, actor, reason, int(appointment_id)),
        )
        is_overbook = _sched_int(_sched_row_get(appt, "is_overbook", None, 0), 0)
        audit_action = "OVERBOOK_CANCELED" if is_overbook else "CANCELED"
        _scheduling_audit(cur, appointment_id, audit_action, {"reason": reason, "is_overbook": bool(is_overbook)})
        db.commit()
        try:
            log_action("APPOINTMENT_OVERBOOK_CANCELED" if is_overbook else "APPOINTMENT_CANCELED", details=f"appointment_id={appointment_id}|reason={reason}")
        except Exception:
            pass
        flash("Overbook appointment canceled." if is_overbook else "Appointment canceled.", "warning")
    except Exception as exc:
        _rollback_with_logging(db, "scheduling_cancel_appointment")
        flash(str(exc), "danger")
    return redirect(request.referrer or url_for("scheduling_book"))


@app.route("/scheduling/waitlist", methods=["POST"])
@login_required
@role_required("reception", "nurse", "doctor", "admin", "inpatient_billing")
def scheduling_add_waitlist():
    ensure_scheduling_schema()
    db = get_db()
    cur = db.cursor()
    clinic = (request.form.get("clinic") or "OPD").strip().upper()
    date_str = (request.form.get("date") or _sched_today()).strip()
    mrn = (request.form.get("mrn") or "").strip()
    try:
        patient_id = _sched_int(request.form.get("patient_id"), 0)
        if not patient_id:
            raise ValueError("Select a patient before adding to waitlist.")
        resource_id = _sched_int(request.form.get("resource_id"), 0) or None
        notes = (request.form.get("notes") or "").strip()
        now_ts = _sched_now()
        actor = session.get("username") or "SYSTEM"
        cur.execute(
            """
            INSERT INTO appointment_waitlist (patient_id, clinic, resource_id, preferred_date, status, notes, created_at, created_by)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (patient_id, clinic, resource_id, date_str, SCHEDULING_WAITLIST_PENDING, notes, now_ts, actor),
        )
        _scheduling_audit(cur, None, "WAITLIST_ADDED", {"patient_id": patient_id, "clinic": clinic, "resource_id": resource_id, "date": date_str})
        db.commit()
        flash("Patient added to waitlist.", "success")
    except Exception as exc:
        _rollback_with_logging(db, "scheduling_add_waitlist")
        flash(str(exc), "danger")
    return redirect(_scheduling_book_url(date_str=date_str, mrn=mrn, clinic=clinic))


@app.route("/scheduling/block", methods=["POST"])
@login_required
@role_required("doctor", "admin", "clinic_manager", "supervisor")
def scheduling_block_time():
    clinic = (request.form.get("clinic") or "OPD").strip().upper()
    date_str = (request.form.get("date") or _sched_today()).strip()
    try:
        reason_code = (request.form.get("reason_code") or request.form.get("reason") or "Blocked").strip()
        reason_other = (request.form.get("reason_other") or "").strip()
        reason = reason_other if reason_code.lower() == "other" and reason_other else reason_code
        _scheduling_create_block(
            request.form.get("resource_id"),
            date_str,
            request.form.get("start_time"),
            request.form.get("end_time"),
            reason=reason or "Blocked",
        )
        flash("Time blocked successfully.", "success")
    except Exception as exc:
        flash(str(exc), "danger")
    return redirect(_scheduling_book_url(date_str=date_str, clinic=clinic))


@app.route("/scheduling/resources", methods=["POST"])
@login_required
@role_required("admin")
def scheduling_add_resource():
    ensure_scheduling_schema()
    db = get_db()
    cur = db.cursor()
    try:
        name = (request.form.get("name") or "").strip()
        resource_type = (request.form.get("resource_type") or "doctor").strip().lower()
        clinic = (request.form.get("clinic") or "OPD").strip().upper()
        specialty = (request.form.get("specialty") or "").strip()
        actor = session.get("username") or "SYSTEM"
        daily_schedule_rows = _sched_daily_schedule_rows_from_form(request.form) if resource_type == "doctor" else None
        schedule_effective_from = _sched_clean_date(
            request.form.get("daily_schedule_effective_from") or request.form.get("date"),
            _sched_today(),
        )
        rid = _sched_insert_resource(cur, name=name, resource_type=resource_type, clinic=clinic, specialty=specialty, actor=actor)
        _sched_seed_template_for_resource(cur, rid, actor=actor, schedule_rows=daily_schedule_rows)
        _scheduling_audit(cur, None, "RESOURCE_ADDED", {"resource_id": rid, "name": name, "type": resource_type, "clinic": clinic, "daily_schedule_rows": daily_schedule_rows or [], "schedule_effective_from": schedule_effective_from})
        db.commit()
        flash("Scheduling resource saved.", "success")
        return redirect(url_for("scheduling_book", clinic=clinic, date=schedule_effective_from, doctor_view='scheduled'))
    except Exception as exc:
        _rollback_with_logging(db, "scheduling_add_resource")
        flash(str(exc), "danger")
        return redirect(url_for("scheduling_book"))


@app.route("/scheduling/templates", methods=["POST"])
@login_required
@role_required("admin")
def scheduling_add_template():
    ensure_scheduling_schema()
    db = get_db()
    cur = db.cursor()
    clinic = (request.form.get("clinic") or "OPD").strip().upper()
    try:
        rid = _scheduling_lock_resource(cur, request.form.get("resource_id"))
        shift_start = (request.form.get("shift_start") or "08:00").strip()[:5]
        shift_end = (request.form.get("shift_end") or "16:00").strip()[:5]
        duration = max(1, _sched_int(request.form.get("duration"), 15))
        weekday_raw = (request.form.get("weekday") or "all").strip().lower()
        weekdays = list(range(7)) if weekday_raw == "all" else [_sched_int(weekday_raw, 0)]
        now_ts = _sched_now()
        actor = session.get("username") or "SYSTEM"
        for wd in weekdays:
            if wd < 0 or wd > 6:
                continue
            cur.execute(
                """
                INSERT INTO scheduling_templates
                    (resource_id, weekday, shift_start, shift_end, slot_duration_minutes, effective_from, effective_to, is_active, created_at, created_by)
                VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?)
                """,
                (rid, wd, shift_start, shift_end, duration, "", "", now_ts, actor),
            )
        _scheduling_audit(cur, None, "TEMPLATE_ADDED", {"resource_id": rid, "shift_start": shift_start, "shift_end": shift_end, "duration": duration, "weekdays": weekdays})
        db.commit()
        flash("Scheduling template saved.", "success")
        return redirect(url_for("scheduling_book", clinic=clinic, date=_sched_today(), doctor_view='scheduled'))
    except Exception as exc:
        _rollback_with_logging(db, "scheduling_add_template")
        flash(str(exc), "danger")
        return redirect(request.referrer or url_for("scheduling_book"))


