        _nav_v3_a = '<a id="ed-nav-appointments" class="nav-link {% if request.path.startswith(\'/scheduling\') %}active fw-bold text-primary{% endif %}" href="/scheduling">Appointments</a>'
        _target_v3 = '<li class="nav-item"><a class="nav-link" href="{{ url_for(\'clinic_board\') }}">Clinic Board</a></li>'
