# ============================================================
# SCHEDULING_BLOCK_OVERLAY_ON_APPOINTMENTS_20260507
# Scheduling-only UI refinement:
# When a doctor block overlaps an existing appointment, show the block beside
# the appointment in the same grid cell. The appointment remains untouched;
# the block remains visible so call center/reception can see the closed period
# at a glance. No non-scheduling workflow is changed.
# ============================================================
def _apply_scheduling_block_overlay_on_appointments_ui_patch():
    try:
        tpl = TEMPLATES.get("scheduling_book.html") or ""
        if "SCHEDULING_BLOCK_OVERLAY_ON_APPOINTMENTS_20260507" in tpl:
            return True

        changed = False

        # 1) Add a compact amber block strip that can live inside appointment cells.
        style_anchor = '  .sched-slot-btn[data-state="blocked"] { border-color: #ffc107; background: #fff8e1; color: #664d03; }'
        overlay_css = (
            '\n  .sched-cell-has-block { background: linear-gradient(90deg,#eef5ff 0%,#eef5ff 62%,#fff8e1 62%,#fff8e1 100%); }'
            '\n  .sched-slot-btn[data-state="appointment"][data-has-block="1"] { border-color:#ffb000; background:linear-gradient(90deg,#eef5ff 0%,#eef5ff 64%,#fff8e1 64%,#fff8e1 100%); color:#084298; }'
            '\n  .sched-block-beside { margin-top:.35rem; border:1px solid #ffc107; background:#fff8e1; color:#664d03; border-radius:8px; padding:.2rem .35rem; line-height:1.15; }'
            '\n  .sched-block-beside .sched-block-time { font-weight:700; }'
        )
        if style_anchor in tpl and ".sched-block-beside" not in tpl:
            tpl = tpl.replace(style_anchor, style_anchor + overlay_css, 1)
            changed = True

        # 2) Make the table cell visually indicate appointment + block overlap.
        td_anchor = '''<td class="sched-cell {% if cell.state == 'available' %}sched-cell-available{% elif cell.state == 'blocked' %}sched-cell-blocked{% elif cell.state == 'appointment' and a and a.status == 'Arrived' %}sched-cell-arrived{% elif cell.state == 'appointment' and a and a.status == 'Canceled' %}sched-cell-canceled{% elif cell.state == 'appointment' %}sched-cell-booked{% else %}sched-cell-off{% endif %}">'''
        td_repl = '''<td class="sched-cell {% if cell.block_count and cell.state == 'appointment' %}sched-cell-has-block {% endif %}{% if cell.state == 'available' %}sched-cell-available{% elif cell.state == 'blocked' %}sched-cell-blocked{% elif cell.state == 'appointment' and a and a.status == 'Arrived' %}sched-cell-arrived{% elif cell.state == 'appointment' and a and a.status == 'Canceled' %}sched-cell-canceled{% elif cell.state == 'appointment' %}sched-cell-booked{% else %}sched-cell-off{% endif %}">'''
        if td_anchor in tpl and "cell.block_count and cell.state == 'appointment'" not in tpl:
            tpl = tpl.replace(td_anchor, td_repl, 1)
            changed = True

        # 3) Expose block metadata to the existing popup even when the cell state is appointment.
        data_anchor_with_impact = '''data-block-reason="{{ b.reason|e if b else '' }}" data-needs-reschedule="{{ a.needs_reschedule if a else 0 }}" data-reschedule-reason="{{ a.reschedule_reason|e if a else '' }}">'''
        data_repl_with_impact = '''data-block-reason="{{ b.reason|e if b else '' }}" data-block-count="{{ cell.block_count or 0 }}" data-has-block="{% if b %}1{% else %}0{% endif %}" data-block-start="{{ b.start_time[11:16] if b and b.start_time else '' }}" data-block-end="{{ b.end_time[11:16] if b and b.end_time else '' }}" data-needs-reschedule="{{ a.needs_reschedule if a else 0 }}" data-reschedule-reason="{{ a.reschedule_reason|e if a else '' }}">'''
        data_anchor_plain = '''data-block-reason="{{ b.reason|e if b else '' }}">'''
        data_repl_plain = '''data-block-reason="{{ b.reason|e if b else '' }}" data-block-count="{{ cell.block_count or 0 }}" data-has-block="{% if b %}1{% else %}0{% endif %}" data-block-start="{{ b.start_time[11:16] if b and b.start_time else '' }}" data-block-end="{{ b.end_time[11:16] if b and b.end_time else '' }}">'''
        if "data-has-block=" not in tpl:
            if data_anchor_with_impact in tpl:
                tpl = tpl.replace(data_anchor_with_impact, data_repl_with_impact, 1)
                changed = True
            elif data_anchor_plain in tpl:
                tpl = tpl.replace(data_anchor_plain, data_repl_plain, 1)
                changed = True

        # 4) Show the active block beside the appointment details, not only in empty slots.
        appt_mrn_line = '''<div class="sched-small text-muted">MRN: {{ a.mrn or '-' }}</div>'''
        block_overlay_html = '''<div class="sched-small text-muted">MRN: {{ a.mrn or '-' }}</div>
                  {% if cell.block_count and b %}
                  <div class="sched-block-beside sched-small">
                    <div><span class="badge bg-warning text-dark">Doctor Blocked</span></div>
                    <div class="sched-block-time">{{ b.start_time[11:16] if b.start_time else '' }} - {{ b.end_time[11:16] if b.end_time else '' }}</div>
                    <div>{{ b.reason or 'Blocked' }}</div>
                  </div>
                  {% endif %}'''
        if appt_mrn_line in tpl and "sched-block-beside sched-small" not in tpl:
            tpl = tpl.replace(appt_mrn_line, block_overlay_html, 1)
            changed = True

        # 5) Popup should show/unblock block details even when an appointment occupies the slot.
        js_blocked_anchor = "var blocked = qs('#m-block-details'); if(blocked) blocked.classList.toggle('d-none', state !== 'blocked');"
        js_blocked_repl = "var blocked = qs('#m-block-details'); if(blocked) blocked.classList.toggle('d-none', !(state === 'blocked' || d.blockId));"
        if js_blocked_anchor in tpl:
            tpl = tpl.replace(js_blocked_anchor, js_blocked_repl, 1)
            changed = True

        js_state_anchor = "if(state === 'blocked') stateLabel = 'Blocked';"
        js_state_repl = "if(state === 'blocked') stateLabel = 'Blocked';\n    if(state === 'appointment' && d.blockId) stateLabel += ' + Doctor Blocked';"
        if js_state_anchor in tpl and "Doctor Blocked';" not in tpl:
            tpl = tpl.replace(js_state_anchor, js_state_repl, 1)
            changed = True

        js_reason_anchor = "setText('#m-block-reason', d.blockReason || 'Unavailable');"
        js_reason_repl = "setText('#m-block-reason', ((d.blockStart || d.blockEnd) ? ((d.blockStart || '-') + ' - ' + (d.blockEnd || '-') + ' · ') : '') + (d.blockReason || 'Unavailable'));"
        if js_reason_anchor in tpl:
            tpl = tpl.replace(js_reason_anchor, js_reason_repl, 1)
            changed = True

        js_unblock_anchor = "if(unblockForm) unblockForm.querySelector('button').disabled = !(state === 'blocked' && d.blockId);"
        js_unblock_repl = "if(unblockForm) unblockForm.querySelector('button').disabled = !d.blockId;"
        if js_unblock_anchor in tpl:
            tpl = tpl.replace(js_unblock_anchor, js_unblock_repl, 1)
            changed = True

        tpl += "\n<!-- SCHEDULING_BLOCK_OVERLAY_ON_APPOINTMENTS_20260507 -->\n"
        if changed:
            TEMPLATES["scheduling_book.html"] = tpl
            try:
                app.jinja_loader = DictLoader(TEMPLATES)
            except Exception:
                pass
        return True
    except Exception as exc:
        try:
            _log_noncritical_exception("Scheduling block overlay on appointments UI patch failed", exc)
        except Exception:
            pass
        return False

try:
    _apply_scheduling_block_overlay_on_appointments_ui_patch()
    if "ENDPOINT_PERMISSION_MAP" in globals():
        ENDPOINT_PERMISSION_MAP.setdefault("scheduling_unblock_time", "boards_scheduling")
    app.logger.info("SCHEDULING_BLOCK_OVERLAY_ON_APPOINTMENTS_20260507 loaded")
except Exception as _sched_block_overlay_load_exc:
    try:
        _log_noncritical_exception("Scheduling block overlay on appointments workflow load failed", _sched_block_overlay_load_exc)
    except Exception:
        pass



# ============================================================
# SCHEDULING_CALL_CENTER_TODAY_PANEL_20260507
# Scope-limited patch for the attached Scheduling build:
# - Add Call Center Agent role with Scheduling access only.
# - Hide Today Appointments by default behind a side arrow toggle.
# - Remove Register action from Scheduling Today Appointments list.
# No other project modules or registration workflow are changed.
# ============================================================
def _apply_scheduling_call_center_role_and_today_panel_patch():
    try:
        # 1) Role normalization aliases.
        try:
            _ROLE_ALIASES.update({
                "call center": "call_center_agent",
                "call centre": "call_center_agent",
                "call center agent": "call_center_agent",
                "call centre agent": "call_center_agent",
                "call_center": "call_center_agent",
                "call_center_agent": "call_center_agent",
            })
        except Exception:
            pass

        # 2) Permission catalog: Scheduling/Appointments only by default.
        try:
            if "PERMISSION_GROUPS" in globals():
                exists = any(k == "boards_scheduling" for group in PERMISSION_GROUPS.values() for k, _label in group)
                if not exists:
                    PERMISSION_GROUPS.setdefault("boards", []).append(("boards_scheduling", "Appointments / Scheduling"))
            if "ALL_PERMISSION_KEYS" in globals():
                ALL_PERMISSION_KEYS.add("boards_scheduling")
        except Exception:
            pass

        # 3) Default permissions for the new role.
        try:
            old_default_permissions = globals().get("_default_permissions_for_role")
            if old_default_permissions and not getattr(old_default_permissions, "_call_center_agent_wrapped", False):
                def _default_permissions_for_role_call_center(role):
                    r = normalize_role_key(role)
                    if r == "call_center_agent":
                        return {"boards_scheduling", "core_search", "core_patient_details", "core_live_chat"}
                    return old_default_permissions(role)
                _default_permissions_for_role_call_center._call_center_agent_wrapped = True
                globals()["_default_permissions_for_role"] = _default_permissions_for_role_call_center
        except Exception:
            pass

        # 4) User-facing role display label.
        try:
            old_role_display = globals().get("role_display")
            if old_role_display and not getattr(old_role_display, "_call_center_agent_wrapped", False):
                def role_display_call_center(role):
                    if normalize_role_key(role) == "call_center_agent":
                        return "Call Center Agent"
                    return old_role_display(role)
                role_display_call_center._call_center_agent_wrapped = True
                globals()["role_display"] = role_display_call_center
                try:
                    app.jinja_env.globals["role_display"] = role_display_call_center
                except Exception:
                    pass
        except Exception:
            pass

        # 5) Landing page for the role.
        try:
            old_login_redirect = globals().get("login_redirect_for_role")
            if old_login_redirect and not getattr(old_login_redirect, "_call_center_agent_wrapped", False):
                def login_redirect_for_role_call_center(role):
                    if normalize_role_key(role) == "call_center_agent":
                        try:
                            return redirect(url_for("scheduling_book"))
                        except Exception:
                            return redirect("/scheduling")
                    return old_login_redirect(role)
                login_redirect_for_role_call_center._call_center_agent_wrapped = True
                globals()["login_redirect_for_role"] = login_redirect_for_role_call_center
        except Exception:
            pass

        # 6) Add the role to Users Management dropdown. User Permissions includes it in the route role list.
        try:
            tpl_users = TEMPLATES.get("admin_users.html") or ""
            if 'value="call_center_agent"' not in tpl_users:
                tpl_users = tpl_users.replace(
                    '<option value="reception">reception</option>',
                    '<option value="reception">reception</option>\n        <option value="call_center_agent">Call Center Agent</option>',
                    1,
                )
                TEMPLATES["admin_users.html"] = tpl_users
        except Exception:
            pass

        # 7) Ensure the role_permissions row exists and includes Scheduling.
        # This runs inside an app context because the single-file DB helper uses Flask g.
        try:
            with app.app_context():
                init_role_permissions_table()
                db = get_db()
                cur = db.cursor()
                role = "call_center_agent"
                now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                desired = set(_default_permissions_for_role(role))
                row = cur.execute("SELECT permissions_json FROM role_permissions WHERE role=?", (role,)).fetchone()
                if row:
                    raw = _fetch_one_val(row, "permissions_json", 0) or "[]"
                    try:
                        perms = set(json.loads(raw) or [])
                    except Exception:
                        perms = set()
                    if "boards_scheduling" not in perms:
                        perms |= desired
                        cur.execute(
                            "UPDATE role_permissions SET permissions_json=?, updated_at=?, updated_by=? WHERE role=?",
                            (json.dumps(sorted(perms)), now, "system", role),
                        )
                else:
                    cur.execute(
                        "INSERT INTO role_permissions (role, permissions_json, updated_at, updated_by) VALUES (?,?,?,?)",
                        (role, json.dumps(sorted(desired)), now, "system"),
                    )
                db.commit()
        except Exception as exc:
            try:
                _log_noncritical_exception("Call Center Agent role permission seed skipped", exc)
            except Exception:
                pass

        # 8) Scheduling template: collapsible Today Appointments + no Register action.
        try:
            tpl = TEMPLATES.get("scheduling_book.html") or ""
            changed = False

            # Remove the Today Appointments direct Register button injected by an earlier patch.
            before = tpl
            tpl = re.sub(
                r"\s*\{%\s*if\s+a\.status\s*==\s*'Scheduled'\s*%\}\s*<form\s+method=\"POST\"\s+action=\"\{\{\s*url_for\('scheduling_register_appointment',\s*appointment_id=a\.id\)\s*\}\}\".*?</form>\s*\{%\s*endif\s*%\}",
                "",
                tpl,
                flags=re.S,
            )
            if tpl != before:
                changed = True

            if "SCHEDULING_TODAY_COLLAPSE_20260507" not in tpl:
                css = '''
  .sched-today-card .sched-today-panel { display:block; }
  .sched-today-card.collapsed .sched-today-panel { display:none; }
  .sched-today-toggle { border-radius:999px; min-width:86px; }
  .sched-today-toggle .arrow { display:inline-block; transition:transform .18s ease; }
  .sched-today-card:not(.collapsed) .sched-today-toggle .arrow { transform:rotate(90deg); }
'''
                if "</style>" in tpl and ".sched-today-toggle" not in tpl:
                    tpl = tpl.replace("</style>", css + "\n</style>", 1)
                    changed = True

                start = '<div class="card bg-white p-3 shadow-sm h-100">\n      <h5 class="mb-2">Today Appointments</h5>\n      <div class="list-group list-group-flush">'
                repl = '<div class="card bg-white p-3 shadow-sm h-100 sched-today-card collapsed" id="sched-today-appointments-card">\n      <div class="d-flex justify-content-between align-items-center mb-2">\n        <h5 class="mb-0">Today Appointments</h5>\n        <button type="button" class="btn btn-sm btn-outline-secondary sched-today-toggle" id="sched-today-toggle" aria-expanded="false" aria-controls="sched-today-panel">\n          <span class="arrow">▶</span> <span class="label">Show</span>\n        </button>\n      </div>\n      <div class="sched-today-panel" id="sched-today-panel">\n      <div class="list-group list-group-flush">'
                if start in tpl:
                    tpl = tpl.replace(start, repl, 1)
                    waitlist_marker = '\n  <div class="col-xl-6">\n    <div class="card bg-white p-3 shadow-sm h-100">\n      <div class="d-flex justify-content-between align-items-center mb-2">\n        <h5 class="mb-0">Waitlist</h5>'
                    idx = tpl.find(repl)
                    j = tpl.find(waitlist_marker, idx + len(repl)) if idx != -1 else -1
                    close_seq = '\n      </div>\n    </div>\n  </div>'
                    if j != -1:
                        k = tpl.rfind(close_seq, idx, j)
                        if k != -1:
                            tpl = tpl[:k] + '\n      </div>' + tpl[k:]
                    changed = True

                js = r'''
<script>
document.addEventListener('DOMContentLoaded', function(){
  var card = document.getElementById('sched-today-appointments-card');
  var btn = document.getElementById('sched-today-toggle');
  if(!card || !btn) return;
  function syncTodayToggle(){
    var collapsed = card.classList.contains('collapsed');
    btn.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
    var label = btn.querySelector('.label');
    if(label) label.textContent = collapsed ? 'Show' : 'Hide';
  }
  btn.addEventListener('click', function(){
    card.classList.toggle('collapsed');
    syncTodayToggle();
  });
  syncTodayToggle();
});
</script>
<!-- SCHEDULING_TODAY_COLLAPSE_20260507 -->
'''
                if "SCHEDULING_TODAY_COLLAPSE_20260507" not in tpl:
                    tpl = tpl.replace("{% endblock %}", js + "\n{% endblock %}", 1)
                    changed = True

            if changed:
                TEMPLATES["scheduling_book.html"] = tpl
                try:
                    app.jinja_loader = DictLoader(TEMPLATES)
                except Exception:
                    pass
        except Exception as exc:
            try:
                _log_noncritical_exception("Scheduling Today Appointments collapse patch failed", exc)
            except Exception:
                pass

        return True
    except Exception as exc:
        try:
            _log_noncritical_exception("Scheduling Call Center / Today panel patch failed", exc)
        except Exception:
            pass
        return False

try:
    _apply_scheduling_call_center_role_and_today_panel_patch()
    if "ENDPOINT_PERMISSION_MAP" in globals():
        for _cc_ep in (
            "scheduling_book",
            "scheduling_book_appointment",
            "scheduling_add_waitlist",
            "scheduling_cancel_appointment",
            "scheduling_reschedule_impacted_appointment",
            "scheduling_clear_appointment_impact",
            "scheduling_update_appointment_impact_contact",
            "api_scheduling_book_popup_submit",
            "api_scheduling_patient_lookup",
            "api_scheduling_patient_quick_register",
        ):
            ENDPOINT_PERMISSION_MAP.setdefault(_cc_ep, "boards_scheduling")
    app.logger.info("SCHEDULING_CALL_CENTER_TODAY_PANEL_20260507 loaded")
except Exception as _sched_call_center_load_exc:
    try:
        _log_noncritical_exception("Scheduling Call Center / Today panel load failed", _sched_call_center_load_exc)
    except Exception:
        pass

# ============================================================
# SCHEDULING_POPUP_APPOINTMENT_RESCHEDULE_20260507
# Scope-limited professional fix for booked-slot popup:
# - Opening an existing appointment auto-selects that appointment patient.
# - Popup shows full appointment/patient details for the booked slot.
# - Call Center can move the scheduled appointment to another doctor/date/time
#   from the same popup, with conflict/template validation and audit trail.
# No registration workflow or other project modules are changed.
# ============================================================
def _ensure_scheduling_popup_move_schema():
    """Ensure lightweight audit columns exist for appointment move updates."""
    try:
        _ensure_scheduling_block_impact_schema()
    except Exception:
        try:
            ensure_scheduling_schema()
        except Exception:
            pass
    db = get_db()
    cur = db.cursor()
    try:
        if DB_ENGINE == "postgres":
            for col_sql in (
                "updated_at TEXT",
                "updated_by TEXT",
            ):
                try:
                    cur.execute(f"ALTER TABLE appointments ADD COLUMN IF NOT EXISTS {col_sql}")
                except Exception:
                    pass
        else:
            for name, col_sql in (
                ("updated_at", "updated_at TEXT"),
                ("updated_by", "updated_by TEXT"),
            ):
                try:
                    _sched_add_sqlite_column_if_missing(cur, "appointments", name, col_sql)
                except Exception:
                    pass
        db.commit()
        return True
    except Exception as exc:
        _rollback_with_logging(db, "_ensure_scheduling_popup_move_schema")
        try:
            _log_noncritical_exception("Scheduling popup move schema failed", exc)
        except Exception:
            pass
        return False

@app.route("/scheduling/appointments/<int:appointment_id>/move", methods=["POST"])
@login_required
@role_required("reception", "nurse", "doctor", "admin", "clinic_manager", "inpatient_billing", "supervisor", "call_center_agent")
def scheduling_move_appointment_from_popup(appointment_id):
    """Move a scheduled appointment from the slot popup to a new doctor/date/time."""
    _ensure_scheduling_popup_move_schema()
    db = get_db()
    cur = db.cursor()
    clinic = (request.form.get("clinic") or "OPD").strip().upper()
    current_date = (request.form.get("date") or _sched_today()).strip()
    mrn = (request.form.get("mrn") or "").strip()
    try:
        appt = _scheduling_lock_appointment(cur, appointment_id)
        if not appt:
            raise ValueError("Appointment not found.")
        if _sched_normalize_status(_sched_row_get(appt, "status", 5, "")) != SCHEDULING_STATUS_SCHEDULED:
            raise ValueError("Only scheduled appointments can be moved. Arrived or canceled appointments cannot be changed here.")

        old_resource_id = _sched_int(_sched_row_get(appt, "resource_id", 2, 0), 0)
        old_start = _sched_row_get(appt, "start_time", 3, "")
        old_end = _sched_row_get(appt, "end_time", 4, "")
        was_impacted = _sched_int(_sched_row_get(appt, "needs_reschedule", None, 0), 0) == 1

        new_resource_id = request.form.get("new_resource_id") or request.form.get("resource_id") or old_resource_id
        rid = _scheduling_lock_resource(cur, new_resource_id)
        target_date = (request.form.get("new_date") or current_date or _sched_today()).strip()
        target_start = (request.form.get("new_start_time") or request.form.get("start_time") or "").strip()[:5]
        if not target_start:
            raise ValueError("Select the new appointment time.")

        start_dt = _sched_parse_local_datetime(f"{target_date} {target_start}")
        duration = _sched_int(request.form.get("duration"), 0)
        if duration <= 0:
            try:
                old_start_dt = _sched_parse_local_datetime(old_start)
                old_end_dt = _sched_parse_local_datetime(old_end)
                duration = max(1, int((old_end_dt - old_start_dt).total_seconds() // 60))
            except Exception:
                duration = _sched_template_duration(cur, rid, start_dt, fallback=15)
        duration = max(1, duration)
        end_dt = start_dt + timedelta(minutes=duration)

        if not _scheduling_is_inside_shift(cur, rid, start_dt, end_dt):
            raise ValueError("New time is outside the doctor's working template.")
        if _scheduling_has_appointment_overlap(cur, rid, start_dt, end_dt, exclude_appointment_id=appointment_id):
            raise ValueError("New time already has another appointment. Choose an available slot.")
        if _scheduling_has_block_overlap(cur, rid, start_dt, end_dt):
            raise ValueError("New time is blocked. Choose an available slot or use the supervised overbook workflow.")

        actor = session.get("username") or "SYSTEM"
        now_ts = _sched_now()
        note = (request.form.get("move_note") or request.form.get("contact_note") or "Patient requested appointment change").strip()

        if was_impacted:
            cur.execute(
                """
                UPDATE appointments
                   SET resource_id=?, start_time=?, end_time=?,
                       needs_reschedule=0,
                       reschedule_reason=NULL,
                       blocked_by_block_id=NULL,
                       patient_contact_status='Rescheduled',
                       patient_contact_note=?,
                       updated_at=?,
                       updated_by=?
                 WHERE id=?
                """,
                (rid, _sched_dt_to_str(start_dt), _sched_dt_to_str(end_dt), note, now_ts, actor, int(appointment_id)),
            )
        else:
            cur.execute(
                """
                UPDATE appointments
                   SET resource_id=?, start_time=?, end_time=?,
                       updated_at=?,
                       updated_by=?
                 WHERE id=?
                """,
                (rid, _sched_dt_to_str(start_dt), _sched_dt_to_str(end_dt), now_ts, actor, int(appointment_id)),
            )

        _scheduling_audit(cur, appointment_id, "APPOINTMENT_MOVED_FROM_POPUP", {
            "old_resource_id": old_resource_id,
            "old_start_time": old_start,
            "old_end_time": old_end,
            "new_resource_id": rid,
            "new_start_time": _sched_dt_to_str(start_dt),
            "new_end_time": _sched_dt_to_str(end_dt),
            "note": note,
            "was_impacted": 1 if was_impacted else 0,
        })
        db.commit()
        try:
            log_action(
                "APPOINTMENT_MOVED_FROM_POPUP",
                details=f"appointment_id={appointment_id}|resource_id={old_resource_id}->{rid}|start={old_start}->{_sched_dt_to_str(start_dt)}",
            )
        except Exception:
            pass
        flash("Appointment moved successfully. Patient booking details were preserved.", "success")
        return redirect(_scheduling_book_url(resource_id=rid, date_str=target_date, mrn=mrn, clinic=clinic))
    except Exception as exc:
        _rollback_with_logging(db, "scheduling_move_appointment_from_popup")
        flash(str(exc), "danger")
        return redirect(_scheduling_book_url(date_str=current_date, mrn=mrn, clinic=clinic))


