# ============================================================
# ADMIN_CLINICS_TO_SCHEDULING_SYNC_20260507
# Scope-limited professional sync:
# - When Admin - Orders Items adds/updates active Clinics, make them available
#   as clinic resources in Appointments / Scheduling Center automatically.
# - Keeps the existing scheduling doctor/template workflow unchanged.
# - Does not auto-import doctors and does not alter other admin lists.
# ============================================================
def _scheduling_sync_active_admin_clinics_to_resources(actor=None):
    """Ensure every active Admin Clinics row has a Scheduling clinic resource."""
    try:
        actor = actor or (session.get("username") if "session" in globals() else None) or "SYSTEM"
    except Exception:
        actor = "SYSTEM"

    try:
        ensure_scheduling_schema(seed_defaults=False)
    except TypeError:
        ensure_scheduling_schema()
    except Exception as exc:
        try:
            _log_noncritical_exception("Admin Clinics to Scheduling sync schema check failed", exc)
        except Exception:
            pass
        return 0

    try:
        clinic_pairs = list(_sched_clinic_pairs() or [])
    except Exception:
        try:
            clinic_pairs = list(get_clinics_for_ui() or [])
        except Exception:
            clinic_pairs = []

    db = get_db()
    cur = db.cursor()
    synced = 0
    try:
        for raw_code, raw_label in clinic_pairs:
            clinic_code = str(raw_code or raw_label or "").strip().upper()
            clinic_label = str(raw_label or raw_code or clinic_code).strip()
            if not clinic_code:
                continue
            clinic_label = clinic_label or clinic_code

            existing = cur.execute(
                """
                SELECT id
                FROM scheduling_resources
                WHERE resource_type='clinic'
                  AND UPPER(COALESCE(clinic,''))=?
                ORDER BY id ASC
                LIMIT 1
                """,
                (clinic_code,),
            ).fetchone()

            if existing:
                rid = _sched_int(_sched_row_get(existing, "id", 0, 0), 0)
                if rid:
                    cur.execute(
                        """
                        UPDATE scheduling_resources
                           SET name=?, clinic=?, is_active=1
                         WHERE id=?
                        """,
                        (clinic_label, clinic_code, rid),
                    )
                    _sched_seed_template_for_resource(cur, rid, actor=actor)
                    synced += 1
                continue

            rid = _sched_insert_resource(
                cur,
                name=clinic_label,
                resource_type="clinic",
                clinic=clinic_code,
                specialty="",
                code=_sched_resource_code(clinic_label, clinic_code, "clinic"),
                actor=actor,
            )
            if rid:
                _sched_seed_template_for_resource(cur, rid, actor=actor)
                try:
                    _scheduling_audit(cur, None, "ADMIN_CLINIC_SYNCED_TO_SCHEDULING", {
                        "resource_id": rid,
                        "clinic": clinic_code,
                        "label": clinic_label,
                    })
                except Exception:
                    pass
                synced += 1

        db.commit()
        return synced
    except Exception as exc:
        _rollback_with_logging(db, "_scheduling_sync_active_admin_clinics_to_resources")
        try:
            _log_noncritical_exception("Admin Clinics to Scheduling sync failed", exc)
        except Exception:
            pass
        return 0


try:
    _orig_scheduling_book_admin_clinic_sync = app.view_functions.get("scheduling_book")
    if callable(_orig_scheduling_book_admin_clinic_sync) and not getattr(_orig_scheduling_book_admin_clinic_sync, "_admin_clinic_sync_wrapped", False):
        def _scheduling_book_with_admin_clinic_sync(*args, **kwargs):
            try:
                _scheduling_sync_active_admin_clinics_to_resources(actor=(session.get("username") or "SYSTEM"))
            except Exception as exc:
                try:
                    _log_noncritical_exception("Scheduling page admin clinic sync skipped", exc)
                except Exception:
                    pass
            return _orig_scheduling_book_admin_clinic_sync(*args, **kwargs)

        _scheduling_book_with_admin_clinic_sync._admin_clinic_sync_wrapped = True
        app.view_functions["scheduling_book"] = _scheduling_book_with_admin_clinic_sync
except Exception as _admin_clinic_sched_wrap_exc:
    try:
        _log_noncritical_exception("Scheduling page admin clinic sync wrapper failed", _admin_clinic_sched_wrap_exc)
    except Exception:
        pass


try:
    _orig_admin_items_admin_clinic_sync = app.view_functions.get("admin_items")
    if callable(_orig_admin_items_admin_clinic_sync) and not getattr(_orig_admin_items_admin_clinic_sync, "_admin_clinic_sync_wrapped", False):
        def _admin_items_with_scheduling_clinic_sync(*args, **kwargs):
            is_clinic_post = False
            try:
                is_clinic_post = request.method == "POST" and (request.form.get("kind") or "").strip().lower() == "clinic"
            except Exception:
                is_clinic_post = False
            result = _orig_admin_items_admin_clinic_sync(*args, **kwargs)
            if is_clinic_post:
                try:
                    _scheduling_sync_active_admin_clinics_to_resources(actor=(session.get("username") or "SYSTEM"))
                except Exception as exc:
                    try:
                        _log_noncritical_exception("Admin Items clinic post scheduling sync skipped", exc)
                    except Exception:
                        pass
            return result

        _admin_items_with_scheduling_clinic_sync._admin_clinic_sync_wrapped = True
        app.view_functions["admin_items"] = _admin_items_with_scheduling_clinic_sync
except Exception as _admin_items_clinic_sched_wrap_exc:
    try:
        _log_noncritical_exception("Admin Items clinic sync wrapper failed", _admin_items_clinic_sched_wrap_exc)
    except Exception:
        pass


try:
    _orig_admin_items_import_admin_clinic_sync = app.view_functions.get("admin_items_import")
    if callable(_orig_admin_items_import_admin_clinic_sync) and not getattr(_orig_admin_items_import_admin_clinic_sync, "_admin_clinic_sync_wrapped", False):
        def _admin_items_import_with_scheduling_clinic_sync(*args, **kwargs):
            is_clinic_import = False
            try:
                is_clinic_import = (request.form.get("kind") or "").strip().lower() == "clinic"
            except Exception:
                is_clinic_import = False
            result = _orig_admin_items_import_admin_clinic_sync(*args, **kwargs)
            if is_clinic_import:
                try:
                    _scheduling_sync_active_admin_clinics_to_resources(actor=(session.get("username") or "SYSTEM"))
                except Exception as exc:
                    try:
                        _log_noncritical_exception("Admin Items clinic import scheduling sync skipped", exc)
                    except Exception:
                        pass
            return result

        _admin_items_import_with_scheduling_clinic_sync._admin_clinic_sync_wrapped = True
        app.view_functions["admin_items_import"] = _admin_items_import_with_scheduling_clinic_sync
except Exception as _admin_items_import_clinic_sched_wrap_exc:
    try:
        _log_noncritical_exception("Admin Items import clinic sync wrapper failed", _admin_items_import_clinic_sched_wrap_exc)
    except Exception:
        pass

try:
    app.logger.info("ADMIN_CLINICS_TO_SCHEDULING_SYNC_20260507 loaded")
except Exception:
    pass



