            _replace = '<textarea class="form-control mb-2" id="radiology_text" name="radiology_orders" rows="2"\n                  placeholder="Selected radiology appear here..." readonly></textarea>\n\n        <div class="row g-2 mb-3" id="rad_reason_section">\n          <div class="col-md-6">\n            <label class="form-label fw-bold small mb-1" for="reason_for_exam">Reason for Exam / Clinical Indication</label>\n            <select class="form-select form-select-sm" id="reason_for_exam" name="reason_for_exam" disabled>\n              <option value="">Select reason...</option>\n              <option value="Trauma">Trauma</option>\n              <option value="Infection">Infection</option>\n              <option value="Pain">Pain</option>\n              <option value="Follow-up">Follow-up</option>\n              <option value="Pre-operative">Pre-operative</option>\n              <option value="Other">Other</option>\n            </select>\n            <div class="form-text small">Optional. Can be completed later on the same order.</div>\n          </div>\n          <div class="col-md-6 d-none" id="reason_for_exam_other_wrap">\n            <label class="form-label fw-bold small mb-1" for="reason_for_exam_other">Other reason</label>\n            <input type="text" class="form-control form-control-sm" id="reason_for_exam_other" name="reason_for_exam_other"\n                   maxlength="120" placeholder="Short clinical indication" disabled>\n          </div>\n        </div>'
