# ============================================================
# FINAL_FIX_20260518_CODE_ORANGE_OFFICIAL_MRN_AND_ORDER_SOURCE_PROPAGATION
# - Code Orange auto-ED registration gets the same official D-prefix MRN as normal registration.
# - Existing Code Orange ED links with blank MRN are repaired safely.
# - Lab/Radiology/Previous Clinical Orders show source location + ordered by clearly.
# ============================================================
def _co_backfill_official_mrn_for_ed_visit(cur, co_patient_id, ed_visit_id, actor="Code Orange"):
    """Fill blank MRN for a Code Orange-linked ED visit using the official patient-id MRN generator."""
    co_patient_id = str(co_patient_id or "").strip()
    ed_visit_id = str(ed_visit_id or "").strip()
    if not ed_visit_id:
        return ""
    try:
        row = cur.execute(
            """
            SELECT v.patient_id, p.mrn
            FROM visits v
            JOIN patients p ON p.id = v.patient_id
            WHERE v.visit_id=?
            LIMIT 1
            """,
            (ed_visit_id,),
        ).fetchone()
    except Exception:
        row = None
    if not row:
        return ""
    patient_id = _co_row_get(row, "patient_id", "")
    current_mrn = str(_co_row_get(row, "mrn", "") or "").strip()
    official_mrn = current_mrn
    if not official_mrn:
        try:
            official_mrn = ensure_patient_has_mrn(patient_id)
        except Exception as exc:
            _log_noncritical_exception(f"Official MRN backfill failed for Code Orange visit={ed_visit_id}", exc)
            official_mrn = ""
    if official_mrn and co_patient_id:
        try:
            cur.execute(
                "UPDATE code_orange_patients SET patient_mrn=?, updated_at=?, updated_by=? WHERE id=? AND COALESCE(TRIM(patient_mrn),'')=''",
                (official_mrn, _co_now_text(), actor or "Code Orange", co_patient_id),
            )
        except Exception as exc:
            _log_noncritical_exception("Code Orange patient_mrn sync failed", exc)
    return official_mrn or ""


def _co_backfill_code_orange_official_mrns(limit=500):
    """Repair old Code Orange victims already linked to ED Board but missing official MRN.

    Schema-safe implementation: some deployed databases were created before
    code_orange_patients.ed_visit_id existed. We inspect columns before building
    the join so startup and polling never spam no-such-column warnings.
    """
    db = None
    try:
        db = get_db()
        cur = db.cursor()
        try:
            cols = _co_table_cols_20260519x(cur, "code_orange_patients") if "_co_table_cols_20260519x" in globals() else set()
        except Exception:
            cols = set()
        if not cols:
            try:
                if DB_ENGINE == "postgres":
                    cur.execute("SELECT column_name FROM information_schema.columns WHERE table_name='code_orange_patients'")
                    cols = {str(r[0] if not hasattr(r, 'keys') else r['column_name']).strip() for r in cur.fetchall()}
                else:
                    cols = {str(r[1]).strip() for r in cur.execute("PRAGMA table_info(code_orange_patients)").fetchall()}
            except Exception:
                cols = set()
        if "ed_visit_id" not in cols:
            # Old schema with no linkage column. Nothing to repair, and this is
            # not an operational error.
            return True
        patient_mrn_expr = "COALESCE(TRIM(cop.patient_mrn),'') = ''" if "patient_mrn" in cols else "1=1"
        rows = cur.execute(
            f"""
            SELECT cop.id AS co_patient_id, cop.ed_visit_id, v.patient_id, p.mrn
            FROM code_orange_patients cop
            JOIN visits v ON v.visit_id = cop.ed_visit_id
            JOIN patients p ON p.id = v.patient_id
            WHERE COALESCE(TRIM(cop.ed_visit_id),'') <> ''
              AND (COALESCE(TRIM(p.mrn),'') = '' OR {patient_mrn_expr})
            ORDER BY cop.id ASC
            LIMIT ?
            """,
            (int(limit or 500),),
        ).fetchall()
        changed = False
        for row in rows or []:
            co_id = _co_row_get(row, "co_patient_id", "")
            ed_visit_id = _co_row_get(row, "ed_visit_id", "")
            mrn = _co_backfill_official_mrn_for_ed_visit(cur, co_id, ed_visit_id, "SYSTEM")
            if mrn:
                changed = True
        if changed:
            db.commit()
        return True
    except Exception as exc:
        try:
            if db is not None:
                db.rollback()
        except Exception:
            pass
        _log_noncritical_exception("Code Orange official MRN bulk repair failed", exc)
        return False


try:
    _orig_ensure_code_orange_schema_official_mrn_20260518 = ensure_code_orange_schema

    def ensure_code_orange_schema():
        result = _orig_ensure_code_orange_schema_official_mrn_20260518()
        try:
            _co_backfill_code_orange_official_mrns(limit=500)
        except Exception as exc:
            _log_noncritical_exception("Code Orange official MRN post-schema repair failed", exc)
        return result
except Exception as _co_schema_wrap_exc:
    try:
        _log_noncritical_exception("Code Orange official MRN schema wrapper failed", _co_schema_wrap_exc)
    except Exception:
        pass


