# FINAL_FIX_20260518_ORDER_SOURCE_PDF_AND_FULL_MOVEMENT_TIMELINE
# - Visit location schema now always includes care_area, so Update Status persists ICU/IP/OR/DR/NICU correctly.
# - Stale ED hidden fields no longer produce mixed strings such as "ED - ICU BED 2".
# - Clinical Order PDF prints Ordered at/by, Order Source, and current patient location.
# - Code Orange ED creation and Location/Bed updates are represented in the movement timeline.
# - Lab/Radiology board row enrichment normalizes and displays the true order source + ordered by.
try:
    _orig_format_order_source_text_20260518_pdfcourse = _format_order_source_text
except Exception:
    _orig_format_order_source_text_20260518_pdfcourse = None

def _format_order_source_text(area, location, bed):
    """Human-readable location text with duplicate-safe Bed handling."""
    parts = []
    seen = set()
    def _add(x):
        x = str(x or "").strip()
        if not x:
            return
        key = re.sub(r"\s+", " ", x).strip().upper()
        if not key or key in seen:
            return
        seen.add(key)
        parts.append(x)
    _add(area)
    _add(location)
    b = str(bed or "").strip()
    if b:
        if re.search(r"\b(BED|ROOM|THEATRE|THEATER|INCUBATOR|BAY)\b", b, re.I):
            _add(b)
        else:
            _add("Bed " + b)
    return " - ".join(parts)

def _co_source_display(area, location, bed):
    """Compact board display for order source/current location."""
    parts = []
    seen = set()
    for x in (area, location, bed):
        x = str(x or "").strip()
        if not x:
            continue
        key = re.sub(r"\s+", " ", x).strip().upper()
        if key and key not in seen:
            seen.add(key)
            parts.append(x)
    return " - ".join(parts) if parts else "ED"

def _finalfix_source_clean(value, max_len=120):
    try:
        value = clean_text(str(value or "").strip())
    except Exception:
        value = str(value or "").strip()
    if max_len and len(value) > max_len:
        value = value[:max_len].rstrip()
    return value

def _finalfix_infer_area_from_location_text(*values):
    text = " ".join(str(v or "") for v in values).upper()
    text = re.sub(r"[_/]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    if not text:
        return ""
    checks = [
        (r"\bNICU\b|NEONATAL", "NICU"),
        (r"\bICU\b|INTENSIVE CARE", "ICU"),
        (r"\bCATH\s*LAB\b|\bCATHLAB\b", "CATH LAB"),
        (r"\bRECOVERY\b|\bPACU\b", "RECOVERY"),
        (r"\bISOLATION\b|\bISO\b", "ISOLATION"),
        (r"\bDELIVERY\s*ROOM\b|\bDR\b", "DR"),
        (r"\bOR\b|\bOR\s*[- ]?\d+\b|OPERATING", "OR"),
        (r"\bIP\b|\bWARD\b|INPATIENT", "IP"),
        (r"\bED\b|EMERGENCY|RESUS|WR\b", "ED"),
    ]
    for pat, area in checks:
        try:
            if re.search(pat, text, re.I):
                return area
        except Exception:
            continue
    return ""

try:
    _orig_ensure_patient_location_movement_schema_20260518_pdfcourse = _ensure_patient_location_movement_schema
    def _ensure_patient_location_movement_schema(cur):
        result = _orig_ensure_patient_location_movement_schema_20260518_pdfcourse(cur)
        try:
            if (DB_ENGINE or "").lower() == "postgres":
                for col, typ in (
                    ("care_area", "TEXT"),
                    ("location", "TEXT"),
                    ("bed_no", "TEXT"),
                    ("bed_status", "TEXT"),
                    ("movement_note", "TEXT"),
                    ("location_updated_at", "TEXT"),
                    ("location_updated_by", "TEXT"),
                ):
                    cur.execute(f"ALTER TABLE visits ADD COLUMN IF NOT EXISTS {col} {typ}")
            else:
                try:
                    existing = {str(r[1]).lower() for r in cur.execute("PRAGMA table_info(visits)").fetchall()}
                except Exception:
                    existing = set()
                for col, typ in (
                    ("care_area", "TEXT"),
                    ("location", "TEXT"),
                    ("bed_no", "TEXT"),
                    ("bed_status", "TEXT"),
                    ("movement_note", "TEXT"),
                    ("location_updated_at", "TEXT"),
                    ("location_updated_by", "TEXT"),
                ):
                    if col.lower() not in existing:
                        try:
                            cur.execute(f"ALTER TABLE visits ADD COLUMN {col} {typ}")
                        except Exception as exc:
                            msg = str(exc or "").lower()
                            if "duplicate column" not in msg and "already exists" not in msg:
                                raise
        except Exception as exc:
            _log_noncritical_exception("Final location schema column ensure failed", exc)
        return result
    globals()["_ensure_patient_location_movement_schema"] = _ensure_patient_location_movement_schema
except Exception as exc:
    try:
        _log_noncritical_exception("Final location schema wrapper failed", exc)
    except Exception:
        pass

def _finalfix_fetch_visit_location(cur, visit_id):
    try:
        _ensure_patient_location_movement_schema(cur)
    except Exception:
        pass
    row = None
    try:
        row = cur.execute(
            """
            SELECT visit_id,
                   COALESCE(care_area,'') AS care_area,
                   COALESCE(location,'') AS location,
                   COALESCE(bed_no,'') AS bed_no,
                   COALESCE(bed_status,'') AS bed_status,
                   COALESCE(clinic,'ED') AS clinic
            FROM visits
            WHERE visit_id=?
            LIMIT 1
            """,
            (visit_id,),
        ).fetchone()
    except Exception:
        row = None
    def _g(row, key, default=""):
        return _co_row_get(row, key, default) if row is not None else default
    area = _finalfix_source_clean(_g(row, "care_area", ""), 40)
    location = _finalfix_source_clean(_g(row, "location", ""), 120)
    bed = _finalfix_source_clean(_g(row, "bed_no", ""), 80)
    clinic = _finalfix_source_clean(_g(row, "clinic", "ED"), 40) or "ED"
    inferred = _finalfix_infer_area_from_location_text(location, bed)
    if not area:
        area = inferred or clinic or "ED"
    return {"care_area": _normalize_care_area(area, "ED"), "location": location, "bed_no": bed, "bed_status": _finalfix_source_clean(_g(row, "bed_status", ""), 40), "clinic": clinic}

def _finalfix_latest_movement(cur, visit_id, at_text=None, allow_latest_without_time=True):
    try:
        _ensure_patient_location_movement_schema(cur)
    except Exception:
        pass
    row = None
    at_text = str(at_text or "").strip()
    if at_text:
        try:
            row = cur.execute(
                """
                SELECT * FROM patient_location_movements
                WHERE visit_id=? AND COALESCE(moved_at,'') <= ?
                ORDER BY COALESCE(moved_at,'') DESC, id DESC
                LIMIT 1
                """,
                (visit_id, at_text),
            ).fetchone()
        except Exception:
            row = None
    if row is None and allow_latest_without_time:
        try:
            row = cur.execute(
                """
                SELECT * FROM patient_location_movements
                WHERE visit_id=?
                ORDER BY COALESCE(moved_at,'') DESC, id DESC
                LIMIT 1
                """,
                (visit_id,),
            ).fetchone()
        except Exception:
            row = None
    if row is None:
        return {}
    return {
        "care_area": _normalize_care_area(_co_row_get(row, "to_area", ""), ""),
        "location": _finalfix_source_clean(_co_row_get(row, "to_location", ""), 120),
        "bed_no": _finalfix_source_clean(_co_row_get(row, "to_bed", ""), 80),
        "moved_at": _finalfix_source_clean(_co_row_get(row, "moved_at", ""), 40),
        "moved_by": _finalfix_source_clean(_co_row_get(row, "moved_by", ""), 80),
    }

def _finalfix_normalize_order_source(cur, visit_id, area="", location="", bed="", created_at="", allow_current_fallback=True):
    area_raw = _finalfix_source_clean(area, 40)
    location_raw = _finalfix_source_clean(location, 120)
    bed_raw = _finalfix_source_clean(bed, 80)
    inferred = _finalfix_infer_area_from_location_text(location_raw, bed_raw)
    visit_loc = _finalfix_fetch_visit_location(cur, visit_id) if visit_id else {"care_area":"ED","location":"","bed_no":""}
    mv = _finalfix_latest_movement(cur, visit_id, created_at, allow_latest_without_time=allow_current_fallback) if visit_id else {}
    area_norm = _normalize_care_area(area_raw, "") if area_raw else ""
    if (not area_norm) or area_norm == "ED":
        if inferred and inferred != "ED":
            area_norm = inferred
        elif mv.get("care_area") and mv.get("care_area") != "ED":
            area_norm = mv.get("care_area")
        elif allow_current_fallback and visit_loc.get("care_area"):
            area_norm = visit_loc.get("care_area")
        else:
            area_norm = area_norm or visit_loc.get("care_area") or "ED"
    if not location_raw:
        location_raw = mv.get("location") or visit_loc.get("location") or ""
    if not bed_raw:
        bed_raw = mv.get("bed_no") or visit_loc.get("bed_no") or ""
    if area_norm == "ED":
        inferred2 = _finalfix_infer_area_from_location_text(location_raw, bed_raw)
        if inferred2 and inferred2 != "ED":
            area_norm = inferred2
    return _normalize_care_area(area_norm, "ED"), location_raw, bed_raw

def _finalfix_maybe_insert_initial_movement(cur, visit_id, actor="Code Orange", note=""):
    visit_id = str(visit_id or "").strip()
    if not visit_id:
        return False
    try:
        _ensure_patient_location_movement_schema(cur)
        exists = cur.execute("SELECT id FROM patient_location_movements WHERE visit_id=? LIMIT 1", (visit_id,)).fetchone()
        if exists:
            return False
        v = _finalfix_fetch_visit_location(cur, visit_id)
        now_txt = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        try:
            row = cur.execute("SELECT COALESCE(created_at,'') AS created_at, COALESCE(created_by,'') AS created_by, COALESCE(status,'REGISTERED') AS status FROM visits WHERE visit_id=?", (visit_id,)).fetchone()
            now_txt = _co_row_get(row, "created_at", "") or now_txt
            actor = _co_row_get(row, "created_by", "") or actor or "SYSTEM"
            status = _co_row_get(row, "status", "") or "REGISTERED"
        except Exception:
            status = "REGISTERED"
        _insert_patient_location_movement(
            cur,
            visit_id,
            {"care_area":"", "location":"", "bed_no":""},
            {"care_area": v.get("care_area") or "ED", "location": v.get("location") or "", "bed_no": v.get("bed_no") or ""},
            status,
            note or "Initial ED registration / Code Orange link",
            now_txt,
            actor or "SYSTEM",
        )
        return True
    except Exception as exc:
        _log_noncritical_exception(f"Initial movement insert failed visit={visit_id}", exc)
        return False

def _repair_order_source_snapshots_for_visit(visit_id):
    """Repair inconsistent stored order source snapshots for one visit.

    Only changes rows whose source is blank/ED but whose location/bed or movement
    timeline proves a later ICU/IP/OR/DR/NICU source. It never rewrites rows that
    already carry a non-ED source.
    """
    try:
        db = get_db()
        cur = db.cursor()
        _ensure_patient_location_movement_schema(cur)
        try:
            _ensure_order_reason_schema_columns(strict=False)
        except Exception:
            pass
        changed = False
        table_specs = [
            ("clinical_orders", "id", "created_at"),
            ("lab_requests", "id", "requested_at"),
            ("radiology_requests", "id", "requested_at"),
        ]
        for table, id_col, ts_col in table_specs:
            try:
                rows = cur.execute(
                    f"""
                    SELECT {id_col} AS rid, COALESCE({ts_col},'') AS event_at,
                           COALESCE(order_source_area,'') AS order_source_area,
                           COALESCE(order_source_location,'') AS order_source_location,
                           COALESCE(order_source_bed,'') AS order_source_bed
                    FROM {table}
                    WHERE visit_id=?
                    ORDER BY {id_col} ASC
                    """,
                    (visit_id,),
                ).fetchall()
            except Exception:
                continue
            for row in rows or []:
                old_area = _finalfix_source_clean(_co_row_get(row, "order_source_area", ""), 40)
                old_loc = _finalfix_source_clean(_co_row_get(row, "order_source_location", ""), 120)
                old_bed = _finalfix_source_clean(_co_row_get(row, "order_source_bed", ""), 80)
                event_at = _co_row_get(row, "event_at", "") or ""
                area_old_norm = _normalize_care_area(old_area, "") if old_area else ""
                if area_old_norm and area_old_norm != "ED":
                    continue
                inferred = _finalfix_infer_area_from_location_text(old_loc, old_bed)
                mv = _finalfix_latest_movement(cur, visit_id, event_at, allow_latest_without_time=False)
                if not (inferred and inferred != "ED") and not (mv.get("care_area") and mv.get("care_area") != "ED"):
                    continue
                new_area, new_loc, new_bed = _finalfix_normalize_order_source(cur, visit_id, old_area, old_loc, old_bed, event_at, allow_current_fallback=False)
                if (new_area, new_loc, new_bed) != (old_area or "", old_loc or "", old_bed or "") and new_area:
                    try:
                        cur.execute(
                            f"UPDATE {table} SET order_source_area=?, order_source_location=?, order_source_bed=? WHERE {id_col}=? AND visit_id=?",
                            (new_area, new_loc, new_bed, _co_row_get(row, "rid"), visit_id),
                        )
                        changed = True
                    except Exception as exc:
                        _log_noncritical_exception(f"Order source repair failed for {table} visit={visit_id}", exc)
        if changed:
            db.commit()
        return changed
    except Exception as exc:
        try:
            get_db().rollback()
        except Exception:
            pass
        _log_noncritical_exception(f"Order source snapshot repair failed visit={visit_id}", exc)
        return False

