def _final20260518_enrich_board_rows_with_source(rows):
    try:
        rows = rows or []
        visit_ids = sorted({str((r or {}).get("visit_id") or "").strip() for r in rows if isinstance(r, dict) and str((r or {}).get("visit_id") or "").strip()})
        cur = get_db().cursor()
        visit_map = {}
        if visit_ids:
            try:
                _ensure_patient_location_movement_schema(cur)
            except Exception:
                pass
            placeholders = ",".join(["?"] * len(visit_ids))
            try:
                for vr in cur.execute(
                    f"SELECT visit_id, COALESCE(care_area,'') AS care_area, COALESCE(location,'') AS location, COALESCE(bed_no,'') AS bed_no, COALESCE(bed_status,'') AS bed_status, COALESCE(clinic,'ED') AS clinic FROM visits WHERE visit_id IN ({placeholders})",
                    visit_ids,
                ).fetchall() or []:
                    d = dict(vr) if hasattr(vr, "keys") else {}
                    visit_map[str(d.get("visit_id") or "")] = d
            except Exception:
                visit_map = {}
        full_by_code, code_by_label = _clinic_display_maps()
        repaired_visits = set()
        for r in rows:
            if not isinstance(r, dict):
                continue
            vid = str(r.get("visit_id") or "").strip()
            if vid and vid not in repaired_visits:
                try:
                    _repair_order_source_snapshots_for_visit(vid)
                except Exception:
                    pass
                repaired_visits.add(vid)
            v = visit_map.get(vid, {})
            current_area = _normalize_care_area((r.get("care_area") or v.get("care_area") or r.get("clinic") or v.get("clinic") or "ED"), "ED")
            current_location = r.get("current_location") or v.get("location") or ""
            current_bed = r.get("current_bed_no") or v.get("bed_no") or ""
            current_area = _finalfix_infer_area_from_location_text(current_location, current_bed) or current_area
            r["current_location_text"] = _co_source_display(current_area, current_location, current_bed)
            event_at = r.get("requested_at") or r.get("created_at") or ""
            src_area, src_loc, src_bed = _finalfix_normalize_order_source(
                cur,
                vid,
                r.get("order_source_area") or "",
                r.get("order_source_location") or "",
                r.get("order_source_bed") or "",
                event_at,
                allow_current_fallback=True,
            )
            r["order_source_area"] = src_area
            r["order_source_location"] = src_loc
            r["order_source_bed"] = src_bed
            r["order_source_text"] = _co_source_display(src_area, src_loc, src_bed)
            r["ordered_by_display"] = r.get("requested_by") or r.get("created_by") or ""
            clinic_raw = str(current_area or r.get("clinic") or "ED").strip()
            clinic_key = clinic_raw.upper()
            clinic_code = clinic_key if clinic_key in full_by_code else code_by_label.get(clinic_key, clinic_key or "ED")
            r["clinic_short"] = clinic_code or clinic_raw or "ED"
            r["clinic_display"] = full_by_code.get(clinic_code, clinic_raw or "ED")
    except Exception as exc:
        _log_noncritical_exception("Final board source/location enrichment v3 failed", exc)
    return rows

def _clinical_order_pdf_v2(visit_id, oid):
    cache_key = ("clinical_order_pdf_v2", str(visit_id or "").strip(), int(oid or 0))
    cache_ttl = _pdf_cache_ttl_seconds()
    try:
        if cache_ttl > 0:
            cached = _PDF_RENDER_CACHE.get(cache_key)
            if cached:
                return Response(cached, mimetype="application/pdf", headers=_patient_pdf_headers({"visit_id": visit_id}, f"ClinicalOrder-{oid}", visit_id=visit_id))
    except Exception:
        pass
    db = get_db()
    cur = db.cursor()
    try:
        _repair_order_source_snapshots_for_visit(visit_id)
    except Exception:
        pass
    visit = cur.execute(
        """
        SELECT v.*, p.name, p.id_number, p.insurance, p.insurance_no, p.mrn, p.cerner_mrn
        FROM visits v JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
        """,
        (visit_id,),
    ).fetchone()
    order = cur.execute("SELECT * FROM clinical_orders WHERE id=? AND visit_id=?", (oid, visit_id)).fetchone()
    if not order or not visit:
        return "Not found", 404
    id_image_path = get_visit_id_photo_path(cur, visit_id)
    try:
        doctor_name = _resolve_doctor_name_for_visit(cur, visit, visit_id)
    except Exception:
        doctor_name = ""
    doctor_display = _doctor_display_with_gd(cur, doctor_name)
    u_font = _get_pdf_unicode_font_name()
    text_font = u_font or "Helvetica"
    bold_font = u_font or "Helvetica-Bold"
    italic_font = u_font or "Helvetica-Oblique"
    buffer = io.BytesIO()
    c = _pdf_attach_patient_mrn_stamp(canvas.Canvas(buffer, pagesize=A4), visit_row=visit, visit_id=visit_id, cur=cur)
    width, height = A4
    y = height - 2 * cm
    if id_image_path:
        try:
            img_w = 4 * cm; img_h = 3 * cm
            c.drawImage(id_image_path, width - img_w - 2 * cm, 3 * cm, width=img_w, height=img_h, preserveAspectRatio=True, mask="auto")
        except Exception:
            pass
    c.setFont(bold_font, 16)
    _pdf_safe_drawString(c, 2 * cm, y, "Clinical Order", max_chars=160)
    y -= 1 * cm
    c.setFont(text_font, 11)
    _pdf_safe_drawString(c, 2 * cm, y, f"Case No: {visit_id}   Order#: {oid}", max_chars=160)
    y -= 0.7 * cm
    _pdf_safe_drawString(c, 2 * cm, y, f"Patient: {_pdf_row_get(visit,'name','-')}   ID: {_pdf_row_get(visit,'id_number','-')}", max_chars=160)
    y -= 0.7 * cm
    try:
        ordered_at_raw = _pdf_row_get(order, "created_at", "") or ""
        ordered_at = format_dt_local(ordered_at_raw) or ordered_at_raw or "-"
    except Exception:
        ordered_at = _pdf_row_get(order, "created_at", "-") or "-"
    try:
        created_by_raw = _pdf_row_get(order, "created_by", "") or "-"
        ordered_by = _staff_display_with_ids(cur, created_by_raw)
    except Exception:
        ordered_by = _pdf_row_get(order, "created_by", "-") or "-"
    src_area, src_loc, src_bed = _finalfix_normalize_order_source(
        cur,
        visit_id,
        _pdf_row_get(order, "order_source_area", ""),
        _pdf_row_get(order, "order_source_location", ""),
        _pdf_row_get(order, "order_source_bed", ""),
        _pdf_row_get(order, "created_at", ""),
        allow_current_fallback=True,
    )
    order_source_txt = _co_source_display(src_area, src_loc, src_bed)
    current_visit = _finalfix_fetch_visit_location(cur, visit_id)
    patient_current_txt = _co_source_display(current_visit.get("care_area"), current_visit.get("location"), current_visit.get("bed_no"))
    c.setFont(italic_font, 9)
    _pdf_safe_drawString(c, 2 * cm, y, f"Ordered: {ordered_at}  |  by {ordered_by}", max_chars=140)
    y -= 0.48 * cm
    c.setFont(text_font, 9)
    _pdf_safe_drawString(c, 2 * cm, y, f"Order Source: {order_source_txt or '-'}", max_chars=140)
    y -= 0.48 * cm
    _pdf_safe_drawString(c, 2 * cm, y, f"Patient Current Location: {patient_current_txt or '-'}", max_chars=140)
    y -= 1.1 * cm

    def section(title, text):
        nonlocal y
        c.setFont(bold_font, 12)
        _pdf_safe_drawString(c, 2 * cm, y, title, max_chars=160)
        y -= 0.6 * cm
        c.setFont(text_font, 10)
        for line in (text or "-").splitlines():
            _pdf_safe_drawString(c, 2.2 * cm, y, line, max_chars=110)
            y -= 0.45 * cm
            if y < 2 * cm:
                c.showPage(); y = height - 2 * cm; c.setFont(text_font, 10)
        y -= 0.3 * cm

    section("Diagnosis / Chief Complaint:", _pdf_row_get(order, "diagnosis", ""))
    section("Radiology orders:", _pdf_row_get(order, "radiology_orders", ""))
    _pdf_reason_for_exam = _pdf_row_get(order, "reason_for_exam", "") or ""
    if _pdf_reason_for_exam:
        section("Reason for Exam / Clinical Indication:", _pdf_reason_for_exam)
    section("Lab orders:", _pdf_row_get(order, "lab_orders", ""))
    _pdf_reason_for_order = _pdf_row_get(order, "reason_for_order", "") or ""
    if _pdf_reason_for_order:
        section("Reason for Lab Order / Clinical Indication:", _pdf_reason_for_order)
    section("Medications:", _pdf_row_get(order, "medications", ""))
    _pdf_med_indication = _pdf_row_get(order, "med_indication", "") or ""
    if _pdf_med_indication:
        section("Indication / Reason for Medication:", _pdf_med_indication)
    sig_y = max(2.0 * cm, y - 1.5 * cm)
    c.setFont(text_font, 9)
    _pdf_safe_drawString(c, 2 * cm, sig_y, f"Physician: {doctor_display}", max_chars=90)
    _pdf_safe_drawString(c, width / 2, sig_y, "Signature: ______________________", max_chars=60)
    c.setFont(italic_font, 8)
    _pdf_safe_drawString(c, 2 * cm, 1.2 * cm, APP_FOOTER_TEXT, max_chars=180)
    c.showPage()
    try:
        v_add = _mrd_fetch_visit_for_addendum(cur, visit_id) or visit
        printed_at2, reg_dt2, triage_dt2, discharge_dt2, age2 = _mrd_addendum_context_from_visit(v_add)
        _mrd_draw_addendum_pages(c, cur=cur, visit=v_add, visit_id=visit_id, age=age2, printed_at=printed_at2, reg_dt=reg_dt2, triage_dt=triage_dt2, discharge_dt=discharge_dt2, report_label=f"Clinical Order #{oid}", include_labs=True, include_rads=True, include_meds=True, include_discharge_snapshot=True, page_break_after=False)
    except Exception as exc:
        _log_noncritical_exception(f"Clinical order PDF timeline appendix failed for visit={visit_id}", exc)
    c.save(); buffer.seek(0)
    pdf_bytes = buffer.getvalue()
    try:
        if cache_ttl > 0:
            _PDF_RENDER_CACHE.set(cache_key, pdf_bytes, cache_ttl)
    except Exception:
        pass
    return Response(pdf_bytes, mimetype="application/pdf", headers=_patient_pdf_headers(visit, f"ClinicalOrder-{oid}", visit_id=visit_id))

