# ============================================================
# FINAL_FIX_20260518_ORDER_SOURCE_PDF_AND_MOVEMENT_TIMELINE
# - Clinical Order PDF prints Ordered date/by + Order Source + current patient location.
# - Mixed source text such as "ED - ICU BED 2" is corrected to the real current area
#   when the order/request was created after the patient movement.
# - Auto ED Course Movement section always includes initial/current location and all movements.
# ============================================================

def _final20260518_norm_text(value, max_len=160):
    try:
        s = clean_text(str(value or '').strip())
    except Exception:
        s = str(value or '').strip()
    return s[:max_len].rstrip() if max_len else s


def _final20260518_infer_area_from_text(*values):
    try:
        txt = ' '.join(str(v or '') for v in values if str(v or '').strip()).upper()
    except Exception:
        txt = ''
    if not txt:
        return ''
    # Match the more specific labels first.
    checks = (
        ('CATH LAB', ('CATH LAB', 'CATHLAB', 'CATH ')),
        ('NICU', ('NICU', 'N.I.C.U')),
        ('ICU', ('ICU', 'I.C.U')),
        ('RECOVERY', ('RECOVERY', 'PACU')),
        ('ISOLATION', ('ISOLATION', 'ISOL')),
        ('DR', ('DELIVERY ROOM', 'DELIVERY', ' DR ', 'DR-', 'DR/', 'DR.')),
        ('OR', ('OPERATING ROOM', 'THEATRE', ' OR ', 'OR-', 'OR/', 'OR.')),
        ('IP', ('WARD', ' IP ', 'IP-', 'IP/', 'INPATIENT', 'IPD')),
        ('ED', (' ED ', 'ER ', 'EMERGENCY', 'RESUS', 'TRIAGE')),
    )
    padded = ' ' + txt + ' '
    for area, tokens in checks:
        for token in tokens:
            if token in padded or token in txt:
                return area
    return ''


def _final20260518_visit_location(cur, visit_id):
    try:
        row = cur.execute(
            """
            SELECT COALESCE(care_area,'') AS care_area,
                   COALESCE(location,'') AS location,
                   COALESCE(bed_no,'') AS bed_no,
                   COALESCE(bed_status,'') AS bed_status,
                   COALESCE(location_updated_at,'') AS location_updated_at,
                   COALESCE(location_updated_by,'') AS location_updated_by,
                   COALESCE(created_at,'') AS created_at,
                   COALESCE(created_by,'') AS created_by,
                   COALESCE(clinic,'ED') AS clinic,
                   COALESCE(status,'') AS status
            FROM visits
            WHERE visit_id=?
            """,
            (visit_id,),
        ).fetchone()
    except Exception:
        row = None
    if not row:
        return {}
    area = _final20260518_norm_text(_co_row_get(row, 'care_area', ''), 40)
    clinic = _final20260518_norm_text(_co_row_get(row, 'clinic', 'ED'), 40) or 'ED'
    loc = _final20260518_norm_text(_co_row_get(row, 'location', ''), 120)
    bed = _final20260518_norm_text(_co_row_get(row, 'bed_no', ''), 80)
    inferred = _final20260518_infer_area_from_text(area, loc, bed)
    if (not area or area.upper() == 'ED') and inferred and inferred != 'ED':
        area = inferred
    if not area:
        area = clinic or 'ED'
    return {
        'care_area': area,
        'location': loc,
        'bed_no': bed,
        'bed_status': _final20260518_norm_text(_co_row_get(row, 'bed_status', ''), 40),
        'location_updated_at': _final20260518_norm_text(_co_row_get(row, 'location_updated_at', ''), 40),
        'location_updated_by': _final20260518_norm_text(_co_row_get(row, 'location_updated_by', ''), 80),
        'created_at': _final20260518_norm_text(_co_row_get(row, 'created_at', ''), 40),
        'created_by': _final20260518_norm_text(_co_row_get(row, 'created_by', ''), 80),
        'clinic': clinic,
        'status': _final20260518_norm_text(_co_row_get(row, 'status', ''), 40),
    }


def _final20260518_ts_ge(ts, cutoff):
    ts = str(ts or '').strip()
    cutoff = str(cutoff or '').strip()
    if not ts or not cutoff:
        return False
    # App timestamps are ISO-like (YYYY-MM-DD HH:MM:SS), so lexical compare is safe.
    return ts[:19] >= cutoff[:19]


def _final20260518_correct_source_tuple(cur, visit_id, area, location, bed, event_ts=''):
    area = _final20260518_norm_text(area, 40)
    location = _final20260518_norm_text(location, 120)
    bed = _final20260518_norm_text(bed, 80)
    v = _final20260518_visit_location(cur, visit_id)
    current_area = _final20260518_norm_text(v.get('care_area') or v.get('clinic') or 'ED', 40)
    current_location = _final20260518_norm_text(v.get('location') or '', 120)
    current_bed = _final20260518_norm_text(v.get('bed_no') or '', 80)
    loc_updated_at = _final20260518_norm_text(v.get('location_updated_at') or '', 40)

    inferred_from_source = _final20260518_infer_area_from_text(area, location, bed)
    if (not area or area.upper() == 'ED') and inferred_from_source and inferred_from_source != 'ED':
        area = inferred_from_source

    # Fix mixed snapshots: e.g. area stayed ED while location/bed came from ICU.
    if current_area and current_area.upper() != 'ED':
        source_matches_current_location = False
        if current_location and location and current_location.strip().lower() == location.strip().lower():
            source_matches_current_location = True
        if current_bed and bed and current_bed.strip().lower() == bed.strip().lower():
            source_matches_current_location = True
        if current_area.upper() in (location or '').upper() or current_area.upper() in (bed or '').upper():
            source_matches_current_location = True
        if _final20260518_ts_ge(event_ts, loc_updated_at):
            source_matches_current_location = True
        if (not area or area.upper() == 'ED') and source_matches_current_location:
            area = current_area
        if source_matches_current_location:
            if not location and current_location:
                location = current_location
            if not bed and current_bed:
                bed = current_bed

    if not area:
        area = current_area or 'ED'
    return area, location, bed


def _final20260518_source_text(cur, visit_id, area, location, bed, event_ts=''):
    a, l, b = _final20260518_correct_source_tuple(cur, visit_id, area, location, bed, event_ts=event_ts)
    return _format_order_source_text(a, l, b) or '-'


def _final20260518_repair_mixed_order_sources_for_visit(visit_id, auto_commit=True):
    """Repair rows created after movement that have stale ED area with ICU/OR/etc location."""
    db = None
    changed = 0
    try:
        db = get_db()
        cur = db.cursor()
        v = _final20260518_visit_location(cur, visit_id)
        current_area = _final20260518_norm_text(v.get('care_area') or v.get('clinic') or 'ED', 40)
        current_location = _final20260518_norm_text(v.get('location') or '', 120)
        current_bed = _final20260518_norm_text(v.get('bed_no') or '', 80)
        if not current_area or current_area.upper() == 'ED':
            return 0
        specs = (
            ('clinical_orders', 'created_at'),
            ('lab_requests', 'requested_at'),
            ('radiology_requests', 'requested_at'),
        )
        for table, ts_col in specs:
            try:
                rows = cur.execute(
                    f"SELECT id, COALESCE({ts_col},'') AS event_ts, COALESCE(order_source_area,'') AS order_source_area, COALESCE(order_source_location,'') AS order_source_location, COALESCE(order_source_bed,'') AS order_source_bed FROM {table} WHERE visit_id=?",
                    (visit_id,),
                ).fetchall() or []
            except Exception:
                continue
            for row in rows:
                rid = _co_row_get(row, 'id', None)
                event_ts = _co_row_get(row, 'event_ts', '')
                old_area = _final20260518_norm_text(_co_row_get(row, 'order_source_area', ''), 40)
                old_loc = _final20260518_norm_text(_co_row_get(row, 'order_source_location', ''), 120)
                old_bed = _final20260518_norm_text(_co_row_get(row, 'order_source_bed', ''), 80)
                new_area, new_loc, new_bed = _final20260518_correct_source_tuple(cur, visit_id, old_area, old_loc, old_bed, event_ts=event_ts)
                if (new_area, new_loc, new_bed) != (old_area, old_loc, old_bed):
                    try:
                        cur.execute(
                            f"UPDATE {table} SET order_source_area=?, order_source_location=?, order_source_bed=? WHERE id=?",
                            (new_area, new_loc, new_bed, rid),
                        )
                        changed += 1
                    except Exception as exc:
                        _log_noncritical_exception(f"Mixed order source repair failed table={table} id={rid}", exc)
        if changed and auto_commit:
            db.commit()
    except Exception as exc:
        try:
            if db is not None:
                db.rollback()
        except Exception:
            pass
        _log_noncritical_exception(f"Mixed order source repair failed visit={visit_id}", exc)
    return changed


# Strengthen the authoritative order-source resolver used by Add/Update Clinical Order.
try:
    _orig_co_order_source_from_form_or_visit_final20260518 = _co_order_source_from_form_or_visit
    def _co_order_source_from_form_or_visit(visit_id):
        area, location, bed = _orig_co_order_source_from_form_or_visit_final20260518(visit_id)
        try:
            return _final20260518_correct_source_tuple(get_db().cursor(), visit_id, area, location, bed, event_ts=datetime.now().strftime('%Y-%m-%d %H:%M:%S'))
        except Exception:
            return area, location, bed
    globals()['_co_order_source_from_form_or_visit'] = _co_order_source_from_form_or_visit
except Exception as _order_source_resolver_wrap_exc:
    try:
        _log_noncritical_exception('Final order source resolver wrapper failed', _order_source_resolver_wrap_exc)
    except Exception:
        pass


# Refresh linked board payload rows and repair/display mixed ED+ICU source snapshots.
def _final20260518_enrich_board_rows_with_source(rows):
    try:
        rows = rows or []
        visit_ids = sorted({str((r or {}).get('visit_id') or '').strip() for r in rows if isinstance(r, dict) and str((r or {}).get('visit_id') or '').strip()})
        visit_map = {}
        cur = get_db().cursor()
        for vid in visit_ids:
            try:
                _final20260518_repair_mixed_order_sources_for_visit(vid, auto_commit=False)
            except Exception:
                pass
        try:
            get_db().commit()
        except Exception:
            pass
        if visit_ids:
            placeholders = ','.join(['?'] * len(visit_ids))
            for vr in cur.execute(
                f"SELECT visit_id, COALESCE(care_area,'') AS care_area, COALESCE(location,'') AS location, COALESCE(bed_no,'') AS bed_no, COALESCE(bed_status,'') AS bed_status, COALESCE(clinic,'ED') AS clinic FROM visits WHERE visit_id IN ({placeholders})",
                visit_ids,
            ).fetchall() or []:
                d = dict(vr) if hasattr(vr, 'keys') else {}
                visit_map[str(d.get('visit_id') or '')] = d
        full_by_code, code_by_label = _clinic_display_maps()
        for r in rows:
            if not isinstance(r, dict):
                continue
            vid = str(r.get('visit_id') or '').strip()
            v = visit_map.get(vid, {})
            current_area = _final20260518_norm_text(r.get('care_area') or v.get('care_area') or r.get('clinic') or v.get('clinic') or 'ED', 40)
            current_location = _final20260518_norm_text(r.get('current_location') or v.get('location') or '', 120)
            current_bed = _final20260518_norm_text(r.get('current_bed_no') or v.get('bed_no') or '', 80)
            current_area, current_location, current_bed = _final20260518_correct_source_tuple(cur, vid, current_area, current_location, current_bed, event_ts='')
            r['current_location_text'] = _format_order_source_text(current_area, current_location, current_bed) or 'ED'
            event_ts = r.get('requested_at') or r.get('created_at') or ''
            source_area, source_location, source_bed = _final20260518_correct_source_tuple(
                cur,
                vid,
                r.get('order_source_area') or '',
                r.get('order_source_location') or '',
                r.get('order_source_bed') or '',
                event_ts=event_ts,
            )
            r['order_source_area'] = source_area
            r['order_source_location'] = source_location
            r['order_source_bed'] = source_bed
            r['order_source_text'] = _format_order_source_text(source_area, source_location, source_bed) or 'ED'
            r['ordered_by_display'] = r.get('requested_by') or r.get('created_by') or ''
            clinic_raw = str(current_area or r.get('clinic') or 'ED').strip()
            clinic_key = clinic_raw.upper()
            clinic_code = clinic_key if clinic_key in full_by_code else code_by_label.get(clinic_key, clinic_key or 'ED')
            r['clinic_short'] = clinic_code or clinic_raw or 'ED'
            r['clinic_display'] = full_by_code.get(clinic_code, clinic_raw or 'ED')
            r['care_area'] = current_area
    except Exception as exc:
        _log_noncritical_exception('Final board source/location enrichment v2 failed', exc)
    return rows

globals()['_final20260518_enrich_board_rows_with_source'] = _final20260518_enrich_board_rows_with_source


# Repair before pages that display previous orders / boards / PDFs.
try:
    _orig_clinical_orders_page_final20260518 = app.view_functions.get('clinical_orders_page')
    if _orig_clinical_orders_page_final20260518 and not globals().get('_final20260518_clinical_orders_page_wrapped'):
        def clinical_orders_page(visit_id):
            try:
                _final20260518_repair_mixed_order_sources_for_visit(visit_id, auto_commit=True)
            except Exception:
                pass
            return _orig_clinical_orders_page_final20260518(visit_id)
        globals()['clinical_orders_page'] = clinical_orders_page
        app.view_functions['clinical_orders_page'] = clinical_orders_page
        globals()['_final20260518_clinical_orders_page_wrapped'] = True
except Exception as _co_page_wrap_exc:
    try:
        _log_noncritical_exception('Clinical orders page source repair wrapper failed', _co_page_wrap_exc)
    except Exception:
        pass


# Clinical Order PDF override: fixes sqlite Row access and prints source/current location.
def _final20260518_clinical_order_pdf(visit_id, oid):
    cache_key = ('clinical_order_pdf_final20260518', str(visit_id or '').strip(), int(oid or 0))
    cache_ttl = _pdf_cache_ttl_seconds()
    try:
        if cache_ttl > 0:
            cached = _PDF_RENDER_CACHE.get(cache_key)
            if cached:
                return Response(cached, mimetype='application/pdf', headers=_patient_pdf_headers({'visit_id': visit_id}, f'ClinicalOrder-{oid}', visit_id=visit_id))
    except Exception:
        pass

    db = get_db()
    cur = db.cursor()
    try:
        _final20260518_repair_mixed_order_sources_for_visit(visit_id, auto_commit=True)
    except Exception:
        pass
    visit = cur.execute(
        """
        SELECT v.*, p.name, p.id_number, p.insurance, p.insurance_no, p.mrn, p.cerner_mrn
        FROM visits v JOIN patients p ON p.id=v.patient_id
        WHERE v.visit_id=?
        """,
        (visit_id,),
    ).fetchone()
    order = cur.execute("SELECT * FROM clinical_orders WHERE id=? AND visit_id=?", (oid, visit_id)).fetchone()
    if not order or not visit:
        return 'Not found', 404

    id_image_path = get_visit_id_photo_path(cur, visit_id)
    try:
        doctor_name = _resolve_doctor_name_for_visit(cur, visit, visit_id)
    except Exception:
        doctor_name = ''
    doctor_display = _doctor_display_with_gd(cur, doctor_name)

    u_font = _get_pdf_unicode_font_name()
    text_font = u_font or 'Helvetica'
    bold_font = u_font or 'Helvetica-Bold'
    italic_font = u_font or 'Helvetica-Oblique'

    buffer = io.BytesIO()
    c = _pdf_attach_patient_mrn_stamp(canvas.Canvas(buffer, pagesize=A4), visit_row=visit, visit_id=visit_id, cur=cur)
    width, height = A4
    y = height - 2 * cm

    if id_image_path:
        try:
            img_w = 4 * cm
            img_h = 3 * cm
            c.drawImage(id_image_path, width - img_w - 2 * cm, 3 * cm, width=img_w, height=img_h, preserveAspectRatio=True, mask='auto')
        except Exception:
            pass

    c.setFont(bold_font, 16)
    _pdf_safe_drawString(c, 2 * cm, y, 'Clinical Order', max_chars=160)
    y -= 1 * cm
    c.setFont(text_font, 11)
    _pdf_safe_drawString(c, 2 * cm, y, f"Case No: {visit_id}   Order#: {oid}", max_chars=160)
    y -= 0.7 * cm
    _pdf_safe_drawString(c, 2 * cm, y, f"Patient: {_co_row_get(visit,'name','-')}   ID: {_co_row_get(visit,'id_number','-')}", max_chars=160)
    y -= 0.7 * cm

    ordered_raw = _co_row_get(order, 'created_at', '')
    try:
        ordered_at = format_dt_local(ordered_raw) or (ordered_raw or '-')
    except Exception:
        ordered_at = ordered_raw or '-'
    try:
        ordered_by = _staff_display_with_ids(cur, _co_row_get(order, 'created_by', '') or '-')
    except Exception:
        ordered_by = _co_row_get(order, 'created_by', '') or '-'

    src_area, src_loc, src_bed = _final20260518_correct_source_tuple(
        cur,
        visit_id,
        _co_row_get(order, 'order_source_area', ''),
        _co_row_get(order, 'order_source_location', ''),
        _co_row_get(order, 'order_source_bed', ''),
        event_ts=ordered_raw,
    )
    order_source_text = _format_order_source_text(src_area, src_loc, src_bed) or '-'
    current_text = _format_order_source_text(
        _co_row_get(visit, 'care_area', '') or _co_row_get(visit, 'clinic', 'ED') or 'ED',
        _co_row_get(visit, 'location', ''),
        _co_row_get(visit, 'bed_no', ''),
    ) or '-'

    c.setFont(italic_font, 9)
    _pdf_safe_drawString(c, 2 * cm, y, f"Ordered: {ordered_at}  |  by {ordered_by}", max_chars=150)
    y -= 0.5 * cm
    c.setFont(text_font, 9)
    _pdf_safe_drawString(c, 2 * cm, y, f"Order Source: {order_source_text}", max_chars=150)
    y -= 0.45 * cm
    _pdf_safe_drawString(c, 2 * cm, y, f"Patient Current Location: {current_text}", max_chars=150)
    y -= 0.85 * cm

    def section(title, text):
        nonlocal y
        c.setFont(bold_font, 12)
        _pdf_safe_drawString(c, 2 * cm, y, title, max_chars=160)
        y -= 0.6 * cm
        c.setFont(text_font, 10)
        for line in str(text or '-').splitlines():
            _pdf_safe_drawString(c, 2.2 * cm, y, line or '-', max_chars=110)
            y -= 0.45 * cm
            if y < 2 * cm:
                c.showPage()
                y = height - 2 * cm
                c.setFont(text_font, 10)
        y -= 0.3 * cm

    section('Diagnosis / Chief Complaint:', _co_row_get(order, 'diagnosis', '') or '-')
    section('Radiology orders:', _co_row_get(order, 'radiology_orders', '') or '-')
    rfe = _co_row_get(order, 'reason_for_exam', '')
    if rfe:
        section('Reason for Exam / Clinical Indication:', rfe)
    section('Lab orders:', _co_row_get(order, 'lab_orders', '') or '-')
    rfo = _co_row_get(order, 'reason_for_order', '')
    if rfo:
        section('Reason for Lab Order / Clinical Indication:', rfo)
    section('Medications:', _co_row_get(order, 'medications', '') or '-')
    mind = _co_row_get(order, 'med_indication', '')
    if mind:
        section('Indication / Reason for Medication:', mind)

    sig_y = max(2.0 * cm, y - 1.5 * cm)
    c.setFont(text_font, 9)
    _pdf_safe_drawString(c, 2 * cm, sig_y, f"Physician: {doctor_display}", max_chars=90)
    _pdf_safe_drawString(c, width / 2, sig_y, 'Signature: ______________________', max_chars=60)

    c.setFont(italic_font, 8)
    _pdf_safe_drawString(c, 2 * cm, 1.2 * cm, APP_FOOTER_TEXT, max_chars=180)
    c.showPage()
    try:
        v_add = _mrd_fetch_visit_for_addendum(cur, visit_id) or visit
        printed_at2, reg_dt2, triage_dt2, discharge_dt2, age2 = _mrd_addendum_context_from_visit(v_add)
        _mrd_draw_addendum_pages(
            c,
            cur=cur,
            visit=v_add,
            visit_id=visit_id,
            age=age2,
            printed_at=printed_at2,
            reg_dt=reg_dt2,
            triage_dt=triage_dt2,
            discharge_dt=discharge_dt2,
            report_label=f"Clinical Order #{oid}",
            include_labs=True,
            include_rads=True,
            include_meds=True,
            include_discharge_snapshot=True,
            page_break_after=False,
        )
    except Exception as exc:
        _log_noncritical_exception(f"Clinical order PDF timeline appendix failed for visit={visit_id}", exc)

    c.save()
    buffer.seek(0)
    pdf_bytes = buffer.getvalue()
    try:
        if cache_ttl > 0:
            _PDF_RENDER_CACHE.set(cache_key, pdf_bytes, cache_ttl)
    except Exception:
        pass
    return Response(pdf_bytes, mimetype='application/pdf', headers=_patient_pdf_headers(visit, f'ClinicalOrder-{oid}', visit_id=visit_id))

