# Auto ED Course: keep original sections but make Movement timeline explicit from start to finish.
try:
    _orig_build_auto_summary_sections_final20260518 = build_auto_summary_sections
    def build_auto_summary_sections(visit_id):
        try:
            _final20260518_repair_mixed_order_sources_for_visit(visit_id, auto_commit=True)
        except Exception:
            pass
        sections = _orig_build_auto_summary_sections_final20260518(visit_id) or []
        try:
            cur = get_db().cursor()
            v = _final20260518_visit_location(cur, visit_id)
            movement_rows = []
            try:
                _ensure_patient_location_movement_schema(cur)
                movement_rows = cur.execute(
                    "SELECT * FROM patient_location_movements WHERE visit_id=? ORDER BY COALESCE(moved_at,'') ASC, id ASC",
                    (visit_id,),
                ).fetchall() or []
            except Exception:
                movement_rows = []
            def _fmt(vv):
                try:
                    return format_dt_local(vv) or (str(vv).strip() if vv else '-')
                except Exception:
                    return str(vv or '-').strip() or '-'
            def _staff(vv):
                try:
                    return _staff_display_with_ids(cur, vv or '-')
                except Exception:
                    return vv or '-'
            lines = []
            # Beginning of the visit.
            first_from = None
            if movement_rows:
                mv0 = movement_rows[0]
                first_from = _format_order_source_text(_co_row_get(mv0, 'from_area', ''), _co_row_get(mv0, 'from_location', ''), _co_row_get(mv0, 'from_bed', ''))
            initial_loc = first_from or _format_order_source_text(v.get('clinic') or 'ED', '', '') or 'ED'
            lines.append(f"- {_fmt(v.get('created_at'))}: Registered / initial care area: {initial_loc} | By: {_staff(v.get('created_by') or '-')}")
            for mv in movement_rows:
                ts = _fmt(_co_row_get(mv, 'moved_at', ''))
                by = _staff(_co_row_get(mv, 'moved_by', '') or '-')
                from_txt = _format_order_source_text(_co_row_get(mv, 'from_area', ''), _co_row_get(mv, 'from_location', ''), _co_row_get(mv, 'from_bed', '')) or '-'
                to_txt = _format_order_source_text(_co_row_get(mv, 'to_area', ''), _co_row_get(mv, 'to_location', ''), _co_row_get(mv, 'to_bed', '')) or '-'
                st = _co_row_get(mv, 'status', '') or '-'
                note = str(_co_row_get(mv, 'note', '') or '').strip()
                line = f"- {ts}: {from_txt} -> {to_txt} | Status: {st} | By: {by}"
                if note:
                    line += f" | Note: {note}"
                lines.append(line)
            current_txt = _format_order_source_text(v.get('care_area') or v.get('clinic') or 'ED', v.get('location') or '', v.get('bed_no') or '') or '-'
            lines.append(f"- Current Location: {current_txt} | Status: {v.get('status') or '-'}")
            replaced = False
            out = []
            for title, body in sections:
                if str(title).strip().lower() == 'patient movement / care area timeline':
                    out.append((title, '\n'.join(lines).strip() or '-'))
                    replaced = True
                else:
                    out.append((title, body))
            if not replaced:
                out.insert(1, ('Patient Movement / Care Area Timeline', '\n'.join(lines).strip() or '-'))
            return out
        except Exception as exc:
            _log_noncritical_exception(f'Final Auto ED Course movement timeline wrapper failed for visit={visit_id}', exc)
            return sections
    globals()['build_auto_summary_sections'] = build_auto_summary_sections
except Exception as _summary_wrap_exc:
    try:
        _log_noncritical_exception('Auto ED Course movement wrapper setup failed', _summary_wrap_exc)
    except Exception:
        pass

