        tpl2 = re.sub(r"<div\s+class=\"x-history-list\">\s*\{\%\s*for\s+a\s+in\s+admins\s*\%\}.*?\{\%\s*endfor\s*\%\}\s*</div>", history_body, tpl2, count=1, flags=re.S)
