def _hdc_print_department_courses_20260519o(raw_json):
    sections = _hdc_safe_json_loads_20260519o(raw_json, [])
    lines = []
    for sec in sections:
        if not isinstance(sec, dict):
            continue
        area = sec.get("area_label") or "Care area"
        fr = sec.get("from_time") or "-"
        to = sec.get("to_time") or "-"
        lines.append(f"{area} ({fr} -> {to})")
        if sec.get("responsible"):
            lines.append(f"Responsible clinician/team: {sec.get('responsible')}")
        if sec.get("status"):
            lines.append(f"Status/Disposition during stay: {sec.get('status')}")
        if sec.get("course_note"):
            lines.append("Course:")
            lines.extend([f"- {x}" for x in str(sec.get("course_note")).splitlines() if x.strip()])
        if sec.get("procedures"):
            lines.append("Procedures / interventions:")
            lines.extend([f"- {x}" for x in str(sec.get("procedures")).splitlines() if x.strip()])
        if sec.get("complications"):
            lines.append("Complications / issues:")
            lines.extend([f"- {x}" for x in str(sec.get("complications")).splitlines() if x.strip()])
        if sec.get("plan"):
            lines.append("Plan / outcome:")
            lines.extend([f"- {x}" for x in str(sec.get("plan")).splitlines() if x.strip()])
        lines.append("")
    return "\n".join(lines).strip()


