_PROPDF_BRAND_BLUE_20260519Q = colors.HexColor("#0b63ce")
_PROPDF_LIGHT_BLUE_20260519Q = colors.HexColor("#eef6ff")
_PROPDF_BORDER_20260519Q = colors.HexColor("#b8d4f3")
_PROPDF_TEXT_20260519Q = colors.HexColor("#111827")
