        story.append(_pdfx_section('Medication Orders')); story.append(_pdfx_table([['#','Medication','Source','Ordered by']] + [[i+1,x,src,order.get('created_by')] for i,x in enumerate(_pdfx_split_items(order.get('medications')))], col_widths=[0.8*_PDFX_cm,8.5*_PDFX_cm,4.0*_PDFX_cm,4.7*_PDFX_cm], header=True))
        story.append(_PDFXSpacer(1,0.25*_PDFX_cm)); story.append(_pdfx_signature_block())
