    def _pdfx_patient_summary_body(ctx, mode='full'):
        story = []
        story.extend(_pdfx_discharge_body(ctx, mode='short'))
        story.append(_pdfx_section('Medication Orders - ED / Inpatient'))
        story.append(_pdfx_med_orders_table(ctx))
        story.append(_pdfx_section('Home Medication / Discharge Prescription'))
        story.append(_pdfx_home_med_table(ctx))
        story.append(_pdfx_section('Orders / Results Snapshot'))
