# LOADTEST_1500_LOGOUT_DB_PDF_HOTFIX_20260525D
# ------------------------------------------------------------
# Production load-test hotfix for the 1500-active-session run.
# Scope is deliberately narrow:
#   - fast /logout path (no user-facing DB work)
#   - no runtime DDL/schema repair inside normal PostgreSQL requests
#   - no GET-time source repair updates on Clinical Orders / boards
#   - PDF endpoints return a safe printable fallback instead of HTTP 500
#   - keep Radiology Board buttons/workflow untouched
# ------------------------------------------------------------
try:
    _PERF25_TAG = "LOADTEST_1500_LOGOUT_DB_PDF_HOTFIX_20260525D"

    def _perf25_cfg_bool(name, default=False):
        try:
            raw = os.environ.get(name)
            if raw is None:
                raw = APP_CONFIG.get(name, default)
        except Exception:
            raw = default
        if isinstance(raw, bool):
            return raw
        s = str(raw or "").strip().lower()
        if s in ("1", "true", "yes", "y", "on"):
            return True
        if s in ("0", "false", "no", "n", "off", "none"):
            return False
        return bool(default)

    def _perf25_cfg_float(name, default=0.0):
        try:
            raw = os.environ.get(name)
            if raw is None:
                raw = APP_CONFIG.get(name, default)
            return float(raw)
        except Exception:
            try:
                return float(default)
            except Exception:
                return 0.0

    def _perf25_runtime_ddl_allowed():
        # PostgreSQL production/1500-user mode must not run ALTER/CREATE from user requests.
        # SQLite keeps its legacy self-healing behavior for portable/dev mode.
        try:
            if (DB_ENGINE or "").lower() != "postgres":
                return True
        except Exception:
            return True
        return _perf25_cfg_bool("ED_ALLOW_RUNTIME_DDL", False)

    def _perf25_is_light_request():
        try:
            path = (request.path or "").strip().lower()
        except Exception:
            path = ""
        try:
            ep = (request.endpoint or "").rsplit(".", 1)[-1].lower()
        except Exception:
            ep = ""
        if path in ("/logout", "/healthz", "/favicon.ico", "/csrf_token", "/session_status"):
            return True
        if ep in ("logout", "healthz", "static", "csrf_token_api", "session_status"):
            return True
        if path.startswith("/static/"):
            return True
        return False

    # 1) Make logout user-facing path constant-time: clear cookie/session and redirect.
    #    Slow cleanup remains best-effort and bounded in the background.
    try:
        _PERF25_LOGOUT_SEM = threading.BoundedSemaphore(max(1, int(_perf25_cfg_float("LOGOUT_CLEANUP_MAX_WORKERS", 1))))
    except Exception:
        _PERF25_LOGOUT_SEM = threading.BoundedSemaphore(1)

    def _perf25_logout_cleanup_bounded(user_id=None, username=None, session_token=None, viewer_token=None):
        acquired = False
        try:
            acquired = _PERF25_LOGOUT_SEM.acquire(blocking=False)
            if not acquired:
                return
            try:
                _logout_cleanup_worker(user_id=user_id, username=username, session_token=session_token, viewer_token=viewer_token)
            except TypeError:
                _logout_cleanup_worker(user_id, username, session_token, viewer_token)
            except Exception:
                pass
        finally:
            if acquired:
                try:
                    _PERF25_LOGOUT_SEM.release()
                except Exception:
                    pass

    def logout():  # type: ignore[override]
        user_id = session.get("user_id")
        username = (session.get("username") or "").strip()
        session_token = (session.get("_session_token") or "").strip()
        viewer_token = (session.get("visit_lock_viewer_token") or "").strip()
        try:
            session.clear()
        except Exception:
            pass
        try:
            session.modified = True
        except Exception:
            pass
        try:
            resp = redirect(url_for("login"))
        except Exception:
            resp = redirect("/login")
        try:
            cname = app.config.get("SESSION_COOKIE_NAME", "session")
            resp.delete_cookie(cname, path="/")
        except Exception:
            pass
        try:
            resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, private, max-age=0"
            resp.headers["Pragma"] = "no-cache"
            resp.headers["Expires"] = "0"
            resp.headers["Surrogate-Control"] = "no-store"
            resp.headers.pop("Clear-Site-Data", None)  # TABLET_LOGOUT_FAST_20260526A: avoid slow iPad/Safari site-data purge
        except Exception:
            pass
        if _perf25_cfg_bool("LOGOUT_ASYNC_CLEANUP_ENABLED", True):
            try:
                t = threading.Thread(
                    target=_perf25_logout_cleanup_bounded,
                    kwargs={
                        "user_id": user_id,
                        "username": username,
                        "session_token": session_token,
                        "viewer_token": viewer_token,
                    },
                    name="EDDT-FastLogoutCleanup",
                    daemon=True,
                )
                t.start()
            except Exception:
                pass
        return resp

    try:
        globals()["logout"] = logout
        app.view_functions["logout"] = logout
    except Exception:
        pass

    # 2) Stop runtime DDL/schema repair in normal PostgreSQL request paths.
    if not _perf25_runtime_ddl_allowed():
        try:
            _AUDIT_LOG_SCHEMA_COMPAT_READY = True
        except Exception:
            pass
        def ensure_audit_log_schema_compat_once():  # type: ignore[override]
            return True
        globals()["ensure_audit_log_schema_compat_once"] = ensure_audit_log_schema_compat_once

        try:
            _presence_schema_ready = True
        except Exception:
            pass
        def ensure_user_presence_schema():  # type: ignore[override]
            return True
        globals()["ensure_user_presence_schema"] = ensure_user_presence_schema

        _perf25_orig_location_schema_ensure = globals().get("_ensure_patient_location_movement_schema")
        def _ensure_patient_location_movement_schema(cur):  # type: ignore[override]
            # Runtime DDL is already handled by Repair_Postgres_Runtime.bat / migrations.
            return True
        globals()["_ensure_patient_location_movement_schema"] = _ensure_patient_location_movement_schema

        _perf25_orig_order_reason_ensure = globals().get("_ensure_order_reason_schema_columns")
        def _ensure_order_reason_schema_columns(strict=True):  # type: ignore[override]
            global _ORDER_REASON_SCHEMA_READY
            try:
                if _ORDER_REASON_SCHEMA_READY:
                    return True
            except Exception:
                pass
            missing = []
            try:
                for table_name, col_name, col_type in _ORDER_REASON_SCHEMA_COLUMNS:
                    cols = _order_reason_cols_lower(table_name)
                    if str(col_name or "").lower() not in cols:
                        missing.append((table_name, col_name, col_type))
                    else:
                        try:
                            _ensured_columns_cache.add((table_name.lower(), col_name.lower()))
                        except Exception:
                            pass
            except Exception as exc:
                if strict:
                    raise
                try:
                    _log_noncritical_exception("Order reason schema read-only check failed", exc)
                except Exception:
                    pass
                return False
            if missing:
                msg = "Clinical Orders schema migration is required before production load: " + _format_missing_order_reason_columns(missing)
                if strict:
                    raise RuntimeError(msg)
                try:
                    _log_noncritical_exception(msg)
                except Exception:
                    pass
                return False
            try:
                _ORDER_REASON_SCHEMA_READY = True
            except Exception:
                pass
            return True
        globals()["_ensure_order_reason_schema_columns"] = _ensure_order_reason_schema_columns

        def _ensure_clinical_order_request_links():  # type: ignore[override]
            global _CLINICAL_ORDER_REQUEST_LINKS_READY
            if _ensure_order_reason_schema_columns(strict=True):
                try:
                    _CLINICAL_ORDER_REQUEST_LINKS_READY = True
                except Exception:
                    pass
            return None
        globals()["_ensure_clinical_order_request_links"] = _ensure_clinical_order_request_links

    # 3) Replace heavy audit hooks with light-path aware versions.
    def _perf25_audit_start():
        if _perf25_is_light_request():
            return None
        try:
            # In production no-DDL mode this is a no-op. In SQLite/dev it can self-heal once.
            ensure_audit_log_schema_compat_once()
        except Exception:
            pass
        try:
            security.audit_before_request()
        except Exception:
            pass
        return None

    def _perf25_audit_end(resp):
        if _perf25_is_light_request():
            return resp
        try:
            security.audit_after_request(resp)
        except Exception:
            pass
        return resp

    try:
        br = list(app.before_request_funcs.get(None, []))
        app.before_request_funcs[None] = [(_perf25_audit_start if getattr(f, "__name__", "") == "_audit_start" else f) for f in br]
    except Exception:
        pass
    try:
        ar = list(app.after_request_funcs.get(None, []))
        app.after_request_funcs[None] = [(_perf25_audit_end if getattr(f, "__name__", "") == "_audit_end" else f) for f in ar]
    except Exception:
        pass

    # 4) Disable read-request repair updates. New writes already store corrected source/location.
    def _perf25_get_repair_enabled():
        return _perf25_cfg_bool("ED_ENABLE_GET_SOURCE_REPAIR", False)

    _perf25_orig_source_repair = globals().get("_final20260518_repair_mixed_order_sources_for_visit")
    def _final20260518_repair_mixed_order_sources_for_visit(visit_id, auto_commit=True):  # type: ignore[override]
        try:
            if request and request.method == "GET" and not _perf25_get_repair_enabled():
                return 0
        except Exception:
            pass
        try:
            if not _perf25_get_repair_enabled() and (DB_ENGINE or "").lower() == "postgres":
                return 0
        except Exception:
            pass
        if callable(_perf25_orig_source_repair):
            return _perf25_orig_source_repair(visit_id, auto_commit=auto_commit)
        return 0
    globals()["_final20260518_repair_mixed_order_sources_for_visit"] = _final20260518_repair_mixed_order_sources_for_visit

    # The prior wrapper around clinical_orders_page did a repair before rendering.
    # Unwrap it when the saved original exists; this keeps the UI intact and removes write work from GET.
    try:
        _orig_co_page = globals().get("_orig_clinical_orders_page_final20260518")
        if callable(_orig_co_page) and not _perf25_get_repair_enabled():
            globals()["clinical_orders_page"] = _orig_co_page
            app.view_functions["clinical_orders_page"] = _orig_co_page
    except Exception:
        pass

    # 5) Sticker parser guard: malformed/partial PDF attachments must never break request handling.
    _perf25_prev_sticker_pdf = globals().get("_sticker_pdf_bytes_for_attachment_v20260525")
    def _sticker_pdf_bytes_for_attachment_v20260525(pdf_bytes, visit_id, filename, patient_context=None):  # type: ignore[override]
        try:
            data = bytes(pdf_bytes or b"")
        except Exception:
            return pdf_bytes
        if not data or not data.lstrip().startswith(b"%PDF"):
            return pdf_bytes
        # If the trailer is missing/corrupt, pypdf raises startxref errors. Serve/store original safely.
        try:
            tail = data[-4096:]
            if b"%%EOF" not in tail:
                return pdf_bytes
        except Exception:
            return pdf_bytes
        try:
            if callable(_perf25_prev_sticker_pdf):
                return _perf25_prev_sticker_pdf(data, visit_id, filename, patient_context=patient_context)
        except Exception as exc:
            try:
                _log_noncritical_exception(f"Attachment PDF patient sticker skipped safely visit={visit_id} filename={filename}", exc)
            except Exception:
                pass
        return pdf_bytes
    globals()["_sticker_pdf_bytes_for_attachment_v20260525"] = _sticker_pdf_bytes_for_attachment_v20260525

    # 6) PDF result endpoints: never return HTTP 500 under load; provide printable fallback.
    _PERF25_PDF_TITLES = {
        "lab_results_pdf": "Lab Results",
        "radiology_results_pdf": "Radiology Results",
        "ip_admission_report_pdf": "IP Admission Report",
        "patient_summary_pdf": "Patient Summary",
    }

    def _perf25_safe_text(value, default="-"):
        try:
            s = str(value if value is not None else "").strip()
            return s if s else default
        except Exception:
            return default

    def _perf25_minimal_pdf_response(visit_id, title, exc=None):
        buf = io.BytesIO()
        try:
            c = canvas.Canvas(buf, pagesize=A4)
            w, h = A4
            y = h - 1.5 * cm
            patient_name = "-"
            mrn = "-"
            pid = "-"
            try:
                db = get_db()
                cur = db.cursor()
                row = cur.execute(
                    """
                    SELECT p.name, p.mrn, p.id_number
                    FROM visits v JOIN patients p ON p.id=v.patient_id
                    WHERE v.visit_id=?
                    LIMIT 1
                    """,
                    (visit_id,),
                ).fetchone()
                if row:
                    patient_name = _perf25_safe_text(_pdf_row_get(row, "name", "-"))
                    mrn = _perf25_safe_text(_pdf_row_get(row, "mrn", "-"))
                    pid = _perf25_safe_text(_pdf_row_get(row, "id_number", "-"))
            except Exception:
                pass
            c.setFont("Helvetica-Bold", 16)
            c.drawString(1.5 * cm, y, _perf25_safe_text(title, "Report"))
            y -= 0.9 * cm
            c.setFont("Helvetica", 10)
            c.drawString(1.5 * cm, y, f"Case No: {_perf25_safe_text(visit_id)}")
            y -= 0.45 * cm
            c.drawString(1.5 * cm, y, f"Patient: {patient_name}")
            y -= 0.45 * cm
            c.drawString(1.5 * cm, y, f"MRN: {mrn}    ID: {pid}")
            y -= 0.9 * cm
            c.setFont("Helvetica-Bold", 10)
            c.drawString(1.5 * cm, y, "Report generation fallback")
            y -= 0.5 * cm
            c.setFont("Helvetica", 9)
            lines = [
                "The full report could not be rendered by the PDF generator at this moment.",
                "The clinical data remains available inside the system screens and attachments.",
                "Please retry printing after the current load spike, or open the source attachment if available.",
            ]
            if exc is not None:
                try:
                    lines.append("Technical note: " + str(exc).splitlines()[0][:160])
                except Exception:
                    pass
            for line in lines:
                c.drawString(1.5 * cm, y, line[:180])
                y -= 0.42 * cm
            c.setFont("Helvetica-Oblique", 8)
            c.drawString(1.5 * cm, 1.1 * cm, "ED Downtime - safe PDF fallback, no clinical data was discarded.")
            c.showPage()
            c.save()
        except Exception:
            try:
                buf = io.BytesIO(b"%PDF-1.4\n% ED Downtime PDF fallback failed\n%%EOF\n")
            except Exception:
                return Response("PDF generation failed", status=503, mimetype="text/plain")
        data = buf.getvalue()
        try:
            headers = _patient_pdf_headers({"visit_id": visit_id}, str(title or "Report").replace(" ", ""), visit_id=visit_id)
        except Exception:
            headers = {"Content-Disposition": f"inline; filename={_perf25_safe_text(visit_id, 'visit')}_{str(title or 'Report').replace(' ','_')}.pdf"}
        try:
            headers["X-ED-Downtime-PDF-Fallback"] = "1"
            headers["Cache-Control"] = "no-store, no-cache, must-revalidate, private, max-age=0"
        except Exception:
            pass
        return Response(data, mimetype="application/pdf", headers=headers)

    def _perf25_wrap_pdf_endpoint(endpoint):
        orig = app.view_functions.get(endpoint)
        if not callable(orig) or getattr(orig, "_perf25_pdf_safe", False):
            return
        title = _PERF25_PDF_TITLES.get(endpoint, endpoint)
        @wraps(orig)
        def _wrapped_pdf(*args, **kwargs):
            try:
                return orig(*args, **kwargs)
            except Exception as exc:
                try:
                    vid = kwargs.get("visit_id") if kwargs else None
                    if vid is None and args:
                        vid = args[0]
                except Exception:
                    vid = ""
                try:
                    _log_noncritical_exception(f"{_PERF25_TAG}: safe fallback for {endpoint} visit={vid}", exc)
                except Exception:
                    pass
                return _perf25_minimal_pdf_response(vid, title, exc=exc)
        _wrapped_pdf._perf25_pdf_safe = True
        try:
            app.view_functions[endpoint] = _wrapped_pdf
            globals()[endpoint] = _wrapped_pdf
        except Exception:
            pass

    for _perf25_ep in ("lab_results_pdf", "radiology_results_pdf", "ip_admission_report_pdf", "patient_summary_pdf"):
        try:
            _perf25_wrap_pdf_endpoint(_perf25_ep)
        except Exception:
            pass

    try:
        app.logger.info("%s loaded", _PERF25_TAG)
    except Exception:
        pass
except Exception as _perf25_exc:
    try:
        _log_noncritical_exception("LOADTEST_1500_LOGOUT_DB_PDF_HOTFIX_20260525D failed", _perf25_exc)
    except Exception:
        pass


# ------------------------------------------------------------
# FINAL_FIX_20260525E_RECEPTION_RESULT_ICON_AND_CO_RAD_COLLAPSE
# - Reception Services Summary: hide Result / Admin time text behind a View icon/modal.
# - Clinical Orders > Results: Radiology Requests section collapsed by default with an arrow.
# - UI-only patch. Does not touch Radiology Board actions/workflow/backend.
