    _ur27e_prev_sticker_pdf = globals().get("_sticker_pdf_bytes_for_attachment_v20260525")
    if callable(_ur27e_prev_sticker_pdf) and not getattr(_ur27e_prev_sticker_pdf, "_ur27e_sticker_guard", False):
        def _sticker_pdf_bytes_for_attachment_v20260525(pdf_bytes, visit_id, filename, patient_context=None):
            try:
                data = bytes(pdf_bytes or b"")
            except Exception:
                return pdf_bytes
            if not data or not data.lstrip().startswith(b"%PDF"):
                return pdf_bytes
            tail = data[-8192:]
            if b"%%EOF" not in tail or b"startxref" not in tail:
                return pdf_bytes
            try:
                return _ur27e_prev_sticker_pdf(data, visit_id, filename, patient_context=patient_context)
            except Exception as exc:
                try:
                    app.logger.warning("%s attachment sticker skipped visit=%s file=%s: %s", _UR27E_TAG, visit_id, filename, str(exc)[:120])
                except Exception:
                    pass
                return pdf_bytes
        _sticker_pdf_bytes_for_attachment_v20260525._ur27e_sticker_guard = True
