# USER_REQUEST_AI_ASSISTANT_FINAL_OFFLINE_CORRECTION_OVERRIDE_20260527J
# Final override: avoid echoing unclear misspellings in suggestions, while keeping them
# in warnings for physician review. This fixes cases like: chest pain defelct preses.
try:
    import re as _ai27j_re
    import os as _ai27j_os

    _AI27J_TAG = 'AI_ASSISTANT_FINAL_OFFLINE_CORRECTION_OVERRIDE_20260527J'

    def _ai27_get_openai_key():
        return (_ai27j_os.environ.get('ED_OPENAI_API_KEY')
                or _ai27j_os.environ.get('OPENAI_API_KEY')
                or _ai27j_os.environ.get('ED_OPNEAI_API_KEY')
                or '')

    def _ai27_openai_key_present():
        return bool(_ai27_get_openai_key())

    _AI27J_PHRASES = [
        (r'\bches\s+pain\b', 'chest pain'), (r'\bchest\s+pian\b', 'chest pain'),
        (r'\bfeaver\b', 'fever'), (r'\bvommiting\b', 'vomiting'),
        (r'\bnausia\b', 'nausea'), (r'\bnusea\b', 'nausea'),
        (r'\bdizzines\b', 'dizziness'), (r'\bheadach\b', 'headache'),
        (r'\bdiarhea\b', 'diarrhea'), (r'\bsob\b', 'shortness of breath'),
        (r'\babd\s+pain\b', 'abdominal pain'),
    ]
    _AI27J_WORDS = {
        'preses':'presents', 'presnt':'presents', 'presentes':'presents',
        'paitent':'patient', 'patinet':'patient', 'complane':'complains',
        'deneis':'denies', 'denie':'denies', 'assoicated':'associated',
        'stabel':'stable', 'dischrage':'discharge', 'dischage':'discharge',
        'referal':'referral', 'folow':'follow', 'followup':'follow-up',
        'medcation':'medication', 'proceduer':'procedure', 'investgation':'investigation',
    }
    _AI27J_UNCLEAR = {'defelct', 'deflect'}
    _AI27J_TERMS = ['chest pain','abdominal pain','shortness of breath','fever','vomiting','nausea','dizziness','headache','diarrhea','cough','palpitations','syncope','weakness','back pain','flank pain','trauma','fall','rash','wound','asthma','pneumonia','hypertension','diabetes','stroke','seizure']

    def _ai27j_clean_sentence(text):
        t = _ai27_clean_text(text, 3500) if '_ai27_clean_text' in globals() else str(text or '').strip()
        changes, unclear = [], []
        for pat, rep in _AI27J_PHRASES:
            if _ai27j_re.search(pat, t, flags=_ai27j_re.I):
                t = _ai27j_re.sub(pat, rep, t, flags=_ai27j_re.I)
                changes.append(rep)
        def repl(m):
            token = m.group(0)
            low = token.lower()
            if low in _AI27J_UNCLEAR:
                if low not in unclear: unclear.append(low)
                return ''
            if low in _AI27J_WORDS:
                val = _AI27J_WORDS[low]
                if val.lower() != low: changes.append(f'{token} -> {val}')
                return val
            return token
        t = _ai27j_re.sub(r'\b[A-Za-z][A-Za-z\-]*\b', repl, t)
        t = _ai27j_re.sub(r'\s+', ' ', t).strip(' ,;:-')
        t = _ai27j_re.sub(r'\s+([.,;:])', r'\1', t)
        if t:
            t = t[0].upper() + t[1:]
            if not t.endswith(('.', '?', '!', ':')): t += '.'
        return t, sorted(set(changes))[:8], sorted(set(unclear))[:8]

    def _ai27j_terms(text):
        low = ' ' + str(text or '').lower() + ' '
        found = []
        for term in sorted(_AI27J_TERMS, key=len, reverse=True):
            if _ai27j_re.search(r'(?<![a-z])' + _ai27j_re.escape(term) + r'(?![a-z])', low):
                found.append(term)
        return found[:6]

    def _ai27j_pretty(term):
        return ' '.join(p.capitalize() for p in str(term).split())

    def _ai27_offline_assist(field_key, label, text, task):
        task = (task or 'improve').lower()
        label = label or (_AI27_FIELD_GUIDANCE.get(field_key) if '_AI27_FIELD_GUIDANCE' in globals() else '') or field_key or 'Clinical Note'
        clean = _ai27_clean_text(text, 3500) if '_ai27_clean_text' in globals() else str(text or '').strip()
        if not clean:
            return _ai27_generic_safe_draft(field_key, label), ['No existing text was provided; generated a conservative starter draft only.', 'Offline mode was used; no external request was made.']
        fixed, changes, unclear = _ai27j_clean_sentence(clean)
        terms = _ai27j_terms(fixed or clean)
        warnings = ['Offline medical spelling/wording assistant was used; no external request was made.']
        if changes:
            warnings.append('Corrected common spelling/medical wording: ' + '; '.join(changes) + '.')
        if unclear:
            warnings.append('Unclear text requires physician clarification and was not inserted as a confirmed fact: ' + ', '.join(unclear) + '.')
        label_l = (label or '').lower()
        if task == 'shorten':
            return fixed[:700], warnings + ['Shortened without adding new clinical facts.']
        if task == 'expand':
            out = fixed
            if len(out) < 160:
                out += ' Additional relevant details should be completed by the treating physician if documented.'
            return out, warnings + ['Expanded only from the text provided; no undocumented facts were added.']
        if 'chief' in label_l or field_key == 'diagnosis_cc':
            if terms:
                out = 'Chief Complaint: ' + '; '.join(_ai27j_pretty(t) for t in terms) + '.'
                if unclear:
                    out += ' Additional details require physician clarification.'
                return out, warnings + ['Chief complaint wording was normalized from the supplied text only.']
            return 'Chief Complaint: ' + fixed, warnings + ['Chief complaint wording was normalized from the supplied text only.']
        if 'final diagnosis' in label_l or field_key == 'final_diagnosis':
            if terms:
                return 'Final Diagnosis: ' + '; '.join(_ai27j_pretty(t) for t in terms) + '.', warnings + ['Final diagnosis text was normalized; physician confirmation is required.']
        if task in ('draft','generate','from_context'):
            return (_ai27_generic_safe_draft(field_key, label) + '\n\nProvided notes, corrected where possible: ' + fixed), warnings + ['Generated a conservative draft from provided notes; physician review is required.']
        if len(fixed) < 90 and not fixed.lower().startswith(str(label).lower()[:12]):
            fixed = str(label).strip().rstrip(':') + ': ' + fixed
        return fixed, warnings + ['Improved wording only; no diagnoses, medications, results, or procedures were added.']

    try: app.logger.info('%s loaded; final offline correction override active', _AI27J_TAG)
    except Exception: pass
except Exception as _ai27j_exc:
    try: app.logger.exception('USER_REQUEST_AI_ASSISTANT_FINAL_OFFLINE_CORRECTION_OVERRIDE_20260527J failed: %s', _ai27j_exc)
    except Exception: pass


