            req_loc = _attachment_sticker_text_v20260525(ctx.get("request_location") or ctx.get("order_request_location") or ctx.get("order_source") or "-", 54)
            ordered_at = _attachment_sticker_text_v20260525(ctx.get("order_ordered_at") or ctx.get("ordered_at") or "-", 34)
            display_order = _attachment_sticker_text_v20260525(_rf20260601g_display_order_for_ctx(ctx, filename), 60)
            left_x = 0.8 * cm
            mid_x = width * 0.42
            right_x = width - 0.8 * cm
            y = total_h - 0.38 * cm
            c.setFillColor(colors.black)
            c.setFont("Helvetica-Bold", 8.2)
            c.drawString(left_x, y, f"{title}   |   {doc_type}   |   Case: {case_no}")
