        try:
            if viewer_token:
                session["visit_lock_viewer_token"] = viewer_token
        except Exception:
            pass
        try:
            ip = request.headers.get("X-Forwarded-For") or request.remote_addr or ""
        except Exception:
            ip = ""
        try:
            ua = request.headers.get("User-Agent") or ""
        except Exception:
            ua = ""
        now_ts = int(time.time())
        window_seconds = int(globals().get("VISIT_LOCK_WINDOW_SECONDS", app.config.get("VISIT_LOCK_WINDOW_SECONDS", 12)) or 12)
        cutoff = now_ts - window_seconds
        now_iso = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
