    # 3) Scan lookup: accept Cerner MRN exactly like Downtime MRN / ID.
    def api_scan_lookup_cerner_20260602c():
        raw_code = request.args.get("code") or request.values.get("code") or ""
        code = normalize_scan_code(raw_code)
        if not code:
            return jsonify({"ok": True, "found": False, "code": ""})
        try:
            cur = get_db().cursor()
            base_select = """
                SELECT
                    v.visit_id,
                    v.created_at AS visit_created_at,
                    COALESCE(v.clinic,'') AS clinic,
                    COALESCE(v.assigned_doctor,'') AS doctor,
                    COALESCE(v.status,'') AS status,
                    p.name,
                    p.dob,
                    p.mrn,
                    COALESCE(p.cerner_mrn,'') AS cerner_mrn,
                    p.id_number,
                    COALESCE(p.insurance,'') AS insurance,
                    COALESCE(p.insurance_no,'') AS insurance_no
                FROM visits v
                JOIN patients p ON p.id = v.patient_id
            """
            row = cur.execute(base_select + " WHERE v.visit_id = ? LIMIT 1", (code,)).fetchone()
            if not row:
                row = cur.execute(
                    base_select + " WHERE p.id_number = ? OR p.mrn = ? OR p.cerner_mrn = ? ORDER BY v.created_at DESC LIMIT 1",
                    (code, code, code),
                ).fetchone()
            if not row:
                # Normalized fallback for Cerner MRN with separators/spaces.
                ncode = re.sub(r"[^A-Za-z0-9]+", "", code or "").upper()
                if ncode:
                    if (DB_ENGINE or "").lower() == "postgres":
                        row = cur.execute(
                            base_select + " WHERE UPPER(REGEXP_REPLACE(COALESCE(p.cerner_mrn,''), '[^A-Za-z0-9]+', '', 'g')) = ? ORDER BY v.created_at DESC LIMIT 1",
                            (ncode,),
                        ).fetchone()
                    else:
                        row = cur.execute(
                            base_select + " WHERE UPPER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(p.cerner_mrn,''), ' ', ''), '-', ''), '/', ''), '.', ''), '_', '')) = ? ORDER BY v.created_at DESC LIMIT 1",
                            (ncode,),
                        ).fetchone()
            if not row:
                return jsonify({"ok": True, "found": False, "code": code})
            visit = _row_to_dict(row)
            dob = visit.get("dob")
            try:
                visit["age"] = calc_age(dob) if dob else ""
            except Exception:
                visit["age"] = ""
            ts = visit.get("visit_created_at") or visit.get("created_at")
            visit["visit_date"] = format_date_yyyy_mm_dd(ts)
            visit["registration_time"] = format_time_hhmm(ts)
            visit["registered"] = format_dt_local(ts)
            for k in ("clinic", "doctor", "insurance", "insurance_no", "mrn", "cerner_mrn", "id_number"):
                visit[k] = visit.get(k) or ""
            return jsonify({"ok": True, "found": True, "code": code, "visit": visit})
        except Exception as e:
            return jsonify({"ok": False, "found": False, "code": code, "error": str(e)})
