                            base_select + f" WHERE UPPER(REGEXP_REPLACE(COALESCE(p.cerner_mrn,''), '[^A-Za-z0-9]+', '', 'g')) IN ({ph}) ORDER BY v.created_at DESC LIMIT 1",
