        if tpl and "ROOTFIX_20260602E_SCHED_CERNER" not in tpl:
            tpl = tpl.replace("</style>", "  /* ROOTFIX_20260602E_SCHED_CERNER */\n</style>", 1)
            tpl = tpl.replace("Patient MRN / ID / Name / Phone", "Patient MRN / Cerner MRN / ID / Name / Phone")
            tpl = tpl.replace("placeholder=\"Search before booking\"", "placeholder=\"Search MRN / Cerner MRN / ID / Name / Phone\"")
            tpl = tpl.replace("placeholder=\"MRN / ID / Name / Phone\"", "placeholder=\"MRN / Cerner MRN / ID / Name / Phone\"")
            tpl = tpl.replace("MRN: {{ p.mrn or '-' }} · ID: {{ p.id_number or '-' }}", "MRN: {{ p.mrn or '-' }} · Cerner MRN: {{ p.cerner_mrn or cerner_mrn_for_patient(p.id) or 'N/A' }} · ID: {{ p.id_number or '-' }}")
            tpl = tpl.replace("if(p.mrn) bits.push('MRN ' + p.mrn);", "if(p.mrn) bits.push('MRN ' + p.mrn);\n    if(p.cerner_mrn) bits.push('Cerner ' + p.cerner_mrn);")
            tpl = tpl.replace("' · ID: ' + (p.id_number || '-') + ' · Phone: '", "' · Cerner MRN: ' + (p.cerner_mrn || 'N/A') + ' · ID: ' + (p.id_number || '-') + ' · Phone: '")
