                    db.execute("UPDATE provider_notes SET note_text=?, updated_at=?, updated_by=?, author_username=COALESCE(NULLIF(author_username,''), ?), note_status=COALESCE(NULLIF(note_status,''),'draft'), note_type=COALESCE(NULLIF(note_type,''),'physician') WHERE visit_id=?", (note_text, now, user, user, visit_id))
