    def _rf20260609f_patch_scheduling_template_keep_target():
        tpl = TEMPLATES.get("scheduling_book.html", "") or ""
        changed = False
        # Add a clinic data attribute to resource choices so the browser can preserve the destination clinic too.
        old = '<option value="{{ r.id }}">{{ r.name }}{% if r.gd_number %} · GD# {{ r.gd_number }}{% endif %}</option>'
        new = '<option value="{{ r.id }}" data-clinic="{{ r.clinic|e }}">{{ r.name }}{% if r.gd_number %} · GD# {{ r.gd_number }}{% endif %}</option>'
        if old in tpl and new not in tpl:
            tpl = tpl.replace(old, new, 1)
            changed = True
        if 'name="target_resource_clinic"' not in tpl and 'name="clinic" value="{{ selected_clinic }}"' in tpl:
            tpl = tpl.replace('name="clinic" value="{{ selected_clinic }}"', 'name="clinic" value="{{ selected_clinic }}" id="m-reschedule-clinic-hidden"', 1)
            changed = True
        js_anchor = "if(moveForm) moveForm.action = d.appointmentId ? ('/scheduling/appointments/' + d.appointmentId + '/move') : '#';"
