    for _cb_tpl_name, _cb_tpl_value in list(TEMPLATES.items()):
        if not isinstance(_cb_tpl_value, str):
            continue
        _cb_tpl_value = _cb_tpl_value.replace("ED Downtime Tool", "CareBridge Clinical Continuity System")
